const LIQUID_FLOW_V2_AUTO_REAL_LABELS = new Set([
  'UP_BASE_SWEEP_LONG_READY',
  'DOWN_BASE_SWEEP_SHORT_READY',
  'PRE_UP_BASE_LONG',
  'PRE_DOWN_BASE_SHORT',
  'HTF_BEAR_15M_EMA99_PUMP_REJECT',
  'HTF_BULL_15M_EMA99_DUMP_RECLAIM',
  'EMA_FAN_LONG_READY',
  'EMA_FAN_LONG_IMPULSE_RUNNER',
  'PUMP_FLUSH_RECLAIM_LONG_READY',
  'PRIMARY_EMA99_PANIC_RECLAIM_LONG_READY',
  'POST_PUMP_SHORT_SQUEEZE_LONG_READY',
  'FADING_WAVE_LIVE_PUMP_SHORT_READY',
]);
const COINGLASS_QUALIFIED_BINANCE_LABELS = new Set([
  'COINGLASS_QUALIFIED_LONG',
  'COINGLASS_QUALIFIED_SHORT',
]);
const LIQUID_FLOW_V2_BINANCE_SIGNAL_LABELS = new Set([
  ...LIQUID_FLOW_V2_AUTO_REAL_LABELS,
  ...COINGLASS_QUALIFIED_BINANCE_LABELS,
]);
const LIQUID_FLOW_V2_INDEPENDENT_BINANCE_COHORTS = new Set([
  'HTF_EMA99',
  'PUMP_FLUSH_RECLAIM',
  'PRIMARY_EMA99_PANIC_RECLAIM',
  'POST_PUMP_SQUEEZE_READY',
  'FADING_WAVE_LIVE_PUMP_SHORT',
  'EMA_FAN_RETEST_CONFIRM',
  'EMA_FAN_IMPULSE',
]);

function coinGlassQualifiedStatsLabel(row = {}) {
  return row?.proposal?.action === 'WAIT_LONG_CONFIRMATION'
    ? 'COINGLASS_QUALIFIED_LONG'
    : row?.proposal?.action === 'WAIT_SHORT_CONFIRMATION'
      ? 'COINGLASS_QUALIFIED_SHORT'
      : '';
}

function defaultLiquidFlowV2BinanceSignalSetting(labelKey) {
  const key = String(labelKey ?? '').trim().toUpperCase();
  if (!LIQUID_FLOW_V2_BINANCE_SIGNAL_LABELS.has(key)) {
    return { labelKey: key, supported: false, enabled: false, marginUsdt: null, leverage: null };
  }
  if (COINGLASS_QUALIFIED_BINANCE_LABELS.has(key)) {
    const enabled = process.env.COINGLASS_WEB_BINANCE_ENABLED !== 'false';
    const margin = Number(process.env.COINGLASS_WEB_BINANCE_MARGIN_USDT ?? COINGLASS_WEB_BINANCE_MARGIN_USDT);
    return {
      labelKey: key,
      supported: true,
      enabled,
      marginUsdt: Number.isFinite(margin) && margin > 0 ? margin : COINGLASS_WEB_BINANCE_MARGIN_USDT,
      leverage: COINGLASS_WEB_BINANCE_LEVERAGE,
    };
  }
  const profile = liquidFlowV2AutoBinanceProfile({ labelKey: key }, liquidFlowV2Paper.state.settings);
  const independentlyEnabled = LIQUID_FLOW_V2_INDEPENDENT_BINANCE_COHORTS.has(profile.cohort);
  const enabled = Boolean(profile.eligible) && (
    independentlyEnabled || liquidFlowV2Paper.state.settings.baseBinanceEnabled
  );
  return {
    labelKey: key,
    supported: Boolean(profile.cohort && profile.source),
    enabled,
    marginUsdt: Number(profile.marginUsdt) > 0 ? Number(profile.marginUsdt) : 2,
    leverage: Number(profile.leverage) > 0 ? Number(profile.leverage) : LIQUID_FLOW_V2_BINANCE_LEVERAGE,
    cohort: profile.cohort,
    sourceName: profile.source,
  };
}

async function resolveLiquidFlowV2BinanceSignalSetting(labelKey) {
  await liquidFlowV2BinanceSignalSettings.init();
  const defaults = defaultLiquidFlowV2BinanceSignalSetting(labelKey);
  const override = liquidFlowV2BinanceSignalSettings.override(defaults.labelKey);
  if (!defaults.supported || !override) return { ...defaults, source: 'DEFAULT' };
  return {
    ...defaults,
    enabled: override.enabled,
    marginUsdt: override.marginUsdt,
    source: 'PERSISTED',
    updatedAt: override.updatedAt,
  };
}

async function resolveCoinGlassQualifiedSignalSetting(row = {}) {
  const setting = await resolveLiquidFlowV2BinanceSignalSetting(coinGlassQualifiedStatsLabel(row));
  return {
    binanceEnabled: setting.enabled,
    marginUsdt: setting.marginUsdt,
    leverage: setting.leverage,
  };
}

async function liquidFlowV2BinanceSignalSettingsPayload() {
  await liquidFlowV2BinanceSignalSettings.init();
  const signals = {};
  for (const labelKey of LIQUID_FLOW_V2_BINANCE_SIGNAL_LABELS) {
    signals[labelKey] = await resolveLiquidFlowV2BinanceSignalSetting(labelKey);
  }
  return {
    version: LIQUID_FLOW_V2_BINANCE_SIGNAL_SETTINGS_VERSION,
    signals,
    globalOrderEnabled: runtimeSettings.orderEnabled,
    dryRun: runtimeSettings.dryRun,
  };
}

async function notifyLiquidFlowV2Binance(trade, state, detail, profile) {
  const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
  if (!webhookUrl) return;
  const ok = state === 'FILLED';
  const sideIcon = trade.side === 'LONG' ? '🟢' : '🔴';
  const cohort = profile?.cohort === 'PRE_EMA99'
    ? 'PRE EMA99'
    : profile?.cohort === 'HTF_EMA99'
      ? 'HTF EMA99'
      : String(profile?.cohort ?? '').startsWith('EMA_FAN')
        ? profile?.cohort === 'EMA_FAN_IMPULSE' ? 'EMA FAN IMPULSE' : 'EMA FAN LIMIT FILL'
        : profile?.cohort === 'PUMP_FLUSH_RECLAIM'
          ? 'PUMP FLUSH RECLAIM'
        : profile?.cohort === 'PRIMARY_EMA99_PANIC_RECLAIM'
          ? 'PRIMARY EMA99 PANIC RECLAIM'
        : profile?.cohort === 'POST_PUMP_SQUEEZE_READY'
          ? 'POST PUMP SQUEEZE READY'
        : profile?.cohort === 'FADING_WAVE_LIVE_PUMP_SHORT'
          ? 'FADING WAVE LIVE PUMP SHORT'
        : 'BASE';
  const margin = Number(profile?.marginUsdt ?? trade.binanceMarginUsdt ?? 0);
  const leverage = Number(profile?.leverage ?? trade.binanceLeverage ?? 0);
  const content = ok
    ? `${sideIcon} **[LIQ FLOW V2 ${cohort}] ${trade.symbol} ${trade.side}** MARKET đã fill\n💰 Margin: $${margin} × ${leverage}x\n🧪 ${trade.labelKey}\n${detail}`
    : `⚠️ **[LIQ FLOW V2 ${cohort} ERROR] ${trade.symbol} ${trade.side}**\n🧪 ${trade.labelKey}\n${detail}`;
  try {
    await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ content }),
    });
  } catch {}
}

async function handleLiquidFlowV2BinanceEvents(events = []) {
  for (const event of Array.isArray(events) ? events : []) {
    if (event?.status !== 'OPEN' || !LIQUID_FLOW_V2_AUTO_REAL_LABELS.has(event.labelKey)) continue;
    const baseProfile = liquidFlowV2AutoBinanceProfile({ labelKey: event.labelKey }, liquidFlowV2Paper.state.settings);
    const signalSetting = await resolveLiquidFlowV2BinanceSignalSetting(event.labelKey);
    if (!signalSetting.supported || !signalSetting.enabled) continue;
    const profile = {
      ...baseProfile,
      eligible: true,
      marginUsdt: signalSetting.marginUsdt,
      leverage: signalSetting.leverage,
    };
    if (!runtimeSettings.orderEnabled || runtimeSettings.dryRun) {
      console.warn(`[LiquidFlowV2Real] ${profile.cohort} skip ${event.symbol}: Binance order disabled/dry-run`);
      continue;
    }

    const trade = await liquidFlowV2Paper.claimBinanceEntry(event.id);
    if (!trade) continue;
    try {
      const credentials = getApiCredentials(null);
      const positions = await client.getPositions({
        ...credentials,
        priority: 1,
        dropOnCongestion: false,
        source: 'liquidFlowV2Real:positions',
      });
      const existingPosition = positions.find((row) => (
        normalizeSymbol(row.symbol) === normalizeSymbol(trade.symbol)
        && Number(row.positionAmt) !== 0
      ));
      if (existingPosition) {
        const reason = `BLOCKED_EXISTING_POSITION amt=${existingPosition.positionAmt}`;
        await liquidFlowV2Paper.recordBinanceEntryResult(trade.id, {
          binanceEntryState: 'BLOCKED',
          binanceEntryError: reason,
        });
        await notifyLiquidFlowV2Binance(trade, 'BLOCKED', reason, profile);
        continue;
      }

      const marginUsdt = profile.marginUsdt;
      const leverage = profile.leverage;
      const protection = buildFillAnchoredProtectionSpec({
        side: trade.side,
        signalEntryPrice: trade.entryPrice,
        takeProfitPrice: trade.takeProfit,
        stopLossPrice: trade.stopLoss,
      });
      const clientOrderId = `lfv2_${String(trade.id).replace(/-/g, '')}`.slice(0, 36);
      const result = await placeOrder(authorizeLiquidFlowV2AutoOrder({
        symbol: trade.symbol,
        side: trade.side === 'LONG' ? 'BUY' : 'SELL',
        orderType: 'MARKET',
        notionalUsdt: marginUsdt * leverage,
        allowMinNotionalCeil: profile.cohort === 'PRE_EMA99'
          || profile.cohort === 'FADING_WAVE_LIVE_PUMP_SHORT'
          || String(profile.cohort ?? '').startsWith('EMA_FAN'),
        leverage,
        takeProfitPrice: trade.takeProfit,
        stopLossPrice: trade.stopLoss,
        protectionOnFill: true,
        preserveSignalProtection: true,
        protectionSignalEntryPrice: protection.signalEntryPrice,
        protectionSignalTakeProfitPrice: protection.signalTakeProfitPrice,
        protectionSignalStopLossPrice: protection.signalStopLossPrice,
        fillAnchorEnabled: protection.fillAnchorEnabled,
        fillAnchorVersion: protection.fillAnchorVersion,
        takeProfitDistanceFraction: protection.takeProfitDistanceFraction,
        stopLossDistanceFraction: protection.stopLossDistanceFraction,
        clientOrderId,
        maxOpenPositions: Math.max(0, Number(process.env.LIQ_FLOW_V2_BINANCE_MAX_POSITIONS ?? process.env.LIQ_FLOW_V2_BASE_BINANCE_MAX_POSITIONS ?? 30)),
        dryRun: false,
        source: profile.source,
      }), null, credentials, { positions });
      const orderResult = result?.orderResult ?? {};
      const avgPrice = Number(orderResult.avgPrice ?? 0) || Number(result?.order?.markPrice ?? trade.entryPrice);
      const actualNotionalUsdt = Number(orderResult.executedQty ?? 0) > 0 && avgPrice > 0
        ? Number(orderResult.executedQty) * avgPrice
        : marginUsdt * leverage;
      const actualMarginUsdt = actualNotionalUsdt / leverage;
      await liquidFlowV2Paper.recordBinanceEntryResult(trade.id, {
        binanceEntryState: 'FILLED',
        binanceEntryFilledAt: Date.now(),
        binanceOrderId: orderResult.orderId ?? null,
        binanceClientOrderId: orderResult.clientOrderId ?? clientOrderId,
        binanceOrderStatus: orderResult.status ?? result?.status ?? null,
        binanceEntryPrice: avgPrice,
        binanceMarginUsdt: actualMarginUsdt,
        binanceRequestedMarginUsdt: marginUsdt,
        binanceLeverage: leverage,
        binanceNotionalUsdt: actualNotionalUsdt,
        binanceProtectionVersion: protection.fillAnchorVersion,
      });
      console.log(`[LiquidFlowV2Real] ${profile.cohort} FILLED ${trade.symbol} ${trade.side} margin=$${marginUsdt} ${leverage}x orderId=${orderResult.orderId ?? '-'}`);
      await notifyLiquidFlowV2Binance(
        trade,
        'FILLED',
        `Entry ${avgPrice} · notional thực $${actualNotionalUsdt.toFixed(4)} · TP/SL được neo lại theo fill · orderId ${orderResult.orderId ?? '-'}`,
        profile,
      );
    } catch (error) {
      const reason = String(error?.message ?? error).slice(0, 500);
      await liquidFlowV2Paper.recordBinanceEntryResult(trade.id, {
        binanceEntryState: 'ERROR',
        binanceEntryError: reason,
      }).catch(() => {});
      console.error(`[LiquidFlowV2Real] ${profile.cohort} ERROR ${trade.symbol} ${trade.side}: ${reason}`);
      await notifyLiquidFlowV2Binance(trade, 'ERROR', reason, profile);
    }
  }
}
const analyzeCache = new Map(); // key: `${symbol}|${interval}|${rangePct}|${binSizePct}` → { data, expiresAt }

function decisionTrendFromHealth(health = {}, timeframe = '1h') {
  const tf = timeframe === '4h' ? '4h' : '1h';
  const directionRaw = tf === '4h' ? health.btcTrendDir4h : health.btcTrendDir;
  const scoreRaw = tf === '4h' ? health.btcTrendScore4h : health.btcTrendScore;
  const direction = ['up', 'down'].includes(String(directionRaw).toLowerCase())
    ? String(directionRaw).toUpperCase()
    : 'FLAT';
  const score = Number.isFinite(Number(scoreRaw)) ? Number(scoreRaw) : 0;
  return {
    timeframe: tf,
    direction,
    score,
    strength: score >= 65 ? 'STRONG' : score >= 45 ? 'MID' : 'WEAK',
    price: Number(health.price) || null,
    pct: tf === '4h' ? Number(health.pct24h) || null : Number(health.pct6h) || null,
    rsi: tf === '4h' ? Number(health.rsi4h) || null : Number(health.rsi1h) || null,
    updatedAt: health.updatedAt ?? Date.now(),
  };
}

function intradayEmaDecisionContext(signal = {}) {
  const side = String(signal.side ?? signal.action ?? signal.direction ?? '').toUpperCase();
  const interval = String(signal.timeframe ?? signal.interval ?? signal.factors?.timeframe ?? '15m').toLowerCase();
  const rawStage = String(signal.stage ?? signal.signalType ?? signal.type ?? '').toUpperCase();
  const runnerMeta = buildEmaSqueezeRunnerPaperMeta(signal);
  const stage = runnerMeta.isRunner
    ? 'RUNNER'
    : rawStage.includes('PRE_BREAKDOWN') ? 'PRE_BREAKDOWN'
      : rawStage.includes('PRE_BREAKOUT') ? 'PRE_BREAKOUT'
        : rawStage.includes('SQUEEZE_SHORT') ? 'SQUEEZE_SHORT'
          : rawStage.includes('BREAKDOWN') ? 'BREAKDOWN'
            : rawStage.includes('BREAKOUT') ? 'BREAKOUT'
              : rawStage.includes('SQUEEZE') ? 'SQUEEZE'
                : rawStage;
  const btcSnap = buildBtcHealthSnapshot(btcHealthCache.data ?? {});
  const chartCorr = Number(signal.btcChartRelation?.corr ?? signal.btcCorr);
  const btcCorr = Number.isFinite(chartCorr)
    ? chartCorr
    : getCoinBtcCorr(signal.symbol, interval, 30);
  let rule = null;

  if (!['5m', '15m'].includes(interval)) {
    rule = {
      allow: false,
      tier: 'BLOCK',
      label: 'EMA_TIMEFRAME_NOT_EVALUATED',
      marginUsdt: 0,
      reason: `Decision Paper chỉ dùng EMA 5m/15m; signal hiện tại là ${interval}`,
    };
  } else if (stage === 'RUNNER') {
    rule = getEmaRunnerEvalGate({ side, interval, btcSnap, btcCorr });
  } else if (stage === 'PRE_BREAKOUT' || stage === 'PRE_BREAKDOWN') {
    rule = getEmaPreStageEvalGate({ stage, side, interval, btcSnap, btcCorr });
  } else if (stage === 'BREAKOUT' || stage === 'BREAKDOWN') {
    rule = getEmaBreakStageEvalGate({
      stage,
      side,
      interval,
      signalScore: signal.score,
      btcSnap,
      btcCorr,
    });
  } else if (stage === 'SQUEEZE' && side === 'LONG') {
    rule = getEmaSqueezeLongEvalGate({ interval, btcSnap, btcCorr });
  } else if (stage === 'SQUEEZE_SHORT' && side === 'SHORT') {
    const marginValue = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_MARGIN_USDT ?? 10);
    rule = {
      allow: true,
      tier: 'A',
      label: 'SQUEEZE_SHORT_FULL',
      marginUsdt: Number.isFinite(marginValue) && marginValue > 0 ? marginValue : 10,
      reason: 'Squeeze Short dùng nhánh BR-like paper hiện tại',
    };
  }

  if (stage === 'PRE_BREAKOUT' && process.env.INTRADAY_DECISION_PAUSE_PRE_BREAKOUT !== 'false') {
    rule = {
      ...(rule ?? {}),
      allow: false,
      tier: 'BLOCK',
      label: 'DECISION_PRE_BREAKOUT_PAUSED',
      marginUsdt: 0,
      reason: 'Tạm dừng Pre Breakout trên Decision Paper sau mẫu thực chiến âm; chờ đánh giá lại sau khi sửa exact matcher',
    };
  }
  if (stage === 'SQUEEZE' && side === 'LONG'
      && process.env.INTRADAY_DECISION_PAUSE_SQUEEZE_LONG !== 'false') {
    rule = {
      ...(rule ?? {}),
      allow: false,
      tier: 'BLOCK',
      label: 'DECISION_SQUEEZE_LONG_PAUSED',
      marginUsdt: 0,
      reason: 'Tạm dừng Squeeze Long trên Decision Paper do mẫu thực chiến hiện tại âm',
    };
  }

  const combo = edgePaperComboOfSignal({
    sig: { ...signal, stage },
    side,
    sourcePrefix: 'emasq-decision',
    interval,
    btcHealth: btcSnap,
    btcCorr,
    capGateLabel: rule?.label ?? signal.emaStageGateLabel ?? null,
  });
  return {
    decisionStage: stage,
    decisionRule: rule,
    decisionCombo: combo,
    decisionBtcCorr: Number.isFinite(Number(btcCorr)) ? Number(btcCorr) : null,
    decisionBtcPhase: rule?.btcPhase ?? null,
  };
}

function intradayPumpDecisionContext(signal = {}) {
  const rule = nativePumpEvalGateOfSignal(signal, btcHealthCache.data ?? {});
  return {
    decisionRule: rule,
    decisionStage: normalizePumpComboPart(signal.type ?? signal.signalType ?? 'PUMP', 'PUMP'),
    decisionBtcCorr: Number.isFinite(Number(rule?.btcCorr)) ? Number(rule.btcCorr) : null,
    decisionBtcPhase: rule?.btcPhase ?? null,
  };
}

function intradayDecisionCandidates(timeframe = '1h') {
  // Signal setup 5m/15m expires quickly even when 4h is used as macro context.
  const maxAgeMs = 60 * 60 * 1000;
  const sources = [
    ['pump', 'pump', pumpScanCache, (signal) => pumpSignalComboOf(signal)],
    ['cap', 'cap', capScanCache, null],
    ['killshort', 'paper', killShortScanCache, null],
    ['dump-ignition', 'di', dumpIgnitionScanCache, null],
    ['spike-reversal', 'paper', spikeReversalScanCache, null],
    ['ppks', 'ppks', postPumpKillShortScanCache, (signal) => ppksComboOfSignal(signal)],
    ['pump-ignition', 'pi', pumpIgnitionScanCache, null],
    ['ema-squeeze', 'pump', emaSqueezesScanCache, null],
    ['ema99-kill-reclaim', 'paper', ema99KillReclaimScanCache, null],
    ['shakeout', 'shakeout', shakeoutReclaimScanCache, (signal) => shakeoutSignalComboOf(signal, btcHealthCache.data)],
    ['top-reversal', 'top-reversal', topReversalScanCache, null],
    ['liquid', 'liquid', liquidScanCache, null],
  ];
  const rows = [];
  for (const [source, modelSource, cache, comboBuilder] of sources) {
    const scannedAt = Number(cache?.data?.scannedAt ?? 0);
    if (!scannedAt || Date.now() - scannedAt > maxAgeMs) continue;
    for (const signal of cache?.data?.signals ?? []) {
      const factors = signal.factors ?? signal.pumpSignalFactors ?? {};
      let combo = signal.combo ?? signal.pumpCombo ?? signal.signalCombo ?? null;
      if (!combo && comboBuilder) {
        try { combo = comboBuilder(signal); } catch {}
      }
      const strategyDecisionContext = source === 'ema-squeeze'
        ? intradayEmaDecisionContext(signal)
        : source === 'pump'
          ? intradayPumpDecisionContext(signal)
          : null;
      if (strategyDecisionContext?.decisionCombo) combo = strategyDecisionContext.decisionCombo;
      const observedAt = signal.scannedAt ?? scannedAt;
      const btcCandlePatternAtEntry = signal.btcCandlePatternAtEntry
        ?? signal.btcCandlePattern5m
        ?? cachedCandlePatternAt('BTCUSDT', '5m', observedAt)
        ?? null;
      rows.push({
        ...signal,
        ...(strategyDecisionContext ?? {}),
        source,
        modelSource,
        combo,
        signalType: signal.signalType ?? signal.type ?? signal.stage ?? source,
        side: signal.side ?? signal.action ?? signal.direction,
        timeframe: signal.timeframe ?? signal.interval ?? factors.timeframe ?? '15m',
        score: signal.score ?? signal.signalScore ?? signal.qualityScore ?? 0,
        entry: signal.entry ?? signal.entryPrice ?? signal.markPrice,
        tp: signal.tp ?? signal.takeProfit ?? signal.targets?.[0],
        sl: signal.sl ?? signal.stopLoss,
        btcCandlePatternAtEntry,
        observedAt,
      });
    }
  }
  return rows;
}

function intradayDecisionSignalVersion() {
  return [
    pumpScanCache, capScanCache, killShortScanCache, dumpIgnitionScanCache,
    spikeReversalScanCache, postPumpKillShortScanCache, pumpIgnitionScanCache,
    emaSqueezesScanCache, ema99KillReclaimScanCache, shakeoutReclaimScanCache,
    topReversalScanCache, liquidScanCache,
  ].map((cache) => Number(cache?.data?.scannedAt ?? 0)).join('|');
}

let intradayDecisionPaper = null;

function createIntradayDecisionPaper() {
  const manager = new IntradayDecisionPaper({
    file: join(rootDir, 'data', 'intraday-decision-paper.json'),
    evaluationFile: join(rootDir, 'data', 'intraday-decision-paper-trades.json'),
    getCandidates: (timeframe) => intradayDecisionCandidates(timeframe),
    getTrend: async (timeframe) => {
      const health = await getBtcHealth();
      const primary = decisionTrendFromHealth(health, timeframe);
      return { ...primary, macro4h: decisionTrendFromHealth(health, '4h') };
    },
    getCatalog: async ({ days, minClosed, limit, trend }) => {
      const health = await getBtcHealth().catch(() => btcHealthCache.data ?? {});
      return getIntradayComboPredictions({
        days,
        minClosed,
        limit,
        btcOverride: {
          ...health,
          btcTrendDir: String(trend.direction).toLowerCase(),
          btcTrendScore: trend.score,
          pct6h: trend.pct,
          rsi1h: trend.rsi,
        },
      });
    },
    getMark: (symbol) => sharedLastTicker.getPrice(symbol)
      ?? (_snapshotCache ?? []).find((row) => row.symbol === symbol)?.markPrice
      ?? null,
    getMarkInfo: (symbol) => sharedLastTicker.getPriceInfo(symbol),
    getSignalVersion: () => intradayDecisionSignalVersion(),
    setSymbols: (symbols) => sharedLastTicker.setSymbols('intradayDecisionPaper', symbols),
    enrichTradeForLog: attachCandlePatternToPaperTrade,
    onStateChange: (state, reason) => pushSse(
      intradayDecisionPaperSseClients,
      reason === 'socket-tick' || reason === 'socket-close'
        ? { event: 'paper-tick', reason, trades: state.trades, summary: state.summary }
        : state,
    ),
  });
  sharedLastTicker.register('intradayDecisionPaper', (tick) => manager.handlePriceTick(tick));
  return manager;
}
const ANALYZE_CACHE_TTL_MS = 10_000; // 10s — nến 15m đổi mỗi 15 phút, giá live qua WS

// ── Shared market snapshot cache — tất cả scan dùng chung, tránh spam REST ───
let _snapshotCache = null;
let _snapshotCacheAt = 0;
let _snapshotInflight = null;
const SNAPSHOT_TTL_MS = 60_000; // 60s — giảm getTicker24hr(w=40)+getPremiumIndex(w=10) frequency
const STALE_BOARD_CACHE_MS = Number(process.env.STALE_BOARD_CACHE_MS ?? 15 * 60_000);

function isBinanceRestCongested() {
  return typeof binanceRateGate.isCongested === 'function'
    ? binanceRateGate.isCongested()
    : (binanceRateGate.snapshot?.().queue ?? 0) > 700;
}

let _lastRestCongestionLogAt = 0;
function logRestCongestion(label, reason) {
  const now = Date.now();
  if (now - _lastRestCongestionLogAt < 30_000) return;
  _lastRestCongestionLogAt = now;
  const snap = binanceRateGate.snapshot?.();
  console.warn(`[${label}] Skip ${reason}: Binance REST queue congested (${snap?.queue ?? '?'}).`);
}

function staleScanPayload(cache, reason = 'binance-rest-congested') {
  if (!cache?.data) return null;
  const ageMs = Date.now() - Number(cache.data.scannedAt ?? 0);
  if (!Number.isFinite(ageMs) || ageMs > STALE_BOARD_CACHE_MS) return null;
  return {
    ...cache.data,
    stale: true,
    staleReason: reason,
    gate: binanceRateGate.snapshot?.() ?? null,
  };
}

let _lastRestBlockAlertKey = '';
let _lastRestCongestedAlertAt = 0;
const _sentRestAuthAlertKeys = new Map();

function binanceRestAlertWebhook(kind = '') {
  if (kind === 'auth-blocked') {
    // Auth/IP failures belong with the real-order signal stream so the operator
    // immediately knows that signals cannot become Binance orders.
    return process.env.LIVE_CARD_ORDER_WEBHOOK_URL
      || process.env.ORDER_FILL_WEBHOOK_URL
      || process.env.BINANCE_REST_ALERT_WEBHOOK_URL
      || '';
  }
  // System/REST alerts must never fall through to a strategy channel such as
  // post-pump-kill-short. Configure a dedicated webhook or keep alerts local.
  const alertWebhook = process.env.BINANCE_REST_ALERT_WEBHOOK_URL || '';
  const ppksWebhook = process.env.POST_PUMP_KILL_SHORT_WEBHOOK_URL || '';
  if (alertWebhook && ppksWebhook && alertWebhook === ppksWebhook) return '';
  return alertWebhook;
}

function topQueueText(snap) {
  const rows = Array.isArray(snap?.queueTop) ? snap.queueTop.slice(0, 5) : [];
  if (!rows.length) return '-';
  return rows.map((r) => `${r.key} x${r.count} w${r.weight}`).join('\n');
}

function sendBinanceRestDiscordAlert(kind, snap, extra = {}) {
  const webhookUrl = binanceRestAlertWebhook(kind);
  if (!webhookUrl) return;
  const now = Date.now();
  const blockedUntil = Number(snap?.blockedUntil ?? 0);
  const remainingSec = blockedUntil > now ? Math.ceil((blockedUntil - now) / 1000) : 0;
  const authBlock = extra.authBlock ?? null;
  const title = kind === 'auth-blocked'
    ? '[BINANCE AUTH BLOCKED] IP / API key / permission'
    : kind === 'blocked'
      ? `Binance REST blocked (${snap?.blockReason || 'rate-limit'})`
      : 'Binance REST queue congested';
  const color = kind === 'congested' ? 0xf59e0b : 0xef4444;
  const fields = kind === 'auth-blocked'
    ? [
        { name: 'Scope', value: String(authBlock?.scope ?? 'legacy').slice(0, 1024), inline: true },
        { name: 'Source', value: String(authBlock?.source ?? 'unknown').slice(0, 1024), inline: true },
        { name: 'Request', value: `${authBlock?.method ?? 'GET'} ${authBlock?.path ?? '-'}`.slice(0, 1024), inline: false },
        { name: 'Binance error', value: `-2015: ${String(authBlock?.reason ?? snap?.authBlockReason ?? 'Invalid API-key, IP, or permissions').slice(0, 950)}`, inline: false },
        {
          name: 'Signed REST paused',
          value: Number(authBlock?.blockedUntil) > now
            ? `${Math.ceil((Number(authBlock.blockedUntil) - now) / 1000)}s | probe ${Math.max(0, Math.ceil((Number(authBlock?.nextProbeAt ?? 0) - now) / 1000))}s`
            : '-',
          inline: false,
        },
      ]
    : [
        { name: 'Queue', value: String(snap?.queue ?? 0), inline: true },
        { name: 'Active', value: String(snap?.active ?? 0), inline: true },
        { name: 'Tokens', value: String(snap?.tokens ?? '-'), inline: true },
        kind === 'blocked'
          ? { name: 'Resume ETA', value: remainingSec > 0 ? `${remainingSec}s | ${new Date(blockedUntil).toISOString()}` : '-', inline: false }
          : { name: 'High watermark', value: String(snap?.highWatermark ?? '-'), inline: true },
        { name: 'Top queue', value: `\`\`\`\n${topQueueText(snap).slice(0, 950)}\n\`\`\``, inline: false },
      ].filter(Boolean);

  fetch(webhookUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      embeds: [{
        title,
        description: extra.message ?? (kind === 'auth-blocked'
          ? 'Binance rejected signed REST. Signals may still be detected, but real entry/management cannot reach Binance until the credential/IP circuit recovers.'
          : 'Backend will prefer cache/WS and limit REST until the gate is stable.'),
        color,
        fields,
        timestamp: new Date(now).toISOString(),
      }],
    }),
  })
    .then((res) => {
      if (!res.ok) console.warn(`[BinanceGate] Discord alert failed: ${res.status}`);
      else console.warn(`[BinanceGate] Discord alert sent: ${kind}`);
    })
    .catch((err) => console.warn('[BinanceGate] Discord alert failed:', err.message));
}

function startBinanceRestAlertMonitor() {
  const intervalMs = Math.max(Number(process.env.BINANCE_REST_ALERT_INTERVAL_MS ?? 5000), 2000);
  const congestedCooldownMs = Number(process.env.BINANCE_REST_CONGESTED_ALERT_COOLDOWN_MS ?? 15 * 60_000);
  const tick = () => {
    const snap = binanceRateGate.snapshot?.();
    if (!snap) return;
    const authBlocks = Array.isArray(snap.authBlocks) ? snap.authBlocks : [];
    for (const block of authBlocks) {
      const openedAt = Number(block?.openedAt ?? 0);
      const key = `${block?.scope ?? 'legacy'}|${openedAt || block?.blockedUntil || block?.reason || 'active'}`;
      if (_sentRestAuthAlertKeys.has(key)) continue;
      _sentRestAuthAlertKeys.set(key, Date.now());
      sendBinanceRestDiscordAlert('auth-blocked', snap, { authBlock: block });
    }
    if (_sentRestAuthAlertKeys.size > 500) {
      const cutoff = Date.now() - 7 * 24 * 60 * 60_000;
      for (const [key, sentAt] of _sentRestAuthAlertKeys) {
        if (sentAt < cutoff) _sentRestAuthAlertKeys.delete(key);
      }
    }
    if (snap.blockedUntil > Date.now()) {
      const key = `${snap.blockedUntil}|${snap.blockReason}`;
      if (key !== _lastRestBlockAlertKey) {
        _lastRestBlockAlertKey = key;
        sendBinanceRestDiscordAlert('blocked', snap);
      }
      return;
    }
    if (_lastRestBlockAlertKey && snap.blockedUntil === 0) _lastRestBlockAlertKey = '';
    if (snap.congested && Date.now() - _lastRestCongestedAlertAt >= congestedCooldownMs) {
      _lastRestCongestedAlertAt = Date.now();
      sendBinanceRestDiscordAlert('congested', snap);
    }
  };
  setInterval(tick, intervalMs).unref?.();
  setTimeout(tick, 3000).unref?.();
}

async function getSharedSnapshot() {
  const now = Date.now();
  if (_snapshotCache && now - _snapshotCacheAt < SNAPSHOT_TTL_MS) return _snapshotCache;
  if (_snapshotCache && isBinanceRestCongested()) {
    console.warn(`[MarketSnapshot] REST congested (queue=${binanceRateGate.snapshot?.().queue ?? '?'}); using stale snapshot.`);
    return _snapshotCache;
  }
  if (_snapshotInflight) return _snapshotInflight; // dedupe concurrent calls
  _snapshotInflight = getMarketSnapshot().then((snap) => {
    _snapshotCache   = snap;
    _snapshotCacheAt = Date.now();
    _snapshotInflight = null;
    return snap;
  }).catch((e) => {
    _snapshotInflight = null;
    if (_snapshotCache) {
      console.warn(`[MarketSnapshot] Refresh failed (${e.message}); using stale snapshot.`);
      return _snapshotCache;
    }
    throw e;
  });
  return _snapshotInflight;
}

// ── SSE helpers ───────────────────────────────────────────────────────────────
const pumpSseClients = new Set();
const capSseClients          = new Set();
const killShortSseClients    = new Set();
const dumpIgnitionSseClients = new Set();
const spikeReversalSseClients  = new Set();
const postPumpKillShortSseClients = new Set();
const pumpIgnitionSseClients   = new Set();
const emaSqueezeSseClients     = new Set();
const ema99KillReclaimSseClients = new Set();
const shakeoutReclaimSseClients = new Set();
const shakeoutPaperSseClients = new Set();
const topReversalSseClients = new Set();
const topReversalPaperSseClients = new Set();
const emaSqueezePaperSseClients = new Set();
const liquidPaperSseClients    = new Set();
const intradayDecisionPaperSseClients = new Set();
const liquidFlowV2SseClients = new Set();

function pushSse(clients, data) {
  if (!clients || clients.size === 0) return;
  const payload = `data: ${JSON.stringify(data)}\n\n`;
  for (const res of clients) {
    try { res.write(payload); } catch { clients.delete(res); }
  }
}

const liquidPaperPendingTradeUpdates = new Map();
let liquidPaperBroadcastTimer = null;
let liquidPaperBroadcastInFlight = false;
let liquidPaperBroadcastQueued = false;

function queueLiquidPaperTradeUpdate(trade) {
  if (!trade?.id) return;
  liquidPaperPendingTradeUpdates.set(trade.id, trade);
}

function writeLiquidPaperSse(response, payload) {
  if (!response || response.destroyed || response.writableEnded) {
    liquidPaperSseClients.delete(response);
    return false;
  }
  if (response.liquidPaperBackpressured) return false;
  try {
    const accepted = response.write(payload);
    if (!accepted) {
      response.liquidPaperBackpressured = true;
      response.once('drain', () => {
        response.liquidPaperBackpressured = false;
        scheduleLiquidPaperBroadcast(50);
      });
    }
    return true;
  } catch {
    liquidPaperSseClients.delete(response);
    return false;
  }
}

function pushLiquidPaperSse(data) {
  const payload = `data: ${JSON.stringify(data)}\n\n`;
  let delivered = 0;
  for (const response of liquidPaperSseClients) {
    if (writeLiquidPaperSse(response, payload)) delivered += 1;
  }
  return delivered;
}

async function getLiquidPaperLivePayload({ snapshot = false } = {}) {
  const store = await readLiquidPaperStore();
  const activeStatuses = new Set(['OPEN', 'PENDING', 'ENTRY_READY']);
  const activeTrades = store.trades.filter((trade) => activeStatuses.has(trade.status));
  const marks = [...new Set(activeTrades.map((trade) => trade.symbol).filter(Boolean))]
    .map((symbol) => {
      const live = paperMarkCache.get(symbol);
      const markPrice = Number(live?.markPrice);
      if (!Number.isFinite(markPrice) || markPrice <= 0) return null;
      return {
        symbol,
        markPrice,
        markUpdatedAt: live.at ?? Date.now(),
        markSource: live.source ?? 'ws',
      };
    })
    .filter(Boolean);

  let updateRows;
  if (snapshot) {
    const recentClosedCutoff = Date.now() - 60 * 60_000;
    const recentClosed = store.trades
      .filter((trade) => (
        trade.status === 'CLOSED'
        && Date.parse(trade.closedAt ?? 0) >= recentClosedCutoff
      ))
      .slice(0, 200);
    updateRows = [...activeTrades, ...recentClosed];
  } else {
    updateRows = [...liquidPaperPendingTradeUpdates.values()];
  }

  const trades = updateRows.map((trade) => (
    attachCandlePatternToPaperTrade(enrichPaperTrade(
      trade,
      paperMarkCache.get(trade.symbol)?.markPrice,
    ))
  ));
  return {
    type: snapshot ? 'LIQUID_LIVE_SNAPSHOT' : 'LIQUID_LIVE_PATCH',
    historyUnchanged: true,
    activeIds: snapshot ? activeTrades.map((trade) => trade.id) : undefined,
    trades,
    marks,
    feeRate: getLiquidPaperFeeRate(),
    updatedAt: new Date().toISOString(),
  };
}

async function flushLiquidPaperBroadcast() {
  if (liquidPaperBroadcastInFlight) {
    liquidPaperBroadcastQueued = true;
    return;
  }
  if (liquidPaperSseClients.size === 0) return;
  liquidPaperBroadcastInFlight = true;
  liquidPaperBroadcastQueued = false;
  try {
    const pendingAtStart = new Map(liquidPaperPendingTradeUpdates);
    const payload = await getLiquidPaperLivePayload();
    const delivered = pushLiquidPaperSse(payload);
    if (delivered > 0) {
      for (const [id, trade] of pendingAtStart) {
        if (liquidPaperPendingTradeUpdates.get(id) === trade) {
          liquidPaperPendingTradeUpdates.delete(id);
        }
      }
    }
  } catch (err) {
    pushLiquidPaperSse({
      type: 'LIQUID_LIVE_ERROR',
      error: err.message,
      updatedAt: new Date().toISOString(),
    });
  } finally {
    liquidPaperBroadcastInFlight = false;
    if (liquidPaperBroadcastQueued || liquidPaperPendingTradeUpdates.size > 0) {
      liquidPaperBroadcastQueued = false;
      scheduleLiquidPaperBroadcast(100);
    }
  }
}

function scheduleLiquidPaperBroadcast(delayMs = 700) {
  if (liquidPaperSseClients.size === 0) return;
  if (liquidPaperBroadcastInFlight) {
    liquidPaperBroadcastQueued = true;
    return;
  }
  if (liquidPaperBroadcastTimer) return;
  liquidPaperBroadcastTimer = setTimeout(() => {
    liquidPaperBroadcastTimer = null;
    flushLiquidPaperBroadcast().catch(() => {});
  }, delayMs);
  liquidPaperBroadcastTimer.unref?.();
}

let shakeoutPaperBroadcastTimer = null;
function scheduleShakeoutPaperBroadcast(delayMs = 700) {
  if (shakeoutPaperSseClients.size === 0 || shakeoutPaperBroadcastTimer) return;
  shakeoutPaperBroadcastTimer = setTimeout(() => {
    shakeoutPaperBroadcastTimer = null;
    if (shakeoutPaperSseClients.size === 0) return;
    pushSse(shakeoutPaperSseClients, {
      type: 'SHAKEOUT_PAPER_REFRESH',
      refresh: true,
      updatedAt: new Date().toISOString(),
    });
  }, delayMs);
}

let emaSqueezePaperBroadcastTimer = null;
let emaSqueezePaperBroadcastRunning = false;
function scheduleEmaSqueezePaperBroadcast(delayMs = 700) {
  if (emaSqueezePaperSseClients.size === 0 || emaSqueezePaperBroadcastTimer || emaSqueezePaperBroadcastRunning) return;
  emaSqueezePaperBroadcastTimer = setTimeout(async () => {
    emaSqueezePaperBroadcastTimer = null;
    if (emaSqueezePaperSseClients.size === 0 || emaSqueezePaperBroadcastRunning) return;
    emaSqueezePaperBroadcastRunning = true;
    try {
      const clientsByFilter = new Map();
      for (const client of emaSqueezePaperSseClients) {
        const key = JSON.stringify(client.filter ?? {});
        if (!clientsByFilter.has(key)) clientsByFilter.set(key, []);
        clientsByFilter.get(key).push(client);
      }
      for (const clients of clientsByFilter.values()) {
        const data = await getEmaSqueezePaperTrades({
          deltaOnly: true,
          filter: clients[0]?.filter ?? null,
        });
        const payload = `data: ${JSON.stringify(data)}\n\n`;
        for (const client of clients) {
          try { client.response.write(payload); } catch { emaSqueezePaperSseClients.delete(client); }
        }
      }
    } catch (err) {
      const payload = `data: ${JSON.stringify({ error: err.message, updatedAt: Date.now() })}\n\n`;
      for (const client of emaSqueezePaperSseClients) {
        try { client.response.write(payload); } catch { emaSqueezePaperSseClients.delete(client); }
      }
    } finally {
      emaSqueezePaperBroadcastRunning = false;
    }
  }, delayMs);
}

// ── Debounced scans triggered by 15m candle close ────────────────────────────
let _pumpScanDebounce = null;
async function schedulePumpScan() {
  clearTimeout(_pumpScanDebounce);
  _pumpScanDebounce = setTimeout(async () => {
    if (!strategyScansReady('PumpScan')) return;
    if (isBinanceRestCongested()) {
      const stale = staleScanPayload(pumpScanCache);
      if (stale) pushSse(pumpSseClients, stale);
      binanceRateGate.pruneLowPriorityQueue?.();
      logRestCongestion('PumpScan', 'scan');
      return;
    }
    try {
      const snapshot    = await getSharedSnapshot();
      const snapshotMap = new Map(snapshot.map((r) => [r.symbol, r]));
      const topSymbols  = snapshot
        .sort((a, b) => b.quoteVolume - a.quoteVolume)
        .slice(0, 400)
        .map((r) => r.symbol);
      const { signals, processed } = await runPumpScan(topSymbols, klineCache, snapshotMap);
      const cacheStats = klineCache.stats('15m');
      const result = { signals, scannedAt: Date.now(), total: topSymbols.length, processed, cacheStats };
      pumpScanCache.data = result;
      pumpScanCache.expiresAt = Date.now() + 30_000;
      pushSse(pumpSseClients, result);
      // Auto-order: đặt LIMIT $1 cho signal score≥90 + marketOk
      // Dùng cached open orders — chỉ gọi API 1 lần, tái sử dụng cho toàn bộ signals
      if (runtimeSettings.pumpAutoOrderEnabled && signals.length > 0 && !isVnBlockHour()) {
        try {
          const { apiKey, apiSecret } = getApiCredentials(null);
          const openOrders = await getCachedOpenOrders(apiKey, apiSecret);
          for (const sig of signals) {
            handlePumpAutoOrder(sig, openOrders).catch((e) => console.error('[PumpAuto] unhandled:', e.message));
          }
        } catch (e) {
          console.error('[PumpAuto] getOpenOrders failed:', e.message);
        }
      }

      // Auto-tạo paper trade — chỉ những signal đủ điều kiện real auto-order
      // để paper stats phản ánh đúng hiệu quả thực của hệ thống
      for (const sig of signals) {
        if (sig.score < 75) continue;                              // paper: 75+ (real auto-order cần 80+)
        if ((sig.factors?.chasePct ?? 0) > 0.30) continue;        // chase quá cao
        if (sig.marketOk === false) continue;                      // too far from EMA
        if ((sig.factors?.emaRibbon ?? 1) === 0) continue;        // EMA không bullish
        const pumpEvalGate = nativePumpEvalGateOfSignal(sig, btcHealthCache.data ?? {});
        const key = `${sig.symbol}|${sig.type}`;
        const last = pumpPaperAutoFired.get(key) ?? 0;
        if (Date.now() - last < 4 * 3600 * 1000) continue;
        pumpPaperAutoFired.set(key, Date.now());
        createPumpPaperTrade({
          symbol: sig.symbol,
          side: sig.action,
          marginUsdt: pumpSignalAutoPaperMarginUsdt(sig),
          leverage: 10,
          entryPrice: sig.entry,
          tp: sig.tp ?? null,
          sl: sig.sl ?? null,
          source: `pump-${sig.score}`,
          pumpSignalType: sig.type ?? null,
          pumpSignalGrade: sig.grade ?? null,
          pumpSignalMarketOk: sig.marketOk ?? null,
          pumpSignalFactors: sig.factors ?? null,
          pumpSignalTimeframe: sig.factors?.timeframe ?? sig.interval ?? null,
          pumpCombo: pumpSignalComboOf(sig),
          btcHealth: btcHealthCache.data ?? null,
          btcCorr: pumpEvalGate?.btcCorr ?? null,
          pumpEvalTier: pumpEvalGate?.tier ?? null,
          pumpEvalLabel: pumpEvalGate?.label ?? null,
          pumpEvalReason: pumpEvalGate?.reason ?? null,
          pumpEvalVersion: pumpEvalGate?.version ?? null,
          pumpEvalMarginUsdt: pumpEvalGate?.marginUsdt ?? null,
          pumpEvalHour: pumpEvalGate?.hour ?? null,
          pumpEvalCorrBucket: pumpEvalGate?.corrBucket ?? null,
          pumpEvalBtcPhase: pumpEvalGate?.btcPhase ?? null,
          pumpEvalContextKey: pumpEvalGate?.contextKey ?? null,
          note: [
            sig.note ?? '',
            pumpEvalGate ? `legacyPumpEval=${pumpEvalGate.label} version=${pumpEvalGate.version} diagnosticOnly=Y` : '',
          ]
            .filter(Boolean).join(' | '),
        }).catch(() => {});
        if (pumpPaperTicker) syncPumpPaperTicker().catch(() => {});
      }

      // Edge paper auto-fire: chỉ những pump signal có action SHORT (xuất hiện trên edge-short board)
      for (const sig of signals) {
        const action = String(sig.action ?? '').toUpperCase();
        if (action !== 'SHORT' && action !== 'SELL') continue;  // chỉ short signal trên edge
        const quality = evaluateShortEdgeAutoQuality(sig, 'pump-short', btcHealthCache.data ?? {});
        if (!quality.ok) {
          console.log(`[EdgePaper] ⏭ ${sig.symbol} skip pump-short auto — ${quality.reason}`);
          continue;
        }
        const key = `pump|${sig.symbol}|${sig.type}`;
        const last = edgePaperAutoFired.get(key) ?? 0;
        if (Date.now() - last < 4 * 3600 * 1000) continue;
        edgePaperAutoFired.set(key, Date.now());
        createEdgePaperTrade(edgePaperPayloadFromSignal(sig, {
          side: 'SHORT',
          sourcePrefix: 'pump-short',
        })).catch((e) => console.warn(`[EdgePaper] pump-short ${sig.symbol}:`, e.message));
      }
    } catch (e) {
      console.error('[PumpScan] error:', e.message);
    }
  }, 2_000);
}

const capPaperAutoFired  = new Map(); // `${symbol}|${type}` → firedAt timestamp
const pumpPaperAutoFired = new Map(); // `${symbol}|${type}` → firedAt timestamp
// Edge paper auto-fire: key = `${source}|${symbol}|${type}` để phân biệt cross-scanner
const diPaperAutoFired   = new Map(); // `${symbol}|${type}` -> firedAt timestamp
const piPaperAutoFired   = new Map(); // `${symbol}|${type}` -> firedAt timestamp
const edgePaperAutoFired = new Map();

function edgePaperComboOfSignal({
  sig = {},
  side = 'SHORT',
  sourcePrefix = 'edge',
  interval = '15m',
  btcHealth = null,
  btcCorr = null,
  capGateLabel = null,
} = {}) {
  const stageRaw = String(sourcePrefix).startsWith('emasq')
    ? (sig.stage ?? sig.type ?? 'EMA_SQUEEZE')
    : (sig.type ?? sourcePrefix);
  const stage = normalizePumpComboPart(stageRaw, 'EDGE');
  const sidePart = normalizePumpComboPart(side, 'SIDE');
  const tfPart = normalizePumpComboPart(interval, '-');
  const corr = Number(btcCorr);
  const corrBucket = Number.isFinite(corr)
    ? corr < 0.3 ? 'BTC_CORR_RAC' : corr < 0.5 ? 'BTC_CORR_YEU' : 'BTC_CORR_THEO'
    : 'BTC_CORR_NO_DATA';
  const h = btcHealth ?? {};
  const regimeFallback = String(h.regime ?? sig.btcRegime ?? '').toUpperCase();
  const dir = String(h.btcTrendDir ?? sig.btcTrendDir ?? regimeFallback ?? '').toUpperCase();
  const score = Number(h.btcTrendScore ?? sig.btcTrendScore);
  const trendBucket = dir
    ? `BTC_${dir}_${Number.isFinite(score) ? (score < 45 ? 'WEAK' : score < 65 ? 'MID' : 'STRONG') : 'NO_SCORE'}`
    : 'BTC_NO_DATA';
  const expected = sidePart === 'LONG' ? 'UP' : sidePart === 'SHORT' ? 'DOWN' : '';
  const relation = Number.isFinite(corr) && corr < 0.3
    ? 'DOC_LAP'
    : Number.isFinite(corr) && corr < 0.5
      ? 'THEO_YEU'
      : dir && expected
        ? (dir === expected ? 'THUAN_BTC' : 'NGUOC_BTC')
        : 'REL_NO_DATA';
  const gate = capGateLabel
    ?? sig.emaStageGateLabel
    ?? sig.breakoutMarketRegimeLabel
    ?? sig.runnerSessionTestLabel
    ?? sig.brMarketRegimeLabel
    ?? '-';
  return [stage, sidePart, tfPart, corrBucket, trendBucket, relation, `GATE_${normalizePumpComboPart(gate)}`].join(' | ');
}

function getEdgeShortPaperMarginUsdt() {
  const value = Number(process.env.EDGE_SHORT_PAPER_MARGIN_USDT ?? 10);
  return Number.isFinite(value) && value > 0 ? value : 10;
}

function getEdgeShortPaperSlRoe() {
  const value = Math.abs(Number(process.env.EDGE_SHORT_PAPER_SL_ROE ?? 30));
  return Number.isFinite(value) && value > 0 ? value : 30;
}

function capPaperStopLossFromRoe({ side, entryPrice, leverage }) {
  const stopLossRoe = Math.abs(Number(process.env.CAP_PAPER_STOP_LOSS_ROE ?? 30));
  const entry = Number(entryPrice);
  const lev = Math.max(1, Number(leverage) || 1);
  if (!Number.isFinite(stopLossRoe) || stopLossRoe <= 0 || !Number.isFinite(entry) || entry <= 0) return null;
  const priceMovePct = stopLossRoe / 100 / lev;
  return String(side).toUpperCase() === 'LONG'
    ? entry * (1 - priceMovePct)
    : entry * (1 + priceMovePct);
}

function edgePaperPayloadFromSignal(sig = {}, {
  side = null,
  sourcePrefix = 'edge',
  status = 'OPEN',
  marginUsdt = null,
} = {}) {
  const action = String(side ?? sig.action ?? sig.side ?? 'SHORT').toUpperCase();
  const interval = String(sig.factors?.timeframe ?? sig.interval ?? '15m');
  const btcHealth = sig.btcHealth ?? buildBtcHealthSnapshot(btcHealthCache.data ?? {});
  const btcCorr = Number.isFinite(Number(sig.btcCorr))
    ? Number(sig.btcCorr)
    : getCoinBtcCorr(sig.symbol, interval, 30);
  const capGateLabel = sig.capGateLabel ?? sig.factors?.capGateLabel ?? null;
  const capGateReason = sig.capGateReason ?? sig.factors?.capGateReason ?? null;
  const edgeCombo = edgePaperComboOfSignal({
    sig,
    side: action,
    sourcePrefix,
    interval,
    btcHealth,
    btcCorr,
    capGateLabel,
  });
  const edgePlan = pumpComboTradePlanOfKey(edgeCombo, {}, { context: 'edge' });
  const edgePlanSlRoe = Number(edgePlan.slRoe);
  const defaultSlRoe = getEdgeShortPaperSlRoe();
  return {
    [LIVE_CARD_AUTO_ELIGIBLE]: true,
    symbol: sig.symbol,
    side: action,
    status,
    marginUsdt: marginUsdt ?? edgePlan.marginUsdt ?? getEdgeShortPaperMarginUsdt(),
    leverage: 10,
    entryPrice: sig.entry,
    tp: sig.tp ?? null,
    sl: sig.sl ?? null,
    slRoe: Number.isFinite(edgePlanSlRoe) && edgePlanSlRoe > 0 ? edgePlanSlRoe : defaultSlRoe,
    source: `${sourcePrefix}-${sig.score}`,
    pumpSignalType: sig.type ?? sourcePrefix,
    pumpSignalGrade: sig.grade ?? null,
    pumpSignalMarketOk: sig.marketOk ?? null,
    pumpSignalFactors: sig.factors ?? null,
    pumpSignalTimeframe: interval,
    pumpCombo: edgeCombo,
    btcHealth,
    btcCorr,
    capGateLabel,
    capGateReason,
    sourceSignalAt: sig.sourceSignalAt ?? sig.signalAt ?? sig.scannedAt ?? null,
    candlePatternAtEntry: sig.candlePatternAtEntry
      ?? sig.candlePattern
      ?? sig.candlePattern15m
      ?? sig.candlePattern5m
      ?? null,
    candlePatternTimeframe: sig.candlePatternTimeframe ?? interval,
    btcCandlePatternAtEntry: sig.btcCandlePatternAtEntry
      ?? sig.btcCandleAtEntry
      ?? sig.btcCandlePattern5m
      ?? null,
    note: sig.note ?? '',
  };
}

function ppksComboOfSignal(sig = {}, {
  side = null,
  interval = '15m',
  btcHealth = null,
  btcCorr = null,
  gateLabel = null,
} = {}) {
  return edgePaperComboOfSignal({
    sig: {
      ...sig,
      type: sig.type === 'post_dump_kill_long' ? 'POST_DUMP_KILL_LONG' : 'POST_PUMP_KILL_SHORT',
    },
    side: side ?? sig.action ?? sig.side,
    sourcePrefix: 'ppks',
    interval,
    btcHealth,
    btcCorr,
    capGateLabel: gateLabel ?? sig.ppksGateLabel ?? '-',
  });
}

function ppksTradeFallbackCombo(t = {}) {
  if (t.ppksCombo) return String(t.ppksCombo);
  if (t.pumpCombo) return String(t.pumpCombo);
  const type = String(t.ppksSignalType ?? t.pumpSignalType ?? t.source ?? 'PPKS')
    .replace(/^ppks-auto-\d+$/i, 'PPKS');
  const side = String(t.side ?? '-').toUpperCase();
  const interval = String(t.ppksSignalTimeframe ?? t.pumpSignalTimeframe ?? '15m');
  return ppksComboOfSignal({
    type,
    ppksGateLabel: t.ppksGateLabel ?? t.capGateLabel ?? '-',
    btcHealth: t.btcHealth,
    btcCorr: t.btcCorr,
  }, {
    side,
    interval,
    btcHealth: t.btcHealth,
    btcCorr: t.btcCorr,
    gateLabel: t.ppksGateLabel ?? t.capGateLabel ?? '-',
  });
}

function scoreFromSignal(sig) {
  const direct = Number(sig?.score);
  if (Number.isFinite(direct)) return direct;
  const txt = `${sig?.source ?? ''} ${sig?.note ?? ''}`;
  const m = txt.match(/(?:score=|[-])(\d{2,3})(?:\b|\()/i);
  return m ? Number(m[1]) : null;
}

function chasePctFromSignal(sig) {
  const factorChase = Number(sig?.factors?.chasePct);
  if (Number.isFinite(factorChase)) return factorChase;
  const m = String(sig?.note ?? '').match(/chase=([0-9.]+)%TP/i);
  return m ? Number(m[1]) / 100 : 0;
}

function isPumpEarlyDumpSignal(sig) {
  return String(sig?.note ?? '').startsWith('EARLY_DUMP');
}

function isPumpDumpSignal(sig) {
  return String(sig?.note ?? '').startsWith('DUMP');
}

function isCapBcSignal(sig) {
  return String(sig?.note ?? '').startsWith('BC ');
}

function evaluateShortEdgeAutoQuality(sig, sourceKind, health = {}) {
  const score = scoreFromSignal(sig) ?? 0;
  const chasePct = chasePctFromSignal(sig);

  if (health?.bullBias === 'bullish') {
    return { ok: false, reason: `BTC bull trend ${health.bullBias}` };
  }

  if (sourceKind === 'dump-ignition') {
    return { ok: false, reason: 'dump ignition blocked from Edge Short' };
  }

  if (sourceKind === 'pump-short') {
    if (isPumpEarlyDumpSignal(sig)) {
      const minEarlyDumpScore = Number(process.env.EDGE_SHORT_EARLY_DUMP_MIN_SCORE ?? 65);
      if (score < minEarlyDumpScore) return { ok: false, reason: `EARLY_DUMP score ${score} < ${minEarlyDumpScore}` };
      return { ok: true, reason: 'EARLY_DUMP edge kept' };
    }

    const minDumpScore = Number(process.env.EDGE_SHORT_DUMP_MIN_SCORE ?? 80);
    if (!isPumpDumpSignal(sig)) return { ok: false, reason: 'unknown pump short type' };
    if (score < minDumpScore && chasePct < 0.25) {
      return { ok: false, reason: `DUMP score ${score} < ${minDumpScore} and chase ${(chasePct * 100).toFixed(0)}%TP < 25%` };
    }
    return { ok: true, reason: 'DUMP edge passed' };
  }

  if (sourceKind === 'cap') {
    if (isCapBcSignal(sig)) {
      const minCapBcScore = Number(process.env.EDGE_SHORT_CAP_BC_MIN_SCORE ?? 90);
      if (score < minCapBcScore) return { ok: false, reason: `cap BC score ${score} < ${minCapBcScore}` };
      return { ok: true, reason: 'cap BC high-score only' };
    }

    const minCapScore = Number(process.env.EDGE_SHORT_CAP_MIN_SCORE ?? 85);
    if (score < minCapScore) return { ok: false, reason: `cap score ${score} < ${minCapScore}` };
    return { ok: true, reason: 'cap edge passed' };
  }

  const minGenericScore = Number(process.env.EDGE_SHORT_MIN_SCORE ?? 80);
  if (score < minGenericScore) return { ok: false, reason: `score ${score} < ${minGenericScore}` };
  return { ok: true, reason: 'generic edge passed' };
}

let _capScanDebounce = null;
function normalizeCapGatePart(value, fallback = '-') {
  const text = String(value ?? fallback).trim().toUpperCase();
  return text ? text.replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '') : fallback;
}

function getCapSignalSpecificGate(sig = {}, health = btcHealthCache.data, btcCorr = null) {
  const type = normalizeCapGatePart(sig.type ?? 'CAP');
  const side = String(sig.action ?? sig.side ?? '').toUpperCase();
  const score = Number(sig.score ?? 0);
  const corr = Number(btcCorr);
  const regimeInfo = getEmaSqueezeMarketRegime(health);
  const regime = normalizeCapGatePart(regimeInfo.regime ?? 'CHOP');
  const upRegime = ['UP', 'SIDEWAY_UP', 'WEAK_UP'].includes(regime);
  const downRegime = ['DOWN', 'SIDEWAY_DOWN', 'WEAK_DOWN'].includes(regime);
  const aligned = (side === 'LONG' && upRegime) || (side === 'SHORT' && downRegime);
  const counter = (side === 'LONG' && downRegime) || (side === 'SHORT' && upRegime);
  const independent = Number.isFinite(corr) && corr < 0.3;
  const highScore = Number.isFinite(score) && score >= 85;
  const blockLong = Boolean(sig.blockLong);
  const blockShort = Boolean(sig.blockShort);
  const protection = blockLong && blockShort
    ? 'PROTECT_LONG_SHORT'
    : blockLong
      ? 'PROTECT_LONG'
      : blockShort
        ? 'PROTECT_SHORT'
        : 'NO_PROTECT';

  let posture = 'NEUTRAL_TEST';
  let prefix = 'OK';
  if (regime === 'CHOP') {
    posture = 'CHOP_TEST';
  } else if (aligned) {
    posture = `${regime}_ALIGNED`;
  } else if (counter) {
    posture = `${regime}_${independent || highScore ? 'COUNTER_TEST' : 'COUNTER_BLOCK_TEST'}`;
    if (!independent && !highScore) prefix = 'BLOCK';
  } else {
    posture = `${regime}_NEUTRAL_TEST`;
  }

  return {
    label: `${prefix}_CAP_${type}_${posture}_${protection}`,
    regime,
    reason: `${regimeInfo.reason}; cap ${type} ${side} aligned=${aligned} counter=${counter} independent=${independent} highScore=${highScore} corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'}`,
  };
}

function attachBtcContextToCapSignals(signals = [], health = btcHealthCache.data) {
  const btcSnap = health ? buildBtcHealthSnapshot(health) : null;
  return (Array.isArray(signals) ? signals : []).map((sig) => {
    const interval = String(sig?.factors?.timeframe ?? sig?.interval ?? '15m');
    const btcCorr = getCoinBtcCorr(sig.symbol, interval, 30);
    const capGate = getCapSignalSpecificGate(sig, health, btcCorr);
    const capGateLabel = capGate.label;
    return {
      ...sig,
      interval,
      factors: { ...(sig.factors ?? {}), timeframe: interval, capGateLabel, capGateReason: capGate.reason, btcRegime: capGate.regime, blockLong: Boolean(sig.blockLong), blockShort: Boolean(sig.blockShort), marketOk: sig.marketOk ?? null },
      capGateLabel,
      capGateReason: capGate.reason,
      btcHealth: btcSnap,
      btcTrendDir: btcSnap?.btcTrendDir ?? null,
      btcTrendScore: btcSnap?.btcTrendScore ?? null,
      btcCorr,
    };
  });
}

async function scheduleCapScan() {
  clearTimeout(_capScanDebounce);
  _capScanDebounce = setTimeout(async () => {
    if (!strategyScansReady('CapScan')) return;
    try {
      const snapshot    = await getSharedSnapshot();
      const snapshotMap = new Map(snapshot.map((r) => [r.symbol, r]));
      const topSymbols  = snapshot
        .sort((a, b) => b.quoteVolume - a.quoteVolume)
        .slice(0, 400)
        .map((r) => r.symbol);
      const { signals: rawSignals, processed } = await runCapScan(topSymbols, klineCache, snapshotMap);
      const btcHealth = await getBtcHealth().catch(() => btcHealthCache.data);
      const signals = attachBtcContextToCapSignals(rawSignals, btcHealth);
      const cacheStats = klineCache.stats('15m');
      const result = { signals, scannedAt: Date.now(), total: topSymbols.length, processed, cacheStats };
      capScanCache.data = result;
      capScanCache.expiresAt = Date.now() + 30_000;
      pushSse(capSseClients, result);
      if (signals.length > 0)
        console.log(`[CapScan] ${signals.length} signal(s): ${signals.map(s => `${s.symbol}(${s.type} ${s.score})`).join(', ')}`);

      // Auto-tạo paper trade cho mỗi signal mới (dedup 4h theo symbol+type)
      for (const sig of signals) {
        const key = `${sig.symbol}|${sig.type}`;
        const last = capPaperAutoFired.get(key) ?? 0;
        if (Date.now() - last < 4 * 3600 * 1000) { console.log(`[CapPaper] skip ${key} — cooldown ${Math.round((Date.now()-last)/60000)}m ago`); continue; }
        capPaperAutoFired.set(key, Date.now());
        createCapPaperTrade({
          symbol: sig.symbol,
          side: sig.action,
          marginUsdt: 10,
          leverage: 10,
          entryPrice: sig.entry,
          tp: sig.tp ?? null,
          sl: sig.sl ?? null,
          source: `cap-${sig.score}`,
          pumpSignalType: sig.type ?? null,
          pumpSignalGrade: sig.grade ?? null,
          pumpSignalMarketOk: sig.marketOk ?? null,
          pumpSignalFactors: sig.factors ?? null,
          pumpSignalTimeframe: sig.factors?.timeframe ?? sig.interval ?? null,
          pumpCombo: pumpSignalComboOf(sig),
          btcHealth: sig.btcHealth ?? null,
          btcCorr: sig.btcCorr,
          capGateLabel: sig.capGateLabel ?? null,
          capGateReason: sig.capGateReason ?? null,
          note: sig.note ?? '',
        }).then(() => syncCapPaperTicker()).catch((e) => console.warn(`[CapPaper] auto create ${sig.symbol}:`, e.message));
      }

      // Edge paper auto-fire: cap signals cũng xuất hiện trên edge-short board
      for (const sig of signals) {
        const action = String(sig.action ?? 'LONG').toUpperCase();
        if (action !== 'SHORT' && sig.score < 60) continue;
        if (action === 'SHORT') {
          const quality = evaluateShortEdgeAutoQuality(sig, 'cap', btcHealthCache.data ?? {});
          if (!quality.ok) {
            console.log(`[EdgePaper] ⏭ ${sig.symbol} skip cap short auto — ${quality.reason}`);
            continue;
          }
        }
        const key = `cap|${sig.symbol}|${sig.type}`;
        const last = edgePaperAutoFired.get(key) ?? 0;
        if (Date.now() - last < 4 * 3600 * 1000) continue;
        edgePaperAutoFired.set(key, Date.now());
        createEdgePaperTrade(edgePaperPayloadFromSignal(sig, {
          side: action,
          sourcePrefix: 'cap',
        })).catch((e) => console.warn(`[EdgePaper] cap ${sig.symbol}:`, e.message));
      }
    } catch (e) {
      console.error('[CapScan] error:', e.message);
    }
  }, 2_000);
}

let _killShortScanDebounce = null;
async function scheduleKillShortScan() {
  clearTimeout(_killShortScanDebounce);
  _killShortScanDebounce = setTimeout(async () => {
    if (!strategyScansReady('KillShortScan')) return;
    try {
      const snapshot    = await getSharedSnapshot();
      const snapshotMap = new Map(snapshot.map((r) => [r.symbol, r]));
      const topSymbols  = snapshot
        .sort((a, b) => b.quoteVolume - a.quoteVolume)
        .slice(0, 400)
        .map((r) => r.symbol);
      const { signals, processed } = await runKillShortScan(topSymbols, klineCache, snapshotMap);
      const cacheStats = klineCache.stats('15m');
      const result = { signals, scannedAt: Date.now(), total: topSymbols.length, processed, cacheStats };
      killShortScanCache.data = result;
      killShortScanCache.expiresAt = Date.now() + 30_000;
      pushSse(killShortSseClients, result);
      if (signals.length > 0)
        console.log(`[KillShortScan] ${signals.length} signal(s): ${signals.map(s => `${s.symbol}(${s.type} ${s.score})`).join(', ')}`);

      // Edge paper auto-fire: killshort signals chỉ xuất hiện trên edge-short
      for (const sig of signals) {
        if (sig.score < 60) continue;
        const key = `killshort|${sig.symbol}|${sig.type}`;
        const last = edgePaperAutoFired.get(key) ?? 0;
        if (Date.now() - last < 4 * 3600 * 1000) continue;
        edgePaperAutoFired.set(key, Date.now());
        createEdgePaperTrade(edgePaperPayloadFromSignal(sig, {
          side: String(sig.action ?? 'LONG').toUpperCase(),
          sourcePrefix: 'killshort',
        })).catch((e) => console.warn(`[EdgePaper] killshort ${sig.symbol}:`, e.message));
      }
    } catch (e) {
      console.error('[KillShortScan] error:', e.message);
    }
  }, 2_000);
}

let _dumpIgnitionScanDebounce = null;

function parseIgnitionNote(note) {
  const kv = {};
  for (const part of String(note ?? '').split('|')) {
    const idx = part.indexOf('=');
    if (idx < 0) continue;
    kv[part.slice(0, idx).trim()] = part.slice(idx + 1).trim();
  }
  return kv;
}

function numberFromNoteValue(value) {
  if (value == null) return null;
  const m = String(value).match(/-?\d+(?:\.\d+)?/);
  return m ? Number(m[0]) : null;
}

function evaluateDumpIgnitionAutoQuality(sig, health = {}) {
  if (sig.type === 'post_pump_dump_risk') return { ok: false, reason: 'post-pump risk is watch-only' };
  if (sig.type === 'post_dump_bounce_risk') return { ok: false, reason: 'post-dump bounce is handled by real-order module' };
  const minScore = Number(process.env.DUMP_IGNITION_AUTO_MIN_SCORE ?? 90);
  if (sig.score < minScore) return { ok: false, reason: `score ${sig.score} < ${minScore}` };

  if (health?.bullBias === 'bullish') {
    return { ok: false, reason: `BTC bull trend ${health.bullBias}` };
  }
  if (health?.bias !== 'bearish') {
    return { ok: false, reason: `BTC bias ${health?.bias ?? 'unknown'} is not bearish` };
  }

  const noteKV = parseIgnitionNote(sig.note);
  const isEarly = sig.type === 'dump_ignition_early';
  const liveEMA = noteKV.liveEMA;
  const bias = noteKV.bias;
  const volX = numberFromNoteValue(noteKV.volX);
  const ema50Slope = numberFromNoteValue(noteKV.ema50Slope);

  if (isEarly) {
    if (liveEMA !== 'Y') return { ok: false, reason: 'EARLY liveEMA=N' };
    if (bias !== 'full') return { ok: false, reason: `EARLY bias=${bias || 'unknown'}` };
  } else if (ema50Slope != null && ema50Slope > -0.05) {
    return { ok: false, reason: `ema50Slope ${ema50Slope.toFixed(3)}%/bar not bearish enough` };
  }

  if (volX != null && volX >= 1.5 && volX < 10) {
    return { ok: false, reason: `volX ${volX.toFixed(2)} in weak 1.5-10x zone` };
  }

  return { ok: true, reason: 'quality gate passed' };
}

function applyPostPumpDumpRiskTslExcludes(signals) {
  for (const sig of signals ?? []) {
    if (sig?.type !== 'post_pump_dump_risk' || !sig.symbol) continue;
    const symbol = String(sig.symbol).toUpperCase();
    if (tslExcludedSymbols.has(symbol)) continue;
    tslExcludedSymbols.add(symbol);
    console.log(`[TSL-Exclude] ⛔ ${symbol} excluded by Post-pump Dump Risk signal`);
  }
}

function applyPostDumpBounceRiskTslExcludes(signals) {
  for (const sig of signals ?? []) {
    if (sig?.type !== 'post_dump_bounce_risk' || !sig.symbol) continue;
    const symbol = String(sig.symbol).toUpperCase();
    if (tslExcludedSymbols.has(symbol)) continue;
    tslExcludedSymbols.add(symbol);
    console.log(`[TSL-Exclude] ⛔ ${symbol} excluded by Post-dump Bounce Risk signal`);
  }
}

function calcAutoLeverage(entry, sl, defaultLev = 10) {
  const e = Number(entry);
  const s = Number(sl);
  if (!e || !s || !Number.isFinite(e) || !Number.isFinite(s)) return defaultLev;
  const slDistPct = Math.abs(e - s) / e;
  return slDistPct * 10 * 100 > 20 ? 5 : 10;
}

async function handlePostPumpDumpRiskRealOrder(sig) {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (sig?.type !== 'post_pump_dump_risk') return;
  if (process.env.POST_PUMP_DUMP_RISK_AUTO_ORDER_ENABLED !== 'true') return;
  if (sig.action !== 'SHORT') return;

  applyPostPumpDumpRiskTslExcludes([sig]);

  const minScore = Number(process.env.POST_PUMP_DUMP_RISK_AUTO_MIN_SCORE ?? 62);
  if (sig.score < minScore) return;
  if (!sig.entry || !sig.sl) return;

  const cooldownMs = Number(process.env.POST_PUMP_DUMP_RISK_AUTO_COOLDOWN_MS ?? 4 * 3600 * 1000);
  const dedupKey = `${sig.symbol}|${sig.type}`;
  const last = postPumpDumpRiskOrderFired.get(dedupKey) ?? 0;
  if (Date.now() - last < cooldownMs) {
    console.log(`[PostPumpDumpRiskOrder] skip ${sig.symbol} - cooldown`);
    return;
  }

  if (!runtimeSettings.orderEnabled || runtimeSettings.dryRun) {
    console.log(`[PostPumpDumpRiskOrder] skip ${sig.symbol} - real Binance order disabled/dry-run`);
    return;
  }

  let apiKey;
  let apiSecret;
  try {
    ({ apiKey, apiSecret } = getApiCredentials(null));
  } catch (err) {
    apiKey = process.env.BINANCE_API_KEY;
    apiSecret = process.env.BINANCE_API_SECRET;
    if (!apiKey || !apiSecret) throw err;
  }

  const [positions, openOrders] = await Promise.all([
    client.getPositions({ apiKey, apiSecret }),
    getCachedOpenOrders(apiKey, apiSecret),
  ]);
  const hasPosition = positions.some((p) => p.symbol === sig.symbol && Math.abs(Number(p.positionAmt ?? 0)) > 0);
  if (hasPosition) {
    console.log(`[PostPumpDumpRiskOrder] skip ${sig.symbol} - already has position`);
    return;
  }
  const hasEntryOrder = openOrders.some((o) => {
    if (o.symbol !== sig.symbol) return false;
    if (String(o.reduceOnly ?? '').toLowerCase() === 'true') return false;
    const type = String(o.type ?? o.origType ?? '').toUpperCase();
    return ['MARKET', 'LIMIT', 'LIMIT_MAKER'].includes(type);
  });
  if (hasEntryOrder) {
    console.log(`[PostPumpDumpRiskOrder] skip ${sig.symbol} - already has entry order`);
    return;
  }

  const marginUsdt = Number(process.env.POST_PUMP_DUMP_RISK_AUTO_MARGIN_USDT ?? 1);
  const defaultLeverage = Number(process.env.POST_PUMP_DUMP_RISK_AUTO_LEVERAGE ?? 10);
  const leverage = calcAutoLeverage(sig.entry, sig.sl, defaultLeverage);
  const notionalUsdt = marginUsdt * leverage;
  const orderType = String(process.env.POST_PUMP_DUMP_RISK_AUTO_ORDER_TYPE ?? 'MARKET').toUpperCase();
  const maxOpenPositions = Number(process.env.POST_PUMP_DUMP_RISK_AUTO_MAX_POSITIONS ?? process.env.AUTO_TRADE_MAX_POSITIONS ?? 0);
  const result = await placeOrder({
    symbol: sig.symbol,
    side: 'SELL',
    orderType,
    notionalUsdt,
    leverage,
    limitPrice: orderType === 'MARKET' ? undefined : sig.entry,
    takeProfitPrice: sig.tp ?? undefined,
    stopLossPrice: sig.sl ?? undefined,
    maxOpenPositions,
    dryRun: false,
  }, null, { apiKey, apiSecret });

  postPumpDumpRiskOrderFired.set(dedupKey, Date.now());
  invalidateOpenOrdersCache();

  const orderId = result?.orderResult?.orderId ?? '-';
  const avgPrice = result?.orderResult?.avgPrice ?? result?.order?.markPrice ?? sig.entry;
  console.log(`[PostPumpDumpRiskOrder] REAL ${sig.symbol} SHORT ${orderType} orderId=${orderId} score=${sig.score}`);

  const webhookUrl = process.env.DUMP_IGNITION_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL || '';
  if (webhookUrl) {
    const fmt = (v) => v == null || !Number.isFinite(Number(v)) ? '-' : Number(v).toPrecision(8).replace(/\.?0+$/, '');
    const msg = [
      `**[REAL ORDER] Post-pump Dump Risk ${sig.symbol} SHORT - ${orderType} - Score ${sig.score} (${sig.grade ?? '-'})**`,
      `OrderId: \`${orderId}\` | Avg/Mark: \`${fmt(avgPrice)}\``,
      `Margin: $${marginUsdt} x ${leverage}x | Notional: $${notionalUsdt}`,
      `Entry signal: \`${fmt(sig.entry)}\` | SL: \`${fmt(sig.sl)}\` | TP: \`${fmt(sig.tp)}\``,
      `Skip TSL: true`,
    ].join('\n');
    fetch(webhookUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ content: msg }),
    }).catch(() => {});
  }
}

function sendPostPumpDumpRiskDiscord(sig) {
  if (sig?.type !== 'post_pump_dump_risk') return;
  const webhookUrl = process.env.POST_PUMP_DUMP_RISK_WEBHOOK_URL || '';
  if (!webhookUrl) return;

  const minScore = Number(process.env.POST_PUMP_DUMP_RISK_MIN_DISCORD_SCORE ?? 0);
  if (sig.score < minScore) return;

  const dedupMs = Number(process.env.POST_PUMP_DUMP_RISK_DISCORD_COOLDOWN_MS ?? 4 * 3600 * 1000);
  const dedupKey = `${sig.symbol}|post_pump_dump_risk`;
  const lastFired = dumpIgnDiscordFired.get(dedupKey) ?? 0;
  if (Date.now() - lastFired < dedupMs) return;
  dumpIgnDiscordFired.set(dedupKey, Date.now());

  const fmt = (v) => {
    if (v == null || !Number.isFinite(Number(v))) return '-';
    const n = Number(v);
    if (Math.abs(n) >= 1000) return n.toLocaleString('en', { maximumFractionDigits: 2 });
    if (Math.abs(n) >= 1) return n.toFixed(4);
    return n.toFixed(6);
  };
  const noteKV = Object.fromEntries((sig.note ?? '')
    .split('|')
    .map((s) => s.trim().split('='))
    .filter((a) => a.length === 2)
    .map(([k, v]) => [k.trim(), v.trim()]));
  const fields = [
    { name: 'Entry / SL / TP', value: `\`${fmt(sig.entry)}\` / \`${fmt(sig.sl)}\` / \`${fmt(sig.tp)}\``, inline: false },
    { name: 'Runup', value: noteKV.runup ? `${noteKV.runup}%` : '-', inline: true },
    { name: 'Red volume', value: noteKV.redVolShare ? `${noteKV.redVolShare}%` : '-', inline: true },
    { name: 'Vol recent', value: noteKV.volRecent ? `${noteKV.volRecent}x` : '-', inline: true },
    { name: 'RSI fade', value: noteKV.rsiFade ?? '-', inline: true },
    { name: 'Support break', value: noteKV.supportBreak ? `${noteKV.supportBreak}%` : '-', inline: true },
    { name: 'Mark', value: fmt(sig.markPrice), inline: true },
  ];

  fetch(webhookUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      content: `🔴 **[POST_PUMP_DUMP_RISK] ${sig.symbol} SHORT** · Score ${sig.score} (${sig.grade ?? '-'})`,
      embeds: [{
        title: `[POST_PUMP_DUMP_RISK] ${sig.symbol} · SHORT`,
        description: sig.reason ?? 'Post-pump distribution risk',
        color: 0xEF4444,
        fields,
        footer: { text: 'Dump Ignition Board' },
        timestamp: new Date().toISOString(),
      }],
    }),
  }).catch((err) => console.warn(`[PostPumpDumpRisk] Discord ${sig.symbol}:`, err.message));

  console.log(`[PostPumpDumpRisk] 📨 Discord: ${sig.symbol} score=${sig.score}`);
}

