      const snapshotMap = new Map(snapshot.map((r) => [r.symbol, r]));
      const topSymbols = snapshot
        .sort((a, b) => Number(b.quoteVolume ?? 0) - Number(a.quoteVolume ?? 0))
        .slice(0, Number(process.env.EMA99_KILL_RECLAIM_MAX_SYMBOLS ?? 400))
        .map((r) => r.symbol);
