function getCachedEmaSqueezeLiquidityPlan(sig) {
  const symbol = String(sig?.symbol ?? '').toUpperCase();
  const interval = String(sig?.interval ?? '15m');
  if (!symbol) return null;

  const ttlMs = Math.max(10_000, Number(process.env.EMA_SQUEEZE_LIQUIDITY_ENTRY_CACHE_MS ?? 60_000));
  const key = `${symbol}|${interval}`;
  const cached = emaSqueezeLiquidityEntryCache.get(key);
  if (cached && Date.now() - cached.at < ttlMs) return cached.data;

  const limit = Math.max(80, Math.min(500, Number(process.env.EMA_SQUEEZE_LIQUIDITY_KLINE_LIMIT ?? 240)));
  const klines = klineCache.getIfCached(symbol, interval, limit);
  if (!klines || klines.length < 60) return null;

  const markPrice = Number(sig.markPrice ?? sig.currentPrice ?? klines.at(-1)?.close ?? sig.entry);
  if (!Number.isFinite(markPrice) || markPrice <= 0) return null;
  const side = String(sig?.action ?? '').toUpperCase();

  const heatmap = computeHeatmapData({
    klines,
    currentPrice: markPrice,
    momentumPct: sig.change24h ?? sig.change24hPct ?? null,
    preferredDirection: side === 'SHORT' ? 'short' : 'long',
  });
  const above = Number(heatmap.liquidityAbove ?? 0);
  const below = Number(heatmap.liquidityBelow ?? 0);
  const bias = Number(heatmap.bias ?? 0);
  const heavySide = bias >= 0 ? 'above' : 'below';
  const target = heatmap.sweepTarget ?? (
    heavySide === 'above'
      ? (heatmap.heatmapAbove?.[0] ?? null)
      : (heatmap.heatmapBelow?.[0] ?? null)
  );
  const sweepProb = liquidSweepProb(heatmap, target);
  const entryPlan = buildLiquidEntryPlan({
    heavySide,
    markPrice,
    target,
    heatmap,
    killZoneCluster: heatmap.killZoneCluster ?? null,
  });

  const data = {
    markPrice,
    heatmap,
    above,
    below,
    total: above + below,
    bias,
    heavySide,
    target,
    sweepProb,
    entryPlan,
  };
  emaSqueezeLiquidityEntryCache.set(key, { at: Date.now(), data });
  return data;
}

async function refineEmaSqueezePaperSignal(sig, { allowFallback = false } = {}) {
  const stage = String(sig?.stage ?? '').toUpperCase();
  const side = String(sig?.action ?? '').toUpperCase();
  if (!['BREAKOUT', 'BREAKDOWN', 'SQUEEZE', 'SQUEEZE_SHORT'].includes(stage)) return sig;
  if (!['LONG', 'SHORT'].includes(side)) return sig;
  if (process.env.EMA_SQUEEZE_LIQUIDITY_ENTRY_ENABLED === 'false') return sig;

  const isSetupStage = stage === 'SQUEEZE' || stage === 'SQUEEZE_SHORT';
  const requireLiquidity = !allowFallback && (isSetupStage
    ? process.env.EMA_SQUEEZE_SQUEEZE_REQUIRES_LIQUIDITY !== 'false'
    : process.env.EMA_SQUEEZE_CONFIRMED_REQUIRES_LIQUIDITY === 'true');
  const planData = getCachedEmaSqueezeLiquidityPlan(sig);
  if (!planData) return requireLiquidity ? null : sig;

  const minBias = Number(process.env.EMA_SQUEEZE_LIQUIDITY_MIN_BIAS ?? 0.05);
  const minSweepProb = Number(process.env.EMA_SQUEEZE_LIQUIDITY_MIN_SWEEP_PROB ?? 35);
  const plan = planData.entryPlan ?? {};
  const entry = Number(plan.entryPrice);
  const tp = Number(plan.takeProfitPrice);
  const sl = Number(plan.stopLossPrice);
  const originalEntry = Number(sig.entry);
  const originalTp = Number(sig.tp);
  const originalSl = Number(sig.sl);
  const expectedHeavySide = side === 'LONG' ? 'above' : 'below';
  const sideBiasOk = side === 'LONG'
    ? planData.bias >= minBias
    : planData.bias <= -minBias;
  const hasDirectionalLiquidity = planData.heavySide === expectedHeavySide
    && plan.side === side
    && sideBiasOk
    && planData.sweepProb >= minSweepProb;

  if (!hasDirectionalLiquidity) return requireLiquidity ? null : sig;
  if (![entry, tp, sl].every((v) => Number.isFinite(v) && v > 0)) return requireLiquidity ? null : sig;
  if (side === 'LONG' ? (sl >= entry || tp <= entry) : (sl <= entry || tp >= entry)) return requireLiquidity ? null : sig;

  const maxPullbackPct = Math.max(0.1, Number(process.env.EMA_SQUEEZE_LIQUIDITY_MAX_PULLBACK_PCT ?? 1.2));
  const pullbackPct = originalEntry > 0 ? Math.abs((entry - originalEntry) / originalEntry) * 100 : 0;
  if (pullbackPct > maxPullbackPct) return requireLiquidity ? null : sig;

  const refinedEntry = side === 'LONG'
    ? Math.min(originalEntry, entry)
    : Math.max(originalEntry, entry);
  const refinedTp = side === 'LONG'
    ? (Number.isFinite(tp) && tp > refinedEntry
        ? tp
        : (Number.isFinite(originalTp) && originalTp > refinedEntry ? originalTp : null))
    : (Number.isFinite(tp) && tp < refinedEntry
        ? tp
        : (Number.isFinite(originalTp) && originalTp < refinedEntry ? originalTp : null));
  const refinedSl = side === 'LONG'
    ? (Number.isFinite(sl) && sl < refinedEntry
        ? sl
        : (Number.isFinite(originalSl) && originalSl < refinedEntry ? originalSl : null))
    : (Number.isFinite(sl) && sl > refinedEntry
        ? sl
        : (Number.isFinite(originalSl) && originalSl > refinedEntry ? originalSl : null));
  if (!refinedTp || !refinedSl || (side === 'LONG' ? (refinedSl >= refinedEntry || refinedTp <= refinedEntry) : (refinedSl <= refinedEntry || refinedTp >= refinedEntry))) {
    return requireLiquidity ? null : sig;
  }

  const target = planData.target;
  const liqNote = [
    'liqEntry=Y',
    `bias=${planData.bias.toFixed(2)}`,
    `sweep=${planData.sweepProb}`,
    `entryPullback=${pullbackPct.toFixed(2)}%`,
    target?.price ? `liqTarget=${Number(target.price).toFixed(6)}` : '',
    plan.killZoneTakeProfitPrice ? `killZoneTP=${Number(plan.killZoneTakeProfitPrice).toFixed(6)}` : '',
  ].filter(Boolean).join(' | ');

  return {
    ...sig,
    entry: refinedEntry,
    tp: refinedTp,
    sl: refinedSl,
    liquidPlanEntry: entry,
    liquidPlanTp: tp,
    liquidPlanSl: sl,
    paperStatus: 'PENDING',
    note: [sig.note ?? sig.reason ?? '', liqNote, plan.note ?? ''].filter(Boolean).join(' | '),
    entryPlan: {
      ...plan,
      markPrice: planData.markPrice,
      signalMarkPrice: Number(sig.markPrice ?? planData.markPrice),
      liquidityBias: planData.bias,
      sweepProb: planData.sweepProb,
    },
    heavySide: planData.heavySide,
    sweepTargetPrice: target?.price ?? null,
    sweepDistancePct: target?.distancePct ?? null,
    rewardPct: plan.rewardPct ?? null,
    riskPct: plan.riskPct ?? null,
    rr: plan.rr ?? null,
    feasibleLeverage: plan.feasibleLeverage ?? null,
    feasibilityScore: plan.feasibilityScore ?? null,
    liquidityEntry: {
      bias: planData.bias,
      sweepProb: planData.sweepProb,
      originalEntry,
      planEntry: entry,
      planTp: tp,
      planSl: sl,
      entry: refinedEntry,
      tp: refinedTp,
      sl: refinedSl,
      targetPrice: target?.price ?? null,
      targetDistancePct: target?.distancePct ?? null,
    },
  };
}

function signalFromEmaSqueezePaperPayload(payload = {}) {
  const source = String(payload.source ?? '');
  if (!source.startsWith('emasq-')) return null;
  const match = source.match(/^emasq-(?:(5m|15m|1h)-)?([a-z_]+)-(\d+)$/i)
    ?? source.match(/^emasq-(?:(5m|15m|1h)-)?(\d+)$/i);
  if (!match) return null;

  const interval = match.length === 4 ? (match[1] || '15m') : (match[1] || '15m');
  const rawStage = match.length === 4 ? match[2] : 'squeeze';
  const score = Number(match.length === 4 ? match[3] : match[2]);
  const stage = String(rawStage ?? 'squeeze').toUpperCase();
  const side = String(payload.side ?? (
    stage.includes('SHORT') || stage === 'BREAKDOWN' ? 'SHORT' : 'LONG'
  )).toUpperCase();
  return {
    symbol: normalizeSymbol(payload.symbol),
    action: side,
    stage,
    interval,
    score,
    entry: Number(payload.entryPrice ?? payload.entry),
    tp: payload.tp ?? payload.takeProfitPrice ?? null,
    sl: payload.sl ?? payload.stopLossPrice ?? null,
    note: payload.note ?? '',
    markPrice: payload.signalMarkPrice ?? payload.markPrice ?? null,
  };
}

async function refineEmaSqueezePaperPayload(payload = {}) {
  const sig = signalFromEmaSqueezePaperPayload(payload);
  if (!sig) return payload;
  const refined = await refineEmaSqueezePaperSignal(sig, { allowFallback: true }).catch((err) => {
    console.warn(`[EmaSqueezePaper] manual liquidity refine ${sig.symbol}:`, err.message);
    return null;
  });
  const runnerMeta = buildEmaSqueezeRunnerPaperMeta({ ...payload, ...refined });
  if (!refined || refined === sig || !refined.liquidityEntry) {
    return runnerMeta.isRunner ? {
      ...payload,
      ...runnerMeta.payload,
      status: 'OPEN',
      source: String(payload.source ?? '').includes('runner') || !payload.source
        ? payload.source
        : String(payload.source).replace(/-(\d+)$/, `${runnerMeta.sourceSuffix}-$1`),
      note: [payload.note ?? '', runnerMeta.noteSuffix].filter(Boolean).join(' | '),
    } : payload;
  }
  return {
    ...payload,
    ...runnerMeta.payload,
    status: runnerMeta.isRunner ? 'OPEN' : (refined.paperStatus ?? payload.status),
    entryPrice: refined.entry,
    tp: refined.tp ?? payload.tp,
    sl: refined.sl ?? payload.sl,
    note: [refined.note ?? payload.note, runnerMeta.noteSuffix].filter(Boolean).join(' | '),
    signalMarkPrice: refined.markPrice ?? refined.entryPlan?.signalMarkPrice ?? payload.signalMarkPrice,
    sweepTargetPrice: refined.sweepTargetPrice ?? payload.sweepTargetPrice,
    sweepDistancePct: refined.sweepDistancePct ?? payload.sweepDistancePct,
    feasibleLeverage: refined.feasibleLeverage ?? payload.feasibleLeverage,
    feasibilityScore: refined.feasibilityScore ?? payload.feasibilityScore,
    rewardPct: refined.rewardPct ?? payload.rewardPct,
    riskPct: refined.riskPct ?? payload.riskPct,
    rr: refined.rr ?? payload.rr,
    heavySide: refined.heavySide ?? payload.heavySide,
    entryPlan: refined.entryPlan ?? payload.entryPlan,
  };
}

function buildEmaSqueezeRunnerPaperMeta(sig = {}) {
  const isRunner = Boolean(sig.runnerCandidate);
  if (!isRunner) return { isRunner: false, sourceSuffix: '', noteSuffix: '', payload: {} };
  const runnerSide = String(sig.action ?? sig.side ?? '').toUpperCase() === 'SHORT' ? 'SHORT' : 'LONG';
  const runnerScore = Number(sig.runnerScore ?? 0);
  const runnerTp = Number(sig.runnerTp ?? 0);
  const projected = Number(sig.runnerProjectedMovePct ?? 0);
  const noteParts = [
    'runner=Y',
    `runnerSide=${runnerSide}`,
    Number.isFinite(runnerScore) && runnerScore > 0 ? `runnerScore=${runnerScore.toFixed(0)}` : '',
    Number.isFinite(runnerTp) && runnerTp > 0 ? `runnerTP=${runnerTp.toFixed(6)}` : '',
    Number.isFinite(projected) && projected > 0 ? `runnerProjected=${runnerSide === 'SHORT' ? '-' : '+'}${projected.toFixed(1)}%` : '',
    sig.runnerReason ? `runnerReason=${sig.runnerReason}` : '',
  ].filter(Boolean);
  return {
    isRunner: true,
    sourceSuffix: '-runner',
    noteSuffix: noteParts.join(' | '),
    payload: {
      runnerCandidate: true,
      runnerSide,
      runnerScore: Number.isFinite(runnerScore) ? runnerScore : null,
      runnerTp: Number.isFinite(runnerTp) && runnerTp > 0 ? runnerTp : null,
      runnerProjectedMovePct: Number.isFinite(projected) ? projected : null,
      runnerReason: sig.runnerReason ?? null,
    },
  };
}

async function enrichEmaSqueezeSignalsWithLiquidityEntries(signals = []) {
  const out = [];
  for (const sig of signals ?? []) {
    const refined = await refineEmaSqueezePaperSignal(sig, { allowFallback: true }).catch(() => null);
    if (!refined?.liquidityEntry) {
      out.push({
        ...sig,
        emaEntry: sig.entry,
        emaTp: sig.tp ?? null,
        emaSl: sig.sl ?? null,
      });
      continue;
    }
    out.push({
      ...sig,
      emaEntry: sig.entry,
      emaTp: sig.tp ?? null,
      emaSl: sig.sl ?? null,
      liquidEntry: refined.liquidPlanEntry ?? refined.entry,
      liquidTp: refined.liquidPlanTp ?? refined.tp ?? null,
      liquidSl: refined.liquidPlanSl ?? refined.sl ?? null,
      paperEntry: refined.entry,
      paperTp: refined.tp ?? null,
      paperSl: refined.sl ?? null,
      liquidEntryOk: true,
      liquidityEntry: refined.liquidityEntry,
      liquidityEntryPlan: refined.entryPlan ?? null,
      liquidityEntryNote: refined.note ?? '',
    });
  }
  return out;
}

// Phân loại regime BTC cho gate pre-stage:
//   WEAK   – BTC yếu/giảm → ưu tiên SHORT, hạn chế LONG
//   STRONG – BTC mạnh/tăng → ưu tiên LONG, hạn chế SHORT
//   FLAT   – đi ngang/không rõ → coi như hạn chế LONG (theo backtest pre_breakout FLAT âm nặng)
function emaSqueezeBtcRegime(health = btcHealthCache.data) {
  if (!health || health.error) return 'FLAT';
  const trendScore = Number(health.btcTrendScore ?? 0);
  const trendDir = String(health.btcTrendDir ?? '').toLowerCase();
  const bearishBias = health.bias === 'bearish' || health.bias === 'caution';
  const bearSignals = health.emaTrend1h === 'below'
    || (health.rsi1h != null && health.rsi1h < 45)
    || (health.pct6h != null && health.pct6h < -0.5);
  const bullSignals = health.emaTrend1h === 'above'
    && (health.rsi1h == null || health.rsi1h >= 52)
    && (health.pct6h == null || health.pct6h > 0.3);
  const weakUp = trendDir === 'up' && Number.isFinite(trendScore) && trendScore < 55 && bullSignals;
  const weakDown = trendDir === 'down' && Number.isFinite(trendScore) && trendScore < 55 && bearSignals;
  if (weakUp) return 'WEAK_UP';
  if (weakDown) return 'WEAK_DOWN';
  if (bearishBias || bearSignals) return 'WEAK';
  if (bullSignals && health.bias === 'neutral' && Number.isFinite(trendScore) && trendScore >= 55) return 'STRONG';
  return 'FLAT';
}

function getEmaSqueezeMarketRegime(health = btcHealthCache.data) {
  if (!health || health.error) return { regime: 'CHOP', reason: 'BTC health not ready' };
  const dir = String(health.btcTrendDir ?? '').toLowerCase();
  const score = Number(health.btcTrendScore ?? 0);
  const pct6h = Number(health.pct6h);
  const candle1h = Number(health.btcCandle1hPct);
  const ema1h = String(health.emaTrend1h ?? '').toLowerCase();
  const rsi1h = Number(health.rsi1h);
  const upPts = [
    dir === 'up' && score >= 55,
    ema1h === 'above',
    Number.isFinite(pct6h) && pct6h >= 0.25,
    Number.isFinite(candle1h) && candle1h >= 0.15,
    Number.isFinite(rsi1h) && rsi1h >= 52,
  ].filter(Boolean).length;
  const downPts = [
    dir === 'down' && score >= 55,
    ema1h === 'below',
    Number.isFinite(pct6h) && pct6h <= -0.25,
    Number.isFinite(candle1h) && candle1h <= -0.15,
    Number.isFinite(rsi1h) && rsi1h <= 48,
  ].filter(Boolean).length;
  const reason = `dir=${dir || '-'} score=${Number.isFinite(score) ? score : '-'} ema1h=${ema1h || '-'} pct6h=${Number.isFinite(pct6h) ? pct6h : '-'} candle1h=${Number.isFinite(candle1h) ? candle1h : '-'} rsi1h=${Number.isFinite(rsi1h) ? rsi1h : '-'} upPts=${upPts} downPts=${downPts}`;
  if (dir === 'up' && score >= 70 && upPts >= 3) return { regime: 'UP', reason };
  if (dir === 'down' && score >= 70 && downPts >= 3) return { regime: 'DOWN', reason };
  if (dir === 'up' && score < 55 && upPts >= 2 && downPts <= 1) return { regime: 'WEAK_UP', reason };
  if (dir === 'down' && score < 55 && downPts >= 2 && upPts <= 1) return { regime: 'WEAK_DOWN', reason };
  if (upPts >= 3 && downPts <= 1) return { regime: 'SIDEWAY_UP', reason };
  if (downPts >= 3 && upPts <= 1) return { regime: 'SIDEWAY_DOWN', reason };
  return { regime: 'CHOP', reason };
}

function getEmaSqueezeSidewayTpGate(health = btcHealthCache.data) {
  if (process.env.EMA_SQUEEZE_PAPER_SIDEWAY_TP_ENABLED === 'false') return null;
  const regimeInfo = getEmaSqueezeMarketRegime(health);
  const regime = String(regimeInfo.regime ?? 'CHOP').toUpperCase();
  const sidewayRegimes = new Set(['CHOP', 'SIDEWAY_UP', 'SIDEWAY_DOWN', 'WEAK_UP', 'WEAK_DOWN']);
  if (!sidewayRegimes.has(regime)) return null;
  const tpRoe = Math.max(0.1, Number(process.env.EMA_SQUEEZE_PAPER_SIDEWAY_TP_ROE ?? 5));
  return {
    regime,
    tpRoe,
    label: `SIDEWAY_TP_${tpRoe}%`,
    reason: regimeInfo.reason,
  };
}

function getEmaSqueezeBrLikeRegimeMarketGate({ side, score, brLikeScore, btcSnap, btcTurnGate, btcCorr }) {
  const regimeInfo = getEmaSqueezeMarketRegime(btcSnap);
  const regime = regimeInfo.regime;
  const tradeSide = String(side ?? '').toUpperCase();
  const highScore = Number(brLikeScore ?? 0) >= Number(process.env.EMA_SQUEEZE_BR_LIKE_REGIME_HIGH_BR_SCORE ?? 95)
    || Number(score ?? 0) >= Number(process.env.EMA_SQUEEZE_BR_LIKE_REGIME_HIGH_SIGNAL_SCORE ?? 90);
  const reverseCorrMax = Number(process.env.EMA_SQUEEZE_BR_LIKE_REGIME_REVERSE_CORR_MAX ?? -0.15);
  const reverseBtc = Number.isFinite(Number(btcCorr)) && Number(btcCorr) <= reverseCorrMax;
  const btcLabel = String(btcTurnGate?.btc?.label ?? btcTurnGate?.label ?? '').toUpperCase();
  const btcHit = Boolean(btcTurnGate?.btc?.hit) || /TOP_REJECT|BOTTOM_BOUNCE/.test(btcLabel);
  const btcReject = btcHit && btcLabel.includes('TOP_REJECT');
  const btcBounce = btcHit && btcLabel.includes('BOTTOM_BOUNCE');
  const chopMargin = Number(process.env.EMA_SQUEEZE_BR_LIKE_CHOP_TEST_MARGIN_USDT ?? 3);
  const common = {
    regime,
    reason: regimeInfo.reason,
    marketMarginUsdt: regime === 'CHOP' && Number.isFinite(chopMargin) && chopMargin > 0 ? chopMargin : null,
    highScore,
    reverseBtc,
    btcReject,
    btcBounce,
  };

  if (regime === 'CHOP') {
    return {
      ...common,
      blockMarket: false,
      label: 'CHOP_SIZE_3',
      reason: `${regimeInfo.reason}; CHOP => reduce test size to $${common.marketMarginUsdt ?? '-'}`,
    };
  }
  const upRegime = regime === 'UP' || regime === 'SIDEWAY_UP';
  const downRegime = regime === 'DOWN' || regime === 'SIDEWAY_DOWN';
  if (regime === 'WEAK_UP' && tradeSide === 'SHORT') {
    return { ...common, blockMarket: false, label: 'WEAK_UP_SHORT_OK', reason: `${regimeInfo.reason}; weak-up is not strong BTC, allow SHORT normally` };
  }
  if (regime === 'WEAK_DOWN' && tradeSide === 'LONG') {
    return { ...common, blockMarket: false, label: 'WEAK_DOWN_LONG_OK', reason: `${regimeInfo.reason}; weak-down is not strong BTC, allow LONG normally` };
  }
  if ((upRegime && tradeSide === 'LONG') || (downRegime && tradeSide === 'SHORT')) {
    return { ...common, blockMarket: false, label: `${regime}_ALIGNED`, reason: `${regimeInfo.reason}; ${tradeSide} aligned with ${regime}` };
  }
  const allowCounter = upRegime && tradeSide === 'SHORT'
    ? highScore && btcReject && reverseBtc
    : downRegime && tradeSide === 'LONG'
      ? highScore && btcBounce && reverseBtc
      : false;
  return {
    ...common,
    blockMarket: !allowCounter,
    label: allowCounter ? `${regime}_COUNTER_OK` : `${regime}_COUNTER_TEST_ONLY`,
    reason: `${regimeInfo.reason}; counter ${tradeSide}: highScore=${highScore} btcReject=${btcReject} btcBounce=${btcBounce} reverseBtc=${reverseBtc} corr=${btcCorr ?? '-'} threshold<=${reverseCorrMax}`,
  };
}

function getEmaSqueezeBreakoutRegimeMarketGate({ side, score, btcSnap, btcTurnGate, btcCorr }) {
  const regimeInfo = getEmaSqueezeMarketRegime(btcSnap);
  const regime = regimeInfo.regime;
  const tradeSide = String(side ?? '').toUpperCase();
  const highScore = Number(score ?? 0) >= Number(process.env.EMA_SQUEEZE_BREAKOUT_REGIME_HIGH_SIGNAL_SCORE ?? 90);
  const reverseCorrMax = Number(process.env.EMA_SQUEEZE_BREAKOUT_REGIME_REVERSE_CORR_MAX
    ?? process.env.EMA_SQUEEZE_BR_LIKE_REGIME_REVERSE_CORR_MAX
    ?? -0.15);
  const reverseBtc = Number.isFinite(Number(btcCorr)) && Number(btcCorr) <= reverseCorrMax;
  const btcLabel = String(btcTurnGate?.btc?.label ?? btcTurnGate?.label ?? '').toUpperCase();
  const btcHit = Boolean(btcTurnGate?.btc?.hit) || /TOP_REJECT|BOTTOM_BOUNCE/.test(btcLabel);
  const btcReject = btcHit && btcLabel.includes('TOP_REJECT');
  const btcBounce = btcHit && btcLabel.includes('BOTTOM_BOUNCE');
  const chopMargin = Number(process.env.EMA_SQUEEZE_BREAKOUT_CHOP_TEST_MARGIN_USDT
    ?? process.env.EMA_SQUEEZE_BR_LIKE_CHOP_TEST_MARGIN_USDT
    ?? 3);
  const common = {
    regime,
    marketMarginUsdt: regime === 'CHOP' && Number.isFinite(chopMargin) && chopMargin > 0 ? chopMargin : null,
    highScore,
    reverseBtc,
    btcReject,
    btcBounce,
  };
  if (regime === 'CHOP') {
    return {
      ...common,
      blockMarket: false,
      label: 'BREAKOUT_CHOP_SIZE_3',
      reason: `${regimeInfo.reason}; Breakout CHOP => reduce test size to $${common.marketMarginUsdt ?? '-'}`,
    };
  }
  const upRegime = regime === 'UP' || regime === 'SIDEWAY_UP';
  const downRegime = regime === 'DOWN' || regime === 'SIDEWAY_DOWN';
  if (regime === 'WEAK_UP' && tradeSide === 'SHORT') {
    return { ...common, blockMarket: false, label: 'BREAKOUT_WEAK_UP_SHORT_OK', reason: `${regimeInfo.reason}; weak-up is not strong BTC, allow SHORT normally` };
  }
  if (regime === 'WEAK_DOWN' && tradeSide === 'LONG') {
    return { ...common, blockMarket: false, label: 'BREAKOUT_WEAK_DOWN_LONG_OK', reason: `${regimeInfo.reason}; weak-down is not strong BTC, allow LONG normally` };
  }
  if ((upRegime && tradeSide === 'LONG') || (downRegime && tradeSide === 'SHORT')) {
    return { ...common, blockMarket: false, label: `BREAKOUT_${regime}_ALIGNED`, reason: `${regimeInfo.reason}; ${tradeSide} breakout aligned with ${regime}` };
  }
  const allowCounter = upRegime && tradeSide === 'SHORT'
    ? highScore && btcReject && reverseBtc
    : downRegime && tradeSide === 'LONG'
      ? highScore && btcBounce && reverseBtc
      : false;
  return {
    ...common,
    blockMarket: !allowCounter,
    label: allowCounter ? `BREAKOUT_${regime}_COUNTER_OK` : `BREAKOUT_${regime}_COUNTER_TEST_ONLY`,
    reason: `${regimeInfo.reason}; breakout counter ${tradeSide}: highScore=${highScore} btcReject=${btcReject} btcBounce=${btcBounce} reverseBtc=${reverseBtc} corr=${btcCorr ?? '-'} threshold<=${reverseCorrMax}`,
  };
}

function getEmaSqueezeGenericStageMarketGate({ side, stage, score, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_GENERIC_STAGE_GATE === 'false') return null;
  const regimeInfo = getEmaSqueezeMarketRegime(btcSnap);
  const regime = String(regimeInfo.regime ?? 'CHOP').toUpperCase();
  const tradeSide = String(side ?? '').toUpperCase();
  const signalStage = String(stage ?? '').toUpperCase();
  const corr = Number(btcCorr);
  const highScore = Number(score ?? 0) >= Number(process.env.EMA_SQUEEZE_GENERIC_STAGE_HIGH_SIGNAL_SCORE ?? 85);
  const blockMode = process.env.EMA_SQUEEZE_PAPER_GENERIC_STAGE_BLOCK_MARKET === 'true';
  const chopMargin = Number(process.env.EMA_SQUEEZE_GENERIC_STAGE_CHOP_TEST_MARGIN_USDT
    ?? process.env.EMA_SQUEEZE_BR_LIKE_CHOP_TEST_MARGIN_USDT
    ?? 3);
  const common = {
    regime,
    marketMarginUsdt: regime === 'CHOP' && Number.isFinite(chopMargin) && chopMargin > 0 ? chopMargin : null,
    highScore,
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
  };
  const stageLabel = String(signalStage || 'STAGE').replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  const labelPrefix = `EMA_${stageLabel || 'STAGE'}`;
  const reasonBase = `${regimeInfo.reason}; stage=${signalStage || '-'} side=${tradeSide || '-'} score=${Number(score ?? 0) || '-'} corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'}`;

  if (regime === 'CHOP') {
    return {
      ...common,
      blockMarket: false,
      label: `${labelPrefix}_CHOP_SIZE_${common.marketMarginUsdt ?? 3}`,
      reason: `${reasonBase}; CHOP => tag/reduce-test context`,
    };
  }

  const upRegime = regime === 'UP' || regime === 'SIDEWAY_UP';
  const downRegime = regime === 'DOWN' || regime === 'SIDEWAY_DOWN';
  if ((upRegime && tradeSide === 'LONG') || (downRegime && tradeSide === 'SHORT')) {
    return {
      ...common,
      blockMarket: false,
      label: `${labelPrefix}_${regime}_ALIGNED`,
      reason: `${reasonBase}; aligned with BTC regime`,
    };
  }
  if (regime === 'WEAK_UP' && tradeSide === 'SHORT') {
    return {
      ...common,
      blockMarket: false,
      label: `${labelPrefix}_WEAK_UP_SHORT_OK`,
      reason: `${reasonBase}; weak-up allows short test/market context`,
    };
  }
  if (regime === 'WEAK_DOWN' && tradeSide === 'LONG') {
    return {
      ...common,
      blockMarket: false,
      label: `${labelPrefix}_WEAK_DOWN_LONG_OK`,
      reason: `${reasonBase}; weak-down allows long test/market context`,
    };
  }

  const counter = (upRegime && tradeSide === 'SHORT') || (downRegime && tradeSide === 'LONG');
  return {
    ...common,
    blockMarket: blockMode && counter && !highScore,
    label: counter ? `${labelPrefix}_${regime}_COUNTER_TEST` : `${labelPrefix}_${regime}_NEUTRAL`,
    reason: `${reasonBase}; counter=${counter} highScore=${highScore} blockMode=${blockMode}`,
  };
}

function noteMetricNumber(note, pattern) {
  const match = String(note ?? '').match(pattern);
  return match ? Number(match[1]) : NaN;
}

function getBreakoutMetricPct(sig = {}, paperSignal = {}, key) {
  const raw = sig?.[key] ?? paperSignal?.[key];
  const n = Number(raw);
  if (!Number.isFinite(n)) return NaN;
  return Math.abs(n) <= 1 ? n * 100 : n;
}

function getEmaSqueezeBreakoutChaseMarketGate({ side, sig, paperSignal, btcCorr }) {
  if (process.env.EMA_SQUEEZE_BREAKOUT_CHASE_MARKET_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  const note = [sig?.note, sig?.noteBase, paperSignal?.note, paperSignal?.reason].filter(Boolean).join(' | ');
  const pump = Number.isFinite(getBreakoutMetricPct(sig, paperSignal, 'pumpMovePct'))
    ? getBreakoutMetricPct(sig, paperSignal, 'pumpMovePct')
    : noteMetricNumber(note, /pump=([\d.]+)%/i);
  const base = Number.isFinite(getBreakoutMetricPct(sig, paperSignal, 'baseRangePct'))
    ? getBreakoutMetricPct(sig, paperSignal, 'baseRangePct')
    : noteMetricNumber(note, /base=([\d.]+)%/i);
  const corr = Number(btcCorr);
  const pumpMax = Number(process.env.EMA_SQUEEZE_BREAKOUT_CHASE_PUMP_MAX_PCT ?? 12);
  const baseMin = Number(process.env.EMA_SQUEEZE_BREAKOUT_CHASE_BASE_MIN_PCT ?? 7);
  const baseMax = Number(process.env.EMA_SQUEEZE_BREAKOUT_CHASE_BASE_MAX_PCT ?? 10);
  const corrMax = Number(process.env.EMA_SQUEEZE_BREAKOUT_CHASE_CORR_MAX ?? 0.3);
  const lowCorr = !Number.isFinite(corr) || corr < corrMax;
  const pumpHot = Number.isFinite(pump) && pump >= pumpMax;
  const wideBaseWeakBtc = Number.isFinite(base) && base >= baseMin && base < baseMax && lowCorr;
  const blockMarket = tradeSide === 'LONG' && (pumpHot || wideBaseWeakBtc);
  return {
    blockMarket,
    label: blockMarket ? 'BREAKOUT_CHASE_TEST_ONLY' : 'BREAKOUT_CHASE_OK',
    pump: Number.isFinite(pump) ? +pump.toFixed(2) : null,
    base: Number.isFinite(base) ? +base.toFixed(2) : null,
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    reason: `pump=${Number.isFinite(pump) ? pump.toFixed(1) : '-'}% max=${pumpMax}%; base=${Number.isFinite(base) ? base.toFixed(1) : '-'}% range=${baseMin}-${baseMax}%; corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'} max=${corrMax}; pumpHot=${pumpHot} wideBaseWeakBtc=${wideBaseWeakBtc}`,
  };
}

function getEmaSqueezeRunnerPreWeakMarketGate({ side, stage, sig, paperSignal, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_PRE_WEAK_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  const signalStage = String(stage ?? sig?.stage ?? paperSignal?.stage ?? '').toUpperCase();
  const note = [sig?.note, sig?.noteBase, paperSignal?.note, paperSignal?.reason].filter(Boolean).join(' | ');
  const base = Number.isFinite(getBreakoutMetricPct(sig, paperSignal, 'baseRangePct'))
    ? getBreakoutMetricPct(sig, paperSignal, 'baseRangePct')
    : noteMetricNumber(note, /base=([\d.]+)%/i);
  const corr = Number(btcCorr);
  const corrMax = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_PRE_WEAK_CORR_MAX ?? 0.3);
  const baseMin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_PRE_WEAK_BASE_MIN_PCT ?? 8);
  const lowCorr = !Number.isFinite(corr) || corr < corrMax;
  const wideBase = Number.isFinite(base) && base >= baseMin;
  const blockMarket = tradeSide === 'LONG' && signalStage === 'PRE_BREAKOUT' && (lowCorr || wideBase);
  return {
    blockMarket,
    label: blockMarket ? 'RUNNER_PRE_WEAK_TEST_ONLY' : 'RUNNER_PRE_OK',
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    base: Number.isFinite(base) ? +base.toFixed(2) : null,
    reason: `runner PRE ${tradeSide}: corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'} max=${corrMax}; base=${Number.isFinite(base) ? base.toFixed(1) : '-'}% min=${baseMin}%; lowCorr=${lowCorr} wideBase=${wideBase}`,
  };
}

// Gate pre-stage theo xu hướng BTC (backtest: pre-long thua khi BTC WEAK/FLAT, pre-short thắng khi WEAK/FLAT)
//   LONG  chỉ fire khi BTC STRONG
//   SHORT chỉ fire khi BTC KHÔNG STRONG (WEAK/FLAT)
function getBangkokHour(date = new Date()) {
  const raw = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Bangkok',
    hour: '2-digit',
    hour12: false,
  }).format(date);
  const hour = Number(raw);
  return Number.isFinite(hour) ? hour : null;
}

function getEmaSqueezeLongEvalGate({ interval, btcSnap, btcCorr, date = new Date() }) {
  if (process.env.EMA_SQUEEZE_PAPER_SQUEEZE_LONG_EVAL_GATE === 'false') return null;
  const tf = String(interval ?? '').toLowerCase();
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = btcSnap?.btcTrendScore == null ? NaN : Number(btcSnap.btcTrendScore);
  const corr = btcCorr == null ? NaN : Number(btcCorr);
  const hour = getBangkokHour(date);
  const badHours = new Set(String(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_LONG_BAD_HOURS ?? '7,8,9,14,21,23')
    .split(',')
    .map((value) => Number(value.trim()))
    .filter(Number.isFinite));
  const configuredFullMargin = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_LONG_A_MARGIN_USDT ?? 10);
  const configuredTestMargin = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_LONG_TEST_MARGIN_USDT ?? 1);
  const fullMarginUsdt = Number.isFinite(configuredFullMargin) && configuredFullMargin > 0 ? configuredFullMargin : 10;
  const testMarginUsdt = Number.isFinite(configuredTestMargin) && configuredTestMargin > 0 ? configuredTestMargin : 1;
  const downWeak = dir === 'down' && Number.isFinite(score) && score < 45;
  const downStrong = dir === 'down' && Number.isFinite(score) && score >= 65;
  const corrWeak = Number.isFinite(corr) && corr >= 0.3 && corr < 0.5;
  const independent = Number.isFinite(corr) && corr < 0.3;
  const groupA = tf === '5m' && (downWeak || downStrong) && corrWeak;
  const groupB = tf === '15m' && downWeak && independent;
  const badHour = Number.isFinite(hour) && badHours.has(hour);

  let tier = groupA ? 'A' : groupB ? 'B' : 'WATCH';
  let marginUsdt = groupA ? fullMarginUsdt : testMarginUsdt;
  let label = groupA ? 'SQUEEZE_LONG_A_FULL' : groupB ? 'SQUEEZE_LONG_B_TEST' : 'SQUEEZE_LONG_WATCH_TEST';
  if (badHour) {
    tier = 'WATCH';
    marginUsdt = testMarginUsdt;
    label = 'SQUEEZE_LONG_BAD_HOUR_TEST';
  }
  return {
    tier,
    label,
    marginUsdt,
    testOnly: marginUsdt <= testMarginUsdt,
    hour,
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    btcPhase: dir && Number.isFinite(score)
      ? `BTC_${dir.toUpperCase()}_${score < 45 ? 'WEAK' : score < 65 ? 'MID' : 'STRONG'}`
      : 'BTC_NO_DATA',
    reason: `tf=${tf || '-'} btc=${dir || '-'}/${Number.isFinite(score) ? score : '-'} corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'} hour=${hour ?? '-'}; A=5m+DOWN_WEAK/STRONG+corr[0.3,0.5); B=15m+DOWN_WEAK+corr<0.3; badHour=${badHour}`,
  };
}

function getEmaPreStageRule({ stage, side, interval, btcPhase, corrBucket, hour = null }) {
  const signalStage = String(stage ?? '').toUpperCase().replace(/[^A-Z]/g, '');
  const tradeSide = String(side ?? '').toUpperCase();
  const tf = String(interval ?? '').toLowerCase();
  const phase = String(btcPhase ?? '').toLowerCase().replace(/^btc_/, '');
  const corr = String(corrBucket ?? '').toLowerCase().replace(/^btc_corr_/, '');
  const isPreBreakout = signalStage === 'PREBREAKOUT' && tradeSide === 'LONG';
  const isPreBreakdown = signalStage === 'PREBREAKDOWN' && tradeSide === 'SHORT';
  if (!isPreBreakout && !isPreBreakdown) return null;

  const key = `${tf}|${corr}|${phase}`;
  const preBreakoutA = new Set([
    '15m|rac|up_strong',
    '15m|yeu|up_mid',
    '5m|rac|up_weak',
    '5m|rac|down_mid',
  ]);
  const preBreakoutB = new Set([
    '5m|theo|up_strong',
    '5m|yeu|down_mid',
    '15m|yeu|up_strong',
  ]);
  const preBreakdownA = new Set([
    '5m|rac|down_mid',
    '15m|yeu|down_mid',
    '5m|theo|down_mid',
    '15m|rac|down_strong',
    '15m|rac|down_mid',
  ]);
  const preBreakdownB = new Set([
    '15m|yeu|up_mid',
    '15m|yeu|up_weak',
    '15m|yeu|down_weak',
    '5m|yeu|down_mid',
    '5m|yeu|up_weak',
    '5m|yeu|down_weak',
    '5m|yeu|down_strong',
  ]);
  const badHours = isPreBreakout
    ? new Set([0, 3, 5, 11, 22])
    : new Set([0, 4, 5, 6, 11, 17, 18]);
  const hasHour = hour !== null && hour !== undefined && Number.isFinite(Number(hour));
  const badHour = hasHour && badHours.has(Number(hour));
  const tier = (isPreBreakout ? preBreakoutA : preBreakdownA).has(key)
    ? 'A'
    : (isPreBreakout ? preBreakoutB : preBreakdownB).has(key)
      ? 'B'
      : 'BLOCK';
  const stageLabel = isPreBreakout ? 'PRE_BREAKOUT' : 'PRE_BREAKDOWN';
  return {
    allow: tier !== 'BLOCK' && !badHour,
    tier: badHour ? 'BLOCK' : tier,
    label: badHour ? `${stageLabel}_BAD_HOUR_BLOCK` : `${stageLabel}_${tier}`,
    badHour,
    key,
    reason: `${stageLabel} ${tradeSide} tf=${tf || '-'} btc=${phase || 'no_data'} corr=${corr || 'no_data'} hour=${hasHour ? Number(hour) : '-'}; selected=${tier}; badHour=${badHour}`,
  };
}

function getEmaPreStageEvalGate({ stage, side, interval, symbolCandle, btcCandle, btcSnap, btcCorr, date = new Date() }) {
  if (process.env.EMA_SQUEEZE_PAPER_PRE_STAGE_EVAL_GATE === 'false') return null;
  const rule = evaluateEmaPreStageCandle({
    stage,
    side,
    interval,
    symbolCandle,
    btcCandle,
  });
  if (!rule) return null;
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const trendScore = btcSnap?.btcTrendScore == null ? NaN : Number(btcSnap.btcTrendScore);
  const corr = btcCorr == null ? NaN : Number(btcCorr);
  return {
    ...rule,
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    btcPhase: dir && Number.isFinite(trendScore)
      ? `BTC_${dir.toUpperCase()}_${trendScore < 45 ? 'WEAK' : trendScore < 65 ? 'MID' : 'STRONG'}`
      : 'BTC_NO_DATA',
    hour: getBangkokHour(date),
  };
}

function getEmaRunnerRule({ side, interval, btcPhase, corrBucket, hour }) {
  const tradeSide = String(side ?? '').toUpperCase();
  const tf = String(interval ?? '').toLowerCase();
  const phase = String(btcPhase ?? '').toLowerCase().replace(/^btc_/, '');
  const corr = String(corrBucket ?? '').toLowerCase().replace(/^btc_corr_/, '');
  const currentHour = Number(hour);
  if (!['LONG', 'SHORT'].includes(tradeSide) || !['5m', '15m'].includes(tf)) return null;

  const key = `${tf}|${corr}|${phase}`;
  const oppositeHighCorr = corr === 'theo'
    && ((tradeSide === 'LONG' && phase.startsWith('down_'))
      || (tradeSide === 'SHORT' && phase.startsWith('up_')));
  const shortUpWeakTheo = tradeSide === 'SHORT' && corr === 'theo' && phase === 'up_weak';

  const shortGoodCombos = new Set([
    '15m|yeu|down_strong',
    '15m|theo|down_weak',
    '15m|yeu|down_mid',
    '15m|yeu|up_mid',
    '15m|theo|down_mid',
    '5m|theo|down_mid',
    '5m|rac|down_mid',
  ]);
  const longGoodCombos = new Set([
    '15m|rac|up_strong',
    '5m|theo|up_strong',
    '5m|rac|down_mid',
  ]);

  let tier = 'BLOCK';
  let label = 'RUNNER_BLOCK';
  if (!oppositeHighCorr && !shortUpWeakTheo) {
    if (tradeSide === 'SHORT' && currentHour === 8
        && ['down_mid', 'down_strong'].includes(phase)) {
      tier = tf === '15m' ? 'A' : shortGoodCombos.has(key) ? 'B' : 'BLOCK';
      label = tier === 'A' ? 'RUNNER_SHORT_H08_A' : tier === 'B' ? 'RUNNER_SHORT_H08_B' : label;
    } else if (tradeSide === 'LONG' && currentHour === 6) {
      tier = tf === '15m' ? 'A' : longGoodCombos.has(key) ? 'B' : 'BLOCK';
      label = tier === 'A' ? 'RUNNER_LONG_H06_A' : tier === 'B' ? 'RUNNER_LONG_H06_B' : label;
    } else if (tradeSide === 'SHORT' && [0, 13, 14, 23].includes(currentHour)
        && shortGoodCombos.has(key)) {
      tier = 'B';
      label = `RUNNER_SHORT_H${String(currentHour).padStart(2, '0')}_B`;
    } else if (tradeSide === 'LONG' && [5, 20].includes(currentHour)
        && longGoodCombos.has(key)) {
      tier = 'B';
      label = `RUNNER_LONG_H${String(currentHour).padStart(2, '0')}_B`;
    }
  }

  return {
    allow: tier !== 'BLOCK',
    tier,
    label,
    key,
    hour: Number.isFinite(currentHour) ? currentHour : null,
    reason: `Runner ${tradeSide} tf=${tf} btc=${phase || 'no_data'} corr=${corr || 'no_data'} hour=${Number.isFinite(currentHour) ? currentHour : '-'}; oppositeHighCorr=${oppositeHighCorr}; selected=${tier}`,
  };
}

function getEmaRunnerEvalGate({ side, interval, btcSnap, btcCorr, date = new Date() }) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_EVAL_GATE === 'false') return null;
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const trendScore = btcSnap?.btcTrendScore == null ? NaN : Number(btcSnap.btcTrendScore);
  const corr = btcCorr == null ? NaN : Number(btcCorr);
  const btcPhase = dir && Number.isFinite(trendScore)
    ? `${dir}_${trendScore < 45 ? 'weak' : trendScore < 65 ? 'mid' : 'strong'}`
    : 'no_data';
  const corrBucket = Number.isFinite(corr)
    ? corr < 0.3 ? 'rac' : corr < 0.5 ? 'yeu' : 'theo'
    : 'no_data';
  const rule = getEmaRunnerRule({
    side,
    interval,
    btcPhase,
    corrBucket,
    hour: getBangkokHour(date),
  });
  if (!rule) return null;
  const configuredFullMargin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_A_MARGIN_USDT ?? 10);
  const configuredTestMargin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_B_MARGIN_USDT ?? 1);
  const fullMarginUsdt = Number.isFinite(configuredFullMargin) && configuredFullMargin > 0 ? configuredFullMargin : 10;
  const testMarginUsdt = Number.isFinite(configuredTestMargin) && configuredTestMargin > 0 ? configuredTestMargin : 1;
  return {
    ...rule,
    marginUsdt: rule.tier === 'A' ? fullMarginUsdt : rule.tier === 'B' ? testMarginUsdt : 0,
    testOnly: rule.tier === 'B',
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    btcPhase: btcPhase === 'no_data' ? 'BTC_NO_DATA' : `BTC_${btcPhase.toUpperCase()}`,
  };
}

function getEmaBreakStageEvalGate({ stage, side, interval, signalScore, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_BREAK_STAGE_EVAL_GATE === 'false') return null;
  const signalStage = String(stage ?? '').toUpperCase();
  const tradeSide = String(side ?? '').toUpperCase();
  if (!((signalStage === 'BREAKOUT' && tradeSide === 'LONG')
      || (signalStage === 'BREAKDOWN' && tradeSide === 'SHORT'))) return null;
  const tf = String(interval ?? '').toLowerCase();
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const trendScore = btcSnap?.btcTrendScore == null ? NaN : Number(btcSnap.btcTrendScore);
  const corr = btcCorr == null ? NaN : Number(btcCorr);
  const phase = dir && Number.isFinite(trendScore)
    ? `${dir}_${trendScore < 45 ? 'weak' : trendScore < 65 ? 'mid' : 'strong'}`
    : 'no_data';
  const configuredFullMargin = Number(process.env.EMA_SQUEEZE_PAPER_BREAK_STAGE_A_MARGIN_USDT ?? 10);
  const configuredTestMargin = Number(process.env.EMA_SQUEEZE_PAPER_BREAK_STAGE_TEST_MARGIN_USDT ?? 1);
  const fullMarginUsdt = Number.isFinite(configuredFullMargin) && configuredFullMargin > 0 ? configuredFullMargin : 10;
  const testMarginUsdt = Number.isFinite(configuredTestMargin) && configuredTestMargin > 0 ? configuredTestMargin : 1;
  let tier = 'WATCH';
  let label = `${signalStage}_WATCH_TEST`;

  if (signalStage === 'BREAKOUT') {
    const groupA = tf === '5m'
      && Number.isFinite(corr) && corr < 0.3
      && ['up_weak', 'down_weak'].includes(phase);
    const groupB = tf === '15m'
      && Number.isFinite(corr) && corr < 0.3
      && phase === 'down_mid';
    if (groupA) {
      tier = 'A';
      label = 'BREAKOUT_A_FULL';
    } else if (groupB) {
      tier = 'B';
      label = 'BREAKOUT_B_TEST';
    }
  } else {
    const groupA = (tf === '5m' && Number.isFinite(corr) && corr >= 0.3 && corr < 0.5 && phase === 'down_mid')
      || (tf === '5m' && Number.isFinite(corr) && corr < 0.3 && phase === 'up_strong')
      || (tf === '5m' && Number.isFinite(corr) && corr >= 0.3 && corr < 0.5 && phase === 'down_weak')
      || (tf === '15m' && Number.isFinite(corr) && corr >= 0.5 && phase === 'down_mid')
      || (tf === '5m' && Number.isFinite(corr) && corr < 0.3 && phase === 'down_strong');
    if (groupA) {
      tier = 'A';
      label = 'BREAKDOWN_A_FULL';
    }
  }

  const marginUsdt = tier === 'A' ? fullMarginUsdt : testMarginUsdt;
  return {
    tier,
    label,
    marginUsdt,
    testOnly: tier !== 'A',
    corr: Number.isFinite(corr) ? +corr.toFixed(3) : null,
    btcPhase: phase === 'no_data' ? 'BTC_NO_DATA' : `BTC_${phase.toUpperCase()}`,
    signalScore: Number.isFinite(Number(signalScore)) ? Number(signalScore) : null,
    reason: `${signalStage} ${tradeSide} tf=${tf || '-'} btc=${phase} corr=${Number.isFinite(corr) ? corr.toFixed(2) : '-'} score=${Number.isFinite(Number(signalScore)) ? Number(signalScore) : '-'}`,
  };
}

function getEmaSqueezeRunnerSessionTestGate({ side, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_US_SESSION_TEST_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  if (tradeSide !== 'SHORT') return null;
  const hour = getBangkokHour();
  const fromHour = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_FROM_HOUR ?? 23);
  const toHour = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_TO_HOUR ?? 3);
  const inSession = Number.isFinite(hour)
    && (fromHour <= toHour
      ? hour >= fromHour && hour < toHour
      : hour >= fromHour || hour < toHour);
  if (!inSession) return null;

  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = Number(btcSnap?.btcTrendScore);
  const minScore = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_DOWN_STRONG_MIN_SCORE ?? 65);
  const corr = Number(btcCorr);
  const minCorr = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_DOWN_STRONG_MIN_CORR ?? 0.5);
  const downStrong = dir === 'down' && Number.isFinite(score) && score >= minScore;
  const followsBtc = Number.isFinite(corr) && corr >= minCorr;
  if (!downStrong || !followsBtc) return null;

  const testMargin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_TEST_MARGIN_USDT ?? 1);
  const margin = Number.isFinite(testMargin) && testMargin > 0 ? testMargin : 1;
  return {
    blockMarket: false,
    testOnly: true,
    label: 'RUNNER_US_SESSION_DOWN_STRONG_TEST_1',
    marketMarginUsdt: margin,
    hour,
    corr: +corr.toFixed(3),
    reason: `VN ${fromHour}:00-${toHour}:00; Runner SHORT + BTC_DOWN_STRONG score=${Number.isFinite(score) ? score : '-'}>=${minScore} + corr=${corr.toFixed(2)}>=${minCorr}; overnight bad combo test $${margin}`,
  };
}

function getEmaSqueezeRunnerBadComboTestGate({ side, interval, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_COMBO_TEST_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  const tf = String(interval ?? '').toLowerCase();
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = Number(btcSnap?.btcTrendScore);
  const corr = Number(btcCorr);
  if (!['LONG', 'SHORT'].includes(tradeSide) || !['5m', '15m'].includes(tf)) return null;
  if (!Number.isFinite(score) || !Number.isFinite(corr)) return null;

  const corrRac = corr < 0.3;
  const corrYeu = corr >= 0.3 && corr < 0.5;
  const corrTheo = corr >= 0.5;
  const upWeak = dir === 'up' && score < 45;
  const upMid = dir === 'up' && score >= 45 && score < 65;
  const upStrong = dir === 'up' && score >= 65;
  const downWeak = dir === 'down' && score < 45;
  const downMid = dir === 'down' && score >= 45 && score < 65;
  const downStrong = dir === 'down' && score >= 65;
  const cases = [
    tradeSide === 'LONG' && tf === '5m' && corrRac && upMid
      ? 'RUNNER_LONG_5M_RAC_UP_MID_BAD_TEST_1'
      : null,
    tradeSide === 'LONG' && tf === '5m' && corrRac && upStrong
      ? 'RUNNER_LONG_5M_RAC_UP_STRONG_BAD_TEST_1'
      : null,
    tradeSide === 'LONG' && tf === '5m' && corrTheo && upStrong
      ? 'RUNNER_LONG_5M_THEO_UP_STRONG_BAD_TEST_1'
      : null,
    tradeSide === 'LONG' && tf === '15m' && corrYeu && upMid
      ? 'RUNNER_LONG_15M_YEU_UP_MID_BAD_TEST_1'
      : null,
    tradeSide === 'LONG' && tf === '5m' && corrTheo && downWeak
      ? 'RUNNER_LONG_5M_THEO_DOWN_WEAK_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '5m' && corrTheo && downStrong
      ? 'RUNNER_SHORT_5M_THEO_DOWN_STRONG_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '5m' && corrRac && upWeak
      ? 'RUNNER_SHORT_5M_RAC_UP_WEAK_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '5m' && corrRac && upMid
      ? 'RUNNER_SHORT_5M_RAC_UP_MID_SIDEWAY_UP_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '5m' && corrRac && upStrong
      ? 'RUNNER_SHORT_5M_RAC_UP_STRONG_SIDEWAY_UP_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '15m' && corrTheo && downMid
      ? 'RUNNER_SHORT_15M_THEO_DOWN_MID_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '15m' && corrRac && upWeak
      ? 'RUNNER_SHORT_15M_RAC_UP_WEAK_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '15m' && corrTheo && upWeak
      ? 'RUNNER_SHORT_15M_THEO_UP_WEAK_BAD_TEST_1'
      : null,
    tradeSide === 'SHORT' && tf === '5m' && corrRac && downMid
      ? 'RUNNER_SHORT_5M_RAC_DOWN_MID_BAD_TEST_1'
      : null,
  ].find(Boolean);
  if (!cases) return null;

  const testMargin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_COMBO_TEST_MARGIN_USDT ?? 1);
  const margin = Number.isFinite(testMargin) && testMargin > 0 ? testMargin : 1;
  return {
    blockMarket: false,
    testOnly: true,
    label: cases,
    marketMarginUsdt: margin,
    corr: +corr.toFixed(3),
    btcTrendDir: dir,
    btcTrendScore: score,
    reason: `${cases}: tf=${tf} side=${tradeSide} btc=${dir}/${score} corr=${corr.toFixed(2)} -> test $${margin}`,
  };
}

function getEmaSqueezeRunnerPositiveComboSizeGate({ side, interval, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_POSITIVE_COMBO_SIZE_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  const tf = String(interval ?? '').toLowerCase();
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = Number(btcSnap?.btcTrendScore);
  const corr = Number(btcCorr);
  if (tradeSide !== 'LONG' || tf !== '15m' || !Number.isFinite(score) || !Number.isFinite(corr)) return null;
  const corrRac = corr < 0.3;
  const upStrong = dir === 'up' && score >= 65;
  if (!corrRac || !upStrong) return null;
  const marginValue = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_POSITIVE_COMBO_MARGIN_USDT ?? 3);
  const margin = Number.isFinite(marginValue) && marginValue > 0 ? marginValue : 3;
  return {
    testOnly: true,
    label: 'RUNNER_LONG_15M_RAC_UP_STRONG_POSITIVE_TEST_3',
    marketMarginUsdt: margin,
    corr: +corr.toFixed(3),
    btcTrendDir: dir,
    btcTrendScore: score,
    reason: `Runner positive combo: tf=${tf} side=${tradeSide} btc=${dir}/${score} corr=${corr.toFixed(2)} -> test $${margin}`,
  };
}

function getEmaPumpBadComboTestGate({ stage, isRunner, side, interval, btcSnap, btcCorr, stageGateLabel }) {
  if (process.env.PUMP_BAD_COMBO_TEST_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  const tf = String(interval ?? '').toLowerCase();
  const stageName = String(stage ?? '').toUpperCase();
  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = Number(btcSnap?.btcTrendScore);
  const corr = Number(btcCorr);
  const gate = String(stageGateLabel ?? '').toUpperCase();
  if (!['LONG', 'SHORT'].includes(tradeSide) || !Number.isFinite(score) || !Number.isFinite(corr)) return null;

  const corrRac = corr < 0.3;
  const corrYeu = corr >= 0.3 && corr < 0.5;
  const corrTheo = corr >= 0.5;
  const upWeak = dir === 'up' && score < 45;
  const upMid = dir === 'up' && score >= 45 && score < 65;
  const upStrong = dir === 'up' && score >= 65;
  const cases = [
    stageName === 'BREAKOUT' && tradeSide === 'LONG' && (tf === '5m' || tf === '15m') && corrRac && upMid && gate === 'BREAKOUT_SIDEWAY_UP_ALIGNED'
      ? `PUMP_BAD_COMBO_BREAKOUT_LONG_${tf.toUpperCase()}_RAC_UP_MID_SIDEWAY_UP_TEST_1`
      : null,
    stageName === 'BREAKOUT' && tradeSide === 'LONG' && (tf === '5m' || tf === '15m') && corrRac && upMid && gate === 'PREMIUM'
      ? `PUMP_BAD_COMBO_BREAKOUT_LONG_${tf.toUpperCase()}_RAC_UP_MID_PREMIUM_TEST_1`
      : null,
    isRunner && tradeSide === 'LONG' && tf === '5m' && corrRac && upMid && gate === 'WEAK_UP_COUNTER_TEST_ONLY'
      ? 'PUMP_BAD_COMBO_RUNNER_LONG_5M_RAC_UP_MID_WEAK_UP_COUNTER_TEST_1'
      : null,
    isRunner && tradeSide === 'LONG' && tf === '15m' && corrYeu && upMid
      ? 'PUMP_BAD_COMBO_RUNNER_LONG_15M_YEU_UP_MID_TEST_1'
      : null,
    isRunner && tradeSide === 'LONG' && tf === '5m' && corrRac && upStrong && gate === 'SIDEWAY_UP_ALIGNED'
      ? 'PUMP_BAD_COMBO_RUNNER_LONG_5M_RAC_UP_STRONG_SIDEWAY_UP_ALIGNED_TEST_1'
      : null,
    isRunner && tradeSide === 'LONG' && tf === '5m' && corrTheo && upStrong
      ? 'PUMP_BAD_COMBO_RUNNER_LONG_5M_THEO_UP_STRONG_TEST_1'
      : null,
    isRunner && tradeSide === 'LONG' && tf === '15m' && corrRac && upStrong && gate === 'UP_ALIGNED'
      ? 'PUMP_BAD_COMBO_RUNNER_LONG_15M_RAC_UP_STRONG_UP_ALIGNED_TEST_1'
      : null,
    isRunner && tradeSide === 'SHORT' && tf === '5m' && corrRac && upWeak
      ? 'PUMP_BAD_COMBO_RUNNER_SHORT_5M_RAC_UP_WEAK_TEST_1'
      : null,
    isRunner && tradeSide === 'SHORT' && tf === '5m' && corrRac && upMid && gate === 'SIDEWAY_UP_COUNTER_TEST_ONLY'
      ? 'PUMP_BAD_COMBO_RUNNER_SHORT_5M_RAC_UP_MID_SIDEWAY_UP_COUNTER_TEST_1'
      : null,
    isRunner && tradeSide === 'SHORT' && tf === '5m' && corrRac && upStrong && gate === 'SIDEWAY_UP_COUNTER_TEST_ONLY'
      ? 'PUMP_BAD_COMBO_RUNNER_SHORT_5M_RAC_UP_STRONG_SIDEWAY_UP_COUNTER_TEST_1'
      : null,
    isRunner && tradeSide === 'SHORT' && tf === '15m' && corrRac && upWeak
      ? 'PUMP_BAD_COMBO_RUNNER_SHORT_15M_RAC_UP_WEAK_TEST_1'
      : null,
    isRunner && tradeSide === 'SHORT' && tf === '15m' && corrTheo && upWeak
      ? 'PUMP_BAD_COMBO_RUNNER_SHORT_15M_THEO_UP_WEAK_TEST_1'
      : null,
  ].find(Boolean);
  if (!cases) return null;

  const testMargin = Number(process.env.PUMP_BAD_COMBO_TEST_MARGIN_USDT ?? 1);
  const margin = Number.isFinite(testMargin) && testMargin > 0 ? testMargin : 1;
  return {
    testOnly: true,
    label: cases,
    marketMarginUsdt: margin,
    corr: +corr.toFixed(3),
    btcTrendDir: dir,
    btcTrendScore: score,
    reason: `${cases}: tf=${tf} stage=${isRunner ? 'RUNNER' : stageName} side=${tradeSide} btc=${dir}/${score} corr=${corr.toFixed(2)} gate=${gate || '-'} -> test $${margin}`,
  };
}

function getEmaSqueezeShortSessionTestGate({ kind, side, btcSnap, btcCorr }) {
  if (process.env.EMA_SQUEEZE_PAPER_SHORT_US_SESSION_TEST_GATE === 'false') return null;
  const tradeSide = String(side ?? '').toUpperCase();
  if (tradeSide !== 'SHORT') return null;
  const hour = getBangkokHour();
  const fromHour = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_FROM_HOUR ?? 23);
  const toHour = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_TO_HOUR ?? 3);
  const inSession = Number.isFinite(hour)
    && (fromHour <= toHour
      ? hour >= fromHour && hour < toHour
      : hour >= fromHour || hour < toHour);
  if (!inSession) return null;

  const dir = String(btcSnap?.btcTrendDir ?? '').toLowerCase();
  const score = Number(btcSnap?.btcTrendScore);
  const minScore = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_DOWN_STRONG_MIN_SCORE ?? 65);
  const corr = Number(btcCorr);
  const minCorr = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_DOWN_STRONG_MIN_CORR ?? 0.5);
  const downStrong = dir === 'down' && Number.isFinite(score) && score >= minScore;
  const followsBtc = Number.isFinite(corr) && corr >= minCorr;
  if (!downStrong || !followsBtc) return null;

  const testMargin = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_BAD_SESSION_TEST_MARGIN_USDT ?? 1);
  const margin = Number.isFinite(testMargin) && testMargin > 0 ? testMargin : 1;
  const labelKind = String(kind ?? 'SHORT').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return {
    blockMarket: false,
    testOnly: true,
    label: `${labelKind}_US_SESSION_DOWN_STRONG_TEST_1`,
    marketMarginUsdt: margin,
    hour,
    corr: +corr.toFixed(3),
    reason: `VN ${fromHour}:00-${toHour}:00; ${labelKind} SHORT + BTC_DOWN_STRONG score=${Number.isFinite(score) ? score : '-'}>=${minScore} + corr=${corr.toFixed(2)}>=${minCorr}; overnight bad combo test $${margin}`,
  };
}

function emaSqueezePreStageBtcGate(side, health = btcHealthCache.data) {
  const regime = emaSqueezeBtcRegime(health);
  if (side === 'SHORT' && regime === 'WEAK_UP') {
    return { ok: true, regime, reason: 'pre-short OK: BTC WEAK_UP is not strong-up' };
  }
  if (side === 'LONG') {
    return regime === 'STRONG'
      ? { ok: true, regime }
      : { ok: false, regime, reason: `pre-long chặn: BTC ${regime} (chỉ long khi BTC STRONG)` };
  }
  // SHORT: chặn khi BTC STRONG, HOẶC đang BOUNCE/chop (bias yếu nhưng giá đang bật) — short whipsaw.
  // Vd 19/06: bias caution nhưng EMA1h above + 6h dương → breakdown short bị bật, net sụt mạnh.
  if (regime === 'STRONG') {
    return { ok: false, regime, reason: 'pre-short chặn: BTC STRONG (chỉ short khi BTC WEAK/FLAT)' };
  }
  if (process.env.EMA_SQUEEZE_PAPER_SHORT_BLOCK_BOUNCE !== 'false' && health && !health.error) {
    const bounceMomentum = Number(process.env.EMA_SQUEEZE_PAPER_SHORT_BOUNCE_PCT6H ?? 0.3);
    const trendScore = Number(health.btcTrendScore ?? 0);
    const bouncing = health.emaTrend1h === 'above'
      && (!Number.isFinite(trendScore) || trendScore >= 55)
      && ((health.pct6h != null && health.pct6h > bounceMomentum)
        || (health.rsi1h != null && health.rsi1h >= 52));
    if (bouncing) {
      return { ok: false, regime, reason: `pre-short chặn: BTC đang bounce (EMA1h above, 6h=${health.pct6h ?? '-'}%, RSI1h=${health.rsi1h ?? '-'}) — chop dễ whipsaw short` };
    }
  }
  return { ok: true, regime };
}

function emaSqueezePreBreakdownQualityGate(sig = {}) {
  if (process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_GATE === 'false') {
    return { ok: true, reason: 'disabled' };
  }
  const pct = (value) => {
    const n = Number(value);
    if (!Number.isFinite(n)) return null;
    return Math.abs(n) <= 1 ? n * 100 : n;
  };
  const preVol = Math.max(Number(sig.pulseVolRatio ?? 0), Number(sig.volRatio ?? 0), Number(sig.breakoutVolRatio ?? 0));
  const redBars = Number(sig.redPulseBars ?? 0);
  const greenBars = Number(sig.greenPulseBars ?? 0);
  const rsi = Number(sig.rsi);
  const basePct = pct(sig.baseRangePct);
  const spreadPct = pct(sig.spreadPct);
  const minVol = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MIN_VOL ?? 2.0);
  const minRedBars = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MIN_RED_BARS ?? 2);
  const minRsi = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MIN_RSI ?? 30);
  const maxRsi = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MAX_RSI ?? 58);
  const maxBasePct = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MAX_BASE_PCT ?? 10);
  const maxSpreadPct = Number(process.env.EMA_SQUEEZE_PAPER_PRE_BREAKDOWN_MAX_SPREAD_PCT ?? 5);
  const fails = [];

  if (!Number.isFinite(preVol) || preVol < minVol) fails.push(`vol ${Number.isFinite(preVol) ? preVol.toFixed(1) : '-'}x < ${minVol}x`);
  if (!Number.isFinite(redBars) || redBars < minRedBars) fails.push(`redBars ${Number.isFinite(redBars) ? redBars : '-'} < ${minRedBars}`);
  if (Number.isFinite(greenBars) && Number.isFinite(redBars) && redBars <= greenBars) fails.push(`redBars ${redBars} <= greenBars ${greenBars}`);
  if (!Number.isFinite(rsi) || rsi < minRsi) fails.push(`RSI ${Number.isFinite(rsi) ? rsi.toFixed(1) : '-'} < ${minRsi} (short dễ ngay đáy)`);
  if (Number.isFinite(rsi) && rsi > maxRsi) fails.push(`RSI ${rsi.toFixed(1)} > ${maxRsi}`);
  if (Number.isFinite(basePct) && basePct > maxBasePct) fails.push(`base ${basePct.toFixed(1)}% > ${maxBasePct}%`);
  if (Number.isFinite(spreadPct) && spreadPct > maxSpreadPct) fails.push(`spread ${spreadPct.toFixed(1)}% > ${maxSpreadPct}%`);

  const reason = `preBreakdownGate vol=${Number.isFinite(preVol) ? preVol.toFixed(1) : '-'}x red=${Number.isFinite(redBars) ? redBars : '-'} green=${Number.isFinite(greenBars) ? greenBars : '-'} rsi=${Number.isFinite(rsi) ? rsi.toFixed(1) : '-'} base=${Number.isFinite(basePct) ? basePct.toFixed(1) : '-'}% spread=${Number.isFinite(spreadPct) ? spreadPct.toFixed(1) : '-'}%`;
  return fails.length
    ? { ok: false, reason: `${reason}; ${fails.join('; ')}` }
    : { ok: true, reason };
}

// Snapshot BTC health lúc vào lệnh — lưu per-trade để backtest regime/gate sau này
function getEmaSqueezeBrLikeBtcGate(health = btcHealthCache.data) {
  const regime = emaSqueezeBtcRegime(health);
  if (!health || health.error) {
    return { ok: false, regime, reason: 'BTC health not ready' };
  }
  if (health.bias === 'bearish' || health.bias === 'caution') {
    return {
      ok: false,
      regime,
      reason: `BTC ${health.bias} / yellow-red (bearPoints=${health.bearPoints ?? '-'})`,
    };
  }
  if (regime === 'WEAK') {
    return {
      ok: false,
      regime,
      reason: `BTC_WEAK (RSI1h=${health.rsi1h ?? '-'} pct6h=${health.pct6h ?? '-'} EMA1h=${health.emaTrend1h ?? '-'})`,
    };
  }

  const lookbackMs = Math.max(5 * 60_000, Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_RECOVERY_LOOKBACK_MS ?? 4 * 3600_000));
  const cutoff = Date.now() - lookbackMs;
  const recent = btcHealthHistory.filter((row) => Number(row.at) >= cutoff);
  const hadWeak = recent.some((row) =>
    row.regime === 'WEAK'
    || row.bias === 'bearish'
    || row.bias === 'caution'
    || Number(row.bearPoints ?? 0) >= 2);
  const improving = health.emaTrend1h === 'above'
    && Number(health.rsi1h ?? 0) >= Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_MIN_RSI1H ?? 45)
    && Number(health.pct6h ?? -999) >= Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_MIN_PCT6H ?? -0.2);
  const allowStrongWithoutHistory = process.env.EMA_SQUEEZE_BR_LIKE_ALLOW_STRONG_WITHOUT_HISTORY === 'true'
    && regime === 'STRONG'
    && health.bullBias !== 'neutral';
  if (!((hadWeak && improving) || allowStrongWithoutHistory)) {
    return {
      ok: false,
      regime,
      reason: `BR-like needs BTC red/weak -> flat/strong recovery (hadWeak=${hadWeak} improving=${improving} regime=${regime})`,
    };
  }
  return {
    ok: true,
    regime,
    reason: hadWeak
      ? `BTC recovery ${recent.length}pts -> ${regime}`
      : `BTC strong fallback ${health.bullBias}`,
  };
}

function getEmaSqueezeBrLikePaperQualityGate(sig = {}) {
  const interval = String(sig.interval ?? '15m');
  const brLikeScore = Number(sig.brLikeScore ?? 0);
  const minScore = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_MIN_SCORE ?? 90);
  if (!Number.isFinite(brLikeScore) || brLikeScore < minScore) {
    return {
      ok: false,
      reason: `BR-like score ${Number.isFinite(brLikeScore) ? brLikeScore.toFixed(0) : '?'} < ${minScore}`,
    };
  }

  const basePct = Number(sig.baseRangePct) * 100;
  const movePct = Number(sig.brLikeMovePct ?? sig.pumpMovePct);
  const max15mBasePct = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_15M_MAX_BASE_PCT ?? 6);
  const max15mMovePct = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_15M_MAX_MOVE_PCT ?? 5);
  if (interval === '15m') {
    if (Number.isFinite(basePct) && basePct >= max15mBasePct) {
      return {
        ok: false,
        reason: `15m BR-like base ${basePct.toFixed(1)}% >= ${max15mBasePct}% (late/wide)`,
      };
    }
    if (Number.isFinite(movePct) && movePct >= max15mMovePct) {
      return {
        ok: false,
        reason: `15m BR-like move ${movePct.toFixed(1)}% >= ${max15mMovePct}% (market entry too chased)`,
      };
    }
  }

  return {
    ok: true,
    reason: [
      `BR-like quality score=${brLikeScore.toFixed(0)}`,
      Number.isFinite(basePct) ? `base=${basePct.toFixed(1)}%` : '',
      Number.isFinite(movePct) ? `move=${movePct.toFixed(1)}%` : '',
      `tf=${interval}`,
    ].filter(Boolean).join(' '),
  };
}

function closeReturnsFromCandles(candles, bars) {
  const rows = Array.isArray(candles) ? candles.slice(-(bars + 1)) : [];
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const prev = Number(rows[i - 1]?.close ?? rows[i - 1]?.[4]);
    const curr = Number(rows[i]?.close ?? rows[i]?.[4]);
    if (Number.isFinite(prev) && Number.isFinite(curr) && prev > 0) out.push((curr - prev) / prev);
  }
  return out;
}

function pearsonCorr(a, b) {
  const n = Math.min(a.length, b.length);
  if (n < 6) return null;
  const ax = a.slice(-n);
  const bx = b.slice(-n);
  const ma = ax.reduce((s, v) => s + v, 0) / n;
  const mb = bx.reduce((s, v) => s + v, 0) / n;
  let num = 0;
  let da = 0;
  let db = 0;
  for (let i = 0; i < n; i++) {
    const x = ax[i] - ma;
    const y = bx[i] - mb;
    num += x * y;
    da += x * x;
    db += y * y;
  }
  const den = Math.sqrt(da * db);
  return den > 0 ? num / den : null;
}

// Correlation coin vs BTC (returns) — cờ xem coin có đi theo sóng BTC không. >0.5 theo; <0.3 độc lập (rác)
function getCoinBtcCorr(symbol, interval = '5m', bars = 30) {
  const coin = klineCache.getIfCached(symbol, interval, bars + 2);
  const btc = klineCache.getIfCached('BTCUSDT', interval, bars + 2);
  if (!coin || !btc) return null;
  const c = pearsonCorr(closeReturnsFromCandles(coin, bars), closeReturnsFromCandles(btc, bars));
  return c == null ? null : Number(c.toFixed(2));
}

function getBrCandleFeaturesFromKline(kline, prev = null) {
  if (!kline) return null;
  const open = Number(kline.open);
  const high = Number(kline.high);
  const low = Number(kline.low);
  const close = Number(kline.close);
  if (![open, high, low, close].every(Number.isFinite) || high <= low) return null;
  const range = Math.max(1e-12, high - low);
  const bodyShare = Math.abs(close - open) / range;
  const upperShare = (high - Math.max(open, close)) / range;
  const lowerShare = (Math.min(open, close) - low) / range;
  const closePos = (close - low) / range;
  const dir = close >= open ? 'GREEN' : 'RED';
  const prevVol = Number(prev?.volume);
  const volRatio = prevVol > 0 ? Number(kline.volume) / prevVol : null;
  let kind = 'MIXED';
  if (bodyShare < 0.25) kind = 'DOJI';
  else if (upperShare >= 0.45 && upperShare > lowerShare * 1.5) kind = 'UPPER_WICK';
  else if (lowerShare >= 0.45 && lowerShare > upperShare * 1.5) kind = 'LOWER_WICK';
  else if (bodyShare >= 0.55 && closePos >= 0.75) kind = 'STRONG_GREEN_CLOSE';
  else if (bodyShare >= 0.55 && closePos <= 0.25) kind = 'STRONG_RED_CLOSE';
  else if (closePos >= 0.7) kind = 'CLOSE_HIGH';
  else if (closePos <= 0.3) kind = 'CLOSE_LOW';
  return {
    dir,
    kind,
    bodyShare: Number(bodyShare.toFixed(3)),
    upperShare: Number(upperShare.toFixed(3)),
    lowerShare: Number(lowerShare.toFixed(3)),
    closePos: Number(closePos.toFixed(3)),
    volRatio: volRatio == null ? null : Number(volRatio.toFixed(2)),
  };
}

function getBrRealCandleFit(side, features) {
  if (!features) return 'NO_DATA';
  const s = String(side ?? '').toUpperCase();
  const goodLong = (features.closePos >= 0.65 && features.upperShare <= 0.35)
    || features.kind === 'LOWER_WICK';
  const badLong = features.closePos <= 0.45
    || features.upperShare >= 0.45
    || (features.dir === 'RED' && features.bodyShare >= 0.45);
  const goodShort = (features.closePos <= 0.35 && features.lowerShare <= 0.35)
    || features.kind === 'UPPER_WICK';
  const badShort = features.closePos >= 0.55
    || features.lowerShare >= 0.45
    || (features.dir === 'GREEN' && features.bodyShare >= 0.45);
  if (s === 'LONG') return goodLong ? 'REAL_OK_CANDLE' : badLong ? 'REAL_BAD_CANDLE' : 'REAL_MID_CANDLE';
  if (s === 'SHORT') return goodShort ? 'REAL_OK_CANDLE' : badShort ? 'REAL_BAD_CANDLE' : 'REAL_MID_CANDLE';
  return 'NO_DATA';
}

function getEmaBrRealCandleFit(symbol, interval = '5m', side = '') {
  const klines = klineCache.getIfCached(symbol, interval, 6);
  if (!Array.isArray(klines) || klines.length < 2) return null;
  const lastClosed = klines.at(-2) ?? klines.at(-1);
  const prev = klines.at(-3) ?? null;
  const features = getBrCandleFeaturesFromKline(lastClosed, prev);
  if (!features) return null;
  return {
    label: getBrRealCandleFit(side, features),
    ...features,
  };
}

function getTopReversalBtcRelation(symbol) {
  const bars = Math.max(12, Number(process.env.TOP_REVERSAL_BTC_RELATION_BARS ?? 30));
  const coin = klineCache.getIfCached(symbol, '5m', bars + 2);
  const btc = klineCache.getIfCached('BTCUSDT', '5m', bars + 2);
  if (!coin || !btc) return null;
  const corr = pearsonCorr(closeReturnsFromCandles(coin, bars), closeReturnsFromCandles(btc, bars));
  const firstCoin = Number(coin.at(-(Math.min(bars, coin.length - 1) + 1))?.close);
  const lastCoin = Number(coin.at(-1)?.close);
  const firstBtc = Number(btc.at(-(Math.min(bars, btc.length - 1) + 1))?.close);
  const lastBtc = Number(btc.at(-1)?.close);
  const coinMovePct = firstCoin > 0 ? ((lastCoin - firstCoin) / firstCoin) * 100 : null;
  const btcMovePct = firstBtc > 0 ? ((lastBtc - firstBtc) / firstBtc) * 100 : null;
  const minCorr = Number(process.env.TOP_REVERSAL_BTC_ALIGNED_MIN_CORR ?? 0.45);
  return {
    corr: corr == null ? null : Number(corr.toFixed(2)),
    bars,
    coinMovePct: coinMovePct == null ? null : Number(coinMovePct.toFixed(2)),
    btcMovePct: btcMovePct == null ? null : Number(btcMovePct.toFixed(2)),
    relation: corr != null && corr >= minCorr ? 'aligned' : 'mixed',
  };
}

// Momentum gate: chặn short top-reversal khi coin còn pump mạnh (đỉnh chưa xác nhận, dễ bay tiếp)
function getTopReversalMomentumGate(symbol) {
  if (process.env.TOP_REVERSAL_PAPER_MOMENTUM_GATE === 'false') return { ok: true };
  const k = klineCache.getIfCached(symbol, '5m', 6);
  if (!k || k.length < 3) return { ok: true }; // thiếu data -> cho qua
  const last = k[k.length - 2]; // nến vừa đóng (bỏ nến đang chạy)
  const o = Number(last.open);
  const c = Number(last.close);
  const lastPct = o > 0 ? (c - o) / o * 100 : 0;
  const maxUp = Number(process.env.TOP_REVERSAL_PAPER_MOMENTUM_MAX_CANDLE_PCT ?? 3);
  // nến cuối còn xanh mạnh = đang bay, chưa đảo -> chặn
  if (lastPct > maxUp) {
    return { ok: false, reason: `nến cuối +${lastPct.toFixed(1)}% > ${maxUp}% (còn pump, đỉnh chưa xác nhận)` };
  }
  return { ok: true };
}

// Phân loại tín hiệu top-reversal TỐT vs KHÔNG TỐT (theo backtest 319 closed):
//  - TỐT  = no-DCA scout (SCOUT_ONLY / TOP_CONFIRMED, không cho DCA)  → net +556% / +202%
//  - XẤU  = tier cho DCA (QUALITY/VOLUME_DISTRIBUTION/qualityBreakdown/strongCase/dcaEligible)
//           → net ÂM (-88 .. -375%) vì DCA nhồi vào reversal thất bại.
// => tín hiệu tốt test margin lớn ($10), xấu test nhỏ ($1).
function isGoodTopReversal(sig) {
  if (!sig) return false;
  const tier = String(sig.qualityTier ?? '');
  const isDcaTier = Boolean(sig.strongCase)
    || Boolean(sig.qualityBreakdown)
    || Boolean(sig.qualityDcaEligible)
    || tier === 'QUALITY'
    || tier === 'VOLUME_DISTRIBUTION';
  return !isDcaTier;
}

function attachTopReversalBtcRelation(signals = []) {
  return signals.map((signal) => ({
    ...signal,
    btcRelation: signal.btcRelation ?? getTopReversalBtcRelation(signal.symbol),
  }));
}

function getTopReversalBtcBearShiftGate(health = btcHealthCache.data) {
  const regime = emaSqueezeBtcRegime(health);
  if (!health || health.error) return { ok: false, regime, reason: 'BTC health not ready' };
  const nowBad = health.bias === 'caution'
    || health.bias === 'bearish'
    || regime === 'WEAK'
    || Number(health.bearPoints ?? 0) >= Number(process.env.TOP_REVERSAL_BTC_SHIFT_MIN_BEAR_POINTS ?? 2);
  if (!nowBad) return { ok: false, regime, reason: `BTC not yellow/red yet (${health.bias ?? '-'} ${regime})` };
  const lookbackMs = Math.max(10 * 60_000, Number(process.env.TOP_REVERSAL_BTC_SHIFT_LOOKBACK_MS ?? 6 * 3600_000));
  const cutoff = Date.now() - lookbackMs;
  const recent = btcHealthHistory.filter((row) => Number(row.at) >= cutoff);
  const hadGreen = recent.some((row) =>
    row.regime === 'STRONG'
    || row.bullBias === 'bullish'
    || row.bullBias === 'caution'
    || Number(row.bullPoints ?? 0) >= 2);
  if (!hadGreen) {
    return { ok: false, regime, reason: `BTC yellow/red but no recent green phase (${recent.length}pts)` };
  }
  return {
    ok: true,
    regime,
    reason: `BTC green->${health.bias ?? regime} shift (${recent.length}pts, bear=${health.bearPoints ?? '-'})`,
  };
}

function buildBtcHealthSnapshot(health = btcHealthCache.data) {
  if (!health || health.error) return null;
  const marketRegime = getEmaSqueezeMarketRegime(health);
  return {
    regime: emaSqueezeBtcRegime(health),
    marketRegime: marketRegime.regime,
    marketRegimeReason: marketRegime.reason,
    bias: health.bias ?? null,
    bearPoints: health.bearPoints ?? null,
    rsi1h: health.rsi1h ?? null,
    rsi4h: health.rsi4h ?? null,
    rsi1d: health.rsi1d ?? null,
    pct6h: health.pct6h ?? null,
    emaTrend1h: health.emaTrend1h ?? null,
    obvTrend: health.obvTrend ?? null,
    bullBias: health.bullBias ?? null,
    bullPoints: health.bullPoints ?? null,
    fundingRate: health.fundingRate ?? null,
    longPct: health.longPct ?? null,
    btcTrendScore: health.btcTrendScore ?? null,
    btcTrendDir: health.btcTrendDir ?? null,
    btcTrendScore4h: health.btcTrendScore4h ?? null,
    btcTrendDir4h: health.btcTrendDir4h ?? null,
    pct24h: health.pct24h ?? null,
    btcCandle1hPct: health.btcCandle1hPct ?? null,
    btcSpikeAlert: health.btcSpikeAlert ?? null,
    btcSpike: health.btcSpike ?? null,
    macroShock: health.macroShock ?? getBtcMacroShockGuard(),
    at: new Date().toISOString(),
  };
}

function parseEmaSqueezeNoteNumber(note, regex) {
  const text = String(note ?? '');
  const m = text.match(regex);
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isFinite(n) ? n : null;
}

function getEmaSqueezeBreakoutBtcRisk(sig, health = btcHealthCache.data) {
  const stage = String(sig?.stage ?? '').toUpperCase();
  const side = String(sig?.action ?? '').toUpperCase();
  if (stage !== 'BREAKOUT' || side !== 'LONG') {
    return { block: false, warn: false, regime: emaSqueezeBtcRegime(health), reason: 'not breakout long' };
  }

  const note = String(sig?.note ?? '');
  const rawSpread = Number(sig?.spreadPct);
  const spreadPct = Number.isFinite(rawSpread)
    ? rawSpread * 100
    : parseEmaSqueezeNoteNumber(note, /spread=([0-9.]+)%/);
  const rawBreakoutBars = Number(sig?.breakoutAge);
  const breakoutBars = Number.isFinite(rawBreakoutBars)
    ? rawBreakoutBars
    : parseEmaSqueezeNoteNumber(note, /breakout-(\d+)bars/);
  const rawBreakVol = Number(sig?.breakoutVolRatio ?? sig?.volRatio);
  const breakVol = Number.isFinite(rawBreakVol)
    ? rawBreakVol
    : parseEmaSqueezeNoteNumber(note, /breakVol=([0-9.]+)x/);
  const rawPumpPct = Number(sig?.pumpMovePct);
  const pumpPct = Number.isFinite(rawPumpPct)
    ? rawPumpPct
    : parseEmaSqueezeNoteNumber(note, /pump=([0-9.]+)%/);

  const lateWide = Number.isFinite(breakoutBars)
    && Number.isFinite(spreadPct)
    && breakoutBars > 8
    && spreadPct >= 5;
  const exhaustion = Number.isFinite(breakVol)
    && Number.isFinite(pumpPct)
    && breakVol > 20
    && pumpPct >= 8;
  const regime = emaSqueezeBtcRegime(health);
  const warn = lateWide || exhaustion;
  const block = regime === 'WEAK' && warn;
  const tags = [
    lateWide ? `lateWide ${breakoutBars}bars/${spreadPct.toFixed(1)}% spread` : '',
    exhaustion ? `exhaustion vol ${breakVol.toFixed(1)}x/pump ${pumpPct.toFixed(1)}%` : '',
  ].filter(Boolean);
  return {
    block,
    warn,
    regime,
    lateWide,
    exhaustion,
    metrics: { spreadPct, breakoutBars, breakVol, pumpPct },
    reason: warn
      ? `BTC_${regime} + ${tags.join(' + ')}`
      : `BTC_${regime} breakout risk clear`,
  };
}

// Breadth đảo chiều: đếm số coin DISTINCT có tín hiệu br-like mỗi chiều trong cửa sổ trượt 30'.
// 1 loạt br-like chiều ngược xuất hiện = thị trường đảo → khóa lời lệnh chiều cũ sớm (trước khi cây giảm SL).
const brLikeBreadthLog = []; // {at, symbol, side}
function recordBrLikeBreadth(symbol, side) {
  if (!symbol || (side !== 'LONG' && side !== 'SHORT')) return;
  brLikeBreadthLog.push({ at: Date.now(), symbol: String(symbol), side });
}
function brLikeBreadthCounts() {
  const winMs = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_WINDOW_MS ?? 30 * 60_000);
  const cutoff = Date.now() - winMs;
  while (brLikeBreadthLog.length && brLikeBreadthLog[0].at < cutoff) brLikeBreadthLog.shift();
  const longSet = new Set();
  const shortSet = new Set();
  for (const r of brLikeBreadthLog) (r.side === 'LONG' ? longSet : shortSet).add(r.symbol);
  return { long: longSet.size, short: shortSet.size };
}

// Clone riêng cho runner: không dùng chung breadth log với BR-like để tránh tín hiệu nhiễu nhau.
const emaSqueezeRunnerBreadthLog = []; // {at, symbol, side}
function recordEmaSqueezeRunnerBreadth(symbol, side) {
  if (!symbol || (side !== 'LONG' && side !== 'SHORT')) return;
  emaSqueezeRunnerBreadthLog.push({ at: Date.now(), symbol: String(symbol), side });
}
function emaSqueezeRunnerBreadthCounts() {
  const winMs = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_REVERSAL_WINDOW_MS
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_WINDOW_MS
    ?? 30 * 60_000);
  const cutoff = Date.now() - winMs;
  while (emaSqueezeRunnerBreadthLog.length && emaSqueezeRunnerBreadthLog[0].at < cutoff) emaSqueezeRunnerBreadthLog.shift();
  const longSet = new Set();
  const shortSet = new Set();
  for (const r of emaSqueezeRunnerBreadthLog) (r.side === 'LONG' ? longSet : shortSet).add(r.symbol);
  return { long: longSet.size, short: shortSet.size };
}

// Clone riêng cho Breakout: không dùng chung breadth log với BR-like/Runner.
const emaSqueezeBreakoutBreadthLog = []; // {at, symbol, side}
function recordEmaSqueezeBreakoutBreadth(symbol, side) {
  if (!symbol || (side !== 'LONG' && side !== 'SHORT')) return;
  emaSqueezeBreakoutBreadthLog.push({ at: Date.now(), symbol: String(symbol), side });
}
function emaSqueezeBreakoutBreadthCounts() {
  const winMs = Number(process.env.EMA_SQUEEZE_PAPER_BREAKOUT_REVERSAL_WINDOW_MS
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_WINDOW_MS
    ?? 30 * 60_000);
  const cutoff = Date.now() - winMs;
  while (emaSqueezeBreakoutBreadthLog.length && emaSqueezeBreakoutBreadthLog[0].at < cutoff) emaSqueezeBreakoutBreadthLog.shift();
  const longSet = new Set();
  const shortSet = new Set();
  for (const r of emaSqueezeBreakoutBreadthLog) (r.side === 'LONG' ? longSet : shortSet).add(r.symbol);
  return { long: longSet.size, short: shortSet.size };
}

function getEmaSqueezeBrLikeQualityLabel(sig = {}, opts = {}) {
  const side = String(opts.side ?? sig.action ?? '').toUpperCase();
  const brScore = Number(opts.brLikeScore ?? sig.brLikeScore ?? 0);
  const runnerScore = Number(sig.runnerScore ?? 0);
  const movePct = Number(sig.brLikeMovePct ?? 0);
  const btcReason = String(opts.btcReason ?? '');
  const reasons = [];

  if (Number.isFinite(movePct) && movePct >= 8) {
    reasons.push(`move=${movePct.toFixed(1)}%>=8%`);
    return { label: 'LOW_CHASE', reasons };
  }

  if (side === 'LONG' && /caution|yellow-red|bearish|red\/weak/i.test(btcReason)) {
    reasons.push('LONG vs BTC caution/bearish');
  }

  if (brScore > 0 && brScore <= 90) {
    reasons.push(`brScore=${brScore}<=90 fee-risk`);
  }

  if (reasons.length) {
    return { label: reasons.some((r) => r.includes('BTC')) ? 'LOW_BTC_CONFLICT' : 'LOW_FEE_RISK', reasons };
  }

  const highQuality = brScore >= 94
    && Number.isFinite(movePct)
    && movePct >= 3
    && movePct < 8
    && runnerScore >= 75
    && runnerScore <= 84;
  if (highQuality) {
    return {
      label: 'HIGH',
      reasons: [`brScore=${brScore}`, `runner=${runnerScore}`, `move=${movePct.toFixed(1)}%`],
    };
  }

  return {
    label: 'OK',
    reasons: [`brScore=${brScore || '?'}`, `runner=${runnerScore || '?'}`, `move=${Number.isFinite(movePct) ? movePct.toFixed(1) : '?'}%`],
  };
}

function isEmaBrLikeShortTrade(t) {
  const source = String(t?.source ?? '').toLowerCase();
  const note = String(t?.note ?? '').toLowerCase();
  return String(t?.side ?? '').toUpperCase() === 'SHORT'
    && (source.includes('br_like_short')
      || note.includes('brlikeshort=y')
      || note.includes('br-like short')
      || isEmaSqueezeSqueezeShortBrRulesSource(source, note));
}

function isEmaSqueezeSqueezeShortBrRulesSource(source, note = '') {
  const s = String(source ?? '').toLowerCase();
  const n = String(note ?? '').toLowerCase();
  return process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_BR_RULES !== 'false'
    && s.startsWith('emasq-')
    && (s.includes('squeeze_short') || n.includes('squeezeshortbrrules=y'));
}

function isEmaSqueezeSqueezeLongBrRulesSource(source, note = '') {
  const s = String(source ?? '').toLowerCase();
  const n = String(note ?? '').toLowerCase();
  return process.env.EMA_SQUEEZE_PAPER_SQUEEZE_LONG_BR_RULES !== 'false'
    && s.startsWith('emasq-')
    && !s.includes('squeeze_short')
    && (s.includes('-squeeze') || n.includes('squeezelongbrrules=y'));
}

function isEmaSqueezeBrRulesMarketSourceForSide(source, side, note = '') {
  const s = String(source ?? '').toLowerCase();
  const tradeSide = String(side ?? '').toUpperCase();
  if (!s.startsWith('emasq-')) return false;
  if (s.includes('br_like')) return tradeSide === 'SHORT' ? s.includes('br_like_short') : !s.includes('br_like_short');
  if (tradeSide === 'SHORT') return isEmaSqueezeSqueezeShortBrRulesSource(s, note);
  if (tradeSide === 'LONG') return isEmaSqueezeSqueezeLongBrRulesSource(s, note);
  return false;
}

function addBrLikeShortRollingStats(bucket, trade) {
  const tradePnl = Number(trade?.pnl ?? 0);
  const outcome = String(trade?.outcome ?? trade?.status ?? '').toUpperCase();
  bucket.closed += 1;
  bucket.pnl += Number.isFinite(tradePnl) ? tradePnl : 0;
  if (Number.isFinite(tradePnl) && tradePnl > 0) bucket.wins += 1;
  if (outcome === 'SL') bucket.sl += 1;
  if (outcome === 'TP') bucket.tp += 1;
  if (outcome === 'BREADTH_REVERSAL_LOSS_CUT') bucket.breadthLossCut += 1;
}

function finalizeBrLikeShortRollingStats(bucket) {
  return {
    ...bucket,
    pnl: +bucket.pnl.toFixed(3),
    wr: bucket.closed ? +((bucket.wins / bucket.closed) * 100).toFixed(1) : 0,
  };
}

function getBrLikeShortRollingStatsFromStore(store, nowMs, windowMs) {
  const bucket = { closed: 0, pnl: 0, wins: 0, sl: 0, tp: 0, breadthLossCut: 0 };
  for (const t of store?.trades ?? []) {
    if (!isEmaBrLikeShortTrade(t)) continue;
    const closedAt = Date.parse(t.closedAt ?? '');
    if (!Number.isFinite(closedAt) || closedAt >= nowMs || closedAt < nowMs - windowMs) continue;
    addBrLikeShortRollingStats(bucket, t);
  }
  return finalizeBrLikeShortRollingStats(bucket);
}

async function getBrLikeShortEnvGate(nowMs = Date.now(), health = btcHealthCache.data) {
  const store = await readPumpPaperStore();
  const strictMinClosed = Number(process.env.EMA_SQUEEZE_BR_SHORT_ENV_STRICT_MIN_CLOSED ?? 20);
  const strictMaxPnl = Number(process.env.EMA_SQUEEZE_BR_SHORT_ENV_STRICT_MAX_PNL ?? -10);
  const strictMinLossCuts = Number(process.env.EMA_SQUEEZE_BR_SHORT_ENV_STRICT_MIN_LOSS_CUTS ?? 8);
  const strictMaxWr = Number(process.env.EMA_SQUEEZE_BR_SHORT_ENV_STRICT_MAX_WR ?? 45);
  const recoveryMinClosed = Number(process.env.EMA_SQUEEZE_BR_SHORT_RECOVERY_60M_MIN_CLOSED ?? 8);
  const recoveryMinWr = Number(process.env.EMA_SQUEEZE_BR_SHORT_RECOVERY_60M_MIN_WR ?? 70);
  const btcUpMinScore = Number(process.env.EMA_SQUEEZE_BR_SHORT_ENV_BTC_UP_MIN_SCORE ?? 55);
  const btcTrendDir = String(health?.btcTrendDir ?? '').toLowerCase();
  const btcTrendScore = Number(health?.btcTrendScore ?? 0);
  const btcUpStrong = btcTrendDir === 'up' && btcTrendScore >= btcUpMinScore;
  const rolling2h = getBrLikeShortRollingStatsFromStore(store, nowMs, 2 * 60 * 60 * 1000);
  const rolling60m = getBrLikeShortRollingStatsFromStore(store, nowMs, 60 * 60 * 1000);
  const strictReasons = [];
  if (rolling2h.closed >= strictMinClosed) {
    if (rolling2h.pnl <= strictMaxPnl) strictReasons.push(`2hPnL=${rolling2h.pnl}<=${strictMaxPnl}`);
    if (rolling2h.breadthLossCut >= strictMinLossCuts) strictReasons.push(`2hLossCut=${rolling2h.breadthLossCut}>=${strictMinLossCuts}`);
    if (rolling2h.wr < strictMaxWr) strictReasons.push(`2hWR=${rolling2h.wr}<${strictMaxWr}`);
  }
  const strict = rolling2h.closed >= strictMinClosed && strictReasons.length > 0;
  const recovery60m = rolling60m.closed >= recoveryMinClosed
    && (rolling60m.pnl > 0 || rolling60m.wr >= recoveryMinWr);
  const blockMarket = strict && btcUpStrong && !recovery60m;
  const label = blockMarket
    ? 'SHORT_ENV_BTC_UP_BAD_STRICT'
    : recovery60m
      ? 'SHORT_RECOVERY_60M'
      : strict
        ? 'SHORT_ENV_BAD_BUT_BTC_NOT_UP'
        : 'SHORT_ENV_OK';
  const btcReason = `btcTrend=${btcTrendDir || '-'} score=${Number.isFinite(btcTrendScore) ? btcTrendScore : '-'} minUp=${btcUpMinScore}`;
  return {
    blockMarket,
    label,
    reason: strict
      ? `${strictReasons.join(', ')}; ${btcReason}${recovery60m ? `; recovery60m PASS pnl=${rolling60m.pnl} wr=${rolling60m.wr}% closed=${rolling60m.closed}` : ''}${!btcUpStrong && !recovery60m ? '; BTC not strong-up => keep market/test' : ''}`
      : `2h ok closed=${rolling2h.closed} pnl=${rolling2h.pnl} wr=${rolling2h.wr}% lossCut=${rolling2h.breadthLossCut}; ${btcReason}`,
    strict,
    btcUpStrong,
    btcTrendDir,
    btcTrendScore: Number.isFinite(btcTrendScore) ? btcTrendScore : null,
    btcUpMinScore,
    recovery60m,
    rolling2h,
    rolling60m,
  };
}

function getBtcTrendSideForBrLikeCut(health = btcHealthCache.data) {
  const dir = String(health?.btcTrendDir ?? '').toLowerCase();
  if (dir === 'up') return { side: 'LONG', label: 'BTC_TREND_UP', reason: `btcTrendDir=up score=${health?.btcTrendScore ?? '-'}` };
  if (dir === 'down') return { side: 'SHORT', label: 'BTC_TREND_DOWN', reason: `btcTrendDir=down score=${health?.btcTrendScore ?? '-'}` };

  const pct6h = Number(health?.pct6h);
  const candle1h = Number(health?.btcCandle1hPct);
  const ema1h = String(health?.emaTrend1h ?? '').toLowerCase();
  if ((Number.isFinite(pct6h) && pct6h >= 0.7) || (Number.isFinite(candle1h) && candle1h >= 0.25) || ema1h === 'above') {
    return { side: 'LONG', label: 'BTC_DERIVED_UP', reason: `pct6h=${Number.isFinite(pct6h) ? pct6h : '-'} candle1h=${Number.isFinite(candle1h) ? candle1h : '-'} ema1h=${ema1h || '-'}` };
  }
  if ((Number.isFinite(pct6h) && pct6h <= -0.7) || (Number.isFinite(candle1h) && candle1h <= -0.25) || ema1h === 'below') {
    return { side: 'SHORT', label: 'BTC_DERIVED_DOWN', reason: `pct6h=${Number.isFinite(pct6h) ? pct6h : '-'} candle1h=${Number.isFinite(candle1h) ? candle1h : '-'} ema1h=${ema1h || '-'}` };
  }
  return { side: null, label: 'BTC_FLAT_MIXED', reason: `pct6h=${Number.isFinite(pct6h) ? pct6h : '-'} candle1h=${Number.isFinite(candle1h) ? candle1h : '-'} ema1h=${ema1h || '-'}` };
}

function getBrLikeBreadthLossCutPolicy(side) {
  const trend = getBtcTrendSideForBrLikeCut();
  const againstRoe = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ROE ?? -6);
  const mixedRoe = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_MIXED_ROE ?? -12);
  const alignedRoe = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ALIGNED_ROE ?? -20);
  const disableAligned = process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ALIGNED === 'false';
  const tradeSide = String(side ?? '').toUpperCase();
  if (trend.side && tradeSide === trend.side) {
    return {
      regime: 'ALIGNED',
      threshold: disableAligned ? null : alignedRoe,
      trend,
      reason: `aligned with ${trend.label}; ${trend.reason}`,
    };
  }
  if (trend.side && tradeSide !== trend.side) {
    return {
      regime: 'AGAINST',
      threshold: againstRoe,
      trend,
      reason: `against ${trend.label}; ${trend.reason}`,
    };
  }
  return {
    regime: 'MIXED',
    threshold: mixedRoe,
    trend,
    reason: `mixed BTC trend; ${trend.reason}`,
  };
}

function getEmaSqueezeRunnerBreadthLossCutPolicy(side) {
  const trend = getBtcTrendSideForBrLikeCut();
  const againstRoe = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_REVERSAL_LOSS_CUT_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ROE
    ?? -6);
  const mixedRoe = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_REVERSAL_LOSS_CUT_MIXED_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_MIXED_ROE
    ?? -12);
  const alignedRoe = Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_REVERSAL_LOSS_CUT_ALIGNED_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ALIGNED_ROE
    ?? -20);
  const disableAligned = process.env.EMA_SQUEEZE_PAPER_RUNNER_REVERSAL_LOSS_CUT_ALIGNED === 'false';
  const tradeSide = String(side ?? '').toUpperCase();
  if (trend.side && tradeSide === trend.side) {
    return {
      regime: 'ALIGNED',
      threshold: disableAligned ? null : alignedRoe,
      trend,
      reason: `runner aligned with ${trend.label}; ${trend.reason}`,
    };
  }
  if (trend.side && tradeSide !== trend.side) {
    return {
      regime: 'AGAINST',
      threshold: againstRoe,
      trend,
      reason: `runner against ${trend.label}; ${trend.reason}`,
    };
  }
  return {
    regime: 'MIXED',
    threshold: mixedRoe,
    trend,
    reason: `runner mixed BTC trend; ${trend.reason}`,
  };
}

function getEmaSqueezeBreakoutBreadthLossCutPolicy(side) {
  const trend = getBtcTrendSideForBrLikeCut();
  const againstRoe = Number(process.env.EMA_SQUEEZE_PAPER_BREAKOUT_REVERSAL_LOSS_CUT_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ROE
    ?? -6);
  const mixedRoe = Number(process.env.EMA_SQUEEZE_PAPER_BREAKOUT_REVERSAL_LOSS_CUT_MIXED_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_MIXED_ROE
    ?? -12);
  const alignedRoe = Number(process.env.EMA_SQUEEZE_PAPER_BREAKOUT_REVERSAL_LOSS_CUT_ALIGNED_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_REVERSAL_LOSS_CUT_ALIGNED_ROE
    ?? -20);
  const disableAligned = process.env.EMA_SQUEEZE_PAPER_BREAKOUT_REVERSAL_LOSS_CUT_ALIGNED === 'false';
  const tradeSide = String(side ?? '').toUpperCase();
  if (trend.side && tradeSide === trend.side) {
    return {
      regime: 'ALIGNED',
      threshold: disableAligned ? null : alignedRoe,
      trend,
      reason: `breakout aligned with ${trend.label}; ${trend.reason}`,
    };
  }
  if (trend.side && tradeSide !== trend.side) {
    return {
      regime: 'AGAINST',
      threshold: againstRoe,
      trend,
      reason: `breakout against ${trend.label}; ${trend.reason}`,
    };
  }
  return {
    regime: 'MIXED',
    threshold: mixedRoe,
    trend,
    reason: `breakout mixed BTC trend; ${trend.reason}`,
  };
}

function isEmaSqueezeBreakoutPaperTrade(t) {
  const source = String(t?.source ?? '').toLowerCase();
  return String(t?.status ?? '').toUpperCase() === 'OPEN'
    && source.startsWith('emasq-')
    && source.includes('-breakout')
    && !source.includes('br_like')
    && !source.includes('-runner');
}

function isEmaSqueezeRunnerPaperTrade(t) {
  const source = String(t?.source ?? '').toLowerCase();
  const note = String(t?.note ?? '').toLowerCase();
  return String(t?.status ?? '').toUpperCase() === 'OPEN'
    && String(t?.source ?? '').startsWith('emasq-')
    && !source.includes('br_like')
    && (source.includes('-runner') || note.includes('runner=y') || t?.runnerCandidate === true);
}

function getBtcLocalTurnSignalForBrLike(side) {
  const tradeSide = String(side ?? '').toUpperCase();
  const klines = getClosedCachedKlines('BTCUSDT', '5m', 80);
  if (!Array.isArray(klines) || klines.length < 30) return { hit: false, label: 'BTC_NO_DATA', reason: 'BTC 5m no data' };
  const last = klines.at(-1);
  const window = Math.max(12, Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_WINDOW ?? 24));
  const recent = klines.slice(-window);
  const open = klineNum(last, 'open', 1);
  const high = klineNum(last, 'high', 2);
  const low = klineNum(last, 'low', 3);
  const close = klineNum(last, 'close', 4);
  if (![open, high, low, close].every((v) => Number.isFinite(v) && v > 0)) {
    return { hit: false, label: 'BTC_INVALID', reason: 'BTC 5m invalid candle' };
  }
  const range = Math.max(1e-12, high - low);
  const closePos = (close - low) / range;
  const lowerShare = (Math.min(open, close) - low) / range;
  const upperShare = (high - Math.max(open, close)) / range;
  const closeFromLowPct = (close - low) / low * 100;
  const closeFromHighPct = (high - close) / high * 100;
  const greenPct = (close - open) / open * 100;
  const lowN = Math.min(...recent.map((k) => Number(k.low ?? k[3])).filter(Number.isFinite));
  const highN = Math.max(...recent.map((k) => Number(k.high ?? k[2])).filter(Number.isFinite));
  const lowTol = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_LOW_TOL_PCT ?? 0.08);
  const highTol = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_HIGH_TOL_PCT ?? 0.08);
  const localLow = Number.isFinite(lowN) && low <= lowN * (1 + lowTol / 100);
  const localHigh = Number.isFinite(highN) && high >= highN * (1 - highTol / 100);

  const minCloseFromLow = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_CLOSE_FROM_LOW_PCT ?? 0.08);
  const minGreen = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_GREEN_PCT ?? 0.10);
  const minLower = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_LOWER_SHARE ?? 0.45);
  const minBottomPos = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_CLOSE_POS ?? 0.50);
  const bottomBounce = localLow
    && (
      closeFromLowPct >= minCloseFromLow
      || greenPct >= minGreen
      || (lowerShare >= minLower && closePos >= minBottomPos)
    );

  const minCloseFromHigh = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_CLOSE_FROM_HIGH_PCT ?? 0.08);
  const minRed = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_RED_PCT ?? 0.10);
  const minUpper = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_UPPER_SHARE ?? 0.45);
  const maxTopPos = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_CLOSE_POS ?? 0.50);
  const topReject = localHigh
    && (
      closeFromHighPct >= minCloseFromHigh
      || greenPct <= -minRed
      || (upperShare >= minUpper && closePos <= maxTopPos)
    );

  const reason = `BTC5m localLow=${localLow} localHigh=${localHigh} cLow=${closeFromLowPct.toFixed(2)} cHigh=${closeFromHighPct.toFixed(2)} candle=${greenPct.toFixed(2)} lower=${lowerShare.toFixed(2)} upper=${upperShare.toFixed(2)} pos=${closePos.toFixed(2)}`;
  if (tradeSide === 'SHORT') return { hit: bottomBounce, label: bottomBounce ? 'BTC_BOTTOM_BOUNCE' : 'BTC_OK_FOR_SHORT', reason };
  if (tradeSide === 'LONG') return { hit: topReject, label: topReject ? 'BTC_TOP_REJECT' : 'BTC_OK_FOR_LONG', reason };
  return { hit: false, label: 'BTC_SIDE_UNKNOWN', reason };
}

function getBtcLocalTurnRiskLogForShakeout(side) {
  const tradeSide = String(side ?? '').toUpperCase();
  const klines = getClosedCachedKlines('BTCUSDT', '5m', 80);
  if (!Array.isArray(klines) || klines.length < 30) {
    return {
      label: 'BTC_NO_DATA',
      againstSide: false,
      bottomBounce: false,
      topReject: false,
      reason: 'BTC 5m no data',
    };
  }
  const last = klines.at(-1);
  const window = Math.max(12, Number(process.env.SHAKEOUT_RECLAIM_BTC_TURN_LOG_WINDOW ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_WINDOW ?? 24));
  const recent = klines.slice(-window);
  const open = klineNum(last, 'open', 1);
  const high = klineNum(last, 'high', 2);
  const low = klineNum(last, 'low', 3);
  const close = klineNum(last, 'close', 4);
  if (![open, high, low, close].every((v) => Number.isFinite(v) && v > 0)) {
    return {
      label: 'BTC_INVALID',
      againstSide: false,
      bottomBounce: false,
      topReject: false,
      reason: 'BTC 5m invalid candle',
    };
  }
  const range = Math.max(1e-12, high - low);
  const closePos = (close - low) / range;
  const lowerShare = (Math.min(open, close) - low) / range;
  const upperShare = (high - Math.max(open, close)) / range;
  const closeFromLowPct = (close - low) / low * 100;
  const closeFromHighPct = (high - close) / high * 100;
  const candlePct = (close - open) / open * 100;
  const lowN = Math.min(...recent.map((k) => Number(k.low ?? k[3])).filter(Number.isFinite));
  const highN = Math.max(...recent.map((k) => Number(k.high ?? k[2])).filter(Number.isFinite));
  const lowTol = Number(process.env.SHAKEOUT_RECLAIM_BTC_TURN_LOW_TOL_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_LOW_TOL_PCT ?? 0.08);
  const highTol = Number(process.env.SHAKEOUT_RECLAIM_BTC_TURN_HIGH_TOL_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TURN_HIGH_TOL_PCT ?? 0.08);
  const localLow = Number.isFinite(lowN) && low <= lowN * (1 + lowTol / 100);
  const localHigh = Number.isFinite(highN) && high >= highN * (1 - highTol / 100);

  const minCloseFromLow = Number(process.env.SHAKEOUT_RECLAIM_BTC_BOTTOM_CLOSE_FROM_LOW_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_CLOSE_FROM_LOW_PCT ?? 0.08);
  const minGreen = Number(process.env.SHAKEOUT_RECLAIM_BTC_BOTTOM_GREEN_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_GREEN_PCT ?? 0.10);
  const minLower = Number(process.env.SHAKEOUT_RECLAIM_BTC_BOTTOM_LOWER_SHARE ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_LOWER_SHARE ?? 0.45);
  const minBottomPos = Number(process.env.SHAKEOUT_RECLAIM_BTC_BOTTOM_CLOSE_POS ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_BOTTOM_CLOSE_POS ?? 0.50);
  const bottomBounce = localLow
    && (
      closeFromLowPct >= minCloseFromLow
      || candlePct >= minGreen
      || (lowerShare >= minLower && closePos >= minBottomPos)
    );

  const minCloseFromHigh = Number(process.env.SHAKEOUT_RECLAIM_BTC_TOP_CLOSE_FROM_HIGH_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_CLOSE_FROM_HIGH_PCT ?? 0.08);
  const minRed = Number(process.env.SHAKEOUT_RECLAIM_BTC_TOP_RED_PCT ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_RED_PCT ?? 0.10);
  const minUpper = Number(process.env.SHAKEOUT_RECLAIM_BTC_TOP_UPPER_SHARE ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_UPPER_SHARE ?? 0.45);
  const maxTopPos = Number(process.env.SHAKEOUT_RECLAIM_BTC_TOP_CLOSE_POS ?? process.env.EMA_SQUEEZE_BR_LIKE_BTC_TOP_CLOSE_POS ?? 0.50);
  const topReject = localHigh
    && (
      closeFromHighPct >= minCloseFromHigh
      || candlePct <= -minRed
      || (upperShare >= minUpper && closePos <= maxTopPos)
    );

  const againstSide = (tradeSide === 'SHORT' && bottomBounce)
    || (tradeSide === 'LONG' && topReject);
  const favorableSide = (tradeSide === 'LONG' && bottomBounce)
    || (tradeSide === 'SHORT' && topReject);
  const label = againstSide
    ? (tradeSide === 'SHORT' ? 'BTC_BOTTOM_BOUNCE_RISK_FOR_SHORT' : 'BTC_TOP_REJECT_RISK_FOR_LONG')
    : favorableSide
      ? (tradeSide === 'LONG' ? 'BTC_BOTTOM_BOUNCE_OK_FOR_LONG' : 'BTC_TOP_REJECT_OK_FOR_SHORT')
      : 'BTC_NO_LOCAL_TURN_RISK';
  const reason = `BTC5m localLow=${localLow} localHigh=${localHigh} cLow=${closeFromLowPct.toFixed(2)} cHigh=${closeFromHighPct.toFixed(2)} candle=${candlePct.toFixed(2)} lower=${lowerShare.toFixed(2)} upper=${upperShare.toFixed(2)} pos=${closePos.toFixed(2)} window=${window}`;
  return {
    label,
    againstSide,
    favorableSide,
    bottomBounce,
    topReject,
    localLow,
    localHigh,
    closeFromLowPct: +closeFromLowPct.toFixed(3),
    closeFromHighPct: +closeFromHighPct.toFixed(3),
    candlePct: +candlePct.toFixed(3),
    lowerShare: +lowerShare.toFixed(3),
    upperShare: +upperShare.toFixed(3),
    closePos: +closePos.toFixed(3),
    window,
    price: close,
    closeTime: last?.closeTime ?? last?.[6] ?? null,
    reason,
  };
}

async function getBrLikeOpenClusterStats(side) {
  const tradeSide = String(side ?? '').toUpperCase();
  const store = await readPumpPaperStore();
  const trades = getPumpPaperActiveIndex(store).ema.filter((t) =>
    t.status === 'OPEN'
    && t.side === tradeSide
    && isEmaSqueezeBrRulesMarketSourceForSide(t.source, tradeSide, t.note));
  let pnl = 0;
  let losers = 0;
  let fastLosers = 0;
  let marked = 0;
  const now = Date.now();
  for (const t of trades) {
    const mark = emaSqueezeSocketMarks.get(t.symbol) ?? sharedLastTicker.getPrice?.(t.symbol) ?? getSnapshotMarkPrice(t.symbol);
    const m = Number(mark);
    if (!Number.isFinite(m) || m <= 0) continue;
    const sideMult = tradeSide === 'LONG' ? 1 : -1;
    const rowPnl = (m - Number(t.entryPrice)) * Number(t.quantity) * sideMult;
    const rowRoe = Number(t.marginUsdt) > 0 ? rowPnl / Number(t.marginUsdt) * 100 : 0;
    pnl += rowPnl;
    marked++;
    if (rowPnl < 0) losers++;
    const ageMs = now - Date.parse(t.openedAt ?? t.createdAt ?? '');
    if (rowRoe <= Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_CLUSTER_FAST_LOSS_ROE ?? -2)
        && Number.isFinite(ageMs)
        && ageMs <= Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_CLUSTER_FAST_WINDOW_MS ?? 30 * 60_000)) {
      fastLosers++;
    }
  }
  return {
    open: trades.length,
    marked,
    pnl: +pnl.toFixed(3),
    losers,
    fastLosers,
  };
}

