let posMonitor = null;
const ORDERS_POSITION_PNL_STREAM_VERSION = 'ORDERS_POSITION_PNL_STREAM_V2_20260809_LIVE_CARD';
const ordersPositionPnlClients = new Set();

function binancePositionDisplayMargin(pos = {}) {
  const reported = Number(pos.positionInitialMargin ?? pos.initialMargin);
  if (reported > 0) return reported;
  const amount = Math.abs(Number(pos.amt ?? pos.positionAmt) || 0);
  const entry = Number(pos.entry ?? pos.entryPrice) || 0;
  const leverage = Math.max(1, Number(pos.leverage) || 1);
  return amount * entry / leverage;
}

function binancePositionPnlPayload(symbol, pos = {}, markPrice = null, managementRoe = null) {
  const amount = Number(pos.amt ?? pos.positionAmt) || 0;
  const entry = Number(pos.entry ?? pos.entryPrice) || 0;
  const leverage = Math.max(1, Number(pos.leverage) || 1);
  const mark = Number(markPrice ?? pos.markPrice) || 0;
  const unrealizedPnl = Number.isFinite(Number(pos.unRealizedProfit))
    ? Number(pos.unRealizedProfit)
    : (mark - entry) * amount;
  const positionInitialMargin = binancePositionDisplayMargin({
    ...pos,
    amt: amount,
    entry,
    leverage,
  });
  const binanceRoe = positionInitialMargin > 0
    ? unrealizedPnl / positionInitialMargin * 100
    : 0;
  return {
    version: ORDERS_POSITION_PNL_STREAM_VERSION,
    symbol: String(symbol ?? pos.symbol ?? '').toUpperCase(),
    positionAmt: String(amount),
    entryPrice: String(entry),
    markPrice: String(mark),
    marketReady: mark > 0,
    leverage: String(leverage),
    positionInitialMargin: String(positionInitialMargin || 0),
    unRealizedProfit: String(unrealizedPnl),
    roe: binanceRoe,
    managementRoe: Number.isFinite(Number(managementRoe)) ? Number(managementRoe) : binanceRoe,
    positionSide: pos.positionSide ?? 'BOTH',
    eventAt: Date.now(),
  };
}

function writeOrdersPositionPnlEvent(response, event, payload) {
  try {
    response.write(`event: ${event}\ndata: ${JSON.stringify(payload)}\n\n`);
    return true;
  } catch {
    ordersPositionPnlClients.delete(response);
    return false;
  }
}

function broadcastOrdersPositionPnl(event, payload) {
  for (const response of ordersPositionPnlClients) {
    writeOrdersPositionPnlEvent(response, event, payload);
  }
}

function openOrdersPositionPnlStream(request, response) {
  response.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  response.socket?.setTimeout?.(0);
  ordersPositionPnlClients.add(response);
  writeOrdersPositionPnlEvent(response, 'ready', {
    version: ORDERS_POSITION_PNL_STREAM_VERSION,
    source: 'BINANCE_USER_DATA_PLUS_MARK_PRICE_SOCKET',
    connectedAt: Date.now(),
  });
  const current = posMonitor?.getActivePositions?.() ?? [];
  writeOrdersPositionPnlEvent(response, 'snapshot', {
    version: ORDERS_POSITION_PNL_STREAM_VERSION,
    positions: current.map((position) => binancePositionPnlPayload(
      position.symbol,
      position,
      position.markPrice,
      null,
    )),
    eventAt: Date.now(),
  });
  const heartbeat = setInterval(() => {
    writeOrdersPositionPnlEvent(response, 'heartbeat', { at: Date.now() });
  }, 15_000);
  heartbeat.unref?.();
  request.on('close', () => {
    clearInterval(heartbeat);
    ordersPositionPnlClients.delete(response);
  });
}
// Legacy signal-based TSL exclusions. These must not suppress the newer non-V2
// Binance profit-lock: a manually opened position can share a symbol with one
// of these observation signals and still needs its live SL protected.
const tslExcludedSymbols = new Set();
const ORDERS_CAP_TSL_STATE_VERSION = 'ORDERS_CAP_TSL_STATE_V1_DURABLE_20260815';
const ORDERS_CAP_TSL_FILE = join(rootDir, 'data', 'orders-cap-tsl.json');
const ordersCapTslSymbols = new Set();
let ordersCapTslWriteLock = Promise.resolve();

async function loadOrdersCapTslSymbols() {
  try {
    const parsed = JSON.parse(await readFile(ORDERS_CAP_TSL_FILE, 'utf8'));
    const rows = Array.isArray(parsed) ? parsed : parsed?.symbols;
    ordersCapTslSymbols.clear();
    for (const value of Array.isArray(rows) ? rows : []) {
      const symbol = String(value ?? '').toUpperCase().trim();
      if (symbol) ordersCapTslSymbols.add(symbol);
    }
    console.log(`[CapTSL] loaded ${ordersCapTslSymbols.size} symbol(s); ${ORDERS_CAP_TSL_STATE_VERSION}`);
  } catch (error) {
    if (error?.code !== 'ENOENT') console.warn(`[CapTSL] state load failed: ${error.message}`);
    ordersCapTslSymbols.clear();
  }
}

async function saveOrdersCapTslSymbols() {
  const payload = {
    version: ORDERS_CAP_TSL_STATE_VERSION,
    updatedAt: new Date().toISOString(),
    symbols: [...ordersCapTslSymbols].sort(),
  };
  ordersCapTslWriteLock = ordersCapTslWriteLock
    .catch(() => {})
    .then(async () => {
      await mkdir(join(rootDir, 'data'), { recursive: true });
      const tmp = `${ORDERS_CAP_TSL_FILE}.tmp`;
      await writeFile(tmp, JSON.stringify(payload, null, 2), 'utf8');
      await rename(tmp, ORDERS_CAP_TSL_FILE);
    });
  await ordersCapTslWriteLock;
  return payload;
}

function isCapTslSymbol(symbol) {
  return ordersCapTslSymbols.has(String(symbol ?? '').toUpperCase().trim());
}

function shouldMoveSymbolNegativeTpToEntry(symbol, roe, thresholdRoe = negativeTpRoeThreshold()) {
  return shouldMoveNegativeTpToEntry({
    roe,
    thresholdRoe,
    capTsl: isCapTslSymbol(symbol),
  });
}

const orderFillDiscordSent = new Map();
const liveCardOrderFailureDiscordSent = new Map();

function sendLiveCardOrderFailureDiscord({
  page,
  trade,
  matchedKeys = [],
  error,
  stage = 'BINANCE_ENTRY',
}) {
  const webhookUrl = process.env.LIVE_CARD_ORDER_WEBHOOK_URL
    || process.env.ORDER_FILL_WEBHOOK_URL
    || '';
  if (!webhookUrl || !Array.isArray(matchedKeys) || matchedKeys.length === 0) return;

  const symbol = normalizeSymbol(trade?.symbol ?? '') || '-';
  const side = String(trade?.side ?? '-').toUpperCase();
  const tradeId = String(trade?.id ?? '-');
  const errorCode = String(error?.code ?? error?.name ?? 'ERROR');
  const errorMessage = String(error?.message ?? error ?? 'Unknown Binance error').slice(0, 950);
  const dedupeKey = `${page}:${tradeId}:${stage}:${errorCode}:${errorMessage}`;
  const previous = Number(liveCardOrderFailureDiscordSent.get(dedupeKey) ?? 0);
  if (previous > 0 && Date.now() - previous < 30 * 60_000) return;
  liveCardOrderFailureDiscordSent.set(dedupeKey, Date.now());
  if (liveCardOrderFailureDiscordSent.size > 2_000) {
    const cutoff = Date.now() - 30 * 60_000;
    for (const [key, at] of liveCardOrderFailureDiscordSent) {
      if (at < cutoff) liveCardOrderFailureDiscordSent.delete(key);
    }
  }

  const gate = binanceRateGate.snapshot();
  const authCircuitText = Array.isArray(gate.authBlocks) && gate.authBlocks.length
    ? gate.authBlocks.slice(0, 3).map((block) => {
      const probeSec = Math.max(0, Math.ceil((Number(block.nextProbeAt ?? 0) - Date.now()) / 1000));
      return `${block.scope ?? 'legacy'} · ${block.source ?? 'unknown'} · ${block.method ?? 'GET'} ${block.path ?? '-'} · probe ${probeSec}s`;
    }).join('\n')
    : 'none';
  const cards = matchedKeys.map((key) => String(key)).join('\n').slice(0, 950) || '-';
  const source = String(
    trade?.source
      ?? trade?.recommendationCombo
      ?? trade?.signalType
      ?? trade?.setup
      ?? '-',
  ).slice(0, 500);
  const embed = {
    title: `[BINANCE FAIL] ${symbol} ${side}`,
    color: 0xef4444,
    fields: [
      { name: 'Page / Stage', value: `${String(page ?? '-')} / ${stage}`.slice(0, 1024), inline: true },
      { name: 'Trade ID', value: tradeId.slice(0, 1024), inline: true },
      { name: 'Signal Source', value: source || '-', inline: false },
      { name: 'Matched real card', value: cards, inline: false },
      { name: 'Error', value: `${errorCode}: ${errorMessage}`.slice(0, 1024), inline: false },
      {
        name: 'REST gate',
        value: `queue ${gate.queue}/${gate.maxQueue} · active ${gate.active}/${gate.concurrency} · tokens ${gate.tokens}/${gate.limitPerMin} · congested ${gate.congested ? 'YES' : 'NO'}`,
        inline: false,
      },
      { name: 'Auth circuit', value: authCircuitText.slice(0, 1024), inline: false },
    ],
    timestamp: new Date().toISOString(),
  };

  fetch(webhookUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ embeds: [embed] }),
    signal: AbortSignal.timeout(10_000),
  })
    .then((res) => {
      if (!res.ok) {
        liveCardOrderFailureDiscordSent.delete(dedupeKey);
        console.warn(`[LiveCardFailDiscord] ${symbol} failed: ${res.status}`);
      } else {
        console.log(`[LiveCardFailDiscord] sent ${symbol} ${side} stage=${stage}`);
      }
    })
    .catch((notifyError) => {
      liveCardOrderFailureDiscordSent.delete(dedupeKey);
      console.warn(`[LiveCardFailDiscord] ${symbol}:`, notifyError.message);
    });
}

function sendOrderFillDiscord({
  symbol,
  side,
  filledQty,
  cumulativeFilledQty,
  avgPrice,
  positionSide,
  fillTime,
  source,
  orderStatus,
  orderId,
  clientOrderId,
  signalSource,
  executionPage,
  lifecycleId,
  matchedKeys,
  signalCombo,
  signalLabel,
  marginUsdt,
  leverage,
}) {
  const webhookUrl = process.env.ORDER_FILL_WEBHOOK_URL || '';
  if (!webhookUrl || !['ORDER_TRADE_UPDATE', 'TRADE_LITE_VERIFIED'].includes(source) || orderStatus !== 'FILLED') return;

  const dedupeKey = String(orderId ?? clientOrderId ?? `${symbol}:${side}:${fillTime}`);
  const previous = Number(orderFillDiscordSent.get(dedupeKey) ?? 0);
  if (previous > 0 && Date.now() - previous < 24 * 60 * 60_000) return;
  orderFillDiscordSent.set(dedupeKey, Date.now());
  if (orderFillDiscordSent.size > 2_000) {
    const cutoff = Date.now() - 24 * 60 * 60_000;
    for (const [key, at] of orderFillDiscordSent) {
      if (at < cutoff) orderFillDiscordSent.delete(key);
    }
  }

  const price = Number(avgPrice);
  const fullQty = Number(cumulativeFilledQty);
  const qty = Number.isFinite(fullQty) && fullQty > 0 ? fullQty : Number(filledQty);
  const isBuy = String(side).toUpperCase() === 'BUY';
  const whitelistText = (Array.isArray(matchedKeys) ? matchedKeys : [])
    .map((key) => String(key ?? '').trim())
    .filter(Boolean)
    .join('\n') || '-';
  const comboText = String(signalCombo ?? signalLabel ?? '-').trim() || '-';
  const embed = {
    title: `[BINANCE FILL] ${symbol} ${isBuy ? 'LONG/BUY' : 'SHORT/SELL'}`,
    color: isBuy ? 0x22c55e : 0xef4444,
    fields: [
      { name: 'Side', value: String(side ?? '-'), inline: true },
      { name: 'Qty', value: Number.isFinite(qty) ? String(qty) : String(filledQty ?? '-'), inline: true },
      { name: 'Avg Fill', value: Number.isFinite(price) ? String(price) : String(avgPrice ?? '-'), inline: true },
      { name: 'Position Side', value: String(positionSide ?? 'BOTH'), inline: true },
      { name: 'Execution Page', value: String(executionPage ?? '-').toUpperCase(), inline: true },
      { name: 'Raw Signal ID', value: String(signalSource ?? 'BINANCE/MANUAL'), inline: true },
      ...(Number.isFinite(Number(marginUsdt)) && Number(marginUsdt) > 0
        ? [{ name: 'Margin / Leverage', value: `$${Number(marginUsdt)} / ${Number(leverage) || 1}x`, inline: true }]
        : []),
      { name: 'Matched Whitelist (exact)', value: whitelistText.slice(0, 1024), inline: false },
      { name: 'Combo / Signal at Entry', value: comboText.slice(0, 1024), inline: false },
      ...(lifecycleId ? [{ name: 'Lifecycle', value: String(lifecycleId).slice(0, 1024), inline: false }] : []),
      { name: 'Order', value: String(orderId ?? clientOrderId ?? '-'), inline: true },
      { name: 'Time', value: fillTime ? new Date(Number(fillTime)).toISOString() : new Date().toISOString(), inline: false },
    ],
    timestamp: new Date().toISOString(),
  };

  fetch(webhookUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ embeds: [embed] }),
  })
    .then((res) => {
      if (!res.ok) {
        orderFillDiscordSent.delete(dedupeKey);
        console.warn(`[OrderFillDiscord] ${symbol} failed: ${res.status}`);
      } else {
        console.log(`[OrderFillDiscord] sent ${symbol} ${side} qty=${qty}`);
      }
    })
    .catch((err) => {
      orderFillDiscordSent.delete(dedupeKey);
      console.warn(`[OrderFillDiscord] ${symbol}:`, err.message);
    });
}

function startPositionSocketMonitor() {
  if (posMonitor) return posMonitor;
  posMonitor = startPositionMonitor({
    client,
    getCredentials: () => getApiCredentials(null),
    onPositionClose: (symbol) => {
      handleConfirmedPositionClose(symbol).catch((error) => {
        console.warn(`[PosMonitor] close confirmation ${symbol}:`, error.message);
      });
    },
    onFullFillObserved: async (_symbol, fill) => {
      await rememberHandledProtectionFill(fill);
    },
    onUserDataReconnect: async ({ reason, reconnected }) => {
      if (!reconnected) return;
      await runMissedFillProtectionRecovery(`USER_DATA_RECONNECT:${reason}`);
    },
    onOrderFill: async (symbol, {
      side,
      filledQty,
      cumulativeFilledQty = null,
      avgPrice,
      positionSide,
      fillTime,
      orderStatus = null,
      orderId = null,
      clientOrderId = null,
      orderType = null,
      source = 'UNKNOWN',
      positionEntryPrice = null,
      positionLeverage = null,
      positionAmount = null,
    }) => {
      const socketFullFill = [
        'ORDER_TRADE_UPDATE',
        'TRADE_LITE_VERIFIED',
        'MISSED_FILL_RECOVERY',
        'MISSED_FILL_RECONNECT_RECOVERY',
      ].includes(source)
        && orderStatus === 'FILLED';
      if (!socketFullFill) {
        console.warn(`[Protection] ${symbol} ignored source=${source} status=${orderStatus ?? '-'}; ${POSITION_PROTECTION_TRIGGER_VERSION}`);
        return;
      }
      const sameSideDcaFill = isBinanceSameSideDcaFill({
        side,
        positionSide,
        filledQty,
        cumulativeFilledQty,
        positionAmount,
      });
      // A genuinely new position starts a new protection lifecycle. A DCA fill
      // must retain the original position's TP/SL and profit-lock state.
      if (!sameSideDcaFill) resetBinanceProfitLockRuntime(symbol, 'SOCKET_FULL_FILL');
      const recoveredMissedFill = source === 'MISSED_FILL_RECOVERY';
      const reconnectRecoveredFill = source === 'MISSED_FILL_RECONNECT_RECOVERY';
      console.log(`[SlGuard] onOrderFill ${symbol} source=${source} fillTime=${fillTime} createdAt=${slTracking.createdAt}`);
      const lifecycleExecution = socketFullFill && (!recoveredMissedFill || reconnectRecoveredFill)
        ? await liveCardBinanceLifecycle.recordFill({
          symbol,
          side,
          filledQty,
          cumulativeFilledQty,
          avgPrice,
          positionSide,
          fillTime,
          orderStatus,
          orderId,
          clientOrderId,
          orderType,
        }).catch((error) => {
          console.warn(`[LiveCardLifecycle] fill ${symbol}:`, error.message);
          return null;
        })
        : null;
      if (sameSideDcaFill) {
        const pendingPlan = signalProtectionPlans.get(symbol);
        const pendingPlanMatchesDcaOrder = pendingPlan && (
          (pendingPlan.orderId != null && orderId != null && String(pendingPlan.orderId) === String(orderId))
          || (pendingPlan.entryClientOrderId && clientOrderId && pendingPlan.entryClientOrderId === clientOrderId)
        );
        if (pendingPlanMatchesDcaOrder) signalProtectionPlans.delete(symbol);
        const manualFlowTrade = liquidFlowV2Paper.state.trades.find((row) => {
          if (normalizeSymbol(row.symbol) !== normalizeSymbol(symbol)) return false;
          if (!String(row.binanceEntryMode ?? '').startsWith('MANUAL_')) return false;
          if (!['OPEN', 'PENDING_ENTRY'].includes(String(row.status))) return false;
          return (row.binanceOrderId != null && orderId != null && String(row.binanceOrderId) === String(orderId))
            || (row.binanceClientOrderId && clientOrderId && row.binanceClientOrderId === clientOrderId);
        });
        if (manualFlowTrade) {
          liquidFlowV2Paper.recordBinanceEntryResult(manualFlowTrade.id, {
            binanceEntryState: 'FILLED',
            binanceEntryFilledAt: Number(fillTime) || Date.now(),
            binanceEntryPrice: Number(avgPrice) || manualFlowTrade.binanceEntryPrice,
            binanceOrderStatus: orderStatus ?? 'FILLED',
            binanceDcaProtectionSuppressed: true,
            binanceDcaProtectionPolicyVersion: BINANCE_DCA_KEEP_PROTECTION_VERSION,
          }).catch(() => {});
        }
        if (lifecycleExecution?.lifecycleId) {
          await liveCardBinanceLifecycle.upsert({
            lifecycleId: lifecycleExecution.lifecycleId,
            dcaProtectionSuppressed: true,
            dcaProtectionPolicyVersion: BINANCE_DCA_KEEP_PROTECTION_VERSION,
          }, 'DCA_KEEP_EXISTING_PROTECTION', {
            symbol,
            orderId,
            clientOrderId,
            positionAmount,
            cumulativeFilledQty,
          }).catch(() => {});
        }
        console.log(
          `[DcaProtection] ${symbol} full fill orderId=${orderId ?? '-'} position=${positionAmount}`
          + ` orderQty=${cumulativeFilledQty ?? filledQty}; giữ nguyên TP/SL vị thế cũ;`
          + ` ${BINANCE_DCA_KEEP_PROTECTION_VERSION}`,
        );
        sendOrderFillDiscord({
          symbol,
          side,
          filledQty,
          cumulativeFilledQty,
          avgPrice,
          positionSide,
          fillTime,
          source,
          orderStatus,
          orderId,
          clientOrderId,
          signalSource: lifecycleExecution?.signalSource ?? 'dca-keep-existing-protection',
          executionPage: lifecycleExecution?.executionPage ?? null,
          lifecycleId: lifecycleExecution?.lifecycleId ?? null,
          matchedKeys: lifecycleExecution?.matchedKeys ?? [],
          signalCombo: lifecycleExecution?.signalCombo ?? null,
          signalLabel: lifecycleExecution?.signalLabel ?? null,
          marginUsdt: lifecycleExecution?.marginUsdt ?? null,
          leverage: lifecycleExecution?.leverage ?? null,
        });
        appendFillLog({ symbol, side, filledQty, avgPrice, positionSide, fillTime }).catch(() => {});
        invalidateOpenOrdersCache();
        return {
          protectionComplete: true,
          protectionSuppressedForDca: true,
          dcaProtectionPolicyVersion: BINANCE_DCA_KEEP_PROTECTION_VERSION,
        };
      }
      let protectionPlan = socketFullFill && (!recoveredMissedFill || reconnectRecoveredFill)
        ? signalProtectionPlans.get(symbol)
        : null;
      const matchesPlan = protectionPlan && (
        (protectionPlan.orderId != null && orderId != null && String(protectionPlan.orderId) === String(orderId))
        || (protectionPlan.entryClientOrderId && clientOrderId && protectionPlan.entryClientOrderId === clientOrderId)
      );
      if (protectionPlan && !matchesPlan) protectionPlan = null;
      if (!protectionPlan && lifecycleExecution) {
        rememberSignalProtectionPlan({
          symbol,
          side,
          takeProfitPrice: lifecycleExecution.takeProfitPrice,
          stopLossPrice: lifecycleExecution.stopLossPrice,
          signalEntryPrice: lifecycleExecution.signalEntryPrice,
          signalTakeProfitPrice: lifecycleExecution.signalTakeProfitPrice ?? lifecycleExecution.takeProfitPrice,
          signalStopLossPrice: lifecycleExecution.signalStopLossPrice ?? lifecycleExecution.stopLossPrice,
          fillAnchorEnabled: lifecycleExecution.fillAnchorEnabled,
          fillAnchorVersion: lifecycleExecution.fillAnchorVersion,
          takeProfitDistanceFraction: lifecycleExecution.takeProfitDistanceFraction,
          stopLossDistanceFraction: lifecycleExecution.stopLossDistanceFraction,
          fillPrice: lifecycleExecution.fillPrice ?? avgPrice,
          source: `live-card-whitelist-${lifecycleExecution.executionPage ?? 'unknown'}`,
          orderId: lifecycleExecution.entryOrderId,
          entryClientOrderId: lifecycleExecution.entryClientOrderId,
          lifecycleId: lifecycleExecution.lifecycleId,
          preserveSignalProtection: lifecycleExecution.preserveSignalProtection !== false,
          takeProfitWorkingType: lifecycleExecution.takeProfitWorkingType,
          stopLossWorkingType: lifecycleExecution.stopLossWorkingType,
        });
        protectionPlan = signalProtectionPlans.get(symbol) ?? null;
      }
      if (!protectionPlan) {
        const manualFlowTrade = liquidFlowV2Paper.state.trades.find((row) => {
          if (normalizeSymbol(row.symbol) !== normalizeSymbol(symbol)) return false;
          if (!String(row.binanceEntryMode ?? '').startsWith('MANUAL_')) return false;
          if (!['OPEN', 'PENDING_ENTRY'].includes(String(row.status))) return false;
          if (socketFullFill) {
            return (row.binanceOrderId != null && orderId != null && String(row.binanceOrderId) === String(orderId))
              || (row.binanceClientOrderId && clientOrderId && row.binanceClientOrderId === clientOrderId);
          }
          return false;
        });
        if (manualFlowTrade) {
          rememberSignalProtectionPlan({
            symbol,
            side: manualFlowTrade.side,
            takeProfitPrice: manualFlowTrade.binanceProtectionSignalTakeProfitPrice ?? manualFlowTrade.takeProfit,
            stopLossPrice: manualFlowTrade.binanceProtectionSignalStopLossPrice ?? manualFlowTrade.stopLoss,
            signalEntryPrice: manualFlowTrade.binanceProtectionSignalEntryPrice ?? manualFlowTrade.entryPrice,
            signalTakeProfitPrice: manualFlowTrade.binanceProtectionSignalTakeProfitPrice ?? manualFlowTrade.takeProfit,
            signalStopLossPrice: manualFlowTrade.binanceProtectionSignalStopLossPrice ?? manualFlowTrade.stopLoss,
            fillAnchorEnabled: true,
            fillAnchorVersion: LIVE_CARD_FILL_ANCHORED_PROTECTION_VERSION,
            takeProfitDistanceFraction: manualFlowTrade.binanceTakeProfitDistanceFraction,
            stopLossDistanceFraction: manualFlowTrade.binanceStopLossDistanceFraction,
            fillPrice: Number(avgPrice) || manualFlowTrade.binanceEntryPrice,
            source: 'liquid-flow-v2-manual',
            orderId: manualFlowTrade.binanceOrderId,
            entryClientOrderId: manualFlowTrade.binanceClientOrderId,
            preserveSignalProtection: true,
          });
          protectionPlan = signalProtectionPlans.get(symbol) ?? null;
          liquidFlowV2Paper.recordBinanceEntryResult(manualFlowTrade.id, {
            binanceEntryState: 'FILLED',
            binanceEntryFilledAt: Number(fillTime) || Date.now(),
            binanceEntryPrice: Number(avgPrice) || manualFlowTrade.binanceEntryPrice,
            binanceOrderStatus: orderStatus ?? 'FILLED',
          }).catch(() => {});
          console.log(`[LiquidFlowV2Manual] ${symbol} recovered protection plan from paper trade ${manualFlowTrade.id}`);
        }
      }
      if (recoveredMissedFill && !reconnectRecoveredFill) {
        protectionPlan = null;
      }
      if (!protectionPlan) {
        const manualEntry = Number(positionEntryPrice) || Number(avgPrice);
        const manualLeverage = Number(positionLeverage);
        const manualProtection = resolveManualSocketProtection({
          side,
          entryPrice: manualEntry,
          leverage: manualLeverage,
          stopLossRoePct: Number(process.env.AUTO_SL_ROE ?? 25),
          stopLossEnabled: process.env.AUTO_SL_ENABLED !== 'false',
        });
        if (manualProtection?.applied) {
          const manualStopLossPrice = manualProtection.stopLossPrice;
          rememberSignalProtectionPlan({
            symbol,
            side,
            takeProfitPrice: manualProtection.takeProfitPrice,
            stopLossPrice: manualStopLossPrice,
            signalEntryPrice: manualEntry,
            signalTakeProfitPrice: manualProtection.takeProfitPrice,
            signalStopLossPrice: manualStopLossPrice,
            fillPrice: manualEntry,
            source: BINANCE_MANUAL_SOCKET_SOURCE,
            orderId,
            entryClientOrderId: clientOrderId,
            preserveSignalProtection: false,
            takeProfitWorkingType: 'MARK_PRICE',
            stopLossWorkingType: 'MARK_PRICE',
          });
          protectionPlan = signalProtectionPlans.get(symbol) ?? null;
          console.log(
            `[ManualProtection] ${symbol} socket fill -> TP +${manualProtection.roePct}% ROE`
            + ` @ ${manualProtection.takeProfitPrice}; SL ${manualStopLossPrice ?? '-'};`
            + ` positionEntry=${manualEntry} lev=${manualLeverage}x amount=${positionAmount ?? '-'}`
            + ` version=${manualProtection.version}`,
          );
        }
      }
      if (protectionPlan) {
        protectionPlan.createdAt = Date.now();
        if (Number(avgPrice) > 0) protectionPlan.fillPrice = Number(avgPrice);
      }
      const trackedEntry = Number(slTracking.positions?.[symbol]?.entry);
      const currentEntry = Number(positionEntryPrice) || Number(avgPrice) || null;
      const trackingMatchesCurrentLifecycle = slTracking.positions?.[symbol]
        && trackedEntry > 0
        && currentEntry > 0
        && Math.abs(trackedEntry - currentEntry) / currentEntry <= 0.001
        && String(slTracking.positions[symbol].entryOrderId ?? '') === String(orderId ?? '');
      if (!trackingMatchesCurrentLifecycle) {
        slTracking.positions[symbol] = {
          openedAt: fillTime,
          openedAtStr: new Date(fillTime).toISOString(),
          entry: currentEntry,
          entryOrderId: orderId == null ? null : String(orderId),
          entryClientOrderId: clientOrderId ?? null,
          protectionTriggerVersion: POSITION_PROTECTION_TRIGGER_VERSION,
          slPlaced: false,
          signalTp: protectionPlan?.tpPrice ?? null,
          signalSl: protectionPlan?.slPrice ?? null,
          signalEntryPrice: protectionPlan?.signalEntryPrice ?? null,
          signalTakeProfitPrice: protectionPlan?.signalTakeProfitPrice ?? null,
          signalStopLossPrice: protectionPlan?.signalStopLossPrice ?? null,
          fillAnchorVersion: protectionPlan?.fillAnchorVersion ?? null,
          fillAnchorEnabled: protectionPlan?.fillAnchorEnabled === true,
          protectionFillPrice: currentEntry || protectionPlan?.fillPrice || null,
          signalSource: protectionPlan?.source ?? null,
          lifecycleId: protectionPlan?.lifecycleId ?? null,
          signalProtectionVersion: protectionPlan?.preserveSignalProtection
            ? LIVE_CARD_SIGNAL_PROTECTION_VERSION
            : null,
          preserveSignalProtection: protectionPlan?.preserveSignalProtection === true,
          takeProfitWorkingType: protectionPlan?.takeProfitWorkingType ?? null,
          stopLossWorkingType: protectionPlan?.stopLossWorkingType ?? null,
        };
        saveSlTracking();
      }
      if (protectionPlan) {
        if (!protectionPlan.appliedAt) {
          console.log(`[SignalProtection] ${symbol} full fill orderId=${orderId ?? protectionPlan.orderId ?? '-'}; applying signal TP/SL`);
          await new Promise((resolve) => setTimeout(resolve, 800));
          await applySignalProtectionOnFill(symbol);
        } else if (protectionPlan.appliedAt) {
          console.log(`[SignalProtection] ${symbol} already applied; ignore duplicate entry fill update`);
        }
      } else {
        console.log(`[SlGuard] Registered ${symbol} from socket full fill; triggering one-shot fallback SL/TP`);
        await new Promise((resolve) => setTimeout(resolve, 1000));
        await triggerSlGuardForSymbol(symbol);
      }
      sendOrderFillDiscord({
        symbol,
        side,
        filledQty,
        cumulativeFilledQty,
        avgPrice,
        positionSide,
        fillTime,
        source,
        orderStatus,
        orderId,
        clientOrderId,
        signalSource: lifecycleExecution?.signalSource ?? protectionPlan?.source ?? null,
        executionPage: lifecycleExecution?.executionPage ?? null,
        lifecycleId: lifecycleExecution?.lifecycleId ?? null,
        matchedKeys: lifecycleExecution?.matchedKeys ?? [],
        signalCombo: lifecycleExecution?.signalCombo ?? null,
        signalLabel: lifecycleExecution?.signalLabel ?? null,
        marginUsdt: lifecycleExecution?.marginUsdt ?? null,
        leverage: lifecycleExecution?.leverage ?? null,
      });
      if (lifecycleExecution?.lifecycleId) {
        broadcastOrdersPositionPnl('live-card-lifecycle', {
          version: ORDERS_POSITION_PNL_STREAM_VERSION,
          lifecycleId: lifecycleExecution.lifecycleId,
          symbol,
          status: lifecycleExecution.status,
          eventAt: Date.now(),
        });
      }
      appendFillLog({ symbol, side, filledQty, avgPrice, positionSide, fillTime }).catch(() => {});
      invalidateOpenOrdersCache();
      tpConfirmedClear(symbol);
      negTpLastRun.delete(symbol);
      twelveHourTpLastRun.delete(symbol);
      twelveHourTpMoved.delete(symbol);
      if (!protectionPlan && socketFullFill && process.env.AUTO_TP_ON_FILL_ENABLED !== 'false') {
        const delayMs = Math.max(500, Number(process.env.AUTO_TP_ON_FILL_DELAY_MS ?? 2500));
        await new Promise((resolve) => setTimeout(resolve, delayMs));
        await refreshTakeProfitForSymbol(symbol);
      }
      const [verifyRegular, verifyAlgoResult] = await Promise.all([
        client.getOpenOrders({
          symbol,
          ...getApiCredentials(null),
          priority: 0,
          dropOnCongestion: false,
          source: 'socket-fill:verify-regular',
        }),
        client.getOpenAlgoOrders({
          symbol,
          ...getApiCredentials(null),
          priority: 0,
          dropOnCongestion: false,
          source: 'socket-fill:verify-algo',
        }),
      ]);
      const verifyAlgo = Array.isArray(verifyAlgoResult?.orders)
        ? verifyAlgoResult.orders
        : Array.isArray(verifyAlgoResult) ? verifyAlgoResult : [];
      const closeSide = Number(positionAmount) > 0 ? 'SELL' : 'BUY';
      const protectionSpec = { symbol, closeSide, positionSide: positionSide ?? 'BOTH' };
      const expectsTp = Number(protectionPlan?.tpPrice) > 0;
      const expectsSl = Number(protectionPlan?.slPrice) > 0;
      const hasTp = hasOpenProtectionOrder(verifyRegular, verifyAlgo, {
        ...protectionSpec,
        kind: 'TP',
      });
      const hasSl = hasOpenProtectionOrder(verifyRegular, verifyAlgo, {
        ...protectionSpec,
        kind: 'SL',
      });
      const protectionComplete = (!expectsTp || hasTp) && (!expectsSl || hasSl);
      if (!protectionComplete) {
        throw new Error(
          `${symbol} socket fill protection verification failed:`
          + ` expected TP=${expectsTp} SL=${expectsSl}; found TP=${hasTp} SL=${hasSl}`,
        );
      }
      return { protectionComplete: true };
    },
    onRoeUpdate: (symbol, pos, markPrice, roe) => {
      broadcastOrdersPositionPnl(
        'position',
        binancePositionPnlPayload(symbol, pos, markPrice, roe),
      );
      if (!positionFirstSeenAt.has(symbol)) positionFirstSeenAt.set(symbol, Date.now());
      if (pendingLiqTp.has(symbol)) {
        placePendingLiqTp(symbol, pos).catch(() => {});
      }
      const tpGuardRoe = Number(process.env.TP_ENTRY_GUARD_ROE ?? -50);
      if (roe <= tpGuardRoe) {
        handleTpEntryGuard(symbol, pos, markPrice, roe).catch(() => {});
      }
      if (shouldMoveSymbolNegativeTpToEntry(symbol, roe)) {
        handleNegativeTimeoutTp(symbol, pos).catch(() => {});
      }
      const avgDownRoe = Number(process.env.AVG_DOWN_ROE ?? -60);
      if (roe <= avgDownRoe) {
        handleAvgDown(symbol, pos, roe).catch(() => {});
      }
      handleSlTrailByProfit(symbol, pos, roe, markPrice).catch(() => {});
      handlePositionTimeout(symbol, pos, markPrice, roe).catch(() => {});
      handleEightHourNegativeTakeProfit(symbol, pos, roe).catch(() => {});
      handleTwelveHourTakeProfit(symbol, pos, markPrice, roe).catch(() => {});
      if (roe < 0) {
        if (!negativeSince.has(symbol)) negativeSince.set(symbol, Date.now());
      } else {
        negativeSince.delete(symbol);
      }
    },
  });
  return posMonitor;
}

function isConfirmedSpikeReversalSignal(sig) {
  const status = String(sig?.stage ?? sig?.status ?? '').toLowerCase();
  return sig?.confirmed === true
    || status.includes('confirmed')
    || sig?.type === 'spike_reversal';
}

function applySpikeReversalTslExcludes(signals) {
  for (const sig of signals ?? []) {
    if (!sig?.symbol || !isConfirmedSpikeReversalSignal(sig)) continue;
    const symbol = String(sig.symbol).toUpperCase();
    if (tslExcludedSymbols.has(symbol)) continue;
    tslExcludedSymbols.add(symbol);
    console.log(`[TSL-Exclude] ⛔ ${symbol} excluded by confirmed Spike Reversal signal`);
  }
}

// Discord dedup: symbol → lastFiredAt (ms) — tránh spam cùng 1 signal
const spikeRevDiscordFired  = new Map();
const dumpIgnDiscordFired   = new Map();
const pumpIgnDiscordFired   = new Map();
const emaSqueezeDiscordFired = new Map();
const ema99KillReclaimDiscordFired = new Map();
const shakeoutReclaimDiscordFired = new Map();
const emaSqueezePaperAutoFired = new Map();
const emaSqueezeLiquidityEntryCache = new Map();
const emaSqueezeRealOrderFired = new Map();
const ema99KillReclaimRealOrderFired = new Map();
const shakeoutReclaimRealOrderFired = new Map();
const postPumpKillShortDiscordFired = new Map();
const postPumpKillShortOrderFired = new Map();
const ppksPaperAutoFired = new Map(); // dedup cho PPKS paper trade auto-fire
const postPumpDumpRiskOrderFired = new Map();
const postDumpBounceRiskOrderFired = new Map();
const longShortCache = new Map();    // symbol → { longShortRatio, longAccount }
const hedgeModeCache = new Map();    // apiKey → bool
const topPositionCache = new Map(); // symbol → { longShortRatio, longPosition, shortPosition }

const BLACKLIST_FILE = join(rootDir, 'data', 'dynamic-blacklist.json');
const dynamicBlacklist = new Map(); // symbol → { expiresAt, addedAt, reason }
