// ── BTC Health ────────────────────────────────────────────────────────────────
let btcHealthCache = { data: null, expiresAt: 0 };
const btcHealthHistory = [];
let btcMacroShockState = { activeUntil: 0, reason: '', detectedAt: 0, metrics: null };
let _btcHealthInflight = null; // dedup concurrent calls — only one REST fetch at a time
let goldHealthCache = { data: null, expiresAt: 0 };
let _goldHealthInflight = null;
// L/S ratio: không có WS → REST cache 30 phút (thay đổi rất chậm)
let btcLsRatioCache = { data: null, expiresAt: 0 };
// Funding rate + mark price: từ WebSocket markPrice stream (field r + p)
// → 0 REST calls, Binance push mỗi 3 giây
let btcMarkPriceWsData = { markPrice: null, fundingRate: null, nextFundingTime: null };

function startBtcMarkPriceWs() {
  const WS_URL = 'wss://fstream.binancefuture.com/ws/btcusdt@markPrice';
  function connect() {
    const ws = new WebSocket(WS_URL);
    ws.on('open',    () => console.log('[BtcWS] markPrice stream connected'));
    ws.on('message', (raw) => {
      try {
        const d = JSON.parse(raw);
        if (d.e === 'markPriceUpdate') {
          btcMarkPriceWsData = {
            markPrice:       Number(d.p),
            fundingRate:     Number(d.r) * 100, // % per 8h (như getPremiumIndex)
            nextFundingTime: Number(d.T),
          };
        }
      } catch {}
    });
    ws.on('close', () => { console.warn('[BtcWS] markPrice disconnected — reconnecting 5s'); setTimeout(connect, 5_000); });
    ws.on('error', () => {});
  }
  connect();
}

// Wilder's Smoothed RSI — khớp với Binance (dùng RMA/SMMA, không phải SMA)
// Cần ít nhất period*10 nến để warm-up đủ; 150+ nến cho kết quả chính xác
function calcRsiSimple(closes, period = 14) {
  if (closes.length < period + 1) return null;
  // Seed: SMA của period nến đầu tiên
  let avgGain = 0, avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const diff = closes[i] - closes[i - 1];
    if (diff > 0) avgGain += diff; else avgLoss -= diff;
  }
  avgGain /= period;
  avgLoss /= period;
  // Wilder's smoothing cho phần còn lại
  for (let i = period + 1; i < closes.length; i++) {
    const diff = closes[i] - closes[i - 1];
    avgGain = (avgGain * (period - 1) + (diff > 0 ? diff : 0)) / period;
    avgLoss = (avgLoss * (period - 1) + (diff < 0 ? -diff : 0)) / period;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}

function klineNum(k, key, idx) {
  const value = Array.isArray(k) ? k[idx] : k?.[key];
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function analyzeBtcMacroShockKlines(interval, rows = []) {
  const list = Array.isArray(rows) ? rows.filter(Boolean) : [];
  if (list.length < 12) return null;
  const last = list[list.length - 1];
  const prev = list[list.length - 2];
  const open = klineNum(last, 'open', 1);
  const close = klineNum(last, 'close', 4);
  const high = klineNum(last, 'high', 2);
  const low = klineNum(last, 'low', 3);
  const vol = klineNum(last, 'volume', 5);
  const prevClose = klineNum(prev, 'close', 4);
  if (![open, close, high, low, vol, prevClose].every(Number.isFinite) || open <= 0 || prevClose <= 0) return null;
  const bodyPct = (close - open) / open * 100;
  const dropFromPrevPct = (close - prevClose) / prevClose * 100;
  const rangePct = (high - low) / open * 100;
  const vols = list.slice(Math.max(0, list.length - 31), list.length - 1)
    .map((k) => klineNum(k, 'volume', 5))
    .filter((v) => Number.isFinite(v) && v > 0);
  const avgVol = vols.length ? vols.reduce((s, v) => s + v, 0) / vols.length : null;
  const volRatio = avgVol ? vol / avgVol : null;
  const closes = list.map((k) => klineNum(k, 'close', 4)).filter((v) => Number.isFinite(v) && v > 0);
  const ema25 = closes.length >= 25 ? closes.slice(-25).reduce((s, v) => s + v, 0) / 25 : null;
  const ema99 = closes.length >= 99 ? closes.slice(-99).reduce((s, v) => s + v, 0) / 99 : null;
  const brokeEma25 = ema25 != null && open >= ema25 && close < ema25;
  const belowEma99 = ema99 != null && close < ema99;
  return { interval, bodyPct, dropFromPrevPct, rangePct, volRatio, brokeEma25, belowEma99, open, close };
}

function getBtcMacroShockGuard() {
  const now = Date.now();
  const k5 = analyzeBtcMacroShockKlines('5m', klineCache.getIfCached('BTCUSDT', '5m', 120));
  const k15 = analyzeBtcMacroShockKlines('15m', klineCache.getIfCached('BTCUSDT', '15m', 120));
  const min5mDrop = Number(process.env.BTC_MACRO_SHOCK_5M_DROP_PCT ?? 0.75);
  const min15mDrop = Number(process.env.BTC_MACRO_SHOCK_15M_DROP_PCT ?? 1.2);
  const minVolRatio = Number(process.env.BTC_MACRO_SHOCK_VOL_RATIO ?? 2);
  const hit = [k5, k15].filter(Boolean).find((m) => {
    const absDrop = Math.abs(Math.min(m.bodyPct, m.dropFromPrevPct, 0));
    const minDrop = m.interval === '5m' ? min5mDrop : min15mDrop;
    const volOk = Number.isFinite(m.volRatio) && m.volRatio >= minVolRatio;
    const emaOk = m.brokeEma25 || m.belowEma99 || absDrop >= minDrop * 1.4;
    return m.bodyPct < 0 && absDrop >= minDrop && volOk && emaOk;
  });
  if (hit) {
    const cooldownMs = Math.max(5 * 60_000, Number(process.env.BTC_MACRO_SHOCK_COOLDOWN_MS ?? 45 * 60_000));
    btcMacroShockState = {
      activeUntil: Math.max(Number(btcMacroShockState.activeUntil ?? 0), now + cooldownMs),
      detectedAt: now,
      reason: `BTC ${hit.interval} shock ${hit.bodyPct.toFixed(2)}% vol ${Number(hit.volRatio ?? 0).toFixed(1)}x`,
      metrics: hit,
    };
  }
  return {
    active: now < Number(btcMacroShockState.activeUntil ?? 0),
    activeUntil: btcMacroShockState.activeUntil,
    detectedAt: btcMacroShockState.detectedAt,
    reason: btcMacroShockState.reason,
    metrics: btcMacroShockState.metrics,
  };
}

async function _fetchBtcHealth() {

  try {
    // Funding rate: từ WebSocket markPrice stream — 0 REST calls
    const fundingRate = btcMarkPriceWsData.fundingRate ?? 0;
    const markPrice   = btcMarkPriceWsData.markPrice;

    // L/S ratio: không có WS → REST cache 30 phút (thay đổi rất chậm, không cần real-time)
    if (!btcLsRatioCache.data || Date.now() >= btcLsRatioCache.expiresAt) {
      const lsTimeout = new Promise((_, rej) => setTimeout(() => rej(new Error('L/S timeout')), 5_000));
      const lsData = await Promise.race([
        client.getGlobalLongShortRatio('BTCUSDT', '5m', 1),
        lsTimeout,
      ]).catch(() => null);
      btcLsRatioCache = { data: lsData, expiresAt: Date.now() + 30 * 60_000 };
    }
    // getIfCached = chỉ đọc WS cache, KHÔNG fallback REST → không bao giờ treo
    const klines4h = klineCache.getIfCached('BTCUSDT', '4h', 100);
    const klines1d = klineCache.getIfCached('BTCUSDT', '1d', 50);
    const klines1h = klineCache.getIfCached('BTCUSDT', '1h', 200);
    if (!klines4h || !klines1h || !klines1d) {
      // Klines chưa seed xong — trả stale nếu có, không treo request
      if (btcHealthCache.data) return btcHealthCache.data;
      return { bias: 'neutral', bearPoints: 0, bullPoints: 0, bullBias: 'neutral', updatedAt: Date.now(), seeding: true };
    }
    const lsRaw = btcLsRatioCache.data;

    // L/S ratio
    const lsData = Array.isArray(lsRaw) ? lsRaw[0] : lsRaw;
    const lsRatio = lsData ? Number(lsData.longShortRatio) : null;
    const longPct = lsRatio ? (lsRatio / (1 + lsRatio)) * 100 : null;

    // RSI 4h — current and 3 candles ago (divergence check)
    const closes4h = klines4h.map((k) => Number(k[4] ?? k.close));
    const highs4h  = klines4h.map((k) => Number(k[2] ?? k.high));
    const rsi4h    = calcRsiSimple(closes4h, 14);

    // Bearish divergence: price higher high but RSI lower high vs 10 candles ago
    const rsiPrev  = calcRsiSimple(closes4h.slice(0, -10), 14);
    const pricePeak  = Math.max(...closes4h.slice(-5));
    const pricePrev  = Math.max(...closes4h.slice(-15, -10));
    const bearishDiv = rsi4h != null && rsiPrev != null && pricePeak > pricePrev && rsi4h < rsiPrev - 3;

    // RSI 1D
    const closes1d = klines1d.map((k) => Number(k[4] ?? k.close));
    const rsi1d    = calcRsiSimple(closes1d, 14);

    // RSI 1h + EMA20 1h + momentum 6h — detect active downtrend
    const closes1h  = klines1h.map((k) => Number(k[4] ?? k.close));
    const rsi1h     = calcRsiSimple(closes1h, 14);
    const ema20_1h  = closes1h.length >= 20
      ? closes1h.slice(-20).reduce((s, v) => s + v, 0) / 20
      : null;
    const lastClose1h = closes1h[closes1h.length - 1];
    const emaTrend1h  = ema20_1h != null
      ? (lastClose1h < ema20_1h ? 'below' : 'above')
      : null;
    // % thay đổi trong 6 nến 1h gần nhất
    const pct6h = closes1h.length >= 7
      ? ((closes1h[closes1h.length - 1] - closes1h[closes1h.length - 7]) / closes1h[closes1h.length - 7]) * 100
      : null;

    // Last CLOSED 1h candle direction — dùng để detect BTC correction phase
    // index -1 = nến đang chạy (bỏ qua), index -2 = nến vừa đóng
    const k1hLast = klines1h[klines1h.length - 2];
    const btcCandle1hPct = k1hLast
      ? ((Number(k1hLast[4]) - Number(k1hLast[1])) / Number(k1hLast[1])) * 100
      : null;

    // BTC spike candle detection — vol > 2.5x avg + move > 1% trên 1h
    // Sau nến spike, correction thường xảy ra → EMA_PB LONG trên alt bị block 2 nến tiếp
    let btcSpikeAlert = false;
    if (klines1h && klines1h.length >= 15) {
      const vols1h = klines1h.map((k) => Number(k[5] ?? k.volume));
      // Baseline: dùng candles 5-25 periods ago (tránh đưa spike vào avg của chính nó)
      const baselineVols = vols1h.slice(Math.max(0, vols1h.length - 25), vols1h.length - 5);
      const avgVol1h = baselineVols.length > 0
        ? baselineVols.reduce((s, v) => s + v, 0) / baselineVols.length : 0;
      // Kiểm tra 3 nến closed gần nhất (bỏ nến đang chạy = index cuối)
      for (let i = 2; i <= 4; i++) {
        const k = klines1h[klines1h.length - i];
        if (!k) continue;
        const vol     = Number(k[5] ?? k.volume);
        const open    = Number(k[1] ?? k.open);
        const close   = Number(k[4] ?? k.close);
        const movePct = Math.abs((close - open) / open) * 100;
        if (avgVol1h > 0 && vol > avgVol1h * 2.5 && movePct > 1.0) {
          btcSpikeAlert = true;
          break;
        }
      }
    }

    // OBV trend 4h (last 20 candles) — rising/falling/flat
    const vols4h   = klines4h.map((k) => Number(k[5] ?? k.volume));
    let obv = 0;
    const obvArr = [];
    for (let i = 1; i < closes4h.length; i++) {
      obv += closes4h[i] > closes4h[i - 1] ? vols4h[i] : closes4h[i] < closes4h[i - 1] ? -vols4h[i] : 0;
      obvArr.push(obv);
    }
    const obvRecent = obvArr.slice(-20);
    const obvTrend  = obvRecent[obvRecent.length - 1] > obvRecent[0] * 1.02 ? 'rising'
                    : obvRecent[obvRecent.length - 1] < obvRecent[0] * 0.98 ? 'falling' : 'flat';

    // BTC trend-strength (1h, 0-100) để set TP động: trend mạnh bền -> cho TP chạy; range/spike -> TP chặt.
    // 3 thành phần: EMA align+giá (40) + độ dốc EMA (30) + tính nhất quán hướng (30). Spike -> cap 50.
    const highs1h = klines1h.map((k) => Number(k[2] ?? k.high));
    const lows1h = klines1h.map((k) => Number(k[3] ?? k.low));
    const emaLastN = (arr, p, back = 0) => {
      const a = 2 / (p + 1);
      let e = arr[0];
      const out = [e];
      for (let i = 1; i < arr.length; i++) { e = a * arr[i] + (1 - a) * e; out.push(e); }
      return out[out.length - 1 - back];
    };
    let btcTrendScore = 0;
    let btcTrendDir = 'flat';
    let btcTrendScore4h = 0;
    let btcTrendDir4h = 'flat';
    let btcSpike = btcSpikeAlert;
    if (closes1h.length >= 28) {
      const ema8 = emaLastN(closes1h, 8);
      const ema21 = emaLastN(closes1h, 21);
      const ema21prev = emaLastN(closes1h, 21, 6);
      const c = closes1h[closes1h.length - 1];
      btcTrendDir = ema8 > ema21 ? 'up' : ema8 < ema21 ? 'down' : 'flat';
      const aligned = (btcTrendDir === 'up' && c > ema8) || (btcTrendDir === 'down' && c < ema8);
      const alignPts = aligned ? 40 : (btcTrendDir !== 'flat' ? 16 : 0);
      const slopePct = ema21prev > 0 ? Math.abs(ema21 - ema21prev) / ema21prev * 100 : 0;
      const slopePts = Math.max(0, Math.min(1, slopePct / 2)) * 30; // ~2%/6h = full
      const recent = closes1h.slice(-13);
      let dirCount = 0;
      for (let i = 1; i < recent.length; i++) {
        if (btcTrendDir === 'up' && recent[i] > recent[i - 1]) dirCount++;
        else if (btcTrendDir === 'down' && recent[i] < recent[i - 1]) dirCount++;
      }
      const consPts = (dirCount / Math.max(1, recent.length - 1)) * 30;
      btcTrendScore = Math.round(alignPts + slopePts + consPts);
      // Spike guard: vol-spike hoặc RSI cực đoan -> không phải trend bền -> cap score
      if (btcSpikeAlert || (rsi1h != null && (rsi1h > 78 || rsi1h < 22))) {
        btcSpike = true;
        btcTrendScore = Math.min(btcTrendScore, 50);
      }
    }

    const pct24h = closes4h.length >= 7
      ? ((closes4h[closes4h.length - 1] - closes4h[closes4h.length - 7]) / closes4h[closes4h.length - 7]) * 100
      : null;
    if (closes4h.length >= 28) {
      const ema8 = emaLastN(closes4h, 8);
      const ema21 = emaLastN(closes4h, 21);
      const ema21prev = emaLastN(closes4h, 21, 6);
      const close = closes4h[closes4h.length - 1];
      btcTrendDir4h = ema8 > ema21 ? 'up' : ema8 < ema21 ? 'down' : 'flat';
      const aligned = (btcTrendDir4h === 'up' && close > ema8) || (btcTrendDir4h === 'down' && close < ema8);
      const alignPts = aligned ? 40 : (btcTrendDir4h !== 'flat' ? 16 : 0);
      const slopePct = ema21prev > 0 ? Math.abs(ema21 - ema21prev) / ema21prev * 100 : 0;
      const slopePts = Math.max(0, Math.min(1, slopePct / 4)) * 30;
      const recent = closes4h.slice(-7);
      let directionCount = 0;
      for (let i = 1; i < recent.length; i++) {
        if (btcTrendDir4h === 'up' && recent[i] > recent[i - 1]) directionCount++;
        else if (btcTrendDir4h === 'down' && recent[i] < recent[i - 1]) directionCount++;
      }
      btcTrendScore4h = Math.round(alignPts + slopePts + (directionCount / Math.max(1, recent.length - 1)) * 30);
      if (rsi4h != null && (rsi4h > 78 || rsi4h < 22)) btcTrendScore4h = Math.min(btcTrendScore4h, 50);
    }

    // Overall bias
    let bearPoints = 0;
    // --- Tín hiệu đỉnh quá nóng (pre-drop) ---
    if (fundingRate > 0.05) bearPoints++;
    if (bearishDiv) bearPoints++;
    if (longPct != null && longPct > 62) bearPoints++;
    if (rsi4h != null && rsi4h > 70) bearPoints++;
    if (obvTrend === 'falling') bearPoints++;
    // --- Tín hiệu đang trong downtrend (active dump) ---
    if (rsi4h != null && rsi4h < 30) bearPoints++;           // BTC dump mạnh trên 4h (< 30 thay vì 35 để unblock LONG sớm hơn khi hồi phục)
    if (rsi1h != null && rsi1h < 40) bearPoints++;           // Momentum âm trên 1h
    if (emaTrend1h === 'below') bearPoints++;                // Price dưới EMA20 1h

    const bias = bearPoints >= 3 ? 'bearish' : bearPoints >= 2 ? 'caution' : 'neutral';

    // --- Bull points — đối xứng, dùng để block SHORT ---
    let bullPoints = 0;
    if (rsi1h != null && rsi1h > 60) bullPoints++;          // Momentum dương trên 1h
    if (emaTrend1h === 'above') bullPoints++;               // Price trên EMA20 1h
    if (pct6h != null && pct6h > 1.5) bullPoints++;        // BTC tăng >1.5% trong 6h
    if (obvTrend === 'rising' && pct6h != null && pct6h > 0.5) bullPoints++; // OBV rising chỉ tính khi momentum 6h xác nhận (> 0.5%) — tránh lagging sau pump
    if (rsi4h != null && rsi4h > 55 && rsi4h < 70) bullPoints++; // 4h bullish nhưng chưa overbought
    if (longPct != null && longPct < 42) bullPoints++;     // Short nhiều → short squeeze risk
    const bullBias = bullPoints >= 3 ? 'bullish' : bullPoints >= 2 ? 'caution' : 'neutral';
    const macroShock = getBtcMacroShockGuard();

    const data = {
      price: markPrice,
      fundingRate: +fundingRate.toFixed(4),
      lsRatio,
      longPct: longPct != null ? +longPct.toFixed(1) : null,
      rsi4h: rsi4h != null ? +rsi4h.toFixed(1) : null,
      rsi1d: rsi1d != null ? +rsi1d.toFixed(1) : null,
      rsi1h: rsi1h != null ? +rsi1h.toFixed(1) : null,
      emaTrend1h,
      pct6h: pct6h != null ? +pct6h.toFixed(2) : null,
      pct24h: pct24h != null ? +pct24h.toFixed(2) : null,
      bearishDiv,
      obvTrend,
      bias,
      bearPoints,
      bullBias,
      bullPoints,
      btcSpikeAlert,
      macroShock,
      btcCandle1hPct: btcCandle1hPct != null ? +btcCandle1hPct.toFixed(3) : null,
      btcTrendScore,
      btcTrendDir,
      btcTrendScore4h,
      btcTrendDir4h,
      btcSpike,
      updatedAt: Date.now(),
    };

    btcHealthHistory.push({
      at: Date.now(),
      regime: emaSqueezeBtcRegime(data),
      bias: data.bias,
      bullBias: data.bullBias,
      bearPoints: data.bearPoints,
      bullPoints: data.bullPoints,
      rsi1h: data.rsi1h,
      pct6h: data.pct6h,
      emaTrend1h: data.emaTrend1h,
    });
    if (btcHealthHistory.length > 720) btcHealthHistory.splice(0, btcHealthHistory.length - 720);

    btcHealthCache = { data, expiresAt: Date.now() + 30_000 }; // 30s — klines từ WS, RSI đủ fresh
    return data;
  } catch (e) {
    console.warn('[BtcHealth] error:', e.message);
    return btcHealthCache.data ?? { error: e.message };
  }
}

// Wrapper: cache check + in-flight dedup → chỉ 1 REST fetch tại một thời điểm
function getBtcHealth() {
  if (btcHealthCache.data && Date.now() < btcHealthCache.expiresAt) {
    return Promise.resolve(btcHealthCache.data);
  }
  if (_btcHealthInflight) return _btcHealthInflight;
  _btcHealthInflight = _fetchBtcHealth().finally(() => { _btcHealthInflight = null; });
  return _btcHealthInflight;
}

async function _fetchGoldHealth() {
  const symbol = String(process.env.EMA_SQUEEZE_REAL_GOLD_SYMBOL ?? 'PAXGUSDT').toUpperCase().trim();
  const interval = String(process.env.EMA_SQUEEZE_REAL_GOLD_INTERVAL ?? '1h').trim() || '1h';
  const useLiveCandle = process.env.EMA_SQUEEZE_REAL_GOLD_USE_LIVE_CANDLE !== 'false';
  const redThresholdPct = Number(process.env.EMA_SQUEEZE_REAL_GOLD_RED_THRESHOLD_PCT ?? 0);
  try {
    const rows = await client.getKlines(symbol, interval, 3, {
      priority: 4,
      dropOnCongestion: true,
      source: 'emaSqueezeGoldHealth',
    });
    const idx = useLiveCandle ? rows.length - 1 : rows.length - 2;
    const k = rows[idx];
    if (!k) throw new Error(`not enough ${symbol} ${interval} candles`);
    const open = Number(k.open ?? k[1]);
    const close = Number(k.close ?? k[4]);
    if (!Number.isFinite(open) || open <= 0 || !Number.isFinite(close) || close <= 0) {
      throw new Error(`invalid ${symbol} ${interval} candle`);
    }
    const changePct = ((close - open) / open) * 100;
    const data = {
      symbol,
      interval,
      mode: useLiveCandle ? 'live' : 'closed',
      open,
      close,
      changePct: +changePct.toFixed(3),
      red: changePct < redThresholdPct,
      redThresholdPct,
      updatedAt: Date.now(),
    };
    goldHealthCache = { data, expiresAt: Date.now() + 60_000 };
    return data;
  } catch (e) {
    console.warn('[GoldHealth] error:', e.message);
    const data = { symbol, interval, error: e.message, updatedAt: Date.now() };
    goldHealthCache = { data, expiresAt: Date.now() + 60_000 };
    return data;
  }
}

function getGoldHealth() {
  if (process.env.EMA_SQUEEZE_REAL_GOLD_FILTER === 'false') {
    return Promise.resolve({ disabled: true, red: false });
  }
  if (goldHealthCache.data && Date.now() < goldHealthCache.expiresAt) {
    return Promise.resolve(goldHealthCache.data);
  }
  if (_goldHealthInflight) return _goldHealthInflight;
  _goldHealthInflight = _fetchGoldHealth().finally(() => { _goldHealthInflight = null; });
  return _goldHealthInflight;
}

// ── RSI update khi nến mới đóng (1h/4h/1d) — không dùng candleTick để tránh ban IP ──────
// klineCache._applyTick() liên tục cập nhật close của nến hiện tại từ WS,
// nên khi getBtcHealth() chạy (mỗi 30s) RSI đã dùng giá live rồi — không cần invalidate liên tục.
klineCache.on('candleClose', ({ symbol, interval }) => {
  if (interval === '5m' || interval === '15m') liquidMarketDirectionCache.expiresAt = 0;
  if (symbol !== 'BTCUSDT') return;
  if (interval !== '1h' && interval !== '4h' && interval !== '1d') return;
  btcHealthCache.expiresAt = 0; // force refresh ngay khi nến mới đóng
  getBtcHealth().catch(() => {}); // pre-warm cache
});

async function getSymbols() {
  if (symbolCache.data && Date.now() < symbolCache.expiresAt) {
    return symbolCache.data;
  }
  if (_symbolCacheInflight) return _symbolCacheInflight;
  _symbolCacheInflight = (async () => {
    const exchangeInfo = await client.getExchangeInfo({ priority: 1, source: 'getSymbols' });
    const symbols = exchangeInfo.symbols
      .filter((item) => item.contractType === 'PERPETUAL' && item.quoteAsset === 'USDT' && item.status === 'TRADING')
      .map((item) => ({
        symbol: item.symbol,
        baseAsset: item.baseAsset,
        quoteAsset: item.quoteAsset,
        quantityPrecision: item.quantityPrecision,
        filters: item.filters,
        orderTypes: item.orderTypes ?? [],
      }))
      .sort((a, b) => a.symbol.localeCompare(b.symbol));
    symbolCache.data = symbols;
    symbolCache.expiresAt = Date.now() + 60 * 60 * 1000;
    return symbols;
  })();
  try {
    return await _symbolCacheInflight;
  } finally {
    _symbolCacheInflight = null;
  }
}

const signalProtectionPlans = new Map(); // symbol -> intended TP/SL to apply after full fill
const signalProtectionRunning = new Set();

function hasPreservedLiveCardSignalProtection(symbol) {
  return isLiveCardSignalProtection({
    tracking: slTracking.positions?.[symbol] ?? null,
    plan: signalProtectionPlans.get(symbol) ?? null,
  });
}

function rememberSignalProtectionPlan({
  symbol,
  side,
  takeProfitPrice,
  stopLossPrice,
  signalEntryPrice = null,
  signalTakeProfitPrice = takeProfitPrice,
  signalStopLossPrice = stopLossPrice,
  fillAnchorEnabled = null,
  fillAnchorVersion = null,
  takeProfitDistanceFraction = null,
  stopLossDistanceFraction = null,
  fillPrice = null,
  source,
  orderId = null,
  entryClientOrderId = null,
  lifecycleId = null,
  preserveSignalProtection = false,
  takeProfitWorkingType = null,
  stopLossWorkingType = null,
}) {
  const tpPrice = Number(takeProfitPrice);
  const slPrice = Number(stopLossPrice);
  if ((!Number.isFinite(tpPrice) || tpPrice <= 0) && (!Number.isFinite(slPrice) || slPrice <= 0)) return;
  const protectionPolicy = resolveSignalProtectionWorkingTypes({
    source,
    preserveSignalProtection,
    takeProfitWorkingType,
    stopLossWorkingType,
  });
  const derivedAnchor = buildFillAnchoredProtectionSpec({
    side,
    signalEntryPrice,
    takeProfitPrice: signalTakeProfitPrice,
    stopLossPrice: signalStopLossPrice,
  });
  const explicitTpDistance = Number(takeProfitDistanceFraction);
  const explicitSlDistance = Number(stopLossDistanceFraction);
  const hasExplicitAnchor = fillAnchorEnabled === true && (
    (Number.isFinite(explicitTpDistance) && explicitTpDistance > 0)
    || (Number.isFinite(explicitSlDistance) && explicitSlDistance > 0)
  );
  const fillAnchor = hasExplicitAnchor
    ? {
        fillAnchorVersion: fillAnchorVersion ?? LIVE_CARD_FILL_ANCHORED_PROTECTION_VERSION,
        fillAnchorEnabled: true,
        signalEntryPrice: Number(signalEntryPrice) || null,
        signalTakeProfitPrice: Number(signalTakeProfitPrice) || null,
        signalStopLossPrice: Number(signalStopLossPrice) || null,
        takeProfitDistanceFraction: Number.isFinite(explicitTpDistance) && explicitTpDistance > 0
          ? explicitTpDistance
          : null,
        stopLossDistanceFraction: Number.isFinite(explicitSlDistance) && explicitSlDistance > 0
          ? explicitSlDistance
          : null,
      }
    : derivedAnchor;
  signalProtectionPlans.set(symbol, {
    symbol,
    side,
    tpPrice: Number.isFinite(tpPrice) && tpPrice > 0 ? tpPrice : null,
    slPrice: Number.isFinite(slPrice) && slPrice > 0 ? slPrice : null,
    source: String(source ?? 'signal'),
    orderId,
    entryClientOrderId,
    lifecycleId,
    fillPrice: Number(fillPrice) || null,
    ...fillAnchor,
    ...protectionPolicy,
    createdAt: Date.now(),
  });
}

async function applySignalProtectionOnFill(symbol, attempt = 1) {
  const plan = signalProtectionPlans.get(symbol);
  if (!plan || signalProtectionRunning.has(symbol)) return;
  if (Date.now() - plan.createdAt > 24 * 3600_000) {
    signalProtectionPlans.delete(symbol);
    return;
  }

  signalProtectionRunning.add(symbol);
  try {
    let execution = null;
    if (plan.lifecycleId) {
      execution = await liveCardBinanceLifecycle.get(plan.lifecycleId);
      if (['BOT_CLOSE_REQUESTED', 'BOT_CLOSE_SUBMITTED', 'POSITION_CLOSED'].includes(execution?.status)) {
        signalProtectionPlans.delete(symbol);
        return;
      }
    }
    const anchored = resolveFillAnchoredProtectionPrices({
      side: plan.side,
      fillPrice: execution?.fillPrice ?? plan.fillPrice,
      takeProfitPrice: plan.tpPrice,
      stopLossPrice: plan.slPrice,
      fillAnchorEnabled: plan.fillAnchorEnabled,
      takeProfitDistanceFraction: plan.takeProfitDistanceFraction,
      stopLossDistanceFraction: plan.stopLossDistanceFraction,
    });
    if (anchored.rebased) {
      plan.fillPrice = anchored.fillPrice;
      plan.tpPrice = anchored.takeProfitPrice;
      plan.slPrice = anchored.stopLossPrice;
      if (!plan.fillAnchoredAt) {
        plan.fillAnchoredAt = new Date().toISOString();
        if (plan.lifecycleId) {
          await liveCardBinanceLifecycle.upsert({
            lifecycleId: plan.lifecycleId,
            takeProfitPrice: plan.tpPrice,
            stopLossPrice: plan.slPrice,
            signalEntryPrice: plan.signalEntryPrice,
            signalTakeProfitPrice: plan.signalTakeProfitPrice,
            signalStopLossPrice: plan.signalStopLossPrice,
            fillAnchorVersion: plan.fillAnchorVersion,
            fillAnchorEnabled: true,
            takeProfitDistanceFraction: plan.takeProfitDistanceFraction,
            stopLossDistanceFraction: plan.stopLossDistanceFraction,
            protectionFillPrice: plan.fillPrice,
            protectionFillAnchoredAt: plan.fillAnchoredAt,
          }, 'PROTECTION_REBASED_TO_FILL', {
            symbol,
            fillPrice: plan.fillPrice,
            takeProfitPrice: plan.tpPrice,
            stopLossPrice: plan.slPrice,
          }).catch((error) => {
            console.warn(`[LiveCardLifecycle] fill anchor ${symbol}:`, error.message);
          });
        }
      }
    }
    const protectionResult = await setTpSl({
      symbol,
      tpPrice: plan.tpPrice,
      slPrice: plan.slPrice,
      source: plan.source,
      clientIdPrefix: plan.lifecycleId ? `lc_${String(plan.lifecycleId).replace(/[^a-zA-Z0-9]/g, '').slice(-12)}` : null,
      takeProfitWorkingType: plan.takeProfitWorkingType,
      stopLossWorkingType: plan.stopLossWorkingType,
    });
    if (protectionResult?.takeProfitPolicyVersion && protectionResult?.placed?.tp && protectionResult?.takeProfitPrice) {
      plan.tpPrice = protectionResult.takeProfitPrice;
    }
    if (slTracking.positions[symbol]) {
      slTracking.positions[symbol].signalTp = plan.tpPrice;
      slTracking.positions[symbol].signalSl = plan.slPrice;
      slTracking.positions[symbol].signalEntryPrice = plan.signalEntryPrice;
      slTracking.positions[symbol].signalTakeProfitPrice = plan.signalTakeProfitPrice;
      slTracking.positions[symbol].signalStopLossPrice = plan.signalStopLossPrice;
      slTracking.positions[symbol].lifecycleId = plan.lifecycleId ?? slTracking.positions[symbol].lifecycleId ?? null;
      slTracking.positions[symbol].fillAnchorVersion = plan.fillAnchorVersion;
      slTracking.positions[symbol].fillAnchorEnabled = plan.fillAnchorEnabled === true;
      slTracking.positions[symbol].protectionFillPrice = plan.fillPrice;
      slTracking.positions[symbol].protectionFillAnchoredAt = plan.fillAnchoredAt ?? null;
      if (plan.slPrice) {
        slTracking.positions[symbol].slPlaced = true;
        slTracking.positions[symbol].slPrice = plan.slPrice;
        slTracking.positions[symbol].slPlacedAt = new Date().toISOString();
      }
      slTracking.positions[symbol].signalProtectionVersion = plan.preserveSignalProtection
        ? LIVE_CARD_SIGNAL_PROTECTION_VERSION
        : null;
      slTracking.positions[symbol].preserveSignalProtection = plan.preserveSignalProtection === true;
      slTracking.positions[symbol].takeProfitWorkingType = plan.takeProfitWorkingType;
      slTracking.positions[symbol].stopLossWorkingType = plan.stopLossWorkingType;
      saveSlTracking();
    }
    plan.appliedAt = Date.now();
    plan.protectionResult = protectionResult;
    if (plan.lifecycleId) {
      await liveCardBinanceLifecycle.markProtection(plan.lifecycleId, protectionResult).catch((error) => {
        console.warn(`[LiveCardLifecycle] protection ${symbol}:`, error.message);
      });
      broadcastOrdersPositionPnl('live-card-lifecycle', {
        version: ORDERS_POSITION_PNL_STREAM_VERSION,
        lifecycleId: plan.lifecycleId,
        symbol,
        status: 'PROTECTED',
        eventAt: Date.now(),
      });
    }
    console.log(`[SignalProtection] ${symbol} applied source=${plan.source} TP=${plan.tpPrice ?? '-'} SL=${plan.slPrice ?? '-'}`);
  } catch (err) {
    console.warn(`[SignalProtection] ${symbol} attempt=${attempt} failed: ${err.message}`);
    if (plan.lifecycleId && attempt >= 4) {
      await liveCardBinanceLifecycle.markProtection(plan.lifecycleId, null, err.message).catch(() => {});
    }
    if (attempt < 4) {
      setTimeout(() => applySignalProtectionOnFill(symbol, attempt + 1), attempt * 1500);
    }
  } finally {
    signalProtectionRunning.delete(symbol);
  }
}

async function waitForCoinGlassOppositeClose(symbol, targetSide, credentials) {
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const positions = await client.getPositions({
      ...credentials,
      priority: 0,
      dropOnCongestion: false,
      source: 'coinglassQualified:confirmOppositeClosed',
    });
    const opposite = positions.filter((position) => {
      if (normalizeSymbol(position?.symbol) !== symbol || Number(position?.positionAmt) === 0) return false;
      const positionSide = String(position?.positionSide ?? 'BOTH').toUpperCase();
      const side = positionSide === 'LONG' || positionSide === 'SHORT'
        ? positionSide
        : Number(position.positionAmt) > 0 ? 'LONG' : 'SHORT';
      return side !== targetSide;
    });
    if (!opposite.length) return positions;
    await new Promise((resolve) => setTimeout(resolve, 400));
  }
  throw new Error(`Opposite ${symbol} position was not confirmed closed.`);
}

async function executeCoinGlassQualifiedBinanceRow(row = {}) {
  const symbol = normalizeSymbol(row?.symbol ?? '');
  if (!runtimeSettings.orderEnabled) return { decision: 'BLOCKED_ORDER_DISABLED' };
  if (runtimeSettings.dryRun) return { decision: 'BLOCKED_DRY_RUN' };
  const config = coinGlassWebTop20.config();
  if (!config.binanceEnabled) return { decision: 'BLOCKED_COINGLASS_BINANCE_DISABLED' };
  const signalSetting = await resolveLiquidFlowV2BinanceSignalSetting(coinGlassQualifiedStatsLabel(row));
  if (!signalSetting.supported || !signalSetting.enabled) {
    return { decision: 'BLOCKED_SIGNAL_BINANCE_DISABLED' };
  }
  const marginUsdt = Math.max(0.01, Number(signalSetting.marginUsdt ?? COINGLASS_WEB_BINANCE_MARGIN_USDT));
  const leverage = Math.max(1, Math.min(125, Number(signalSetting.leverage ?? COINGLASS_WEB_BINANCE_LEVERAGE)));
  const stopLossRoePct = Math.max(1, Number(
    config.binanceStopLossRoePct ?? COINGLASS_WEB_BINANCE_STOP_LOSS_ROE_PCT,
  ));
  const credentials = getApiCredentials(null);
  const [symbols, premiumIndex, positions, openOrders] = await Promise.all([
    getSymbols(),
    client.getPremiumIndex(symbol, {
      priority: 0,
      dropOnCongestion: false,
      source: 'coinglassQualified:premiumIndex',
    }),
    client.getPositions({
      ...credentials,
      priority: 0,
      dropOnCongestion: false,
      source: 'coinglassQualified:positions',
    }),
    client.getOpenOrders({
      ...credentials,
      symbol,
      priority: 0,
      dropOnCongestion: false,
      source: 'coinglassQualified:openOrders',
    }),
  ]);
  const symbolInfo = symbols.find((item) => item.symbol === symbol);
  if (!symbolInfo) return { decision: 'BLOCKED_INVALID_SYMBOL' };
  let decision = evaluateCoinglassWebBinanceEntry({
    row,
    currentPrice: Number(premiumIndex?.markPrice),
    positions,
    leverage,
    stopLossRoePct,
  });
  if (!decision.allowed) return decision;

  const entryOrders = openOrders.filter((order) => (
    order?.reduceOnly !== true
    && order?.reduceOnly !== 'true'
    && order?.closePosition !== true
    && order?.closePosition !== 'true'
  ));
  if (entryOrders.length) {
    return { ...decision, allowed: false, decision: 'BLOCKED_EXISTING_ENTRY_ORDER' };
  }

  const reversedOrderIds = [];
  let positionsForEntry = positions;
  if (decision.opposite?.length) {
    for (const position of decision.opposite) {
      const amount = Number(position.positionAmt ?? position.amt);
      const positionSide = String(position.positionSide ?? 'BOTH').toUpperCase();
      const quantity = quantityFromNotional(
        symbolInfo,
        Math.abs(amount) * Number(premiumIndex.markPrice),
        Number(premiumIndex.markPrice),
        true,
      );
      if (!(Number(quantity) > 0)) throw new Error(`Invalid reversal quantity for ${symbol}.`);
      const closeParams = {
        symbol,
        side: amount > 0 ? 'SELL' : 'BUY',
        type: 'MARKET',
        quantity,
        recvWindow: Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000),
        newClientOrderId: `cg_rev_${Date.now().toString(36)}`.slice(0, 36),
      };
      if (positionSide === 'LONG' || positionSide === 'SHORT') closeParams.positionSide = positionSide;
      else closeParams.reduceOnly = 'true';
      const closeResult = await client.placeFuturesOrder({ params: closeParams, ...credentials });
      reversedOrderIds.push(closeResult?.orderId ?? null);
    }
    positionsForEntry = await waitForCoinGlassOppositeClose(symbol, decision.side, credentials);
    await handleConfirmedPositionClose(symbol);
  }

  const latestPremium = await client.getPremiumIndex(symbol, {
    priority: 0,
    dropOnCongestion: false,
    source: 'coinglassQualified:finalPrice',
  });
  decision = evaluateCoinglassWebBinanceEntry({
    row,
    currentPrice: Number(latestPremium?.markPrice),
    positions: positionsForEntry,
    leverage,
    stopLossRoePct,
  });
  if (!decision.allowed) {
    return { ...decision, reversedOrderId: reversedOrderIds.filter(Boolean).join(',') || null };
  }

  const plan = row.proposal.tradePlan;
  const fillAnchorSpec = buildFillAnchoredProtectionSpec({
    side: decision.side,
    signalEntryPrice: decision.proposedEntry,
    takeProfitPrice: decision.takeProfit,
    stopLossPrice: decision.stopLoss,
  });
  const protectionPolicy = resolveSignalProtectionWorkingTypes({
    source: 'coinglass-web-qualified',
    preserveSignalProtection: true,
  });
  const orderResult = await placeOrder(authorizeCoinglassWebAutoOrder({
    symbol,
    side: decision.side === 'LONG' ? 'BUY' : 'SELL',
    orderType: 'MARKET',
    notionalUsdt: marginUsdt * leverage,
    leverage,
    takeProfitPrice: Number(plan.takeProfit.price),
    stopLossPrice: decision.stopLoss,
    protectionSignalEntryPrice: decision.proposedEntry,
    protectionSignalTakeProfitPrice: Number(plan.takeProfit.price),
    protectionSignalStopLossPrice: decision.stopLoss,
    ...fillAnchorSpec,
    protectionOnFill: true,
    ...protectionPolicy,
    allowMinNotionalCeil: true,
    dryRun: false,
    maxOpenPositions: Math.max(0, Number(process.env.COINGLASS_WEB_BINANCE_MAX_POSITIONS ?? 30)),
    source: 'coinglass-web-qualified',
    clientOrderId: `cg_${Date.now().toString(36)}_${symbol.slice(0, 8)}`.slice(0, 36),
  }), null, credentials, {
    liveCard: true,
    positions: positionsForEntry,
    openOrders: [],
  });
  const submitted = orderResult?.status === 'submitted';
  console.log(
    `[CoinGlassBinance] ${submitted ? 'SUBMITTED' : 'NOT_SUBMITTED'} ${symbol} ${decision.side}`
    + ` mark=${decision.currentPrice} proposed=${decision.proposedEntry} margin=$${marginUsdt} x${leverage}`
    + ` sl=-${stopLossRoePct}%ROE@${decision.stopLoss}`
    + ` reversed=${reversedOrderIds.filter(Boolean).join(',') || '-'}`
    + ` version=${COINGLASS_WEB_BINANCE_VERSION}`,
  );
  return {
    ...decision,
    decision: submitted ? 'SUBMITTED' : 'NOT_SUBMITTED',
    orderId: orderResult?.orderResult?.orderId ?? null,
    binanceEntryPrice: Number(orderResult?.orderResult?.avgPrice) > 0
      ? Number(orderResult.orderResult.avgPrice)
      : decision.currentPrice,
    filledAt: Number(orderResult?.orderResult?.updateTime ?? orderResult?.orderResult?.transactTime) || null,
    reversedOrderId: reversedOrderIds.filter(Boolean).join(',') || null,
    marginUsdt,
    leverage,
    stopLossRoePct,
  };
}

async function placeOrder(payload, token = null, credentialsOverride = null, executionContext = null) {
  const symbol = normalizeSymbol(payload.symbol ?? '');
  const side = String(payload.side ?? '').toUpperCase();
  const orderType = String(payload.orderType ?? payload.type ?? 'MARKET').toUpperCase();
  const notionalUsdt = Number(payload.notionalUsdt);
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 1)));
  const dryRun = payload.dryRun !== false;
  const limitPrice = payload.limitPrice === undefined || payload.limitPrice === null || payload.limitPrice === ''
    ? null
    : Number(payload.limitPrice);
  const takeProfitPrice = payload.takeProfitPrice === undefined || payload.takeProfitPrice === null || payload.takeProfitPrice === ''
    ? null
    : Number(payload.takeProfitPrice);
  const stopLossPrice = payload.stopLossPrice === undefined || payload.stopLossPrice === null || payload.stopLossPrice === ''
    ? null
    : Number(payload.stopLossPrice);
  const protectionSource = String(payload.source ?? 'signal');
  const protectionMeta = payload.protectionMeta && typeof payload.protectionMeta === 'object'
    ? payload.protectionMeta
    : {};
  const protectionPolicy = resolveSignalProtectionWorkingTypes({
    source: protectionSource,
    preserveSignalProtection: payload.preserveSignalProtection === true,
    takeProfitWorkingType: payload.takeProfitWorkingType,
    stopLossWorkingType: payload.stopLossWorkingType,
  });
  const requestedClientOrderId = String(payload.clientOrderId ?? '').replace(/[^a-zA-Z0-9_\-]/g, '').slice(0, 36);
  const maxOpenPositions = Number(payload.maxOpenPositions ?? 0);
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  const autoEntryPolicy = evaluateAutoBinanceEntryPolicy({
    payload,
    tokenIsAuthorized: Boolean(token && ordersTokens.has(token)),
    orderEnabled: runtimeSettings.orderEnabled,
  });

  if (!autoEntryPolicy.allowed) {
    const error = new Error('Auto Binance bị khóa: tín hiệu không thuộc card đã bật LỆNH THẬT trong Orders.');
    error.code = autoEntryPolicy.reason;
    error.policyVersion = AUTO_BINANCE_ENTRY_POLICY_VERSION;
    throw error;
  }

  if (!['BUY', 'SELL'].includes(side)) {
    throw new Error('Invalid order side.');
  }

  const isLimitIOC = orderType === 'LIMIT_IOC';
  if (!['MARKET', 'LIMIT', 'LIMIT_IOC'].includes(orderType)) {
    throw new Error('Invalid order type.');
  }

  if (!Number.isFinite(notionalUsdt) || notionalUsdt <= 0) {
    throw new Error('Order notional must be greater than 0.');
  }

  if (orderType === 'LIMIT' && (!Number.isFinite(limitPrice) || limitPrice <= 0)) {
    throw new Error('Limit price must be greater than 0.');
  }

  const urgentOrderReadOptions = executionContext?.liveCard === true
    ? {
        priority: 1,
        dropOnCongestion: false,
        dedupeKey: `live-card-order-premium:${symbol}`,
        source: 'liveCardOrder:premiumIndex',
      }
    : {};
  const [symbols, premiumIndex] = await Promise.all([
    getSymbols(),
    client.getPremiumIndex(symbol, urgentOrderReadOptions),
  ]);
  const symbolInfo = symbols.find((item) => item.symbol === symbol);

  if (!symbolInfo) {
    throw new Error(`Symbol ${symbol} is not a trading USDT perpetual futures symbol.`);
  }

  const markPrice = Number(premiumIndex.markPrice);
  const roundedLimitPrice = limitPrice
    ? priceFromTick(symbolInfo, limitPrice)
    : null;
  const executionPrice = roundedLimitPrice ? Number(roundedLimitPrice) : markPrice;
  const quantity = quantityFromNotional(symbolInfo, notionalUsdt, executionPrice, dryRun, {
    allowMinNotionalCeil: payload.allowMinNotionalCeil === true,
  });
  const takeProfitPolicy = resolveOrdersManualTakeProfit({
    side,
    source: protectionSource,
    entryPrice: executionPrice,
    leverage,
    requestedTakeProfitPrice: takeProfitPrice,
  }) ?? resolveNonLiquidFlowV2TakeProfit({
    side,
    source: protectionSource,
    entryPrice: executionPrice,
    leverage,
    requestedTakeProfitPrice: takeProfitPrice,
    shortRoePct: Number(payload.takeProfitRoePct) > 0 ? Number(payload.takeProfitRoePct) : undefined,
    longRoePct: Number(payload.takeProfitRoePct) > 0 ? Number(payload.takeProfitRoePct) : undefined,
  });
  const effectiveTakeProfitPrice = takeProfitPolicy.takeProfitPrice;
  const roundedTakeProfitPrice = effectiveTakeProfitPrice
    ? priceFromTick(symbolInfo, effectiveTakeProfitPrice)
    : null;
  const roundedStopLossPrice = stopLossPrice
    ? priceFromTick(symbolInfo, stopLossPrice)
    : null;
  // Every attached TP/SL waits for Binance's full-fill user-data event. This
  // prevents protection from being submitted against an unfilled LIMIT entry.
  const requestedProtectionOnFill = payload.protectionOnFill === true
    || roundedTakeProfitPrice != null
    || roundedStopLossPrice != null;
  let protectionOnFill = requestedProtectionOnFill;
  let protectionSuppressedForDca = false;
  const plannedOrder = {
    enabled: runtimeSettings.orderEnabled,
    dryRun,
    baseUrl: process.env.BINANCE_FUTURES_BASE_URL ?? 'https://fapi.binance.com',
    symbol,
    side,
    type: orderType,
    notionalUsdt,
    markPrice,
    limitPrice: roundedLimitPrice,
    quantity,
    leverage,
    takeProfitPrice: roundedTakeProfitPrice,
    stopLossPrice: roundedStopLossPrice,
    takeProfitPolicyVersion: takeProfitPolicy.version,
    protectionOnFill: requestedProtectionOnFill,
    protectionSuppressedForDca: false,
  };

  if (dryRun || !runtimeSettings.orderEnabled) {
    return {
      status: 'planned',
      message: dryRun
        ? 'Dry run only. No order was sent to Binance.'
        : 'Order execution is disabled. Enable it in Settings.',
      order: plannedOrder,
    };
  }

  const { apiKey, apiSecret } = credentialsOverride ?? getApiCredentials(token);

  let positionsForOrder = Array.isArray(executionContext?.positions)
    ? executionContext.positions
    : null;
  if ((maxOpenPositions > 0 || requestedProtectionOnFill) && !positionsForOrder) {
    positionsForOrder ??= await client.getPositions({
      apiKey,
      apiSecret,
      ...(executionContext?.liveCard === true
        ? {
            priority: 1,
            dropOnCongestion: false,
            dedupeKey: 'live-card-order-max-positions',
            source: 'liveCardOrder:maxPositions',
          }
        : {}),
    });
  }
  if (maxOpenPositions > 0) {
    const openCount = (positionsForOrder ?? []).filter((p) => Number(p.positionAmt) !== 0).length;
    if (openCount >= maxOpenPositions) {
      throw new Error(`Max open positions (${maxOpenPositions}) reached. Currently ${openCount} open.`);
    }
  }
  const dcaPositionState = inspectLiquidFlowV2DcaPositions({
    positions: positionsForOrder ?? [],
    symbol,
    side: side === 'BUY' ? 'LONG' : 'SHORT',
  });
  if (requestedProtectionOnFill && dcaPositionState.hasExistingSameSide) {
    protectionOnFill = false;
    protectionSuppressedForDca = true;
    plannedOrder.protectionOnFill = false;
    plannedOrder.protectionSuppressedForDca = true;
    console.log(
      `[DcaProtection] ${symbol} ${side}: keep existing TP/SL; no new protection plan/order;`
      + ` ${BINANCE_DCA_KEEP_PROTECTION_VERSION}`,
    );
  }

  const orderParams = {
    symbol,
    side,
    type: orderType,
    quantity,
    recvWindow,
    newClientOrderId: requestedClientOrderId || `lp_${Date.now()}`,
  };

  if (orderType === 'LIMIT') {
    orderParams.price = roundedLimitPrice;
    orderParams.timeInForce = 'GTC';
  }
  if (isLimitIOC) {
    orderParams.type = 'LIMIT';
    orderParams.price = roundedLimitPrice;
    orderParams.timeInForce = 'IOC';
  }
  const isHedge = await getHedgeMode(
    token,
    credentialsOverride,
    executionContext?.liveCard === true
      ? {
          priority: 1,
          dropOnCongestion: false,
          dedupeKey: 'live-card-order-position-mode',
          source: 'liveCardOrder:positionMode',
        }
      : {},
  );
  const closeSide = side === 'BUY' ? 'SELL' : 'BUY';
  const positionSide = isHedge ? (side === 'BUY' ? 'LONG' : 'SHORT') : undefined;

  const tpSlBase = (type, triggerPrice, clientId) => {
    const p = { algoType: 'CONDITIONAL', symbol, side: closeSide, type, triggerPrice, quantity, workingType: 'MARK_PRICE', recvWindow, newClientOrderId: clientId };
    if (isHedge) p.positionSide = positionSide;
    else p.reduceOnly = 'true';
    return p;
  };

  if (isHedge) orderParams.positionSide = positionSide;

  const supportsStopMarket = !symbolInfo.orderTypes?.length || symbolInfo.orderTypes.includes('STOP_MARKET');
  const supportsTpMarket = !symbolInfo.orderTypes?.length || symbolInfo.orderTypes.includes('TAKE_PROFIT_MARKET');

  const takeProfitParams = roundedTakeProfitPrice && supportsTpMarket
    ? tpSlBase('TAKE_PROFIT_MARKET', roundedTakeProfitPrice, `lp_tp_${Date.now()}`)
    : null;
  const stopLossParams = roundedStopLossPrice && supportsStopMarket
    ? tpSlBase('STOP_MARKET', roundedStopLossPrice, `lp_sl_${Date.now()}`)
    : null;
  const positionLeverage = Number(positionsForOrder?.find((position) => position.symbol === symbol)?.leverage);
  const leverageAlreadySet = Number.isFinite(positionLeverage) && positionLeverage === leverage;
  const leverageResult = leverageAlreadySet
    ? { symbol, leverage, skipped: true, reason: 'PREFLIGHT_LEVERAGE_ALREADY_SET' }
    : await client.setLeverage({
        symbol,
        leverage,
        apiKey,
        apiSecret,
        recvWindow,
      });
  if (protectionOnFill) {
    const policyTakeProfitDistanceFraction = takeProfitPolicy.applied
      ? (takeProfitPolicy.roePct / 100) / leverage
      : payload.takeProfitDistanceFraction;
    rememberSignalProtectionPlan({
      symbol,
      side,
      takeProfitPrice: roundedTakeProfitPrice,
      stopLossPrice: roundedStopLossPrice,
      signalEntryPrice: payload.protectionSignalEntryPrice,
      signalTakeProfitPrice: takeProfitPolicy.applied
        ? roundedTakeProfitPrice
        : payload.protectionSignalTakeProfitPrice ?? roundedTakeProfitPrice,
      signalStopLossPrice: payload.protectionSignalStopLossPrice ?? roundedStopLossPrice,
      fillAnchorEnabled: payload.fillAnchorEnabled,
      fillAnchorVersion: payload.fillAnchorVersion,
      takeProfitDistanceFraction: policyTakeProfitDistanceFraction,
      stopLossDistanceFraction: payload.stopLossDistanceFraction,
      source: protectionSource,
      entryClientOrderId: orderParams.newClientOrderId,
      lifecycleId: protectionMeta.lifecycleId ?? null,
      ...protectionPolicy,
    });
  }

  let orderResult;
  try {
    orderResult = await client.placeFuturesOrder({ params: orderParams, apiKey, apiSecret });
  } catch (err) {
    if (protectionOnFill) signalProtectionPlans.delete(symbol);
    throw err;
  }

  // LIMIT IOC: if not filled, fall back to MARKET immediately
  if (isLimitIOC && Number(orderResult.executedQty ?? 0) === 0) {
    console.log(`[Order] ${symbol} IOC not filled → MARKET fallback`);
    const marketParams = { ...orderParams, type: 'MARKET', timeInForce: undefined };
    delete marketParams.price;
    delete marketParams.timeInForce;
    orderResult = await client.placeFuturesOrder({ params: marketParams, apiKey, apiSecret });
  }
  if (!protectionSuppressedForDca && !protectionOnFill
    && takeProfitPolicy.applied && takeProfitParams && Number(orderResult?.avgPrice) > 0) {
    const fillAnchoredTakeProfit = resolveNonLiquidFlowV2TakeProfit({
      side,
      source: protectionSource,
      entryPrice: Number(orderResult.avgPrice),
      leverage,
      requestedTakeProfitPrice: takeProfitParams.triggerPrice,
      shortRoePct: Number(payload.takeProfitRoePct) > 0 ? Number(payload.takeProfitRoePct) : undefined,
      longRoePct: Number(payload.takeProfitRoePct) > 0 ? Number(payload.takeProfitRoePct) : undefined,
    });
    takeProfitParams.triggerPrice = String(priceFromTick(symbolInfo, fillAnchoredTakeProfit.takeProfitPrice));
  }
  const takeProfitResult = !protectionSuppressedForDca && !protectionOnFill && takeProfitParams
    ? await client.placeAlgoOrder({ params: takeProfitParams, apiKey, apiSecret })
    : null;
  const stopLossResult = !protectionSuppressedForDca && !protectionOnFill && stopLossParams
    ? await client.placeAlgoOrder({ params: stopLossParams, apiKey, apiSecret })
    : null;

  if (protectionOnFill) {
    const plan = signalProtectionPlans.get(symbol);
    if (plan) {
      plan.orderId = orderResult?.orderId ?? null;
      plan.entryClientOrderId = orderResult?.clientOrderId ?? orderParams.newClientOrderId;
      plan.submittedQty = Number(quantity) || null;
    }
  }

  trackSubmittedOrderPosition({
    symbol,
    side,
    quantity,
    leverage,
    markPrice,
    orderResult,
    isHedge,
    positionSide,
    orderType,
  });

  return {
    status: 'submitted',
    message: 'Order submitted to Binance.',
    order: plannedOrder,
    leverageResult,
    orderResult,
    takeProfitResult,
    stopLossResult,
    protectionSuppressedForDca,
    dcaProtectionPolicyVersion: protectionSuppressedForDca ? BINANCE_DCA_KEEP_PROTECTION_VERSION : null,
  };
}

function trackSubmittedOrderPosition({ symbol, side, quantity, leverage, markPrice, orderResult, isHedge, positionSide, orderType }) {
  if (!posMonitor) return;
  const executedQty = Number(orderResult?.executedQty ?? 0);
  if (executedQty <= 0) return;

  const avgPrice = Number(orderResult?.avgPrice ?? orderResult?.price ?? 0) || markPrice;
  const amt = (side === 'BUY' ? 1 : -1) * executedQty;
  posMonitor.trackPosition(symbol, {
    amt,
    entry: avgPrice,
    leverage,
    positionSide: isHedge ? positionSide : 'BOTH',
  });
  console.log(`[PosMonitor] Seeded ${symbol} from submitted ${orderType} order qty=${executedQty} entry=${avgPrice}`);
}

async function setTpSl(payload, token = null) {
  const symbol = normalizeSymbol(payload.symbol ?? '');
  if (!symbol) throw new Error('symbol is required.');
  let tpPrice = payload.tpPrice !== '' && payload.tpPrice != null ? Number(payload.tpPrice) : null;
  const slPrice = payload.slPrice !== '' && payload.slPrice != null ? Number(payload.slPrice) : null;
  const clientIdPrefix = String(payload.clientIdPrefix ?? 'lp')
    .replace(/[^a-zA-Z0-9_\-]/g, '')
    .slice(0, 24) || 'lp';
  const protectionSource = String(payload.source ?? 'set-tp-sl');
  const protectionPolicy = resolveSignalProtectionWorkingTypes({
    source: protectionSource,
    takeProfitWorkingType: payload.takeProfitWorkingType,
    stopLossWorkingType: payload.stopLossWorkingType,
  });
  if (!tpPrice && !slPrice) throw new Error('Nhập ít nhất một trong hai: TP price hoặc SL price.');

  const { apiKey, apiSecret } = getApiCredentials(token);
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

  const [symbols, openOrders, algoResult, positions] = await Promise.all([
    getSymbols(),
    client.getOpenOrders({ apiKey, apiSecret }),
    client.getOpenAlgoOrders({ apiKey, apiSecret }),
    client.getPositions({ apiKey, apiSecret }),
  ]);

  const symbolInfo = symbols.find((s) => s.symbol === symbol);
  if (!symbolInfo) throw new Error(`Symbol ${symbol} không tìm thấy.`);

  const pos = positions.find((p) => p.symbol === symbol && Number(p.positionAmt) !== 0);
  if (!pos) throw new Error(`Không có vị thế mở cho ${symbol}.`);

  const isHedge = String(pos.positionSide ?? 'BOTH') !== 'BOTH';
  const positionSide = pos.positionSide ?? 'BOTH';
  const isLong = Number(pos.positionAmt) > 0;
  const closeSide = isLong ? 'SELL' : 'BUY';
  const allAlgo = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];

  const takeProfitPolicy = resolveNonLiquidFlowV2TakeProfit({
    side: isLong ? 'LONG' : 'SHORT',
    source: protectionSource,
    entryPrice: Number(pos.entryPrice),
    leverage: Number(pos.leverage) || 1,
    requestedTakeProfitPrice: tpPrice,
  });
  if (takeProfitPolicy.applied) {
    tpPrice = takeProfitPolicy.takeProfitPrice;
    console.log(`[SetTpSl] ${symbol} ${takeProfitPolicy.direction} TP fixed at ${takeProfitPolicy.roePct}% ROE version=${takeProfitPolicy.version}`);
  }

  const markPrice = Number((await client.getPremiumIndex(symbol)).markPrice);
  const isTpTypeRegular = (t) => { const u = String(t ?? '').toUpperCase(); return u === 'TAKE_PROFIT_MARKET' || u === 'TAKE_PROFIT'; };
  const isSlTypeRegular = (t) => { const u = String(t ?? '').toUpperCase(); return u === 'STOP_MARKET' || u === 'STOP'; };
  // TP: trigger chưa chạm (còn xa hơn mark theo hướng lãi). SL/TSL: trigger đã qua mark hoặc phía lỗ.
  const isAlgoTp = (o) => { const t = Number(o.triggerPrice ?? 0); return t > 0 && (isLong ? t > markPrice : t < markPrice); };
  const isAlgoSl = (o) => { const t = Number(o.triggerPrice ?? 0); return t > 0 && (isLong ? t < markPrice : t > markPrice); };

  const cancelled = { tp: [], sl: [] };
  const placed = { tp: null, sl: null };

  const matchesPosition = (o) => {
    if (String(o?.symbol ?? '').toUpperCase() !== symbol) return false;
    if (String(o?.side ?? '').toUpperCase() !== closeSide) return false;
    return String(o?.positionSide ?? 'BOTH').toUpperCase() === String(positionSide).toUpperCase();
  };
  const protectionState = (regularRows, algoRows) => ({
    hasTp: hasOpenProtectionOrder(regularRows, algoRows, {
      symbol, closeSide, positionSide, kind: 'TP',
    }) || algoRows.some((o) => matchesPosition(o) && isAlgoTp(o)),
    hasSl: hasOpenProtectionOrder(regularRows, algoRows, {
      symbol, closeSide, positionSide, kind: 'SL',
    }) || algoRows.some((o) => matchesPosition(o) && isAlgoSl(o)),
  });
  let { hasTp, hasSl } = protectionState(openOrders, allAlgo);

  const tpSlBase = (type, triggerPrice, workingType, clientId) => {
    return buildClosePositionProtectionParams({
      symbol,
      closeSide,
      type,
      triggerPrice: String(priceFromTick(symbolInfo, triggerPrice)),
      positionSide: isHedge ? positionSide : 'BOTH',
      workingType,
      recvWindow,
      clientAlgoId: clientId,
    });
  };

  // Re-read immediately before placement. If Binance cannot answer, fail closed
  // instead of assuming protection is missing and creating a duplicate.
  if ((tpPrice && !hasTp) || (slPrice && !hasSl)) {
    const [freshRegular, freshAlgoResult] = await Promise.all([
      client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
      client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }),
    ]);
    const freshAlgo = Array.isArray(freshAlgoResult?.orders)
      ? freshAlgoResult.orders
      : Array.isArray(freshAlgoResult) ? freshAlgoResult : [];
    ({ hasTp, hasSl } = protectionState(freshRegular, freshAlgo));
  }

  if (tpPrice && !hasTp) {
    const params = tpSlBase(
      'TAKE_PROFIT_MARKET',
      tpPrice,
      protectionPolicy.takeProfitWorkingType,
      `${clientIdPrefix}_tp_${Date.now().toString(36)}`.slice(0, 36),
    );
    placed.tp = await client.placeAlgoOrder({ params, apiKey, apiSecret });
  } else if (tpPrice) {
    console.log(`[SetTpSl] ${symbol} TP skipped: existing protection retained`);
  }
  if (slPrice && !hasSl) {
    const params = tpSlBase(
      'STOP_MARKET',
      slPrice,
      protectionPolicy.stopLossWorkingType,
      `${clientIdPrefix}_sl_${Date.now().toString(36)}`.slice(0, 36),
    );
    placed.sl = await client.placeAlgoOrder({ params, apiKey, apiSecret });
  } else if (slPrice) {
    console.log(`[SetTpSl] ${symbol} SL skipped: existing protection retained`);
  }

  console.log(`[SetTpSl] ${symbol} tp=${tpPrice ?? '-'}(${protectionPolicy.takeProfitWorkingType}) sl=${slPrice ?? '-'}(${protectionPolicy.stopLossWorkingType}) cancelled=${JSON.stringify(cancelled)} version=${BINANCE_CLOSE_POSITION_PROTECTION_VERSION}`);
  return {
    symbol,
    cancelled,
    placed,
    takeProfitPrice: placed.tp ? tpPrice : null,
    takeProfitPolicyVersion: takeProfitPolicy.version,
    ...protectionPolicy,
  };
}

async function getMarketSnapshot() {
  if (snapshotCache.data && Date.now() < snapshotCache.expiresAt) return snapshotCache.data;
  // Deduplicate concurrent calls — all callers await the same in-flight promise
  if (snapshotCache.inflight) return snapshotCache.inflight;
  snapshotCache.inflight = (async () => {
    try {
      return await _fetchMarketSnapshot();
    } finally {
      snapshotCache.inflight = null;
    }
  })();
  return snapshotCache.inflight;
}

function liquidSweepProb(heatmap, target = null) {
  const above = Number(heatmap?.liquidityAbove ?? 0);
  const below = Number(heatmap?.liquidityBelow ?? 0);
  const total = above + below;
  if (total <= 0) return 0;
  const bias = Number(heatmap?.bias ?? 0);
  const dominant = bias >= 0 ? above : below;
  const dominantPct = dominant / total;
  const imbalanceScore = clamp(Math.abs(bias), 0, 1);
  const dominanceScore = clamp((dominantPct - 0.5) / 0.5, 0, 1);
  const distanceAbs = Math.abs(Number(target?.distancePct ?? 8));
  const distanceScore = clamp((6 - distanceAbs) / 6, 0, 1);
  const targetShare = target?.score && dominant > 0 ? clamp(Number(target.score) / dominant, 0, 1) : 0;

  const probability = (
    imbalanceScore * 0.45
    + dominanceScore * 0.20
    + distanceScore * 0.25
    + targetShare * 0.10
  ) * 100;

  return Math.min(99, Math.max(0, Math.round(probability)));
}

function liquidSweepLabel(prob) {
  if (prob >= 80) return 'CAO';
  if (prob >= 55) return 'TRUNG BINH';
  return 'THAP';
}

function buildLiquidEntryPlan({ heavySide, markPrice, target, heatmap, killZoneCluster = null }) {
  const side = heavySide === 'above' ? 'LONG' : 'SHORT';
  const sweepDirection = heavySide === 'above' ? 'UP' : 'DOWN';
  const targetPrice = Number(target?.price ?? markPrice);
  const distancePct = Number(target?.distancePct ?? 0);
  const killZoneTarget = Number(killZoneCluster?.mainKillZone?.mid ?? 0);
  const hasKillZoneTarget = killZoneTarget > 0
    && ((side === 'LONG' && killZoneTarget > targetPrice) || (side === 'SHORT' && killZoneTarget < targetPrice));
  const planTargetPrice = hasKillZoneTarget ? killZoneTarget : targetPrice;
  const planTargetDistancePct = markPrice > 0 ? ((planTargetPrice - markPrice) / markPrice) * 100 : distancePct;
  const nearestOpposite = side === 'LONG'
    ? (heatmap.heatmapBelow?.[0] ?? null)
    : (heatmap.heatmapAbove?.[0] ?? null);
  const tp = planTargetPrice;
  const entryOffsetPct = Math.max(0.12, Math.min(0.55, Math.abs(planTargetDistancePct) * 0.28));
  const entryPrice = side === 'LONG'
    ? markPrice * (1 - entryOffsetPct / 100)
    : markPrice * (1 + entryOffsetPct / 100);
  const stopPct = Math.max(0.8, Math.min(2.5, Math.abs(planTargetDistancePct) * 0.75));
  const fallbackSl = side === 'LONG'
    ? entryPrice * (1 - stopPct / 100)
    : entryPrice * (1 + stopPct / 100);
  // Never tighter than fallbackSl — if nearestOpposite is too close it causes instant SL hit
  const rawSl = nearestOpposite?.price ?? fallbackSl;
  const sl = side === 'LONG' ? Math.min(rawSl, fallbackSl) : Math.max(rawSl, fallbackSl);
  const rewardPct = Math.abs((tp - entryPrice) / entryPrice * 100);
  const riskPct = Math.abs((entryPrice - sl) / entryPrice * 100);
  const rr = riskPct > 0 ? rewardPct / riskPct : null;
  const feasibleLeverage = Math.max(1, Math.min(10, Math.floor(10 / Math.max(stopPct, 0.5))));
  const feasibilityScore = Math.round(clamp(
    (rewardPct / 3) * 45
    + (Math.min(rr ?? 0, 3) / 3) * 35
    + (Math.min(Math.abs(planTargetDistancePct), 6) / 6) * 20,
    0,
    100,
  ));

  return {
    side,
    sweepDirection,
    entryPrice,
    entryDistancePct: side === 'LONG' ? -entryOffsetPct : entryOffsetPct,
    entryType: 'LIMIT_PULLBACK',
    takeProfitPrice: tp,
    stopLossPrice: sl,
    targetPrice,
    targetDistancePct: planTargetDistancePct,
    sweepTargetPrice: targetPrice,
    sweepTargetDistancePct: distancePct,
    killZoneCluster,
    killZoneTakeProfitPrice: hasKillZoneTarget ? tp : null,
    rewardPct,
    riskPct,
    rr,
    feasibleLeverage,
    feasibilityScore,
    status: 'ENTER_NOW',
    note: heavySide === 'above'
      ? (hasKillZoneTarget ? 'Thanh khoản trên một chiều: LONG theo lực hút, TP ưu tiên main kill zone.' : 'Thanh khoản trên dày: vào LONG theo hướng hút lên target.')
      : (hasKillZoneTarget ? 'Thanh khoản dưới một chiều: SHORT theo lực kéo, TP ưu tiên main kill zone.' : 'Thanh khoản dưới dày: vào SHORT theo hướng kéo xuống target.'),
  };
}

function calcLiquidRsi(closes, period = 14) {
  if (!Array.isArray(closes) || closes.length <= period) return null;
  let gains = 0;
  let losses = 0;
  for (let i = 1; i <= period; i += 1) {
    const diff = closes[i] - closes[i - 1];
    if (diff >= 0) gains += diff;
    else losses -= diff;
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  for (let i = period + 1; i < closes.length; i += 1) {
    const diff = closes[i] - closes[i - 1];
    avgGain = (avgGain * (period - 1) + Math.max(diff, 0)) / period;
    avgLoss = (avgLoss * (period - 1) + Math.max(-diff, 0)) / period;
  }
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

function calcLiquidEma(values, period) {
  if (!Array.isArray(values) || values.length < period) return null;
  const k = 2 / (period + 1);
  let ema = values.slice(0, period).reduce((sum, value) => sum + value, 0) / period;
  for (let i = period; i < values.length; i += 1) {
    ema = values[i] * k + ema * (1 - k);
  }
  return ema;
}

function detectLiquidationHuntPattern({ row, klines, heatmap, target, heavySide, interval }) {
  const closed = klines.slice(0, -1);
  if (closed.length < 80 || !target) return null;

  const recent = closed.slice(-8);
  const prior = closed.slice(-48, -8);
  const last = closed.at(-1);
  const closes = closed.map((k) => k.close);
  const volumes = closed.map((k) => k.quoteVolume);
  const avgVol = prior.length ? prior.reduce((sum, k) => sum + k.quoteVolume, 0) / prior.length : 0;
  const recentVol = recent.reduce((sum, k) => sum + k.quoteVolume, 0);
  const avgRecentVol = avgVol * Math.max(recent.length, 1);
  const volX = avgRecentVol > 0 ? recentVol / avgRecentVol : 0;
  const greenCount = recent.filter((k) => k.close > k.open).length;
  const redCount = recent.filter((k) => k.close < k.open).length;
  const rsi = calcLiquidRsi(closes, 14);
  const ema13 = calcLiquidEma(closes, 13);
  const ema25 = calcLiquidEma(closes, 25);
  const ema99 = calcLiquidEma(closes, 99);
  const runupBase = closed[Math.max(0, closed.length - 17)]?.close ?? closed[0]?.close;
  const runupPct = runupBase > 0 ? ((last.close - runupBase) / runupBase) * 100 : 0;
  const drawdownBase = closed[Math.max(0, closed.length - 17)]?.close ?? closed[0]?.close;
  const drawdownPct = drawdownBase > 0 ? ((drawdownBase - last.close) / drawdownBase) * 100 : 0;
  const distancePct = Number(target.distancePct ?? 999);
  const absDistance = Math.abs(distancePct);
  const isNearTarget = absDistance <= Number(process.env.LIQ_HUNT_MAX_TARGET_DISTANCE_PCT ?? 1.2);
  const targetIntensity = Number(target.intensity ?? 0);
  const targetStrong = targetIntensity >= 0.45 || Number(target.score ?? 0) >= Math.max(Number(heatmap.liquidityAbove ?? 0), Number(heatmap.liquidityBelow ?? 0)) * 0.08;
  const rsiHot = rsi != null && rsi >= Number(process.env.LIQ_HUNT_RSI_HOT ?? 78);
  const rsiCold = rsi != null && rsi <= Number(process.env.LIQ_HUNT_RSI_COLD ?? 22);
  const emaBull = ema13 != null && ema25 != null && ema99 != null && last.close > ema13 && ema13 > ema25 && ema25 > ema99;
  const emaBear = ema13 != null && ema25 != null && ema99 != null && last.close < ema13 && ema13 < ema25 && ema25 < ema99;
  const strongUp = runupPct >= Number(process.env.LIQ_HUNT_RUNUP_PCT ?? 4.0) || Number(row.change24hPct ?? 0) >= 10;
  const strongDown = drawdownPct >= Number(process.env.LIQ_HUNT_DRAWDOWN_PCT ?? 4.0) || Number(row.change24hPct ?? 0) <= -10;
  const volHot = volX >= Number(process.env.LIQ_HUNT_VOL_X ?? 1.8);

  const isUpsideHunt = heavySide === 'above'
    && distancePct > 0
    && isNearTarget
    && targetStrong
    && strongUp
    && greenCount >= 5
    && volHot
    && (rsiHot || emaBull);

  const isDownsideHunt = heavySide === 'below'
    && distancePct < 0
    && isNearTarget
    && targetStrong
    && strongDown
    && redCount >= 5
    && volHot
    && (rsiCold || emaBear);

  if (!isUpsideHunt && !isDownsideHunt) return null;

  const score = Math.round(clamp(
    (isUpsideHunt ? Math.min(runupPct / 14, 1) : Math.min(drawdownPct / 14, 1)) * 28
    + Math.min(volX / 4, 1) * 22
    + Math.min(absDistance <= 0.15 ? 1 : (1.2 - absDistance) / 1.05, 1) * 20
    + Math.min(targetIntensity || 0.6, 1) * 16
    + (isUpsideHunt ? Math.min((rsi ?? 50) / 100, 1) : Math.min((100 - (rsi ?? 50)) / 100, 1)) * 14,
    0,
    100,
  ));

  return {
    type: isUpsideHunt ? 'LIQUIDITY_RUNUP_HUNT' : 'LIQUIDITY_DUMP_HUNT',
    side: isUpsideHunt ? 'UP' : 'DOWN',
    score,
    interval,
    targetPrice: target.price,
    targetDistancePct: distancePct,
    targetIntensity,
    runupPct,
    drawdownPct,
    volX,
    greenCount,
    redCount,
    rsi,
    emaStack: isUpsideHunt ? (emaBull ? 'bull' : 'hot') : (emaBear ? 'bear' : 'cold'),
    note: isUpsideHunt
      ? 'Pump manh, volume xanh bung no, RSI nong va gia dang hut len cum thanh ly tren.'
      : 'Dump manh, volume do bung no, RSI lanh va gia dang hut xuong cum thanh ly duoi.',
  };
}

async function mapConcurrent(items, concurrency, mapper) {
  const results = new Array(items.length);
  let cursor = 0;
  const workers = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (cursor < items.length) {
      const index = cursor++;
      results[index] = await mapper(items[index], index);
    }
  });
  await Promise.all(workers);
  return results;
}

async function runLiquidScan({ interval = '15m', limit = 200, minVolumeUsdt = 0 } = {}) {
  const snapshot = await getSharedSnapshot();
  const candidates = snapshot
    .filter((row) => row.quoteVolume >= minVolumeUsdt)
    .sort((a, b) => b.quoteVolume - a.quoteVolume)
    .slice(0, limit);

  const rows = await mapConcurrent(candidates, 8, async (row) => {
    try {
      const klines = await klineCache.getKlines(row.symbol, interval, 500);
      if (!klines || klines.length < 60) return null;
      const heatmap = computeHeatmapData({ klines, currentPrice: row.markPrice, momentumPct: row.change24hPct });
      const above = Number(heatmap.liquidityAbove ?? 0);
      const below = Number(heatmap.liquidityBelow ?? 0);
      const total = above + below;
      const bias = Number(heatmap.bias ?? 0);
      const heavySide = bias >= 0 ? 'above' : 'below';
      const heavyLiquidity = heavySide === 'above' ? above : below;
      const heavyPct = total > 0 ? heavyLiquidity / total * 100 : 0;
      const target = heatmap.sweepTarget ?? (
        heavySide === 'above'
          ? (heatmap.heatmapAbove?.[0] ?? null)
          : (heatmap.heatmapBelow?.[0] ?? null)
      );
      const targetDistancePct = target?.distancePct ?? null;
      const sweepProb = liquidSweepProb(heatmap, target);
      const isNearTarget = targetDistancePct != null && Math.abs(targetDistancePct) <= 0.35;
      const killZoneCluster = heatmap.killZoneCluster ?? null;
      const entryPlan = buildLiquidEntryPlan({ heavySide, markPrice: row.markPrice, target, heatmap, killZoneCluster });
      const huntSignal = detectLiquidationHuntPattern({ row, klines, heatmap, target, heavySide, interval });

      return {
        symbol: row.symbol,
        markPrice: row.markPrice,
        quoteVolume: row.quoteVolume,
        change24hPct: row.change24hPct,
        fundingRate: row.fundingRate,
        interval,
        liquidityAbove: above,
        liquidityBelow: below,
        totalLiquidity: total,
        bias,
        heavySide,
        heavyPct,
        sweepProb,
        sweepLabel: liquidSweepLabel(sweepProb),
        huntSignal,
        killZoneCluster,
        sweepTarget: target ? {
          direction: target.direction ?? heavySide,
          price: target.price,
          distancePct: target.distancePct,
          score: target.score,
        } : null,
        entryPlan,
        isNearTarget,
        strongestAbove: (heatmap.strongestAbove ?? heatmap.heatmapAbove ?? []).slice(0, 3),
        strongestBelow: (heatmap.strongestBelow ?? heatmap.heatmapBelow ?? []).slice(0, 3),
      };
    } catch (err) {
      return {
        symbol: row.symbol,
        markPrice: row.markPrice,
        quoteVolume: row.quoteVolume,
        change24hPct: row.change24hPct,
        interval,
        error: err.message,
      };
    }
  });

  const successful = rows.filter((row) => row && !row.error);
  successful.sort((a, b) => b.sweepProb - a.sweepProb || Math.abs(b.bias) - Math.abs(a.bias) || b.quoteVolume - a.quoteVolume);

  return {
    scannedAt: Date.now(),
    interval,
    requested: limit,
    processed: successful.length,
    failed: rows.length - successful.length,
    rows: successful,
    errors: rows.filter((row) => row?.error).slice(0, 10),
    cacheStats: klineCache.stats(interval),
  };
}

function liquidFlowV2SignalCandleClosedAt(row = {}, classification = {}) {
  return Number(
    classification.signalCandleClosedAt
    ?? classification.signalLiveCandleOpenAt
    ?? classification.pumpFlushReadyAt
    ?? classification.flagpoleShortKillReadyAt
    ?? classification.emaFanReadyAt
    ?? classification.postPumpReadyAt
    ?? classification.ema99RetestCandleClosedAt
    ?? row?.features?.emaFanLong5m?.readyAt
    ?? row?.features?.emaFanShort5m?.readyAt
    ?? row?.features?.postPumpShortSqueeze5m?.readyAt
    ?? row?.features?.flagpoleShortKill5m?.readyAt
    ?? row?.features?.fadingWaveLivePump5m?.liveCandleOpenAt
    ?? row?.features?.pumpFlushReclaim5m?.readyAt
    ?? row?.features?.pumpDistribution15m?.readyAt
    ?? row?.features?.ema99Retest5m?.candleClosedAt
    ?? row?.features?.ema99Retest15m?.candleClosedAt
    ?? row?.features?.candleClosedAt
    ?? 0
  );
}

function noteLiquidFlowV2Transitions(rows = []) {
  const primaryReadySymbols = new Set();
  const readyLabelKeys = new Set();
  for (const row of rows) {
    const symbol = String(row?.symbol ?? '').toUpperCase();
    if (!symbol) continue;
    const recoveringFromStale = liquidFlowV2Session.staleSymbols.has(symbol);
    if (row?.dataFreshness?.stale === true) liquidFlowV2Session.staleSymbols.add(symbol);
    else liquidFlowV2Session.staleSymbols.delete(symbol);
    const classifications = [
      row?.classification,
      ...(Array.isArray(row?.classification?.secondaryLabels) ? row.classification.secondaryLabels : []),
    ].filter((classification) => classification && classification.labelKey !== 'WAIT');
    const current = new Set(classifications.map((classification) => String(classification.labelKey)));
    const alreadyObserved = liquidFlowV2Session.lastLabelBySymbol.has(symbol);
    const previousValue = liquidFlowV2Session.lastLabelBySymbol.get(symbol);
    const previous = previousValue instanceof Set
      ? previousValue
      : new Set(previousValue && previousValue !== 'WAIT' ? [String(previousValue)] : []);
    liquidFlowV2Session.lastLabelBySymbol.set(symbol, current);
    for (const classification of classifications) {
      const labelKey = String(classification.labelKey);
      if (previous.has(labelKey)) continue;
      const signalCandleClosedAt = liquidFlowV2SignalCandleClosedAt(row, classification);
      if (suppressLiquidFlowV2RecoveredSignal({
        recoveringFromStale,
        signalCandleClosedAt,
      })) continue;
      const freshEmaFanFirstObservation = [
        'EMA_FAN_LONG_READY',
        'EMA_FAN_LONG_IMPULSE_RUNNER',
        'EMA_FAN_SHORT_READY',
      ].includes(labelKey)
        && signalCandleClosedAt > liquidFlowV2Session.startedAt
        && Date.now() - signalCandleClosedAt <= 15 * 60_000;
      const freshPostPumpFirstObservation = [
        'POST_PUMP_SHORT_SQUEEZE_LONG_READY',
        'POST_PUMP_SHORT_SQUEEZE_PRIME',
      ].includes(labelKey)
        && signalCandleClosedAt > 0
        && Date.now() - signalCandleClosedAt <= 15 * 60_000;
      const freshKillLongFirstObservation = labelKey === 'KILL_LONG_EXHAUSTION_RECLAIM_LONG_READY'
        && signalCandleClosedAt > 0
        && Date.now() - signalCandleClosedAt <= 15 * 60_000;
      const freshPumpFlushFirstObservation = labelKey === 'PUMP_FLUSH_RECLAIM_LONG_READY'
        && signalCandleClosedAt > 0
        && Date.now() - signalCandleClosedAt <= 15 * 60_000;
      const freshFlagpoleShortKillFirstObservation = labelKey === 'POST_PUMP_FLAGPOLE_SHORT_KILL_LONG_READY'
        && signalCandleClosedAt > 0
        && Date.now() - signalCandleClosedAt <= 15 * 60_000;
      const freshFadingWaveLivePumpFirstObservation = labelKey === 'FADING_WAVE_LIVE_PUMP_SHORT_READY'
        && signalCandleClosedAt > 0
        && Date.now() - signalCandleClosedAt <= 6 * 60_000;
      const seedFirstObservation = labelKey === 'PUMP_DISTRIBUTION_WATCH'
        || labelKey === 'PUMP_DISTRIBUTION_SHORT_READY'
        || labelKey === 'EXTENDED_EMA99_PANIC_RECLAIM_LONG'
        || labelKey === 'PRIMARY_EMA99_PANIC_FLUSH_ACTIVE'
        || labelKey === 'PRIMARY_EMA99_PANIC_RECLAIM_LONG_READY'
        || labelKey === 'POST_PUMP_BASE_ABSORPTION_WATCH'
        || freshEmaFanFirstObservation
        || freshPostPumpFirstObservation
        || freshKillLongFirstObservation
        || freshPumpFlushFirstObservation
        || freshFlagpoleShortKillFirstObservation
        || freshFadingWaveLivePumpFirstObservation;
      // Existing primary labels retain the old no-fire-on-process-start policy.
      // Distribution labels may be long-lived, so seed their first causal
      // observation; signalKey dedupe in paper keeps restarts idempotent.
      if (!alreadyObserved && !seedFirstObservation) continue;
      liquidFlowV2Session.transitionsByLabel.set(
        labelKey,
        (liquidFlowV2Session.transitionsByLabel.get(labelKey) ?? 0) + 1,
      );
      if (classification.phase !== 'READY') continue;
      readyLabelKeys.add(`${symbol}|${labelKey}`);
      if (classification === row.classification) primaryReadySymbols.add(symbol);
    }
  }
  return { primaryReadySymbols, readyLabelKeys };
}

function liquidFlowV2ReadyCount(rows = []) {
  return rows.filter((row) => [
    row?.classification,
    ...(Array.isArray(row?.classification?.secondaryLabels) ? row.classification.secondaryLabels : []),
  ].some((classification) => classification?.phase === 'READY')).length;
}

function sortLiquidFlowV2Rows(rows = []) {
  rows.sort((a, b) => {
    const phaseRank = (row) => row.classification.phase === 'READY' ? 0
      : row.classification.labelKey.endsWith('SQUEEZE_ACTIVE')
        || row.classification.labelKey.endsWith('FLUSH_ACTIVE') ? 1 : 2;
    return phaseRank(a) - phaseRank(b)
      || Number(b.classification.confidence ?? 0) - Number(a.classification.confidence ?? 0)
      || Math.abs(Number(b.features.change24hPct ?? 0)) - Math.abs(Number(a.features.change24hPct ?? 0));
  });
  return rows;
}

async function refreshLiquidHeatmapFlowV2({ force = false } = {}) {
  const now = Date.now();
  if (!force && liquidFlowV2Cache.data && now < liquidFlowV2Cache.expiresAt) {
    return liquidFlowV2Cache.data;
  }
  if (liquidFlowV2Cache.inflight) return liquidFlowV2Cache.inflight;

  liquidFlowV2Cache.inflight = (async () => {
    const snapshot = await getSharedSnapshot();
    const candidates = selectLiquidHeatmapFlowV2Candidates(snapshot, {
      topPerSide: Math.max(8, Math.min(20, Number(process.env.LIQ_FLOW_V2_TOP_PER_SIDE ?? 20))),
      maxSymbols: Math.max(16, Math.min(48, Number(process.env.LIQ_FLOW_V2_MAX_SYMBOLS ?? 48))),
      minQuoteVolume: Math.max(0, Number(process.env.LIQ_FLOW_V2_MIN_QUOTE_VOLUME ?? 2_000_000)),
    });
    const primarySymbols = new Set(candidates.map((row) => row.symbol));
    const extendedCandidates = selectLiquidHeatmapFlowV2ExtendedCandidates(snapshot, {
      fromRank: Math.max(21, Number(process.env.LIQ_FLOW_V2_EXTENDED_FROM_RANK ?? 21)),
      toRank: Math.max(21, Math.min(100, Number(process.env.LIQ_FLOW_V2_EXTENDED_TO_RANK ?? 100))),
      maxSymbols: Math.max(0, Math.min(80, Number(process.env.LIQ_FLOW_V2_EXTENDED_PREFILTER_SYMBOLS ?? 80))),
      minQuoteVolume: Math.max(0, Number(process.env.LIQ_FLOW_V2_EXTENDED_MIN_QUOTE_VOLUME ?? 2_000_000)),
      minChange24hPct: Math.max(0, Number(process.env.LIQ_FLOW_V2_EXTENDED_MIN_CHANGE_24H_PCT ?? 0)),
    }).filter((row) => !primarySymbols.has(row.symbol));
    const emaFanShortCandidates = selectLiquidHeatmapFlowV2EmaFanShortCandidates(snapshot, {
      topLiquidity: Math.max(1, Math.min(200, Number(process.env.LIQ_FLOW_V2_EMA_FAN_SHORT_TOP_LIQUIDITY ?? 150))),
      minQuoteVolume: Math.max(0, Number(process.env.LIQ_FLOW_V2_EMA_FAN_SHORT_MIN_QUOTE_VOLUME ?? 2_000_000)),
      maxChange24hPct: Math.min(-5, Number(process.env.LIQ_FLOW_V2_EMA_FAN_SHORT_MAX_CHANGE_24H_PCT ?? -5)),
    });
    const postPumpCandidates = selectLiquidHeatmapFlowV2PostPumpCandidates(snapshot, {
      topLiquidity: Math.max(20, Math.min(200, Number(process.env.LIQ_FLOW_V2_POST_PUMP_TOP_LIQUIDITY ?? 150))),
      minQuoteVolume: Math.max(0, Number(process.env.LIQ_FLOW_V2_POST_PUMP_MIN_QUOTE_VOLUME ?? 2_000_000)),
    });
    const extendedSymbols = extendedCandidates.map((row) => row.symbol);
    const minBars = 180;
    klineCache.subscribe(extendedSymbols, '5m');
    const extendedMissing5m = klineCache.needsRefresh(
      extendedSymbols,
      '5m',
      minBars,
      liquidFlowV2KlineMaxAgeMs['5m'],
    );
    if (extendedMissing5m.length && !isBinanceRestCongested()) {
      await klineCache.seed(extendedMissing5m, '5m', 220, {
        batchSize: 4,
        batchDelayMs: 350,
        maxAgeMs: liquidFlowV2KlineMaxAgeMs['5m'],
      });
    }
    const postPumpSymbols = postPumpCandidates.map((row) => row.symbol);
    liquidFlowV2PostPumpSymbols = postPumpSymbols;
    const fadingWaveLiveGroup = klineCache.subscribeGroup(
      'liquid-flow-v2-top-liquidity',
      postPumpSymbols,
      '5m',
    );
    const postPumpMissing5m = klineCache.needsRefresh(
      postPumpSymbols,
      '5m',
      40,
      liquidFlowV2KlineMaxAgeMs['5m'],
    );
    if (postPumpMissing5m.length && !isBinanceRestCongested() && !liquidFlowV2PostPumpSeedPromise) {
      liquidFlowV2PostPumpSeedPromise = klineCache
        .seed(postPumpMissing5m, '5m', 220, {
          batchSize: 4,
          batchDelayMs: 350,
          maxAgeMs: liquidFlowV2KlineMaxAgeMs['5m'],
          subscribe: false,
        })
        .catch((error) => {
          console.warn(`[LiquidFlowV2] top-liquidity 5m background seed failed: ${error.message}`);
        })
        .finally(() => {
          liquidFlowV2PostPumpSeedPromise = null;
          scheduleLiquidHeatmapFlowV2FastScan();
        });
    }
    const postPumpQualified = postPumpCandidates
      .map((market) => {
        const klines = klineCache.getIfCached(market.symbol, '5m', 340) ?? [];
        const features = buildLiquidHeatmapFlowV2Features({ market, klines });
        const setup = features.postPumpShortSqueeze5m ?? {};
        const pumpFlush = features.pumpFlushReclaim5m ?? {};
        const flagpoleShortKill = features.flagpoleShortKill5m ?? {};
        const fadingWaveLivePump = features.fadingWaveLivePump5m ?? {};
        const qualified = setup.watchReady === true || setup.longReady === true
          || pumpFlush.watchReady === true || pumpFlush.longReady === true
          || flagpoleShortKill.watchReady === true || flagpoleShortKill.longReady === true
          || fadingWaveLivePump.shortReady === true;
        return qualified ? {
          market,
          fadingWaveLivePumpActive: fadingWaveLivePump.shortReady === true,
        } : null;
      })
      .filter(Boolean)
      .sort((a, b) => Number(b.fadingWaveLivePumpActive) - Number(a.fadingWaveLivePumpActive)
        || Number(a.market.liquidityRank ?? Infinity) - Number(b.market.liquidityRank ?? Infinity))
      .slice(0, Math.max(1, Math.min(60, Number(process.env.LIQ_FLOW_V2_POST_PUMP_MAX_QUALIFIED ?? 60))))
      .map((row) => row.market);
    const extendedQualified = extendedCandidates
      .map((market) => {
        const klines = klineCache.getIfCached(market.symbol, '5m', 220) ?? [];
        const features = buildLiquidHeatmapFlowV2Features({ market, klines });
        return liquidHeatmapFlowV2ExtendedPrefilter(features)
          ? { market, emaFanActive: features.emaFanLong5m?.watchActive === true }
          : null;
      })
      .filter(Boolean)
      .sort((a, b) => Number(b.emaFanActive) - Number(a.emaFanActive)
        || Number(a.market.moverRank ?? Infinity) - Number(b.market.moverRank ?? Infinity))
      .slice(0, Math.max(1, Math.min(30, Number(process.env.LIQ_FLOW_V2_EXTENDED_MAX_QUALIFIED ?? 30))))
      .map((row) => row.market);
    const emaFanShortBySymbol = new Map(emaFanShortCandidates.map((row) => [row.symbol, row]));
    const postPumpBySymbol = new Map(postPumpQualified.map((row) => [row.symbol, row]));
    const existingCandidateSymbols = new Set();
    const allCandidates = [...candidates, ...extendedQualified].map((market) => {
      existingCandidateSymbols.add(market.symbol);
      const shortMarket = emaFanShortBySymbol.get(market.symbol);
      const postPumpMarket = postPumpBySymbol.get(market.symbol);
      return shortMarket || postPumpMarket ? {
        ...market,
        liquidityRank: shortMarket?.liquidityRank ?? postPumpMarket?.liquidityRank ?? market.liquidityRank,
        emaFanShortUniverse: shortMarket != null,
        postPumpUniverse: postPumpMarket != null,
        fadingWaveUniverse: postPumpMarket?.fadingWaveUniverse === true,
      } : market;
    });
    for (const market of emaFanShortCandidates) {
      if (existingCandidateSymbols.has(market.symbol)) continue;
      existingCandidateSymbols.add(market.symbol);
      const postPumpMarket = postPumpBySymbol.get(market.symbol);
      allCandidates.push(postPumpMarket ? {
        ...market,
        postPumpUniverse: true,
        fadingWaveUniverse: postPumpMarket.fadingWaveUniverse === true,
      } : market);
    }
    for (const market of postPumpQualified) {
      if (existingCandidateSymbols.has(market.symbol)) continue;
      existingCandidateSymbols.add(market.symbol);
      allCandidates.push(market);
    }
    const snapshotBySymbol = new Map((Array.isArray(snapshot) ? snapshot : [])
      .map((market) => [normalizeSymbol(market?.symbol), market])
      .filter(([symbol]) => symbol));
    const priorRowBySymbol = new Map((liquidFlowV2Cache.data?.rows ?? [])
      .map((row) => [normalizeSymbol(row?.symbol), row])
      .filter(([symbol]) => symbol));
    for (const symbol of liquidFlowV2Paper.pendingConfirmationSymbols()) {
      if (existingCandidateSymbols.has(symbol)) continue;
      const market = snapshotBySymbol.get(symbol);
      if (!market || !(Number(market.markPrice) > 0)) continue;
      const priorRow = priorRowBySymbol.get(symbol);
      existingCandidateSymbols.add(symbol);
      allCandidates.push({
        ...market,
        symbol,
        moverSide: priorRow?.moverSide ?? (Number(market.change24hPct) >= 0 ? 'UP' : 'DOWN'),
        moverRank: priorRow?.moverRank ?? null,
        liquidityRank: priorRow?.liquidityRank ?? null,
        universeTier: priorRow?.features?.universeTier ?? 'EMA_FAN_PENDING_CONFIRMATION',
      });
    }
    const extendedQualifiedSymbols = new Set(extendedQualified.map((row) => row.symbol));
    for (const market of extendedCandidates) {
      if (extendedQualifiedSymbols.has(market.symbol)) continue;
      const previous = liquidFlowV2Session.lastLabelBySymbol.get(market.symbol);
      if (!(previous instanceof Set)) continue;
      const next = new Set(previous);
      next.delete('EXTENDED_EMA99_PANIC_RECLAIM_LONG');
      next.delete('EMA_FAN_LONG_READY');
      next.delete('EMA_FAN_LONG_IMPULSE_RUNNER');
      if (next.size) liquidFlowV2Session.lastLabelBySymbol.set(market.symbol, next);
      else liquidFlowV2Session.lastLabelBySymbol.delete(market.symbol);
    }
    const emaFanShortSymbols = new Set(emaFanShortCandidates.map((row) => row.symbol));
    for (const [symbol, previous] of liquidFlowV2Session.lastLabelBySymbol.entries()) {
      if (emaFanShortSymbols.has(symbol) || !(previous instanceof Set) || !previous.has('EMA_FAN_SHORT_READY')) continue;
      const next = new Set(previous);
      next.delete('EMA_FAN_SHORT_READY');
      if (next.size) liquidFlowV2Session.lastLabelBySymbol.set(symbol, next);
      else liquidFlowV2Session.lastLabelBySymbol.delete(symbol);
    }
    const postPumpQualifiedSymbols = new Set(postPumpQualified.map((row) => row.symbol));
    for (const market of postPumpCandidates) {
      if (postPumpQualifiedSymbols.has(market.symbol)) continue;
      const previous = liquidFlowV2Session.lastLabelBySymbol.get(market.symbol);
      if (!(previous instanceof Set)) continue;
      const next = new Set(previous);
      next.delete('POST_PUMP_BASE_ABSORPTION_WATCH');
      next.delete('POST_PUMP_SHORT_SQUEEZE_LONG_READY');
      next.delete('POST_PUMP_SHORT_SQUEEZE_PRIME');
      next.delete('POST_PUMP_FLAGPOLE_SHORT_KILL_LONG_READY');
      next.delete('FADING_WAVE_LIVE_PUMP_SHORT_READY');
      next.delete('PUMP_FLUSH_RECLAIM_LONG_READY');
      if (next.size) liquidFlowV2Session.lastLabelBySymbol.set(market.symbol, next);
      else liquidFlowV2Session.lastLabelBySymbol.delete(market.symbol);
    }
    const symbols = allCandidates.map((row) => row.symbol);
    klineCache.subscribe(symbols, '5m');
    klineCache.subscribe(symbols, '15m');
    klineCache.subscribe(symbols, '1h');
    klineCache.subscribe(symbols, '4h');
    const missing = klineCache.needsRefresh(
      symbols,
      '5m',
      minBars,
      liquidFlowV2KlineMaxAgeMs['5m'],
    );
    if (missing.length && !isBinanceRestCongested()) {
      await klineCache.seed(missing, '5m', 220, {
        batchSize: 4,
        batchDelayMs: 350,
        maxAgeMs: liquidFlowV2KlineMaxAgeMs['5m'],
      });
    }
    for (const interval of ['15m', '1h', '4h']) {
      const requiredBars = interval === '15m' ? 180 : 105;
      const seedBars = interval === '15m' ? 220 : 120;
      const htfMissing = klineCache.needsRefresh(
        symbols,
        interval,
        requiredBars,
        liquidFlowV2KlineMaxAgeMs[interval],
      );
      if (htfMissing.length && !isBinanceRestCongested()) {
        await klineCache.seed(htfMissing, interval, seedBars, {
          batchSize: 4,
          batchDelayMs: 350,
          maxAgeMs: liquidFlowV2KlineMaxAgeMs[interval],
        });
      }
    }

    const rows = await mapConcurrent(allCandidates, 5, async (market) => {
      let openInterest = liquidFlowV2Collector.openInterestSummary(market.symbol);
      try {
        const response = await client.getOpenInterest(market.symbol, {
          priority: 7,
          dropOnCongestion: true,
          source: 'liquidFlowV2:openInterest',
        });
        openInterest = liquidFlowV2Collector.recordOpenInterest(
          market.symbol,
          Number(response?.openInterest),
        ) ?? openInterest;
      } catch {
        // Keep the prior OI sample. The classifier exposes OI warmup explicitly.
      }

      const klines = klineCache.getIfCached(market.symbol, '5m', 340) ?? [];
      const klines15m = klineCache.getIfCached(market.symbol, '15m', 220) ?? [];
      const klines1h = klineCache.getIfCached(market.symbol, '1h', 160) ?? [];
      const klines4h = klineCache.getIfCached(market.symbol, '4h', 160) ?? [];
      let heatmap = null;
      if (klines.length >= minBars) {
        try {
          heatmap = computeHeatmapData({
            klines,
            currentPrice: market.markPrice,
            momentumPct: market.change24hPct,
          });
        } catch {}
      }
      const liquidation = liquidFlowV2Collector.summary(market.symbol);
      const features = buildLiquidHeatmapFlowV2Features({
        market: {
          ...market,
          universeTier: market.universeTier ?? 'PRIMARY_1_20',
        },
        klines,
        klines15m,
        klines1h,
        klines4h,
        heatmap,
        openInterest,
        liquidation,
      });
      const dataFreshness = liquidFlowV2KlineFreshness({
        klines,
        klines15m,
        klines1h,
        klines4h,
      });
      const classification = dataFreshness.fresh
        ? classifyLiquidHeatmapFlowV2(features)
        : liquidFlowV2StaleWaitClassification(dataFreshness);
      return {
        symbol: market.symbol,
        moverSide: market.moverSide,
        moverRank: market.moverRank,
        liquidityRank: market.liquidityRank,
        emaFanShortUniverse: market.emaFanShortUniverse === true,
        features,
        dataFreshness,
        classification,
      };
    });

    sortLiquidFlowV2Rows(rows);
    const generatedAt = Date.now();
    const confirmedPaperTrades = await liquidFlowV2Paper.evaluatePendingEntryConfirmations(rows, generatedAt);
    handleLiquidFlowV2BinanceEvents(confirmedPaperTrades).catch((error) => {
      console.warn(`[LiquidFlowV2Real] confirmation-event failed: ${error.message}`);
    });
    const transitions = noteLiquidFlowV2Transitions(rows);
    notifyLiquidFlowV2HtfDiscord(rows, transitions.primaryReadySymbols, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2HTF] notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2ExtendedDiscord(rows, transitions.primaryReadySymbols, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2Extended] notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2EmaFanDiscord(rows, transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2EmaFan] notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2KillLongDiscord(rows, transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2KillLong] notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2FlagpoleShortKillDiscord(rows, transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2FlagpoleShortKill] notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2FadingWaveLivePumpDiscord(rows, transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2FadingWaveLivePump] notify failed: ${error.message}`);
    });
    const createdPaperTrades = await liquidFlowV2Paper.createFromReadyTransitions(
      rows,
      transitions.primaryReadySymbols,
      generatedAt,
      transitions.readyLabelKeys,
    );
    handleLiquidFlowV2BinanceEvents(createdPaperTrades).catch((error) => {
      console.warn(`[LiquidFlowV2Real] create-event failed: ${error.message}`);
    });
    const paperSnapshot = liquidFlowV2Paper.snapshot();
    const stats = liquidHeatmapFlowV2Stats(rows, paperSnapshot.trades).map((row) => ({
      ...row,
      transitions: liquidFlowV2Session.transitionsByLabel.get(row.key) ?? 0,
    }));
    const fadingWaveLiveCoverage = klineCache.liveCoverage(postPumpSymbols, '5m', generatedAt);
    const result = {
      version: LIQUID_HEATMAP_FLOW_V2_VERSION,
      generatedAt,
      observationOnly: false,
      labelsObservationOnly: false,
      affectsOrders: true,
      affectsBinance: true,
      affectsEntry: true,
      affectsSize: true,
      affectsSlTp: true,
      candidateCount: allCandidates.length,
      primaryCandidateCount: candidates.length,
      extendedUniverseCount: extendedCandidates.length,
      extendedQualifiedCount: extendedQualified.length,
      emaFanShortCandidateCount: emaFanShortCandidates.length,
      postPumpCandidateCount: postPumpCandidates.length,
      postPumpQualifiedCount: postPumpQualified.length,
      readyCount: liquidFlowV2ReadyCount(rows),
      activeCount: rows.filter((row) => row.classification.labelKey.endsWith('SQUEEZE_ACTIVE')
        || row.classification.labelKey.endsWith('FLUSH_ACTIVE')).length,
      warmupCount: rows.filter((row) => row.classification.warmingUp).length,
      staleDataCount: rows.filter((row) => row.dataFreshness?.stale === true).length,
      dataFreshnessVersion: LIQUID_FLOW_V2_KLINE_FRESHNESS_VERSION,
      fadingWaveLiveVersion: KLINE_CACHE_MANAGED_LIVE_GROUP_VERSION,
      fadingWaveLiveGroup,
      fadingWaveLiveCoverage,
      klineTelemetry: {
        m5: klineCache.stats('5m'),
        m15: klineCache.stats('15m'),
        h1: klineCache.stats('1h'),
        h4: klineCache.stats('4h'),
      },
      sessionStartedAt: liquidFlowV2Session.startedAt,
      telemetry: liquidFlowV2Collector.health(),
      paper: paperSnapshot,
      stats,
      rows,
    };
    liquidFlowV2Cache.data = result;
    liquidFlowV2Cache.expiresAt = Date.now() + 12_000;
    pushSse(liquidFlowV2SseClients, result);
    return result;
  })().finally(() => {
    liquidFlowV2Cache.inflight = null;
  });
  return liquidFlowV2Cache.inflight;
}

const liquidFlowV2RefreshTimer = setInterval(() => {
  refreshLiquidHeatmapFlowV2({ force: true }).catch((error) => {
    console.warn(`[LiquidFlowV2] refresh failed: ${error.message}`);
  });
}, 15_000);
liquidFlowV2RefreshTimer.unref?.();

const liquidFlowV2FastScanTimers = new Map();
const liquidFlowV2FastScanLastAt = new Map();
let liquidFlowV2FastScanQueue = Promise.resolve();

async function refreshLiquidHeatmapFlowV2Symbol(symbolInput) {
  const symbol = normalizeSymbol(symbolInput);
  const prior = liquidFlowV2Cache.data;
  if (!symbol || !prior?.rows?.length || liquidFlowV2Cache.inflight) return;
  const priorIndex = prior.rows.findIndex((row) => row.symbol === symbol);
  if (priorIndex < 0) return;

  const priorRow = prior.rows[priorIndex];
  const klines = klineCache.getIfCached(symbol, '5m', 340) ?? [];
  const klines15m = klineCache.getIfCached(symbol, '15m', 220) ?? [];
  const klines1h = klineCache.getIfCached(symbol, '1h', 160) ?? [];
  const klines4h = klineCache.getIfCached(symbol, '4h', 160) ?? [];
  if (klines.length < 180) return;
  const liveCandle = klines.at(-1);
  const liveMark = Number(liveCandle?.close);
  if (!Number.isFinite(liveMark) || liveMark <= 0) return;

  let heatmap = null;
  try {
    heatmap = computeHeatmapData({
      klines,
      currentPrice: liveMark,
      momentumPct: Number(priorRow.features?.change24hPct ?? 0),
    });
  } catch {}

  const features = buildLiquidHeatmapFlowV2Features({
    market: {
      markPrice: liveMark,
      change24hPct: priorRow.features?.change24hPct,
      quoteVolume: priorRow.features?.quoteVolume,
      fundingRate: priorRow.features?.fundingRate,
      moverSide: priorRow.moverSide,
      moverRank: priorRow.moverRank,
      liquidityRank: priorRow.features?.liquidityRank,
      emaFanShortUniverse: priorRow.features?.emaFanShortUniverse === true,
      postPumpUniverse: priorRow.features?.postPumpUniverse === true,
      fadingWaveUniverse: priorRow.features?.fadingWaveUniverse === true,
      universeTier: priorRow.features?.universeTier,
    },
    klines,
    klines15m,
    klines1h,
    klines4h,
    heatmap,
    openInterest: liquidFlowV2Collector.openInterestSummary(symbol),
    liquidation: liquidFlowV2Collector.summary(symbol),
  });
  const dataFreshness = liquidFlowV2KlineFreshness({
    klines,
    klines15m,
    klines1h,
    klines4h,
  });
  const row = {
    symbol,
    moverSide: priorRow.moverSide,
    moverRank: priorRow.moverRank,
    liquidityRank: priorRow.features?.liquidityRank,
    features,
    dataFreshness,
    classification: dataFreshness.fresh
      ? classifyLiquidHeatmapFlowV2(features)
      : liquidFlowV2StaleWaitClassification(dataFreshness),
  };
  const rows = [...prior.rows];
  rows[priorIndex] = row;
  sortLiquidFlowV2Rows(rows);

  const generatedAt = Date.now();
  const confirmedPaperTrades = await liquidFlowV2Paper.evaluatePendingEntryConfirmations([row], generatedAt);
  handleLiquidFlowV2BinanceEvents(confirmedPaperTrades).catch((error) => {
    console.warn(`[LiquidFlowV2Real] fast confirmation-event failed: ${error.message}`);
  });
  const transitions = noteLiquidFlowV2Transitions([row]);
    notifyLiquidFlowV2HtfDiscord([row], transitions.primaryReadySymbols, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2HTF] fast notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2ExtendedDiscord([row], transitions.primaryReadySymbols, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2Extended] fast notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2EmaFanDiscord([row], transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2EmaFan] fast notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2KillLongDiscord([row], transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2KillLong] fast notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2FlagpoleShortKillDiscord([row], transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2FlagpoleShortKill] fast notify failed: ${error.message}`);
    });
    notifyLiquidFlowV2FadingWaveLivePumpDiscord([row], transitions.readyLabelKeys, generatedAt).catch((error) => {
      console.warn(`[LiquidFlowV2FadingWaveLivePump] fast notify failed: ${error.message}`);
    });
  const createdPaperTrades = await liquidFlowV2Paper.createFromReadyTransitions(
    [row],
    transitions.primaryReadySymbols,
    generatedAt,
    transitions.readyLabelKeys,
  );
  handleLiquidFlowV2BinanceEvents(createdPaperTrades).catch((error) => {
    console.warn(`[LiquidFlowV2Real] fast create-event failed: ${error.message}`);
  });
  const paperSnapshot = liquidFlowV2Paper.snapshot();
  const stats = liquidHeatmapFlowV2Stats(rows, paperSnapshot.trades).map((stat) => ({
    ...stat,
    transitions: liquidFlowV2Session.transitionsByLabel.get(stat.key) ?? 0,
  }));
  const fadingWaveLiveCoverage = klineCache.liveCoverage(
    liquidFlowV2PostPumpSymbols,
    '5m',
    generatedAt,
  );
  const result = {
    ...prior,
    version: LIQUID_HEATMAP_FLOW_V2_VERSION,
    generatedAt,
    readyCount: liquidFlowV2ReadyCount(rows),
    activeCount: rows.filter((candidate) => candidate.classification.labelKey.endsWith('SQUEEZE_ACTIVE')).length,
    warmupCount: rows.filter((candidate) => candidate.classification.warmingUp).length,
    staleDataCount: rows.filter((candidate) => candidate.dataFreshness?.stale === true).length,
    dataFreshnessVersion: LIQUID_FLOW_V2_KLINE_FRESHNESS_VERSION,
    fadingWaveLiveVersion: KLINE_CACHE_MANAGED_LIVE_GROUP_VERSION,
    fadingWaveLiveCoverage,
    klineTelemetry: {
      m5: klineCache.stats('5m'),
      m15: klineCache.stats('15m'),
      h1: klineCache.stats('1h'),
      h4: klineCache.stats('4h'),
    },
    telemetry: liquidFlowV2Collector.health(),
    paper: paperSnapshot,
    stats,
    rows,
  };
  liquidFlowV2Cache.data = result;
  liquidFlowV2Cache.expiresAt = Date.now() + 12_000;
  pushSse(liquidFlowV2SseClients, result);
}

function scheduleLiquidHeatmapFlowV2FastScan({ symbol, interval } = {}) {
  const normalized = normalizeSymbol(symbol);
  if (!['5m', '15m', '1h', '4h'].includes(interval)
    || !normalized
    || !liquidFlowV2Cache.data?.rows?.some((row) => row.symbol === normalized)) return;
  if (liquidFlowV2FastScanTimers.has(normalized)) return;
  const elapsed = Date.now() - Number(liquidFlowV2FastScanLastAt.get(normalized) ?? 0);
  const delay = Math.max(250, 750 - elapsed);
  const timer = setTimeout(() => {
    liquidFlowV2FastScanTimers.delete(normalized);
    liquidFlowV2FastScanLastAt.set(normalized, Date.now());
    liquidFlowV2FastScanQueue = liquidFlowV2FastScanQueue
      .then(() => refreshLiquidHeatmapFlowV2Symbol(normalized))
      .catch((error) => console.warn(`[LiquidFlowV2] fast ${normalized} failed: ${error.message}`));
  }, delay);
  timer.unref?.();
  liquidFlowV2FastScanTimers.set(normalized, timer);
}

klineCache.on('candleTick', (event) => {
  if (event?.interval === '5m') scheduleLiquidHeatmapFlowV2FastScan(event);
});
klineCache.on('candleClose', scheduleLiquidHeatmapFlowV2FastScan);

async function refreshLiquidMarketDirectionHealth() {
  if (liquidMarketDirectionCache.data && Date.now() < liquidMarketDirectionCache.expiresAt) {
    return liquidMarketDirectionCache.data;
  }

  const now = Date.now();
  const maxSymbols = Math.max(30, Math.min(200, Number(process.env.LIQUID_MARKET_HEALTH_MAX_SYMBOLS ?? 120)));
  const stableBasePattern = /^(USDC|FDUSD|TUSD|USDP|BUSD|DAI|EUR|TRY|BRL|JPY|GBP)USDT$/;
  // Scoring uses websocket candle cache; the market snapshot is only the liquid
  // symbol universe. Prefer the in-memory snapshot so a stuck/congested Binance
  // REST refresh cannot blank or block the point card.
  let snapshotSource = 'shared-cache';
  let snapshot = Array.isArray(_snapshotCache) && _snapshotCache.length
    ? _snapshotCache
    : Array.isArray(snapshotCache.data) && snapshotCache.data.length
      ? snapshotCache.data
      : null;
  if (!snapshot) {
    snapshotSource = 'rest-fallback';
    const snapshotTimeoutMs = Math.max(
      1_000,
      Number(process.env.LIQUID_MARKET_HEALTH_SNAPSHOT_TIMEOUT_MS ?? 4_000),
    );
    snapshot = await Promise.race([
      getSharedSnapshot(),
      new Promise((resolve) => setTimeout(() => resolve([]), snapshotTimeoutMs)),
    ]).catch(() => []);
    if (!Array.isArray(snapshot) || !snapshot.length) snapshotSource = 'no-snapshot';
  }
  const candidates = [...snapshot]
    .filter((row) => row?.symbol && row.symbol !== 'BTCUSDT' && !stableBasePattern.test(row.symbol))
    .sort((a, b) => Number(b.quoteVolume ?? 0) - Number(a.quoteVolume ?? 0))
    .slice(0, maxSymbols);
  const universe = candidates.map((row) => ({
    symbol: row.symbol,
    quoteVolume: Number(row.quoteVolume ?? 0),
    candles15m: klineCache.getIfCached(row.symbol, '15m', 100),
  }));
  const btcHealth = btcHealthCache.data ?? await Promise.race([
    getBtcHealth(),
    new Promise((resolve) => setTimeout(() => resolve(null), 2_500)),
  ]).catch(() => null);
  const evaluation = evaluateLiquidMarketDirectionHealth({
    universe,
    btcCandles5m: klineCache.getIfCached('BTCUSDT', '5m', 100),
    btcCandles15m: klineCache.getIfCached('BTCUSDT', '15m', 100),
    btcCandles1h: klineCache.getIfCached('BTCUSDT', '1h', 100),
    btcHealth,
    macroShock: getBtcMacroShockGuard(),
    now,
    minSample: 30,
  });
  liquidMarketDirectionState = stabilizeLiquidMarketDirectionLabel(
    liquidMarketDirectionState,
    evaluation,
    2,
  );
  const scoreDynamics = deriveLiquidMarketDirectionScoreDynamics(
    liquidMarketDirectionCache.data,
    evaluation,
  );
  liquidShortEdgeCycleState = advanceLiquidShortEdgeCycle(
    liquidShortEdgeCycleState,
    {
      sampleKey: scoreDynamics?.sampleKey ?? evaluation?.sampleKey ?? '',
      evaluatedAt: scoreDynamics?.evaluatedAt ?? evaluation?.evaluatedAt ?? now,
      longScore: scoreDynamics?.longScore ?? evaluation?.scores?.long,
      shortScore: scoreDynamics?.shortScore ?? evaluation?.scores?.short,
      shortScoreSlope: scoreDynamics?.shortScoreSlope,
      longScoreSlope: scoreDynamics?.longScoreSlope,
      shortScoreDropFromPeak: scoreDynamics?.shortScoreDropFromPeak,
      shortWaveState: scoreDynamics?.shortWaveState,
      btcRet15m: scoreDynamics?.btcRet15m ?? evaluation?.btc?.ret15m,
    },
  );
  const socket = klineCache.stats('15m');
  const data = {
    ...evaluation,
    label: liquidMarketDirectionState.committedLabel,
    description: liquidMarketDirectionLabelDescription(liquidMarketDirectionState.committedLabel),
    pendingLabel: liquidMarketDirectionState.candidateLabel,
    pendingCount: liquidMarketDirectionState.candidateCount,
    hysteresisSamples: 2,
    scoreDynamics,
    shortEdgeCycle: {
      ...liquidShortEdgeCycleState,
      rule: 'SHORT_DROP_FROM_PEAK_OR_2_DOWN_AND_LONG_UP_AND_BTC_RECLAIM',
      resetRule: 'SHORT_RELOAD_OR_IMPULSE_OR_SHORT_RECOVERY',
      observationOnly: true,
      affectsOrders: false,
    },
    universeSize: candidates.length,
    version: LIQUID_MARKET_DIRECTION_HEALTH_VERSION,
    runtime: {
      version: 'LIQUID_MARKET_HEALTH_RUNTIME_V3_20260801',
      snapshotSource,
      nonBlockingRefresh: true,
    },
    socket: {
      lastTickAt: socket.lastTickAt,
      staleSec: socket.staleSec,
      isStale: socket.isStale,
      cached15m: socket.cached,
    },
    observationOnly: true,
    affectsOrders: false,
  };
  liquidMarketPointLiveState = advanceLiquidMarketPointState(
    liquidMarketPointLiveState,
    {
      sampleKey: data.sampleKey ?? data.scoreDynamics?.sampleKey,
      evaluatedAt: data.evaluatedAt ?? data.scoreDynamics?.evaluatedAt ?? now,
      longScore: data.scores?.long ?? data.scoreDynamics?.longScore,
      shortScore: data.scores?.short ?? data.scoreDynamics?.shortScore,
      marketLabel: data.label ?? data.rawLabel,
    },
  );
  liquidMarketDirectionCache.data = data;
  liquidMarketDirectionCache.expiresAt = now + 20_000;
  return data;
}

function getLiquidMarketDirectionHealth() {
  if (liquidMarketDirectionCache.data && Date.now() < liquidMarketDirectionCache.expiresAt) {
    return Promise.resolve(liquidMarketDirectionCache.data);
  }
  if (!liquidMarketDirectionCache.inflight) {
    const refreshPromise = refreshLiquidMarketDirectionHealth();
    const trackedPromise = refreshPromise.finally(() => {
      if (liquidMarketDirectionCache.inflight === trackedPromise) {
        liquidMarketDirectionCache.inflight = null;
      }
    });
    liquidMarketDirectionCache.inflight = trackedPromise;
  }
  // Once a valid score exists, never blank the card while the next 20s refresh
  // is still running. Cold start waits for the bounded refresh above.
  return liquidMarketDirectionCache.data
    ? Promise.resolve(liquidMarketDirectionCache.data)
    : liquidMarketDirectionCache.inflight;
}

function marketDirectionSnapshotForSignalStorage() {
  return buildMarketDirectionSnapshot(liquidMarketDirectionCache.data ?? {
    version: LIQUID_MARKET_DIRECTION_HEALTH_VERSION,
    evaluatedAt: Date.now(),
    label: 'NO_DATA',
    rawLabel: 'NO_DATA',
    scores: { long: 0, short: 0, confidence: 0 },
    breadth: null,
    btc: null,
    sampleSize: 0,
    universeSize: 0,
    reasons: ['market direction cache is warming up'],
  });
}

async function getShortWavePerformanceStats() {
  if (shortWaveStatsCache.data && Date.now() < shortWaveStatsCache.expiresAt) {
    return shortWaveStatsCache.data;
  }
  const [liquidStore, pumpStore, edgeStore] = await Promise.all([
    readLiquidPaperStore(),
    readPumpPaperStore(),
    readEdgePaperStore(),
  ]);
  const liquidTrades = (Array.isArray(liquidStore?.trades) ? liquidStore.trades : [])
    .map((trade) => String(trade.status ?? '').toUpperCase() === 'OPEN'
      ? enrichPaperTrade(trade, paperMarkCache.get(trade.symbol)?.markPrice)
      : trade);
  const pumpTrades = (Array.isArray(pumpStore?.trades) ? pumpStore.trades : [])
    .map((trade) => {
      if (String(trade.status ?? '').toUpperCase() !== 'OPEN') return trade;
      const mark = String(trade.source ?? '').startsWith('emasq-')
        ? getFreshEmaSqueezeMarkInfo(trade.symbol)?.mark
        : getFreshPumpPaperMark(trade.symbol);
      return enrichPumpPaperTrade(trade, mark);
    });
  const edgeTrades = (Array.isArray(edgeStore?.trades) ? edgeStore.trades : [])
    .map((trade) => ({
      ...(String(trade.status ?? '').toUpperCase() === 'OPEN'
        ? enrichEdgePaperTrade(trade, edgeMarkCache.get(trade.symbol))
        : trade),
      shortWaveSourceFamily: 'SHORT_EDGE',
    }));
  const trades = [
    ...liquidTrades,
    ...pumpTrades,
    ...edgeTrades,
  ];
  const data = {
    ...buildShortWaveStats(trades),
    updatedAt: Date.now(),
  };
  shortWaveStatsCache.data = data;
  shortWaveStatsCache.expiresAt = Date.now() + 20_000;
  return data;
}

let liquidMarketDirectionMonitorTimer = null;

function startLiquidMarketDirectionHealthMonitor() {
  if (liquidMarketDirectionMonitorTimer) return;
  const refresh = () => getLiquidMarketDirectionHealth()
    .catch((error) => console.warn(`[LiquidMarketDirection] refresh failed: ${error.message}`));
  const initialTimer = setTimeout(refresh, 8_000);
  initialTimer.unref?.();
  liquidMarketDirectionMonitorTimer = setInterval(refresh, 20_000);
  liquidMarketDirectionMonitorTimer.unref?.();
}

let _liquidMarketDirectionSignalLogLock = Promise.resolve();
let _liquidMarketDirectionSignalLogReadCache = {
  signature: '',
  pointSnapshotsByTradeId: new Map(),
  marketSnapshotsByTradeId: new Map(),
};

async function getLiquidMarketDirectionSignalLogSnapshots() {
  try {
    const fileStat = await stat(LIQUID_MARKET_DIRECTION_SIGNAL_LOG_FILE);
    const signature = `${fileStat.size}:${fileStat.mtimeMs}`;
    if (_liquidMarketDirectionSignalLogReadCache.signature === signature) {
      return _liquidMarketDirectionSignalLogReadCache;
    }
    const text = await readFile(LIQUID_MARKET_DIRECTION_SIGNAL_LOG_FILE, 'utf8');
    const records = [];
    const marketSnapshotsByTradeId = new Map();
    for (const line of text.split(/\r?\n/)) {
      if (!line.trim()) continue;
      try {
        const record = JSON.parse(line);
        records.push(record);
        if (record?.tradeId && record?.marketDirection) {
          marketSnapshotsByTradeId.set(String(record.tradeId), record.marketDirection);
        }
      } catch {
        // The final append may still be in progress; ignore only malformed lines.
      }
    }
    const pointSnapshotsByTradeId = buildLiquidMarketPointCrossoverSnapshots(records);
    _liquidMarketDirectionSignalLogReadCache = {
      signature,
      pointSnapshotsByTradeId,
      marketSnapshotsByTradeId,
    };
    return _liquidMarketDirectionSignalLogReadCache;
  } catch (error) {
    if (error?.code !== 'ENOENT') {
      console.warn(`[LiquidWaveContinuation] snapshot log read failed: ${error.message}`);
    }
    return {
      signature: '',
      pointSnapshotsByTradeId: new Map(),
      marketSnapshotsByTradeId: new Map(),
    };
  }
}

async function getLiquidMarketPointCrossoverSnapshots() {
  return (await getLiquidMarketDirectionSignalLogSnapshots()).pointSnapshotsByTradeId;
}

async function appendLiquidMarketDirectionSignalLog(trade) {
  const storedMarketHealth = trade?.marketDirectionAtSignal;
  const marketHealth = storedMarketHealth && typeof storedMarketHealth === 'object'
    ? storedMarketHealth
    : await getLiquidMarketDirectionHealth().catch((error) => ({
    version: LIQUID_MARKET_DIRECTION_HEALTH_VERSION,
    evaluatedAt: Date.now(),
    label: 'NO_DATA',
    rawLabel: 'NO_DATA',
    scores: { long: 0, short: 0, confidence: 0 },
    breadth: null,
    btc: null,
    sampleSize: 0,
    universeSize: 0,
    reasons: [`snapshot error: ${String(error?.message ?? error).slice(0, 160)}`],
    }));
  const record = buildLiquidMarketDirectionSignalLogRecord(trade, marketHealth);
  const line = `${JSON.stringify(record)}\n`;
  _liquidMarketDirectionSignalLogLock = _liquidMarketDirectionSignalLogLock
    .catch(() => {})
    .then(async () => {
      await mkdir(join(rootDir, 'data'), { recursive: true });
      await appendFile(LIQUID_MARKET_DIRECTION_SIGNAL_LOG_FILE, line, 'utf8');
    });
  await _liquidMarketDirectionSignalLogLock;
  return record;
}

async function _fetchMarketSnapshot() {
  const [symbols, tickers, premiumRows] = await Promise.all([
    getSymbols(),
    client.getTicker24hr({ priority: 1, source: 'marketSnapshot:ticker24hr' }),
    client.getPremiumIndex(undefined, { priority: 1, source: 'marketSnapshot:premiumIndex' }),
  ]);
  const allowedSymbols = new Set(symbols.map((item) => item.symbol));
  const premiumBySymbol = new Map(
    premiumRows
      .filter((item) => allowedSymbols.has(item.symbol))
      .map((item) => [item.symbol, item]),
  );

  const result = tickers
    .filter((item) => allowedSymbols.has(item.symbol))
    .map((item) => {
      const premium = premiumBySymbol.get(item.symbol);
      const lsr = longShortCache.get(item.symbol);
      const tp = topPositionCache.get(item.symbol);
      return {
        symbol: item.symbol,
        markPrice: Number(premium?.markPrice ?? item.lastPrice),
        indexPrice: Number(premium?.indexPrice ?? item.weightedAvgPrice),
        fundingRate: Number(premium?.lastFundingRate ?? 0),
        change24hPct: Number(item.priceChangePercent),
        quoteVolume: Number(item.quoteVolume),
        longShortRatio: lsr?.longShortRatio ?? null,
        longAccount: lsr?.longAccount ?? null,
        topLongPosition: tp?.longPosition ?? null,
        topShortPosition: tp?.shortPosition ?? null,
      };
    });
  snapshotCache.data = result;
  snapshotCache.expiresAt = Date.now() + 60_000; // 60s — align với getSharedSnapshot TTL tránh duplicate w=50 call
  return result;
}

async function readPaperStore() {
  try {
    const text = await readFile(PAPER_TRADES_FILE, 'utf8');
    const parsed = JSON.parse(text);
    return {
      createdAt: parsed.createdAt ?? new Date().toISOString(),
      updatedAt: parsed.updatedAt ?? null,
      trades: Array.isArray(parsed.trades) ? parsed.trades : [],
    };
  } catch (e) {
    if (e.code === 'ENOENT') {
      const fresh = { createdAt: new Date().toISOString(), updatedAt: null, trades: [] };
      await writePaperStore(fresh);
      return fresh;
    }
    console.error('[Paper] ⚠️ Store parse error, serving empty to avoid overwrite:', e.message);
    return { createdAt: new Date().toISOString(), updatedAt: null, trades: [] };
  }
}

