async function createPumpPaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase().trim();
  const side = String(payload.side ?? '').toUpperCase();
  const requestedMarginUsdt = Number(payload.marginUsdt ?? 1);
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 10)));
  const entryPrice = Number(payload.entryPrice);

  if (!symbol) throw new Error('symbol required');
  if (!['LONG', 'SHORT'].includes(side)) throw new Error('side must be LONG or SHORT');
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) throw new Error('entryPrice required');

  const variant = payload.variant ? String(payload.variant).toUpperCase().slice(0, 16) : null;
  const signalId = payload.signalId ? String(payload.signalId).slice(0, 64) : null;

  const store = await readPumpPaperStore();
  const dup = store.trades.find((t) =>
    t.symbol === symbol && t.side === side && (t.variant ?? null) === variant &&
    Math.abs(t.entryPrice - entryPrice) / entryPrice < 0.005 &&
    ['PENDING', 'OPEN'].includes(t.status),
  );
  if (dup) {
    const dupMark = String(dup.source ?? '').startsWith('emasq-')
      ? getFreshEmaSqueezeMarkInfo(symbol)?.mark
      : getFreshPumpPaperMark(symbol);
    return {
      trade: decorateSourceLongCorrReboundTrade(
        enrichEmaStageCandleTrade(enrichPumpPaperTrade(dup, dupMark)),
        { sourcePage: 'pump' },
      ),
    };
  }

  const status = payload.status === 'OPEN' ? 'OPEN' : 'PENDING';
  const source = String(payload.source ?? 'manual').slice(0, 80);
  const marketDirectionAtSignal = marketDirectionSnapshotForSignalStorage();
  const signalMarkPrice = Number(payload.signalMarkPrice);
  const pumpTf = String(payload.pumpSignalTimeframe
    ?? payload.pumpSignalFactors?.timeframe
    ?? payload.interval
    ?? '15m');
  const rawBtcHealth = payload.btcHealth
    ?? (source.startsWith('pump-') ? await getBtcHealth().catch(() => btcHealthCache.data) : null);
  const btcHealthSnapshot = rawBtcHealth ? buildBtcHealthSnapshot(rawBtcHealth) : null;
  const payloadBtcCorr = payload.btcCorr == null ? NaN : Number(payload.btcCorr);
  const btcCorr = Number.isFinite(payloadBtcCorr)
    ? +payloadBtcCorr.toFixed(2)
    : source.startsWith('pump-')
      ? getCoinBtcCorr(symbol, pumpTf, 30)
      : null;
  const nativePumpSource = isNativePumpEvalSource(source);
  const pumpEvalGate = nativePumpSource
    ? nativePumpEvalGateOfSignal({ ...payload, source, symbol, side, interval: pumpTf }, btcHealthSnapshot ?? {}, btcCorr)
    : null;
  const pumpCanonicalRule = nativePumpSource
    ? evaluatePumpCanonicalTier(
        { ...payload, source, symbol, side, interval: pumpTf, btcHealth: btcHealthSnapshot, btcCorr },
        null,
        { snapshot: true },
      )
    : null;
  // Legacy Pump Eval is retained only as an audit label. It must not reject a
  // paper trade or override its requested size while the tier is unvalidated.
  const marginUsdt = Number.isFinite(requestedMarginUsdt) && requestedMarginUsdt > 0
    ? requestedMarginUsdt
    : 1;
  if (process.env.EMA_SQUEEZE_PAPER_BREAKOUT_QUALITY_GATE !== 'false'
      && source.includes('-breakout')
      && payload.breakoutPaperEligible === false) {
    throw new Error(`BREAKOUT ${payload.breakoutQuality ?? 'REVIEW'} is not eligible for Paper`);
  }
  const emaSqueezeSl = emaSqueezePaperStopLossFromRoe({ source, side, entryPrice, leverage });
  const configuredPumpHardSlRoe = Number(process.env.PUMP_PAPER_HARD_SL_ROE ?? 15);
  const pumpHardSlRoe = Number.isFinite(configuredPumpHardSlRoe) && configuredPumpHardSlRoe > 0
    ? configuredPumpHardSlRoe
    : 15;
  const pumpHardSl = nativePumpSource && process.env.PUMP_PAPER_HARD_SL_ENABLED !== 'false'
    ? capPumpStructureStopLoss({ side, entryPrice, leverage, structureSl: payload.sl, maxLossRoe: pumpHardSlRoe })
    : null;
  const resolvedStopLoss = emaSqueezeSl
    ?? pumpHardSl
    ?? (payload.sl != null ? Number(payload.sl) : null);
  if (source.includes('-breakout')) {
    const minRr = Number(process.env.EMA_SQUEEZE_PAPER_BREAKOUT_MIN_RR ?? 1);
    const tp = Number(payload.tp);
    const risk = side === 'LONG'
      ? entryPrice - Number(emaSqueezeSl)
      : Number(emaSqueezeSl) - entryPrice;
    const reward = side === 'LONG' ? tp - entryPrice : entryPrice - tp;
    const rr = risk > 0 && reward > 0 ? reward / risk : null;
    if (!Number.isFinite(rr) || rr < minRr) {
      throw new Error(`BREAKOUT RR ${Number.isFinite(rr) ? rr.toFixed(2) : '?'} < ${minRr}`);
    }
  }
  const trade = {
    id: crypto.randomUUID(),
    signalId, variant,
    symbol, side, status,
    marginUsdt, leverage,
    quantity: (marginUsdt * leverage) / entryPrice,
    entryPrice,
    tp: payload.tp != null ? Number(payload.tp) : null,
    sl: resolvedStopLoss,
    fillPrice: status === 'OPEN' ? entryPrice : null,
    signalMarkPrice: Number.isFinite(signalMarkPrice) && signalMarkPrice > 0 ? signalMarkPrice : null,
    marketEntrySource: payload.marketEntrySource ? String(payload.marketEntrySource).slice(0, 40) : null,
    marketEntrySourceAgeMs: payload.marketEntrySourceAgeMs != null ? Number(payload.marketEntrySourceAgeMs) : null,
    exitPrice: null,
    pnl: null,
    roe: null,
    outcome: null,
    createdAt: new Date().toISOString(),
    openedAt: status === 'OPEN' ? new Date().toISOString() : null,
    closedAt: null,
    source,
    note: String(payload.note ?? '').slice(0, 500),
    pumpSignalType: payload.pumpSignalType ? String(payload.pumpSignalType).slice(0, 80) : null,
    pumpSignalGrade: payload.pumpSignalGrade ? String(payload.pumpSignalGrade).slice(0, 16) : null,
    pumpSignalMarketOk: payload.pumpSignalMarketOk ?? null,
    pumpSignalFactors: payload.pumpSignalFactors ?? null,
    pumpSignalTimeframe: pumpTf,
    candlePatternAtEntry: payload.candlePatternAtEntry ?? null,
    candlePatternTimeframe: payload.candlePatternTimeframe ?? null,
    btcCandlePatternAtEntry: payload.btcCandlePatternAtEntry ?? null,
    sideCandleTier: payload.sideCandleTier ?? null,
    sideCandleLabel: payload.sideCandleLabel ?? null,
    sideCandleReason: payload.sideCandleReason ?? null,
    sideCandleRuleVersion: payload.sideCandleRuleVersion ?? null,
    sideCandleContext: payload.sideCandleContext ?? null,
    pumpCombo: payload.pumpCombo
      ? String(payload.pumpCombo).slice(0, 240)
      : (String(source ?? '').startsWith('pump-') ? pumpSignalComboOf({
          source,
          side,
          score: Number(String(source).match(/pump-(\d+)/)?.[1]),
          type: payload.pumpSignalType,
          grade: payload.pumpSignalGrade,
          marketOk: payload.pumpSignalMarketOk,
          factors: payload.pumpSignalFactors,
        }) : null),
    pumpComboSavedAt: new Date().toISOString(),
    pumpEvalTier: pumpEvalGate?.tier ?? payload.pumpEvalTier ?? null,
    pumpEvalLabel: pumpEvalGate?.label ?? payload.pumpEvalLabel ?? null,
    pumpEvalReason: pumpEvalGate?.reason ?? payload.pumpEvalReason ?? null,
    pumpEvalVersion: pumpEvalGate?.version ?? payload.pumpEvalVersion ?? null,
    pumpEvalMarginUsdt: pumpEvalGate?.marginUsdt ?? payload.pumpEvalMarginUsdt ?? null,
    pumpEvalHour: pumpEvalGate?.hour ?? payload.pumpEvalHour ?? null,
    pumpEvalCorrBucket: pumpEvalGate?.corrBucket ?? payload.pumpEvalCorrBucket ?? null,
    pumpEvalBtcPhase: pumpEvalGate?.btcPhase ?? payload.pumpEvalBtcPhase ?? null,
    pumpEvalContextKey: pumpEvalGate?.contextKey ?? payload.pumpEvalContextKey ?? null,
    pumpCanonicalTier: pumpCanonicalRule?.tier ?? null,
    pumpCanonicalLabel: pumpCanonicalRule?.label ?? null,
    pumpCanonicalCode: pumpCanonicalRule?.code ?? null,
    pumpCanonicalReason: pumpCanonicalRule?.reason ?? null,
    pumpCanonicalCandidateTier: pumpCanonicalRule?.candidateTier ?? null,
    pumpCanonicalCandidateCode: pumpCanonicalRule?.candidateCode ?? null,
    pumpCanonicalCandidateReason: pumpCanonicalRule?.candidateReason ?? null,
    pumpCanonicalVersion: pumpCanonicalRule?.version ?? null,
    pumpCanonicalBasis: pumpCanonicalRule?.basis ?? null,
    pumpCanonicalModelCutoffDay: pumpCanonicalRule?.modelCutoffDay ?? null,
    pumpCanonicalHistoryDays: pumpCanonicalRule?.historyDays ?? [],
    pumpCanonicalExactKey: pumpCanonicalRule?.exactKey ?? null,
    pumpCanonicalCoarseKey: pumpCanonicalRule?.coarseKey ?? null,
    pumpCanonicalParentKey: pumpCanonicalRule?.parentKey ?? null,
    pumpCanonicalExpectedNetRoe: pumpCanonicalRule?.expectedNetRoe ?? null,
    pumpCanonicalConservativeEdge: pumpCanonicalRule?.conservativeEdge ?? null,
    pumpCanonicalProfitFactor: pumpCanonicalRule?.profitFactor ?? null,
    pumpCanonicalSlRate: pumpCanonicalRule?.slRate ?? null,
    pumpCanonicalSupportClosed: pumpCanonicalRule?.supportClosed ?? 0,
    pumpCanonicalExactClosed: pumpCanonicalRule?.exactClosed ?? 0,
    pumpCanonicalDays: pumpCanonicalRule?.days ?? 0,
    pumpCanonicalPositiveWindows: pumpCanonicalRule?.positiveWindows ?? 0,
    pumpCanonicalNegativeWindows: pumpCanonicalRule?.negativeWindows ?? 0,
    pumpCanonicalRecentConflict: pumpCanonicalRule?.recentConflict ?? false,
    pumpCanonicalRuntimeAllow: true,
    pumpCanonicalMarginUsdt: null,
    pumpCanonicalValidated: false,
    pumpCanonicalObservationOnly: true,
    pumpCanonicalAffectsEntry: false,
    pumpCanonicalAffectsMargin: false,
    pumpCanonicalAffectsSl: false,
    pumpCanonicalAffectsTp: false,
    pumpCanonicalDerived: false,
    pumpStructureSl: nativePumpSource && payload.sl != null ? Number(payload.sl) : null,
    pumpHardSlEnabled: nativePumpSource ? process.env.PUMP_PAPER_HARD_SL_ENABLED !== 'false' : null,
    pumpHardSlRoe: nativePumpSource ? pumpHardSlRoe : null,
    pumpHardSlApplied: nativePumpSource && pumpHardSl != null && Number.isFinite(Number(pumpHardSl)),
    btcHealth: btcHealthSnapshot, // snapshot BTC health lúc vào — để backtest gate
    btcTrendDir: btcHealthSnapshot?.btcTrendDir ?? null,
    btcTrendScore: btcHealthSnapshot?.btcTrendScore ?? null,
    btcCorr,     // correlation coin vs BTC lúc vào (cờ theo sóng BTC)
    marketDirectionAtSignal,
    breakoutQuality: payload.breakoutQuality ?? null,
    breakoutQualityReason: payload.breakoutQualityReason ?? null,
    breakoutPaperEligible: payload.breakoutPaperEligible ?? null,
    brQualityLabel: payload.brQualityLabel ?? null,
    brQualityReasons: payload.brQualityReasons ?? null,
    brRealCandleFit: payload.brRealCandleFit ?? null,
    brCandleKind: payload.brCandleKind ?? null,
    brCandleDir: payload.brCandleDir ?? null,
    brCandleClosePos: payload.brCandleClosePos ?? null,
    brCandleBodyShare: payload.brCandleBodyShare ?? null,
    brCandleUpperShare: payload.brCandleUpperShare ?? null,
    brCandleLowerShare: payload.brCandleLowerShare ?? null,
    brCandleVolRatio: payload.brCandleVolRatio ?? null,
    brEvalTier: payload.brEvalTier ?? null,
    brEvalLabel: payload.brEvalLabel ?? null,
    brEvalReason: payload.brEvalReason ?? null,
    brEvalVersion: payload.brEvalVersion ?? null,
    brEvalMarginUsdt: payload.brEvalMarginUsdt ?? null,
    brEvalHour: payload.brEvalHour ?? null,
    brEvalCorrBucket: payload.brEvalCorrBucket ?? null,
    brEvalBtcPhase: payload.brEvalBtcPhase ?? null,
    brShortEnvLabel: payload.brShortEnvLabel ?? null,
    brShortEnvBlockMarket: payload.brShortEnvBlockMarket ?? null,
    shortSessionTestLabel: payload.shortSessionTestLabel ?? null,
    shortSessionTestReason: payload.shortSessionTestReason ?? null,
    shortSessionTestMarginUsdt: payload.shortSessionTestMarginUsdt ?? null,
    shortSessionTestHour: payload.shortSessionTestHour ?? null,
    shortSessionTestCorr: payload.shortSessionTestCorr ?? null,
    binanceMarketEligible: payload.binanceMarketEligible ?? null,
    brShortEnvReason: payload.brShortEnvReason ?? null,
    brShortEnvRolling2h: payload.brShortEnvRolling2h ?? null,
    brShortRecovery60m: payload.brShortRecovery60m ?? null,
    brBtcTurnClusterLabel: payload.brBtcTurnClusterLabel ?? null,
    brBtcTurnClusterBlockMarket: payload.brBtcTurnClusterBlockMarket ?? null,
    brBtcTurnClusterReason: payload.brBtcTurnClusterReason ?? null,
    brBtcTurnCluster: payload.brBtcTurnCluster ?? null,
    brMarketRegime: payload.brMarketRegime ?? null,
    brMarketRegimeLabel: payload.brMarketRegimeLabel ?? null,
    brMarketRegimeBlockMarket: payload.brMarketRegimeBlockMarket ?? null,
    brMarketRegimeReason: payload.brMarketRegimeReason ?? null,
    runnerBtcTurnClusterLabel: payload.runnerBtcTurnClusterLabel ?? null,
    runnerBtcTurnClusterBlockMarket: payload.runnerBtcTurnClusterBlockMarket ?? null,
    runnerBtcTurnClusterReason: payload.runnerBtcTurnClusterReason ?? null,
    runnerBtcTurnCluster: payload.runnerBtcTurnCluster ?? null,
    runnerSessionTestLabel: payload.runnerSessionTestLabel ?? null,
    runnerSessionTestReason: payload.runnerSessionTestReason ?? null,
    runnerSessionTestMarginUsdt: payload.runnerSessionTestMarginUsdt ?? null,
    runnerSessionTestHour: payload.runnerSessionTestHour ?? null,
    runnerSessionTestCorr: payload.runnerSessionTestCorr ?? null,
    runnerBadComboLabel: payload.runnerBadComboLabel ?? null,
    runnerBadComboReason: payload.runnerBadComboReason ?? null,
    runnerBadComboTestMarginUsdt: payload.runnerBadComboTestMarginUsdt ?? null,
    runnerBadComboCorr: payload.runnerBadComboCorr ?? null,
    pumpBadComboLabel: payload.pumpBadComboLabel ?? null,
    pumpBadComboReason: payload.pumpBadComboReason ?? null,
    pumpBadComboTestMarginUsdt: payload.pumpBadComboTestMarginUsdt ?? null,
    pumpBadComboCorr: payload.pumpBadComboCorr ?? null,
    runnerPositiveComboLabel: payload.runnerPositiveComboLabel ?? null,
    runnerPositiveComboReason: payload.runnerPositiveComboReason ?? null,
    runnerPositiveComboTestMarginUsdt: payload.runnerPositiveComboTestMarginUsdt ?? null,
    runnerPositiveComboCorr: payload.runnerPositiveComboCorr ?? null,
    runnerEvalLabel: payload.runnerEvalLabel ?? null,
    runnerEvalTier: payload.runnerEvalTier ?? null,
    runnerEvalReason: payload.runnerEvalReason ?? null,
    runnerEvalMarginUsdt: payload.runnerEvalMarginUsdt ?? null,
    runnerEvalHour: payload.runnerEvalHour ?? null,
    runnerEvalCorr: payload.runnerEvalCorr ?? null,
    runnerEvalBtcPhase: payload.runnerEvalBtcPhase ?? null,
    breakoutBtcTurnClusterLabel: payload.breakoutBtcTurnClusterLabel ?? null,
    breakoutBtcTurnClusterBlockMarket: payload.breakoutBtcTurnClusterBlockMarket ?? null,
    breakoutBtcTurnClusterReason: payload.breakoutBtcTurnClusterReason ?? null,
    breakoutBtcTurnCluster: payload.breakoutBtcTurnCluster ?? null,
    breakoutMarketRegime: payload.breakoutMarketRegime ?? null,
    breakoutMarketRegimeLabel: payload.breakoutMarketRegimeLabel ?? null,
    breakoutMarketRegimeBlockMarket: payload.breakoutMarketRegimeBlockMarket ?? null,
    breakoutMarketRegimeReason: payload.breakoutMarketRegimeReason ?? null,
    breakoutChaseLabel: payload.breakoutChaseLabel ?? null,
    breakoutChaseBlockMarket: payload.breakoutChaseBlockMarket ?? null,
    breakoutChaseReason: payload.breakoutChaseReason ?? null,
    breakoutChasePumpPct: payload.breakoutChasePumpPct ?? null,
    breakoutChaseBasePct: payload.breakoutChaseBasePct ?? null,
    breakoutChaseCorr: payload.breakoutChaseCorr ?? null,
    emaStageGateRegime: payload.emaStageGateRegime ?? null,
    emaStageGateLabel: payload.emaStageGateLabel ?? null,
    emaStageGateBlockMarket: payload.emaStageGateBlockMarket ?? null,
    emaStageGateReason: payload.emaStageGateReason ?? null,
    emaStageGateCorr: payload.emaStageGateCorr ?? null,
    squeezeLongEvalTier: payload.squeezeLongEvalTier ?? null,
    squeezeLongEvalLabel: payload.squeezeLongEvalLabel ?? null,
    squeezeLongEvalReason: payload.squeezeLongEvalReason ?? null,
    squeezeLongEvalMarginUsdt: payload.squeezeLongEvalMarginUsdt ?? null,
    squeezeLongEvalHour: payload.squeezeLongEvalHour ?? null,
    squeezeLongEvalCorr: payload.squeezeLongEvalCorr ?? null,
    emaBreakEvalTier: payload.emaBreakEvalTier ?? null,
    emaBreakEvalLabel: payload.emaBreakEvalLabel ?? null,
    emaBreakEvalReason: payload.emaBreakEvalReason ?? null,
    emaBreakEvalMarginUsdt: payload.emaBreakEvalMarginUsdt ?? null,
    emaBreakEvalCorr: payload.emaBreakEvalCorr ?? null,
    emaBreakEvalBtcPhase: payload.emaBreakEvalBtcPhase ?? null,
    emaPreStageEvalTier: payload.emaPreStageEvalTier ?? null,
    emaPreStageEvalLabel: payload.emaPreStageEvalLabel ?? null,
    emaPreStageEvalReason: payload.emaPreStageEvalReason ?? null,
    emaPreStageEvalMarginUsdt: payload.emaPreStageEvalMarginUsdt ?? null,
    emaPreStageEvalCorr: payload.emaPreStageEvalCorr ?? null,
    emaPreStageEvalBtcPhase: payload.emaPreStageEvalBtcPhase ?? null,
    emaPreStageEvalHour: payload.emaPreStageEvalHour ?? null,
    emaPreStageEvalVersion: payload.emaPreStageEvalVersion ?? null,
    emaPreStageEvalSymbolPattern: payload.emaPreStageEvalSymbolPattern ?? null,
    emaPreStageEvalSymbolBias: payload.emaPreStageEvalSymbolBias ?? null,
    emaPreStageEvalBtcPattern: payload.emaPreStageEvalBtcPattern ?? null,
    emaPreStageEvalBtcBias: payload.emaPreStageEvalBtcBias ?? null,
    emaPreStageEvalReasonCode: payload.emaPreStageEvalReasonCode ?? null,
  };
  const candleTrade = attachCandlePatternToPaperTrade(trade);
  const emaStageCandleTrade = source.startsWith('emasq-')
    ? withEmaStageCandleFields(
        candleTrade,
        emaStageCandleEvaluationOfTrade(candleTrade),
        { derived: false },
      )
    : candleTrade;
  const stage2Rule = nativePumpSource ? pumpStage2RuleOfTrade(emaStageCandleTrade) : null;
  const stage2Trade = stage2Rule
    ? {
        ...emaStageCandleTrade,
        pumpStage2Tier: stage2Rule.tier,
        pumpStage2Code: stage2Rule.code,
        pumpStage2Label: stage2Rule.label,
        pumpStage2Reason: stage2Rule.reason,
        pumpStage2ContextKey: stage2Rule.contextKey,
        pumpStage2Version: stage2Rule.version,
        pumpStage2ObservationOnly: true,
      }
    : emaStageCandleTrade;
  const liftModel = nativePumpSource
    ? buildPumpLiftModel(store, pumpPaperDateOf(stage2Trade))
    : null;
  const liftRule = nativePumpSource
    ? pumpLiftRuleOfTrade(stage2Trade, liftModel)
    : null;
  const liftTrade = withPumpLiftFields(
    stage2Trade,
    liftRule ? { ...liftRule, derived: false } : null,
  );
  const selectorModel = buildPumpComboSelectorModel(store, pumpPaperDateOf(liftTrade));
  const selectorRule = pumpComboSelectorRuleOfTrade(
    liftTrade,
    selectorModel,
    { snapshot: true },
  );
  const selectorTrade = withPumpComboSelectorFields(
    liftTrade,
    { ...selectorRule, derived: false },
  );
  const emaLayerEvaluation = source.startsWith('emasq-')
    ? evaluateEmaComboLayers(selectorTrade, selectorModel.emaLayers)
    : null;
  const layeredTrade = withEmaComboLayerFields(selectorTrade, emaLayerEvaluation);
  const observationAt = Date.parse(layeredTrade.openedAt ?? layeredTrade.createdAt ?? '') || Date.now();
  if (
    !_pumpObservationEntryModel
    || observationAt < _pumpObservationEntryModel.dayStartAt
    || observationAt >= _pumpObservationEntryModel.dayStartAt + 24 * 60 * 60 * 1000
  ) {
    _pumpObservationEntryModel = buildPumpObservationEntryModel(store.trades, observationAt);
  }
  const observedTrade = {
    ...layeredTrade,
    ...pumpObservationSnapshotForEntry(layeredTrade, _pumpObservationEntryModel),
  };
  const liveCardAutoEligible = payload[LIVE_CARD_AUTO_ELIGIBLE] === true;
  let storedTrade = {
    ...observedTrade,
    ...sourceLongCorrReboundSnapshotForEntry(observedTrade, { sourcePage: 'pump' }),
    liveCardAutoEligible,
  };
  if (source.startsWith('emasq-') && storedTrade.status === 'OPEN') {
    let liveDecision;
    try {
      liveDecision = await maybePlaceSourceLiveCardOrder(
        'ema',
        storedTrade,
        store.trades,
        emaLiveCardKeysOfTrade(storedTrade),
        { autoEligible: liveCardAutoEligible },
      );
    } catch (error) {
      liveDecision = {
        decision: 'ERROR',
        matchedKeys: error?.liveCardMatchedKeys ?? [],
        version: error?.liveCardWhitelistVersion ?? LIQUID_LIVE_CARD_WHITELIST_VERSION,
        attemptedAt: new Date().toISOString(),
        error: String(error?.message ?? error).slice(0, 500),
      };
    }
    storedTrade = {
      ...storedTrade,
      ...liveCardAuditPatch(liveDecision),
      liveCardError: liveDecision.error ?? null,
    };
  }
  store.trades.unshift(storedTrade);
  // Dispatch the direct event before serializing the large historical store.
  // Recommended computes freshness at function entry, so disk latency cannot
  // turn a genuinely new market signal into SOURCE_EVENT_STALE.
  if (storedTrade.status === 'OPEN') {
    publishRecommendedSourceOpen(source.startsWith('emasq-') ? 'ema' : 'pump', storedTrade, {
      price: storedTrade.entryPrice,
      at: Date.parse(storedTrade.openedAt ?? storedTrade.createdAt),
      source: source.startsWith('emasq-') ? 'ema-source-open-event' : 'pump-source-open-event',
    });
  }
  await writePumpPaperStore(store, { upsertIds: [storedTrade.id] });
  if (source.startsWith('emasq-')) syncEmaSqueezePaperTicker().catch(() => {});
  else syncPumpPaperTicker().catch(() => {});
  console.log(`[PumpPaper] ${status === 'PENDING' ? '⏳' : '✅'} ${side} ${symbol} entry=${entryPrice} src=${trade.source}`);
  return {
    trade: withPumpComboSelectorFields(
      enrichPumpLiftTrade(enrichEmaStageCandleTrade(
        enrichPumpStage2Trade(enrichPumpPaperTrade(
          storedTrade,
          source.startsWith('emasq-') ? getFreshEmaSqueezeMarkInfo(symbol)?.mark : getFreshPumpPaperMark(symbol),
        )),
      ), liftModel),
      pumpComboSelectorRuleOfTrade(storedTrade, selectorModel),
    ),
  };
}

async function closePumpPaperTrade(payload) {
  const store = await readPumpPaperStore();
  const idx = store.trades.findIndex((t) => t.id === payload.id);
  if (idx < 0) throw new Error('Pump paper trade not found');
  const trade = store.trades[idx];
  if (trade.status === 'CLOSED') return { trade: enrichPumpPaperTrade(trade, trade.exitPrice) };
  const isEmaSqueeze = String(trade.source ?? '').startsWith('emasq-');
  const exitPrice = payload.exitPrice
    ? Number(payload.exitPrice)
    : isEmaSqueeze
      ? Number(getFreshEmaSqueezeMarkInfo(trade.symbol)?.mark)
      : Number(getFreshPumpPaperMark(trade.symbol));
  if (!Number.isFinite(exitPrice) || exitPrice <= 0) {
    throw new Error(`Chưa có giá socket/REST mới cho ${trade.symbol}; không thể đóng bằng giá cache/entry`);
  }
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = Number(trade.realizedPnl ?? 0)
    + (exitPrice - trade.entryPrice) * trade.quantity * sideMult;
  const roe = trade.marginUsdt > 0 ? (pnl / trade.marginUsdt) * 100 : 0;
  const outcome = payload.outcome ?? 'MANUAL';
  store.trades[idx] = {
    ...trade,
    status: 'CLOSED',
    exitPrice,
    pnl,
    roe,
    outcome,
    closeReason: payload.closeReason ? String(payload.closeReason).slice(0, 500) : trade.closeReason,
    note: payload.closeReason
      ? [String(trade.note ?? ''), `closeReason=${payload.closeReason}`].filter(Boolean).join(' | ').slice(0, 500)
      : trade.note,
    closedAt: new Date().toISOString(),
  };
  await writePumpPaperStore(store, { upsertIds: [payload.id] });
  queueLiveCardBotClose(isEmaSqueeze ? 'ema' : 'pump', store.trades[idx], {
    outcome,
    reason: store.trades[idx].closeReason ?? outcome,
  });
  if (String(trade.source ?? '').startsWith('emasq-')) syncEmaSqueezePaperTicker().catch(() => {});
  else syncPumpPaperTicker().catch(() => {});
  return { trade: enrichPumpPaperTrade(store.trades[idx], exitPrice) };
}

async function deletePumpPaperTrade(payload) {
  const store = await readPumpPaperStore();
  const deleted = store.trades.find((t) => t.id === payload.id);
  store.trades = store.trades.filter((t) => t.id !== payload.id);
  await writePumpPaperStore(store, { deleteIds: [payload.id] });
  if (String(deleted?.source ?? '').startsWith('emasq-')) syncEmaSqueezePaperTicker().catch(() => {});
  else syncPumpPaperTicker().catch(() => {});
  return { ok: true };
}

async function fillPumpPendingTrade(trade, markPrice) {
  if (pumpPaperFillLocks.has(trade.id)) return;
  pumpPaperFillLocks.add(trade.id);
  try {
    const store = await readPumpPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'PENDING');
    if (idx < 0) return;
    const entry = Number(store.trades[idx].entryPrice);
    const touched = store.trades[idx].side === 'LONG' ? markPrice <= entry : markPrice >= entry;
    if (!touched) return;
    let filledTrade = { ...store.trades[idx], status: 'OPEN', fillPrice: entry, openedAt: new Date().toISOString() };
    if (String(filledTrade.source ?? '').startsWith('emasq-') && filledTrade.liveCardAutoEligible === true) {
      let liveDecision;
      try {
        liveDecision = await maybePlaceSourceLiveCardOrder(
          'ema',
          filledTrade,
          store.trades,
          emaLiveCardKeysOfTrade(filledTrade),
          { autoEligible: true },
        );
      } catch (error) {
        liveDecision = {
          decision: 'ERROR',
          matchedKeys: error?.liveCardMatchedKeys ?? [],
          version: error?.liveCardWhitelistVersion ?? LIQUID_LIVE_CARD_WHITELIST_VERSION,
          attemptedAt: new Date().toISOString(),
          error: String(error?.message ?? error).slice(0, 500),
        };
      }
      filledTrade = {
        ...filledTrade,
        ...liveCardAuditPatch(liveDecision),
        liveCardError: liveDecision.error ?? null,
      };
    }
    store.trades[idx] = filledTrade;
    await writePumpPaperStore(store, { upsertIds: [trade.id] });
    console.log(`[PumpPaper] ✅ FILLED ${store.trades[idx].side} ${store.trades[idx].symbol} entry=${entry} mark=${markPrice}`);
    publishRecommendedSourceOpen(String(store.trades[idx].source ?? '').startsWith('emasq-') ? 'ema' : 'pump', store.trades[idx], {
      price: Number(markPrice),
      at: Date.now(),
      source: String(store.trades[idx].source ?? '').startsWith('emasq-') ? 'ema-fill-socket-event' : 'pump-fill-socket-event',
    });
  } finally {
    pumpPaperFillLocks.delete(trade.id);
  }
}

async function processPumpPaperFills(symbol, markPrice) {
  const store = await readPumpPaperStore();
  const activeForSymbol = getPumpPaperActiveIndex(store).pumpBySymbol.get(String(symbol ?? '').toUpperCase()) ?? [];
  const pending = activeForSymbol.filter((t) => t.status === 'PENDING');
  for (const t of pending) await fillPumpPendingTrade(t, markPrice);
  const open = activeForSymbol.filter((t) => t.status === 'OPEN');
  for (const t of open) {
    await checkEmaSqueezePaperProfit(t, markPrice);
    await checkPumpPaperTpSl(t, markPrice);
    await checkPumpPaperDynamicRisk(t, markPrice);
    await checkPumpPaperTimeout(t, markPrice);
  }
}

async function processPumpPaperCachedMarks() {
  if (pumpPaperBatchRunning) return;
  pumpPaperBatchRunning = true;
  try {
  const store = await readPumpPaperStore();
  const active = getPumpPaperActiveIndex(store).pump;
  for (const trade of active) {
    const markPrice = getFreshPumpPaperMark(trade.symbol);
    if (!Number.isFinite(Number(markPrice)) || Number(markPrice) <= 0) continue;
    if (trade.status === 'PENDING') await fillPumpPendingTrade(trade, Number(markPrice));
    else {
      await checkEmaSqueezePaperProfit(trade, Number(markPrice));
      await checkPumpPaperTpSl(trade, Number(markPrice));
      await checkPumpPaperDynamicRisk(trade, Number(markPrice));
      await checkPumpPaperTimeout(trade, Number(markPrice));
    }
  }
  scheduleEmaSqueezePaperBroadcast();
  } finally {
    pumpPaperBatchRunning = false;
  }
}

function isPumpBoardPaperSource(source) {
  const s = String(source ?? '');
  return s.startsWith('pump-') && !s.startsWith('pump-short-') && !s.startsWith('emasq-');
}

const pumpPaperDynamicRiskLocks = new Set();
async function checkPumpPaperDynamicRisk(trade, markPrice) {
  if (process.env.PUMP_PAPER_DYNAMIC_MANAGEMENT_ENABLED === 'false') return;
  if (!isPumpBoardPaperSource(trade.source)) return;
  if (pumpPaperDynamicRiskLocks.has(trade.id)) return;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const entry = Number(trade.entryPrice);
  const qty = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const mark = Number(markPrice);
  if (!Number.isFinite(entry) || entry <= 0 || !Number.isFinite(qty) || qty <= 0) return;
  if (!Number.isFinite(margin) || margin <= 0 || !Number.isFinite(mark) || mark <= 0) return;

  const pnl = (mark - entry) * qty * sideMult;
  const roe = (pnl / margin) * 100;
  const prevPeak = pumpPaperPeakRoe.get(trade.id) ?? Number(trade.peakRoe ?? 0) ?? 0;
  const peakRoe = Math.max(prevPeak, roe);
  pumpPaperPeakRoe.set(trade.id, peakRoe);

  const isLong = trade.side === 'LONG';
  const updates = {};
  const notes = [];

  if (process.env.PUMP_PAPER_SL_TRAIL_ENABLED !== 'false') {
    const trailStartRoe = Number(process.env.PUMP_PAPER_TRAIL_START_ROE ?? 10);
    if (roe >= trailStartRoe) {
      const targetLockRoe = getTargetLockRoe(roe);
      if (targetLockRoe != null) {
        const leverage = Math.max(1, Number(trade.leverage) || 1);
        const lockMove = targetLockRoe / 100 / leverage;
        const newSl = isLong ? entry * (1 + lockMove) : entry * (1 - lockMove);
        const curSl = Number(trade.sl ?? 0);
        const improves = !Number.isFinite(curSl) || curSl <= 0
          || (isLong ? newSl > curSl : newSl < curSl);
        const validSide = isLong ? newSl < mark : newSl > mark;
        if (Number.isFinite(newSl) && newSl > 0 && validSide && improves) {
          updates.sl = newSl;
          updates.slTrailLockRoe = targetLockRoe;
          notes.push(`pumpPaperSlTrail=${targetLockRoe}%@${newSl}`);
        }
      }
    }
  }

  if (process.env.PUMP_PAPER_NEG_TP_ENABLED !== 'false') {
    const isBrLike = String(trade.source ?? '').includes('br_like');
    const brLikeNegTpEnabled = process.env.EMA_SQUEEZE_PAPER_BR_LIKE_NEG_TP_ENABLED === 'true';
    if (!isBrLike || brLikeNegTpEnabled) {
      const negTpRoe = isBrLike
        ? Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_NEG_TP_ROE ?? -10)
        : Number(process.env.PUMP_PAPER_NEG_TP_ROE ?? -30);
      const alreadyMoved = trade.paperTpMovedToEntry === true || String(trade.note ?? '').includes('pumpPaperTpEntryGuard=');
      if (!alreadyMoved && roe <= negTpRoe) {
        const curTp = Number(trade.tp ?? 0);
        const improvesExit = !Number.isFinite(curTp) || curTp <= 0
          || (isLong ? curTp > entry : curTp < entry);
        const validSide = isLong ? entry > mark : entry < mark;
        if (improvesExit && validSide) {
          updates.tp = entry;
          updates.paperTpMovedToEntry = true;
          updates.paperTpMovedToEntryRoe = +roe.toFixed(2);
          updates.tpMovedToEntryBy = 'NEG_TP_ENTRY_GUARD';
          notes.push(`pumpPaperTpEntryGuard=${negTpRoe}%@${entry}`);
        }
      }
    }
  }

  if (!Object.keys(updates).length) return;

  pumpPaperDynamicRiskLocks.add(trade.id);
  try {
    const store = await readPumpPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'OPEN');
    if (idx < 0) return;
    const row = store.trades[idx];
    const note = [String(row.note ?? ''), ...notes].filter(Boolean).join(' | ').slice(0, 500);
    store.trades[idx] = {
      ...row,
      ...updates,
      peakRoe,
      dynamicRiskUpdatedAt: new Date().toISOString(),
      note,
    };
    await writePumpPaperStore(store, { upsertIds: [trade.id] });
    console.log(`[PumpPaper] DYNAMIC ${row.side} ${row.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% sl=${store.trades[idx].sl ?? '-'} tp=${store.trades[idx].tp ?? '-'}`);
  } finally {
    pumpPaperDynamicRiskLocks.delete(trade.id);
  }
}

const emaSqueezeProfitLocks = new Set();

function isBaseEmaSqueezeShortPaperTrade(trade) {
  const source = String(trade?.source ?? '').toLowerCase();
  const note = String(trade?.note ?? '').toLowerCase();
  return source.startsWith('emasq-')
    && source.includes('squeeze_short')
    && !source.includes('runner')
    && !source.includes('br_like_short')
    && trade?.runnerCandidate !== true
    && !note.includes('runner=y')
    && String(trade?.side ?? '').toUpperCase() === 'SHORT';
}

function recommendedTradeTimeframe(trade) {
  const sourceMatch = String(trade?.source ?? '').match(
    /(?:emasq|pump|cap|edge|ppks|liq|shakeout|top)-(\d+[mh])-/i,
  );
  if (sourceMatch) return sourceMatch[1].toLowerCase();
  const direct = String(trade?.timeframe ?? trade?.tf ?? trade?.pumpSignalTimeframe
    ?? trade?.candlePatternTimeframe ?? '').toLowerCase();
  if (/^\d+[mh]$/.test(direct)) return direct;
  const comboMatch = String(trade?.recommendationCombo ?? '').match(/(?:^|\|)\s*(\d+[mh])\s*(?:\||$)/i);
  return comboMatch?.[1]?.toLowerCase() || '15m';
}

function cachedCandlePatternAt(symbol, interval, signalAt) {
  const candles = klineCache.getIfCached(String(symbol ?? '').toUpperCase(), interval, 500);
  if (!Array.isArray(candles) || candles.length < 3) return null;
  const signalMs = Date.parse(signalAt ?? '');
  const snapshot = Number.isFinite(signalMs)
    ? candles.filter((candle) => Number(candle?.openTime) <= signalMs)
    : candles;
  if (snapshot.length < 3) return null;
  const pattern = detectClosedCandlePattern(snapshot);
  if (!pattern || pattern.name === 'UNKNOWN') return null;
  const candle = snapshot.at(-2);
  return {
    ...pattern,
    timeframe: interval,
    candleOpenTime: Number(candle?.openTime) || null,
    detectedFrom: 'KLINE_AT_SIGNAL',
  };
}

function liquidSpringStructureAtEntry(trade = {}) {
  if (trade.liquidSpringStructureAtEntry
    && typeof trade.liquidSpringStructureAtEntry === 'object') {
    return trade.liquidSpringStructureAtEntry;
  }
  const requested = String(trade.signalTimeframe ?? trade.candlePatternTimeframe ?? '15m').toLowerCase();
  const timeframe = ['5m', '15m'].includes(requested) ? requested : '15m';
  const candles = klineCache.getIfCached(String(trade.symbol ?? '').toUpperCase(), timeframe, 500);
  if (!Array.isArray(candles)) return null;
  return liquidSpringStructureSnapshot(candles, paperTradeSignalAt(trade), { timeframe });
}

function enrichRecommendedPaperCandlePattern(trade) {
  if (!trade || typeof trade !== 'object') return trade;
  const timeframe = recommendedTradeTimeframe(trade);
  const direct = trade.candlePatternAtEntry
    ?? (timeframe === '5m' ? trade.candlePattern5m : trade.candlePattern15m);
  if (direct && (typeof direct !== 'object'
    || !['UNKNOWN', 'NO_DATA'].includes(String(direct.name ?? '').toUpperCase()))) {
    return {
      ...trade,
      candlePatternAtEntry: typeof direct === 'object'
        ? { ...direct, timeframe: direct.timeframe ?? timeframe }
        : { name: String(direct), direction: 'NEUTRAL', timeframe, detectedFrom: 'SOURCE' },
      candlePatternTimeframe: timeframe,
    };
  }
  if (trade.brCandleKind) {
    return {
      ...trade,
      candlePatternAtEntry: {
        name: String(trade.brCandleKind),
        direction: String(trade.brCandleDir ?? 'NEUTRAL'),
        timeframe,
        detectedFrom: 'SOURCE_BR_CANDLE',
      },
      candlePatternTimeframe: timeframe,
    };
  }
  const pattern = cachedCandlePatternAt(
    trade.symbol,
    timeframe,
    trade.sourceSignalAt ?? trade.createdAt ?? trade.openedAt ?? trade.time,
  );
  return pattern
    ? { ...trade, candlePatternAtEntry: pattern, candlePatternTimeframe: timeframe }
    : {
        ...trade,
        candlePatternAtEntry: {
          name: 'NO_DATA',
          direction: 'NEUTRAL',
          timeframe,
          detectedFrom: 'NO_OHLC_SNAPSHOT',
        },
        candlePatternTimeframe: timeframe,
      };
}

function getEmaSqueezeShortRunnerTargetRoe(trade) {
  const source = String(trade?.source ?? '').toLowerCase();
  const sourceInterval = source.match(/^emasq-(5m|15m|1h)-/)?.[1];
  const interval = sourceInterval ?? String(trade?.pumpSignalTimeframe ?? '').toLowerCase();
  const interval15m = interval === '15m';
  const btcAligned = String(trade?.btcTrendDir ?? trade?.btcHealth?.btcTrendDir ?? '').toLowerCase() === 'down';
  const normalTarget = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_RUNNER_TP_ROE ?? 10);
  const strongTarget = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_STRONG_RUNNER_TP_ROE ?? 15);
  const selected = interval15m || btcAligned ? strongTarget : normalTarget;
  return Number.isFinite(selected) && selected > 0 ? selected : (interval15m || btcAligned ? 15 : 10);
}

const emaSqueezeShortPartialTpLocks = new Set();
async function checkEmaSqueezeShortPartialTp(trade, markPrice) {
  if (process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_PARTIAL_TP_ENABLED === 'false') return false;
  if (!isBaseEmaSqueezeShortPaperTrade(trade) || trade.status !== 'OPEN' || trade.partialTpTaken === true) return false;
  if (emaSqueezeShortPartialTpLocks.has(trade.id)) return false;

  const entry = Number(trade.entryPrice);
  const mark = Number(markPrice);
  const quantity = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const leverage = Math.max(1, Number(trade.leverage) || 1);
  if (![entry, mark, quantity, margin].every(Number.isFinite)
      || entry <= 0 || mark <= 0 || quantity <= 0 || margin <= 0) return false;

  const tp1Roe = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_PARTIAL_TP_ROE ?? 5);
  const closeRatioRaw = Number(process.env.EMA_SQUEEZE_PAPER_SQUEEZE_SHORT_PARTIAL_CLOSE_RATIO ?? 0.5);
  const closeRatio = Math.min(0.95, Math.max(0.05, closeRatioRaw));
  if (!Number.isFinite(tp1Roe) || tp1Roe <= 0) return false;
  const tp1Price = entry * (1 - tp1Roe / 100 / leverage);
  if (mark > tp1Price) return false;

  const closedQuantity = quantity * closeRatio;
  const remainingQuantity = quantity - closedQuantity;
  const partialPnl = (entry - tp1Price) * closedQuantity;
  const realizedPnl = Number(trade.realizedPnl ?? 0) + partialPnl;
  const runnerTargetRoe = Math.max(tp1Roe, getEmaSqueezeShortRunnerTargetRoe(trade));
  const runnerTp = entry * (1 - runnerTargetRoe / 100 / leverage);
  const nowIso = new Date().toISOString();

  emaSqueezeShortPartialTpLocks.add(trade.id);
  try {
    const store = await readPumpPaperStore();
    const idx = store.trades.findIndex((row) => row.id === trade.id && row.status === 'OPEN');
    if (idx < 0 || store.trades[idx].partialTpTaken === true) return false;
    const row = store.trades[idx];
    const ruleNote = `squeezeShortTP1=${tp1Roe}% close=${(closeRatio * 100).toFixed(0)}% pnl=${partialPnl.toFixed(4)}; TP2=${runnerTargetRoe}%; SL=BE`;
    store.trades[idx] = {
      ...row,
      originalQuantity: Number(row.originalQuantity ?? quantity),
      quantity: remainingQuantity,
      realizedPnl,
      partialTpTaken: true,
      partialTpTakenAt: nowIso,
      partialTpRoe: tp1Roe,
      partialTpPrice: tp1Price,
      partialTpCloseRatio: closeRatio,
      partialTpQuantity: closedQuantity,
      tp: runnerTp,
      sl: entry,
      squeezeShortRunnerTargetRoe: runnerTargetRoe,
      dynamicRiskUpdatedAt: nowIso,
      note: [ruleNote, String(row.note ?? '')].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writePumpPaperStore(store, { upsertIds: [trade.id] });
    scheduleEmaSqueezePaperBroadcast(50);
    console.log(`[EmaSqueezePaper] SQUEEZE_SHORT_TP1 ${row.symbol}: close=${(closeRatio * 100).toFixed(0)}% roe=${tp1Roe}% partialPnl=${partialPnl.toFixed(4)} TP2=${runnerTargetRoe}% SL=BE`);
    return true;
  } finally {
    emaSqueezeShortPartialTpLocks.delete(trade.id);
  }
}

function getEmaSqueezeFastGivebackGroup(trade) {
  const source = String(trade?.source ?? '').toLowerCase();
  if (!source.startsWith('emasq-')) return null;
  const side = String(trade?.side ?? '').toUpperCase();
  const isRunner = trade?.runnerCandidate === true
    || source.includes('-runner')
    || String(trade?.note ?? '').toLowerCase().includes('runner=y');
  if (isRunner && side === 'SHORT') return 'RUNNER_SHORT';
  if (isRunner && side === 'LONG') return 'RUNNER_LONG';
  if (source.includes('squeeze_short') && side === 'SHORT') return 'SQUEEZE_SHORT_SHORT';
  if (source.includes('breakdown') && side === 'SHORT') return 'BREAKDOWN_SHORT';
  if (source.includes('breakout') && side === 'LONG') return 'BREAKOUT_LONG';
  return null;
}

function getEmaSqueezeFastGivebackLockRoe(trade, roe) {
  if (process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_TRAIL_ENABLED === 'false') return null;
  const group = getEmaSqueezeFastGivebackGroup(trade);
  if (!group) return null;
  const groups = new Set(String(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_GROUPS
    ?? 'SQUEEZE_SHORT_SHORT,BREAKDOWN_SHORT,RUNNER_SHORT,BREAKOUT_LONG,RUNNER_LONG')
    .split(',')
    .map((s) => s.trim().toUpperCase())
    .filter(Boolean));
  if (!groups.has(group)) return null;
  const firstTrigger = Number(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_TRIGGER_ROE ?? 5);
  const firstLock = Number(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_LOCK_ROE ?? 1);
  const secondTrigger = Number(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_SECOND_TRIGGER_ROE ?? 10);
  const secondLock = Number(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_SECOND_LOCK_ROE ?? 5);
  if (Number.isFinite(secondTrigger) && Number.isFinite(secondLock) && roe >= secondTrigger) {
    return { group, lockRoe: secondLock, triggerRoe: secondTrigger };
  }
  if (Number.isFinite(firstTrigger) && Number.isFinite(firstLock) && roe >= firstTrigger) {
    return { group, lockRoe: firstLock, triggerRoe: firstTrigger };
  }
  return null;
}

async function checkEmaSqueezePaperProfit(trade, markPrice) {
  if (!String(trade.source ?? '').startsWith('emasq-')) return;
  if (isBaseEmaSqueezeShortPaperTrade(trade) && trade.partialTpTaken === true) return;
  if (emaSqueezeProfitLocks.has(trade.id)) return;
  if (process.env.EMA_SQUEEZE_PAPER_SL_TRAIL_ENABLED === 'false') return;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const entry = Number(trade.entryPrice);
  const qty = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  if (!Number.isFinite(entry) || !Number.isFinite(qty) || !Number.isFinite(margin) || margin <= 0) return;

  const pnl = (Number(markPrice) - entry) * qty * sideMult;
  const roe = (pnl / margin) * 100;
  const prevPeak = emaSqueezePaperPeakRoe.get(trade.id) ?? Number(trade.peakRoe ?? 0) ?? 0;
  const peakRoe = Math.max(prevPeak, roe);
  emaSqueezePaperPeakRoe.set(trade.id, peakRoe);

  const macroShock = getBtcMacroShockGuard();
  const macroExitMinRoe = Number(process.env.EMA_SQUEEZE_PAPER_MACRO_SHOCK_EXIT_MIN_ROE ?? 1);
  if (process.env.EMA_SQUEEZE_PAPER_MACRO_SHOCK_EXIT !== 'false'
      && trade.side === 'LONG'
      && macroShock.active
      && roe >= macroExitMinRoe) {
    emaSqueezeProfitLocks.add(trade.id);
    try {
      await closePumpPaperTrade({
        id: trade.id,
        exitPrice: Number(markPrice),
        outcome: 'BTC_MACRO_EXIT',
      });
      console.log(`[EmaSqueezePaper] BTC_MACRO_EXIT ${trade.symbol} roe=${roe.toFixed(1)}% - ${macroShock.reason}`);
    } finally {
      emaSqueezeProfitLocks.delete(trade.id);
    }
    return;
  }

  const fastGiveback = getEmaSqueezeFastGivebackLockRoe(trade, roe);
  const trailStartRoe = fastGiveback
    ? Number(process.env.EMA_SQUEEZE_PAPER_FAST_GIVEBACK_TRIGGER_ROE ?? 5)
    : Number(process.env.EMA_SQUEEZE_PAPER_TRAIL_START_ROE ?? 10);
  if (roe < trailStartRoe) return;
  const normalLockRoe = getTargetLockRoe(roe);
  const targetLockRoe = fastGiveback
    ? Math.max(Number(normalLockRoe ?? -Infinity), Number(fastGiveback.lockRoe))
    : normalLockRoe;
  if (targetLockRoe == null) return;

  emaSqueezeProfitLocks.add(trade.id);
  try {
    const store = await readPumpPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'OPEN');
    if (idx < 0) return;
    const row = store.trades[idx];
    const leverage = Math.max(1, Number(row.leverage ?? trade.leverage) || 1);
    const isLong = row.side === 'LONG';
    const lockMove = targetLockRoe / 100 / leverage;
    const newSl = isLong ? entry * (1 + lockMove) : entry * (1 - lockMove);
    const mark = Number(markPrice);
    if (!Number.isFinite(newSl) || newSl <= 0 || !Number.isFinite(mark) || mark <= 0) return;
    if ((isLong && newSl >= mark) || (!isLong && newSl <= mark)) return;

    const curSl = Number(row.sl ?? 0);
    const improves = !Number.isFinite(curSl) || curSl <= 0
      || (isLong ? newSl > curSl : newSl < curSl);
    if (!improves) return;

    const notePart = fastGiveback
      ? `fastGivebackSlTrail=${fastGiveback.group}:${targetLockRoe}%@${newSl}; trigger=${fastGiveback.triggerRoe}%`
      : `paperSlTrail=${targetLockRoe}%@${newSl}`;
    store.trades[idx] = {
      ...row,
      sl: newSl,
      peakRoe,
      slTrailLockRoe: targetLockRoe,
      note: [String(row.note ?? ''), notePart].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writePumpPaperStore(store, { upsertIds: [trade.id] });
    console.log(`[EmaSqueezePaper] ${fastGiveback ? 'FAST-GIVEBACK-SL' : 'SL_TRAIL'} ${row.side} ${row.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% lock=${targetLockRoe}% sl=${newSl}${fastGiveback ? ` group=${fastGiveback.group}` : ''}`);
  } finally {
    emaSqueezeProfitLocks.delete(trade.id);
  }
}

const pumpPaperTimeoutLocks = new Set();
async function checkPumpPaperTimeout(trade, markPrice) {
  if (!trade.openedAt) return;
  if (String(trade.source ?? '').startsWith('emasq-')) return;
  const timeoutMs = runtimeSettings.pumpPaperTimeoutH * 3600_000;
  const openedMs  = Date.parse(trade.openedAt);
  if (Date.now() - openedMs < timeoutMs) return;

  // Tính ROE theo mark price hiện tại
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = (markPrice - Number(trade.entryPrice)) * Number(trade.quantity) * sideMult;
  const roe = Number(trade.marginUsdt) > 0 ? (pnl / Number(trade.marginUsdt)) * 100 : 0;

  // Chỉ chốt khi đang lời > 1% — âm/flat thì để SL tự xử lý
  if (roe <= 1) return;

  if (pumpPaperTimeoutLocks.has(trade.id)) return;
  pumpPaperTimeoutLocks.add(trade.id);
  try {
    await closePumpPaperTrade({ id: trade.id, exitPrice: markPrice, outcome: 'TIMEOUT' });
    console.log(`[PumpPaper] ⏱ TIMEOUT ${trade.side} ${trade.symbol} roe=${roe.toFixed(1)}% after ${runtimeSettings.pumpPaperTimeoutH}h`);
  } finally {
    pumpPaperTimeoutLocks.delete(trade.id);
  }
}

const pumpPaperTpSlLocks = new Set();
async function checkPumpPaperTpSl(trade, markPrice) {
  if (!trade.tp && !trade.sl) return;
  if (pumpPaperTpSlLocks.has(trade.id)) return;
  const isLong = trade.side === 'LONG';
  const tpHit = trade.tp != null && (isLong ? markPrice >= trade.tp : markPrice <= trade.tp);
  const slHit = trade.sl != null && (isLong ? markPrice <= trade.sl : markPrice >= trade.sl);
  if (!tpHit && !slHit) return;
  pumpPaperTpSlLocks.add(trade.id);
  try {
    const exitPrice = tpHit ? trade.tp : trade.sl;
    const entry = Number(trade.entryPrice);
    const closedAtEntry = tpHit
      && Number.isFinite(entry)
      && entry > 0
      && Math.abs(Number(exitPrice) - entry) / entry < 1e-8;
    const outcome = tpHit
      ? (closedAtEntry && trade.tpMovedToEntryBy === 'BR_LIKE_NEG_5' ? 'BR_LIKE_TP_ENTRY' : 'TP')
      : 'SL';
    const partialClosedAtBreakeven = !tpHit
      && trade.partialTpTaken === true
      && Number.isFinite(entry)
      && entry > 0
      && Math.abs(Number(exitPrice) - entry) / entry < 1e-8;
    const isSqueezeShortPartial = isBaseEmaSqueezeShortPaperTrade(trade) && trade.partialTpTaken === true;
    const finalOutcome = isSqueezeShortPartial && tpHit
      ? 'SQUEEZE_SHORT_TP2'
      : isSqueezeShortPartial && partialClosedAtBreakeven
        ? 'SQUEEZE_SHORT_PARTIAL_BE'
        : tpHit && closedAtEntry && trade.tpMovedToEntryBy === 'RUNNER_NEG_5'
          ? 'RUNNER_TP_ENTRY'
          : outcome;
    await closePumpPaperTrade({ id: trade.id, exitPrice, outcome: finalOutcome });
    console.log(`[PumpPaper] 🎯 ${finalOutcome} hit ${trade.side} ${trade.symbol} exit=${exitPrice}`);
  } finally {
    pumpPaperTpSlLocks.delete(trade.id);
  }
}

const emaSqueezeRunnerTpEntryLocks = new Set();
async function checkEmaSqueezeRunnerTpToEntry(trade, markPrice) {
  if (process.env.EMA_SQUEEZE_PAPER_RUNNER_TP_ENTRY_GUARD === 'false') return;
  if (!isEmaSqueezeRunnerPaperTrade(trade)) return;
  if (trade.status !== 'OPEN') return;
  if (emaSqueezeRunnerTpEntryLocks.has(trade.id)) return;

  const entry = Number(trade.entryPrice);
  const qty = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const mark = Number(markPrice);
  if (![entry, qty, margin, mark].every(Number.isFinite) || entry <= 0 || qty <= 0 || margin <= 0 || mark <= 0) return;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = (mark - entry) * qty * sideMult;
  const roe = pnl / margin * 100;
  const triggerRoe = -Math.abs(Number(process.env.EMA_SQUEEZE_PAPER_RUNNER_TP_ENTRY_ROE
    ?? process.env.EMA_SQUEEZE_PAPER_BR_LIKE_TP_ENTRY_ROE
    ?? 5));
  if (!Number.isFinite(roe) || roe > triggerRoe) return;

  const curTp = Number(trade.tp ?? 0);
  const isLong = trade.side === 'LONG';
  const improvesExit = !Number.isFinite(curTp) || curTp <= 0 || (isLong ? curTp > entry : curTp < entry);
  const validSide = isLong ? entry > mark : entry < mark;
  const alreadyMoved = trade.tpMovedToEntryBy === 'RUNNER_NEG_5'
    || String(trade.note ?? '').includes('runnerTpEntryGuard=');
  if (!improvesExit || !validSide || alreadyMoved) return;

  emaSqueezeRunnerTpEntryLocks.add(trade.id);
  try {
    const store = await readPumpPaperStore();
    const idx = store.trades.findIndex((row) => row.id === trade.id && row.status === 'OPEN');
    if (idx < 0) return;
    const row = store.trades[idx];
    store.trades[idx] = {
      ...row,
      tp: entry,
      paperTpMovedToEntry: true,
      paperTpMovedToEntryRoe: +roe.toFixed(2),
      tpMovedToEntryBy: 'RUNNER_NEG_5',
      dynamicRiskUpdatedAt: new Date().toISOString(),
      note: [String(row.note ?? ''), `runnerTpEntryGuard=${triggerRoe}%@${entry}; roe=${roe.toFixed(2)}%`]
        .filter(Boolean)
        .join(' | ')
        .slice(0, 500),
    };
    await writePumpPaperStore(store, { upsertIds: [trade.id] });
    scheduleEmaSqueezePaperBroadcast(50);
    console.log(`[EmaSqueezeRunnerPaper] RUNNER-TP-ENTRY ${row.side} ${row.symbol}: roe=${roe.toFixed(1)}% <= ${triggerRoe}% tp=${entry}`);
  } finally {
    emaSqueezeRunnerTpEntryLocks.delete(trade.id);
  }
}

