async function syncPumpPaperTicker() {
  if (!pumpPaperTicker) return;
  const store = await readPumpPaperStore();
  const symbols = [...getPumpPaperActiveIndex(store).pumpBySymbol.keys()];
  pumpPaperTicker.setSymbols(symbols);
}

async function processEmaSqueezePaperSymbol(symbol, markPrice) {
  const store = await readPumpPaperStore();
  const trades = getPumpPaperActiveIndex(store).emaBySymbol.get(String(symbol ?? '').toUpperCase()) ?? [];
  for (const trade of trades) {
    if (trade.status === 'PENDING') {
      await fillPumpPendingTrade(trade, markPrice);
      continue;
    }
    const partialTpTakenNow = await checkEmaSqueezeShortPartialTp(trade, markPrice);
    if (partialTpTakenNow) continue;
    await checkEmaSqueezeBrLikeTpToEntry(trade, markPrice);
    await checkEmaSqueezeRunnerTpToEntry(trade, markPrice);
    await checkEmaSqueezeRunnerTpEntryFailFast(trade, markPrice);
    await checkEmaSqueezeBreakoutTpToEntry(trade, markPrice);
    await checkPumpPaperTpSl(trade, markPrice);
    await checkEmaSqueezePaperProfit(trade, markPrice);
  }
  await processBrLikeLimitPaperSymbol(symbol, markPrice);
}

function queueEmaSqueezePaperProcessing(symbol, markPrice) {
  emaSqueezePendingProcess.set(symbol, markPrice);
  if (emaSqueezeProcessTimer || emaSqueezeProcessRunning) return;
  emaSqueezeProcessTimer = setTimeout(drainEmaSqueezePaperProcessing, 250);
}

async function drainEmaSqueezePaperProcessing() {
  emaSqueezeProcessTimer = null;
  if (emaSqueezeProcessRunning) return;
  const next = emaSqueezePendingProcess.entries().next();
  if (next.done) return;
  const [symbol, markPrice] = next.value;
  emaSqueezePendingProcess.delete(symbol);
  emaSqueezeProcessRunning = true;
  try {
    if (Number.isFinite(Number(markPrice)) && Number(markPrice) > 0) {
      await processEmaSqueezePaperSymbol(symbol, Number(markPrice));
    }
  } catch (err) {
    console.warn(`[EmaSqueezePaper] socket processing ${symbol}:`, err.message);
  } finally {
    emaSqueezeProcessRunning = false;
    if (emaSqueezePendingProcess.size > 0 && !emaSqueezeProcessTimer) {
      emaSqueezeProcessTimer = setTimeout(drainEmaSqueezePaperProcessing, 250);
    }
  }
}

async function syncEmaSqueezePaperTicker() {
  if (!emaSqueezePaperTicker) return;
  const store = await readPumpPaperStore();
  const brLimitStore = await readBrLikeLimitPaperStore().catch(() => ({ trades: [] }));
  const symbols = [...new Set([
    ...getPumpPaperActiveIndex(store).emaBySymbol.keys(),
    ...brLimitStore.trades
      .filter((t) => ['PENDING', 'OPEN'].includes(t.status))
      .map((t) => t.symbol),
  ])];
  emaSqueezePaperTicker.setSymbols(symbols);
}

function startEmaSqueezePaperTicker() {
  if (emaSqueezePaperTicker) return;
  emaSqueezePaperTicker = sharedLastTicker.createClient(
    'emaSqueezePaper',
    ({ symbol, markPrice, eventTime }) => {
      emaSqueezeSocketMarks.set(symbol, markPrice);
      emaSqueezeSocketMarkAt.set(symbol, eventTime);
      scheduleEmaSqueezePaperBroadcast();
      queueEmaSqueezePaperProcessing(symbol, markPrice);
    },
  );
  console.log('[EmaSqueezePaper] Shared last-price ticker consumer started.');
  syncEmaSqueezePaperTicker().catch(() => {});
  setInterval(() => syncEmaSqueezePaperTicker().catch(() => {}), 30_000);
  setInterval(() => expireOldBrLikeLimitPaper().catch(() => {}), 60_000);
  setInterval(() => enforceBrLikeBtcTurnPositiveCuts().catch((err) => {
    console.warn('[EmaSqueezePaper] btc-turn positive-cut failed:', err.message);
  }), 15_000);
  setInterval(() => enforceRunnerBtcTurnPositiveCuts().catch((err) => {
    console.warn('[EmaSqueezeRunnerPaper] btc-turn positive-cut failed:', err.message);
  }), 15_000);
  setInterval(() => enforceBreakoutBtcTurnPositiveCuts().catch((err) => {
    console.warn('[EmaSqueezeBreakoutPaper] btc-turn positive-cut failed:', err.message);
  }), 15_000);
}

function startPumpPaperTicker() {
  if (pumpPaperTicker) return;
  pumpPaperTicker = sharedLastTicker.createClient(
    'pumpPaper',
    ({ symbol, markPrice, eventTime }) => {
      pumpMarkCache.set(symbol, markPrice);
      pumpMarkCacheAt.set(symbol, eventTime);
      scheduleEmaSqueezePaperBroadcast();
    },
  );
  console.log('[PumpPaper] Shared last-price ticker consumer started (1s batched processing).');
  syncPumpPaperTicker().catch(() => {});
  setInterval(() => syncPumpPaperTicker().catch(() => {}), 30_000);
  setInterval(() => processPumpPaperCachedMarks().catch((err) => {
    console.warn('[PumpPaper] Batch mark processing failed:', err.message);
  }), 1_000);
  const restMarkIntervalMs = Math.max(
    15_000,
    Number(process.env.PUMP_PAPER_REST_MARK_INTERVAL_MS ?? 30_000),
  );
  setTimeout(() => refreshPumpPaperRestMarks().catch(() => {}), 1_500).unref?.();
  setInterval(() => refreshPumpPaperRestMarks().catch(() => {}), restMarkIntervalMs).unref?.();
  setInterval(() => expireOldEmaSqueezePending().catch(() => {}), 60_000);
  setInterval(() => exitEuphoriaBrLikeOnBtcReversal().catch(() => {}), 60_000);
  startEmaSqueezePaperTicker();
}

// Xóa lệnh EMA Squeeze paper PENDING quá TTL (4h) chưa khớp (chỉ source emasq-, không đụng pump strategy)
async function expireOldEmaSqueezePending() {
  const ttlMs = Number(process.env.EMA_SQUEEZE_PAPER_PENDING_TTL_MS ?? 4 * 3600 * 1000);
  const store = await readPumpPaperStore();
  const now = Date.now();
  const keep = [];
  const expiredIds = [];
  let removed = 0;
  for (const t of store.trades) {
    if (t.status === 'PENDING' && String(t.source ?? '').startsWith('emasq-')
        && (now - (Date.parse(t.createdAt ?? 0) || now)) > ttlMs) {
      console.log(`[EmaSqueezePaper] EXPIRE pending ${t.side} ${t.symbol} - >${(ttlMs / 3600000).toFixed(0)}h chưa khớp, xóa lệnh`);
      removed++;
      if (t.id) expiredIds.push(t.id);
      continue;
    }
    keep.push(t);
  }
  if (removed) {
    store.trades = keep;
    await writePumpPaperStore(store, { deleteIds: expiredIds });
    syncEmaSqueezePaperTicker().catch(() => {});
  }
}

// Cắt nhóm BR-like vào "sai đỉnh/đáy" KHI BTC đảo RÕ (không phải giảm/tăng nhẹ):
//   LONG  vào lúc euphoria (pct6h>1%)      → cắt khi BTC đảo XUỐNG rõ (WEAK + EMA1h below / pct6h<-0.5)
//   SHORT vào lúc capitulation (pct6h<-1%) → cắt khi BTC đảo LÊN  rõ (STRONG / EMA1h above + pct6h>+0.5)
// Nhắm đúng nhóm nhờ btcHealth snapshot lúc entry; tránh cắt hàng loạt khi chỉ dao động nhẹ.
async function exitEuphoriaBrLikeOnBtcReversal() {
  if (process.env.EMA_SQUEEZE_PAPER_BR_LIKE_EUPHORIA_EXIT_ENABLED === 'false') return;
  const health = btcHealthCache.data;
  if (!health || health.error) return;
  const regime = emaSqueezeBtcRegime(health);
  const p6 = Number(health.pct6h ?? 0);

  const longExitPct6h = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_EUPHORIA_EXIT_PCT6H ?? -0.5);
  const longReversal = regime === 'WEAK' && (health.emaTrend1h === 'below' || p6 < longExitPct6h);
  const shortExitPct6h = Number(process.env.EMA_SQUEEZE_PAPER_BR_LIKE_SHORT_EXIT_PCT6H ?? 0.5);
  const shortReversal = regime === 'STRONG' || (health.emaTrend1h === 'above' && p6 > shortExitPct6h);
  if (!longReversal && !shortReversal) return;

  const euphoriaPct6h = Number(process.env.EMA_SQUEEZE_BR_LIKE_BTC_MAX_PCT6H ?? 1.0);
  const capitulationPct6h = Number(process.env.EMA_SQUEEZE_BR_LIKE_SHORT_BTC_MIN_PCT6H ?? -1.0);
  const store = await readPumpPaperStore();
  const targets = store.trades.filter((t) => {
    if (t.status !== 'OPEN' || !String(t.source ?? '').includes('-br_like')) return false;
    const ep = Number(t.btcHealth?.pct6h);
    if (t.side === 'LONG') return longReversal && Number.isFinite(ep) && ep > euphoriaPct6h;
    if (t.side === 'SHORT') return shortReversal && Number.isFinite(ep) && ep < capitulationPct6h;
    return false;
  });
  if (!targets.length) return;

  const snapshotMarks = new Map((_snapshotCache ?? [])
    .map((r) => [r.symbol, Number(r.markPrice ?? r.lastPrice ?? r.price)])
    .filter(([, p]) => Number.isFinite(p) && p > 0));
  for (const t of targets) {
    const mark = pumpMarkCache.get(t.symbol) ?? sharedLastTicker.getPrice?.(t.symbol) ?? snapshotMarks.get(t.symbol);
    if (!Number.isFinite(Number(mark)) || Number(mark) <= 0) continue;
    const dir = t.side === 'LONG' ? 'đảo xuống' : 'đảo lên';
    await closePumpPaperTrade({ id: t.id, exitPrice: Number(mark), outcome: 'BTC_REVERSAL' })
      .then(() => console.log(`[EmaSqueezePaper] BTC-REVERSAL-EXIT ${t.side} ${t.symbol} (vào pct6h=${t.btcHealth?.pct6h}%, BTC nay ${regime} ${dir} pct6h=${health.pct6h}% EMA1h=${health.emaTrend1h}) exit=${mark}`))
      .catch((e) => console.warn(`[EmaSqueezePaper] btc-reversal-exit ${t.symbol}:`, e.message));
  }
}

// ── End pump paper trade system ───────────────────────────────────────────────

// Edge paper trade system (private to /edge-short)
const EDGE_PAPER_STORE_CACHE_VERSION = 'EDGE_PAPER_STORE_CACHE_V1_20260822';
let _edgePaperStoreCache = null;
let _edgePaperStoreLoadPromise = null;
async function readEdgePaperStore() {
  if (_edgePaperStoreCache) return _edgePaperStoreCache;
  if (_edgePaperStoreLoadPromise) return _edgePaperStoreLoadPromise;
  _edgePaperStoreLoadPromise = (async () => {
    try {
      const raw = await readFile(EDGE_PAPER_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed?.trades)) throw new Error('invalid structure');
      _edgePaperStoreCache = parsed;
      console.log(`[EdgePaper] Store cached in memory (${parsed.trades.length} trades; ${EDGE_PAPER_STORE_CACHE_VERSION}).`);
    } catch (e) {
      console.warn('[EdgePaper] Store read error, starting fresh:', e.message);
      _edgePaperStoreCache = { trades: [] };
    } finally {
      _edgePaperStoreLoadPromise = null;
    }
    return _edgePaperStoreCache;
  })();
  return _edgePaperStoreLoadPromise;
}

let _edgePaperWriteLock = Promise.resolve();
let _edgePaperMutationLock = Promise.resolve();
let edgeShortLabelDecorationCache = null;
async function writeEdgePaperStore(store) {
  edgeShortLabelDecorationCache = null;
  _edgePaperStoreCache = store;
  _edgePaperWriteLock = _edgePaperWriteLock
    .catch((error) => console.warn(`[EdgePaper] previous write failed; queue continues: ${error.message}`))
    .then(() => atomicWriteJson(EDGE_PAPER_FILE, store));
  return _edgePaperWriteLock;
}

function mutateEdgePaperStore(mutator) {
  const run = _edgePaperMutationLock
    .catch(() => {})
    .then(async () => {
      await _edgePaperWriteLock.catch(() => {});
      const store = await readEdgePaperStore();
      const result = await mutator(store);
      if (result?.changed !== false) await writeEdgePaperStore(store);
      return result;
    });
  _edgePaperMutationLock = run.then(() => undefined, () => undefined);
  return run;
}

async function upsertEdgePaperTrade(trade) {
  return mutateEdgePaperStore((store) => {
    const index = store.trades.findIndex((row) => String(row?.id) === String(trade?.id));
    if (index >= 0) store.trades[index] = trade;
    else store.trades.unshift(trade);
    return { changed: true, trade };
  });
}

async function recoverEdgePaperEntryJournal() {
  const latest = await readLatestEdgePaperJournalRecords(EDGE_PAPER_ENTRY_JOURNAL_FILE);
  if (!latest.size) return { recoveredIds: [] };
  const result = await mutateEdgePaperStore((store) => {
    const recovered = recoverEdgePaperTradesFromJournal(store, latest);
    if (recovered.recoveredIds.length) store.trades = recovered.store.trades;
    return { changed: recovered.recoveredIds.length > 0, recoveredIds: recovered.recoveredIds };
  });
  if (result.recoveredIds.length) {
    console.warn(`[EdgePaperJournal] recovered ${result.recoveredIds.length} paper row(s): ${result.recoveredIds.join(', ')}`);
  }
  return result;
}

async function writeEdgePaperCandleBackfill(enrichedStore) {
  const enrichedById = new Map((enrichedStore?.trades ?? []).map((trade) => [String(trade?.id ?? ''), trade]));
  return mutateEdgePaperStore((store) => {
    let changed = false;
    store.trades = store.trades.map((trade) => {
      const enriched = enrichedById.get(String(trade?.id ?? ''));
      if (!enriched) return trade;
      const patch = {};
      if (!trade.candlePatternAtEntry && enriched.candlePatternAtEntry) patch.candlePatternAtEntry = enriched.candlePatternAtEntry;
      if (!trade.btcCandlePatternAtEntry && enriched.btcCandlePatternAtEntry) patch.btcCandlePatternAtEntry = enriched.btcCandlePatternAtEntry;
      if (!Object.keys(patch).length) return trade;
      changed = true;
      return { ...trade, ...patch };
    });
    return { changed };
  });
}

function edgeShortLabelStoreKey(trades = []) {
  let closed = 0;
  let latestClosedAt = '';
  for (const trade of trades) {
    if (trade?.status !== 'CLOSED') continue;
    closed += 1;
    const closedAt = String(trade.closedAt ?? '');
    if (closedAt > latestClosedAt) latestClosedAt = closedAt;
  }
  const newest = trades[0] ?? {};
  return [
    trades.length,
    closed,
    newest.id ?? '',
    newest.createdAt ?? '',
    latestClosedAt,
  ].join('|');
}

function getDecoratedEdgeShortLabelTrades(trades = []) {
  const key = edgeShortLabelStoreKey(trades);
  if (edgeShortLabelDecorationCache?.key === key) {
    return edgeShortLabelDecorationCache.trades;
  }
  const decorated = decorateEdgeShortUtadSnapshots(decorateEdgeShortLongSpringSnapshots(
    decorateSourceLongCorrReboundTrades(decorateEdgeShortBestProfileSnapshots(
      decorateEdgeShortLiveSnapshots(
        decorateEdgeShortBestSnapshots(
          decorateEdgeShortWave2cSnapshots(
            decorateEdgeShortWave2bSnapshots(
              decorateEdgeShortTierSnapshots(
                decorateEdgeShortLabelSnapshots(trades),
              ),
            ),
          ),
        ),
      ),
    ), { sourcePage: 'edge' }),
  ));
  edgeShortLabelDecorationCache = { key, trades: decorated };
  return decorated;
}

function enrichEdgePaperTrade(t, markPrice) {
  const mark = Number(markPrice ?? t.markPrice ?? t.exitPrice ?? t.entryPrice);
  const entry = Number(t.entryPrice);
  const qty = Number(t.quantity);
  const margin = Number(t.marginUsdt);
  const sideMult = t.side === 'LONG' ? 1 : -1;
  const isActive = t.status === 'OPEN';
  const pnl = isActive ? (mark - entry) * qty * sideMult : (t.pnl ?? null);
  const roe = isActive && margin > 0 ? (pnl / margin) * 100 : (t.roe ?? null);
  return { ...t, markPrice: mark, pnl, roe };
}

async function getEdgePaperTrades({ day = 'all', fromDay = '', toDay = '', page = 1, pageSize = 300 } = {}) {
  const store = await readEdgePaperStore();
  const allStoreTrades = getDecoratedEdgeShortLabelTrades(
    Array.isArray(store.trades) ? store.trades : [],
  );
  const availableDays = [...new Set(allStoreTrades
    .map((trade) => liquidPaperTradeDayKey(trade))
    .filter(Boolean))]
    .sort((a, b) => b.localeCompare(a));
  const dateRange = normalizeLiquidPaperDateRange({ day, fromDay, toDay });
  const selectedStoredTrades = dateRange.mode === 'all'
    ? allStoreTrades
    : allStoreTrades.filter((trade) => liquidPaperDayInRange(
      liquidPaperTradeDayKey(trade),
      dateRange,
    ));
  const pageNum = Math.max(1, Math.floor(Number(page) || 1));
  const pageSizeNum = Math.max(25, Math.min(1000, Math.floor(Number(pageSize) || 300)));
  const sortedStoredTrades = selectedStoredTrades.slice().sort((a, b) => {
    const aStatus = a.status === 'CLOSED' ? 1 : 0;
    const bStatus = b.status === 'CLOSED' ? 1 : 0;
    if (aStatus !== bStatus) return aStatus - bStatus;
    return (Date.parse(b.createdAt ?? '') || 0) - (Date.parse(a.createdAt ?? '') || 0);
  });
  const totalRows = sortedStoredTrades.length;
  const totalPages = Math.max(1, Math.ceil(totalRows / pageSizeNum));
  const safePage = Math.min(pageNum, totalPages);
  const pageStart = (safePage - 1) * pageSizeNum;
  const pageStoredTrades = sortedStoredTrades.slice(pageStart, pageStart + pageSizeNum);
  const trades = selectedStoredTrades.map((t) => enrichEdgePaperTrade(t, edgeMarkCache.get(t.symbol)));
  const pageTrades = pageStoredTrades.map((t) => enrichEdgePaperTrade(t, edgeMarkCache.get(t.symbol)));
  const open = trades.filter((t) => t.status !== 'CLOSED');
  const closed = trades.filter((t) => t.status === 'CLOSED');
  const wins = closed.filter((t) => (t.pnl ?? 0) > 0).length;
  const tpHits = closed.filter((t) => t.outcome === 'TP').length;
  const slHits = closed.filter((t) => t.outcome === 'SL').length;
  const avgRoe = closed.length > 0 ? closed.reduce((s, t) => s + (t.roe ?? 0), 0) / closed.length : null;
  const realizedPnl = closed.reduce((s, t) => s + Number(t.pnl ?? 0), 0);
  const unrealizedPnl = open.reduce((s, t) => s + Number(t.pnl ?? 0), 0);
  const supportEntryStats = paperSupportEntryStats(
    decorateRecommendedSupportEntrySnapshots(
      trades.map((trade) => ({ ...trade, sourcePage: 'edge' })),
    ),
  );
  const summary = {
    total: trades.length,
    open: open.length,
    closed: closed.length,
    wins,
    losses: closed.length - wins,
    tpHits,
    slHits,
    avgRoe: avgRoe != null ? +avgRoe.toFixed(1) : null,
    realizedPnl: +realizedPnl.toFixed(4),
    unrealizedPnl: +unrealizedPnl.toFixed(4),
    netPnl: +(realizedPnl + unrealizedPnl).toFixed(4),
  };
  const wave2cStats = edgeShortWave2cStats(trades);
  const sourceLongCorrReboundStats = buildSourceLongCorrReboundStats(
    trades,
    { sourcePage: 'edge' },
  );
  return {
    trades: pageTrades,
    summary,
    comboStats: pumpComboStatsOf(selectedStoredTrades, { context: 'edge' }),
    supportEntryStats,
    labelStats: edgeShortLabelGroupStats(trades),
    labelVersion: EDGE_SHORT_LABEL_VERSION,
    tierStats: edgeShortTierStats(trades),
    tierVersion: EDGE_SHORT_TIER_VERSION,
    tierObservationOnly: true,
    wave2bStats: edgeShortWave2bStats(trades),
    wave2bVersion: EDGE_SHORT_WAVE_2B_VERSION,
    wave2bObservationOnly: true,
    wave2cStats: wave2cStats.aggregate,
    wave2cTierStats: wave2cStats.byTier,
    wave2cVersion: EDGE_SHORT_WAVE_2C_VERSION,
    wave2cObservationOnly: true,
    bestStats: edgeShortBestStats(trades),
    bestVersion: EDGE_SHORT_BEST_VERSION,
    bestObservationOnly: true,
    bestProfileStats: edgeShortBestProfileStats(trades),
    bestProfileVersion: EDGE_SHORT_BEST_PROFILE_VERSION,
    bestProfileObservationOnly: true,
    bestRiskPhaseStats: edgeShortBestRiskPhaseStats(trades),
    bestRiskPhaseVersion: EDGE_SHORT_BEST_RISK_PHASE_VERSION,
    bestRiskPhaseObservationOnly: true,
    longSpringStats: edgeShortLongSpringStats(trades),
    longSpringVersion: EDGE_SHORT_LONG_SPRING_VERSION,
    longSpringWhitelistVersion: EDGE_SHORT_LONG_SPRING_WHITELIST_VERSION,
    longSpringObservationOnly: true,
    shortUtadStats: edgeShortUtadStats(trades),
    shortUtadVersion: EDGE_SHORT_UTAD_VERSION,
    shortUtadWhitelistVersion: EDGE_SHORT_UTAD_WHITELIST_VERSION,
    shortUtadObservationOnly: true,
    liveStats: edgeShortLiveStats(trades),
    liveVersion: EDGE_SHORT_LIVE_VERSION,
    liveObservationOnly: true,
    sourceLongCorrReboundStats,
    sourceLongCorrReboundVersion: SOURCE_LONG_CORR_REBOUND_VERSION,
    availableDays,
    filter: {
      day: dateRange.mode === 'day' ? dateRange.fromDay : 'all',
      fromDay: dateRange.fromDay,
      toDay: dateRange.toDay,
      mode: dateRange.mode,
      timeZone: LIQUID_PAPER_DAY_TIME_ZONE,
    },
    pagination: {
      page: safePage,
      pageSize: pageSizeNum,
      totalRows,
      totalPages,
      hasPrev: safePage > 1,
      hasNext: safePage < totalPages,
    },
    updatedAt: Date.now(),
  };
}

async function createEdgePaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase().trim();
  const side = String(payload.side ?? '').toUpperCase();
  const marginUsdt = Number(payload.marginUsdt ?? getEdgeShortPaperMarginUsdt());
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 10)));
  const entryPrice = Number(payload.entryPrice);

  if (!symbol) throw new Error('symbol required');
  if (!['LONG', 'SHORT'].includes(side)) throw new Error('side must be LONG or SHORT');
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) throw new Error('entryPrice required');

  const store = await readEdgePaperStore();
  const dup = store.trades.find((t) =>
    t.symbol === symbol && t.side === side && Math.abs(t.entryPrice - entryPrice) / entryPrice < 0.005 &&
    ['PENDING', 'OPEN'].includes(t.status),
  );
  if (dup) {
    const decoratedDup = getDecoratedEdgeShortLabelTrades(store.trades)
      .find((trade) => trade.id === dup.id) ?? dup;
    return { trade: enrichEdgePaperTrade(decoratedDup, edgeMarkCache.get(symbol)) };
  }

  const status = payload.status === 'OPEN' ? 'OPEN' : 'PENDING';
  const createdAt = new Date().toISOString();
  const marketDirectionAtSignal = marketDirectionSnapshotForSignalStorage();
  const maxShortSlRoe = Number(process.env.EDGE_SHORT_MAX_SL_ROE ?? getEdgeShortPaperSlRoe());
  const payloadSlRoe = Math.abs(Number(payload.slRoe));
  const forcedSlRoe = Number.isFinite(payloadSlRoe) && payloadSlRoe > 0
    ? payloadSlRoe
    : getEdgeShortPaperSlRoe();
  const rawTp = payload.tp != null ? Number(payload.tp) : null;
  let rawSl = Number.isFinite(forcedSlRoe) && forcedSlRoe > 0
    ? calcRoeStopLossPrice({ side, entryPrice, leverage, roe: forcedSlRoe })
    : payload.sl != null ? Number(payload.sl) : null;
  let riskNote = '';
  if (Number.isFinite(forcedSlRoe) && forcedSlRoe > 0 && Number.isFinite(rawSl) && rawSl > 0) {
    riskNote = ` | edgePlanSl=${forcedSlRoe}%ROE`;
  }
  if (side === 'SHORT' && Number.isFinite(rawSl) && rawSl > entryPrice && maxShortSlRoe > 0) {
    const slRoe = ((rawSl - entryPrice) / entryPrice) * leverage * 100;
    if (slRoe > maxShortSlRoe) {
      const cappedSl = entryPrice * (1 + (maxShortSlRoe / 100) / leverage);
      rawSl = +cappedSl.toFixed(10);
      riskNote = ` | slClamp=${maxShortSlRoe}%ROE`;
      console.log(`[EdgePaper] clamp SHORT SL ${symbol}: ${slRoe.toFixed(1)}%ROE → ${maxShortSlRoe}%ROE`);
    }
  }
  const baseTrade = attachCandlePatternToPaperTrade({
    id: crypto.randomUUID(),
    symbol,
    side,
    status,
    marginUsdt,
    leverage,
    quantity: (marginUsdt * leverage) / entryPrice,
    entryPrice,
    setupEntry: payload.setupEntry != null ? Number(payload.setupEntry) : entryPrice,
    tp: Number.isFinite(rawTp) ? rawTp : null,
    sl: Number.isFinite(rawSl) ? rawSl : null,
    fillPrice: status === 'OPEN' ? entryPrice : null,
    exitPrice: null,
    pnl: null,
    roe: null,
    outcome: null,
    createdAt,
    openedAt: status === 'OPEN' ? createdAt : null,
    closedAt: null,
    source: String(payload.source ?? 'edge').slice(0, 80),
    note: `${String(payload.note ?? '').slice(0, 460)}${riskNote}`,
    pumpSignalType: payload.pumpSignalType ? String(payload.pumpSignalType).slice(0, 80) : null,
    pumpSignalGrade: payload.pumpSignalGrade ? String(payload.pumpSignalGrade).slice(0, 16) : null,
    pumpSignalMarketOk: payload.pumpSignalMarketOk ?? null,
    pumpSignalFactors: payload.pumpSignalFactors ?? null,
    pumpSignalTimeframe: payload.pumpSignalTimeframe ? String(payload.pumpSignalTimeframe).slice(0, 16) : null,
    pumpCombo: payload.pumpCombo ? String(payload.pumpCombo).slice(0, 240) : null,
    pumpComboSavedAt: new Date().toISOString(),
    btcHealth: payload.btcHealth ?? null,
    btcTrendDir: payload.btcHealth?.btcTrendDir ?? payload.btcTrendDir ?? null,
    btcTrendScore: payload.btcHealth?.btcTrendScore ?? payload.btcTrendScore ?? null,
    btcCorr: payload.btcCorr ?? null,
    marketDirectionAtSignal,
    capGateLabel: payload.capGateLabel ?? null,
    capGateReason: payload.capGateReason ?? null,
    sourceSignalAt: payload.sourceSignalAt ?? payload.signalAt ?? payload.scannedAt ?? createdAt,
    candlePatternAtEntry: payload.candlePatternAtEntry ?? payload.candlePattern ?? null,
    candlePatternTimeframe: payload.candlePatternTimeframe
      ?? payload.pumpSignalTimeframe
      ?? null,
    btcCandlePatternAtEntry: payload.btcCandlePatternAtEntry
      ?? payload.btcCandleAtEntry
      ?? payload.btcCandlePattern
      ?? null,
  });
  const coreTrade = {
    ...baseTrade,
    ...edgeShortLabelSnapshotForEntry(
      store.trades,
      baseTrade,
      Date.parse(createdAt),
    ),
  };
  const tierTrade = {
    ...coreTrade,
    ...edgeShortTierSnapshot(coreTrade),
  };
  const wave2bTrade = {
    ...tierTrade,
    ...edgeShortWave2bSnapshot(tierTrade),
  };
  const wave2cTrade = {
    ...wave2bTrade,
    ...edgeShortWave2cSnapshot(wave2bTrade),
  };
  const priorTrades = getDecoratedEdgeShortLabelTrades(store.trades);
  const bestTrade = {
    ...wave2cTrade,
    ...edgeShortBestSnapshotForEntry(
      priorTrades,
      wave2cTrade,
      Date.parse(createdAt),
    ),
  };
  const liveTrade = {
    ...bestTrade,
    ...edgeShortLiveSnapshotForEntry(
      priorTrades,
      bestTrade,
      Date.parse(createdAt),
    ),
  };
  const profiledTrade = {
    ...liveTrade,
    ...edgeShortBestProfileSnapshotForEntry(liveTrade),
  };
  const longSpringTrade = {
    ...profiledTrade,
    ...edgeShortLongSpringSnapshotForEntry(profiledTrade),
  };
  const shortUtadTrade = {
    ...longSpringTrade,
    ...edgeShortUtadSnapshotForEntry(longSpringTrade),
  };
  const liveCardAutoEligible = payload[LIVE_CARD_AUTO_ELIGIBLE] === true;
  let trade = {
    ...shortUtadTrade,
    ...sourceLongCorrReboundSnapshotForEntry(shortUtadTrade, { sourcePage: 'edge' }),
    liveCardAutoEligible,
  };
  const journaledLiveEntry = trade.status === 'OPEN' && liveCardAutoEligible;
  if (journaledLiveEntry) {
    await appendEdgePaperEntryJournal(
      EDGE_PAPER_ENTRY_JOURNAL_FILE,
      'PREPARED',
      trade,
      { source: 'createEdgePaperTrade' },
    );
  }
  if (trade.status === 'OPEN') {
    let liveDecision;
    try {
      liveDecision = await maybePlaceSourceLiveCardOrder(
        'edge',
        trade,
        store.trades,
        edgeLiveCardKeysOfTrade(trade),
        { autoEligible: liveCardAutoEligible },
      );
    } catch (error) {
      liveDecision = {
        decision: 'ERROR',
        matchedKeys: error?.liveCardMatchedKeys ?? [],
        version: error?.liveCardWhitelistVersion ?? LIQUID_LIVE_CARD_WHITELIST_VERSION,
        attemptedAt: new Date().toISOString(),
        error: String(error?.message ?? error).slice(0, 500),
      };
    }
    trade = {
      ...trade,
      ...liveCardAuditPatch(liveDecision),
      liveCardError: liveDecision.error ?? null,
    };
  }
  await upsertEdgePaperTrade(trade);
  if (journaledLiveEntry) {
    await appendEdgePaperEntryJournal(
      EDGE_PAPER_ENTRY_JOURNAL_FILE,
      'COMMITTED',
      trade,
      { source: 'createEdgePaperTrade' },
    );
  }
  if (trade.status === 'OPEN') {
    publishRecommendedSourceOpen('edge', trade, {
      price: trade.entryPrice,
      at: Date.parse(trade.openedAt ?? trade.createdAt),
      source: 'edge-source-open-event',
    });
  }
  await syncEdgePaperTicker();
  console.log(`[EdgePaper] ${status} ${side} ${symbol} entry=${entryPrice} src=${trade.source}`);
  return { trade: enrichEdgePaperTrade(trade, entryPrice) };
}

async function closeEdgePaperTrade(payload) {
  const result = await mutateEdgePaperStore((store) => {
    const idx = store.trades.findIndex((t) => t.id === payload.id);
    if (idx < 0) throw new Error('Edge paper trade not found');
    const trade = store.trades[idx];
    if (trade.status === 'CLOSED') return { changed: false, trade, alreadyClosed: true };
    const exitPrice = payload.exitPrice ? Number(payload.exitPrice) : (edgeMarkCache.get(trade.symbol) ?? trade.entryPrice);
    const sideMult = trade.side === 'LONG' ? 1 : -1;
    const pnl = (exitPrice - trade.entryPrice) * trade.quantity * sideMult;
    const roe = trade.marginUsdt > 0 ? (pnl / trade.marginUsdt) * 100 : 0;
    const outcome = payload.outcome ?? 'MANUAL';
    const closedTrade = { ...trade, status: 'CLOSED', exitPrice, pnl, roe, outcome, closedAt: new Date().toISOString() };
    store.trades[idx] = closedTrade;
    return { changed: true, trade: closedTrade };
  });
  const outcome = result.trade.outcome ?? payload.outcome ?? 'MANUAL';
  if (!result.alreadyClosed) {
    queueLiveCardBotClose('edge', result.trade, { outcome, reason: outcome });
  }
  await syncEdgePaperTicker();
  return { trade: enrichEdgePaperTrade(result.trade, result.trade.exitPrice) };
}

async function deleteEdgePaperTrade(payload) {
  const result = await mutateEdgePaperStore((store) => {
    const deleted = store.trades.find((trade) => trade.id === payload.id) ?? null;
    store.trades = store.trades.filter((trade) => trade.id !== payload.id);
    return { changed: Boolean(deleted), deleted };
  });
  if (result.deleted?.liveCardAutoEligible === true) {
    await appendEdgePaperEntryJournal(
      EDGE_PAPER_ENTRY_JOURNAL_FILE,
      'DELETED',
      payload.id,
      { source: 'deleteEdgePaperTrade' },
    );
  }
  await syncEdgePaperTicker();
  return { ok: true };
}

async function fillEdgePendingTrade(trade, markPrice) {
  if (edgePaperFillLocks.has(trade.id)) return;
  edgePaperFillLocks.add(trade.id);
  try {
    const store = await readEdgePaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'PENDING');
    if (idx < 0) return;
    const entry = Number(store.trades[idx].entryPrice);
    const fillPrice = Number(markPrice);
    const touched = store.trades[idx].side === 'LONG' ? fillPrice <= entry : fillPrice >= entry;
    if (!touched) return;
    const row = store.trades[idx];
    const marginUsdt = Number(row.marginUsdt);
    const leverage = Math.max(1, Number(row.leverage) || 1);
    const nextQuantity = Number.isFinite(marginUsdt) && marginUsdt > 0 && Number.isFinite(fillPrice) && fillPrice > 0
      ? (marginUsdt * leverage) / fillPrice
      : row.quantity;
    let filledTrade = {
      ...row,
      status: 'OPEN',
      setupEntry: Number(row.setupEntry ?? entry),
      entryPrice: fillPrice,
      fillPrice,
      quantity: nextQuantity,
      openedAt: new Date().toISOString(),
      note: [
        String(row.note ?? ''),
        `socketFill=${fillPrice}; setupEntry=${Number(row.setupEntry ?? entry)}`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    const journaledLiveEntry = filledTrade.liveCardAutoEligible === true;
    if (journaledLiveEntry) {
      await appendEdgePaperEntryJournal(
        EDGE_PAPER_ENTRY_JOURNAL_FILE,
        'PREPARED',
        filledTrade,
        { source: 'fillEdgePendingTrade' },
      );
    }
    if (filledTrade.liveCardAutoEligible === true) {
      let liveDecision;
      try {
        liveDecision = await maybePlaceSourceLiveCardOrder(
          'edge',
          filledTrade,
          store.trades,
          edgeLiveCardKeysOfTrade(filledTrade),
          { autoEligible: true },
        );
      } catch (error) {
        liveDecision = {
          decision: 'ERROR',
          matchedKeys: error?.liveCardMatchedKeys ?? [],
          version: error?.liveCardWhitelistVersion ?? LIQUID_LIVE_CARD_WHITELIST_VERSION,
          attemptedAt: new Date().toISOString(),
          error: String(error?.message ?? error).slice(0, 500),
        };
      }
      filledTrade = {
        ...filledTrade,
        ...liveCardAuditPatch(liveDecision),
        liveCardError: liveDecision.error ?? null,
      };
    }
    await upsertEdgePaperTrade(filledTrade);
    if (journaledLiveEntry) {
      await appendEdgePaperEntryJournal(
        EDGE_PAPER_ENTRY_JOURNAL_FILE,
        'COMMITTED',
        filledTrade,
        { source: 'fillEdgePendingTrade' },
      );
    }
    console.log(`[EdgePaper] FILLED ${filledTrade.side} ${filledTrade.symbol} setupEntry=${entry} fill=${fillPrice}`);
    publishRecommendedSourceOpen('edge', filledTrade, {
      price: fillPrice,
      at: Date.now(),
      source: 'edge-fill-socket-event',
    });
  } finally {
    edgePaperFillLocks.delete(trade.id);
  }
}

async function processEdgePaperFills(symbol, markPrice) {
  const store = await readEdgePaperStore();
  const pending = store.trades.filter((t) => t.status === 'PENDING' && t.symbol === symbol);
  for (const t of pending) await fillEdgePendingTrade(t, markPrice);
  const open = store.trades.filter((t) => t.status === 'OPEN' && t.symbol === symbol);
  for (const t of open) {
    await checkEdgePaperTpSl(t, markPrice);
    await checkEdgePaperTimeout(t, markPrice);
  }
}

async function processEdgePaperCachedMarks() {
  if (edgePaperBatchRunning) return;
  edgePaperBatchRunning = true;
  try {
    const store = await readEdgePaperStore();
    const active = store.trades.filter((t) => ['PENDING', 'OPEN'].includes(t.status));
    for (const trade of active) {
      const markPrice = Number(edgeMarkCache.get(trade.symbol) ?? sharedLastTicker.getPrice?.(trade.symbol));
      if (!Number.isFinite(markPrice) || markPrice <= 0) continue;
      if (trade.status === 'PENDING') await fillEdgePendingTrade(trade, markPrice);
      else {
        await checkEdgePaperTpSl(trade, markPrice);
        await checkEdgePaperTimeout(trade, markPrice);
      }
    }
  } finally {
    edgePaperBatchRunning = false;
  }
}

const edgePaperTimeoutLocks = new Set();
async function checkEdgePaperTimeout(trade, markPrice) {
  if (!trade.openedAt) return;
  const timeoutH = Number(process.env.EDGE_PAPER_TIMEOUT_H ?? runtimeSettings.pumpPaperTimeoutH ?? 3);
  const timeoutMs = timeoutH * 3600_000;
  const openedMs = Date.parse(trade.openedAt);
  if (Date.now() - openedMs < timeoutMs) return;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = (markPrice - Number(trade.entryPrice)) * Number(trade.quantity) * sideMult;
  const roe = Number(trade.marginUsdt) > 0 ? (pnl / Number(trade.marginUsdt)) * 100 : 0;
  if (roe <= 1) return;

  if (edgePaperTimeoutLocks.has(trade.id)) return;
  edgePaperTimeoutLocks.add(trade.id);
  try {
    await closeEdgePaperTrade({ id: trade.id, exitPrice: markPrice, outcome: 'TIMEOUT' });
    console.log(`[EdgePaper] TIMEOUT ${trade.side} ${trade.symbol} roe=${roe.toFixed(1)}% after ${timeoutH}h`);
  } finally {
    edgePaperTimeoutLocks.delete(trade.id);
  }
}

const edgePaperTpSlLocks = new Set();
async function checkEdgePaperTpSl(trade, markPrice) {
  if (!trade.tp && !trade.sl) return;
  if (edgePaperTpSlLocks.has(trade.id)) return;
  const isLong = trade.side === 'LONG';
  const tpHit = trade.tp != null && (isLong ? markPrice >= trade.tp : markPrice <= trade.tp);
  const slHit = trade.sl != null && (isLong ? markPrice <= trade.sl : markPrice >= trade.sl);
  if (!tpHit && !slHit) return;
  edgePaperTpSlLocks.add(trade.id);
  try {
    const outcome = tpHit ? 'TP' : 'SL';
    const exitPrice = tpHit ? trade.tp : trade.sl;
    await closeEdgePaperTrade({ id: trade.id, exitPrice, outcome });
    console.log(`[EdgePaper] ${outcome} hit ${trade.side} ${trade.symbol} exit=${exitPrice}`);
  } finally {
    edgePaperTpSlLocks.delete(trade.id);
  }
}

async function syncEdgePaperTicker() {
  if (!edgePaperTicker) return;
  const store = await readEdgePaperStore();
  const symbols = [...new Set(store.trades.filter((t) => ['PENDING', 'OPEN'].includes(t.status)).map((t) => t.symbol))];
  sharedLastTicker.setSymbols('edgePaper', symbols);
}

function startEdgePaperTicker() {
  if (edgePaperTicker) return;
  edgePaperTicker = true; // guard flag — actual WS is sharedLastTicke
  sharedLastTicker.register('edgePaper', ({ symbol, markPrice }) => {
    edgeMarkCache.set(symbol, markPrice);
  });
  console.log('[EdgePaper] Last-price ticker started (shared, 1s batched processing).');
  syncEdgePaperTicker().catch(() => {});
  setInterval(() => syncEdgePaperTicker().catch(() => {}), 30_000);
  setInterval(() => processEdgePaperCachedMarks().catch((err) => {
    console.warn('[EdgePaper] Batch mark processing failed:', err.message);
  }), 1_000);
}

// ── SR Paper Trades (Spike Reversal) ─────────────────────────────────────────

async function readSrPaperStore() {
  try {
    const raw = await readFile(SR_PAPER_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed?.trades)) throw new Error('invalid structure');
    return parsed;
  } catch (e) {
    if (e.code !== 'ENOENT') console.warn('[SrPaper] Store read error, starting fresh:', e.message);
    return { trades: [] };
  }
}

let _srPaperWriteLock = Promise.resolve();
async function writeSrPaperStore(store) {
  _srPaperWriteLock = _srPaperWriteLock.then(() => atomicWriteJson(SR_PAPER_FILE, store));
  return _srPaperWriteLock;
}

function enrichSrPaperTrade(t, markPrice) {
  const mark = Number(markPrice ?? t.markPrice ?? t.exitPrice ?? t.entryPrice);
  const entry = Number(t.entryPrice);
  const qty = Number(t.quantity);
  const margin = Number(t.marginUsdt);
  const sideMult = t.side === 'LONG' ? 1 : -1;
  const isActive = t.status === 'OPEN';
  const pnl = isActive ? (mark - entry) * qty * sideMult : (t.pnl ?? null);
  const roe = isActive && margin > 0 ? (pnl / margin) * 100 : (t.roe ?? null);
  return { ...t, markPrice: mark, pnl, roe };
}

async function getSrPaperTrades() {
  const store = await readSrPaperStore();
  const trades = store.trades.map((t) => enrichSrPaperTrade(t, srMarkCache.get(t.symbol)));
  const open   = trades.filter((t) => t.status !== 'CLOSED');
  const closed = trades.filter((t) => t.status === 'CLOSED');
  const wins   = closed.filter((t) => (t.pnl ?? 0) > 0).length;
  const tpHits = closed.filter((t) => t.outcome === 'TP').length;
  const slHits = closed.filter((t) => t.outcome === 'SL').length;
  const avgRoe = closed.length > 0
    ? closed.reduce((s, t) => s + (t.roe ?? 0), 0) / closed.length : null;
  const summary = {
    total: trades.length, open: open.length, closed: closed.length,
    wins, losses: closed.length - wins, tpHits, slHits,
    avgRoe: avgRoe != null ? +avgRoe.toFixed(1) : null,
  };
  return { trades, summary };
}

async function createSrPaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase().trim();
  const side = String(payload.side ?? 'SHORT').toUpperCase();
  const marginUsdt = Number(payload.marginUsdt ?? 1);
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 10)));
  const entryPrice = Number(payload.entryPrice);

  if (!symbol) throw new Error('symbol required');
  if (!['LONG', 'SHORT'].includes(side)) throw new Error('side must be LONG or SHORT');
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) throw new Error('entryPrice required');

  const store = await readSrPaperStore();
  const dup = store.trades.find((t) =>
    t.symbol === symbol && t.side === side &&
    Math.abs(t.entryPrice - entryPrice) / entryPrice < 0.005 &&
    ['PENDING', 'OPEN'].includes(t.status),
  );
  if (dup) return { trade: enrichSrPaperTrade(dup, srMarkCache.get(symbol)) };

  const status = payload.status === 'OPEN' ? 'OPEN' : 'PENDING';
  const trade = {
    id: crypto.randomUUID(),
    symbol, side, status,
    marginUsdt, leverage,
    quantity: (marginUsdt * leverage) / entryPrice,
    entryPrice,
    tp: payload.tp != null ? Number(payload.tp) : null,
    sl: payload.sl != null ? Number(payload.sl) : null,
    fillPrice: status === 'OPEN' ? entryPrice : null,
    exitPrice: null,
    pnl: null,
    roe: null,
    outcome: null,
    createdAt: new Date().toISOString(),
    openedAt: status === 'OPEN' ? new Date().toISOString() : null,
    closedAt: null,
    source: String(payload.source ?? 'manual').slice(0, 80),
    note: String(payload.note ?? '').slice(0, 500),
  };
  store.trades.unshift(trade);
  await writeSrPaperStore(store);
  console.log(`[SrPaper] ${status === 'PENDING' ? '⏳' : '✅'} ${side} ${symbol} entry=${entryPrice} src=${trade.source}`);
  return { trade: enrichSrPaperTrade(trade, entryPrice) };
}

async function closeSrPaperTrade(payload) {
  const store = await readSrPaperStore();
  const idx = store.trades.findIndex((t) => t.id === payload.id);
  if (idx < 0) throw new Error('SR paper trade not found');
  const trade = store.trades[idx];
  if (trade.status === 'CLOSED') return { trade: enrichSrPaperTrade(trade, trade.exitPrice) };
  const exitPrice = payload.exitPrice ? Number(payload.exitPrice) : (srMarkCache.get(trade.symbol) ?? trade.entryPrice);
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = (exitPrice - trade.entryPrice) * trade.quantity * sideMult;
  const roe = trade.marginUsdt > 0 ? (pnl / trade.marginUsdt) * 100 : 0;
  const outcome = payload.outcome ?? 'MANUAL';
  store.trades[idx] = { ...trade, status: 'CLOSED', exitPrice, pnl, roe, outcome, closedAt: new Date().toISOString() };
  await writeSrPaperStore(store);
  return { trade: enrichSrPaperTrade(store.trades[idx], exitPrice) };
}

async function deleteSrPaperTrade(payload) {
  const store = await readSrPaperStore();
  store.trades = store.trades.filter((t) => t.id !== payload.id);
  await writeSrPaperStore(store);
  return { ok: true };
}

async function fillSrPendingTrade(trade, markPrice) {
  if (srPaperFillLocks.has(trade.id)) return;
  srPaperFillLocks.add(trade.id);
  try {
    const store = await readSrPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'PENDING');
    if (idx < 0) return;
    const entry = Number(store.trades[idx].entryPrice);
    const touched = store.trades[idx].side === 'LONG' ? markPrice <= entry : markPrice >= entry;
    if (!touched) return;
    store.trades[idx] = { ...store.trades[idx], status: 'OPEN', fillPrice: entry, openedAt: new Date().toISOString() };
    await writeSrPaperStore(store);
    console.log(`[SrPaper] ✅ FILLED ${store.trades[idx].side} ${store.trades[idx].symbol} entry=${entry} mark=${markPrice}`);
  } finally {
    srPaperFillLocks.delete(trade.id);
  }
}

async function processSrPaperFills(symbol, markPrice) {
  const store = await readSrPaperStore();
  const pending = store.trades.filter((t) => t.status === 'PENDING' && t.symbol === symbol);
  for (const t of pending) await fillSrPendingTrade(t, markPrice);
  const open = store.trades.filter((t) => t.status === 'OPEN' && t.symbol === symbol);
  for (const t of open) await checkSrPaperTpSl(t, markPrice);
}

const srPaperTpSlLocks = new Set();
async function checkSrPaperTpSl(trade, markPrice) {
  if (!trade.tp && !trade.sl) return;
  if (srPaperTpSlLocks.has(trade.id)) return;
  const isLong = trade.side === 'LONG';
  const tpHit = trade.tp != null && (isLong ? markPrice >= trade.tp : markPrice <= trade.tp);
  const slHit = trade.sl != null && (isLong ? markPrice <= trade.sl : markPrice >= trade.sl);
  if (!tpHit && !slHit) return;
  srPaperTpSlLocks.add(trade.id);
  try {
    const outcome = tpHit ? 'TP' : 'SL';
    const exitPrice = tpHit ? trade.tp : trade.sl;
    await closeSrPaperTrade({ id: trade.id, exitPrice, outcome });
    console.log(`[SrPaper] 🎯 ${outcome} hit ${trade.side} ${trade.symbol} exit=${exitPrice}`);
  } finally {
    srPaperTpSlLocks.delete(trade.id);
  }
}

async function syncSrPaperTicker() {
  if (!srPaperTicker) return;
  const store = await readSrPaperStore();
  const symbols = [...new Set(store.trades.filter((t) => ['PENDING', 'OPEN'].includes(t.status)).map((t) => t.symbol))];
  sharedLastTicker.setSymbols('srPaper', symbols);
}

function startSrPaperTicker() {
  if (srPaperTicker) return;
  srPaperTicker = true; // guard flag — actual WS is sharedLastTicke
  sharedLastTicker.register('srPaper', ({ symbol, markPrice }) => {
    srMarkCache.set(symbol, markPrice);
    processSrPaperFills(symbol, markPrice).catch(() => {});
  });
  console.log('[SrPaper] Last-price ticker started (shared).');
  syncSrPaperTicker().catch(() => {});
  setInterval(() => syncSrPaperTicker().catch(() => {}), 30_000);
}

// ── PPKS Paper Trades (Post Pump Kill Short / Post Dump Kill Long) ─────────────

async function readPpksPaperStore() {
  try {
    const raw = await readFile(PPKS_PAPER_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed?.trades)) throw new Error('invalid structure');
    return parsed;
  } catch (e) {
    if (e.code !== 'ENOENT') console.warn('[PpksPaper] Store read error, starting fresh:', e.message);
    return { trades: [] };
  }
}

let _ppksPaperWriteLock = Promise.resolve();
async function writePpksPaperStore(store) {
  _ppksPaperWriteLock = _ppksPaperWriteLock.then(() => atomicWriteJson(PPKS_PAPER_FILE, store));
  return _ppksPaperWriteLock;
}

function enrichPpksPaperTrade(t, markPrice) {
  const liveMark = Number(markPrice);
  const hasLiveMark = Number.isFinite(liveMark) && liveMark > 0;
  const isActive = t.status === 'OPEN';
  const mark = isActive
    ? (hasLiveMark ? liveMark : null)
    : Number(t.exitPrice ?? t.markPrice ?? markPrice ?? t.entryPrice);
  const entry = Number(t.entryPrice);
  const qty = Number(t.quantity);
  const margin = Number(t.marginUsdt);
  const sideMult = t.side === 'LONG' ? 1 : -1;
  const pnl = isActive
    ? (Number.isFinite(mark) && mark > 0 ? (mark - entry) * qty * sideMult : null)
    : (t.pnl ?? null);
  const roe = isActive && margin > 0
    ? (pnl == null ? null : (pnl / margin) * 100)
    : (t.roe ?? null);
  return {
    ...t,
    markPrice: mark,
    markUpdatedAt: ppksMarkCacheAt.get(String(t.symbol ?? '').toUpperCase()) ?? null,
    pnl,
    roe,
  };
}

function getFreshPpksPaperMark(symbol) {
  const sym = String(symbol ?? '').toUpperCase();
  const freshMs = Number(process.env.PPKS_PAPER_MARK_STALE_MS ?? 60_000);
  const now = Date.now();

  const socketMark = Number(ppksMarkCache.get(sym));
  const socketAt = Number(ppksMarkCacheAt.get(sym) ?? 0);
  if (Number.isFinite(socketMark) && socketMark > 0 && socketAt && now - socketAt <= freshMs) {
    return socketMark;
  }

  const sharedInfo = sharedLastTicker.getPriceInfo?.(sym);
  const sharedMark = Number(sharedInfo?.markPrice);
  const sharedAt = Number(sharedInfo?.at ?? 0);
  if (Number.isFinite(sharedMark) && sharedMark > 0 && sharedAt && now - sharedAt <= freshMs) {
    return sharedMark;
  }

  const snapshotMark = getSnapshotMarkPrice(sym);
  const snapshotAt = Number(_snapshotCacheAt ?? 0);
  if (Number.isFinite(snapshotMark) && snapshotMark > 0 && snapshotAt && now - snapshotAt <= freshMs) {
    return snapshotMark;
  }
  return null;
}

function summarizePpksMarginStats(storedTrades = []) {
  const groups = {
    test10: { label: 'TEST $10', total: 0, open: 0, closed: 0, wins: 0, losses: 0, realizedPnl: 0, unrealizedPnl: 0, roeSum: 0 },
    test1: { label: 'TEST $1', total: 0, open: 0, closed: 0, wins: 0, losses: 0, realizedPnl: 0, unrealizedPnl: 0, roeSum: 0 },
    other: { label: 'Other', total: 0, open: 0, closed: 0, wins: 0, losses: 0, realizedPnl: 0, unrealizedPnl: 0, roeSum: 0 },
  };
  const pick = (margin) => {
    const m = Number(margin);
    if (Number.isFinite(m) && m <= 1.01) return groups.test1;
    if (Number.isFinite(m) && m >= 9.5 && m <= 10.5) return groups.test10;
    return groups.other;
  };
  for (const raw of storedTrades) {
    const trade = enrichPpksPaperTrade(raw, getFreshPpksPaperMark(raw.symbol));
    const row = pick(trade.marginUsdt);
    row.total += 1;
    const pnl = Number(trade.pnl ?? 0);
    if (trade.status === 'CLOSED') {
      row.closed += 1;
      row.realizedPnl += pnl;
      if (pnl > 0) row.wins += 1;
      else row.losses += 1;
      row.roeSum += Number(trade.roe ?? 0);
    } else {
      row.open += 1;
      row.unrealizedPnl += pnl;
    }
  }
  return Object.fromEntries(Object.entries(groups).map(([key, row]) => [key, {
    ...row,
    wr: row.closed > 0 ? +(row.wins / row.closed * 100).toFixed(1) : null,
    avgRoe: row.closed > 0 ? +(row.roeSum / row.closed).toFixed(1) : null,
    realizedPnl: +row.realizedPnl.toFixed(4),
    unrealizedPnl: +row.unrealizedPnl.toFixed(4),
    netPnl: +(row.realizedPnl + row.unrealizedPnl).toFixed(4),
  }]));
}

function calcRoeStopLossPrice({ side, entryPrice, leverage, roe }) {
  const entry = Number(entryPrice);
  const lev = Math.max(1, Number(leverage) || 1);
  const stopRoe = Math.abs(Number(roe));
  if (!Number.isFinite(entry) || entry <= 0 || !Number.isFinite(stopRoe) || stopRoe <= 0) return null;
  const move = stopRoe / 100 / lev;
  return String(side).toUpperCase() === 'LONG'
    ? entry * (1 - move)
    : entry * (1 + move);
}

async function getPpksPaperTrades({ day = null } = {}) {
  const store = await readPpksPaperStore();
  const allTrades = store.trades.map((t) => enrichPpksPaperTrade(t, getFreshPpksPaperMark(t.symbol)));
  const availableDays = [...new Set(allTrades
    .map((t) => String(t.createdAt ?? t.openedAt ?? t.closedAt ?? '').slice(0, 10))
    .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d)))]
    .sort((a, b) => b.localeCompare(a));
  const selectedDay = day && /^\d{4}-\d{2}-\d{2}$/.test(String(day)) ? String(day) : null;
  const trades = selectedDay
    ? allTrades.filter((t) => String(t.createdAt ?? t.openedAt ?? t.closedAt ?? '').slice(0, 10) === selectedDay)
    : allTrades;
  const open   = trades.filter((t) => t.status !== 'CLOSED');
  const closed = trades.filter((t) => t.status === 'CLOSED');
  const wins   = closed.filter((t) => (t.pnl ?? 0) > 0).length;
  const tpHits = closed.filter((t) => t.outcome === 'TP').length;
  const slHits = closed.filter((t) => t.outcome === 'SL').length;
  const avgRoe = closed.length > 0
    ? closed.reduce((s, t) => s + (t.roe ?? 0), 0) / closed.length : null;
  const realizedPnl = closed.reduce((s, t) => s + Number(t.pnl ?? 0), 0);
  const unrealizedPnl = open.reduce((s, t) => s + Number(t.pnl ?? 0), 0);
  const summary = {
    total: trades.length, open: open.length, closed: closed.length,
    wins, losses: closed.length - wins, tpHits, slHits,
    realizedPnl: +realizedPnl.toFixed(3),
    unrealizedPnl: +unrealizedPnl.toFixed(3),
    netPnl: +(realizedPnl + unrealizedPnl).toFixed(3),
    avgRoe: avgRoe != null ? +avgRoe.toFixed(1) : null,
    byMargin: summarizePpksMarginStats(trades),
    day: selectedDay,
  };
  return {
    trades,
    summary,
    comboStats: pumpComboStatsOf(trades.map((t) => ({
      ...t,
      pumpCombo: ppksTradeFallbackCombo(t),
    })), { context: 'ppks' }),
    availableDays,
  };
}

async function createPpksPaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase().trim();
  const side = String(payload.side ?? 'SHORT').toUpperCase();
  const signalTimeframe = String(payload.ppksSignalTimeframe ?? payload.pumpSignalTimeframe ?? '15m');
  const rawBtcHealth = payload.btcHealth ?? null;
  const btcHealthSnapshot = rawBtcHealth ? buildBtcHealthSnapshot(rawBtcHealth) : buildBtcHealthSnapshot(btcHealthCache.data ?? {});
  const payloadBtcCorr = Number(payload.btcCorr);
  const btcCorr = Number.isFinite(payloadBtcCorr)
    ? payloadBtcCorr
    : (symbol ? getCoinBtcCorr(symbol, signalTimeframe, 30) : null);
  const ppksGateLabel = payload.ppksGateLabel ?? payload.capGateLabel ?? null;
  const ppksCombo = payload.ppksCombo
    ? String(payload.ppksCombo)
    : ppksComboOfSignal({
      type: payload.ppksSignalType ?? payload.pumpSignalType ?? 'PPKS',
      ppksGateLabel,
      btcHealth: btcHealthSnapshot,
      btcCorr,
    }, {
      side,
      interval: signalTimeframe,
      btcHealth: btcHealthSnapshot,
      btcCorr,
      gateLabel: ppksGateLabel,
    });
  const ppksPlan = pumpComboTradePlanOfKey(ppksCombo, {}, { context: 'ppks' });
  const marginUsdt = Number(payload.marginUsdt ?? ppksPlan.marginUsdt ?? 10);
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 10)));
  const entryPrice = Number(payload.entryPrice);

  if (!symbol) throw new Error('symbol required');
  if (!['LONG', 'SHORT'].includes(side)) throw new Error('side must be LONG or SHORT');
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) throw new Error('entryPrice required');

  const store = await readPpksPaperStore();
  const dup = store.trades.find((t) =>
    t.symbol === symbol && t.side === side &&
    Math.abs(t.entryPrice - entryPrice) / entryPrice < 0.005 &&
    ['PENDING', 'OPEN'].includes(t.status),
  );
  if (dup) return { trade: enrichPpksPaperTrade(dup, getFreshPpksPaperMark(symbol)) };

  const status = payload.status === 'OPEN' ? 'OPEN' : 'PENDING';
  const slRoe = Number(process.env.PPKS_PAPER_SL_ROE ?? 20);
  const forcedSl = process.env.PPKS_PAPER_FORCE_SL_ROE !== 'false'
    ? calcRoeStopLossPrice({ side, entryPrice, leverage, roe: slRoe })
    : null;
  const effectiveSl = forcedSl ?? (payload.sl != null ? Number(payload.sl) : calcRoeStopLossPrice({ side, entryPrice, leverage, roe: slRoe }));
  const trade = {
    id: crypto.randomUUID(),
    symbol, side, status,
    marginUsdt, leverage,
    quantity: (marginUsdt * leverage) / entryPrice,
    entryPrice,
    setupEntry: payload.setupEntry != null ? Number(payload.setupEntry) : entryPrice,
    tp: payload.tp != null ? Number(payload.tp) : null,
    sl: effectiveSl,
    fillPrice: status === 'OPEN' ? entryPrice : null,
    exitPrice: null,
    pnl: null,
    roe: null,
    outcome: null,
    createdAt: new Date().toISOString(),
    openedAt: status === 'OPEN' ? new Date().toISOString() : null,
    closedAt: null,
    source: String(payload.source ?? 'manual').slice(0, 80),
    ppksSignalType: payload.ppksSignalType ?? payload.pumpSignalType ?? null,
    ppksSignalGrade: payload.ppksSignalGrade ?? payload.pumpSignalGrade ?? null,
    ppksSignalTimeframe: signalTimeframe,
    ppksSignalFactors: payload.ppksSignalFactors ?? payload.pumpSignalFactors ?? null,
    ppksGateLabel,
    ppksCombo,
    pumpCombo: ppksCombo,
    btcHealth: btcHealthSnapshot,
    btcCorr: Number.isFinite(btcCorr) ? btcCorr : null,
    note: [
      String(payload.note ?? ''),
      Number.isFinite(effectiveSl) ? `ppksDefaultSl=${slRoe}%ROE@${effectiveSl}` : '',
      `ppksMargin=$${marginUsdt}`,
      ppksPlan?.label ? `ppksPlan=${ppksPlan.label}` : '',
    ].filter(Boolean).join(' | ').slice(0, 500),
  };
  store.trades.unshift(trade);
  await writePpksPaperStore(store);
  syncPpksPaperTicker().catch(() => {});
  console.log(`[PpksPaper] ${status === 'PENDING' ? '⏳' : '✅'} ${side} ${symbol} entry=${entryPrice} src=${trade.source}`);
  return { trade: enrichPpksPaperTrade(trade, getFreshPpksPaperMark(symbol)) };
}

async function closePpksPaperTrade(payload) {
  const store = await readPpksPaperStore();
  const idx = store.trades.findIndex((t) => t.id === payload.id);
  if (idx < 0) throw new Error('PPKS paper trade not found');
  const trade = store.trades[idx];
  if (trade.status === 'CLOSED') return { trade: enrichPpksPaperTrade(trade, trade.exitPrice) };
  const exitPrice = payload.exitPrice ? Number(payload.exitPrice) : (getFreshPpksPaperMark(trade.symbol) ?? trade.entryPrice);
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = (exitPrice - trade.entryPrice) * trade.quantity * sideMult;
  const roe = trade.marginUsdt > 0 ? (pnl / trade.marginUsdt) * 100 : 0;
  const outcome = payload.outcome ?? 'MANUAL';
  store.trades[idx] = { ...trade, status: 'CLOSED', exitPrice, pnl, roe, outcome, closedAt: new Date().toISOString() };
  await writePpksPaperStore(store);
  syncPpksPaperTicker().catch(() => {});
  return { trade: enrichPpksPaperTrade(store.trades[idx], exitPrice) };
}

async function deletePpksPaperTrade(payload) {
  const store = await readPpksPaperStore();
  store.trades = store.trades.filter((t) => t.id !== payload.id);
  await writePpksPaperStore(store);
  syncPpksPaperTicker().catch(() => {});
  return { ok: true };
}

async function fillPpksPendingTrade(trade, markPrice) {
  if (ppksPaperFillLocks.has(trade.id)) return;
  ppksPaperFillLocks.add(trade.id);
  try {
    const store = await readPpksPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'PENDING');
    if (idx < 0) return;
    const entry = Number(store.trades[idx].entryPrice);
    const fillPrice = Number(markPrice);
    const touched = store.trades[idx].side === 'LONG' ? fillPrice <= entry : fillPrice >= entry;
    if (!touched) return;
    const row = store.trades[idx];
    const marginUsdt = Number(row.marginUsdt);
    const leverage = Math.max(1, Number(row.leverage) || 1);
    const nextQuantity = Number.isFinite(marginUsdt) && marginUsdt > 0 && Number.isFinite(fillPrice) && fillPrice > 0
      ? (marginUsdt * leverage) / fillPrice
      : row.quantity;
    store.trades[idx] = {
      ...row,
      status: 'OPEN',
      setupEntry: Number(row.setupEntry ?? entry),
      entryPrice: fillPrice,
      fillPrice,
      quantity: nextQuantity,
      openedAt: new Date().toISOString(),
      note: [
        String(row.note ?? ''),
        `socketFill=${fillPrice}; setupEntry=${Number(row.setupEntry ?? entry)}`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writePpksPaperStore(store);
    syncPpksPaperTicker().catch(() => {});
    console.log(`[PpksPaper] ✅ FILLED ${store.trades[idx].side} ${store.trades[idx].symbol} setupEntry=${entry} fill=${fillPrice}`);
  } finally {
    ppksPaperFillLocks.delete(trade.id);
  }
}

async function processPpksPaperFills(symbol, markPrice) {
  const store = await readPpksPaperStore();
  const pending = store.trades.filter((t) => t.status === 'PENDING' && t.symbol === symbol);
  for (const t of pending) await fillPpksPendingTrade(t, markPrice);
  const open = store.trades.filter((t) => t.status === 'OPEN' && t.symbol === symbol);
  for (const t of open) {
    await checkPpksPaperSlTrail(t, markPrice);
    await checkPpksPaperTpSl(t, markPrice);
  }
}

const ppksPaperSlTrailLocks = new Set();
async function checkPpksPaperSlTrail(trade, markPrice) {
  if (process.env.PPKS_PAPER_SL_TRAIL_ENABLED === 'false') return;
  if (trade.status !== 'OPEN') return;
  if (ppksPaperSlTrailLocks.has(trade.id)) return;

  const entry = Number(trade.entryPrice);
  const mark = Number(markPrice);
  const qty = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const leverage = Math.max(1, Number(trade.leverage) || 1);
  if (![entry, mark, qty, margin].every(Number.isFinite) || entry <= 0 || mark <= 0 || qty <= 0 || margin <= 0) return;

  const isLong = trade.side === 'LONG';
  const sideMult = isLong ? 1 : -1;
  const pnl = (mark - entry) * qty * sideMult;
  const roe = pnl / margin * 100;
  const prevPeak = Number(trade.peakRoe ?? 0);
  const peakRoe = Math.max(prevPeak, Number.isFinite(roe) ? roe : 0);
  const trailStartRoe = Number(process.env.PPKS_PAPER_TRAIL_START_ROE ?? process.env.EMA_SQUEEZE_PAPER_TRAIL_START_ROE ?? 10);
  if (!Number.isFinite(roe) || roe < trailStartRoe) return;

  const targetLockRoe = getTargetLockRoe(roe);
  if (targetLockRoe == null) return;
  const lockMove = targetLockRoe / 100 / leverage;
  const newSl = isLong ? entry * (1 + lockMove) : entry * (1 - lockMove);
  const curSl = Number(trade.sl ?? 0);
  const improves = !Number.isFinite(curSl) || curSl <= 0 || (isLong ? newSl > curSl : newSl < curSl);
  const validSide = isLong ? newSl < mark : newSl > mark;
  if (!Number.isFinite(newSl) || newSl <= 0 || !improves || !validSide) return;

  ppksPaperSlTrailLocks.add(trade.id);
  try {
    const store = await readPpksPaperStore();
    const idx = store.trades.findIndex((row) => row.id === trade.id && row.status === 'OPEN');
    if (idx < 0) return;
    const row = store.trades[idx];
    const rowCurSl = Number(row.sl ?? 0);
    const rowImproves = !Number.isFinite(rowCurSl) || rowCurSl <= 0 || (isLong ? newSl > rowCurSl : newSl < rowCurSl);
    if (!rowImproves) return;
    store.trades[idx] = {
      ...row,
      sl: newSl,
      peakRoe,
      slTrailLockRoe: targetLockRoe,
      dynamicRiskUpdatedAt: new Date().toISOString(),
      note: [
        String(row.note ?? ''),
        `ppksSlTrail=${targetLockRoe}%@${newSl}; roe=${roe.toFixed(1)}%; peak=${peakRoe.toFixed(1)}%`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writePpksPaperStore(store);
    console.log(`[PpksPaper] SL_TRAIL ${row.side} ${row.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% lock=${targetLockRoe}% sl=${newSl}`);
  } finally {
    ppksPaperSlTrailLocks.delete(trade.id);
  }
}

const ppksPaperTpSlLocks = new Set();
async function checkPpksPaperTpSl(trade, markPrice) {
  if (!trade.tp && !trade.sl) return;
  if (ppksPaperTpSlLocks.has(trade.id)) return;
  const isLong = trade.side === 'LONG';
  const tpHit = trade.tp != null && (isLong ? markPrice >= trade.tp : markPrice <= trade.tp);
  const slHit = trade.sl != null && (isLong ? markPrice <= trade.sl : markPrice >= trade.sl);
  if (!tpHit && !slHit) return;
  ppksPaperTpSlLocks.add(trade.id);
  try {
    const outcome = tpHit ? 'TP' : 'SL';
    const exitPrice = tpHit ? trade.tp : trade.sl;
    await closePpksPaperTrade({ id: trade.id, exitPrice, outcome });
    console.log(`[PpksPaper] 🎯 ${outcome} hit ${trade.side} ${trade.symbol} exit=${exitPrice}`);
  } finally {
    ppksPaperTpSlLocks.delete(trade.id);
  }
}

async function syncPpksPaperTicker() {
  if (!ppksPaperTicker) return;
  const store = await readPpksPaperStore();
  const symbols = [...new Set(store.trades.filter((t) => ['PENDING', 'OPEN'].includes(t.status)).map((t) => t.symbol))];
  ppksPaperTicker.setSymbols(symbols);
}

function startPpksPaperTicker() {
  if (ppksPaperTicker) return;
  ppksPaperTicker = sharedLastTicker.createClient(
    'ppksPaper',
    ({ symbol, markPrice, eventTime }) => {
    ppksMarkCache.set(symbol, markPrice);
      ppksMarkCacheAt.set(symbol, eventTime);
    processPpksPaperFills(symbol, markPrice).catch(() => {});
    },
  );
  console.log('[PpksPaper] Shared last-price ticker consumer started.');
  syncPpksPaperTicker().catch(() => {});
  setInterval(() => syncPpksPaperTicker().catch(() => {}), 30_000);
}

// Shakeout Reclaim Paper Trades

const SHAKEOUT_PAPER_STORE_CACHE_VERSION = 'SHAKEOUT_PAPER_STORE_CACHE_V1_20260822';
let _shakeoutPaperStoreCache = null;
let _shakeoutPaperStoreLoadPromise = null;
async function readShakeoutPaperStore() {
  if (_shakeoutPaperStoreCache) return _shakeoutPaperStoreCache;
  if (_shakeoutPaperStoreLoadPromise) return _shakeoutPaperStoreLoadPromise;
  _shakeoutPaperStoreLoadPromise = (async () => {
    try {
      const raw = await readFile(SHAKEOUT_PAPER_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed?.trades)) throw new Error('invalid structure');
      _shakeoutPaperStoreCache = parsed;
      console.log(`[ShakeoutPaper] Store cached in memory (${parsed.trades.length} trades; ${SHAKEOUT_PAPER_STORE_CACHE_VERSION}).`);
    } catch (e) {
      if (e.code !== 'ENOENT') console.warn('[ShakeoutPaper] Store read error, starting fresh:', e.message);
      _shakeoutPaperStoreCache = { trades: [] };
    } finally {
      _shakeoutPaperStoreLoadPromise = null;
    }
    return _shakeoutPaperStoreCache;
  })();
  return _shakeoutPaperStoreLoadPromise;
}

let _shakeoutPaperWriteLock = Promise.resolve();
async function writeShakeoutPaperStore(store) {
  _shakeoutPaperStoreCache = store;
  _shakeoutPaperWriteLock = _shakeoutPaperWriteLock.then(() => atomicWriteJson(SHAKEOUT_PAPER_FILE, store));
  return _shakeoutPaperWriteLock;
}

function getShakeoutPaperFeeRate() {
  const feeRate = Number(
    process.env.SHAKEOUT_RECLAIM_PAPER_FEE_RATE
      ?? process.env.BINANCE_FUTURES_TAKER_FEE_RATE
      ?? process.env.BINANCE_FEE_RATE
      ?? 0.0004,
  );
  return Number.isFinite(feeRate) && feeRate >= 0 ? feeRate : 0.0004;
}

function estimateShakeoutPaperFeeUsdt(trade, exitPrice) {
  if (!trade || trade.status === 'PENDING') return null;
  const entry = Number(trade.entryPrice);
  const exit = Number(exitPrice ?? trade.exitPrice ?? trade.markPrice ?? trade.entryPrice);
  const qty = Math.abs(Number(trade.originalQuantity ?? trade.quantity));
  const feeRate = getShakeoutPaperFeeRate();
  if (![entry, exit, qty].every(Number.isFinite) || entry <= 0 || exit <= 0 || qty <= 0) return null;
  return (Math.abs(entry * qty) + Math.abs(exit * qty)) * feeRate;
}

function enrichShakeoutPaperTrade(t, markPrice) {
  const liveMark = Number(markPrice);
  const hasLiveMark = Number.isFinite(liveMark) && liveMark > 0;
  const needsLiveMark = t.status === 'OPEN' || t.status === 'PENDING';
  const mark = needsLiveMark
    ? (hasLiveMark ? liveMark : null)
    : Number(t.exitPrice ?? t.entryPrice);
  const entry = Number(t.entryPrice);
  const qty = Number(t.quantity);
  const margin = Number(t.marginUsdt);
  const realizedPnl = Number(t.realizedPnl ?? 0);
  const sideMult = t.side === 'LONG' ? 1 : -1;
  const isActive = t.status === 'OPEN';
  const pnl = isActive
    ? (hasLiveMark ? realizedPnl + (liveMark - entry) * qty * sideMult : null)
    : (t.pnl ?? null);
  const roe = isActive && margin > 0
    ? (pnl == null ? null : (pnl / margin) * 100)
    : (t.roe ?? null);
  const feeRate = getShakeoutPaperFeeRate();
  const feeUsdt = pnl == null ? null : estimateShakeoutPaperFeeUsdt(t, mark);
  const netPnl = pnl == null ? null : pnl - Number(feeUsdt ?? 0);
  const netRoe = margin > 0 && netPnl != null ? (netPnl / margin) * 100 : null;
  const realGate = t.shakeoutRealGateLabel
    ? null
    : getShakeoutRealGate({
      ...t,
      projectedRoe: getShakeoutProjectedRoe(t),
    });
  return {
    ...t,
    markPrice: mark,
    markUpdatedAt: shakeoutSocketMarkAt.get(String(t.symbol ?? '').toUpperCase()) ?? null,
    pnl,
    roe,
    grossPnl: pnl,
    feeRate,
    feeUsdt,
    netPnl,
    netRoe,
    shakeoutRealGateLabel: t.shakeoutRealGateLabel ?? realGate?.label ?? null,
    shakeoutRealGateReason: t.shakeoutRealGateReason ?? realGate?.reasons?.join('; ') ?? null,
    shakeoutRealGateAllow: t.shakeoutRealGateAllow ?? realGate?.allowReal ?? false,
    shakeoutProjectedRoe: t.shakeoutProjectedRoe ?? realGate?.projectedRoe ?? getShakeoutProjectedRoe(t),
  };
}

function enrichShakeoutStage2V2(trade = {}) {
  const layer1Tier = String(trade.shakeoutSideCandleTier ?? '').toUpperCase();
  if (!['GOOD', 'WATCH', 'RISK'].includes(layer1Tier)) return trade;
  const auditCaptured = Boolean(trade.shakeoutStage2Version);
  const evaluation = evaluateShakeoutStage2({
    layer1Tier,
    setup: trade.shakeoutClass ?? trade.subtype ?? trade.signalType,
    shakeoutCombo: trade.shakeoutCombo,
    signalType: trade.signalType,
    subtype: trade.subtype,
    variant: trade.variant,
    side: trade.side,
    signalAt: trade.signalAt ?? trade.scannedAt ?? trade.createdAt,
    fillAt: trade.openedAt,
    signalBtcMarketRegime: trade.btcMarketRegimeAtSignal,
    entryBtcMarketRegime: trade.btcMarketRegimeAtEntry,
    signalBtcCandle: trade.btcCandleAtSignal,
    entryBtcCandle: auditCaptured
      ? (trade.btcCandleAtEntry ?? trade.btcCandlePatternAtEntry)
      : null,
    duplicateActiveCount: trade.shakeoutStage2DuplicateActiveCount,
    duplicateActiveMarginUsdt: trade.shakeoutStage2DuplicateActiveMarginUsdt,
    rollingDrift: trade.shakeoutStage2RollingDrift,
    // A historical row did not capture these flags at entry/fill. Keep its
    // audit empty instead of fabricating hindsight evidence from later data.
    auditFlags: auditCaptured ? (trade.shakeoutStage2Flags ?? []) : [],
  });
  return {
    ...trade,
    shakeoutStage2SourceVersion: trade.shakeoutStage2Version ?? null,
    shakeoutStage2Version: evaluation.version,
    shakeoutStage2Tier: evaluation.tier,
    shakeoutStage2Label: evaluation.label,
    shakeoutStage2Code: evaluation.code,
    shakeoutStage2Modifier: evaluation.modifier,
    shakeoutStage2Layer1Tier: evaluation.layer1Tier,
    shakeoutStage2Setup: evaluation.setup,
    shakeoutStage2Variant: evaluation.variant,
    shakeoutStage2FillQuality: evaluation.fillQuality,
    shakeoutStage2Flags: evaluation.flags,
    shakeoutStage2Reason: evaluation.reason,
    shakeoutStage2FillDelayMinutes: evaluation.fillDelayMinutes,
    shakeoutStage2AuditOnlyFlags: true,
    shakeoutStage2AuditCaptured: auditCaptured,
    shakeoutStage2Derived: trade.shakeoutStage2Version !== SHAKEOUT_STAGE_2_VERSION,
  };
}

function getShakeoutPaperMark(symbol) {
  const key = String(symbol ?? '').toUpperCase();
  const wsMark = Number(shakeoutSocketMarks.get(key));
  if (Number.isFinite(wsMark) && wsMark > 0) return wsMark;
  return null;
}

async function getShakeoutPaperTrades({
  paging = null,
  day = 'all',
  shakeoutClass = 'all',
  side = 'all',
  stage2 = 'all',
} = {}) {
  const store = await readShakeoutPaperStore();
  const allTrades = store.trades.map((t) => enrichShakeoutMarketIndependentObservation(
    enrichShakeoutObservation(
      enrichShakeoutStage2V2(enrichShakeoutPaperTrade(
        t,
        getShakeoutPaperMark(t.symbol),
      )),
    ),
  ));
  const availableDays = [...new Set(allTrades
    .map((t) => String(t.createdAt ?? t.openedAt ?? t.closedAt ?? '').slice(0, 10))
    .filter(Boolean))]
    .sort()
    .reverse();
  const availableClasses = [...new Set(allTrades
    .map((t) => String(t.shakeoutClass ?? 'UNKNOWN'))
    .filter(Boolean))]
    .sort();
  const selectedDay = String(day ?? 'all');
  const selectedClass = String(shakeoutClass ?? 'all');
  const selectedSide = String(side ?? 'all').toUpperCase();
  const selectedStage2 = String(stage2 ?? 'all').toUpperCase();
  const statusRank = { OPEN: 0, PENDING: 1, CLOSED: 2, EXPIRED: 3, CANCELLED: 4 };
  const trades = allTrades
    .filter((t) => (
      (selectedDay === 'all'
        || String(t.createdAt ?? t.openedAt ?? t.closedAt ?? '').slice(0, 10) === selectedDay)
      && (selectedClass === 'all' || String(t.shakeoutClass ?? 'UNKNOWN') === selectedClass)
      && (selectedSide === 'ALL' || String(t.side ?? '').toUpperCase() === selectedSide)
      && (selectedStage2 === 'ALL'
        || String(t.shakeoutStage2Tier ?? '').toUpperCase() === selectedStage2)
    ))
    .sort((a, b) => {
      const statusDiff = (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9);
      if (statusDiff !== 0) return statusDiff;
      return (Date.parse(b.createdAt ?? '') || 0) - (Date.parse(a.createdAt ?? '') || 0);
    });
  const openRows = trades.filter((t) => t.status === 'OPEN');
  const pendingRows = trades.filter((t) => t.status === 'PENDING');
  const closed = trades.filter((t) => t.status === 'CLOSED');
  const expired = trades.filter((t) => t.status === 'EXPIRED').length;
  const cancelled = trades.filter((t) => t.status === 'CANCELLED').length;
  const invalid = closed.filter((t) => t.outcome === 'INVALID').length;
  const validClosed = closed.filter((t) => t.outcome !== 'INVALID');
  const wins = validClosed.filter((t) => Number(t.netPnl ?? t.pnl ?? 0) > 0).length;
  const tpHits = validClosed.filter((t) => ['TP', 'RUNNER_TP'].includes(t.outcome)).length;
  const slHits = validClosed.filter((t) => t.outcome === 'SL').length;
  const partialActive = trades.filter((t) => t.status === 'OPEN' && t.partialTpTaken).length;
  const partialBreakeven = validClosed.filter((t) => t.outcome === 'PARTIAL_BE').length;
  const partialTrail = validClosed.filter((t) => t.outcome === 'PARTIAL_TRAIL').length;
  const runnerTpHits = validClosed.filter((t) => t.outcome === 'RUNNER_TP').length;
  const recoveryActive = trades.filter((t) => t.status === 'OPEN' && t.recoveryMode).length;
  const recoveryBreakeven = validClosed.filter((t) => t.outcome === 'RECOVERY_BE').length;
  const recoverySl30 = validClosed.filter((t) => t.outcome === 'RECOVERY_SL30').length;
  const avgRoe = validClosed.length > 0 ? validClosed.reduce((s, t) => s + Number(t.netRoe ?? t.roe ?? 0), 0) / validClosed.length : null;
  const feeRows = trades.filter((t) => t.status === 'OPEN' || (t.status === 'CLOSED' && t.outcome !== 'INVALID'));
  const grossPnl = feeRows.reduce((s, t) => s + Number(t.grossPnl ?? t.pnl ?? 0), 0);
  const feeUsdt = feeRows.reduce((s, t) => s + Number(t.feeUsdt ?? 0), 0);
  const netPnl = feeRows.reduce((s, t) => s + Number(t.netPnl ?? t.pnl ?? 0), 0);
  const liveRoe = feeRows.reduce((s, t) => s + Number(t.netRoe ?? t.roe ?? 0), 0);

  // Thống kê theo ngày (group theo closedAt, bỏ INVALID)
  const dailyMap = new Map();
  for (const t of validClosed) {
    const date = String(t.closedAt ?? t.createdAt ?? '').slice(0, 10);
    if (!date) continue;
    const d = dailyMap.get(date) ?? {
      date, orders: 0, wins: 0, losses: 0, tpHits: 0, slHits: 0,
      totalPnl: 0, grossPnl: 0, feeUsdt: 0, netPnl: 0, totalRoe: 0, totalNetRoe: 0, winRate: 0, avgPnl: 0,
    };
    const gross = Number(t.grossPnl ?? t.pnl ?? 0);
    const fee = Number(t.feeUsdt ?? 0);
    const pnl = Number(t.netPnl ?? t.pnl ?? 0);
    d.orders += 1;
    if (pnl > 0) d.wins += 1; else d.losses += 1;
    if (['TP', 'RUNNER_TP'].includes(t.outcome)) d.tpHits += 1;
    if (t.outcome === 'SL') d.slHits += 1;
    d.totalPnl = +(d.totalPnl + pnl).toFixed(4);
    d.grossPnl = +(Number(d.grossPnl ?? 0) + gross).toFixed(4);
    d.feeUsdt = +(Number(d.feeUsdt ?? 0) + fee).toFixed(4);
    d.netPnl = +(Number(d.netPnl ?? 0) + pnl).toFixed(4);
    d.totalRoe = +(d.totalRoe + Number(t.roe ?? 0)).toFixed(2);
    d.totalNetRoe = +(Number(d.totalNetRoe ?? 0) + Number(t.netRoe ?? t.roe ?? 0)).toFixed(2);
    dailyMap.set(date, d);
  }
  for (const t of trades) {
    if (t.status !== 'OPEN' || !t.partialTpTaken) continue;
    const realizedPnl = Number(t.realizedPnl ?? 0);
    if (!Number.isFinite(realizedPnl) || realizedPnl === 0) continue;
    const date = String(t.partialTpAt ?? t.openedAt ?? t.createdAt ?? '').slice(0, 10);
    if (!date) continue;
    const d = dailyMap.get(date) ?? {
      date, orders: 0, wins: 0, losses: 0, tpHits: 0, slHits: 0,
      totalPnl: 0, grossPnl: 0, feeUsdt: 0, netPnl: 0, totalRoe: 0, totalNetRoe: 0, winRate: 0, avgPnl: 0,
    };
    d.openPartialRealizedPnl = +(Number(d.openPartialRealizedPnl ?? 0) + realizedPnl).toFixed(4);
    d.totalPnl = +(d.totalPnl + realizedPnl).toFixed(4);
    d.grossPnl = +(Number(d.grossPnl ?? 0) + realizedPnl).toFixed(4);
    d.netPnl = +(Number(d.netPnl ?? 0) + realizedPnl).toFixed(4);
    d.totalRoe = +(d.totalRoe + realizedPnl / Math.max(Number(t.marginUsdt) || 1, 1) * 100).toFixed(2);
    d.totalNetRoe = +(Number(d.totalNetRoe ?? 0) + realizedPnl / Math.max(Number(t.marginUsdt) || 1, 1) * 100).toFixed(2);
    dailyMap.set(date, d);
  }
  const daily = [...dailyMap.values()]
    .map((d) => ({
      ...d,
      winRate: d.orders > 0 ? +((d.wins / d.orders) * 100).toFixed(1) : 0,
      avgPnl: d.orders > 0 ? +(d.totalPnl / d.orders).toFixed(4) : 0,
      avgNetRoe: d.orders > 0 ? +(Number(d.totalNetRoe ?? d.totalRoe ?? 0) / d.orders).toFixed(2) : 0,
    }))
    .sort((a, b) => b.date.localeCompare(a.date));

  // So sánh điểm vào MARKET vs PENDING (2 lệnh cùng signalId)
  const buildVariant = (name) => {
    const all = trades.filter((t) => t.variant === name);
    const vClosed = all.filter((t) => t.status === 'CLOSED' && t.outcome !== 'INVALID');
    const w = vClosed.filter((t) => Number(t.netPnl ?? t.pnl ?? 0) > 0).length;
    const totalPnl = vClosed.reduce((s, t) => s + Number(t.netPnl ?? t.pnl ?? 0), 0);
    const totalRoe = vClosed.reduce((s, t) => s + Number(t.netRoe ?? t.roe ?? 0), 0);
    return {
      variant: name,
      total: all.length,
      open: all.filter((t) => t.status === 'OPEN').length,
      pending: all.filter((t) => t.status === 'PENDING').length,   // PENDING chưa fill (chưa chạm entry)
      closed: vClosed.length,
      wins: w,
      losses: vClosed.length - w,
      winRate: vClosed.length > 0 ? +((w / vClosed.length) * 100).toFixed(1) : 0,
      totalPnl: +totalPnl.toFixed(4),
      totalRoe: +totalRoe.toFixed(2),
      avgRoe: vClosed.length > 0 ? +(totalRoe / vClosed.length).toFixed(1) : null,
    };
  };
  const variantCompare = [buildVariant('MARKET'), buildVariant('PENDING')];
  const buildRealGate = (label) => {
    const all = trades.filter((t) => String(t.shakeoutRealGateLabel ?? 'REAL_TEST') === label);
    const vClosed = all.filter((t) => t.status === 'CLOSED' && t.outcome !== 'INVALID');
    const w = vClosed.filter((t) => Number(t.netPnl ?? t.pnl ?? 0) > 0).length;
    const totalPnl = vClosed.reduce((s, t) => s + Number(t.netPnl ?? t.pnl ?? 0), 0);
    const totalRoe = vClosed.reduce((s, t) => s + Number(t.netRoe ?? t.roe ?? 0), 0);
    return {
      label,
      total: all.length,
      open: all.filter((t) => t.status === 'OPEN').length,
      pending: all.filter((t) => t.status === 'PENDING').length,
      closed: vClosed.length,
      wins: w,
      losses: vClosed.length - w,
      winRate: vClosed.length > 0 ? +((w / vClosed.length) * 100).toFixed(1) : 0,
      totalPnl: +totalPnl.toFixed(4),
      avgRoe: vClosed.length > 0 ? +(totalRoe / vClosed.length).toFixed(1) : null,
    };
  };
  const realGateCompare = ['REAL_OK', 'REAL_TEST', 'REAL_BLOCK'].map(buildRealGate);
  const observationStats = buildShakeoutObservationStats(allTrades);
  const aggregateStats = buildShakeoutPaperAggregateStats(trades, {
    day: selectedDay,
  });
  const page = slicePaperPage(trades, paging);

  return {
    trades: page.rows,
    pagination: page.pagination,
    availableDays,
    availableClasses,
    filter: {
      day: selectedDay,
      shakeoutClass: selectedClass,
      side: selectedSide,
      stage2: selectedStage2,
    },
    summary: {
      total: trades.length,
      open: openRows.length,
      pending: pendingRows.length,
      active: openRows.length + pendingRows.length,
      closed: closed.length,
      expired,
      cancelled,
      invalid,
      wins,
      losses: validClosed.length - wins,
      tpHits,
      slHits,
      recoveryActive,
      recoveryBreakeven,
      recoverySl30,
      partialActive,
      partialBreakeven,
      partialTrail,
      runnerTpHits,
      avgRoe: avgRoe != null ? +avgRoe.toFixed(1) : null,
      feeRate: getShakeoutPaperFeeRate(),
      grossPnl: +grossPnl.toFixed(4),
      feeUsdt: +feeUsdt.toFixed(4),
      netPnl: +netPnl.toFixed(4),
      livePnl: +netPnl.toFixed(4),
      liveRoe: +liveRoe.toFixed(2),
    },
    daily,
    variantCompare,
    realGateCompare,
    observationStats,
    aggregateStats,
  };
}

async function getRecentBreakoutBtcTurnProfitCutPause(side) {
  const tradeSide = String(side ?? '').toUpperCase();
  const expected = tradeSide === 'SHORT'
    ? 'BREAKOUT_BTC_BOTTOM_BOUNCE_CLUSTER_BAD_PROFIT_CUT'
    : 'BREAKOUT_BTC_TOP_REJECT_CLUSTER_BAD_PROFIT_CUT';
  const pumpStore = await readPumpPaperStore().catch(() => ({ trades: [] }));
  let latest = null;
  for (const t of pumpStore.trades ?? []) {
    if (t.side !== tradeSide || String(t.outcome ?? '') !== expected) continue;
    const closedAt = Date.parse(t.closedAt ?? '');
    if (!Number.isFinite(closedAt)) continue;
    if (!latest || closedAt > latest.closedAt) latest = { closedAt, symbol: t.symbol, outcome: expected };
  }
  if (!latest) return null;
  const confirmation = getBtcPostCutResumeConfirmation(tradeSide, latest.closedAt);
  if (confirmation.confirmed) return null;
  return {
    setAt: latest.closedAt,
    label: expected,
    reason: `recent ${expected} ${latest.symbol ?? ''} at ${new Date(latest.closedAt).toISOString()}`,
    confirmation,
  };
}

function getShakeoutDefaultSlPrice(entryPrice, leverage, side) {
  const entry = Number(entryPrice);
  const lev = Number(leverage);
  const slRoe = Math.min(
    getShakeoutMaxSlRoe(),
    Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_DEFAULT_SL_ROE ?? 20)),
  );
  const tradeSide = String(side ?? '').toUpperCase();
  if (![entry, lev, slRoe].every(Number.isFinite) || entry <= 0 || lev <= 0 || slRoe <= 0) return null;
  if (tradeSide === 'LONG') return entry * (1 - slRoe / 100 / lev);
  if (tradeSide === 'SHORT') return entry * (1 + slRoe / 100 / lev);
  return null;
}

function getShakeoutMaxSlRoe() {
  const maxSlRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_MAX_SL_ROE ?? 20));
  return Number.isFinite(maxSlRoe) && maxSlRoe > 0 ? maxSlRoe : 20;
}

function getShakeoutPaperSlRoeForTrade(trade) {
  const maxSlRoe = getShakeoutMaxSlRoe();
  let slRoe;
  if (process.env.SHAKEOUT_RECLAIM_PAPER_REAL_GATE_SL === 'false') {
    slRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_DEFAULT_SL_ROE ?? 20));
    return Math.min(maxSlRoe, Number.isFinite(slRoe) && slRoe > 0 ? slRoe : maxSlRoe);
  }
  const realGate = String(trade?.shakeoutRealGateLabel ?? '').toUpperCase();
  if (realGate === 'REAL_OK') {
    slRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_REAL_OK_SL_ROE ?? 30));
    return Math.min(maxSlRoe, Number.isFinite(slRoe) && slRoe > 0 ? slRoe : maxSlRoe);
  }
  if (realGate === 'REAL_TEST' || realGate === 'REAL_BLOCK') {
    slRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_REAL_TEST_BLOCK_SL_ROE ?? 15));
    return Math.min(maxSlRoe, Number.isFinite(slRoe) && slRoe > 0 ? slRoe : maxSlRoe);
  }
  slRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_DEFAULT_SL_ROE ?? 20));
  return Math.min(maxSlRoe, Number.isFinite(slRoe) && slRoe > 0 ? slRoe : maxSlRoe);
}

function getShakeoutSlPriceByRoe(entryPrice, leverage, side, slRoe) {
  const entry = Number(entryPrice);
  const lev = Number(leverage);
  const riskRoe = Math.abs(Number(slRoe));
  const tradeSide = String(side ?? '').toUpperCase();
  if (![entry, lev, riskRoe].every(Number.isFinite) || entry <= 0 || lev <= 0 || riskRoe <= 0) return null;
  if (tradeSide === 'LONG') return entry * (1 - riskRoe / 100 / lev);
  if (tradeSide === 'SHORT') return entry * (1 + riskRoe / 100 / lev);
  return null;
}

function capShakeoutTpByMaxRoe({ entryPrice, tp, side, leverage }) {
  if (tp == null) return { tp: null, capped: false, maxRoe: null };
  const entry = Number(entryPrice);
  const target = Number(tp);
  const lev = Number(leverage);
  const maxRoe = Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_MAX_TP_ROE ?? 55));
  const tradeSide = String(side ?? '').toUpperCase();
  if (![entry, target, lev, maxRoe].every(Number.isFinite)
      || entry <= 0 || target <= 0 || lev <= 0 || maxRoe <= 0) {
    return { tp: target, capped: false, maxRoe: null };
  }

  const maxMove = maxRoe / 100 / lev;
  const cappedTp = tradeSide === 'LONG'
    ? Math.min(target, entry * (1 + maxMove))
    : tradeSide === 'SHORT'
      ? Math.max(target, entry * (1 - maxMove))
      : target;
  const capped = Math.abs(cappedTp - target) / Math.max(Math.abs(target), 1e-12) > 1e-10;
  return { tp: cappedTp, capped, maxRoe };
}

async function createShakeoutPaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase().trim();
  const side = String(payload.side ?? payload.action ?? 'LONG').toUpperCase();
  let marginUsdt = Number(payload.marginUsdt ?? process.env.SHAKEOUT_RECLAIM_PAPER_MARGIN_USDT ?? 10);
  const leverage = Math.max(1, Math.min(125, Number(payload.leverage ?? 10)));
  const entryPrice = Number(payload.entryPrice ?? payload.entry);

  if (!symbol) throw new Error('symbol required');
  if (!['LONG', 'SHORT'].includes(side)) throw new Error('side must be LONG or SHORT');
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) throw new Error('entryPrice required');
  const defaultSl = getShakeoutDefaultSlPrice(entryPrice, leverage, side);
  const sl = process.env.SHAKEOUT_RECLAIM_PAPER_FORCE_DEFAULT_SL === 'false'
    ? (payload.sl != null ? Number(payload.sl) : defaultSl)
    : defaultSl;
  const rawTp = payload.tp != null ? Number(payload.tp) : null;
  const tpCap = capShakeoutTpByMaxRoe({ entryPrice, tp: rawTp, side, leverage });
  const tp = tpCap.tp;
  if (Number.isFinite(sl) && Number.isFinite(tp)) {
    const validGeometry = side === 'LONG'
      ? (sl < entryPrice && entryPrice < tp)
      : (tp < entryPrice && entryPrice < sl);
    if (!validGeometry) throw new Error(`invalid ${side} geometry entry=${entryPrice} sl=${sl} tp=${tp}`);
  }

  // variant: 'MARKET' (vào ngay theo giá market) hoặc 'PENDING' (chờ giá chạm entry dự kiến)
  const variant = payload.variant ? String(payload.variant).toUpperCase().slice(0, 16) : null;
  const signalId = payload.signalId ? String(payload.signalId).slice(0, 64) : null;
  const pendingShadowMarginCapUsdt = Math.max(
    0.01,
    Number(process.env.SHAKEOUT_RECLAIM_PENDING_SHADOW_MARGIN_CAP_USDT ?? 1),
  );
  marginUsdt = capShakeoutPendingShadowMargin({
    variant,
    marginUsdt,
    capUsdt: pendingShadowMarginCapUsdt,
  });

  const store = await readShakeoutPaperStore();
  const dup = store.trades.find((t) =>
    t.symbol === symbol &&
    t.side === side &&
    (t.variant ?? null) === variant &&
    String(t.source ?? '').startsWith('shakeout-auto') &&
    ['PENDING', 'OPEN'].includes(t.status),
  );
  if (dup) return { trade: enrichShakeoutPaperTrade(dup, getShakeoutPaperMark(symbol)) };

  const status = payload.status === 'PENDING' ? 'PENDING' : 'OPEN';
  const rawBtcHealth = payload.btcHealth && typeof payload.btcHealth === 'object'
    ? payload.btcHealth
    : await getBtcHealth().catch(() => btcHealthCache.data);
  const btcHealthSnapshot = buildBtcHealthSnapshot(rawBtcHealth) ?? null;
  const signalContext = getShakeoutBtcEntrySnapshot(rawBtcHealth, Date.now());
  const entryContext = status === 'OPEN'
    ? signalContext
    : null;
  const chopChaseMarginCapUsdt = Math.max(
    0.01,
    Number(process.env.SHAKEOUT_RECLAIM_CHASE_CHOP_MARGIN_CAP_USDT ?? 1),
  );
  marginUsdt = capShakeoutChopChaseMargin({
    variant,
    btcMarketRegimeAtEntry: entryContext?.btcMarketRegimeAtEntry,
    marginUsdt,
    capUsdt: chopChaseMarginCapUsdt,
  });
  const entrySignalAt = payload.signalAt ?? payload.scannedAt ?? payload.createdAt ?? new Date().toISOString();
  const resolvedSymbolCandleAtEntry = payload.symbolCandleAtEntry
    ?? payload.candlePatternAtEntry
    ?? payload.candlePattern5m
    ?? cachedCandlePatternAt(symbol, '5m', entrySignalAt)
    ?? null;
  const resolvedBtcCandleAtEntry = payload.btcCandleAtEntry
    ?? payload.btcCandlePatternAtEntry
    ?? payload.btcCandlePattern5m
    ?? cachedCandlePatternAt('BTCUSDT', '5m', entrySignalAt)
    ?? null;
  const activeSignalVariants = signalId
    ? store.trades.filter((row) =>
        row.signalId === signalId
        && ['OPEN', 'PENDING'].includes(row.status))
    : [];
  const stage2RollingDrift = shakeoutRollingDriftStats(store.trades, {
    variant,
    side,
    createdAt: entrySignalAt,
  });
  const resolvedSideCandleGate = payload.shakeoutSideCandleTie
    ? {
        version: payload.ruleVersion,
        regime: payload.regimeAtEntry,
        tier: payload.shakeoutSideCandleTier,
        label: payload.shakeoutSideCandleLabel,
        reason: payload.shakeoutSideCandleReason,
        marginCapUsdt: payload.shakeoutSideCandleMarginCapUsdt,
      }
    : evaluateShakeoutSideCandle({
        side,
        btcHealth: btcHealthSnapshot ?? {},
        btcCandle: resolvedBtcCandleAtEntry,
      });
  const sideCandleMarginCap = Number(resolvedSideCandleGate.marginCapUsdt);
  if (resolvedSideCandleGate.marginCapUsdt != null
      && Number.isFinite(sideCandleMarginCap)
      && sideCandleMarginCap > 0) {
    marginUsdt = Math.min(marginUsdt, sideCandleMarginCap);
  }
  const btcTrendScore = Number(btcHealthSnapshot?.btcTrendScore);
  const btcPct6h = Number(btcHealthSnapshot?.pct6h);
  const signalTimeframe = String(payload.signalTimeframe ?? payload.timeframe ?? payload.interval ?? payload.factors?.timeframe ?? '5m');
  const payloadBtcCorr = Number(payload.btcCorr);
  const btcCorr = Number.isFinite(payloadBtcCorr)
    ? +payloadBtcCorr.toFixed(2)
    : getCoinBtcCorr(symbol, signalTimeframe, 30);
  const fallbackBtcGate = getShakeoutBtcGate({
    sig: {
      ...payload,
      action: side,
      factors: payload.factors ?? {},
    },
    side,
    btcHealth: btcHealthSnapshot,
    btcCorr,
    trapRisk: payload.trapRisk,
  });
  const btcGateLabel = normalizePumpComboPart(payload.btcGateLabel ?? payload.shakeoutBtcGateLabel ?? fallbackBtcGate.label, 'GATE_UNKNOWN');
  const btcGateReason = String(payload.btcGateReason ?? payload.shakeoutBtcGateReason ?? fallbackBtcGate.reason ?? '').slice(0, 360);
  const btcPhase = normalizePumpComboPart(payload.btcPhase ?? fallbackBtcGate.phase, 'BTC_NO_DATA');
  const btcRelationLabel = normalizePumpComboPart(payload.btcRelationLabel ?? fallbackBtcGate.relation, 'REL_NO_DATA');
  const chaseShortTierEvaluation = evaluateShakeoutChaseShortTier({
    variant,
    side,
    score: payload.score,
    btcPhase,
    tierAMarginUsdt: process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_SHORT_A_MARGIN_USDT ?? 10,
    tierBMarginUsdt: process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_SHORT_B_MARGIN_USDT ?? 5,
  });
  if (chaseShortTierEvaluation.applies) {
    // The explicit CHASE SHORT A/B plan owns sizing for this cohort. Olde
    // CHOP, side-candle and weak-group caps remain active for other variants.
    marginUsdt = chaseShortTierEvaluation.marginUsdt;
  }
  const chaseChopShadow = !chaseShortTierEvaluation.applies && isShakeoutChopChase({
    variant,
    btcMarketRegimeAtEntry: entryContext?.btcMarketRegimeAtEntry,
  });
  const shakeoutCombo = String(payload.shakeoutCombo ?? shakeoutSignalComboOf({
    ...payload,
    action: side,
    side,
    timeframe: signalTimeframe,
    btcCorr,
    btcPhase,
    btcRelationLabel,
    btcGateLabel,
  }, btcHealthSnapshot)).slice(0, 260);
  const stage2Evaluation = evaluateShakeoutStage2({
    layer1Tier: resolvedSideCandleGate.tier,
    setup: payload.shakeoutClass ?? payload.subtype ?? payload.signalType ?? payload.type,
    shakeoutCombo,
    signalType: payload.signalType ?? payload.type,
    subtype: payload.subtype,
    variant,
    side,
    signalAt: entrySignalAt,
    fillAt: status === 'OPEN' ? new Date().toISOString() : null,
    signalBtcMarketRegime: signalContext?.btcMarketRegimeAtEntry,
    entryBtcMarketRegime: entryContext?.btcMarketRegimeAtEntry,
    signalBtcCandle: resolvedBtcCandleAtEntry,
    entryBtcCandle: status === 'OPEN' ? resolvedBtcCandleAtEntry : null,
    duplicateActiveCount: activeSignalVariants.length,
    duplicateActiveMarginUsdt: activeSignalVariants.reduce(
      (sum, row) => sum + Number(row.marginUsdt ?? 0),
      0,
    ),
    rollingDrift: stage2RollingDrift,
  });
  const observationRiskPct = Number.isFinite(sl) && sl > 0
    ? Math.abs(sl - entryPrice) / entryPrice * 100
    : null;
  const observationRewardPct = Number.isFinite(tp) && tp > 0
    ? Math.abs(tp - entryPrice) / entryPrice * 100
    : null;
  const observationEvaluation = evaluateShakeoutObservation({
    ...payload,
    side,
    variant,
    status: undefined,
    outcome: undefined,
    pnl: undefined,
    roe: undefined,
    signalAt: entrySignalAt,
    signalTimeframe,
    btcHealth: btcHealthSnapshot,
    btcCorr,
    btcPhase,
    btcRelationLabel,
    btcMarketRegimeAtSignal: signalContext?.btcMarketRegimeAtEntry,
    btcMarketRegimeAtEntry: entryContext?.btcMarketRegimeAtEntry,
    symbolCandleAtEntry: resolvedSymbolCandleAtEntry,
    btcCandleAtEntry: resolvedBtcCandleAtEntry,
    shakeoutObservationRiskPct: observationRiskPct,
    shakeoutObservationRewardPct: observationRewardPct,
    shakeoutObservationRr: observationRiskPct > 0 && observationRewardPct != null
      ? observationRewardPct / observationRiskPct
      : null,
  });
  const btcLogNote = btcHealthSnapshot
    ? `btcLog=${btcHealthSnapshot.regime ?? '-'}:${btcHealthSnapshot.btcTrendDir ?? '-'}:${Number.isFinite(btcTrendScore) ? btcTrendScore : '-'} pct6h=${Number.isFinite(btcPct6h) ? btcPct6h.toFixed(2) : '-'} ema1h=${btcHealthSnapshot.emaTrend1h ?? '-'} bull=${btcHealthSnapshot.bullBias ?? '-'}`
    : 'btcLog=NO_DATA';
  const trade = {
    id: crypto.randomUUID(),
    signalId,
    variant,
    symbol,
    side,
    status,
    marginUsdt,
    leverage,
    quantity: (marginUsdt * leverage) / entryPrice,
    originalQuantity: (marginUsdt * leverage) / entryPrice,
    realizedPnl: 0,
    entryPrice,
    tp,
    sl,
    fillPrice: status === 'OPEN' ? entryPrice : null,
    exitPrice: null,
    pnl: null,
    roe: null,
    outcome: null,
    score: payload.score != null ? Number(payload.score) : null,
    signalType: String(payload.signalType ?? payload.type ?? '').slice(0, 80),
    candlePattern5m: payload.candlePattern5m && typeof payload.candlePattern5m === 'object'
      ? payload.candlePattern5m
      : null,
    candlePattern15m: payload.candlePattern15m && typeof payload.candlePattern15m === 'object'
      ? payload.candlePattern15m
      : null,
    btcCandlePattern5m: payload.btcCandlePattern5m && typeof payload.btcCandlePattern5m === 'object'
      ? payload.btcCandlePattern5m
      : null,
    candlePatternAtEntry: resolvedSymbolCandleAtEntry && typeof resolvedSymbolCandleAtEntry === 'object'
      ? resolvedSymbolCandleAtEntry
      : null,
    btcCandlePatternAtEntry: resolvedBtcCandleAtEntry && typeof resolvedBtcCandleAtEntry === 'object'
      ? resolvedBtcCandleAtEntry
      : null,
    symbolCandleAtEntry: resolvedSymbolCandleAtEntry && typeof resolvedSymbolCandleAtEntry === 'object'
      ? resolvedSymbolCandleAtEntry
      : null,
    btcCandleAtEntry: resolvedBtcCandleAtEntry && typeof resolvedBtcCandleAtEntry === 'object'
      ? resolvedBtcCandleAtEntry
      : null,
    symbolCandleAtSignal: resolvedSymbolCandleAtEntry && typeof resolvedSymbolCandleAtEntry === 'object'
      ? resolvedSymbolCandleAtEntry
      : null,
    btcCandleAtSignal: resolvedBtcCandleAtEntry && typeof resolvedBtcCandleAtEntry === 'object'
      ? resolvedBtcCandleAtEntry
      : null,
    ruleVersion: resolvedSideCandleGate.version ? String(resolvedSideCandleGate.version).slice(0, 64) : null,
    regimeAtEntry: resolvedSideCandleGate.regime ? String(resolvedSideCandleGate.regime).toUpperCase().slice(0, 16) : null,
    shakeoutSideCandleTier: resolvedSideCandleGate.tie
      ? String(resolvedSideCandleGate.tier).toUpperCase().slice(0, 12)
      : null,
    shakeoutSideCandleLabel: resolvedSideCandleGate.label
      ? String(resolvedSideCandleGate.label).toUpperCase().slice(0, 80)
      : null,
    shakeoutSideCandleReason: resolvedSideCandleGate.reason
      ? String(resolvedSideCandleGate.reason).slice(0, 300)
      : null,
    shakeoutSideCandleMarginCapUsdt: resolvedSideCandleGate.marginCapUsdt != null
      && Number.isFinite(Number(resolvedSideCandleGate.marginCapUsdt))
      ? Number(resolvedSideCandleGate.marginCapUsdt)
      : null,
    shakeoutQuality: payload.shakeoutQuality ? String(payload.shakeoutQuality).toUpperCase().slice(0, 12) : null,
    highJumpRisk: Boolean(payload.highJumpRisk),
    highJumpRiskLabel: payload.highJumpRiskLabel ? String(payload.highJumpRiskLabel).slice(0, 40) : null,
    highJumpRiskReason: payload.highJumpRiskReason ? String(payload.highJumpRiskReason).slice(0, 300) : null,
    highJumpRiskMetrics: payload.highJumpRiskMetrics && typeof payload.highJumpRiskMetrics === 'object'
      ? payload.highJumpRiskMetrics
      : null,
    shakeoutClass: payload.shakeoutClass ? String(payload.shakeoutClass).toUpperCase().slice(0, 40) : null,
    shakeoutClassLabel: payload.shakeoutClassLabel ? String(payload.shakeoutClassLabel).slice(0, 80) : null,
    shakeoutClassReason: payload.shakeoutClassReason ? String(payload.shakeoutClassReason).slice(0, 240) : null,
    shakeoutClassColor: payload.shakeoutClassColor ? String(payload.shakeoutClassColor).slice(0, 20) : null,
    shakeoutRealGateLabel: payload.shakeoutRealGateLabel ? String(payload.shakeoutRealGateLabel).slice(0, 24) : null,
    shakeoutRealGateReason: payload.shakeoutRealGateReason ? String(payload.shakeoutRealGateReason).slice(0, 300) : null,
    shakeoutRealGateAllow: Boolean(payload.shakeoutRealGateAllow),
    shakeoutProjectedRoe: Number.isFinite(Number(payload.shakeoutProjectedRoe)) ? Number(payload.shakeoutProjectedRoe) : null,
    subtype: payload.subtype ? String(payload.subtype).toUpperCase().slice(0, 40) : null,
    bottomRebound: Boolean(payload.bottomRebound),
    noStopLoss: false,
    bottomReboundDcaAllowed: payload.bottomReboundDcaAllowed !== false,
    bottomReboundScoutOnly: Boolean(payload.bottomReboundScoutOnly),
    dcaBlocked: Boolean(payload.dcaBlocked),
    stage: String(payload.stage ?? '').slice(0, 80),
    signalTimeframe,
    btcHealth: btcHealthSnapshot,
    btcCorr,
    btcPhase,
    btcGateLabel,
    btcGateReason,
    btcRelationLabel,
    shakeoutCombo,
    chaseConfirmation: payload.chaseConfirmation && typeof payload.chaseConfirmation === 'object'
      ? payload.chaseConfirmation
      : null,
    shakeoutChaseShortTierVersion: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.version
      : null,
    shakeoutChaseShortTier: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.tie
      : null,
    shakeoutChaseShortLabel: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.label
      : null,
    shakeoutChaseShortCode: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.code
      : null,
    shakeoutChaseShortReason: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.reason
      : null,
    shakeoutChaseShortMarginUsdt: chaseShortTierEvaluation.applies
      ? chaseShortTierEvaluation.marginUsdt
      : null,
    btcTrendDir: btcHealthSnapshot?.btcTrendDir ?? null,
    btcTrendScore: Number.isFinite(btcTrendScore) ? btcTrendScore : null,
    btcRegimeAtEntry: btcHealthSnapshot?.regime ?? null,
    btcPct6hAtEntry: Number.isFinite(btcPct6h) ? btcPct6h : null,
    btcEmaTrend1hAtEntry: btcHealthSnapshot?.emaTrend1h ?? null,
    btcBullBiasAtEntry: btcHealthSnapshot?.bullBias ?? null,
    btcMarketRegimeAtEntry: entryContext?.btcMarketRegimeAtEntry ?? null,
    btcTrendDir4hAtEntry: entryContext?.btcTrendDir4hAtEntry ?? null,
    btcTrendScore4hAtEntry: entryContext?.btcTrendScore4hAtEntry ?? null,
    btcPct24hAtEntry: entryContext?.btcPct24hAtEntry ?? null,
    btc5mFlipRateAtEntry: entryContext?.btc5mFlipRateAtEntry ?? null,
    btc5mFlipCountAtEntry: entryContext?.btc5mFlipCountAtEntry ?? null,
    btc5mFlipTransitionsAtEntry: entryContext?.btc5mFlipTransitionsAtEntry ?? null,
    btc5mFlipSamplesAtEntry: entryContext?.btc5mFlipSamplesAtEntry ?? null,
    btc5mFlipWindowAtEntry: entryContext?.btc5mFlipWindowAtEntry ?? null,
    btcContextCapturedAt: entryContext?.capturedAt ?? null,
    btcMarketRegimeAtSignal: signalContext?.btcMarketRegimeAtEntry ?? null,
    btcTrendDir4hAtSignal: signalContext?.btcTrendDir4hAtEntry ?? null,
    btcTrendScore4hAtSignal: signalContext?.btcTrendScore4hAtEntry ?? null,
    btc5mFlipRateAtSignal: signalContext?.btc5mFlipRateAtEntry ?? null,
    btcSignalContextCapturedAt: signalContext?.capturedAt ?? null,
    shakeoutStage2Version: stage2Evaluation.version,
    shakeoutStage2Tier: stage2Evaluation.tier,
    shakeoutStage2Label: stage2Evaluation.label,
    shakeoutStage2Code: stage2Evaluation.code,
    shakeoutStage2Modifier: stage2Evaluation.modifier,
    shakeoutStage2Layer1Tier: stage2Evaluation.layer1Tier,
    shakeoutStage2Setup: stage2Evaluation.setup,
    shakeoutStage2Variant: stage2Evaluation.variant,
    shakeoutStage2FillQuality: stage2Evaluation.fillQuality,
    shakeoutStage2AuditOnlyFlags: true,
    shakeoutStage2AuditCaptured: true,
    shakeoutStage2Derived: false,
    shakeoutStage2Flags: stage2Evaluation.flags,
    shakeoutStage2Reason: stage2Evaluation.reason,
    shakeoutStage2EvaluatedAt: stage2Evaluation.evaluatedAt,
    shakeoutStage2FillDelayMinutes: stage2Evaluation.fillDelayMinutes,
    shakeoutStage2DuplicateActiveCount: stage2Evaluation.duplicateActiveCount,
    shakeoutStage2DuplicateActiveMarginUsdt: stage2Evaluation.duplicateActiveMarginUsdt,
    shakeoutStage2RollingDrift: stage2Evaluation.rollingDrift,
    ...observationEvaluation,
    shakeoutObservationDerived: false,
    pendingShadowMarginCapUsdt: variant === 'PENDING' ? pendingShadowMarginCapUsdt : null,
    chaseChopShadow,
    signalAt: String(entrySignalAt),
    createdAt: new Date().toISOString(),
    openedAt: status === 'OPEN' ? new Date().toISOString() : null,
    closedAt: null,
    source: String(payload.source ?? 'manual').slice(0, 80),
    note: [
      btcLogNote,
      entryContext
        ? `BTC_ENTRY_CONTEXT=4h:${entryContext.btcTrendDir4hAtEntry ?? '-'}:${entryContext.btcTrendScore4hAtEntry ?? '-'} flip5m=${entryContext.btc5mFlipRateAtEntry ?? '-'} (${entryContext.btc5mFlipCountAtEntry}/${entryContext.btc5mFlipTransitionsAtEntry}) regime=${entryContext.btcMarketRegimeAtEntry ?? '-'}`
        : '',
      chaseChopShadow
        ? `CHASE_CHOP_SHADOW=margin_cap_$${chopChaseMarginCapUsdt}`
        : '',
      `SHAKEOUT_BTC_GATE=${btcGateLabel}: ${btcGateReason}`,
      `SHAKEOUT_COMBO=${shakeoutCombo}`,
      resolvedSideCandleGate.label
        ? `SIDE_BTC_CANDLE=${resolvedSideCandleGate.label}: ${resolvedSideCandleGate.reason ?? ''}`
        : '',
      variant === 'PENDING'
        ? `PENDING_SHADOW=margin_cap_$${pendingShadowMarginCapUsdt}`
        : '',
      chaseShortTierEvaluation.applies
        ? `CHASE_SHORT_TIER=${chaseShortTierEvaluation.tier}; ${chaseShortTierEvaluation.reason}`
        : '',
      `SHAKEOUT_STAGE_2=${stage2Evaluation.tier}:${stage2Evaluation.label}; ${stage2Evaluation.reason}`,
      String(payload.note ?? ''),
      defaultSl ? `defaultSL=${Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_DEFAULT_SL_ROE ?? 20))}%ROE@${defaultSl}` : '',
      tpCap.capped ? `maxTP=${tpCap.maxRoe}%ROE oldTP=${rawTp} newTP=${tp}` : '',
    ].filter(Boolean).join(' | ').slice(0, 900),
    trapRisk: payload.trapRisk ? String(payload.trapRisk).toUpperCase().slice(0, 12) : null,
    warning: Array.isArray(payload.trapReasons) ? payload.trapReasons.join('; ').slice(0, 300) : null,
    entryReference: Number.isFinite(Number(payload.entryReference)) ? Number(payload.entryReference) : null,
    entryRaw: Number.isFinite(Number(payload.entryRaw)) ? Number(payload.entryRaw) : null,
    entryDistancePct: Number.isFinite(Number(payload.entryDistancePct)) ? Number(payload.entryDistancePct) : null,
    entryRawDistancePct: Number.isFinite(Number(payload.entryRawDistancePct)) ? Number(payload.entryRawDistancePct) : null,
    entryWasClamped: Boolean(payload.entryWasClamped),
    btcRegime: payload.btcRegime ? String(payload.btcRegime).toUpperCase().slice(0, 12) : null,
    btcEntryClass: payload.btcEntryClass ? String(payload.btcEntryClass).toUpperCase().slice(0, 20) : null,
    btcRelation: payload.btcRelation && typeof payload.btcRelation === 'object'
      ? payload.btcRelation
      : null,
    btcTurnRisk: payload.btcTurnRisk && typeof payload.btcTurnRisk === 'object'
      ? payload.btcTurnRisk
      : null,
    btcTurnRiskLabel: payload.btcTurnRiskLabel ? String(payload.btcTurnRiskLabel).slice(0, 60) : null,
    btcTurnRiskAgainstSide: Boolean(payload.btcTurnRiskAgainstSide),
    btcTurnRiskReason: payload.btcTurnRiskReason ? String(payload.btcTurnRiskReason).slice(0, 320) : null,
    btcTurnRiskAt: payload.btcTurnRiskAt ? String(payload.btcTurnRiskAt).slice(0, 32) : null,
    btcTurnRiskPrice: Number.isFinite(Number(payload.btcTurnRiskPrice)) ? Number(payload.btcTurnRiskPrice) : null,
    btcTurnRiskBottomBounce: Boolean(payload.btcTurnRiskBottomBounce),
    btcTurnRiskTopReject: Boolean(payload.btcTurnRiskTopReject),
    btcIndependentShort: Boolean(payload.btcIndependentShort),
    btcStrongShortEma99: Boolean(payload.btcStrongShortEma99),
    btcDynamicEntry: Boolean(payload.btcDynamicEntry),
    btcDynamicLocked: Boolean(payload.btcDynamicLocked),
    btcAnchorPrice: Number.isFinite(Number(payload.btcAnchorPrice)) ? Number(payload.btcAnchorPrice) : null,
    btcLastPrice: Number.isFinite(Number(payload.btcLastPrice)) ? Number(payload.btcLastPrice) : null,
    btcDynamicBaseEntry: Number.isFinite(Number(payload.btcDynamicBaseEntry))
      ? Number(payload.btcDynamicBaseEntry)
      : null,
    btcDynamicMaxPct: Number.isFinite(Number(payload.btcDynamicMaxPct))
      ? Number(payload.btcDynamicMaxPct)
      : null,
    btcDynamicBeta: Number.isFinite(Number(payload.btcDynamicBeta))
      ? Number(payload.btcDynamicBeta)
      : null,
    btcDynamicRiskPct: Number.isFinite(Number(payload.btcDynamicRiskPct))
      ? Number(payload.btcDynamicRiskPct)
      : null,
    btcDynamicRr: Number.isFinite(Number(payload.btcDynamicRr))
      ? Number(payload.btcDynamicRr)
      : null,
    btcDynamicUpdatedAt: payload.btcDynamicEntry ? new Date().toISOString() : null,
  };
  store.trades.unshift(trade);
  await writeShakeoutPaperStore(store);
  console.log(`[ShakeoutPaper] ${status} ${side} ${symbol} entry=${entryPrice} score=${trade.score ?? '-'} trap=${trade.trapRisk ?? 'LOW'} src=${trade.source}`);
  syncShakeoutPaperTicker().catch(() => {});
  scheduleShakeoutPaperBroadcast(50);
  return { trade: enrichShakeoutPaperTrade(trade, getShakeoutPaperMark(symbol)) };
}

async function closeShakeoutPaperTrade(payload) {
  const store = await readShakeoutPaperStore();
  const idx = store.trades.findIndex((t) => t.id === payload.id);
  if (idx < 0) throw new Error('Shakeout paper trade not found');
  const trade = store.trades[idx];
  if (trade.status === 'CLOSED') return { trade: enrichShakeoutPaperTrade(trade, trade.exitPrice) };
  const exitPrice = payload.exitPrice
    ? Number(payload.exitPrice)
    : getShakeoutPaperMark(trade.symbol);
  if (!Number.isFinite(exitPrice) || exitPrice <= 0) {
    throw new Error(`Chưa có tick socket mới cho ${trade.symbol}; không thể đóng bằng giá cache/entry`);
  }
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = Number(trade.realizedPnl ?? 0)
    + (exitPrice - trade.entryPrice) * trade.quantity * sideMult;
  const roe = trade.marginUsdt > 0 ? (pnl / trade.marginUsdt) * 100 : 0;
  const feeRate = getShakeoutPaperFeeRate();
  const feeUsdt = estimateShakeoutPaperFeeUsdt(trade, exitPrice) ?? 0;
  const netPnl = pnl - feeUsdt;
  const netRoe = trade.marginUsdt > 0 ? (netPnl / trade.marginUsdt) * 100 : 0;
  const outcome = payload.outcome ?? 'MANUAL';
  store.trades[idx] = {
    ...trade,
    status: 'CLOSED',
    exitPrice,
    pnl,
    roe,
    grossPnl: pnl,
    feeRate,
    feeUsdt,
    netPnl,
    netRoe,
    outcome,
    closeReason: payload.closeReason ? String(payload.closeReason).slice(0, 500) : trade.closeReason,
    note: payload.closeReason
      ? [String(trade.note ?? ''), `closeReason=${payload.closeReason}`].filter(Boolean).join(' | ').slice(0, 500)
      : trade.note,
    closedAt: new Date().toISOString(),
  };
  await writeShakeoutPaperStore(store);
  syncShakeoutPaperTicker().catch(() => {});
  scheduleShakeoutPaperBroadcast(50);
  return { trade: enrichShakeoutPaperTrade(store.trades[idx], exitPrice) };
}

async function deleteShakeoutPaperTrade(payload) {
  const store = await readShakeoutPaperStore();
  store.trades = store.trades.filter((t) => t.id !== payload.id);
  await writeShakeoutPaperStore(store);
  syncShakeoutPaperTicker().catch(() => {});
  scheduleShakeoutPaperBroadcast(50);
  return { ok: true };
}

async function fillShakeoutPendingTrade(trade, markPrice) {
  if (shakeoutPaperFillLocks.has(trade.id)) return;
  shakeoutPaperFillLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'PENDING');
    if (idx < 0) return;
    const row = store.trades[idx];
    const limit = Number(row.entryPrice);
    const side = row.side;
    const touched = side === 'LONG' ? markPrice <= limit : markPrice >= limit;
    if (!touched) return;
    // Giá khớp thực tế: limit đã marketable (giá vượt qua) thì khớp ở giá market, không bao giờ tệ hơn market
    const fill = side === 'LONG' ? Math.min(limit, markPrice) : Math.max(limit, markPrice);
    const filledAt = new Date().toISOString();
    const rawBtcHealth = await getBtcHealth().catch(() => btcHealthCache.data);
    const entryContext = getShakeoutBtcEntrySnapshot(rawBtcHealth, Date.now());
    const chopChaseMarginCapUsdt = Math.max(
      0.01,
      Number(process.env.SHAKEOUT_RECLAIM_CHASE_CHOP_MARGIN_CAP_USDT ?? 1),
    );
    let margin = capShakeoutChopChaseMargin({
      variant: row.variant,
      btcMarketRegimeAtEntry: entryContext.btcMarketRegimeAtEntry,
      marginUsdt: row.marginUsdt,
      capUsdt: chopChaseMarginCapUsdt,
    });
    const pendingShadowMarginCapUsdt = Math.max(
      0.01,
      Number(process.env.SHAKEOUT_RECLAIM_PENDING_SHADOW_MARGIN_CAP_USDT ?? 1),
    );
    margin = capShakeoutPendingShadowMargin({
      variant: row.variant,
      marginUsdt: margin,
      capUsdt: pendingShadowMarginCapUsdt,
    });
    const symbolCandleAtEntry = cachedCandlePatternAt(row.symbol, '5m', filledAt) ?? null;
    const btcCandleAtEntry = cachedCandlePatternAt('BTCUSDT', '5m', filledAt) ?? null;
    const fillBtcHealthSnapshot = buildBtcHealthSnapshot(rawBtcHealth) ?? {};
    const fillSideCandleGate = evaluateShakeoutSideCandle({
      side,
      btcHealth: fillBtcHealthSnapshot,
      btcCandle: btcCandleAtEntry,
    });
    const activeSignalVariants = row.signalId
      ? store.trades.filter((candidate) =>
          candidate.id !== row.id
          && candidate.signalId === row.signalId
          && ['OPEN', 'PENDING'].includes(candidate.status))
      : [];
    const stage2RollingDrift = shakeoutRollingDriftStats(store.trades, {
      ...row,
      openedAt: filledAt,
    });
    const stage2Evaluation = evaluateShakeoutStage2({
      layer1Tier: fillSideCandleGate.tier,
      setup: row.shakeoutClass ?? row.subtype ?? row.signalType,
      shakeoutCombo: row.shakeoutCombo,
      signalType: row.signalType,
      subtype: row.subtype,
      variant: row.variant,
      side,
      signalAt: row.signalAt ?? row.scannedAt ?? row.createdAt,
      fillAt: filledAt,
      signalBtcMarketRegime: row.btcMarketRegimeAtSignal
        ?? row.btcMarketRegimeAtEntry
        ?? row.btcRegimeAtEntry,
      entryBtcMarketRegime: entryContext.btcMarketRegimeAtEntry,
      signalBtcCandle: row.btcCandleAtSignal
        ?? row.btcCandleAtEntry
        ?? row.btcCandlePatternAtEntry
        ?? row.btcCandlePattern5m,
      entryBtcCandle: btcCandleAtEntry,
      duplicateActiveCount: activeSignalVariants.length,
      duplicateActiveMarginUsdt: activeSignalVariants.reduce(
        (sum, candidate) => sum + Number(candidate.marginUsdt ?? 0),
        0,
      ),
      rollingDrift: stage2RollingDrift,
    });
    const lev = Number(row.leverage);
    const qty = fill > 0 ? (margin * lev) / fill : row.quantity;
    const dynamicRiskPct = Math.max(0.001, Number(row.btcDynamicRiskPct ?? 0.03));
    const dynamicRr = Math.max(0.1, Number(row.btcDynamicRr ?? 2.2));
    const fillSlRoe = getShakeoutPaperSlRoeForTrade(row);
    const realGateFillSl = getShakeoutSlPriceByRoe(fill, lev, side, fillSlRoe);
    const filledSl = Number.isFinite(realGateFillSl) && realGateFillSl > 0
        ? realGateFillSl
        : row.sl;
    const rawFilledTp = row.btcDynamicEntry
      ? (side === 'LONG'
        ? fill * (1 + dynamicRiskPct * dynamicRr)
        : fill * (1 - dynamicRiskPct * dynamicRr))
      : row.tp;
    const fillTpCap = capShakeoutTpByMaxRoe({
      entryPrice: fill,
      tp: rawFilledTp,
      side,
      leverage: lev,
    });
    const filledTp = fillTpCap.tp;
    const fillObservationRiskPct = Number.isFinite(filledSl) && filledSl > 0
      ? Math.abs(filledSl - fill) / fill * 100
      : null;
    const fillObservationRewardPct = Number.isFinite(filledTp) && filledTp > 0
      ? Math.abs(filledTp - fill) / fill * 100
      : null;
    const fillObservation = evaluateShakeoutObservation({
      ...row,
      openedAt: filledAt,
      shakeoutObservationCapturedAt: filledAt,
      entryPrice: fill,
      btcHealth: fillBtcHealthSnapshot,
      btcPhase: pumpBtcPhaseBucket(fillBtcHealthSnapshot),
      btcMarketRegimeAtEntry: entryContext.btcMarketRegimeAtEntry,
      symbolCandleAtEntry,
      btcCandleAtEntry,
      shakeoutObservationRiskPct: fillObservationRiskPct,
      shakeoutObservationRewardPct: fillObservationRewardPct,
      shakeoutObservationRr: fillObservationRiskPct > 0 && fillObservationRewardPct != null
        ? fillObservationRewardPct / fillObservationRiskPct
        : null,
    });
    const entryContextNote = `BTC_ENTRY_CONTEXT=4h:${entryContext.btcTrendDir4hAtEntry ?? '-'}:${entryContext.btcTrendScore4hAtEntry ?? '-'} flip5m=${entryContext.btc5mFlipRateAtEntry ?? '-'} (${entryContext.btc5mFlipCountAtEntry}/${entryContext.btc5mFlipTransitionsAtEntry}) regime=${entryContext.btcMarketRegimeAtEntry ?? '-'}`;
    const chopShadowNote = isShakeoutChopChase({
      variant: row.variant,
      btcMarketRegimeAtEntry: entryContext.btcMarketRegimeAtEntry,
    }) ? `CHASE_CHOP_SHADOW=margin_cap_$${chopChaseMarginCapUsdt}` : '';
    store.trades[idx] = {
      ...row,
      status: 'OPEN',
      marginUsdt: margin,
      entryPrice: fill,
      fillPrice: fill,
      quantity: qty,
      originalQuantity: qty,
      sl: filledSl,
      tp: filledTp,
      realizedPnl: Number(row.realizedPnl ?? 0),
      openedAt: filledAt,
      symbolCandleAtEntry: symbolCandleAtEntry && typeof symbolCandleAtEntry === 'object'
        ? symbolCandleAtEntry
        : null,
      candlePatternAtEntry: symbolCandleAtEntry && typeof symbolCandleAtEntry === 'object'
        ? symbolCandleAtEntry
        : row.candlePatternAtEntry,
      btcCandleAtEntry: btcCandleAtEntry && typeof btcCandleAtEntry === 'object'
        ? btcCandleAtEntry
        : null,
      btcCandlePatternAtEntry: btcCandleAtEntry && typeof btcCandleAtEntry === 'object'
        ? btcCandleAtEntry
        : row.btcCandlePatternAtEntry,
      ruleVersion: fillSideCandleGate.version,
      regimeAtEntry: fillSideCandleGate.regime,
      shakeoutSideCandleTier: fillSideCandleGate.tier,
      shakeoutSideCandleLabel: fillSideCandleGate.label,
      shakeoutSideCandleReason: fillSideCandleGate.reason,
      shakeoutSideCandleMarginCapUsdt: fillSideCandleGate.marginCapUsdt,
      btcMarketRegimeAtEntry: entryContext.btcMarketRegimeAtEntry,
      btcTrendDir4hAtEntry: entryContext.btcTrendDir4hAtEntry,
      btcTrendScore4hAtEntry: entryContext.btcTrendScore4hAtEntry,
      btcPct24hAtEntry: entryContext.btcPct24hAtEntry,
      btc5mFlipRateAtEntry: entryContext.btc5mFlipRateAtEntry,
      btc5mFlipCountAtEntry: entryContext.btc5mFlipCountAtEntry,
      btc5mFlipTransitionsAtEntry: entryContext.btc5mFlipTransitionsAtEntry,
      btc5mFlipSamplesAtEntry: entryContext.btc5mFlipSamplesAtEntry,
      btc5mFlipWindowAtEntry: entryContext.btc5mFlipWindowAtEntry,
      btcContextCapturedAt: entryContext.capturedAt,
      shakeoutStage2Version: stage2Evaluation.version,
      shakeoutStage2Tier: stage2Evaluation.tier,
      shakeoutStage2Label: stage2Evaluation.label,
      shakeoutStage2Code: stage2Evaluation.code,
      shakeoutStage2Modifier: stage2Evaluation.modifier,
      shakeoutStage2Layer1Tier: stage2Evaluation.layer1Tier,
      shakeoutStage2Setup: stage2Evaluation.setup,
      shakeoutStage2Variant: stage2Evaluation.variant,
      shakeoutStage2FillQuality: stage2Evaluation.fillQuality,
      shakeoutStage2AuditOnlyFlags: true,
      shakeoutStage2AuditCaptured: true,
      shakeoutStage2Derived: false,
      shakeoutStage2Flags: stage2Evaluation.flags,
      shakeoutStage2Reason: stage2Evaluation.reason,
      shakeoutStage2EvaluatedAt: stage2Evaluation.evaluatedAt,
      shakeoutStage2FillDelayMinutes: stage2Evaluation.fillDelayMinutes,
      shakeoutStage2DuplicateActiveCount: stage2Evaluation.duplicateActiveCount,
      shakeoutStage2DuplicateActiveMarginUsdt: stage2Evaluation.duplicateActiveMarginUsdt,
      shakeoutStage2RollingDrift: stage2Evaluation.rollingDrift,
      shakeoutObservationSignalSnapshot: row.shakeoutObservationSignalSnapshot
        ?? row.shakeoutObservationSnapshot
        ?? null,
      ...fillObservation,
      shakeoutObservationDerived: false,
      pendingShadowMarginCapUsdt,
      chaseChopShadow: isShakeoutChopChase({
        variant: row.variant,
        btcMarketRegimeAtEntry: entryContext.btcMarketRegimeAtEntry,
      }),
      btcDynamicLocked: row.btcDynamicEntry ? true : row.btcDynamicLocked,
      noStopLoss: false,
      note: row.btcDynamicEntry
        ? [
            `btcDynamicFilled=${fill} sl=${filledSl} hardSlRoe=${fillSlRoe}% tp=${filledTp}`,
            fillTpCap.capped ? `maxTP=${fillTpCap.maxRoe}%ROE oldTP=${rawFilledTp} newTP=${filledTp}` : '',
            entryContextNote,
            chopShadowNote,
            `SHAKEOUT_STAGE_2=${stage2Evaluation.tier}:${stage2Evaluation.label}; ${stage2Evaluation.reason}`,
            String(row.note ?? ''),
          ]
          .filter(Boolean).join(' | ').slice(0, 900)
        : [
            String(row.note ?? ''),
            entryContextNote,
            chopShadowNote,
            `SHAKEOUT_STAGE_2=${stage2Evaluation.tier}:${stage2Evaluation.label}; ${stage2Evaluation.reason}`,
            Number.isFinite(realGateFillSl) && realGateFillSl > 0
              ? `fillSL=${fillSlRoe}%ROE@${filledSl}`
              : '',
          ].filter(Boolean).join(' | ').slice(0, 900),
    };
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    console.log(`[ShakeoutPaper] FILLED ${side} ${row.symbol} limit=${limit} fill=${fill} mark=${markPrice}`);
  } finally {
    shakeoutPaperFillLocks.delete(trade.id);
  }
}

const shakeoutPaperTpSlLocks = new Set();
const shakeoutPaperPartialLocks = new Set();
const shakeoutPaperDcaLocks = new Set();

function isShakeoutBottomReboundTrade(trade) {
  return Boolean(trade?.bottomRebound)
    || String(trade?.subtype ?? '').toUpperCase() === 'BOTTOM_REBOUND';
}

function notePercentValue(note, label) {
  const escaped = String(label).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = String(note ?? '').match(new RegExp(`${escaped}=([\\d.]+)%`, 'i'));
  const value = match ? Number(match[1]) : null;
  return Number.isFinite(value) ? value : null;
}

function getShakeoutBottomReboundPaperPolicy(sig = {}, trapRisk = 'LOW') {
  const note = String(sig.note ?? sig.reason ?? '');
  const trapReasons = Array.isArray(sig.riskFlags?.trapReasons) ? sig.riskFlags.trapReasons : [];
  const hasWarning = trapReasons.length > 0 || Boolean(sig.warning);
  const pump15m = notePercentValue(note, '15m pump');
  const declinePct = notePercentValue(note, 'bottomRebound decline');
  const reboundPct = notePercentValue(note, 'rebound');
  const hardPump15m = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_MAX_15M_PUMP ?? 100);
  const scoutPump15m = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_SCOUT_15M_PUMP ?? 80);
  const deepWeakMinDecline = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_NO_DCA_MIN_DECLINE ?? 40);
  const deepWeakMaxRebound = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_NO_DCA_MAX_REBOUND ?? 20);
  const deepWeakMaxScore = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_NO_DCA_MAX_SCORE ?? 60);
  const risk = String(trapRisk ?? 'LOW').toUpperCase();
  const reasons = [];
  const labels = [];

  if (Number.isFinite(pump15m) && pump15m >= hardPump15m) {
    reasons.push(`15m pump ${pump15m.toFixed(1)}% >= ${hardPump15m}%`);
    labels.push('NO_DCA_HARD_PUMP');
    return {
      skip: true,
      scoutOnly: false,
      noStopLoss: false,
      dcaAllowed: false,
      marginUsdt: 0,
      pump15m,
      declinePct,
      reboundPct,
      dcaLabel: labels.join(','),
      reasons,
    };
  }

  if (['MEDIUM', 'HIGH'].includes(risk)) reasons.push(`trapRisk=${risk}`);
  if (hasWarning) reasons.push('warning');
  if (Number.isFinite(pump15m) && pump15m >= scoutPump15m) {
    reasons.push(`15m pump ${pump15m.toFixed(1)}% >= ${scoutPump15m}%`);
  }
  if (Number.isFinite(declinePct)
      && Number.isFinite(reboundPct)
      && Number(sig.score) <= deepWeakMaxScore
      && declinePct >= deepWeakMinDecline
      && reboundPct < deepWeakMaxRebound) {
    labels.push('NO_DCA_DEEP_WEAK_REBOUND');
    reasons.push(
      `deepWeakRebound decline ${declinePct.toFixed(1)}% >= ${deepWeakMinDecline}%`
      + ` rebound ${reboundPct.toFixed(1)}% < ${deepWeakMaxRebound}%`
      + ` score ${Number(sig.score)} <= ${deepWeakMaxScore}`,
    );
  }

  const scoutOnly = reasons.length > 0;
  if (!labels.length) labels.push(scoutOnly ? 'NO_DCA_RISK' : 'DCA_OK');
  return {
    skip: false,
    scoutOnly,
    noStopLoss: !scoutOnly,
    dcaAllowed: !scoutOnly,
    marginUsdt: scoutOnly
        ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_SCOUT_MARGIN_USDT ?? 1)
        : Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_MARGIN_USDT ?? 5),
    pump15m,
    declinePct,
    reboundPct,
    dcaLabel: labels.join(','),
    reasons,
  };
}

async function checkShakeoutBottomReboundDca(trade, markPrice) {
  if (!isShakeoutBottomReboundTrade(trade) || trade.status !== 'OPEN' || trade.dcaTaken) return trade;
  if (trade.bottomReboundDcaAllowed === false || trade.dcaBlocked || !trade.noStopLoss) return trade;
  const risk = String(trade.trapRisk ?? '').toUpperCase();
  if (['MEDIUM', 'HIGH'].includes(risk) || String(trade.warning ?? '').trim()) return trade;
  if (shakeoutPaperDcaLocks.has(trade.id)) return trade;

  const entry = Number(trade.entryPrice);
  const quantity = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const leverage = Math.max(1, Number(trade.leverage) || 1);
  const mark = Number(markPrice);
  if (![entry, quantity, margin, mark].every(Number.isFinite)
      || entry <= 0 || quantity <= 0 || margin <= 0 || mark <= 0) return trade;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = Number(trade.realizedPnl ?? 0) + (mark - entry) * quantity * sideMult;
  const roe = pnl / margin * 100;
  const triggerRoe = -Math.abs(
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_DCA_ROE ?? 25),
  );
  if (roe > triggerRoe) return trade;

  const dcaMargin = Math.max(
    0.01,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_DCA_MARGIN_USDT ?? 10),
  );
  shakeoutPaperDcaLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((t) =>
      t.id === trade.id && t.status === 'OPEN' && !t.dcaTaken);
    if (idx < 0) return trade;

    const row = store.trades[idx];
    const oldQty = Number(row.quantity);
    const oldMargin = Number(row.marginUsdt);
    const oldEntry = Number(row.entryPrice);
    const rowLeverage = Math.max(1, Number(row.leverage) || 1);
    const addQty = dcaMargin * rowLeverage / mark;
    const totalQty = oldQty + addQty;
    const totalMargin = oldMargin + dcaMargin;
    const averageEntry = totalQty > 0
      ? (oldEntry * oldQty + mark * addQty) / totalQty
      : oldEntry;
    const dcaAt = new Date().toISOString();

    store.trades[idx] = {
      ...row,
      entryPrice: averageEntry,
      quantity: totalQty,
      originalQuantity: totalQty,
      marginUsdt: totalMargin,
      sl: null,
      dcaTaken: true,
      dcaAt,
      dcaPrice: mark,
      dcaMarginUsdt: dcaMargin,
      dcaTriggerRoe: triggerRoe,
      entryBeforeDca: oldEntry,
      marginBeforeDca: oldMargin,
      note: [
        String(row.note ?? ''),
        `bottomReboundDca=${dcaMargin}USDT@${mark}`,
        `triggerRoe=${roe.toFixed(1)}%`,
        `avgEntry=${averageEntry}`,
        'noSL=Y',
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    console.log(
      `[ShakeoutPaper] BOTTOM_REBOUND_DCA ${row.side} ${row.symbol}`
      + ` add=$${dcaMargin} roe=${roe.toFixed(1)}% mark=${mark}`
      + ` entry=${oldEntry}->${averageEntry} margin=${oldMargin}->${totalMargin}`,
    );
    return store.trades[idx];
  } finally {
    shakeoutPaperDcaLocks.delete(trade.id);
  }
}

async function checkShakeoutPaperPartialTp(trade, markPrice) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_PARTIAL_TP_ENABLED === 'false') return trade;
  if (trade.status !== 'OPEN' || trade.partialTpTaken || trade.recoveryMode) return trade;
  if (isShakeoutBottomReboundTrade(trade)) return trade;
  if (shakeoutPaperPartialLocks.has(trade.id)) return trade;

  const entry = Number(trade.entryPrice);
  const target = Number(trade.tp);
  const leverage = Math.max(1, Number(trade.leverage) || 1);
  const quantity = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  if (![entry, target, quantity, margin].every(Number.isFinite)
      || entry <= 0 || target <= 0 || quantity <= 0 || margin <= 0) return trade;

  const minTargetRoe = Math.max(
    0,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_PARTIAL_MIN_TARGET_ROE ?? 40),
  );
  const triggerRoe = Math.max(
    0,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_PARTIAL_TRIGGER_ROE ?? 30),
  );
  const closeRatio = Math.min(
    0.95,
    Math.max(0.01, Number(process.env.SHAKEOUT_RECLAIM_PAPER_PARTIAL_CLOSE_RATIO ?? 0.30)),
  );
  const targetRoe = Math.abs(target - entry) / entry * leverage * 100;
  if (targetRoe < minTargetRoe) return trade;

  const isLong = trade.side === 'LONG';
  const triggerMove = triggerRoe / 100 / leverage;
  const triggerPrice = isLong
    ? entry * (1 + triggerMove)
    : entry * (1 - triggerMove);
  const triggerHit = isLong ? markPrice >= triggerPrice : markPrice <= triggerPrice;
  if (!triggerHit) return trade;

  shakeoutPaperPartialLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((t) =>
      t.id === trade.id && t.status === 'OPEN' && !t.partialTpTaken);
    if (idx < 0) return trade;
    const row = store.trades[idx];
    const rowQty = Number(row.quantity);
    if (!Number.isFinite(rowQty) || rowQty <= 0) return trade;

    const closeQty = rowQty * closeRatio;
    const remainingQty = rowQty - closeQty;
    const sideMult = row.side === 'LONG' ? 1 : -1;
    const realizedAdd = (triggerPrice - entry) * closeQty * sideMult;
    const realizedPnl = Number(row.realizedPnl ?? 0) + realizedAdd;
    const partialAt = new Date().toISOString();
    store.trades[idx] = {
      ...row,
      originalQuantity: Number(row.originalQuantity ?? rowQty),
      quantity: remainingQty,
      realizedPnl,
      partialTpTaken: true,
      partialTpAt: partialAt,
      partialTpPrice: triggerPrice,
      partialTpRoe: triggerRoe,
      partialCloseRatio: closeRatio,
      runnerRatio: 1 - closeRatio,
      runnerOriginalTp: Number(row.tp),
      sl: entry,
      slTrailLockRoe: 0,
      dynamicRiskUpdatedAt: partialAt,
      note: [
        String(row.note ?? ''),
        `partialTp=${(closeRatio * 100).toFixed(0)}%@${triggerRoe}%`,
        `runner=${((1 - closeRatio) * 100).toFixed(0)}%`,
        `runnerSl=entry@${entry}`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    console.log(
      `[ShakeoutPaper] PARTIAL_TP ${row.side} ${row.symbol}`
      + ` close=${(closeRatio * 100).toFixed(0)}% roe=${triggerRoe}%`
      + ` realized=${realizedAdd.toFixed(4)} runner=${remainingQty}`,
    );
    return store.trades[idx];
  } finally {
    shakeoutPaperPartialLocks.delete(trade.id);
  }
}

function getShakeoutPaperRecoverySetup(trade) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_RECOVERY_ENABLED === 'false') return null;
  if (trade.recoveryMode || trade.status !== 'OPEN') return null;

  const note = String(trade.note ?? '');
  const emaDistance = Number(note.match(/emaDist=([\d.]+)%/i)?.[1]);
  const confirmation = Number(note.match(/(?:reclaim|reject)=([\d.]+)%/i)?.[1]);
  const maxEmaDistance = Math.max(
    0,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_RECOVERY_MAX_EMA_DISTANCE_PCT ?? 1),
  );
  const minConfirmation = Math.max(
    0,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_RECOVERY_MIN_CONFIRM_PCT ?? 5),
  );
  if (!Number.isFinite(emaDistance) || emaDistance > maxEmaDistance) return null;
  if (!Number.isFinite(confirmation) || confirmation < minConfirmation) return null;

  const entry = Number(trade.entryPrice);
  const currentSl = Number(trade.sl);
  const leverage = Math.max(1, Number(trade.leverage) || 1);
  const hardSlRoe = Math.max(
    1,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_RECOVERY_HARD_SL_ROE ?? 30),
  );
  if (!Number.isFinite(entry) || entry <= 0 || !Number.isFinite(currentSl) || currentSl <= 0) return null;

  // Recovery is only for an original losing SL, never for a profit-lock/trailing SL.
  const isLosingSl = trade.side === 'LONG' ? currentSl < entry : currentSl > entry;
  if (!isLosingSl) return null;

  const hardSlMove = hardSlRoe / 100 / leverage;
  const hardSl = trade.side === 'LONG'
    ? entry * (1 - hardSlMove)
    : entry * (1 + hardSlMove);
  if (!Number.isFinite(hardSl) || hardSl <= 0) return null;
  return {
    emaDistance,
    confirmation,
    hardSlRoe,
    hardSl,
    recoveryTp: entry,
  };
}

async function activateShakeoutPaperRecovery(trade, setup, markPrice) {
  const store = await readShakeoutPaperStore();
  const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'OPEN' && !t.recoveryMode);
  if (idx < 0) return null;

  const row = store.trades[idx];
  const activatedAt = new Date().toISOString();
  const recoveryNote = [
    `shakeoutRecovery=ACTIVE`,
    `triggerSl=${row.sl}`,
    `tpEntry=${setup.recoveryTp}`,
    `hardSl=${setup.hardSl}`,
    `hardSlRoe=-${setup.hardSlRoe}%`,
    `emaDist=${setup.emaDistance}%`,
    `confirm=${setup.confirmation}%`,
  ].join(' ');
  store.trades[idx] = {
    ...row,
    recoveryMode: true,
    recoveryTriggeredAt: activatedAt,
    recoveryOriginalSl: Number(row.sl),
    recoveryOriginalTp: Number(row.tp),
    recoveryTriggerMark: Number(markPrice),
    recoveryHardSlRoe: -setup.hardSlRoe,
    sl: setup.hardSl,
    tp: setup.recoveryTp,
    note: [String(row.note ?? ''), recoveryNote].filter(Boolean).join(' | ').slice(0, 500),
  };
  await writeShakeoutPaperStore(store);
  scheduleShakeoutPaperBroadcast(50);
  console.log(
    `[ShakeoutPaper] RECOVERY_ACTIVE ${row.side} ${row.symbol}`
    + ` oldSl=${row.sl} tpEntry=${setup.recoveryTp} hardSl=${setup.hardSl}`,
  );
  return store.trades[idx];
}

async function checkShakeoutPaperTpSl(trade, markPrice) {
  if (!trade.tp && !trade.sl) return false;
  if (shakeoutPaperTpSlLocks.has(trade.id)) return false;
  const isLong = trade.side === 'LONG';
  const tpHit = trade.tp != null && (isLong ? markPrice >= trade.tp : markPrice <= trade.tp);
  const slHit = trade.sl != null && (isLong ? markPrice <= trade.sl : markPrice >= trade.sl);
  if (!tpHit && !slHit) return false;
  shakeoutPaperTpSlLocks.add(trade.id);
  try {
    if (slHit && !trade.recoveryMode) {
      const recoverySetup = getShakeoutPaperRecoverySetup(trade);
      if (recoverySetup) {
        const recoveryTrade = await activateShakeoutPaperRecovery(trade, recoverySetup, markPrice);
        if (!recoveryTrade) return false;

        const hardSlHit = isLong
          ? markPrice <= recoverySetup.hardSl
          : markPrice >= recoverySetup.hardSl;
        if (!hardSlHit) return true;
        await closeShakeoutPaperTrade({
          id: trade.id,
          exitPrice: recoverySetup.hardSl,
          outcome: 'RECOVERY_SL30',
        });
        console.log(
          `[ShakeoutPaper] RECOVERY_SL30 ${trade.side} ${trade.symbol}`
          + ` exit=${recoverySetup.hardSl}`,
        );
        return true;
      }
    }

    const partialSlAtEntry = trade.partialTpTaken
      && Math.abs(Number(trade.sl) - Number(trade.entryPrice))
        / Math.max(Number(trade.entryPrice), 1e-9) < 0.0001;
    const outcome = trade.lossTpMovedToEntry && tpHit
      ? 'LOSS_RECOVERY_BE'
      : trade.recoveryMode
      ? (tpHit ? 'RECOVERY_BE' : 'RECOVERY_SL30')
      : trade.partialTpTaken
        ? (tpHit ? 'RUNNER_TP' : partialSlAtEntry ? 'PARTIAL_BE' : 'PARTIAL_TRAIL')
        : slHit && trade.slTrailMode === 'CHASE_CHOP_FEE_BREAK_EVEN'
          ? 'CHASE_CHOP_FEE_BE'
        : slHit && Number(trade.slTrailLockRoe ?? 0) > 0
          ? 'SL_TRAIL_LOCK'
        : (tpHit ? 'TP' : 'SL');
    const exitPrice = tpHit ? trade.tp : trade.sl;
    await closeShakeoutPaperTrade({ id: trade.id, exitPrice, outcome });
    console.log(`[ShakeoutPaper] ${outcome} hit ${trade.side} ${trade.symbol} exit=${exitPrice}`);
    return true;
  } finally {
    shakeoutPaperTpSlLocks.delete(trade.id);
  }
}

const shakeoutPaperSlTrailLocks = new Set();
const shakeoutPaperLossRecoveryLocks = new Set();

async function checkShakeoutPaperLossRecovery(trade, markPrice) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_LOSS_TP_ENTRY_ENABLED === 'false') return trade;
  if (trade.status !== 'OPEN' || trade.lossTpMovedToEntry) return trade;
  if (shakeoutPaperLossRecoveryLocks.has(trade.id)) return trade;

  const entry = Number(trade.entryPrice);
  const quantity = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const mark = Number(markPrice);
  if (![entry, quantity, margin, mark].every(Number.isFinite)
      || entry <= 0 || quantity <= 0 || margin <= 0 || mark <= 0) return trade;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = Number(trade.realizedPnl ?? 0) + (mark - entry) * quantity * sideMult;
  const roe = pnl / margin * 100;
  const triggerRoe = -Math.abs(
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_LOSS_TP_ENTRY_ROE ?? 15),
  );
  if (roe > triggerRoe) return trade;

  shakeoutPaperLossRecoveryLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((row) =>
      row.id === trade.id && row.status === 'OPEN' && !row.lossTpMovedToEntry);
    if (idx < 0) return trade;
    const row = store.trades[idx];
    store.trades[idx] = {
      ...row,
      lossTpMovedToEntry: true,
      lossTpTriggerRoe: triggerRoe,
      lossTpTriggerMark: mark,
      lossTpOriginalTp: Number(row.tp),
      lossTpMovedAt: new Date().toISOString(),
      tp: entry,
      note: [
        String(row.note ?? ''),
        `lossTpToEntry=${triggerRoe}%@mark=${mark}`,
        `oldTp=${row.tp}`,
        `newTp=${entry}`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    console.log(
      `[ShakeoutPaper] LOSS_TP_TO_ENTRY ${row.side} ${row.symbol}`
      + ` roe=${roe.toFixed(1)}% mark=${mark} tp=${row.tp}->${entry}`,
    );
    return store.trades[idx];
  } finally {
    shakeoutPaperLossRecoveryLocks.delete(trade.id);
  }
}

async function checkShakeoutPaperSlTrail(trade, markPrice) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_SL_TRAIL_ENABLED === 'false') return;
  if (trade.status !== 'OPEN' || trade.outcome === 'INVALID') return;
  if (isShakeoutBottomReboundTrade(trade)) return;
  if (shakeoutPaperSlTrailLocks.has(trade.id)) return;

  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const entry = Number(trade.entryPrice);
  const qty = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const mark = Number(markPrice);
  if (!Number.isFinite(entry) || entry <= 0 || !Number.isFinite(qty) || qty <= 0) return;
  if (!Number.isFinite(margin) || margin <= 0 || !Number.isFinite(mark) || mark <= 0) return;

  const realizedPnl = Number(trade.realizedPnl ?? 0);
  const pnl = realizedPnl + (mark - entry) * qty * sideMult;
  const roe = (pnl / margin) * 100;
  const prevPeak = shakeoutPaperPeakRoe.get(trade.id) ?? Number(trade.peakRoe ?? 0) ?? 0;
  const peakRoe = Math.max(prevPeak, roe);
  shakeoutPaperPeakRoe.set(trade.id, peakRoe);

  const isChaseTrade = String(trade.variant ?? '').toUpperCase() === 'CHASE';
  const isChopChaseShadow = isShakeoutChopChase({
    variant: trade.variant,
    btcMarketRegimeAtEntry: trade.btcMarketRegimeAtEntry,
  });
  const chopBreakEvenTriggerRoe = Math.max(
    0.1,
    Number(process.env.SHAKEOUT_RECLAIM_CHASE_CHOP_BE_TRIGGER_ROE ?? 7),
  );
  const chopFeeBreakEvenActive = isChopChaseShadow && peakRoe >= chopBreakEvenTriggerRoe;
  const trailStartRoe = Number(isChaseTrade
    ? (process.env.SHAKEOUT_RECLAIM_CHASE_TRAIL_START_ROE ?? 20)
    : (process.env.SHAKEOUT_RECLAIM_PAPER_TRAIL_START_ROE ?? 15));
  const getTradeTargetLockRoe = (currentPeakRoe) => {
    if (!isChaseTrade) return getTargetLockRoe(currentPeakRoe);
    if (currentPeakRoe < trailStartRoe) return null;
    const firstLockRoe = Number(process.env.SHAKEOUT_RECLAIM_CHASE_TRAIL_FIRST_LOCK_ROE ?? 5);
    const stepRoe = Math.max(1, Number(process.env.SHAKEOUT_RECLAIM_CHASE_TRAIL_STEP_ROE ?? 5));
    return firstLockRoe + Math.floor((currentPeakRoe - trailStartRoe) / stepRoe) * stepRoe;
  };
  const targetLockRoe = chopFeeBreakEvenActive
    ? 0
    : trade.partialTpTaken
    ? (peakRoe >= trailStartRoe ? getTradeTargetLockRoe(peakRoe) : 0)
    : (peakRoe >= trailStartRoe ? getTradeTargetLockRoe(peakRoe) : null);

  const leverage = Math.max(1, Number(trade.leverage) || 1);
  const isLong = trade.side === 'LONG';
  let newSl = null;
  let improves = false;
  let crossedLock = false;
  if (targetLockRoe != null) {
    if (chopFeeBreakEvenActive && realizedPnl === 0) {
      newSl = shakeoutFeeBreakEvenPrice({
        entryPrice: entry,
        side: trade.side,
        feeRate: getShakeoutPaperFeeRate(),
      });
    } else {
      const targetTotalPnl = margin * targetLockRoe / 100;
      const runnerPnlNeeded = targetTotalPnl - realizedPnl;
      const priceMove = runnerPnlNeeded / qty;
      newSl = isLong ? entry + priceMove : entry - priceMove;
    }
    if (Number.isFinite(newSl) && newSl > 0) {
      const curSl = Number(trade.sl ?? 0);
      improves = !Number.isFinite(curSl) || curSl <= 0
        || (isLong ? newSl > curSl : newSl < curSl);
      crossedLock = improves && (isLong ? newSl >= mark : newSl <= mark);
    }
  }

  const shouldPersistPeak = peakRoe > Number(trade.peakRoe ?? 0) + 0.05;
  if (!shouldPersistPeak && (!improves || !Number.isFinite(newSl) || newSl <= 0)) return;

  shakeoutPaperSlTrailLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && t.status === 'OPEN');
    if (idx < 0) return;
    const row = store.trades[idx];
    const notes = [];
    if (targetLockRoe != null && improves && Number.isFinite(newSl) && newSl > 0) {
      notes.push(chopFeeBreakEvenActive
        ? `shakeoutChaseChopFeeBE=peak>=${chopBreakEvenTriggerRoe}%@${newSl}`
        : trade.partialTpTaken
        ? `shakeoutRunnerSlTrail=${targetLockRoe}%@${newSl}`
        : `shakeoutPaperSlTrail=${targetLockRoe}%@${newSl}`);
    }
    if (shouldPersistPeak && (targetLockRoe == null || !improves)) {
      notes.push(`shakeoutPaperPeak=${peakRoe.toFixed(1)}%`);
    }
    store.trades[idx] = {
      ...row,
      ...(targetLockRoe != null && improves && !crossedLock ? { sl: newSl } : {}),
      peakRoe,
      ...(targetLockRoe != null ? { slTrailLockRoe: targetLockRoe } : {}),
      ...(chopFeeBreakEvenActive ? {
        slTrailMode: 'CHASE_CHOP_FEE_BREAK_EVEN',
        chaseChopBreakEvenTriggeredAt: row.chaseChopBreakEvenTriggeredAt ?? new Date().toISOString(),
        chaseChopBreakEvenTriggerRoe: chopBreakEvenTriggerRoe,
        chaseChopBreakEvenPrice: newSl,
      } : {}),
      dynamicRiskUpdatedAt: new Date().toISOString(),
      note: [String(row.note ?? ''), ...notes].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    if (crossedLock) {
      const exitPrice = mark;
      await closeShakeoutPaperTrade({
        id: trade.id,
        exitPrice,
        outcome: chopFeeBreakEvenActive
          ? 'CHASE_CHOP_FEE_BE'
          : trade.partialTpTaken ? 'PARTIAL_TRAIL' : 'SL',
      });
      console.log(`[ShakeoutPaper] SL_LOCK_HIT ${row.side} ${row.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% lock=${targetLockRoe}% exit=${exitPrice}`);
    } else if (targetLockRoe != null && improves && Number.isFinite(newSl) && newSl > 0) {
      console.log(`[ShakeoutPaper] SL_TRAIL ${row.side} ${row.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% lock=${targetLockRoe}% sl=${newSl}`);
    }
  } finally {
    shakeoutPaperSlTrailLocks.delete(trade.id);
  }
}

const shakeoutPaperDefaultSlLocks = new Set();
async function enforceShakeoutPaperDefaultSl(trade) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_FORCE_DEFAULT_SL === 'false') return trade;
  if (!['OPEN', 'PENDING'].includes(String(trade.status))) return trade;
  if (trade.slTrailLockRoe != null) return trade;
  if (shakeoutPaperDefaultSlLocks.has(trade.id)) return trade;
  const slRoe = getShakeoutPaperSlRoeForTrade(trade);
  const sl = getShakeoutSlPriceByRoe(trade.entryPrice, trade.leverage, trade.side, slRoe);
  if (!Number.isFinite(sl) || sl <= 0) return trade;
  const curSl = Number(trade.sl);
  const needsUpdate = !Number.isFinite(curSl)
    || Math.abs(curSl - sl) / sl > 1e-10
    || trade.noStopLoss !== false;
  if (!needsUpdate) return trade;

  shakeoutPaperDefaultSlLocks.add(trade.id);
  try {
    const store = await readShakeoutPaperStore();
    const idx = store.trades.findIndex((t) => t.id === trade.id && ['OPEN', 'PENDING'].includes(t.status));
    if (idx < 0) return trade;
    const row = store.trades[idx];
    store.trades[idx] = {
      ...row,
      sl,
      noStopLoss: false,
      dynamicRiskUpdatedAt: new Date().toISOString(),
      note: [String(row.note ?? ''), `forceDefaultSL=${slRoe}%ROE@${sl}`]
        .filter(Boolean)
        .join(' | ')
        .slice(0, 500),
    };
    await writeShakeoutPaperStore(store);
    return store.trades[idx];
  } finally {
    shakeoutPaperDefaultSlLocks.delete(trade.id);
  }
}

async function processShakeoutPaperFills(symbol, markPrice) {
  let store = await readShakeoutPaperStore();
  const cancelPendingRoe = -Math.abs(
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_CANCEL_PENDING_MARKET_ROE ?? 10),
  );
  let cancelled = 0;
  for (const pendingTrade of store.trades.filter((t) =>
    t.status === 'PENDING' && t.symbol === symbol && t.signalId)) {
    if (pendingTrade.btcDynamicEntry) continue;
    const marketTrade = store.trades.find((t) =>
      t.signalId === pendingTrade.signalId
      && t.variant === 'MARKET'
      && ['OPEN', 'CLOSED'].includes(t.status));
    if (!marketTrade) continue;
    let marketRoe;
    if (marketTrade.status === 'CLOSED' && Number.isFinite(Number(marketTrade.roe))) {
      marketRoe = Number(marketTrade.roe);
    } else {
      const entry = Number(marketTrade.entryPrice);
      const qty = Number(marketTrade.quantity);
      const margin = Number(marketTrade.marginUsdt);
      if (![entry, qty, margin].every(Number.isFinite) || entry <= 0 || qty <= 0 || margin <= 0) continue;
      const sideMult = marketTrade.side === 'LONG' ? 1 : -1;
      const marketPnl = Number(marketTrade.realizedPnl ?? 0)
        + (markPrice - entry) * qty * sideMult;
      marketRoe = marketPnl / margin * 100;
    }
    if (marketRoe > cancelPendingRoe) continue;

    const idx = store.trades.findIndex((t) => t.id === pendingTrade.id && t.status === 'PENDING');
    if (idx < 0) continue;
    store.trades[idx] = {
      ...store.trades[idx],
      status: 'CANCELLED',
      outcome: 'CANCELLED_MARKET_LOSS',
      cancelledAt: new Date().toISOString(),
      cancelledByTradeId: marketTrade.id,
      cancelledMarketRoe: marketRoe,
      cancelledMarketStatus: marketTrade.status,
      note: [
        String(store.trades[idx].note ?? ''),
        `pendingCancelled marketRoe=${marketRoe.toFixed(1)}% <= ${cancelPendingRoe.toFixed(1)}%`,
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    cancelled++;
    console.log(
      `[ShakeoutPaper] CANCEL_PENDING ${pendingTrade.side} ${symbol}`
      + ` marketRoe=${marketRoe.toFixed(1)}% threshold=${cancelPendingRoe.toFixed(1)}%`,
    );
  }
  if (cancelled) {
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    syncShakeoutPaperTicker().catch(() => {});
    store = await readShakeoutPaperStore();
  }

  const pending = store.trades.filter((t) => t.status === 'PENDING' && t.symbol === symbol);
  for (const t of pending) await fillShakeoutPendingTrade(t, markPrice);
  const open = store.trades.filter((t) => t.status === 'OPEN' && t.symbol === symbol);
  for (const t of open) {
    const hardSlTrade = await enforceShakeoutPaperDefaultSl(t);
    if (await checkShakeoutPaperTpSl(hardSlTrade, markPrice)) continue;
    if (await checkShakeoutBtcDynamicFailFast(hardSlTrade, markPrice)) continue;
    const dcaTrade = await checkShakeoutBottomReboundDca(hardSlTrade, markPrice);
    const recoveryTrade = await checkShakeoutPaperLossRecovery(dcaTrade, markPrice);
    const current = await checkShakeoutPaperPartialTp(recoveryTrade, markPrice);
    await checkShakeoutPaperSlTrail(current, markPrice);
    const defaultSlTrade = await enforceShakeoutPaperDefaultSl(current);
    await checkShakeoutPaperTpSl(defaultSlTrade, markPrice);
  }
  scheduleShakeoutPaperBroadcast();
}

function queueShakeoutPaperProcessing(symbol, markPrice) {
  shakeoutPaperPendingProcess.set(symbol, markPrice);
  if (shakeoutPaperProcessTimer || shakeoutPaperProcessRunning) return;
  shakeoutPaperProcessTimer = setTimeout(drainShakeoutPaperProcessing, 250);
}

async function drainShakeoutPaperProcessing() {
  shakeoutPaperProcessTimer = null;
  if (shakeoutPaperProcessRunning) return;
  const next = shakeoutPaperPendingProcess.entries().next();
  if (next.done) return;
  const [symbol, markPrice] = next.value;
  shakeoutPaperPendingProcess.delete(symbol);
  shakeoutPaperProcessRunning = true;
  try {
    if (Number.isFinite(Number(markPrice)) && Number(markPrice) > 0) {
      await processShakeoutPaperFills(symbol, Number(markPrice));
    }
  } catch {} finally {
    shakeoutPaperProcessRunning = false;
    if (shakeoutPaperPendingProcess.size > 0 && !shakeoutPaperProcessTimer) {
      shakeoutPaperProcessTimer = setTimeout(drainShakeoutPaperProcessing, 250);
    }
  }
}

async function syncShakeoutPaperTicker() {
  if (!shakeoutPaperTicker) return;
  const store = await readShakeoutPaperStore();
  const symbols = [...new Set(store.trades.filter((t) => ['PENDING', 'OPEN'].includes(t.status)).map((t) => t.symbol))];
  shakeoutPaperTicker.setSymbols(symbols);
}

// Xóa lệnh PENDING quá TTL (mặc định 4h) chưa khớp
function shakeoutBtcTrendSupportsSide(side, regime) {
  const normalizedSide = String(side ?? '').toUpperCase();
  const normalizedRegime = String(regime ?? 'FLAT').toUpperCase();
  return (normalizedSide === 'LONG' && normalizedRegime === 'STRONG')
    || (normalizedSide === 'SHORT' && normalizedRegime === 'WEAK');
}

function calcShakeoutPaperRoeAt(trade, markPrice) {
  const entry = Number(trade?.entryPrice);
  const quantity = Number(trade?.quantity);
  const margin = Number(trade?.marginUsdt);
  const mark = Number(markPrice);
  if (![entry, quantity, margin, mark].every(Number.isFinite)
      || entry <= 0 || quantity <= 0 || margin <= 0 || mark <= 0) return null;
  const sideMult = trade.side === 'LONG' ? 1 : -1;
  const pnl = Number(trade.realizedPnl ?? 0) + (mark - entry) * quantity * sideMult;
  return pnl / margin * 100;
}

async function checkShakeoutBtcDynamicFailFast(trade, markPrice) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_FAIL_FAST === 'false') return false;
  if (trade?.status !== 'OPEN') return false;
  const note = String(trade.note ?? '');
  const isDynamicLocked = Boolean(trade.btcDynamicLocked)
    || /btcDynamicFilled=/i.test(note)
    || (trade.btcDynamicEntry && trade.openedAt);
  if (!isDynamicLocked) return false;

  const mark = Number(markPrice);
  const roe = calcShakeoutPaperRoeAt(trade, mark);
  if (!Number.isFinite(roe)) return false;

  const side = String(trade.side ?? '').toUpperCase();
  const roeCut = side === 'SHORT'
    ? -Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_FAIL_FAST_SHORT_ROE ?? 20))
    : -Math.abs(Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_FAIL_FAST_LONG_ROE ?? 30));
  const timeMs = Math.max(
    60_000,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_FAIL_FAST_TIME_MS ?? 30 * 60_000),
  );
  const minPeakRoe = Math.max(
    0,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_FAIL_FAST_MIN_PEAK_ROE ?? 5),
  );
  const openedAt = Date.parse(trade.openedAt ?? trade.createdAt ?? '');
  const ageMs = Number.isFinite(openedAt) ? Date.now() - openedAt : 0;
  const prevPeak = shakeoutPaperPeakRoe.get(trade.id) ?? Number(trade.peakRoe ?? 0) ?? 0;
  const peakRoe = Math.max(prevPeak, roe);
  shakeoutPaperPeakRoe.set(trade.id, peakRoe);

  let outcome = null;
  let closeReason = null;
  if (roe <= roeCut) {
    outcome = 'BTC_DYNAMIC_FAIL_FAST_ROE';
    closeReason = `BTC dynamic locked fail-fast: roe=${roe.toFixed(1)}% <= ${roeCut}% side=${side}`;
  } else if (ageMs >= timeMs && peakRoe < minPeakRoe) {
    outcome = 'BTC_DYNAMIC_FAIL_FAST_TIME';
    closeReason = `BTC dynamic locked fail-fast: age=${Math.round(ageMs / 60_000)}m >= ${Math.round(timeMs / 60_000)}m and peakRoe=${peakRoe.toFixed(1)}% < ${minPeakRoe}%`;
  }
  if (!outcome) return false;

  await closeShakeoutPaperTrade({
    id: trade.id,
    exitPrice: mark,
    outcome,
    closeReason,
  });
  console.log(`[ShakeoutPaper] ${outcome} ${side} ${trade.symbol} roe=${roe.toFixed(1)}% peak=${peakRoe.toFixed(1)}% mark=${mark}`);
  return true;
}

function shakeoutNoteNumber(note, regex) {
  const m = String(note ?? '').match(regex);
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isFinite(n) ? n : null;
}

function getShakeoutBottomFlushShortRisk(input = {}) {
  const note = String(input.note ?? input.reason ?? '');
  const side = String(input.side ?? input.action ?? '').toUpperCase();
  if (side !== 'SHORT') return { block: false, reason: '' };
  const dump5 = shakeoutNoteNumber(note, /5m dump=([0-9.]+)%/i);
  const dump15 = shakeoutNoteNumber(note, /15m dump=([0-9.]+)%/i);
  const bounce = shakeoutNoteNumber(note, /bounce=([0-9.]+)%/i);
  const reject = shakeoutNoteNumber(note, /reject=([0-9.]+)%/i);
  const trapRisk = String(input.trapRisk ?? input.riskFlags?.trapRisk ?? '').toUpperCase()
    || (note.match(/trapRisk=(HIGH|MEDIUM|LOW)/i)?.[1] ?? '').toUpperCase();
  const deepDump = Number(dump5) >= 30 || Number(dump15) >= 20;
  const reboundTooLarge = Number(bounce) >= 20;
  const trapWarn = ['MEDIUM', 'HIGH'].includes(trapRisk);
  const rejectLarge = Number(reject) >= 10;
  const block = deepDump && reboundTooLarge && (trapWarn || rejectLarge);
  return {
    block,
    reason: block
      ? `bottomFlushShortRisk dump5=${dump5 ?? '-'} dump15=${dump15 ?? '-'} bounce=${bounce ?? '-'} reject=${reject ?? '-'} trap=${trapRisk || '-'}`
      : '',
  };
}

function getShakeoutWeakRejectShortSqueezeRisk(input = {}) {
  const note = String(input.note ?? input.reason ?? '');
  const side = String(input.side ?? input.action ?? '').toUpperCase();
  if (side !== 'SHORT') return { block: false, reason: '' };
  const trapRisk = String(input.trapRisk ?? input.riskFlags?.trapRisk ?? '').toUpperCase()
    || (note.match(/trapRisk=(HIGH|MEDIUM|LOW)/i)?.[1] ?? '').toUpperCase();
  const score = Number(input.score ?? 0);
  const factors = input.factors ?? {};
  const bounce = Number.isFinite(Number(factors.drop5mPct))
    ? Number(factors.drop5mPct)
    : shakeoutNoteNumber(note, /bounce=([0-9.]+)%/i);
  const reject = Number.isFinite(Number(factors.reclaimPct))
    ? Number(factors.reclaimPct)
    : shakeoutNoteNumber(note, /reject=([0-9.]+)%/i);
  const maxScore = Number(process.env.SHAKEOUT_REJECT_SHORT_SQUEEZE_RISK_MAX_SCORE ?? 55);
  const minBounce = Number(process.env.SHAKEOUT_REJECT_SHORT_SQUEEZE_RISK_MIN_BOUNCE ?? 8);
  const maxReject = Number(process.env.SHAKEOUT_REJECT_SHORT_SQUEEZE_RISK_MAX_REJECT ?? 5);
  const block = process.env.SHAKEOUT_REJECT_SHORT_SQUEEZE_RISK_GATE !== 'false'
    && score <= maxScore
    && ['MEDIUM', 'HIGH'].includes(trapRisk)
    && Number(bounce) >= minBounce
    && Number(reject) < maxReject;
  return {
    block,
    reason: block
      ? `weakRejectShortSqueezeRisk score=${score} bounce=${Number(bounce).toFixed(1)}>=${minBounce} reject=${Number(reject).toFixed(1)}<${maxReject} trap=${trapRisk}`
      : '',
  };
}

function getShakeoutBtcDirectionalBias(health = btcHealthCache.data) {
  if (!health || health.error) return { bias: 'FLAT', reason: 'btc health unavailable' };
  const explicit = String(health.btcTrendDir ?? '').toLowerCase();
  if (explicit === 'up') {
    return { bias: 'LONG', reason: `btcTrendDir=up score=${health.btcTrendScore ?? '-'}` };
  }
  if (explicit === 'down') {
    return { bias: 'SHORT', reason: `btcTrendDir=down score=${health.btcTrendScore ?? '-'}` };
  }

  const pct6h = Number(health.pct6h);
  const candle1h = Number(health.btcCandle1hPct);
  const rsi1h = Number(health.rsi1h);
  const ema1h = String(health.emaTrend1h ?? '').toLowerCase();
  const longScore = [
    Number.isFinite(pct6h) && pct6h >= 0.25,
    Number.isFinite(candle1h) && candle1h >= 0.2,
    ema1h === 'above',
    Number.isFinite(rsi1h) && rsi1h >= 50,
  ].filter(Boolean).length;
  const shortScore = [
    Number.isFinite(pct6h) && pct6h <= -0.25,
    Number.isFinite(candle1h) && candle1h <= -0.2,
    ema1h === 'below',
    Number.isFinite(rsi1h) && rsi1h <= 48,
  ].filter(Boolean).length;
  const reason = `pct6h=${Number.isFinite(pct6h) ? pct6h : '-'} candle1h=${Number.isFinite(candle1h) ? candle1h : '-'} ema1h=${ema1h || '-'} rsi1h=${Number.isFinite(rsi1h) ? rsi1h : '-'}`;
  if (longScore >= 2 && longScore > shortScore) return { bias: 'LONG', reason };
  if (shortScore >= 2 && shortScore > longScore) return { bias: 'SHORT', reason };
  return { bias: 'FLAT', reason };
}

function getShakeoutHybridStructuralBlock(sig = {}, side, trapRisk, btcBias = getShakeoutBtcDirectionalBias()) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_HYBRID_BTC_GATE === 'false') {
    return { block: false, reasons: [], btcBias };
  }
  const note = String(sig.note ?? sig.reason ?? '');
  const className = String(sig.shakeoutClass ?? '').toUpperCase();
  const classReason = String(sig.shakeoutClassReason ?? '');
  const normalizedSide = String(side ?? sig.action ?? '').toUpperCase();
  const risk = String(trapRisk ?? sig.riskFlags?.trapRisk ?? '').toUpperCase();
  const reject = shakeoutNoteNumber(note, /reject=([0-9.]+)%/i);
  const bounce = shakeoutNoteNumber(note, /bounce=([0-9.]+)%/i);
  const reasons = [];

  if (normalizedSide === 'LONG'
      && className === 'WEAK_RECLAIM'
      && classReason.includes('BTC weak vs long')
      && btcBias.bias === 'SHORT') {
    reasons.push(`BTC_BIAS_SHORT blocks LONG_WEAK_BTC_WEAK (${btcBias.reason})`);
  }
  if (normalizedSide === 'LONG' && className === 'FALSE_RECLAIM' && risk === 'HIGH') {
    reasons.push('LONG_FALSE_RECLAIM_TRAP_HIGH');
  }
  if (normalizedSide === 'SHORT'
      && className === 'FALSE_RECLAIM'
      && Number.isFinite(reject)
      && Number.isFinite(bounce)
      && reject < Number(process.env.SHAKEOUT_RECLAIM_PAPER_SHORT_FALSE_MAX_REJECT ?? 10)
      && bounce >= Number(process.env.SHAKEOUT_RECLAIM_PAPER_SHORT_FALSE_MIN_BOUNCE ?? 20)) {
    reasons.push(`SHORT_FALSE_RECLAIM_WEAK_REJECT_BIG_BOUNCE reject=${reject.toFixed(1)} bounce=${bounce.toFixed(1)}`);
  }
  return { block: reasons.length > 0, reasons, btcBias };
}

function getShakeoutProjectedRoe(input = {}) {
  const side = String(input.side ?? input.action ?? '').toUpperCase();
  const entry = Number(input.entryPrice ?? input.entry ?? input.markPrice);
  const tp = Number(input.tp);
  const sl = Number(input.sl);
  const leverage = Number(input.leverage) || calcAutoLeverage(entry, sl);
  if (!['LONG', 'SHORT'].includes(side) || !Number.isFinite(entry) || entry <= 0
      || !Number.isFinite(tp) || tp <= 0 || !Number.isFinite(leverage) || leverage <= 0) return null;
  return Math.abs(tp - entry) / entry * leverage * 100;
}

function getShakeoutRealGate(input = {}, opts = {}) {
  const side = String(input.side ?? input.action ?? '').toUpperCase();
  const score = Number(input.score ?? 0);
  const cls = String(input.shakeoutClass ?? '').toUpperCase();
  const reason = String(input.shakeoutClassReason ?? '');
  const trap = String(input.trapRisk ?? input.riskFlags?.trapRisk ?? '').toUpperCase() || 'LOW';
  const projectedRoe = Number(opts.projectedRoe ?? input.projectedRoe ?? getShakeoutProjectedRoe(input));
  const btcBias = opts.btcBias ?? getShakeoutBtcDirectionalBias();
  const reasons = [];
  const warns = [];

  if (trap === 'HIGH') reasons.push('trap HIGH');
  if (side === 'LONG' && btcBias.bias === 'SHORT') reasons.push(`BTC bias SHORT (${btcBias.reason})`);
  if (side === 'SHORT' && btcBias.bias === 'LONG') reasons.push(`BTC bias LONG (${btcBias.reason})`);
  if (side === 'LONG' && cls === 'WEAK_RECLAIM' && reason.includes('BTC weak vs long')) reasons.push('WEAK_RECLAIM + BTC weak vs long');
  if (side === 'SHORT' && cls === 'WEAK_REJECT' && reason.includes('BTC strong vs short')) reasons.push('WEAK_REJECT + BTC strong vs short');
  if (cls === 'FALSE_RECLAIM' || cls === 'FALSE_REJECT') warns.push(cls.replace('_', ' '));
  if (trap === 'MEDIUM') warns.push('trap MEDIUM');
  if (score < Number(process.env.SHAKEOUT_REAL_OK_MIN_SCORE ?? 75)) warns.push(`score ${score}<75`);
  if (Number.isFinite(projectedRoe) && projectedRoe < Number(process.env.SHAKEOUT_REAL_OK_MIN_TP_ROE ?? 10)) {
    warns.push(`projectedRoe ${projectedRoe.toFixed(1)}%<10%`);
  }

  if (reasons.length) {
    return { label: 'REAL_BLOCK', allowReal: false, color: 'red', reasons, projectedRoe: Number.isFinite(projectedRoe) ? +projectedRoe.toFixed(1) : null };
  }
  if (warns.length) {
    return { label: 'REAL_TEST', allowReal: true, color: 'amber', reasons: warns, projectedRoe: Number.isFinite(projectedRoe) ? +projectedRoe.toFixed(1) : null };
  }
  return {
    label: 'REAL_OK',
    allowReal: true,
    color: 'green',
    reasons: [`score=${score}`, `trap=${trap}`, `btc=${btcBias.bias}`, Number.isFinite(projectedRoe) ? `tpRoe=${projectedRoe.toFixed(1)}%` : 'tpRoe=?'],
    projectedRoe: Number.isFinite(projectedRoe) ? +projectedRoe.toFixed(1) : null,
  };
}

async function updateShakeoutDynamicBtcEntries() {
  const health = await getBtcHealth();
  const btcPrice = Number(health?.price);
  if (!Number.isFinite(btcPrice) || btcPrice <= 0) return;

  const btcRegime = emaSqueezeBtcRegime(health);
  const store = await readShakeoutPaperStore();
  const now = Date.now();
  const ttlMs = Math.max(
    60_000,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_TTL_MS ?? 60 * 60_000),
  );
  let changed = 0;

  for (let i = 0; i < store.trades.length; i++) {
    const row = store.trades[i];
    if (row.status !== 'PENDING' || !row.btcDynamicEntry || row.btcDynamicLocked) continue;

    const createdAt = Date.parse(row.createdAt ?? 0);
    if (Number.isFinite(createdAt) && now - createdAt >= ttlMs) {
      store.trades[i] = {
        ...row,
        status: 'EXPIRED',
        outcome: 'EXPIRED_BTC_DYNAMIC_60M',
        expiredAt: new Date().toISOString(),
        note: [
          `btcDynamicExpired>${Math.round(ttlMs / 60_000)}m`,
          String(row.note ?? ''),
        ].filter(Boolean).join(' | ').slice(0, 500),
      };
      changed++;
      continue;
    }

    if (shakeoutBtcTrendSupportsSide(row.side, btcRegime)) {
      const mark = getShakeoutPaperMark(row.symbol);
      const scout = store.trades.find((t) =>
        t.signalId === row.signalId
        && t.variant === 'MARKET'
        && String(t.source ?? '').includes('-scout-')
        && ['OPEN', 'CLOSED'].includes(t.status));
      const scoutRoe = scout
        ? (scout.status === 'CLOSED' && Number.isFinite(Number(scout.roe))
          ? Number(scout.roe)
          : calcShakeoutPaperRoeAt(scout, mark))
        : null;
      const risk = getShakeoutBottomFlushShortRisk(row);
      const scoutNote = String(scout?.note ?? '');
      const scoutRecovery = Boolean(scout?.lossTpMovedToEntry)
        || /lossTpToEntry/i.test(scoutNote)
        || /shakeoutRecovery=ACTIVE/i.test(scoutNote);
      const scoutDeepLoss = Number.isFinite(scoutRoe) && scoutRoe <= -15;
      if (risk.block || scoutRecovery || scoutDeepLoss) {
        store.trades[i] = {
          ...row,
          status: 'EXPIRED',
          outcome: risk.block
            ? 'EXPIRED_BOTTOM_FLUSH_SHORT_RISK'
            : scoutRecovery ? 'EXPIRED_SCOUT_RECOVERY_ACTIVE' : 'EXPIRED_SCOUT_DEEP_LOSS',
          expiredAt: new Date().toISOString(),
          btcDynamicLocked: true,
          btcLastPrice: btcPrice,
          btcRegime,
          btcDynamicUpdatedAt: new Date().toISOString(),
          note: [
            risk.block ? `btcDynamicBlocked=${risk.reason}` : '',
            scoutRecovery ? 'btcDynamicBlocked=scoutRecoveryActive' : '',
            scoutDeepLoss ? `btcDynamicBlocked=scoutRoe=${scoutRoe.toFixed(1)}%` : '',
            String(row.note ?? ''),
          ].filter(Boolean).join(' | ').slice(0, 500),
        };
        changed++;
        continue;
      }
      const minScoutRoe = Number(
        process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_MARKET_SCOUT_MIN_ROE ?? 5,
      );
      const maxChaseRoe = Number(
        process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_MARKET_MAX_CHASE_ROE ?? 35,
      );
      const entry = Number(row.entryPrice);
      const leverage = Math.max(1, Number(row.leverage) || 1);
      const chaseRoe = Number.isFinite(mark) && mark > 0 && Number.isFinite(entry) && entry > 0
        ? Math.abs(mark - entry) / entry * leverage * 100
        : Infinity;
      if (Number.isFinite(mark) && mark > 0
          && Number.isFinite(scoutRoe) && scoutRoe >= minScoutRoe
          && Number.isFinite(chaseRoe) && chaseRoe <= maxChaseRoe) {
        const riskPct = Math.max(0.001, Number(row.btcDynamicRiskPct ?? 0.03));
        const rr = Math.max(0.1, Number(row.btcDynamicRr ?? 2.2));
        const nextTp = row.side === 'LONG'
          ? mark * (1 + riskPct * rr)
          : mark * (1 - riskPct * rr);
        store.trades[i] = {
          ...row,
          status: 'OPEN',
          entryPrice: mark,
          fillPrice: mark,
          quantity: Number(row.marginUsdt) * leverage / mark,
          originalQuantity: Number(row.marginUsdt) * leverage / mark,
          sl: null,
          tp: nextTp,
          openedAt: new Date().toISOString(),
          btcDynamicLocked: true,
          btcLastPrice: btcPrice,
          btcRegime,
          btcDynamicUpdatedAt: new Date().toISOString(),
          note: [
            `btcDynamicMarketAdd=${mark} sl=OFF scoutRoe=${scoutRoe.toFixed(1)}% chase=${chaseRoe.toFixed(1)}% btc=${btcRegime}`,
            String(row.note ?? ''),
          ].filter(Boolean).join(' | ').slice(0, 500),
        };
        changed++;
        continue;
      }
      store.trades[i] = {
        ...row,
        btcDynamicLocked: false,
        btcLastPrice: btcPrice,
        btcRegime,
        btcDynamicUpdatedAt: new Date().toISOString(),
        note: [
          `btcDynamicGuard=${btcRegime}@${btcPrice}; wait scout/pullback`
            + (Number.isFinite(scoutRoe) ? ` scoutRoe=${scoutRoe.toFixed(1)}%` : ' noScoutRoe')
            + (Number.isFinite(chaseRoe) ? ` chase=${chaseRoe.toFixed(1)}%` : ''),
          String(row.note ?? ''),
        ].filter(Boolean).join(' | ').slice(0, 500),
      };
      changed++;
      continue;
    }

    const anchor = Number(row.btcAnchorPrice);
    const baseEntry = Number(row.btcDynamicBaseEntry ?? row.entryPrice);
    const beta = Math.max(
      0.25,
      Math.min(5, Math.abs(Number(row.btcDynamicBeta ?? row.btcRelation?.beta ?? 1))),
    );
    const maxMovePct = Math.max(0, Number(row.btcDynamicMaxPct ?? 0));
    const riskPct = Math.max(0.001, Number(row.btcDynamicRiskPct ?? 0.03));
    const rr = Math.max(0.1, Number(row.btcDynamicRr ?? 2.2));
    if (![anchor, baseEntry].every(Number.isFinite) || anchor <= 0 || baseEntry <= 0) continue;

    const btcMove = btcPrice / anchor - 1;
    const adverseMove = row.side === 'LONG'
      ? Math.min(0, btcMove * beta)
      : Math.max(0, btcMove * beta);
    const cappedMove = Math.max(-maxMovePct / 100, Math.min(maxMovePct / 100, adverseMove));
    const nextEntry = baseEntry * (1 + cappedMove);
    const nextSl = row.side === 'LONG'
      ? nextEntry * (1 - riskPct)
      : nextEntry * (1 + riskPct);
    const nextTp = row.side === 'LONG'
      ? nextEntry * (1 + riskPct * rr)
      : nextEntry * (1 - riskPct * rr);
    if (![nextEntry, nextSl, nextTp].every(Number.isFinite)
        || nextEntry <= 0 || nextSl <= 0 || nextTp <= 0) continue;

    const oldEntry = Number(row.entryPrice);
    if (Math.abs(nextEntry - oldEntry) / oldEntry < 0.0005
        && Number(row.btcLastPrice) === btcPrice) continue;

    const leverage = Math.max(1, Number(row.leverage) || 1);
    store.trades[i] = {
      ...row,
      entryPrice: nextEntry,
      quantity: Number(row.marginUsdt) * leverage / nextEntry,
      originalQuantity: Number(row.marginUsdt) * leverage / nextEntry,
      sl: nextSl,
      tp: nextTp,
      btcLastPrice: btcPrice,
      btcRegime,
      btcDynamicUpdatedAt: new Date().toISOString(),
      note: [
        `btcDynamic=${oldEntry}->${nextEntry} btc=${btcPrice} move=${(btcMove * 100).toFixed(2)}% beta=${beta.toFixed(2)}`,
        String(row.note ?? ''),
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    changed++;
  }

  if (changed) {
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    syncShakeoutPaperTicker().catch(() => {});
  }
}

async function expireOldShakeoutPending() {
  const ttlMs = Number(process.env.SHAKEOUT_RECLAIM_PAPER_PENDING_TTL_MS ?? 4 * 3600 * 1000);
  const store = await readShakeoutPaperStore();
  const now = Date.now();
  let changed = 0;
  for (let i = 0; i < store.trades.length; i++) {
    let t = store.trades[i];
    if (t.status === 'PENDING' && t.entryDistancePct == null) {
      const mark = getShakeoutPaperMark(t.symbol);
      const entry = Number(t.entryPrice);
      const maxDistancePct = Math.max(
        0,
        Number(process.env.SHAKEOUT_RECLAIM_PENDING_MAX_DISTANCE_PCT ?? 5),
      );
      const distancePct = Number.isFinite(mark) && mark > 0 && Number.isFinite(entry) && entry > 0
        ? Math.abs(entry - mark) / mark * 100
        : 0;
      if (maxDistancePct > 0 && distancePct > maxDistancePct) {
        const newEntry = mark + Math.sign(entry - mark) * mark * maxDistancePct / 100;
        const tp = Number(t.tp);
        const geometryOk = t.side === 'LONG' ? newEntry < tp : newEntry > tp;
        if (!geometryOk) {
          store.trades[i] = {
            ...t,
            status: 'EXPIRED',
            outcome: 'EXPIRED',
            expiredAt: new Date().toISOString(),
            note: [String(t.note ?? ''), 'pendingExpired=target-crossed-after-clamp']
              .filter(Boolean).join(' | ').slice(0, 500),
          };
          changed++;
          continue;
        }
        const leverage = Math.max(1, Number(t.leverage) || 1);
        const oldSl = Number(t.sl);
        const slRoe = Number.isFinite(oldSl) && oldSl > 0
          ? Math.abs(entry - oldSl) / entry * leverage * 100
          : 20;
        const slMove = slRoe / 100 / leverage;
        const newSl = t.side === 'LONG'
          ? newEntry * (1 - slMove)
          : newEntry * (1 + slMove);
        store.trades[i] = {
          ...t,
          entryPrice: newEntry,
          quantity: (Number(t.marginUsdt) * leverage) / newEntry,
          sl: newSl,
          entryReference: mark,
          entryRaw: entry,
          entryDistancePct: maxDistancePct,
          entryRawDistancePct: distancePct,
          entryWasClamped: true,
          note: [
            String(t.note ?? ''),
            `legacyEntryClamped=${entry}->${newEntry} maxDistance=${maxDistancePct.toFixed(1)}%`,
          ].filter(Boolean).join(' | ').slice(0, 500),
        };
        t = store.trades[i];
        changed++;
      }
    }
    const effectiveTtlMs = t.btcDynamicEntry
      ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_TTL_MS ?? 60 * 60_000)
      : ttlMs;
    if (t.status === 'PENDING' && (now - (Date.parse(t.createdAt ?? 0) || now)) > effectiveTtlMs) {
      console.log(`[ShakeoutPaper] EXPIRE pending ${t.side} ${t.symbol} ${t.variant ?? ''} - >${(ttlMs / 3600000).toFixed(0)}h chưa khớp, xóa lệnh`);
      store.trades[i] = {
        ...t,
        status: 'EXPIRED',
        outcome: 'EXPIRED',
        expiredAt: new Date().toISOString(),
        note: [String(t.note ?? ''), `pendingExpired>${Math.round(effectiveTtlMs / 60_000)}m`]
          .filter(Boolean).join(' | ').slice(0, 500),
      };
      changed++;
    }
  }
  if (changed) {
    await writeShakeoutPaperStore(store);
    scheduleShakeoutPaperBroadcast(50);
    syncShakeoutPaperTicker().catch(() => {});
  }
}

function startShakeoutPaperTicker() {
  if (shakeoutPaperTicker) return;
  shakeoutPaperTicker = sharedLastTicker.createClient(
    'shakeoutPaper',
    ({ symbol, markPrice, eventTime }) => {
      shakeoutSocketMarks.set(symbol, markPrice);
      shakeoutSocketMarkAt.set(symbol, eventTime);
      scheduleShakeoutPaperBroadcast();
      queueShakeoutPaperProcessing(symbol, markPrice);
    },
  );
  console.log('[ShakeoutPaper] Shared last-price ticker consumer started.');
  syncShakeoutPaperTicker().catch(() => {});
  setInterval(() => syncShakeoutPaperTicker().catch(() => {}), 30_000);
  setTimeout(() => expireOldShakeoutPending().catch(() => {}), 3_000);
  setInterval(() => expireOldShakeoutPending().catch(() => {}), 60_000);
  setInterval(() => updateShakeoutDynamicBtcEntries().catch((e) => {
    console.warn('[ShakeoutPaper] BTC dynamic entry update failed:', e.message);
  }), 30_000);
}

function isBetween(value, min, max) {
  const n = Number(value);
  return Number.isFinite(n) && n >= min && n < max;
}

// Phan loai chat luong theo cohort backtest gan nhat. Rule nay chi label + sizing paper,
// khong chan signal, de tiep tuc thu thap thong ke.
function classifyShakeoutPaperQuality(input, sideArg) {
  const sig = input && typeof input === 'object'
    ? input
    : { shakeoutClass: input, side: sideArg, action: sideArg };
  const c = String(sig.shakeoutClass ?? '').toUpperCase();
  const s = String(sig.side ?? sig.action ?? sideArg ?? '').toUpperCase();
  const score = Number(sig.score ?? 0);
  const reason = String(sig.shakeoutClassReason ?? sig.reason ?? '');
  const trap = String(sig.trapRisk ?? sig.riskFlags?.trapRisk ?? '').toUpperCase();
  const f = sig.factors ?? {};
  const move = Number(f.move5mPct ?? 0);
  const move15 = Number(f.move15mPct ?? 0);
  const pull = Number(f.drop5mPct ?? 0);
  const confirm = Number(f.reclaimPct ?? 0);
  const vol5 = Number(f.vol5mX ?? 0);
  const vol15 = Number(f.vol15mX ?? 0);
  const emaDist = Number(f.emaZoneDistPct ?? sig.entryDistancePct ?? 0);
  const projected = Number(sig.shakeoutProjectedRoe ?? sig.projectedRoe ?? 0);
  const btcRegime = String(sig.btcRegime ?? '').toUpperCase();
  const btcDir = String(sig.btcTrendDir ?? sig.btcHealth?.btcTrendDir ?? '').toUpperCase();
  const entryClamped = Boolean(sig.entryWasClamped);
  const realGate = String(sig.shakeoutRealGateLabel ?? '').toUpperCase();
  const good = [];
  const bad = [];

  if (c === 'FALSE_RECLAIM') {
    if (btcRegime === 'FLAT') good.push('FALSE_RECLAIM_FLAT_BTC');
    if (confirm > 0 && confirm < 2) good.push('FALSE_RECLAIM_CONFIRM_UNDER_2');
    if (isBetween(move, 35, 50) || isBetween(move15, 35, 50)) good.push('FALSE_RECLAIM_PUMP_35_50');
    if (entryClamped) good.push('FALSE_RECLAIM_ENTRY_CLAMPED');
    if (btcDir === 'UP' || btcRegime === 'STRONG') bad.push('FALSE_RECLAIM_BTC_UP_STRONG');
    if (projected >= 80) bad.push('FALSE_RECLAIM_PROJECTED_80_PLUS');
    if (move > 0 && move < 20) bad.push('FALSE_RECLAIM_PUMP_UNDER_20');
    if (isBetween(emaDist, 2, 4)) bad.push('FALSE_RECLAIM_EMA_DIST_2_4');
  } else if (c === 'WEAK_RECLAIM') {
    if (vol5 >= 12) good.push('WEAK_RECLAIM_VOL5_12_PLUS');
    if (score >= 55 && score < 60) good.push('WEAK_RECLAIM_SCORE_55_59');
    if (isBetween(emaDist, 2, 4)) good.push('WEAK_RECLAIM_EMA_DIST_2_4');
    if (move > 0 && move < 20) good.push('WEAK_RECLAIM_PUMP_UNDER_20');
    if (score >= 70 && score < 75) bad.push('WEAK_RECLAIM_SCORE_70_74');
    if (btcRegime === 'FLAT') bad.push('WEAK_RECLAIM_FLAT_BTC');
    if (isBetween(emaDist, 0.5, 1)) bad.push('WEAK_RECLAIM_EMA_DIST_0_5_1');
    if (isBetween(vol5, 2, 12)) bad.push('WEAK_RECLAIM_VOL5_2_12');
    if (isBetween(vol15, 8, 12)) bad.push('WEAK_RECLAIM_VOL15_8_12');
  } else if (c === 'WEAK_REJECT') {
    if (score >= 60 && score < 65) good.push('WEAK_REJECT_SCORE_60_64');
    if (isBetween(move, 20, 35) || isBetween(move15, 20, 35)) good.push('WEAK_REJECT_DUMP_20_35');
    if (confirm > 0 && confirm < 2) good.push('WEAK_REJECT_CONFIRM_UNDER_2');
    if (entryClamped) good.push('WEAK_REJECT_ENTRY_CLAMPED');
    if (isBetween(emaDist, 1, 4)) good.push('WEAK_REJECT_EMA_DIST_1_4');
    if (vol15 >= 12) good.push('WEAK_REJECT_VOL15_12_PLUS');
    if (score >= 55 && score < 60) bad.push('WEAK_REJECT_SCORE_55_59');
    if (move > 0 && move < 20) bad.push('WEAK_REJECT_DUMP_UNDER_20');
    if (isBetween(confirm, 2, 5)) bad.push('WEAK_REJECT_CONFIRM_2_5');
    if (realGate === 'REAL_BLOCK') bad.push('WEAK_REJECT_REAL_BLOCK');
    if (emaDist > 0 && emaDist < 0.5) bad.push('WEAK_REJECT_EMA_DIST_UNDER_0_5');
  } else if (c === 'FALSE_REJECT') {
    if (pull > 0 && pull < 8) good.push('FALSE_REJECT_BOUNCE_UNDER_8');
    if (isBetween(move, 35, 50) || isBetween(move15, 35, 50)) good.push('FALSE_REJECT_DUMP_35_50');
    if (isBetween(vol5, 4, 8)) good.push('FALSE_REJECT_VOL5_4_8');
    if (score >= 55 && score < 60) good.push('FALSE_REJECT_SCORE_55_59');
    if (pull >= 15) bad.push('FALSE_REJECT_BOUNCE_15_PLUS');
    if (score >= 60 && score < 70) bad.push('FALSE_REJECT_SCORE_60_69');
    if (projected >= 40) bad.push('FALSE_REJECT_PROJECTED_40_PLUS');
    if (vol15 >= 12) bad.push('FALSE_REJECT_VOL15_12_PLUS');
  } else if (c === 'BOTTOM_REBOUND') {
    if (vol5 >= 12 || vol15 >= 12) good.push('BOTTOM_REBOUND_VOLUME_EXPANDED');
    if (trap === 'LOW') good.push('BOTTOM_REBOUND_TRAP_LOW');
    if (['MEDIUM', 'HIGH'].includes(trap)) bad.push(`BOTTOM_REBOUND_TRAP_${trap}`);
  } else if (c === 'CLEAN_REJECT' || c === 'CLEAN_RECLAIM') {
    bad.push(`${c}_BACKTEST_WEAK`);
  }

  if (reason.includes('BTC weak vs long') || reason.includes('BTC strong vs short')) bad.push('BTC_CONFLICT_REASON');
  if (reason.includes('weak/late') && trap !== 'LOW') bad.push('WEAK_LATE_WITH_TRAP');
  if (trap === 'HIGH') bad.push('TRAP_HIGH');

  const tier = bad.length > good.length
    ? 'BAD'
    : good.length > 0
      ? 'GOOD'
      : 'TEST';
  return {
    tier,
    label: tier === 'GOOD' ? 'GOOD SHAKEOUT' : tier === 'BAD' ? 'LOW QUALITY' : 'TEST / WATCH',
    marginUsdt: tier === 'GOOD'
      ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_GOOD_MARGIN_USDT ?? 10)
      : tier === 'BAD'
        ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_BAD_MARGIN_USDT ?? 1)
        : Number(process.env.SHAKEOUT_RECLAIM_PAPER_TEST_MARGIN_USDT ?? 1),
    reason: [
      good.length ? `good=${good.slice(0, 4).join(',')}` : '',
      bad.length ? `bad=${bad.slice(0, 4).join(',')}` : '',
    ].filter(Boolean).join(' | ') || 'no strong cohort match',
    goodReasons: good,
    badReasons: bad,
  };
}

function getShakeoutChaseCandleTest({ symbol, side, marketEntry, pendingEntry, signalTp, signalSl, now = Date.now() }) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_TEST === 'false') {
    return { active: false };
  }
  const tradeSide = String(side ?? '').toUpperCase();
  const market = Number(marketEntry);
  const pending = Number(pendingEntry);
  if (!['LONG', 'SHORT'].includes(tradeSide)
      || !Number.isFinite(market)
      || !Number.isFinite(pending)
      || market <= 0
      || pending <= 0) {
    return { active: false };
  }
  const movePct = tradeSide === 'LONG'
    ? (market - pending) / pending * 100
    : (pending - market) / pending * 100;
  const minMovePct = Math.max(0, Number(process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_MIN_MOVE_PCT ?? 0.8));
  const maxMovePct = Math.max(minMovePct, Number(process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_MAX_MOVE_PCT ?? 6));
  if (movePct < minMovePct || movePct > maxMovePct) {
    return { active: false, movePct, minMovePct, maxMovePct };
  }
  const target = Number(signalTp);
  const stop = Number(signalSl);
  const hasRoom = tradeSide === 'LONG'
    ? Number.isFinite(target) && target > market
    : Number.isFinite(target) && target < market;
  const stillBeforeStop = tradeSide === 'LONG'
    ? !Number.isFinite(stop) || stop < market
    : !Number.isFinite(stop) || stop > market;
  if (!hasRoom || !stillBeforeStop) {
    return { active: false, movePct, minMovePct, maxMovePct, noRoom: !hasRoom, stopInvalid: !stillBeforeStop };
  }

  const requireClosedCandleConfirmation =
    process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_REQUIRE_CONFIRMATION === 'true';
  if (!requireClosedCandleConfirmation) {
    return {
      active: true,
      movePct,
      minMovePct,
      maxMovePct,
      confirmation: {
        mode: 'RELAXED',
        timeframe: '5m',
        required: false,
      },
    };
  }

  const closed = (klineCache.getIfCached(String(symbol ?? '').toUpperCase(), '5m', 6) ?? [])
    .filter((k) => Number(k?.closeTime ?? 0) <= now)
    .slice(-2);
  if (closed.length < 2) {
    return { active: false, reason: 'NO_CLOSED_5M_DATA', movePct, minMovePct, maxMovePct };
  }
  const previous = closed[0];
  const candle = closed[1];
  const open = Number(candle.open);
  const high = Number(candle.high);
  const low = Number(candle.low);
  const close = Number(candle.close);
  const previousClose = Number(previous.close);
  const range = high - low;
  if (![open, high, low, close, previousClose].every(Number.isFinite) || range <= 0) {
    return { active: false, reason: 'INVALID_CLOSED_5M_DATA', movePct, minMovePct, maxMovePct };
  }
  const minBodyShare = Math.max(
    0,
    Math.min(1, Number(process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_MIN_BODY_SHARE ?? 0.3)),
  );
  const bodyShare = Math.abs(close - open) / range;
  const directionConfirmed = tradeSide === 'LONG' ? close > open : close < open;
  const previousCloseConfirmed = tradeSide === 'LONG' ? close > previousClose : close < previousClose;
  const confirmation = {
    timeframe: '5m',
    closeTime: Number(candle.closeTime),
    open,
    high,
    low,
    close,
    previousClose,
    bodyShare: Number(bodyShare.toFixed(4)),
    minBodyShare,
    directionConfirmed,
    previousCloseConfirmed,
  };
  if (!directionConfirmed) {
    return { active: false, reason: 'CANDLE_DIRECTION_NOT_CONFIRMED', movePct, minMovePct, maxMovePct, confirmation };
  }
  if (bodyShare < minBodyShare) {
    return { active: false, reason: 'CANDLE_BODY_TOO_SMALL', movePct, minMovePct, maxMovePct, confirmation };
  }
  if (!previousCloseConfirmed) {
    return { active: false, reason: 'PREVIOUS_CLOSE_NOT_BROKEN', movePct, minMovePct, maxMovePct, confirmation };
  }
  return { active: true, movePct, minMovePct, maxMovePct, confirmation };
}

function getShakeoutBadChaseGroup({ shakeoutClass, side, score, btcGateLabel, combo }) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_BAD_GROUP_TEST === 'false') {
    return { bad: false, reason: '' };
  }
  const cls = normalizePumpComboPart(shakeoutClass ?? '', '');
  const dir = normalizePumpComboPart(side ?? '', '');
  const gate = normalizePumpComboPart(btcGateLabel ?? '', '');
  const comboText = normalizePumpComboPart(combo ?? '', '');
  const sc = Number(score);
  const inScore = (lo, hi) => Number.isFinite(sc) && sc >= lo && sc <= hi;
  const isClass = (...names) => names.some((name) => cls === name || comboText.includes(name));
  const match = (reason, ok) => (ok ? { bad: true, reason } : null);

  return match(
    'CLEAN_REJECT_SHORT_60_64_SIDEWAY_DOWN',
    dir === 'SHORT'
      && isClass('CLEAN_REJECT')
      && inScore(60, 64)
      && gate === 'GATE_OK_SHAKEOUT_SIDEWAY_DOWN_INDEPENDENT',
  ) || match(
    'FALSE_RECLAIM_LONG_60_64_SIDEWAY_DOWN',
    dir === 'LONG'
      && isClass('FALSE_RECLAIM')
      && inScore(60, 64)
      && gate === 'GATE_OK_SHAKEOUT_SIDEWAY_DOWN_INDEPENDENT',
  ) || match(
    'WEAK_REJECT_SHORT_55_59_SIDEWAY_DOWN',
    dir === 'SHORT'
      && isClass('WEAK_REJECT')
      && inScore(55, 59)
      && gate === 'GATE_OK_SHAKEOUT_SIDEWAY_DOWN_INDEPENDENT',
  ) || match(
    'FALSE_RECLAIM_LONG_60_64_SIDEWAY_UP',
    dir === 'LONG'
      && isClass('FALSE_RECLAIM')
      && inScore(60, 64)
      && gate === 'GATE_OK_SHAKEOUT_SIDEWAY_UP_INDEPENDENT',
  ) || match(
    'WEAK_RECLAIM_LONG_55_59_WEAK_UP',
    dir === 'LONG'
      && isClass('WEAK_RECLAIM')
      && inScore(55, 59)
      && gate === 'GATE_OK_SHAKEOUT_WEAK_UP_INDEPENDENT',
  ) || match(
    'WEAK_RECLAIM_LONG_55_59_CHOP',
    dir === 'LONG'
      && isClass('WEAK_RECLAIM')
      && inScore(55, 59)
      && gate === 'GATE_OK_SHAKEOUT_CHOP_TEST',
  ) || match(
    'WEAK_REJECT_SHORT_55_59_WEAK_UP',
    dir === 'SHORT'
      && isClass('WEAK_REJECT')
      && inScore(55, 59)
      && gate === 'GATE_OK_SHAKEOUT_WEAK_UP_INDEPENDENT',
  ) || { bad: false, reason: '' };
}

function getShakeoutBtcUpShortBadSizeGroup(combo) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_BTC_UP_SHORT_BAD_SIZE_TEST === 'false') {
    return { bad: false, reason: '' };
  }
  const parts = new Set(
    String(combo ?? '')
      .split('|')
      .map((part) => normalizePumpComboPart(part, ''))
      .filter(Boolean),
  );
  const has = (part) => parts.has(part);
  const match = (reason, ok) => (ok ? { bad: true, reason } : null);
  if (!has('SHORT')) return { bad: false, reason: '' };

  return match(
    'FALSE_RECLAIM_SHORT_60_69_MEDIUM_BTC_UP_WEAK',
    has('FALSE_RECLAIM') && has('SCORE_60_69') && has('MEDIUM') && has('BTC_UP_WEAK'),
  ) || match(
    'FALSE_RECLAIM_SHORT_60_69_LOW_BTC_UP_MID',
    has('FALSE_RECLAIM') && has('SCORE_60_69') && has('LOW') && has('BTC_UP_MID'),
  ) || match(
    'WEAK_REJECT_SHORT_70_79_MEDIUM_BTC_UP_MID',
    has('WEAK_REJECT') && has('SCORE_70_79') && has('MEDIUM') && has('BTC_UP_MID'),
  ) || match(
    'WEAK_REJECT_SHORT_70_79_MEDIUM_BTC_UP_WEAK',
    has('WEAK_REJECT') && has('SCORE_70_79') && has('MEDIUM') && has('BTC_UP_WEAK'),
  ) || { bad: false, reason: '' };
}

function getShakeoutHighJumpRisk({ symbol, leverage, now = Date.now() }) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_RISK_FILTER === 'false') {
    return { block: false, enabled: false };
  }
  const sampleSize = Math.max(
    6,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_SAMPLE_5M ?? 12),
  );
  const excludeRecent = Math.max(
    1,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_EXCLUDE_RECENT_5M ?? 2),
  );
  const closed = (klineCache.getIfCached(String(symbol ?? '').toUpperCase(), '5m', sampleSize + excludeRecent + 4) ?? [])
    .filter((k) => Number(k?.closeTime ?? 0) <= now)
    .slice(-(sampleSize + excludeRecent));
  const baseline = excludeRecent > 0 ? closed.slice(0, -excludeRecent) : closed;
  const ranges = baseline
    .map((k) => {
      const open = Number(k?.open);
      const high = Number(k?.high);
      const low = Number(k?.low);
      return Number.isFinite(open) && open > 0 && Number.isFinite(high) && Number.isFinite(low)
        ? Math.abs(high - low) / open * 100
        : NaN;
    })
    .filter(Number.isFinite)
    .sort((a, b) => a - b);
  const minSamples = Math.max(
    5,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_MIN_SAMPLES ?? 8),
  );
  if (ranges.length < minSamples) {
    return { block: false, enabled: true, reason: `samples=${ranges.length}<${minSamples}` };
  }
  const mid = Math.floor(ranges.length / 2);
  const medianRangePct = ranges.length % 2
    ? ranges[mid]
    : (ranges[mid - 1] + ranges[mid]) / 2;
  const p75RangePct = ranges[Math.min(ranges.length - 1, Math.ceil(ranges.length * 0.75) - 1)];
  const lev = Math.max(1, Number(leverage) || 1);
  const medianRoe = medianRangePct * lev;
  const p75Roe = p75RangePct * lev;
  const maxMedianRoe = Math.max(
    1,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_MAX_MEDIAN_ROE ?? 12),
  );
  const maxP75Roe = Math.max(
    maxMedianRoe,
    Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_MAX_P75_ROE ?? 20),
  );
  const block = medianRoe >= maxMedianRoe || p75Roe >= maxP75Roe;
  return {
    block,
    enabled: true,
    samples: ranges.length,
    leverage: lev,
    medianRangePct,
    p75RangePct,
    medianRoe,
    p75Roe,
    maxMedianRoe,
    maxP75Roe,
    reason: `5m baseline ${ranges.length} candles: median=${medianRangePct.toFixed(2)}% (${medianRoe.toFixed(1)}% ROE), p75=${p75RangePct.toFixed(2)}% (${p75Roe.toFixed(1)}% ROE) @${lev}x`,
  };
}

function decorateShakeoutHighJumpRisks(signals = [], now = Date.now()) {
  for (const sig of signals) {
    const marketEntry = Number(sig?.entryReference ?? sig?.markPrice ?? sig?.entry);
    const pendingEntry = Number(sig?.entry ?? sig?.markPrice);
    const signalSl = Number(sig?.sl);
    const marketLeverage = calcAutoLeverage(marketEntry, signalSl);
    const pendingLeverage = calcAutoLeverage(pendingEntry, signalSl);
    const risk = getShakeoutHighJumpRisk({
      symbol: sig?.symbol,
      leverage: Math.max(marketLeverage, pendingLeverage),
      now,
    });
    sig.highJumpRisk = Boolean(risk.block);
    sig.highJumpRiskLabel = risk.block ? 'HIGH JUMP RISK' : '';
    sig.highJumpRiskReason = risk.reason ?? '';
    sig.highJumpRiskMetrics = risk.enabled ? risk : null;
  }
  return signals;
}

async function createShakeoutPaperTrades(signals = []) {
  if (process.env.SHAKEOUT_RECLAIM_PAPER_ENABLED === 'false') return;
  const minScore = Number(process.env.SHAKEOUT_RECLAIM_PAPER_MIN_SCORE ?? 55);
  const marketMinScore = Number(process.env.SHAKEOUT_RECLAIM_PAPER_MARKET_MIN_SCORE ?? 60);
  const shortMarketMinScore = Number(process.env.SHAKEOUT_RECLAIM_PAPER_SHORT_MARKET_MIN_SCORE ?? 60);
  const noHedge = process.env.SHAKEOUT_RECLAIM_PAPER_NO_HEDGE !== 'false';
  const now = Date.now();
  const candleLockMs = getShakeoutPaperCandleLockMs();
  const candleStart = getShakeoutPaperCandleStart(now);

  // Chặn hedge: nếu coin đang có lệnh chiều ngược active (OPEN/PENDING) thì không vào chiều mới
  const activeSide = new Map(); // symbol -> Set sides đang active
  const store = await readShakeoutPaperStore();
  for (const t of store.trades) {
    if (['OPEN', 'PENDING'].includes(t.status)) {
      if (!activeSide.has(t.symbol)) activeSide.set(t.symbol, new Set());
      activeSide.get(t.symbol).add(t.side);
    }
  }

  for (const sig of signals) {
    if (Number(sig?.score ?? 0) < minScore) continue;
    if (String(sig?.stage ?? '') !== 'RECLAIM_CONFIRMED') continue;
    if (sig.bottomReboundRisk || sig.autoTradeBlocked
        || String(sig.subtype ?? '') === 'BOTTOM_REBOUND_RISK') {
      console.log(`[ShakeoutPaper] skip ${sig.symbol} BOTTOM_REBOUND_RISK - ${sig.autoTradeBlockReason ?? 'false-bottom risk'}`);
      continue;
    }
    const side = String(sig.action ?? '').toUpperCase();
    if (!['LONG', 'SHORT'].includes(side)) continue;
    const btcTurnRisk = getBtcLocalTurnRiskLogForShakeout(side);
    if (activeSide.get(sig.symbol)?.has(side)) {
      console.log(`[ShakeoutPaper] skip ${sig.symbol} ${side} - dang co lenh cung chieu active (OPEN/PENDING)`);
      continue;
    }
    if (noHedge) {
      const opposite = side === 'LONG' ? 'SHORT' : 'LONG';
      if (activeSide.get(sig.symbol)?.has(opposite)) {
        console.log(`[ShakeoutPaper] skip ${sig.symbol} ${side} - đã có lệnh ${opposite} active (chặn hedge)`);
        continue;
      }
    }
    // FALSE_RECLAIM filter: bỏ khi vol cực cao (blow-off climax) HOẶC 15m pump quá extended — nhóm thua rõ.
    // Backtest: loser vol ~104x vs winner ~62x; bucket pump15m>70% net âm. Giữ trap HIGH (vẫn dương).
    if (String(sig.shakeoutClass ?? '') === 'FALSE_RECLAIM'
        && process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_FILTER !== 'false') {
      const maxVol = Number(process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_MAX_VOL ?? 100);
      const maxMove15 = Number(process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_MAX_MOVE15 ?? 70);
      const vol5 = Number(sig.factors?.vol5mX ?? 0);
      const mv15 = Number(sig.factors?.move15mPct ?? 0);
      if (vol5 > maxVol || mv15 > maxMove15) {
        console.log(`[ShakeoutPaper] skip ${sig.symbol} FALSE_RECLAIM - vol=${vol5}x>${maxVol} hoặc 15m=${mv15}%>${maxMove15}% (blow-off/over-extended)`);
        continue;
      }
    }
    const key = `${sig.symbol}|${side}|${sig.stage ?? ''}`;
    const lastCandleStart = shakeoutPaperAutoFired.get(key) ?? 0;
    if (lastCandleStart === candleStart) continue;
    const firedInCurrentCandle = store.trades.some((t) =>
      String(t.source ?? '').startsWith('shakeout-auto')
      && String(t.symbol ?? '').toUpperCase() === String(sig.symbol ?? '').toUpperCase()
      && String(t.side ?? '').toUpperCase() === side
      && String(t.stage ?? '') === String(sig.stage ?? '')
      && getShakeoutPaperCandleStart(Date.parse(t.createdAt ?? 0)) === candleStart);
    if (firedInCurrentCandle) {
      shakeoutPaperAutoFired.set(key, candleStart);
      continue;
    }
    shakeoutPaperAutoFired.set(key, candleStart);

    // Tạo 2 lệnh cùng 1 signalId để so sánh điểm vào:
    //   MARKET  (cách A): entry = giá market lúc signal, vào OPEN ngay
    //   PENDING (cách B): entry = giá dự kiến (EMA99 cho score thấp), chờ giá chạm mới fill
    // Binary 5x/10x theo SL distance của từng entry (giống real-order handlers).
    const signalId = crypto.randomUUID();
    const marketEntry = Number(sig.entryReference ?? sig.markPrice ?? sig.entry);
    const pendingEntry = Number(sig.entry ?? sig.markPrice);
    const btcStrongShortEma99 = side === 'SHORT' && Boolean(sig.btcStrongShortEma99);
    const trapRisk = String(sig.riskFlags?.trapRisk ?? 'LOW').toUpperCase();
    const hybridGate = getShakeoutHybridStructuralBlock(sig, side, trapRisk);
    if (hybridGate.block) {
      console.log(
        `[ShakeoutPaper] skip ${sig.symbol} ${side} HYBRID_BTC_GATE`
        + ` btc=${hybridGate.btcBias.bias} (${hybridGate.btcBias.reason})`
        + ` - ${hybridGate.reasons.join('; ')}`,
      );
      continue;
    }
    // FALSE_RECLAIM trap HIGH: chỉ giữ reclaim weak > 6% (vùng lời, lossRate 14%); skip còn lại.
    // Backtest: reclaim 3-6% lossRate 59% net -113%; <3% & pump>55% & vol>100x đều thua cao.
    const isFalseReclaimHigh = String(sig.shakeoutClass ?? '') === 'FALSE_RECLAIM' && trapRisk === 'HIGH';
    if (isFalseReclaimHigh && process.env.SHAKEOUT_RECLAIM_PAPER_FR_HIGH_FILTER !== 'false') {
      const reclPct = Number(sig.factors?.reclaimPct ?? 0);
      const minRecl = Number(process.env.SHAKEOUT_RECLAIM_PAPER_FR_HIGH_MIN_RECLAIM ?? 6);
      if (reclPct <= minRecl) {
        console.log(`[ShakeoutPaper] skip ${sig.symbol} FALSE_RECLAIM trap HIGH - reclaim ${reclPct.toFixed(1)}% <= ${minRecl}% (chỉ giữ reclaim>6%)`);
        continue;
      }
    }
    // WEAK "sạch" = reason mặc định "setup passes but lacks strong confirmation" (không cờ xấu cụ thể)
    // -> cohort R:R đẹp, dùng margin $20 + ép SL thường. WEAK có reason xấu (BTC weak vs long,
    // reclaim weak/late...) KHÔNG tính, về $10 + cơ chế thường.
    const isWeakClean = ['WEAK_RECLAIM', 'WEAK_REJECT'].includes(String(sig.shakeoutClass ?? ''))
      && String(sig.shakeoutClassReason ?? '').includes('lacks strong confirmation');
    const isCleanConfirmLong = isWeakClean
      && side === 'LONG'
      && String(sig.shakeoutClass ?? '') === 'WEAK_RECLAIM';
    const isCleanConfirmShort = isWeakClean
      && side === 'SHORT'
      && String(sig.shakeoutClass ?? '') === 'WEAK_REJECT';
    const isWeakReclaimBtcLateBad = side === 'LONG'
      && String(sig.shakeoutClass ?? '') === 'WEAK_RECLAIM'
      && String(sig.shakeoutClassReason ?? '').includes('BTC weak vs long')
      && String(sig.shakeoutClassReason ?? '').includes('reclaim weak/late')
      && trapRisk === 'MEDIUM'
      && Number(sig.score ?? 0) < Number(process.env.SHAKEOUT_RECLAIM_WEAK_BTC_LATE_MAX_SCORE ?? 60);
    const weakReclaimBtcLateNote = isWeakReclaimBtcLateBad
      ? `WEAK_BTC_LATE_NO_DYNAMIC score=${sig.score}<${Number(process.env.SHAKEOUT_RECLAIM_WEAK_BTC_LATE_MAX_SCORE ?? 60)}; BTC weak vs long + reclaim weak/late + trap MEDIUM; PENDING/test only; SL required`
      : '';
    const falseReclaimNoDynamicEnabled = process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_WEAK_HOT_NO_DYNAMIC !== 'false';
    const frWeakHotMinPump = Number(process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_WEAK_HOT_MIN_PUMP ?? 30);
    const frWeakHotMaxReclaim = Number(process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_WEAK_HOT_MAX_RECLAIM ?? 2);
    const frMovePct = Number(sig.factors?.move5mPct ?? sig.factors?.move15mPct ?? 0);
    const frReclaimPct = Number(sig.factors?.reclaimPct ?? 0);
    const falseReclaimWeakHotNoDynamic = falseReclaimNoDynamicEnabled
      && String(sig.shakeoutClass ?? '') === 'FALSE_RECLAIM'
      && ['MEDIUM', 'HIGH'].includes(trapRisk)
      && Number.isFinite(frMovePct)
      && Number.isFinite(frReclaimPct)
      && frMovePct >= frWeakHotMinPump
      && frReclaimPct < frWeakHotMaxReclaim;
    const falseReclaimWeakHotNote = falseReclaimWeakHotNoDynamic
      ? `FALSE_RECLAIM_WEAK_HOT_NO_DYNAMIC pump=${frMovePct.toFixed(1)}%>=${frWeakHotMinPump}% reclaim=${frReclaimPct.toFixed(1)}%<${frWeakHotMaxReclaim}% trap=${trapRisk}; SL required`
      : '';
    const falseReclaimNoMarket = process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_NO_MARKET !== 'false'
      && String(sig.shakeoutClass ?? '') === 'FALSE_RECLAIM';
    const falseReclaimNoMarketNote = falseReclaimNoMarket
      ? `FALSE_RECLAIM_NO_MARKET: backtest 4d negative; MARKET disabled, keep PENDING/test only`
      : '';
    const bottomFlushShortRisk = getShakeoutBottomFlushShortRisk({
      ...sig,
      side,
      trapRisk,
      note: sig.note ?? sig.reason ?? '',
    });
    const weakRejectShortSqueezeRisk = getShakeoutWeakRejectShortSqueezeRisk({
      ...sig,
      side,
      trapRisk,
      note: sig.note ?? sig.reason ?? '',
    });
    const shakeoutQuality = classifyShakeoutPaperQuality({ ...sig, side, trapRisk });
    const isBadClass = shakeoutQuality.tier === 'BAD'
      && process.env.SHAKEOUT_RECLAIM_PAPER_BAD_CLASS_DOWNSIZE !== 'false';
    const useBtcDynamicEntry = ['MEDIUM', 'HIGH'].includes(trapRisk)
      && !bottomFlushShortRisk.block
      && !isFalseReclaimHigh // FR trap HIGH (giữ lại) dùng SL thường, KHÔNG noSL/dynamic
      && !isWeakClean        // WEAK sạch ($20) cũng ép SL thường, không noSL
      && !isBadClass         // loại XẤU (FALSE_RECLAIM short, CLEAN_*): luôn ép SL, không noSL/dynamic
      && !isWeakReclaimBtcLateBad // WEAK BTC yếu + reclaim late score thấp như ESPORTS: không noSL/dynamic
      && !falseReclaimWeakHotNoDynamic; // FR nóng + reclaim yếu như ACT: không noSL/dynamic
    const btcAnchorPrice = Number(btcHealthCache.data?.price);
    const btcDynamicMaxPct = trapRisk === 'HIGH'
      ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_HIGH_MAX_PCT ?? 4)
      : Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_DYNAMIC_MEDIUM_MAX_PCT ?? 8);
    const isBottomRebound = side === 'LONG'
      && (sig.bottomRebound || String(sig.subtype ?? '') === 'BOTTOM_REBOUND');
    const bottomReboundPolicy = isBottomRebound
      ? getShakeoutBottomReboundPaperPolicy(sig, trapRisk)
      : null;
    const riskGateEnabled = process.env.SHAKEOUT_RECLAIM_PAPER_BACKTEST_RISK_GATE !== 'false';
    const riskGateReasons = [];
    const className = String(sig.shakeoutClass ?? '');
    const classReason = String(sig.shakeoutClassReason ?? '');
    if (riskGateEnabled && trapRisk === 'HIGH') {
      riskGateReasons.push('trap HIGH backtest-negative');
    }
    if (riskGateEnabled
        && className === 'WEAK_RECLAIM'
        && classReason.includes('BTC weak vs long')) {
      riskGateReasons.push('WEAK_RECLAIM + BTC weak vs long');
    }
    if (riskGateEnabled && weakRejectShortSqueezeRisk.block) {
      riskGateReasons.push(weakRejectShortSqueezeRisk.reason);
    }
    const suppressMarketByRiskGate = riskGateReasons.length > 0;
    const riskGateNote = suppressMarketByRiskGate
      ? `BACKTEST_RISK_GATE: ${riskGateReasons.join('; ')} - MARKET/scout disabled, PENDING only`
      : '';
    // Gate BTC: không bắt đáy (bottom_rebound long, no-SL+DCA) khi BTC đảo XUỐNG rõ — cả market đang đổ
    // thì "đáy" thường là dao rơi, DCA chỉ nhồi thêm lỗ. Chỉ chặn khi đảo rõ, không phải giảm nhẹ.
    if (isBottomRebound && process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_BTC_GATE !== 'false') {
      const h = btcHealthCache.data;
      const reg = emaSqueezeBtcRegime(h);
      const gatePct6h = Number(process.env.SHAKEOUT_RECLAIM_PAPER_BOTTOM_REBOUND_BTC_PCT6H ?? -0.5);
      const btcFalling = h && !h.error && reg === 'WEAK'
        && (h.emaTrend1h === 'below' || Number(h.pct6h ?? 0) < gatePct6h);
      if (btcFalling) {
        console.log(`[ShakeoutPaper] skip ${sig.symbol} BOTTOM_REBOUND - BTC đảo xuống rõ (regime=${reg} EMA1h=${h.emaTrend1h} pct6h=${h.pct6h}%) — không bắt đáy khi market đang đổ`);
        continue;
      }
    }
    if (bottomReboundPolicy?.skip) {
      console.log(
        `[ShakeoutPaper] skip ${sig.symbol} BOTTOM_REBOUND - ${bottomReboundPolicy.reasons.join('; ')}`,
      );
      continue;
    }
    const cleanLongTestMarginUsdt = Number(process.env.SHAKEOUT_RECLAIM_PAPER_CLEAN_LONG_TEST_MARGIN_USDT ?? 1);
    const cleanShortPendingMarginUsdt = Number(process.env.SHAKEOUT_RECLAIM_PAPER_CLEAN_SHORT_PENDING_MARGIN_USDT ?? 10);
    const marginUsdt = isBottomRebound
      ? bottomReboundPolicy.marginUsdt
      : isBadClass
        ? shakeoutQuality.marginUsdt
      : isCleanConfirmLong && Number(sig.score ?? 0) < 60
        ? cleanLongTestMarginUsdt
      : isCleanConfirmShort
        ? cleanShortPendingMarginUsdt
      : isWeakClean
        ? shakeoutQuality.marginUsdt
        : isWeakReclaimBtcLateBad
          ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_WEAK_BTC_LATE_TEST_MARGIN_USDT ?? 1)
          : shakeoutQuality.marginUsdt;
    // Uniform test: đồng nhất margin cho MỌI lệnh shakeout để dễ so sánh (đặt =0 để tắt, về margin theo phân loại).
    const uniformTestMargin = Number(process.env.SHAKEOUT_RECLAIM_PAPER_UNIFORM_TEST_MARGIN ?? 0);
    const sc = sig.score;
    const sideL = side.toLowerCase();
    const marketThreshold = side === 'SHORT' ? shortMarketMinScore : marketMinScore;
    const marketScoreOk = isWeakClean || sc >= marketThreshold;
    const marketScoreNote = isWeakClean && sc < marketThreshold
      ? `WEAK_CLEAN_SCORE_BYPASS score=${sc}<${marketThreshold}; MARKET not blocked by point`
      : '';
    const referenceEntry = Number(sig.entryReference ?? sig.markPrice ?? sig.entry);
    const signalSl = Number(sig.sl);
    const signalTp = Number(sig.tp);
    const riskPct = Number.isFinite(referenceEntry) && referenceEntry > 0 && Number.isFinite(signalSl)
      ? Math.min(0.35, Math.max(0.003, Math.abs(referenceEntry - signalSl) / referenceEntry))
      : 0.03;
    const rewardPct = Number.isFinite(referenceEntry) && referenceEntry > 0 && Number.isFinite(signalTp)
      ? Math.max(riskPct * 1.1, Math.abs(signalTp - referenceEntry) / referenceEntry)
      : riskPct * 2.2;
    const nearEntryMaxPct = Math.max(
      0,
      Number(process.env.SHAKEOUT_RECLAIM_PAPER_NEAR_ENTRY_MAX_PCT ?? 1),
    );
    const entryDistancePct = Number.isFinite(marketEntry) && marketEntry > 0 && Number.isFinite(pendingEntry)
      ? Math.abs(pendingEntry - marketEntry) / marketEntry * 100
      : Infinity;
    const nearMarketEntry = entryDistancePct <= nearEntryMaxPct;
    const nearEntryNote = nearMarketEntry
      ? `nearMarketEntry=${entryDistancePct.toFixed(2)}% <= ${nearEntryMaxPct.toFixed(2)}%; PENDING skipped`
      : '';
    const marketLeverage = calcAutoLeverage(marketEntry, signalSl);
    const pendingLeverage = calcAutoLeverage(pendingEntry, signalSl);
    const highJumpRiskMarginUsdt = Math.max(
      0.01,
      Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_RISK_MARGIN_USDT ?? 10),
    );
    const highJumpRiskLeverage = Math.max(
      1,
      Math.min(20, Number(process.env.SHAKEOUT_RECLAIM_PAPER_HIGH_JUMP_RISK_LEVERAGE ?? 5)),
    );
    const jumpRisk = sig.highJumpRiskMetrics ?? getShakeoutHighJumpRisk({
      symbol: sig.symbol,
      leverage: highJumpRiskLeverage,
      now,
    });
    if (jumpRisk.block) {
      console.log("[ShakeoutPaper] warn " + sig.symbol + " " + side + " HIGH_JUMP_RISK - " + jumpRisk.reason + "; trade remains enabled at $" + highJumpRiskMarginUsdt.toFixed(0) + " margin / " + highJumpRiskLeverage + "x leverage");
    }
    const marketRewardRoe = Number.isFinite(marketEntry) && marketEntry > 0 && Number.isFinite(signalTp)
      ? Math.abs(signalTp - marketEntry) / marketEntry * marketLeverage * 100
      : 0;
    const minMarketRewardRoe = Math.max(
      0,
      Number(process.env.SHAKEOUT_RECLAIM_PAPER_MARKET_MIN_TP_ROE ?? 20),
    );
    const marketRewardTooLow = marketRewardRoe < minMarketRewardRoe;
    const marketRewardNote = marketRewardTooLow
      ? `marketTpRoe=${marketRewardRoe.toFixed(1)}% < ${minMarketRewardRoe.toFixed(1)}%; MARKET skipped, PENDING only`
      : '';
    const realGate = getShakeoutRealGate({
      ...sig,
      side,
      trapRisk,
      entry: marketEntry,
      tp: signalTp,
      sl: signalSl,
      leverage: marketLeverage,
    }, {
      btcBias: hybridGate.btcBias,
      projectedRoe: marketRewardRoe,
    });
    const realGateNote = `SHAKEOUT_${realGate.label}: ${realGate.reasons.join('; ')}${realGate.projectedRoe != null ? `; tpRoe=${realGate.projectedRoe}%` : ''}`;
    const signalTimeframe = String(sig.factors?.timeframe ?? sig.interval ?? '5m');
    const shakeoutBtcHealth = buildBtcHealthSnapshot(btcHealthCache.data ?? {});
    const rawSignalAt = sig.scannedAt ?? sig.signalAt ?? now;
    const parsedSignalAt = typeof rawSignalAt === 'number' ? rawSignalAt : Date.parse(rawSignalAt);
    const signalAt = new Date(Number.isFinite(parsedSignalAt) ? parsedSignalAt : now).toISOString();
    const symbolCandleAtEntry = sig.candlePattern5m
      ?? cachedCandlePatternAt(sig.symbol, '5m', signalAt)
      ?? null;
    const btcCandleAtEntry = sig.btcCandlePattern5m
      ?? cachedCandlePatternAt('BTCUSDT', '5m', signalAt)
      ?? null;
    const sideCandleGate = evaluateShakeoutSideCandle({
      side,
      btcHealth: shakeoutBtcHealth ?? {},
      btcCandle: btcCandleAtEntry,
    });
    const shakeoutBtcCorr = getCoinBtcCorr(sig.symbol, signalTimeframe, 30);
    const shakeoutBtcGate = getShakeoutBtcGate({
      sig,
      side,
      btcHealth: shakeoutBtcHealth,
      btcCorr: shakeoutBtcCorr,
      trapRisk,
    });
    const shakeoutCombo = shakeoutSignalComboOf({
      ...sig,
      action: side,
      side,
      timeframe: signalTimeframe,
      trapRisk,
      btcCorr: shakeoutBtcCorr,
      btcPhase: shakeoutBtcGate.phase,
      btcRelationLabel: shakeoutBtcGate.relation,
      btcGateLabel: shakeoutBtcGate.label,
    }, shakeoutBtcHealth);
    const shakeoutClassUpper = String(sig.shakeoutClass ?? '').toUpperCase();
    const shakeoutBtcPhaseUpper = String(shakeoutBtcGate.phase ?? '').toUpperCase();
    const shakeoutBtcGateUpper = String(shakeoutBtcGate.label ?? '').toUpperCase();
    const btcRegimeAtEntryUpper = String(
      sig.btcRegimeAtEntry
      ?? shakeoutBtcGate.regime
      ?? shakeoutBtcHealth.regime
      ?? '',
    ).toUpperCase();
    const btcTrendScoreAtEntry = Number(
      sig.btcTrendScoreAtEntry
      ?? shakeoutBtcGate.btcTrendScore
      ?? shakeoutBtcHealth.btcTrendScore,
    );
    const btcPct6hAtEntry = Number(
      sig.btcPct6hAtEntry
      ?? shakeoutBtcGate.btcPct6h
      ?? shakeoutBtcHealth.pct6h,
    );
    const isWeakReclaimLongSub75 = side === 'LONG'
      && shakeoutClassUpper === 'WEAK_RECLAIM'
      && Number.isFinite(sc)
      && sc < 75;
    const weakReclaimLongBadBtcUpMid = isWeakReclaimLongSub75
      && shakeoutBtcPhaseUpper === 'BTC_UP_MID'
      && (
        btcRegimeAtEntryUpper === 'FLAT'
        || btcRegimeAtEntryUpper === 'WEAK'
        || (Number.isFinite(btcTrendScoreAtEntry) && btcTrendScoreAtEntry <= 55)
        || (Number.isFinite(btcPct6hAtEntry) && btcPct6hAtEntry <= 0.10)
        || shakeoutBtcGateUpper.includes('WEAK_UP')
      );
    const weakReclaimLongGoodBtcUpMid = isWeakReclaimLongSub75
      && shakeoutBtcPhaseUpper === 'BTC_UP_MID'
      && (
        btcRegimeAtEntryUpper === 'STRONG'
        || (Number.isFinite(btcTrendScoreAtEntry) && btcTrendScoreAtEntry >= 60)
        || (Number.isFinite(btcPct6hAtEntry) && btcPct6hAtEntry >= 0.25)
      );
    const weakReclaimLongDownWeakIndependent =
      process.env.SHAKEOUT_RECLAIM_PAPER_BLOCK_WEAK_LONG_DOWN_WEAK_INDEPENDENT !== 'false'
      && side === 'LONG'
      && shakeoutClassUpper === 'WEAK_RECLAIM'
      && shakeoutBtcPhaseUpper === 'BTC_DOWN_WEAK'
      && shakeoutBtcGateUpper === 'GATE_OK_SHAKEOUT_WEAK_DOWN_INDEPENDENT';
    let weakReclaimBtcSizeOverrideUsdt = null;
    let weakReclaimBtcSizeNote = '';
    if (process.env.SHAKEOUT_RECLAIM_PAPER_WEAK_RECLAIM_LONG_BTC_SIZE_RULE !== 'false') {
      if (weakReclaimLongBadBtcUpMid || weakReclaimLongDownWeakIndependent) {
        weakReclaimBtcSizeOverrideUsdt = Math.max(
          0.01,
          Number(process.env.SHAKEOUT_RECLAIM_PAPER_WEAK_RECLAIM_LONG_BAD_MARGIN_USDT ?? 1),
        );
        weakReclaimBtcSizeNote = `WEAK_RECLAIM_LONG_BTC_SIZE_BAD: phase=${shakeoutBtcGate.phase}`
          + ` regime=${btcRegimeAtEntryUpper || '-'} btcTrendScore=${Number.isFinite(btcTrendScoreAtEntry) ? btcTrendScoreAtEntry : '-'}`
          + ` btcPct6h=${Number.isFinite(btcPct6hAtEntry) ? btcPct6hAtEntry : '-'} gate=${shakeoutBtcGate.label}`
          + `; margin=$${weakReclaimBtcSizeOverrideUsdt.toFixed(0)}`;
      } else if (weakReclaimLongGoodBtcUpMid) {
        weakReclaimBtcSizeOverrideUsdt = Math.max(
          0.01,
          Number(process.env.SHAKEOUT_RECLAIM_PAPER_WEAK_RECLAIM_LONG_GOOD_MARGIN_USDT ?? 10),
        );
        weakReclaimBtcSizeNote = `WEAK_RECLAIM_LONG_BTC_SIZE_GOOD: phase=${shakeoutBtcGate.phase}`
          + ` regime=${btcRegimeAtEntryUpper || '-'} btcTrendScore=${Number.isFinite(btcTrendScoreAtEntry) ? btcTrendScoreAtEntry : '-'}`
          + ` btcPct6h=${Number.isFinite(btcPct6hAtEntry) ? btcPct6hAtEntry : '-'} gate=${shakeoutBtcGate.label}`
          + `; margin=$${weakReclaimBtcSizeOverrideUsdt.toFixed(0)}`;
      }
    }
    const allowBtcDynamicScout = marketScoreOk
      && !marketRewardTooLow
      && !suppressMarketByRiskGate
      && !falseReclaimNoMarket;

    const cleanConfirmNote = isCleanConfirmLong
      ? Number(sig.score ?? 0) >= 70
        ? (marketRewardTooLow
          ? `CLEAN_CONFIRM_LONG_RULE score>=70 but tpRoe ${marketRewardRoe.toFixed(1)}% < ${minMarketRewardRoe.toFixed(1)}%: PENDING only`
          : 'CLEAN_CONFIRM_LONG_RULE score>=70: MARKET OK')
        : Number(sig.score ?? 0) >= 60
          ? 'CLEAN_CONFIRM_LONG_RULE score 60-69: PENDING only'
          : (marketRewardTooLow
            ? `CLEAN_CONFIRM_LONG_RULE score<60 but tpRoe ${marketRewardRoe.toFixed(1)}% < ${minMarketRewardRoe.toFixed(1)}%: PENDING only`
            : `CLEAN_CONFIRM_LONG_RULE score<60: MARKET test small $${cleanLongTestMarginUsdt}`)
      : isCleanConfirmShort
        ? 'CLEAN_CONFIRM_SHORT_RULE: PENDING preferred; MARKET disabled until more data'
        : '';
    let variants = isBottomRebound
      ? [{ variant: 'MARKET', status: 'OPEN', entryPrice: marketEntry, tag: 'mkt' }]
      : isCleanConfirmLong
        ? Number(sig.score ?? 0) >= 70
          ? (marketRewardTooLow
            ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'pend' }]
            : [{ variant: 'MARKET', status: 'OPEN', entryPrice: marketEntry, tag: 'mkt' }])
          : Number(sig.score ?? 0) >= 60
            ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'pend' }]
            : (marketRewardTooLow
              ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'pend' }]
              : [{
              variant: 'MARKET',
              status: 'OPEN',
              entryPrice: marketEntry,
              tag: 'mkt-test',
              marginUsdt: cleanLongTestMarginUsdt,
            }])
      : isCleanConfirmShort
        ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'pend' }]
      : useBtcDynamicEntry
        ? (!allowBtcDynamicScout
          ? [
            {
              variant: 'PENDING',
              status: 'PENDING',
              entryPrice: pendingEntry,
              tag: 'btc-dynamic',
              btcDynamicEntry: true,
            },
          ]
          : [
          {
            variant: 'MARKET',
            status: 'OPEN',
            entryPrice: marketEntry,
            tag: 'scout',
            // FALSE_RECLAIM ($10) và WEAK sạch ($20) dùng full margin thay vì scout $1
            marginUsdt: ((String(sig.shakeoutClass ?? '') === 'FALSE_RECLAIM'
              && process.env.SHAKEOUT_RECLAIM_PAPER_FALSE_RECLAIM_FULL_MARGIN !== 'false') || isWeakClean)
              ? marginUsdt
              : Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_SCOUT_MARGIN_USDT ?? 1),
          },
          {
            variant: 'PENDING',
            status: 'PENDING',
            entryPrice: pendingEntry,
            tag: 'btc-dynamic',
            btcDynamicEntry: true,
          },
        ])
      : btcStrongShortEma99
        ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'btc-strong-ema99' }]
      : [
      ...(marketScoreOk && !marketRewardTooLow && !suppressMarketByRiskGate && !falseReclaimNoMarket
        ? [{ variant: 'MARKET', status: 'OPEN', entryPrice: marketEntry, tag: 'mkt' }]
        : []),
      ...(!nearMarketEntry || marketRewardTooLow || suppressMarketByRiskGate || falseReclaimNoMarket
        ? [{ variant: 'PENDING', status: 'PENDING', entryPrice: pendingEntry, tag: 'pend' }]
        : []),
      ];
    // Apply the near-market guard after every branch has selected its variants.
    // This also covers BTC dynamic and pending-only paths, which otherwise bypass
    // the default MARKET/PENDING selector and double-count nearly identical entries.
    if (nearMarketEntry) {
      variants = variants.filter((v) => v.variant !== 'PENDING');
      console.log(
        `[ShakeoutPaper] skip ${sig.symbol} ${side} PENDING: distance=${entryDistancePct.toFixed(2)}% <= ${nearEntryMaxPct.toFixed(2)}%`,
      );
    }
    const hasPendingVariant = variants.some((v) => v.variant === 'PENDING');
    const hasOpenMarketVariant = variants.some((v) => v.status === 'OPEN');
    const chaseTest = getShakeoutChaseCandleTest({
      symbol: sig.symbol,
      side,
      marketEntry,
      pendingEntry,
      signalTp,
      signalSl,
    });
    const chaseShortTier = evaluateShakeoutChaseShortTier({
      variant: 'CHASE',
      side,
      score: sc,
      btcPhase: shakeoutBtcGate.phase,
      tierAMarginUsdt: process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_SHORT_A_MARGIN_USDT ?? 10,
      tierBMarginUsdt: process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_SHORT_B_MARGIN_USDT ?? 5,
    });
    const chaseBadGroup = getShakeoutBadChaseGroup({
      shakeoutClass: sig.shakeoutClass,
      side,
      score: sc,
      btcGateLabel: shakeoutBtcGate.label,
      combo: shakeoutCombo,
    });
    const chaseMarginUsdt = chaseShortTier.applies
      ? chaseShortTier.marginUsdt
      : chaseBadGroup.bad
        ? Math.max(0.01, Number(process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_BAD_GROUP_MARGIN_USDT ?? 1))
        : Number(process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_MARGIN_USDT ?? 2);
    const chaseBadGroupNote = !chaseShortTier.applies && chaseBadGroup.bad
      ? `; CHASE_BAD_GROUP_TEST_1=${chaseBadGroup.reason}`
      : '';
    const chaseShortTierNote = chaseShortTier.applies
      ? `; CHASE_SHORT_TIER=${chaseShortTier.tier}; ${chaseShortTier.reason}`
      : '';
    const btcUpShortBadSizeGroup = getShakeoutBtcUpShortBadSizeGroup(shakeoutCombo);
    const btcUpShortBadSizeMarginUsdt = Math.max(
      0.01,
      Number(process.env.SHAKEOUT_RECLAIM_PAPER_BTC_UP_SHORT_BAD_MARGIN_USDT ?? 1),
    );
    if (hasPendingVariant && !hasOpenMarketVariant && chaseTest.active) {
      variants = [
        {
          variant: 'CHASE',
          status: 'OPEN',
          entryPrice: marketEntry,
          tag: 'chase-candle-test',
          marginUsdt: chaseMarginUsdt,
          shakeoutQualityOverride: 'CHASE',
          chaseWeakGroup: Boolean(!chaseShortTier.applies && chaseBadGroup.bad),
          chaseWeakGroupReason: !chaseShortTier.applies ? chaseBadGroup.reason : '',
          chaseShortTier: chaseShortTier.applies ? chaseShortTier.tier : null,
          chaseShortTierLabel: chaseShortTier.applies ? chaseShortTier.label : null,
          chaseShortTierReason: chaseShortTier.applies ? chaseShortTier.reason : '',
          chaseConfirmation: chaseTest.confirmation,
          chaseNote: chaseTest.confirmation?.mode === 'RELAXED'
            ? `CHASE_CANDLE_TEST_RELAXED: pending entry ${pendingEntry} missed by ${chaseTest.movePct.toFixed(2)}%; closed 5m confirmation temporarily disabled; test $${chaseMarginUsdt}${chaseBadGroupNote}${chaseShortTierNote}`
            : `CHASE_CANDLE_TEST: pending entry ${pendingEntry} missed by ${chaseTest.movePct.toFixed(2)}%; closed 5m confirmed ${side}; body=${(chaseTest.confirmation.bodyShare * 100).toFixed(1)}%; close=${chaseTest.confirmation.close}; previousClose=${chaseTest.confirmation.previousClose}; test $${chaseMarginUsdt}${chaseBadGroupNote}${chaseShortTierNote}`,
        },
        ...variants,
      ];
    }
    const minPaperProjectedRoe = Math.max(
      0,
      Number(process.env.SHAKEOUT_RECLAIM_PAPER_MIN_PROJECTED_ROE ?? minMarketRewardRoe),
    );
    for (const v of variants) {
      if (!Number.isFinite(v.entryPrice) || v.entryPrice <= 0) continue;
      const weakReclaimSizedMarginUsdt = weakReclaimBtcSizeOverrideUsdt != null
        ? weakReclaimBtcSizeOverrideUsdt
        : Number(v.marginUsdt ?? marginUsdt);
      const classifiedMarginUsdt = v.shakeoutQualityOverride === 'CHASE'
        ? Number(v.marginUsdt ?? process.env.SHAKEOUT_RECLAIM_PAPER_CHASE_CANDLE_MARGIN_USDT ?? 2)
        : (uniformTestMargin > 0 ? uniformTestMargin : weakReclaimSizedMarginUsdt);
      const isBadChaseGroup = Boolean(v.chaseWeakGroup);
      const hasChaseShortTier = ['A', 'B_TEST'].includes(String(v.chaseShortTier ?? '').toUpperCase());
      const variantMarginUsdt = Number(v.marginUsdt);
      // Explicit weak cohorts stay at $1 so they remain measurable instead of being hidden.
      const preSideCandleMarginUsdt = hasChaseShortTier
        ? variantMarginUsdt
        : btcUpShortBadSizeGroup.bad
        ? btcUpShortBadSizeMarginUsdt
        : Number.isFinite(variantMarginUsdt) && variantMarginUsdt > 0
          ? variantMarginUsdt
        : jumpRisk.block && !isBadChaseGroup
          ? highJumpRiskMarginUsdt
          : classifiedMarginUsdt;
      const effectiveMarginUsdt = hasChaseShortTier || sideCandleGate.marginCapUsdt == null
        ? preSideCandleMarginUsdt
        : Math.min(preSideCandleMarginUsdt, sideCandleGate.marginCapUsdt);
      const geometryOk = side === 'LONG'
        ? signalSl < v.entryPrice && v.entryPrice < signalTp
        : signalTp < v.entryPrice && v.entryPrice < signalSl;
      const variantSl = geometryOk
        ? signalSl
        : side === 'LONG'
          ? v.entryPrice * (1 - riskPct)
          : v.entryPrice * (1 + riskPct);
      const variantTp = geometryOk
        ? signalTp
        : side === 'LONG'
          ? v.entryPrice * (1 + rewardPct)
          : v.entryPrice * (1 - rewardPct);
      const autoLeverage = calcAutoLeverage(v.entryPrice, variantSl);
      const lev = jumpRisk.block ? highJumpRiskLeverage : autoLeverage;
      const variantProjectedRoe = Number.isFinite(variantTp) && variantTp > 0
        ? Math.abs(variantTp - v.entryPrice) / v.entryPrice * lev * 100
        : NaN;
      if (minPaperProjectedRoe > 0
          && (!Number.isFinite(variantProjectedRoe) || variantProjectedRoe < minPaperProjectedRoe)) {
        console.log(
          `[ShakeoutPaper] skip ${sig.symbol} ${side} ${v.variant}: projectedRoe=`
          + `${Number.isFinite(variantProjectedRoe) ? variantProjectedRoe.toFixed(1) : 'NA'}%`
          + ` < ${minPaperProjectedRoe.toFixed(1)}%`,
        );
        continue;
      }
      const pendingMinSlRoe = Math.max(
        1,
        Number(process.env.SHAKEOUT_RECLAIM_PAPER_PENDING_MIN_SL_ROE ?? 20),
      );
      const pendingMaxSlRoe = Math.max(
        pendingMinSlRoe,
        Number(process.env.SHAKEOUT_RECLAIM_PAPER_PENDING_MAX_SL_ROE ?? 30),
      );
      const rawSlRoe = Math.abs(v.entryPrice - variantSl) / v.entryPrice * lev * 100;
      const adjustedSlRoe = v.variant === 'PENDING'
        ? Math.min(pendingMaxSlRoe, Math.max(pendingMinSlRoe, rawSlRoe))
        : rawSlRoe;
      const adjustedSlMove = adjustedSlRoe / 100 / lev;
      const finalVariantSl = v.variant === 'PENDING'
        ? (side === 'LONG'
          ? v.entryPrice * (1 - adjustedSlMove)
          : v.entryPrice * (1 + adjustedSlMove))
        : variantSl;
      // SL theo Real Gate: REAL_OK tin cậy (WR 75%) cho rộng 30%; REAL_TEST/BLOCK cắt sớm 15%.
      const realGateSlRoe = String(realGate.label ?? '') === 'REAL_OK'
        ? Number(process.env.SHAKEOUT_RECLAIM_PAPER_REAL_OK_SL_ROE ?? 30)
        : Number(process.env.SHAKEOUT_RECLAIM_PAPER_REAL_TEST_BLOCK_SL_ROE ?? 15);
      const maxPaperSlRoe = process.env.SHAKEOUT_RECLAIM_PAPER_REAL_GATE_SL === 'false'
        ? Math.max(1, Number(process.env.SHAKEOUT_RECLAIM_PAPER_MAX_SL_ROE ?? 40))
        : Math.max(1, realGateSlRoe);
      const finalSlRoe = Math.abs(v.entryPrice - finalVariantSl) / v.entryPrice * lev * 100;
      const cappedSlRoe = Math.min(maxPaperSlRoe, finalSlRoe);
      const cappedSlMove = cappedSlRoe / 100 / lev;
      const cappedVariantSl = finalSlRoe > maxPaperSlRoe
        ? (side === 'LONG'
          ? v.entryPrice * (1 - cappedSlMove)
          : v.entryPrice * (1 + cappedSlMove))
        : finalVariantSl;
      const pendingSlNote = v.variant === 'PENDING' && Math.abs(adjustedSlRoe - rawSlRoe) > 0.01
        ? `pendingSlRoeAdjusted=${rawSlRoe.toFixed(1)}%->${adjustedSlRoe.toFixed(1)}% sl=${finalVariantSl}`
        : '';
      const maxSlNote = finalSlRoe > maxPaperSlRoe
        ? `paperSlRoeCapped=${finalSlRoe.toFixed(1)}%->${maxPaperSlRoe.toFixed(1)}% sl=${cappedVariantSl}`
        : '';
      const finalRiskPct = Math.abs(v.entryPrice - cappedVariantSl) / v.entryPrice;
      const finalRr = finalRiskPct > 0
        ? Math.abs(variantTp - v.entryPrice) / v.entryPrice / finalRiskPct
        : 2.2;
      await createShakeoutPaperTrade({
        symbol: sig.symbol,
        side,
        status: v.status,
        variant: v.variant,
        signalId,
        marginUsdt: effectiveMarginUsdt,
        leverage: lev,
        entryPrice: v.entryPrice,
        sl: cappedVariantSl,
        tp: variantTp,
        score: sc,
        stage: sig.stage,
        signalTimeframe,
        signalType: sig.type,
        shakeoutSignalFactors: sig.factors,
        shakeoutSignalChange24hPct: sig.change24h,
        shakeoutSignalQuoteVolume: sig.volume,
        shakeoutEntryMode: v.btcDynamicEntry
          ? 'BTC_DYNAMIC'
          : (sig.entryMode ?? (v.variant === 'MARKET' ? 'MARKET' : 'PENDING_LIMIT')),
        candlePattern5m: sig.candlePattern5m,
        candlePattern15m: sig.candlePattern15m,
        btcCandlePattern5m: sig.btcCandlePattern5m,
        symbolCandleAtEntry,
        btcCandleAtEntry,
        ruleVersion: sideCandleGate.version,
        regimeAtEntry: sideCandleGate.regime,
        shakeoutSideCandleTier: sideCandleGate.tier,
        shakeoutSideCandleLabel: sideCandleGate.label,
        shakeoutSideCandleReason: sideCandleGate.reason,
        shakeoutSideCandleMarginCapUsdt: sideCandleGate.marginCapUsdt,
        shakeoutQuality: v.shakeoutQualityOverride ?? shakeoutQuality.tier,
        highJumpRisk: Boolean(jumpRisk.block),
        highJumpRiskLabel: jumpRisk.block ? 'HIGH JUMP RISK' : '',
        highJumpRiskReason: jumpRisk.reason ?? '',
        highJumpRiskMetrics: jumpRisk.enabled ? jumpRisk : null,
        shakeoutClass: sig.shakeoutClass,
        shakeoutClassLabel: sig.shakeoutClassLabel,
        shakeoutClassReason: sig.shakeoutClassReason,
        shakeoutClassColor: sig.shakeoutClassColor,
        shakeoutRealGateLabel: realGate.label,
        shakeoutRealGateReason: realGate.reasons.join('; '),
        shakeoutRealGateAllow: realGate.allowReal,
        shakeoutProjectedRoe: realGate.projectedRoe,
        btcHealth: shakeoutBtcHealth,
        btcCorr: shakeoutBtcCorr,
        btcPhase: shakeoutBtcGate.phase,
        btcGateLabel: shakeoutBtcGate.label,
        btcGateReason: shakeoutBtcGate.reason,
        btcRelationLabel: shakeoutBtcGate.relation,
        shakeoutCombo,
        chaseConfirmation: v.chaseConfirmation,
        subtype: sig.subtype,
        bottomRebound: isBottomRebound,
        noStopLoss: false,
        bottomReboundDcaAllowed: isBottomRebound ? bottomReboundPolicy.dcaAllowed : true,
        bottomReboundScoutOnly: Boolean(isBottomRebound && bottomReboundPolicy.scoutOnly),
        dcaBlocked: Boolean(isBottomRebound && !bottomReboundPolicy.dcaAllowed),
        source: `shakeout-auto-${sideL}-${sc}-${v.tag}-${lev}x`,
        note: [
          sig.note ?? sig.reason ?? '',
          `paperCandle${Math.round(candleLockMs / 60_000)}m=${new Date(candleStart).toISOString()}`,
          nearEntryNote,
	          marketRewardNote,
	          riskGateNote,
	          falseReclaimWeakHotNote,
          falseReclaimNoMarketNote,
	          weakReclaimBtcLateNote,
          weakReclaimBtcSizeNote,
          cleanConfirmNote,
          marketScoreNote,
          v.chaseNote,
          v.chaseWeakGroup ? `CHASE_BAD_GROUP_TEST_1=${v.chaseWeakGroupReason}; margin=$${effectiveMarginUsdt.toFixed(0)}` : '',
              v.chaseShortTier
            ? `CHASE_SHORT_TIER=${v.chaseShortTier}; ${v.chaseShortTierReason}; margin=$${effectiveMarginUsdt.toFixed(0)}`
            : '',
              btcUpShortBadSizeGroup.bad && !v.chaseShortTier
            ? `BTC_UP_SHORT_BAD_GROUP_TEST_1=${btcUpShortBadSizeGroup.reason}; margin=$${effectiveMarginUsdt.toFixed(0)}`
            : '',
          `SHAKEOUT_QUALITY=${v.shakeoutQualityOverride === 'CHASE' ? 'CHASE CANDLE TEST' : shakeoutQuality.label}; margin=$${effectiveMarginUsdt.toFixed(0)}; ${v.shakeoutQualityOverride === 'CHASE' ? (v.chaseConfirmation?.mode === 'RELAXED' ? 'pending missed; closed 5m confirmation temporarily disabled' : 'pending missed; closed 5m candle confirmed direction') : shakeoutQuality.reason}`,
          realGateNote,
          `SHAKEOUT_BTC_GATE=${shakeoutBtcGate.label}: ${shakeoutBtcGate.reason}`,
          `SHAKEOUT_COMBO=${shakeoutCombo}`,
          jumpRisk.block ? `HIGH_JUMP_RISK_WARNING=${jumpRisk.reason}; trade not blocked; margin=$${effectiveMarginUsdt.toFixed(0)}; leverage=${lev}x` : '',
          btcTurnRisk?.label ? `BTC_TURN_LOG=${btcTurnRisk.label}${btcTurnRisk.againstSide ? ' AGAINST_SIDE' : ''}` : '',
          geometryOk ? '' : `variantGeometryAdjusted=${v.variant} sl=${variantSl} tp=${variantTp}`,
          pendingSlNote,
          maxSlNote,
          btcStrongShortEma99 ? 'BTC STRONG: SHORT waits exact EMA99; MARKET disabled; no 5% clamp' : '',
          sig.btcIndependentShort
            ? `BTC STRONG but ${sig.btcEntryClass}: use coin structure entry`
            : '',
          isBottomRebound && bottomReboundPolicy?.scoutOnly
            ? `bottomRebound=SCOUT_ONLY | dcaLabel=${bottomReboundPolicy.dcaLabel} | noSL=OFF | noDCA=Y | reason=${bottomReboundPolicy.reasons.join(',')}`
            : '',
          isBottomRebound && !bottomReboundPolicy?.scoutOnly
            ? `bottomRebound=MARKET_ONLY | dcaLabel=${bottomReboundPolicy.dcaLabel} | noSL=Y | dca=$10@-25%ROE`
            : '',
          bottomFlushShortRisk.block ? `BTC_DYNAMIC_BLOCKED=${bottomFlushShortRisk.reason}` : '',
          v.tag === 'scout' ? 'BTC_DYNAMIC_SCOUT=MARKET $1' : '',
          v.btcDynamicEntry
            ? `BTC_DYNAMIC_LIMIT max=${btcDynamicMaxPct}% ttl=60m rr=${finalRr.toFixed(2)}`
            : '',
        ].filter(Boolean).join(' | '),
        trapRisk: sig.riskFlags?.trapRisk ?? null,
        trapReasons: sig.riskFlags?.trapReasons ?? null,
        entryReference: marketEntry,
        entryRaw: sig.entryRaw,
        entryDistancePct: sig.entryDistancePct,
        entryRawDistancePct: sig.entryRawDistancePct,
        entryWasClamped: sig.entryWasClamped,
        btcRegime: sig.btcRegime,
        btcEntryClass: sig.btcEntryClass,
        btcRelation: sig.btcRelation,
        btcTurnRisk,
        btcTurnRiskLabel: btcTurnRisk?.label,
        btcTurnRiskAgainstSide: Boolean(btcTurnRisk?.againstSide),
        btcTurnRiskReason: btcTurnRisk?.reason,
        btcTurnRiskAt: btcTurnRisk?.closeTime ? new Date(Number(btcTurnRisk.closeTime)).toISOString() : null,
        btcTurnRiskPrice: btcTurnRisk?.price,
        btcTurnRiskBottomBounce: Boolean(btcTurnRisk?.bottomBounce),
        btcTurnRiskTopReject: Boolean(btcTurnRisk?.topReject),
        btcIndependentShort: sig.btcIndependentShort,
        btcStrongShortEma99,
        btcDynamicEntry: Boolean(v.btcDynamicEntry),
        btcDynamicLocked: Boolean(v.btcDynamicEntry
          && shakeoutBtcTrendSupportsSide(side, sig.btcRegime)),
        btcAnchorPrice,
        btcLastPrice: btcAnchorPrice,
        btcDynamicBaseEntry: v.entryPrice,
        btcDynamicMaxPct,
        btcDynamicBeta: sig.btcRelation?.beta,
        btcDynamicRiskPct: finalRiskPct,
        btcDynamicRr: finalRr,
      }).catch((e) => console.warn(`[ShakeoutPaper] auto-fire ${v.variant} ${sig.symbol}:`, e.message));
    }
    // đánh dấu side active để chặn chiều ngược trong cùng batch scan
    if (!activeSide.has(sig.symbol)) activeSide.set(sig.symbol, new Set());
    activeSide.get(sig.symbol).add(side);
  }
}

// Top Reversal Paper Trades - isolated from Shakeout paper history.
async function readTopReversalPaperStore() {
  try {
    const parsed = JSON.parse(await readFile(TOP_REVERSAL_PAPER_FILE, 'utf8'));
    return Array.isArray(parsed?.trades) ? parsed : { trades: [] };
  } catch {
    return { trades: [] };
  }
}

let _topReversalPaperWriteLock = Promise.resolve();
async function writeTopReversalPaperStore(store) {
  _topReversalPaperWriteLock = _topReversalPaperWriteLock
    .then(() => atomicWriteJson(TOP_REVERSAL_PAPER_FILE, store));
  return _topReversalPaperWriteLock;
}

function getTopReversalPaperMark(symbol) {
  const mark = Number(topReversalSocketMarks.get(String(symbol ?? '').toUpperCase()));
  return Number.isFinite(mark) && mark > 0 ? mark : null;
}

function enrichTopReversalPaperTrade(trade, markPrice) {
  const mark = Number(markPrice);
  const hasMark = Number.isFinite(mark) && mark > 0;
  const entry = Number(trade.entryPrice);
  const quantity = Number(trade.quantity);
  const margin = Number(trade.marginUsdt);
  const pnl = trade.status === 'OPEN' && hasMark
    ? (entry - mark) * quantity
    : trade.pnl ?? null;
  const roe = trade.status === 'OPEN' && margin > 0 && pnl != null
    ? pnl / margin * 100
    : trade.roe ?? null;
  return {
    ...trade,
    markPrice: ['OPEN', 'PENDING'].includes(trade.status) ? (hasMark ? mark : null) : Number(trade.exitPrice ?? entry),
    markUpdatedAt: topReversalSocketMarkAt.get(String(trade.symbol ?? '').toUpperCase()) ?? null,
    pnl,
    roe,
  };
}

function calcTopReversalPaperRoeAt(trade, markPrice) {
  const entry = Number(trade?.entryPrice);
  const quantity = Number(trade?.quantity);
  const margin = Number(trade?.marginUsdt);
  const mark = Number(markPrice);
  if (![entry, quantity, margin, mark].every(Number.isFinite)
      || entry <= 0 || quantity <= 0 || margin <= 0 || mark <= 0) return null;
  const pnl = (entry - mark) * quantity;
  return pnl / margin * 100;
}

function getTopReversalDefaultSlPrice(entryPrice, leverage) {
  const entry = Number(entryPrice);
  const lev = Number(leverage);
  const slRoe = Math.abs(Number(process.env.TOP_REVERSAL_PAPER_DEFAULT_SL_ROE ?? 20));
  if (![entry, lev, slRoe].every(Number.isFinite) || entry <= 0 || lev <= 0 || slRoe <= 0) return null;
  return entry * (1 + slRoe / 100 / lev);
}

function isTopReversalEarlyScout(trade) {
  return String(trade?.source ?? '').startsWith('top-reversal-early-')
    || String(trade?.qualityTier ?? '').toUpperCase() === 'EARLY_CONFIRMED'
    || String(trade?.stage ?? '').toUpperCase() === 'TOP_EARLY_CONFIRMED';
}

function getTopReversalEarlyFailFastConfig() {
  return {
    enabled: process.env.TOP_REVERSAL_PAPER_EARLY_FAIL_FAST !== 'false',
    maxAgeMs: Math.max(
      60_000,
      Number(process.env.TOP_REVERSAL_PAPER_EARLY_FAIL_FAST_MS ?? 15 * 60_000),
    ),
    maxLossRoe: -Math.abs(Number(process.env.TOP_REVERSAL_PAPER_EARLY_FAIL_FAST_ROE ?? 15)),
    minPeakRoe: Math.max(
      0,
      Number(process.env.TOP_REVERSAL_PAPER_EARLY_FAIL_FAST_MIN_PEAK_ROE ?? 5),
    ),
  };
}

function getTopReversalEarlyPendingConfig() {
  return {
    enabled: process.env.TOP_REVERSAL_PAPER_EARLY_PENDING_LIMIT !== 'false',
    ttlMs: Math.max(
      5 * 60_000,
      Number(process.env.TOP_REVERSAL_PAPER_EARLY_PENDING_TTL_MS ?? 4 * 3600_000),
    ),
    bufferPct: Math.max(
      0,
      Number(process.env.TOP_REVERSAL_PAPER_EARLY_PENDING_BUFFER_PCT ?? 2),
    ),
    marginUsdt: Number(process.env.TOP_REVERSAL_PAPER_EARLY_PENDING_MARGIN_USDT ?? process.env.TOP_REVERSAL_PAPER_SCOUT_MARGIN_USDT ?? 1),
  };
}

function getTopReversalBtcLog(signal = {}, health = btcHealthCache.data) {
  const relation = signal.btcRelation ?? getTopReversalBtcRelation(signal.symbol);
  const regime = emaSqueezeBtcRegime(health);
  const bias = health?.bias ?? 'unknown';
  const trendDir = health?.btcTrendDir ?? '-';
  const trendScore = health?.btcTrendScore ?? '-';
  const pct6h = Number(health?.pct6h);
  const rsi1h = Number(health?.rsi1h);
  const rel = relation?.relation ?? 'noRel';
  const corr = relation?.corr ?? '-';
  const btcMove = relation?.btcMovePct ?? '-';
  const coinMove = relation?.coinMovePct ?? '-';
  return {
    note: [
      `btcBias=${bias}`,
      `btcRegime=${regime}`,
      `btcTrend=${trendDir}:${trendScore}`,
      `btcPct6h=${Number.isFinite(pct6h) ? pct6h.toFixed(2) : '-'}`,
      `btcRsi1h=${Number.isFinite(rsi1h) ? rsi1h.toFixed(1) : '-'}`,
      `btcRel=${rel}`,
      `btcCorr=${corr}`,
      `btcMove=${btcMove}`,
      `coinMove=${coinMove}`,
    ].join(' | '),
    health: health && !health.error ? {
      regime,
      bias,
      bearPoints: health.bearPoints ?? null,
      bullBias: health.bullBias ?? null,
      bullPoints: health.bullPoints ?? null,
      rsi1h: health.rsi1h ?? null,
      rsi4h: health.rsi4h ?? null,
      pct6h: health.pct6h ?? null,
      emaTrend1h: health.emaTrend1h ?? null,
      obvTrend: health.obvTrend ?? null,
      btcTrendScore: health.btcTrendScore ?? null,
      btcTrendDir: health.btcTrendDir ?? null,
      btcCandle1hPct: health.btcCandle1hPct ?? null,
      at: health.at ?? null,
    } : null,
    relation,
  };
}

function calcTopReversalEarlyPendingLimitPrice(signal = {}) {
  const cfg = getTopReversalEarlyPendingConfig();
  const mark = Number(signal.markPrice ?? signal.entry);
  const planned = Number(signal.entry);
  if (!Number.isFinite(mark) || mark <= 0) return planned;
  const buffered = mark * (1 + cfg.bufferPct / 100);
  if (Number.isFinite(planned) && planned > mark) return Math.max(planned, buffered);
  return buffered;
}

async function getTopReversalPaperTrades() {
  const store = await readTopReversalPaperStore();
  const trades = store.trades.map((trade) =>
    enrichTopReversalPaperTrade(trade, getTopReversalPaperMark(trade.symbol)));
  const closed = trades.filter((trade) => trade.status === 'CLOSED');
  const wins = closed.filter((trade) => Number(trade.pnl) > 0).length;
  const dailyMap = new Map();
  for (const trade of closed) {
    const date = String(trade.closedAt ?? trade.createdAt ?? '').slice(0, 10);
    if (!date) continue;
    const row = dailyMap.get(date) ?? { date, orders: 0, wins: 0, losses: 0, pnl: 0, roe: 0 };
    row.orders++;
    if (Number(trade.pnl) > 0) row.wins++;
    else row.losses++;
    row.pnl += Number(trade.pnl ?? 0);
    row.roe += Number(trade.roe ?? 0);
    dailyMap.set(date, row);
  }
  const daily = [...dailyMap.values()]
    .map((row) => ({
      ...row,
      pnl: Number(row.pnl.toFixed(4)),
      roe: Number(row.roe.toFixed(1)),
      winRate: row.orders ? Number((row.wins / row.orders * 100).toFixed(1)) : 0,
    }))
    .sort((a, b) => b.date.localeCompare(a.date));
  return {
    trades,
    summary: {
      total: trades.length,
      open: trades.filter((trade) => trade.status === 'OPEN').length,
      closed: closed.length,
      wins,
      losses: closed.length - wins,
      winRate: closed.length ? Number((wins / closed.length * 100).toFixed(1)) : 0,
      pnl: Number(closed.reduce((sum, trade) => sum + Number(trade.pnl ?? 0), 0).toFixed(4)),
      dcaActive: trades.filter((trade) => trade.status === 'OPEN' && trade.dcaTaken).length,
      trailActive: trades.filter((trade) =>
        trade.status === 'OPEN' && Number.isFinite(Number(trade.sl)) && Number(trade.sl) > 0).length,
    },
    daily,
  };
}

async function createTopReversalPaperTrade(payload) {
  const symbol = String(payload.symbol ?? '').toUpperCase();
  const entryPrice = Number(payload.entryPrice ?? payload.entry);
  const marginUsdt = Number(payload.marginUsdt ?? process.env.TOP_REVERSAL_PAPER_MARGIN_USDT ?? 5);
  const leverage = Math.max(1, Number(payload.leverage ?? process.env.TOP_REVERSAL_PAPER_LEVERAGE ?? 5));
  const requestedStatus = String(payload.status ?? 'OPEN').toUpperCase() === 'PENDING' ? 'PENDING' : 'OPEN';
  if (!symbol || !Number.isFinite(entryPrice) || entryPrice <= 0) {
    throw new Error('invalid top reversal paper entry');
  }
  const store = await readTopReversalPaperStore();
  const duplicate = requestedStatus === 'OPEN'
    ? store.trades.find((trade) => trade.symbol === symbol && trade.status === 'OPEN')
    : store.trades.find((trade) =>
      trade.symbol === symbol
      && trade.status === 'PENDING'
      && String(trade.source ?? '') === String(payload.source ?? 'top-reversal-auto').slice(0, 80));
  if (duplicate) return { trade: enrichTopReversalPaperTrade(duplicate, getTopReversalPaperMark(symbol)) };
  const defaultSl = getTopReversalDefaultSlPrice(entryPrice, leverage);

  const trade = {
    id: crypto.randomUUID(),
    symbol,
    side: 'SHORT',
    status: requestedStatus,
    orderType: requestedStatus === 'PENDING' ? 'LIMIT' : 'MARKET',
    marginUsdt,
    leverage,
    quantity: marginUsdt * leverage / entryPrice,
    originalQuantity: marginUsdt * leverage / entryPrice,
    entryPrice,
    fillPrice: entryPrice,
    sl: Number.isFinite(Number(payload.sl)) && Number(payload.sl) > 0 ? Number(payload.sl) : defaultSl,
    tp: Number(payload.tp),
    runnerTp: Number(payload.runnerTp ?? payload.tp),
    score: Number(payload.score ?? 0),
    stage: String(payload.stage ?? 'TOP_CONFIRMED'),
    source: String(payload.source ?? 'top-reversal-auto').slice(0, 80),
    note: [
      String(payload.note ?? ''),
      defaultSl ? `defaultSL=${Math.abs(Number(process.env.TOP_REVERSAL_PAPER_DEFAULT_SL_ROE ?? 20))}%ROE@${defaultSl}` : '',
    ].filter(Boolean).join(' | ').slice(0, 500),
    signalGood: Boolean(payload.signalGood),
    signalGoodStrong: Boolean(payload.signalGoodStrong),
    qualityBreakdown: Boolean(payload.qualityBreakdown),
    qualityDcaEligible: Boolean(payload.qualityDcaEligible),
    qualityTier: String(payload.qualityTier ?? (payload.qualityBreakdown ? 'QUALITY' : 'SCOUT_ONLY')).slice(0, 32),
    qualityReasons: Array.isArray(payload.qualityReasons)
      ? payload.qualityReasons.map((reason) => String(reason).slice(0, 48)).slice(0, 8)
      : [],
    btcHealth: payload.btcHealth ?? null,
    btcRelation: payload.btcRelation ?? null,
    btcLog: payload.btcLog ? String(payload.btcLog).slice(0, 300) : null,
    hardBreakdownCount: Number.isFinite(Number(payload.hardBreakdownCount))
      ? Number(payload.hardBreakdownCount)
      : null,
    blowoffTop: Boolean(payload.blowoffTop),
    volumeDistribution: Boolean(payload.volumeDistribution),
    strongCase: Boolean(payload.strongCase),
    strongCaseType: String(payload.strongCaseType ?? '').slice(0, 40),
    strongCaseScore: Number.isFinite(Number(payload.strongCaseScore))
      ? Number(payload.strongCaseScore)
      : null,
    strongCaseReasons: Array.isArray(payload.strongCaseReasons)
      ? payload.strongCaseReasons.map((reason) => String(reason).slice(0, 64)).slice(0, 8)
      : [],
    dcaTaken: false,
    peakRoe: 0,
    slTrailLockRoe: null,
    pnl: null,
    roe: null,
    outcome: null,
    createdAt: new Date().toISOString(),
    openedAt: requestedStatus === 'OPEN' ? new Date().toISOString() : null,
    expiresAt: requestedStatus === 'PENDING' && Number.isFinite(Number(payload.expiresAtMs))
      ? new Date(Number(payload.expiresAtMs)).toISOString()
      : requestedStatus === 'PENDING' && Number.isFinite(Number(payload.ttlMs))
        ? new Date(Date.now() + Number(payload.ttlMs)).toISOString()
        : null,
    closedAt: null,
  };
  store.trades.unshift(trade);
  await writeTopReversalPaperStore(store);
  syncTopReversalPaperTicker().catch(() => {});
  scheduleTopReversalPaperBroadcast(50);
  console.log(`[TopReversalPaper] ${requestedStatus} SHORT ${symbol} $${marginUsdt} entry=${entryPrice} score=${trade.score}`);
  return { trade: enrichTopReversalPaperTrade(trade, getTopReversalPaperMark(symbol)) };
}

async function expireTopReversalPendingTrade(trade, reason = 'EXPIRED') {
  const store = await readTopReversalPaperStore();
  const idx = store.trades.findIndex((row) => row.id === trade.id && row.status === 'PENDING');
  if (idx < 0) return null;
  store.trades[idx] = {
    ...store.trades[idx],
    status: 'EXPIRED',
    outcome: reason,
    pnl: 0,
    roe: 0,
    closedAt: new Date().toISOString(),
    note: [
      String(store.trades[idx].note ?? ''),
      `pendingExpired=${reason}`,
    ].filter(Boolean).join(' | ').slice(0, 1000),
  };
  await writeTopReversalPaperStore(store);
  scheduleTopReversalPaperBroadcast(50);
  console.log(`[TopReversalPaper] ${reason} ${trade.symbol} pending limit entry=${trade.entryPrice}`);
  return store.trades[idx];
}

async function fillTopReversalPendingTrade(trade, fillPrice) {
  const store = await readTopReversalPaperStore();
  const idx = store.trades.findIndex((row) => row.id === trade.id && row.status === 'PENDING');
  if (idx < 0) return null;
  const row = store.trades[idx];
  const entry = Number(fillPrice ?? row.entryPrice);
  if (!Number.isFinite(entry) || entry <= 0) return null;
  const margin = Number(row.marginUsdt);
  const leverage = Number(row.leverage);
  store.trades[idx] = {
    ...row,
    status: 'OPEN',
    orderType: 'LIMIT_FILLED',
    entryPrice: entry,
    fillPrice: entry,
    quantity: margin * leverage / entry,
    originalQuantity: margin * leverage / entry,
    openedAt: new Date().toISOString(),
    expiresAt: null,
    note: [
      String(row.note ?? ''),
      `pendingFilled=${entry}`,
    ].filter(Boolean).join(' | ').slice(0, 500),
  };
  await writeTopReversalPaperStore(store);
  syncTopReversalPaperTicker().catch(() => {});
  scheduleTopReversalPaperBroadcast(50);
  console.log(`[TopReversalPaper] FILLED SHORT ${trade.symbol} limit=${entry}`);
  return store.trades[idx];
}

async function closeTopReversalPaperTrade(payload) {
  const store = await readTopReversalPaperStore();
  const idx = store.trades.findIndex((trade) => trade.id === payload.id);
  if (idx < 0) throw new Error('Top reversal paper trade not found');
  const trade = store.trades[idx];
  if (trade.status === 'CLOSED' || trade.status === 'EXPIRED') return { trade };
  if (trade.status === 'PENDING') {
    const expired = await expireTopReversalPendingTrade(trade, String(payload.outcome ?? 'MANUAL_CANCEL'));
    return { trade: expired ?? trade };
  }
  const exitPrice = Number(payload.exitPrice ?? getTopReversalPaperMark(trade.symbol));
  if (!Number.isFinite(exitPrice) || exitPrice <= 0) throw new Error('socket price not ready');
  const pnl = (Number(trade.entryPrice) - exitPrice) * Number(trade.quantity);
  const roe = pnl / Number(trade.marginUsdt) * 100;
  store.trades[idx] = {
    ...trade,
    status: 'CLOSED',
    exitPrice,
    pnl,
    roe,
    outcome: String(payload.outcome ?? 'MANUAL'),
    note: [
      String(trade.note ?? ''),
      payload.noteAppend ? String(payload.noteAppend) : '',
    ].filter(Boolean).join(' | ').slice(0, 500),
    closedAt: new Date().toISOString(),
  };
  await writeTopReversalPaperStore(store);
  syncTopReversalPaperTicker().catch(() => {});
  scheduleTopReversalPaperBroadcast(50);
  return { trade: store.trades[idx] };
}

async function deleteTopReversalPaperTrade(payload) {
  const store = await readTopReversalPaperStore();
  store.trades = store.trades.filter((trade) => trade.id !== payload.id);
  await writeTopReversalPaperStore(store);
  syncTopReversalPaperTicker().catch(() => {});
  scheduleTopReversalPaperBroadcast(50);
  return { ok: true };
}

async function applyTopReversalBtcShiftPaper(signal, btcGate, btcRelation) {
  if (process.env.TOP_REVERSAL_BTC_SHIFT_PAPER_ENABLED === 'false') return false;
  const symbol = String(signal?.symbol ?? '').toUpperCase();
  const markPrice = Number(signal?.markPrice ?? signal?.entry);
  if (!symbol || !Number.isFinite(markPrice) || markPrice <= 0) return false;
  if (!btcGate?.ok || btcRelation?.relation !== 'aligned') return false;

  const cooldownMs = Number(process.env.TOP_REVERSAL_BTC_SHIFT_PAPER_COOLDOWN_MS ?? 90 * 60_000);
  const key = `${symbol}|BTC_SHIFT`;
  const last = topReversalPaperAutoFired.get(key) ?? 0;
  if (Date.now() - last < cooldownMs) return false;

  const addMargin = Number(process.env.TOP_REVERSAL_BTC_SHIFT_PAPER_MARGIN_USDT ?? 10);
  const store = await readTopReversalPaperStore();
  const idx = store.trades.findIndex((trade) =>
    trade.symbol === symbol
    && trade.status === 'OPEN'
    && trade.side === 'SHORT');
  if (idx >= 0) {
    const row = store.trades[idx];
    if (row.btcShiftDcaTaken) return false;
    const existingRoe = calcTopReversalPaperRoeAt(row, markPrice);
    const maxRoe = Number(process.env.TOP_REVERSAL_BTC_SHIFT_DCA_MAX_ROE ?? 5);
    const maxPeak = Number(process.env.TOP_REVERSAL_BTC_SHIFT_DCA_MAX_PEAK_ROE ?? 15);
    if (Number.isFinite(existingRoe) && existingRoe > maxRoe) return false;
    if (Number(row.peakRoe ?? 0) > maxPeak) return false;

    const leverage = Math.max(1, Number(row.leverage ?? process.env.TOP_REVERSAL_PAPER_LEVERAGE ?? 5));
    const oldQty = Number(row.quantity);
    const addQty = addMargin * leverage / markPrice;
    const nextQty = oldQty + addQty;
    const nextMargin = Number(row.marginUsdt) + addMargin;
    const avgEntry = nextQty > 0
      ? ((Number(row.entryPrice) * oldQty) + (markPrice * addQty)) / nextQty
      : Number(row.entryPrice);
    store.trades[idx] = {
      ...row,
      marginUsdt: nextMargin,
      quantity: nextQty,
      originalQuantity: Number(row.originalQuantity ?? oldQty) + addQty,
      entryPrice: avgEntry,
      fillPrice: avgEntry,
      tp: Number(signal.tp ?? row.tp),
      runnerTp: Number(signal.runnerTp ?? row.runnerTp ?? signal.tp ?? row.tp),
      dcaTaken: true,
      dcaPrice: markPrice,
      dcaMarginUsdt: addMargin,
      dcaAt: new Date().toISOString(),
      btcShiftDcaTaken: true,
      btcShiftDcaAt: new Date().toISOString(),
      btcRelation,
      btcShiftGate: btcGate,
      note: [
        String(row.note ?? ''),
        `BTC_SHIFT_DCA=$${addMargin}@${markPrice}`,
        `avgEntry=${avgEntry}`,
        btcGate.reason,
        `btcCorr=${btcRelation.corr}`,
      ].filter(Boolean).join(' | ').slice(0, 1000),
    };
    await writeTopReversalPaperStore(store);
    topReversalPaperAutoFired.set(key, Date.now());
    syncTopReversalPaperTicker().catch(() => {});
    scheduleTopReversalPaperBroadcast(50);
    console.log(`[TopReversalPaper] BTC_SHIFT DCA SHORT ${symbol} +$${addMargin} mark=${markPrice} corr=${btcRelation.corr}`);
    return true;
  }

  topReversalPaperAutoFired.set(key, Date.now());
  const btcLog = getTopReversalBtcLog(signal, btcHealthCache.data);
  await createTopReversalPaperTrade({
    symbol,
    entryPrice: markPrice,
    marginUsdt: addMargin,
    tp: signal.tp,
    runnerTp: signal.runnerTp,
    score: signal.score,
    stage: 'BTC_SHIFT_SHORT',
    source: `top-reversal-btc-shift-${signal.score}`,
    note: [
      btcLog.note,
      String(signal.note ?? '').replace('paper=NO', 'paper=BTC_SHIFT'),
      `BTC_SHIFT_MARKET=$${addMargin}`,
      btcGate.reason,
      `btcCorr=${btcRelation.corr}`,
      `btcMove=${btcRelation.btcMovePct}%`,
      `coinMove=${btcRelation.coinMovePct}%`,
    ].filter(Boolean).join(' | '),
    qualityBreakdown: signal.qualityBreakdown,
    qualityDcaEligible: false,
    qualityTier: 'BTC_SHIFT',
    qualityReasons: signal.qualityReasons,
    btcHealth: btcLog.health,
    btcRelation: btcLog.relation ?? btcRelation,
    btcLog: btcLog.note,
    hardBreakdownCount: signal.hardBreakdownCount,
    blowoffTop: signal.blowoffTop,
    volumeDistribution: signal.volumeDistribution,
  });
  return true;
}

const topReversalDcaLocks = new Set();
const topReversalTrailLocks = new Set();

function getTopReversalTrailLockRoe(peakRoe) {
  const startRoe = Math.max(
    0,
    Number(process.env.TOP_REVERSAL_PAPER_TRAIL_START_ROE ?? 15),
  );
  if (peakRoe < startRoe) return null;
  if (peakRoe < 20) return 0;
  return Math.max(0, Math.floor((peakRoe - 10) / 5) * 5);
}

function getClosedCachedKlines(symbol, interval, limit) {
  const now = Date.now();
  const klines = klineCache.getIfCached(symbol, interval, limit);
  if (!Array.isArray(klines) || klines.length === 0) return [];
  return klines.filter((k) => Number(k?.closeTime ?? 0) <= now).slice(-limit);
}

function getTopReversalTrailConfirmation(symbol) {
  const interval = String(process.env.TOP_REVERSAL_PAPER_TRAIL_CONFIRM_INTERVAL ?? '5m');
  const klines = getClosedCachedKlines(symbol, interval, 80);
  const closes = klines.map((k) => Number(k.close)).filter(Number.isFinite);
  const last = klines.at(-1);
  let closeBelowEma = false;
  let redContinuation = false;
  let ema13 = null;
  let ema25 = null;
  let redBars = 0;
  let redWindow = 0;

  if (closes.length >= 30 && last) {
    ema13 = computeEMA(closes, 13);
    ema25 = computeEMA(closes, 25);
    const close = Number(last.close);
    closeBelowEma = Number.isFinite(close)
      && Number.isFinite(ema13)
      && Number.isFinite(ema25)
      && close < ema13
      && close < ema25;

    redWindow = Math.max(1, Number(process.env.TOP_REVERSAL_PAPER_TRAIL_CONFIRM_RED_WINDOW ?? 3));
    const minRed = Math.max(1, Number(process.env.TOP_REVERSAL_PAPER_TRAIL_CONFIRM_RED_BARS ?? 2));
    const recent = klines.slice(-redWindow);
    redBars = recent.filter((k) => Number(k.close) < Number(k.open)).length;
    redContinuation = recent.length >= redWindow && redBars >= minRed;
  }

  const btcRegime = emaSqueezeBtcRegime(btcHealthCache.data);
  const btcNotBouncing = btcRegime !== 'STRONG';
  const ok = closeBelowEma || redContinuation || btcNotBouncing;
  return {
    ok,
    closeBelowEma,
    redContinuation,
    btcNotBouncing,
    btcRegime,
    interval,
    redBars,
    redWindow,
    ema13,
    ema25,
    close: Number(last?.close),
    reason: [
      closeBelowEma ? `close<EMA13/25 ${interval}` : '',
      redContinuation ? `red ${redBars}/${redWindow} ${interval}` : '',
      btcNotBouncing ? `BTC_${btcRegime}` : '',
    ].filter(Boolean).join('+') || `no confirm ${interval} BTC_${btcRegime}`,
  };
}

async function updateTopReversalPaperTrail(trade, markPrice) {
  if (process.env.TOP_REVERSAL_PAPER_TRAIL_ENABLED === 'false') return trade;
  if (trade.status !== 'OPEN' || topReversalTrailLocks.has(trade.id)) return trade;
  const qualityTier = String(trade.qualityTier ?? (trade.qualityBreakdown ? 'QUALITY' : 'SCOUT_ONLY')).toUpperCase();
  if (trade.dcaTaken && ['QUALITY', 'VOLUME_DISTRIBUTION'].includes(qualityTier)) {
    return trade;
  }
  const entry = Number(trade.entryPrice);
  const margin = Number(trade.marginUsdt);
  const quantity = Number(trade.quantity);
  const mark = Number(markPrice);
  if (![entry, margin, quantity, mark].every(Number.isFinite)
      || entry <= 0 || margin <= 0 || quantity <= 0 || mark <= 0) return trade;

  const roe = ((entry - mark) * quantity / margin) * 100;
  const peakRoe = Math.max(Number(trade.peakRoe ?? 0), roe);
  const rawLockRoe = getTopReversalTrailLockRoe(peakRoe);
  const skipEarlyBreakeven = rawLockRoe === 0
    && (trade.qualityDcaEligible === true || ['QUALITY', 'VOLUME_DISTRIBUTION'].includes(qualityTier));
  const needsConfirmation = rawLockRoe != null && !skipEarlyBreakeven
    && process.env.TOP_REVERSAL_PAPER_TRAIL_CONFIRM_ENABLED !== 'false';
  const confirmation = needsConfirmation
    ? getTopReversalTrailConfirmation(trade.symbol)
    : { ok: true, reason: '' };
  const lockRoe = skipEarlyBreakeven || !confirmation.ok ? null : rawLockRoe;
  const currentLock = trade.slTrailLockRoe != null && Number.isFinite(Number(trade.slTrailLockRoe))
    ? Number(trade.slTrailLockRoe)
    : -Infinity;
  const shouldMoveSl = lockRoe != null && lockRoe > currentLock;
  const shouldPersistPeak = peakRoe > Number(trade.peakRoe ?? 0) + 0.05;
  if (!shouldMoveSl && !shouldPersistPeak) return trade;

  const newSl = shouldMoveSl
    ? entry - (margin * lockRoe / 100) / quantity
    : Number(trade.sl);
  topReversalTrailLocks.add(trade.id);
  try {
    const latest = await readTopReversalPaperStore();
    const idx = latest.trades.findIndex((row) => row.id === trade.id && row.status === 'OPEN');
    if (idx < 0) return trade;
    const row = latest.trades[idx];
    latest.trades[idx] = {
      ...row,
      peakRoe,
      ...(shouldMoveSl ? {
        sl: newSl,
        slTrailLockRoe: lockRoe,
        slTrailUpdatedAt: new Date().toISOString(),
      } : {}),
      note: [
        String(row.note ?? ''),
        shouldMoveSl ? `topReversalTrail=${lockRoe}%@${newSl}` : '',
        shouldMoveSl && confirmation.reason ? `topReversalTrailConfirm=${confirmation.reason}` : '',
        skipEarlyBreakeven && shouldPersistPeak ? `topReversalSkipBE=quality peak=${peakRoe.toFixed(1)}%` : '',
        needsConfirmation && !confirmation.ok && shouldPersistPeak ? `topReversalWaitConfirm=${confirmation.reason} peak=${peakRoe.toFixed(1)}%` : '',
        shouldPersistPeak && !shouldMoveSl ? `topReversalPeak=${peakRoe.toFixed(1)}%` : '',
      ].filter(Boolean).join(' | ').slice(0, 500),
    };
    await writeTopReversalPaperStore(latest);
    scheduleTopReversalPaperBroadcast(50);
    if (shouldMoveSl) {
      console.log(
        `[TopReversalPaper] TRAIL SHORT ${row.symbol}`
        + ` peak=${peakRoe.toFixed(1)}% lock=${lockRoe}% sl=${newSl}`,
      );
    }
    return latest.trades[idx];
  } finally {
    topReversalTrailLocks.delete(trade.id);
  }
}

async function processTopReversalPaperPrice(symbol, markPrice) {
  const store = await readTopReversalPaperStore();
  const openTrades = store.trades.filter((trade) =>
    ['OPEN', 'PENDING'].includes(trade.status) && trade.symbol === symbol);
  for (const trade of openTrades) {
    if (trade.status === 'PENDING') {
      const expiresAt = Date.parse(trade.expiresAt ?? 0);
      if (Number.isFinite(expiresAt) && expiresAt > 0 && Date.now() >= expiresAt) {
        await expireTopReversalPendingTrade(trade, 'EXPIRED_4H');
        continue;
      }
      const entry = Number(trade.entryPrice);
      if (Number.isFinite(entry) && entry > 0 && markPrice >= entry) {
        await fillTopReversalPendingTrade(trade, entry);
      }
      continue;
    }
    if (Number.isFinite(Number(trade.tp)) && markPrice <= Number(trade.tp)) {
      await closeTopReversalPaperTrade({ id: trade.id, exitPrice: Number(trade.tp), outcome: 'TP' });
      continue;
    }
    if (Number.isFinite(Number(trade.sl)) && Number(trade.sl) > 0
        && markPrice >= Number(trade.sl)) {
      await closeTopReversalPaperTrade({
        id: trade.id,
        exitPrice: Number(trade.sl),
        outcome: Number.isFinite(Number(trade.slTrailLockRoe))
          ? (Number(trade.slTrailLockRoe) > 0 ? 'TRAIL_SL' : 'BREAKEVEN')
          : 'SL',
      });
      continue;
    }
    // Hard SL cap: chặn tail catastrophe (đỉnh giả, coin pump tiếp) cho lệnh scout/no-SL.
    // VELVET -560% là do short không stop khi giá +112%. Cap ROE ≤ -X% -> đóng tại mark.
    if (isTopReversalEarlyScout(trade)) {
      const cfg = getTopReversalEarlyFailFastConfig();
      if (cfg.enabled) {
        const roe = calcTopReversalPaperRoeAt(trade, markPrice);
        const openedAt = Date.parse(trade.openedAt ?? trade.createdAt ?? 0);
        const ageMs = Number.isFinite(openedAt) ? Date.now() - openedAt : 0;
        const peakRoe = Number(trade.peakRoe ?? 0);
        const ageMin = ageMs / 60_000;
        if (Number.isFinite(roe) && roe <= cfg.maxLossRoe) {
          await closeTopReversalPaperTrade({
            id: trade.id,
            exitPrice: markPrice,
            outcome: 'EARLY_FAIL_FAST_ROE',
            noteAppend: `EARLY_FAIL_FAST_ROE roe=${roe.toFixed(1)}%<=${cfg.maxLossRoe}% peak=${peakRoe.toFixed(1)}%`,
          });
          console.log(`[TopReversalPaper] EARLY_FAIL_FAST_ROE ${trade.symbol} roe=${roe.toFixed(1)}% <= ${cfg.maxLossRoe}% exit=${markPrice}`);
          continue;
        }
        if (ageMs >= cfg.maxAgeMs && peakRoe < cfg.minPeakRoe) {
          await closeTopReversalPaperTrade({
            id: trade.id,
            exitPrice: markPrice,
            outcome: 'EARLY_FAIL_FAST_TIME',
            noteAppend: `EARLY_FAIL_FAST_TIME age=${ageMin.toFixed(1)}m>=${(cfg.maxAgeMs / 60_000).toFixed(0)}m peak=${peakRoe.toFixed(1)}%<${cfg.minPeakRoe}%`,
          });
          console.log(`[TopReversalPaper] EARLY_FAIL_FAST_TIME ${trade.symbol} age=${ageMin.toFixed(1)}m peak=${peakRoe.toFixed(1)}% < ${cfg.minPeakRoe}% exit=${markPrice}`);
          continue;
        }
      }
    }
    if (process.env.TOP_REVERSAL_PAPER_HARD_SL !== 'false') {
      const capRoe = -Math.abs(Number(process.env.TOP_REVERSAL_PAPER_HARD_SL_ROE ?? 100));
      const capPnl = (Number(trade.entryPrice) - markPrice) * Number(trade.quantity);
      const capCurRoe = Number(trade.marginUsdt) > 0 ? capPnl / Number(trade.marginUsdt) * 100 : 0;
      if (capCurRoe <= capRoe) {
        await closeTopReversalPaperTrade({ id: trade.id, exitPrice: markPrice, outcome: 'HARD_SL' });
        console.log(`[TopReversalPaper] HARD_SL ${trade.symbol} roe=${capCurRoe.toFixed(0)}% <= ${capRoe}% (cap tail) exit=${markPrice}`);
        continue;
      }
    }
    // SL cho nhóm "loại tốt" (scout no-DCA): chặn bleed sớm thay vì để trôi tới hard-cap -100%.
    // Vì nhóm này không cho DCA, không có lý do nhồi thêm — cắt lỗ ở mức cố định.
    const isGoodTrade = trade.signalGood != null ? Boolean(trade.signalGood) : isGoodTopReversal(trade);
    if (process.env.TOP_REVERSAL_PAPER_SCOUT_SL !== 'false' && isGoodTrade && !trade.dcaTaken) {
      const scoutSlRoe = -Math.abs(Number(process.env.TOP_REVERSAL_PAPER_SCOUT_SL_ROE ?? 45));
      const sPnl = (Number(trade.entryPrice) - markPrice) * Number(trade.quantity);
      const sRoe = Number(trade.marginUsdt) > 0 ? sPnl / Number(trade.marginUsdt) * 100 : 0;
      if (sRoe <= scoutSlRoe) {
        await closeTopReversalPaperTrade({ id: trade.id, exitPrice: markPrice, outcome: 'SCOUT_SL' });
        console.log(`[TopReversalPaper] SCOUT_SL ${trade.symbol} roe=${sRoe.toFixed(0)}% <= ${scoutSlRoe}% (loại tốt cắt lỗ) exit=${markPrice}`);
        continue;
      }
    }
    await updateTopReversalPaperTrail(trade, markPrice);
    if (trade.dcaTaken || topReversalDcaLocks.has(trade.id)) continue;
    const pnl = (Number(trade.entryPrice) - markPrice) * Number(trade.quantity);
    const roe = pnl / Number(trade.marginUsdt) * 100;
    const trigger = -Math.abs(Number(process.env.TOP_REVERSAL_PAPER_DCA_ROE ?? 25));
    if (roe > trigger) continue;
    if (trade.strongCase) {
      const latest = await readTopReversalPaperStore();
      const idx = latest.trades.findIndex((row) =>
        row.id === trade.id && row.status === 'OPEN' && !row.dcaTaken);
      if (idx >= 0 && latest.trades[idx].dcaBlockedReason !== 'strongCase=$10-test') {
        latest.trades[idx] = {
          ...latest.trades[idx],
          dcaBlockedAt: new Date().toISOString(),
          dcaBlockedReason: 'strongCase=$10-test',
          note: [
            String(latest.trades[idx].note ?? ''),
            `DCA_BLOCKED=strongCase $10 test roe=${roe.toFixed(1)}%`,
          ].filter(Boolean).join(' | ').slice(0, 500),
        };
        await writeTopReversalPaperStore(latest);
        scheduleTopReversalPaperBroadcast(50);
      }
      continue;
    }
    if (!trade.qualityBreakdown) {
      const latest = await readTopReversalPaperStore();
      const idx = latest.trades.findIndex((row) =>
        row.id === trade.id && row.status === 'OPEN' && !row.dcaTaken);
      if (idx >= 0 && latest.trades[idx].dcaBlockedReason !== 'qualityBreakdown=false') {
        latest.trades[idx] = {
          ...latest.trades[idx],
          dcaBlockedAt: new Date().toISOString(),
          dcaBlockedReason: 'qualityBreakdown=false',
          note: [
            String(latest.trades[idx].note ?? ''),
            `DCA_BLOCKED=qualityBreakdown=false roe=${roe.toFixed(1)}%`,
          ].filter(Boolean).join(' | ').slice(0, 500),
        };
        await writeTopReversalPaperStore(latest);
        scheduleTopReversalPaperBroadcast(50);
      }
      continue;
    }
    {
      const latest = await readTopReversalPaperStore();
      const idx = latest.trades.findIndex((row) =>
        row.id === trade.id && row.status === 'OPEN' && !row.dcaTaken);
      if (idx < 0) continue;
      const row = latest.trades[idx];
      const minScore = Number(process.env.TOP_REVERSAL_QUALITY_DCA_MIN_SCORE ?? 65);
      const minPeakRoe = Number(process.env.TOP_REVERSAL_PAPER_DCA_MIN_PEAK_ROE ?? 5);
      const blockReasons = [
        row.qualityDcaEligible !== true ? 'qualityDcaEligible=false' : null,
        Number(row.score ?? 0) < minScore ? `score<${minScore}` : null,
        Number(row.peakRoe ?? 0) < minPeakRoe ? `peakRoe<${minPeakRoe}` : null,
      ].filter(Boolean);
      if (blockReasons.length) {
        const reason = blockReasons.join('+');
        if (row.dcaBlockedReason !== reason) {
          latest.trades[idx] = {
            ...row,
            dcaBlockedAt: new Date().toISOString(),
            dcaBlockedReason: reason,
            note: [
              String(row.note ?? ''),
              `DCA_BLOCKED=${reason} roe=${roe.toFixed(1)}% peak=${Number(row.peakRoe ?? 0).toFixed(1)}%`,
            ].filter(Boolean).join(' | ').slice(0, 500),
          };
          await writeTopReversalPaperStore(latest);
          scheduleTopReversalPaperBroadcast(50);
        }
        continue;
      }
    }

    topReversalDcaLocks.add(trade.id);
    try {
      const latest = await readTopReversalPaperStore();
      const idx = latest.trades.findIndex((row) =>
        row.id === trade.id && row.status === 'OPEN' && !row.dcaTaken);
      if (idx < 0) continue;
      const row = latest.trades[idx];
      const qualityTier = String(row.qualityTier ?? (row.qualityBreakdown ? 'QUALITY' : 'SCOUT_ONLY')).toUpperCase();
      const dcaMargin = qualityTier === 'VOLUME_DISTRIBUTION'
        ? Number(process.env.TOP_REVERSAL_PAPER_VOLUME_DCA_MARGIN_USDT ?? 5)
        : Number(process.env.TOP_REVERSAL_PAPER_DCA_MARGIN_USDT ?? 10);
      const addQty = dcaMargin * Number(row.leverage) / markPrice;
      const totalQty = Number(row.quantity) + addQty;
      const totalMargin = Number(row.marginUsdt) + dcaMargin;
      const averageEntry = (
        Number(row.entryPrice) * Number(row.quantity) + markPrice * addQty
      ) / totalQty;
      latest.trades[idx] = {
        ...row,
        entryBeforeDca: row.entryPrice,
        marginBeforeDca: row.marginUsdt,
        entryPrice: averageEntry,
        marginUsdt: totalMargin,
        quantity: totalQty,
        originalQuantity: totalQty,
        dcaTaken: true,
        dcaPrice: markPrice,
        dcaMarginUsdt: dcaMargin,
        dcaTriggerRoe: trigger,
        dcaAt: new Date().toISOString(),
        sl: null,
        peakRoe: 0,
        slTrailLockRoe: null,
        note: [
          String(row.note ?? ''),
          `DCA=$${dcaMargin}@${markPrice}`,
          `qualityTier=${qualityTier}`,
          `avgEntry=${averageEntry}`,
          'initialNoSL=Y',
          ['QUALITY', 'VOLUME_DISTRIBUTION'].includes(qualityTier)
            ? 'trailOffAfterQualityDca=Y'
            : 'trailFrom=15%ROE',
        ].join(' | ').slice(0, 500),
      };
      await writeTopReversalPaperStore(latest);
      scheduleTopReversalPaperBroadcast(50);
      console.log(`[TopReversalPaper] DCA SHORT ${symbol} +$${dcaMargin} roe=${roe.toFixed(1)}% avg=${averageEntry}`);
    } finally {
      topReversalDcaLocks.delete(trade.id);
    }
  }
}

async function createTopReversalPaperTrades(signals = []) {
  if (process.env.TOP_REVERSAL_PAPER_ENABLED === 'false') return;
  const minScore = Number(process.env.TOP_REVERSAL_PAPER_MIN_SCORE ?? 55);
  const cooldownMs = Number(process.env.TOP_REVERSAL_PAPER_COOLDOWN_MS ?? 4 * 3600_000);
  const allowedStages = new Set(String(process.env.TOP_REVERSAL_PAPER_STAGES ?? 'TOP_CONFIRMED,TOP_EARLY_CONFIRMED')
    .split(',')
    .map((stage) => stage.trim().toUpperCase())
    .filter(Boolean));
  for (const signal of signals) {
    const stage = String(signal.stage ?? '').toUpperCase();
    if (!allowedStages.has(stage) || Number(signal.score) < minScore) continue;
    const isEarlyConfirmed = stage === 'TOP_EARLY_CONFIRMED';
    if (String(signal.action ?? '').toUpperCase() === 'SHORT') {
      // Momentum gate: không short khi coin còn pump mạnh (đỉnh chưa xác nhận) — tránh đu đỉnh coin đang bay
      const mg = getTopReversalMomentumGate(signal.symbol);
      if (!mg.ok) {
        console.log(`[TopReversalPaper] skip ${signal.symbol} SHORT - ${mg.reason}`);
        continue;
      }
      const btcRelation = signal.btcRelation ?? getTopReversalBtcRelation(signal.symbol);
      const btcShiftGate = getTopReversalBtcBearShiftGate(btcHealthCache.data);
      if (btcRelation?.relation === 'aligned' && btcShiftGate.ok) {
        const handled = await applyTopReversalBtcShiftPaper(signal, btcShiftGate, btcRelation)
          .catch((err) => {
            console.warn(`[TopReversalPaper] BTC_SHIFT ${signal.symbol}:`, err.message);
            return false;
          });
        if (handled) continue;
      }
    }
    const key = `${signal.symbol}|${stage}`;
    const last = topReversalPaperAutoFired.get(key) ?? 0;
    if (Date.now() - last < cooldownMs) continue;
    topReversalPaperAutoFired.set(key, Date.now());
    const isStrongCase = Boolean(signal.strongCase);
    const isGoodSignal = isGoodTopReversal(signal);
    // Trong nhóm TỐT còn phân tầng theo backtest:
    //  TỐT MẠNH = TOP_CONFIRMED hoặc score>=60 (WR 82% / +686%) → $10
    //  TỐT YẾU  = EARLY + score<60 (WR 67% / avgLoss -24%)      → $5
    //  XẤU (DCA/quality/strongCase)                             → $1
    const goodStrong = isGoodSignal
      && (String(signal.stage ?? '') === 'TOP_CONFIRMED'
        || Number(signal.score ?? 0) >= Number(process.env.TOP_REVERSAL_PAPER_GOOD_STRONG_MIN_SCORE ?? 60));
    const goodMargin = Number(process.env.TOP_REVERSAL_PAPER_GOOD_MARGIN_USDT ?? 10);
    const goodWeakMargin = Number(process.env.TOP_REVERSAL_PAPER_GOOD_WEAK_MARGIN_USDT ?? 5);
    const badMargin = Number(process.env.TOP_REVERSAL_PAPER_BAD_MARGIN_USDT ?? 1);
    const scoutMargin = !isGoodSignal ? badMargin : goodStrong ? goodMargin : goodWeakMargin;
    const minDcaScore = Number(process.env.TOP_REVERSAL_QUALITY_DCA_MIN_SCORE ?? 65);
    const dcaAllowedBySignal = Boolean(signal.qualityDcaEligible) && Number(signal.score) >= minDcaScore;
    const qualLabel = isGoodSignal ? (goodStrong ? 'GOOD_STRONG' : 'GOOD_WEAK') : 'BAD';
    const dcaText = isStrongCase
      ? `${qualLabel}=$${scoutMargin} | STRONG_CASE ${signal.strongCaseType ?? 'STRONG_PEAK_SIMILAR'} | DCA=NO`
      : dcaAllowedBySignal
      ? `${qualLabel}=$${scoutMargin} | DCA=${signal.qualityTier === 'VOLUME_DISTRIBUTION' ? '$5' : '$10'}@-25%ROE tier=${signal.qualityTier ?? (signal.qualityBreakdown ? 'QUALITY' : 'SCOUT_ONLY')}`
      : `${qualLabel}=$${scoutMargin} | DCA=BLOCKED tier=${signal.qualityTier ?? 'SCOUT_ONLY'}`;
    const earlyFailFast = isEarlyConfirmed ? getTopReversalEarlyFailFastConfig() : null;
    const earlyFailFastText = earlyFailFast?.enabled
      ? `failFast=${Math.round(earlyFailFast.maxAgeMs / 60_000)}m | failFastRoe=${earlyFailFast.maxLossRoe}% | minPeakRoe=${earlyFailFast.minPeakRoe}%`
      : '';
    const btcLog = getTopReversalBtcLog(signal);
	    await createTopReversalPaperTrade({
	      symbol: signal.symbol,
      entryPrice: signal.markPrice ?? signal.entry,
      marginUsdt: scoutMargin,
      tp: signal.tp,
      runnerTp: signal.runnerTp,
      score: signal.score,
      stage: signal.stage,
      note: [
        btcLog.note,
        String(signal.note ?? '').replace('paper=NO', isStrongCase ? 'paper=STRONG_CASE' : isEarlyConfirmed ? 'paper=EARLY_SCOUT' : 'paper=YES'),
        dcaText,
        earlyFailFastText,
        'initialNoSL=Y',
        'trailFrom=15%ROE',
        dcaAllowedBySignal ? 'skipEarlyBE=quality' : '',
      ].filter(Boolean).join(' | '),
      source: isStrongCase ? `top-reversal-strong-${signal.score}` : isEarlyConfirmed ? `top-reversal-early-${signal.score}` : `top-reversal-${signal.score}`,
      signalGood: isGoodSignal,
      signalGoodStrong: goodStrong,
      qualityBreakdown: signal.qualityBreakdown,
      qualityDcaEligible: signal.qualityDcaEligible,
      qualityTier: signal.qualityTier,
      qualityReasons: signal.qualityReasons,
      btcHealth: btcLog.health,
      btcRelation: btcLog.relation,
      btcLog: btcLog.note,
      hardBreakdownCount: signal.hardBreakdownCount,
      blowoffTop: signal.blowoffTop,
      volumeDistribution: signal.volumeDistribution,
      strongCase: signal.strongCase,
      strongCaseType: signal.strongCaseType,
      strongCaseScore: signal.strongCaseScore,
	      strongCaseReasons: signal.strongCaseReasons,
	    }).catch((err) => console.warn(`[TopReversalPaper] ${signal.symbol}:`, err.message));
    if (isEarlyConfirmed) {
      const pendingCfg = getTopReversalEarlyPendingConfig();
      if (pendingCfg.enabled) {
        const pendingEntry = calcTopReversalEarlyPendingLimitPrice(signal);
        await createTopReversalPaperTrade({
          symbol: signal.symbol,
          entryPrice: pendingEntry,
          status: 'PENDING',
          ttlMs: pendingCfg.ttlMs,
          marginUsdt: pendingCfg.marginUsdt,
          tp: signal.tp,
          runnerTp: signal.runnerTp,
          score: signal.score,
          stage: signal.stage,
          note: [
            btcLog.note,
            String(signal.note ?? '').replace('paper=NO', 'paper=EARLY_LIMIT_TEST'),
            `EARLY_PENDING_LIMIT=$${pendingCfg.marginUsdt}@${pendingEntry}`,
            `ttl=${Math.round(pendingCfg.ttlMs / 3600_000)}h`,
            `buffer=${pendingCfg.bufferPct}%`,
            dcaText,
            earlyFailFastText,
            'DCA=NO',
            'test=limit-entry',
          ].filter(Boolean).join(' | '),
          source: `top-reversal-early-limit-${signal.score}`,
          signalGood: isGoodSignal,
      signalGoodStrong: goodStrong,
          qualityBreakdown: signal.qualityBreakdown,
          qualityDcaEligible: false,
          qualityTier: signal.qualityTier ?? 'EARLY_CONFIRMED',
          qualityReasons: signal.qualityReasons,
          btcHealth: btcLog.health,
          btcRelation: btcLog.relation,
          btcLog: btcLog.note,
          hardBreakdownCount: signal.hardBreakdownCount,
          blowoffTop: signal.blowoffTop,
          volumeDistribution: signal.volumeDistribution,
        }).catch((err) => console.warn(`[TopReversalPaper] pending ${signal.symbol}:`, err.message));
      }
    }
	  }
	}

async function syncTopReversalPaperTicker() {
  if (!topReversalPaperTicker) return;
  const store = await readTopReversalPaperStore();
  topReversalPaperTicker.setSymbols(
    [...new Set(store.trades.filter((trade) => ['OPEN', 'PENDING'].includes(trade.status)).map((trade) => trade.symbol))],
  );
}

function queueTopReversalPaperProcessing(symbol, markPrice) {
  topReversalPendingProcess.set(symbol, markPrice);
  if (topReversalProcessTimer || topReversalProcessRunning) return;
  topReversalProcessTimer = setTimeout(async function drain() {
    topReversalProcessTimer = null;
    const next = topReversalPendingProcess.entries().next();
    if (next.done) return;
    const [nextSymbol, nextMark] = next.value;
    topReversalPendingProcess.delete(nextSymbol);
    topReversalProcessRunning = true;
    try {
      await processTopReversalPaperPrice(nextSymbol, Number(nextMark));
    } finally {
      topReversalProcessRunning = false;
      if (topReversalPendingProcess.size) {
        topReversalProcessTimer = setTimeout(drain, 250);
      }
    }
  }, 250);
}

function startTopReversalPaperTicker() {
  if (topReversalPaperTicker) return;
  topReversalPaperTicker = sharedLastTicker.createClient(
    'topReversalPaper',
    ({ symbol, markPrice }) => {
      topReversalSocketMarks.set(symbol, markPrice);
      topReversalSocketMarkAt.set(symbol, Date.now());
      queueTopReversalPaperProcessing(symbol, markPrice);
      scheduleTopReversalPaperBroadcast();
    },
  );
  syncTopReversalPaperTicker().catch(() => {});
  setInterval(() => syncTopReversalPaperTicker().catch(() => {}), 30_000);
}

async function handleShakeoutReclaimRealOrders(signals = []) {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (process.env.SHAKEOUT_RECLAIM_REAL_ORDER_ENABLED !== 'true') return;
  if (!runtimeSettings.orderEnabled || runtimeSettings.dryRun) {
    console.log('[ShakeoutReclaimOrder] skip - real Binance order disabled/dry-run');
    return;
  }

  const minScore = Number(process.env.SHAKEOUT_RECLAIM_REAL_MIN_SCORE ?? 60);
  const cooldownMs = Number(process.env.SHAKEOUT_RECLAIM_REAL_COOLDOWN_MS ?? 4 * 3600 * 1000);
  const maxOrders = Math.max(1, Number(process.env.SHAKEOUT_RECLAIM_REAL_MAX_ORDERS_PER_SCAN ?? 1));
  const marginUsdt = Number(process.env.SHAKEOUT_RECLAIM_REAL_MARGIN_USDT ?? 1);
  const defaultLeverage = Number(process.env.SHAKEOUT_RECLAIM_REAL_LEVERAGE ?? 10);
  const minNotionalUsdt = Number(process.env.SHAKEOUT_RECLAIM_REAL_MIN_NOTIONAL_USDT ?? 5.5);
  const orderType = String(process.env.SHAKEOUT_RECLAIM_REAL_ORDER_TYPE ?? 'MARKET').toUpperCase();
  const maxOpenPositions = Number(process.env.SHAKEOUT_RECLAIM_REAL_MAX_POSITIONS ?? process.env.AUTO_TRADE_MAX_POSITIONS ?? 0);
  if (!['MARKET', 'LIMIT', 'LIMIT_IOC'].includes(orderType)) {
    console.warn(`[ShakeoutReclaimOrder] invalid order type: ${orderType}`);
    return;
  }

  const ordered = [...signals]
    .filter((sig) => Number(sig?.score ?? 0) >= minScore)
    .filter((sig) => !sig.bottomReboundRisk && !sig.autoTradeBlocked)
    .filter((sig) => String(sig?.subtype ?? '') !== 'BOTTOM_REBOUND_RISK')
    .filter((sig) => ['LONG', 'SHORT'].includes(String(sig?.action ?? '').toUpperCase()))
    .filter((sig) => Number.isFinite(Number(sig?.entry)) && Number(sig.entry) > 0)
    .filter((sig) => Number.isFinite(Number(sig?.sl)) && Number(sig.sl) > 0)
    .filter((sig) => !['MEDIUM', 'HIGH'].includes(String(sig?.riskFlags?.trapRisk ?? 'LOW').toUpperCase()))
    .sort((a, b) => Number(b?.score ?? 0) - Number(a?.score ?? 0));
  if (!ordered.length) return;

  let apiKey;
  let apiSecret;
  try {
    ({ apiKey, apiSecret } = getApiCredentials(null));
  } catch (err) {
    apiKey = process.env.BINANCE_API_KEY;
    apiSecret = process.env.BINANCE_API_SECRET;
    if (!apiKey || !apiSecret) throw err;
  }

  const [positions, openOrders] = await Promise.all([
    client.getPositions({ apiKey, apiSecret }),
    getCachedOpenOrders(apiKey, apiSecret),
  ]);

  let submitted = 0;

  for (const sig of ordered) {
    if (submitted >= maxOrders) break;
    const symbol = normalizeSymbol(sig?.symbol ?? '');
    const action = String(sig?.action ?? '').toUpperCase();
    const isLong = action === 'LONG';
    const isShort = action === 'SHORT';
    if (!symbol || (!isLong && !isShort)) continue;
    if (!Number.isFinite(Number(sig.entry)) || Number(sig.entry) <= 0) continue;
    if (!Number.isFinite(Number(sig.sl)) || Number(sig.sl) <= 0) continue;
    const trapRisk = String(sig?.riskFlags?.trapRisk ?? 'LOW').toUpperCase();
    const realGate = getShakeoutRealGate({
      ...sig,
      side: action,
      trapRisk,
      entry: sig.entry,
      tp: sig.tp,
      sl: sig.sl,
      leverage: calcAutoLeverage(sig.entry, sig.sl, defaultLeverage),
    });
    if (process.env.SHAKEOUT_REAL_GATE !== 'false') {
      if (!realGate.allowReal) {
        console.log(`[ShakeoutReclaimOrder] skip ${symbol} ${action} - ${realGate.label}: ${realGate.reasons.join('; ')}`);
        continue;
      }
      if (realGate.label === 'REAL_TEST') {
        console.log(`[ShakeoutReclaimOrder] allow ${symbol} ${action} - REAL_TEST: ${realGate.reasons.join('; ')}`);
      }
    } else if (trapRisk === 'MEDIUM' || trapRisk === 'HIGH') {
      console.log(`[ShakeoutReclaimOrder] skip ${symbol} ${action} - trapRisk=${trapRisk}`);
      continue;
    }
    const liqBlock = liqAutoBlockReason(symbol, action);
    if (liqBlock) {
      console.log(`[ShakeoutReclaimOrder] skip ${symbol} ${action} - ${liqBlock}`);
      continue;
    }

    const dedupKey = `${symbol}|${sig.stage ?? '-'}|${action}`;
    const last = shakeoutReclaimRealOrderFired.get(dedupKey) ?? 0;
    if (Date.now() - last < cooldownMs) {
      console.log(`[ShakeoutReclaimOrder] skip ${symbol} - cooldown`);
      continue;
    }

    const hasPosition = positions.some((p) => p.symbol === symbol && Math.abs(Number(p.positionAmt ?? 0)) > 0);
    if (hasPosition) {
      console.log(`[ShakeoutReclaimOrder] skip ${symbol} - already has position`);
      continue;
    }

    const hasEntryOrder = openOrders.some((o) => {
      if (o.symbol !== symbol) return false;
      if (String(o.reduceOnly ?? '').toLowerCase() === 'true') return false;
      const type = String(o.type ?? o.origType ?? '').toUpperCase();
      return ['MARKET', 'LIMIT', 'LIMIT_MAKER'].includes(type);
    });
    if (hasEntryOrder) {
      console.log(`[ShakeoutReclaimOrder] skip ${symbol} - already has entry order`);
      continue;
    }

    const leverage = calcAutoLeverage(sig.entry, sig.sl, defaultLeverage);
    const notionalUsdt = Math.max(marginUsdt * leverage, minNotionalUsdt);
    const side = isLong ? 'BUY' : 'SELL';
    const effectiveOrderType = isShort && sig.btcStrongShortEma99 ? 'LIMIT' : orderType;

    try {
      const result = await placeOrder({
        symbol,
        side,
        orderType: effectiveOrderType,
        notionalUsdt,
        leverage,
        limitPrice: effectiveOrderType === 'MARKET' ? undefined : sig.entry,
        takeProfitPrice: sig.tp ?? undefined,
        stopLossPrice: sig.sl ?? undefined,
        protectionOnFill: true,
        maxOpenPositions,
        dryRun: false,
        source: 'shakeout-reclaim',
      }, null, { apiKey, apiSecret });

      submitted++;
      shakeoutReclaimRealOrderFired.set(dedupKey, Date.now());
      invalidateOpenOrdersCache();
      const orderId = result?.orderResult?.orderId ?? '-';
      console.log(`[ShakeoutReclaimOrder] REAL ${symbol} ${action} ${effectiveOrderType} orderId=${orderId} margin=$${marginUsdt} score=${sig.score}`);

      const webhookUrl = process.env.SHAKEOUT_RECLAIM_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL || '';
      if (webhookUrl) {
        const fmt = (v) => v == null || !Number.isFinite(Number(v)) ? '-' : Number(v).toPrecision(8).replace(/\.?0+$/, '');
        const msg = [
          `**[REAL ORDER] Shakeout Reclaim ${symbol} ${action} - ${effectiveOrderType} - Score ${sig.score} (${sig.grade ?? '-'})**`,
          `OrderId: \`${orderId}\` | Margin: $${marginUsdt} x ${leverage}x | Notional: $${notionalUsdt}`,
          `Entry: \`${fmt(sig.entry)}\` | SL: \`${fmt(sig.sl)}\` | TP: \`${fmt(sig.tp)}\``,
          `Stage: ${sig.stage ?? '-'} | Type: ${sig.type ?? '-'}`,
          sig.btcStrongShortEma99 ? 'BTC STRONG: SHORT LIMIT đặt đúng EMA99 5m, không clamp 5%.' : '',
        ].filter(Boolean).join('\n');
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: msg }),
        }).catch(() => {});
      }
    } catch (e) {
      console.warn(`[ShakeoutReclaimOrder] ${symbol}:`, e.message);
    }
  }
}

function startPaperTradeTicker() {
  if (process.env.PAPER_TRADE_TICKER_ENABLED === 'false') return;
  if (paperTicker) return;
  paperTicker = true; // guard flag — actual WS is sharedLastTicke
  sharedLastTicker.register('paperTrade', ({ symbol, markPrice }) => {
    paperMarkCache.set(symbol, { markPrice, at: Date.now(), source: 'ws' });
    processPaperPendingFillsForSymbol(symbol, markPrice).catch(() => {});
    processLiquidPaperPendingFillsForSymbol(symbol, markPrice).catch(() => {});
    scheduleLiquidPaperBroadcast();
  });
  console.log('[PaperLiq] Last-price ticker started for paper trades (shared).');
  syncPaperTickerSymbols().catch(() => {});
  setInterval(() => syncPaperTickerSymbols().catch(() => {}), 10_000);
  // REST poller disabled — sharedLastTicker WS handles last-price updates
  // startLiquidPaperRestPoller();
}

async function callOpenAI(messages) {
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: process.env.OPENAI_MODEL ?? 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      messages,
      temperature: 0.2,
    }),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`OpenAI ${res.status}: ${text.slice(0, 200)}`);
  }
  const data = await res.json();
  return JSON.parse(data.choices[0].message.content);
}

function fp(v, d = 4) { return v == null ? '-' : Number(v).toFixed(d); }

function buildAiPrompt(symbol, a) {
  const d = a;
  const liq = d.liquidationProxy;
  const sig = d.signal;
  const setup = d.tradeSetup;
  const m = d.market;
  const ob = d.orderBook;

  const zonesAbove = (liq.strongestAbove ?? []).slice(0, 5)
    .map((z) => `  • ${fp(z.price, 4)} (+${fp(z.distancePct, 2)}%) score=${fp(z.score, 2)}`).join('\n');
  const zonesBelow = (liq.strongestBelow ?? []).slice(0, 5)
    .map((z) => `  • ${fp(z.price, 4)} (${fp(z.distancePct, 2)}%) score=${fp(z.score, 2)}`).join('\n');

  const lrLine = m.longShortRatio
    ? `Long/Short ratio: ${fp(m.longShortRatio.longShortRatio, 3)} (long accounts: ${(m.longShortRatio.longAccount * 100).toFixed(1)}%)`
    : 'Long/Short ratio: N/A';

  const setupLine = setup.direction !== 'wait'
    ? `Direction: ${setup.direction.toUpperCase()} | Confidence: ${setup.confidence}
Entry zone: ${setup.entry ? `${fp(setup.entry.low, 6)} – ${fp(setup.entry.high, 6)}` : 'N/A'}
Stop loss: ${fp(setup.stopLoss, 6)}
Targets: ${(setup.targets ?? []).map((t) => fp(t, 6)).join(' → ')}
Reasons: ${(setup.reason ?? []).join('; ')}`
    : `Direction: WAIT
Breakout long above: ${fp(setup.breakoutLevels?.longAbove, 6)}
Breakout short below: ${fp(setup.breakoutLevels?.shortBelow, 6)}`;

  const userContent = `## ${symbol} Futures Analysis

**Price:** Mark ${fp(d.price.mark, 6)}  |  Index ${fp(d.price.index, 6)}

**Momentum:** 24h ${fp(m.momentumPct * 100, 2)}%  |  48h ${fp(m.momentumPct48h * 100, 2)}%  |  Trend aligned: ${m.trendAligned}
**ATR:** ${m.atrPct}% of price
**Funding rate:** ${m.fundingRatePct}% (positive = longs pay shorts → bearish pressure)
**Open Interest:** ${m.openInterest}

**Taker buy ratio:** ${(m.takerBuyRatio * 100).toFixed(1)}% (>50% = buy pressure)
${lrLine}

**Order Book (${(ob.rangePct * 100).toFixed(1)}% range):**
Bid: ${ob.bidNotional?.toFixed(0)} USDT  |  Ask: ${ob.askNotional?.toFixed(0)} USDT  |  Imbalance: ${fp(ob.imbalance, 3)} (positive = buy wall)

**Estimated Liquidation Zones (from leveraged position history):**
Above current price (short liquidations → bullish magnet):
${zonesAbove || '  (none)'}
Below current price (long liquidations → bearish magnet):
${zonesBelow || '  (none)'}
Liquidity bias: ${fp(liq.bias, 3)} (>0 = more liquidity above = short squeeze potential)

**Internal Signal:**
Label: ${sig.label}  |  Score: ${sig.score} (range -1 to +1)
Components → momentum:${sig.components.momentum} funding:${sig.components.funding} takerFlow:${sig.components.takerFlow} orderBook:${sig.components.orderBook} liquidityMagnet:${sig.components.liquidityMagnet} crowding:${sig.components.crowding}

**Heuristic Trade Setup:**
${setupLine}

Based on ALL the above data, provide your trading recommendation. Focus especially on:
1. Where liquidation clusters sit relative to price (they act as magnets)
2. Whether funding rate and taker flow confirm or contradict momentum
3. Realistic entry price within the next 1-4 hours

Respond ONLY with JSON in this exact format:
{
  "recommendation": "LONG or SHORT or WAIT",
  "entry": { "low": number, "high": number },
  "stopLoss": number,
  "target": number,
  "riskLevel": "LOW or MEDIUM or HIGH",
  "confidence": number (0-100),
  "reasoning": ["bullet 1", "bullet 2", "bullet 3"],
  "summary": "one sentence in Vietnamese"
}`;

  return [
    {
      role: 'system',
      content: 'You are an expert crypto futures trader. Analyze Binance USD-M Futures market data and return a precise JSON trading recommendation. Be specific with price levels. Do not add commentary outside the JSON.',
    },
    { role: 'user', content: userContent },
  ];
}

function startAutoTrader() {
  autoTradeState.startedAt = new Date().toISOString();
  const intervalMs = Math.max(Number(process.env.AUTO_TRADE_INTERVAL_MS ?? 15000), 5000);
  console.log(`Auto trader ready. Scan interval ${intervalMs}ms. Currently ${runtimeSettings.autoTradeEnabled ? 'enabled' : 'disabled'}.`);
  runAutoTradeScan();
  setInterval(runAutoTradeScan, intervalMs);
}

async function runAutoTradeScan() {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (!runtimeSettings.autoTradeEnabled) return;
  if (isVnBlockHour()) { console.log('[AutoTrade] ⏰ Block 17-19h VN'); return; }
  try {
    const snapshot = await getMarketSnapshot();
    const threshold = Number(process.env.AUTO_TRADE_THRESHOLD ?? 0.7);
    const maxOrders = Math.max(1, Number(process.env.AUTO_TRADE_MAX_ORDERS_PER_SCAN ?? 1));
    const minVolume = Number(process.env.AUTO_TRADE_MIN_VOLUME_USDT ?? 5_000_000);
    const maxChangePct = Number(process.env.AUTO_TRADE_MAX_CHANGE_PCT ?? 30);
    const blacklist = new Set(
      (process.env.AUTO_TRADE_BLACKLIST ?? '').split(',').map((s) => s.trim().toUpperCase()).filter(Boolean),
    );
    const candidates = snapshot
      .filter((row) => {
        if (blacklist.has(row.symbol)) return false;
        if (isDynamicBlacklisted(row.symbol)) return false;
        if (row.quoteVolume < minVolume) return false;
        if (Math.abs(row.change24hPct) > maxChangePct) return false;
        return true;
      })
      .map((row) => ({
        row,
        setup: buildAutoTradeSignal(row),
      }))
      .filter(({ setup }) => setup.direction !== 'wait' && Math.abs(setup.score) >= threshold)
      .sort((a, b) => Math.abs(b.setup.score) - Math.abs(a.setup.score));
    let placed = 0;

    autoTradeState.lastScanAt = new Date().toISOString();

    const webhookUrl = process.env.DISCORD_WEBHOOK_URL || '';
    const minStreak = Math.max(1, Number(process.env.AUTO_TRADE_MIN_STREAK ?? 2));

    // Decay streaks for symbols no longer qualifying
    const qualifyingSymbols = new Set(candidates.map(({ row }) => row.symbol));
    for (const sym of autoTradeState.signalStreak.keys()) {
      if (!qualifyingSymbols.has(sym)) autoTradeState.signalStreak.delete(sym);
    }

    for (const candidate of candidates) {
      const { row, setup } = candidate;
      if (placed >= maxOrders) break;
      if (isAutoTradeCoolingDown(row.symbol)) continue;

      // ── Streak confirmation ──────────────────────────────────
      const streak = autoTradeState.signalStreak.get(row.symbol) ?? { direction: null, count: 0 };
      if (streak.direction !== setup.direction) {
        autoTradeState.signalStreak.set(row.symbol, { direction: setup.direction, count: 1 });
        console.log(`[AutoTrade] ${row.symbol} new signal ${setup.direction} score=${setup.score.toFixed(3)} — streak 1/${minStreak}`);
        // Discord #1: signal detected (lightweight, no analysis)
        if (webhookUrl) {
          sendSignalDetected(row.symbol, setup.score, webhookUrl)
            .catch((err) => console.error(`[Discord] signal alert ${row.symbol}:`, err.message));
        }
        continue;
      }
      if (streak.count < minStreak) {
        autoTradeState.signalStreak.set(row.symbol, { ...streak, count: streak.count + 1 });
        console.log(`[AutoTrade] ${row.symbol} streak ${streak.count + 1}/${minStreak}`);
        continue;
      }

      // ── Bounce/dip entry filter ──────────────────────────────
      // SHORT: track lowest seen → wait for price to bounce ≥ bouncePct above that low
      // LONG:  anchor to signal price → wait for price to dip ≥ bouncePct below signal price
      //        (can't track "highest" for LONG because rising price keeps updating extreme → move always 0)
      // ── Calculate entry level (EMA99 / ATR-based) → LIMIT IOC ─
      const [symbols] = await Promise.all([getSymbols()]);
      const symbolInfo = symbols.find((s) => s.symbol === row.symbol);
      const limitPrice = symbolInfo
        ? await calculateEntryLevel(row.symbol, setup.direction, row.markPrice, symbolInfo, setup.score)
        : null;

      // ── Place order ──────────────────────────────────────────
      console.log(`[AutoTrade] ${row.symbol} ${setup.direction.toUpperCase()} ENTRY — streak OK → ${limitPrice ? `LIMIT IOC @ ${limitPrice}` : 'MARKET'}`);
      let result;
      try {
        result = await placeAutoTrade(row, setup, limitPrice, setup.score);
      } catch (placeErr) {
        const reason = placeErr instanceof Error ? placeErr.message : String(placeErr);
        console.warn(`[AutoTrade] ${row.symbol} blocked: ${reason}`);
        autoTradeState.lastErrors.unshift({ at: new Date().toISOString(), message: reason });
        autoTradeState.lastErrors = autoTradeState.lastErrors.slice(0, 20);
        if (webhookUrl) {
          sendOrderBlocked(row.symbol, setup.score, setup.direction, reason, webhookUrl)
            .catch((err) => console.error(`[Discord] blocked alert ${row.symbol}:`, err.message));
        }
        continue;
      }
      // Track position immediately so positionMonitor picks it up before next REST sync
      if (posMonitor && result?.status === 'submitted') {
        const isLong = setup.direction === 'long';
        const lev = Math.max(1, Math.min(125, Number(process.env.AUTO_TRADE_LEVERAGE ?? 10)));
        const margin = Number(process.env.AUTO_TRADE_MARGIN_USDT ?? 1);
        const qty = (margin * lev) / row.markPrice;
        posMonitor.trackPosition(row.symbol, {
          amt: isLong ? qty : -qty,
          entry: row.markPrice,
          leverage: lev,
        });
      }
      // Discord #2: order placed (full analysis embed)
      if (webhookUrl) {
        fetchAnalysis({ client, symbol: row.symbol, interval: '15m', limit: 192 })
          .then((analysis) => sendOrderPlaced(row.symbol, setup.score, analysis, webhookUrl))
          .catch((err) => console.error(`[Discord] order alert ${row.symbol}:`, err.message));
      }
      autoTradeState.lastOrders.unshift({
        at: new Date().toISOString(),
        symbol: row.symbol,
        direction: setup.direction,
        score: setup.score,
        result,
      });
      autoTradeState.lastOrders = autoTradeState.lastOrders.slice(0, 20);
      autoTradeState.symbolCooldowns.set(row.symbol, Date.now());
      autoTradeState.signalStreak.delete(row.symbol);
      placed += 1;
    }
  } catch (error) {
    autoTradeState.lastErrors.unshift({
      at: new Date().toISOString(),
      message: error instanceof Error ? error.message : String(error),
    });
    autoTradeState.lastErrors = autoTradeState.lastErrors.slice(0, 20);
    console.error('Auto trader scan failed:', error instanceof Error ? error.message : error);
  }
}

async function placeAutoTrade(row, setup, limitPrice = null, score = 0) {
  const marginUsdt = Number(process.env.AUTO_TRADE_MARGIN_USDT ?? 2);
  const leverage = Math.max(1, Math.min(125, Number(process.env.AUTO_TRADE_LEVERAGE ?? 10)));
  const notionalUsdt = marginUsdt * leverage;
  const dryRun = runtimeSettings.dryRun;
  const isLong = setup.direction === 'long';
  const side = isLong ? 'BUY' : 'SELL';
  const mark = row.markPrice;

  // ── TP: direction-specific, with strong-signal boost ─────────────────────
  const defaultTpRoe = Number(process.env.AUTO_TRADE_TP_ROE ?? 20);
  const tpRoeBase = isLong
    ? Number(process.env.AUTO_TRADE_LONG_TP_ROE ?? defaultTpRoe)
    : Number(process.env.AUTO_TRADE_SHORT_TP_ROE ?? defaultTpRoe);

  const strongThreshold = Number(process.env.AUTO_TRADE_STRONG_SCORE ?? 0.85);
  const strongMult = Number(process.env.AUTO_TRADE_STRONG_TP_MULT ?? 1.5);
  const isStrong = Math.abs(score) >= strongThreshold;
  const tpRoePct = (isStrong ? tpRoeBase * strongMult : tpRoeBase) / 100;

  if (isStrong) {
    console.log(`[AutoTrade] ${row.symbol} strong score ${score.toFixed(3)} → TP boosted ${tpRoeBase}% → ${(tpRoePct * 100).toFixed(1)}%`);
  }

  const takeProfitPrice = tpRoePct > 0 && mark > 0
    ? (isLong ? mark * (1 + tpRoePct / leverage) : mark * (1 - tpRoePct / leverage))
    : undefined;

  // ── SL: direction-specific, optional ─────────────────────────────────────
  const slRoeEnv = isLong
    ? process.env.AUTO_TRADE_LONG_SL_ROE
    : process.env.AUTO_TRADE_SHORT_SL_ROE;
  const slRoePct = slRoeEnv ? Math.abs(Number(slRoeEnv)) / 100 : null;
  const stopLossPrice = slRoePct && mark > 0
    ? (isLong ? mark * (1 - slRoePct / leverage) : mark * (1 + slRoePct / leverage))
    : undefined;

  const maxPositions = Number(process.env.AUTO_TRADE_MAX_POSITIONS ?? 0);

  return placeOrder({
    symbol: row.symbol,
    side,
    orderType: limitPrice && !dryRun ? 'LIMIT_IOC' : 'MARKET',
    notionalUsdt,
    leverage,
    dryRun,
    limitPrice: limitPrice ?? undefined,
    takeProfitPrice,
    stopLossPrice,
    maxOpenPositions: maxPositions,
    source: 'auto-trader',
  });
}

// symbol → entry price at the time avg-down was placed (reset when position closes)
const avgDownTriggered = new Map();

async function runAvgDownScan() {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (process.env.AVG_DOWN_ENABLED !== 'true') return;
  const triggerRoe = Number(process.env.AVG_DOWN_TRIGGER_ROE ?? -60);
  const marginUsdt = Number(process.env.AVG_DOWN_MARGIN_USDT ?? 2);

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const positions = await client.getPositions({ apiKey, apiSecret });
    const active = positions.filter((p) => Number(p.positionAmt) !== 0);

    // Clear triggered map for closed positions
    const activeSymbols = new Set(active.map((p) => p.symbol));
    for (const sym of avgDownTriggered.keys()) {
      if (!activeSymbols.has(sym)) avgDownTriggered.delete(sym);
    }

    for (const pos of active) {
      const amt = Number(pos.positionAmt);
      const entry = Number(pos.entryPrice);
      const upnl = Number(pos.unRealizedProfit);
      const lev = Number(pos.leverage) || 1;
      const isolatedMargin = Number(pos.isolatedMargin);
      const initialMargin = Number(pos.initialMargin);
      const margin = isolatedMargin > 0 ? isolatedMargin
        : initialMargin > 0 ? initialMargin
          : Math.abs(amt) * entry / lev;
      const roe = margin > 0 ? (upnl / margin) * 100 : 0;

      if (roe > triggerRoe) continue;

      // Already averaged for this position entry price (within 1% means same position, not re-opened)
      const prevEntry = avgDownTriggered.get(pos.symbol);
      if (prevEntry !== undefined && Math.abs(prevEntry - entry) / entry < 0.01) continue;

      const side = amt > 0 ? 'BUY' : 'SELL';
      const notionalUsdt = marginUsdt * lev;

      if (runtimeSettings.dryRun) {
        console.log(`[AvgDown] [DRY RUN] ${pos.symbol} ROE=${roe.toFixed(1)}% → would avg down $${marginUsdt} ${side}`);
        avgDownTriggered.set(pos.symbol, entry);
        continue;
      }

      try {
        await placeOrder({ symbol: pos.symbol, side, notionalUsdt, leverage: lev, dryRun: false, source: 'avg-down' });
        avgDownTriggered.set(pos.symbol, entry);
        console.log(`[AvgDown] ✅ ${pos.symbol} ROE=${roe.toFixed(1)}% → avg down $${marginUsdt} ${side}`);
      } catch (err) {
        console.error(`[AvgDown] ❌ ${pos.symbol}:`, err.message);
      }
    }
  } catch (err) {
    if (err.message?.includes('Missing Binance API')) return; // no credentials yet
    console.error('[AvgDown] Scan error:', err.message);
  }
}

function buildAutoTradeSignal(row) {
  const price = row.markPrice;
  const change24h = row.change24hPct ?? 0;
  const fundingPct = (row.fundingRate ?? 0) * 100;
  const firstSeenPrice = autoTradeState.firstSeenPrices.get(row.symbol) ?? price;

  if (!autoTradeState.firstSeenPrices.has(row.symbol)) {
    autoTradeState.firstSeenPrices.set(row.symbol, price);
  }

  const liveMomentum = ((price - firstSeenPrice) / firstSeenPrice) * 100;
  const score = (
    clamp(change24h / 12, -1, 1) * 0.45
    + clamp(liveMomentum / 1.2, -1, 1) * 0.4
    + clamp(-fundingPct / 0.05, -0.4, 0.4) * 0.15
  );

  if (score >= 0.7) {
    return {
      direction: 'long',
      score,
      reason: 'Auto score >= 0.7: 24h trend/live momentum/funding aligned upward.',
    };
  }

  if (score <= -0.7) {
    return {
      direction: 'short',
      score,
      reason: 'Auto score <= -0.7: 24h trend/live momentum/funding aligned downward.',
    };
  }

  return {
    direction: 'wait',
    score,
    reason: 'Auto score below threshold.',
  };
}

function isAutoTradeCoolingDown(symbol) {
  const lastOrderAt = autoTradeState.symbolCooldowns.get(symbol);
  if (!lastOrderAt) return false;
  return Date.now() - lastOrderAt < Number(process.env.AUTO_TRADE_COOLDOWN_MS ?? 900000);
}

function computeEMA(closes, period) {
  const k = 2 / (period + 1);
  let ema = closes.slice(0, period).reduce((a, b) => a + b, 0) / period;
  for (let i = period; i < closes.length; i++) {
    ema = closes[i] * k + ema * (1 - k);
  }
  return ema;
}

function computeATR(klines, period = 14) {
  const trs = [];
  for (let i = 1; i < klines.length; i++) {
    const { high, low } = klines[i];
    const prevClose = klines[i - 1].close;
    trs.push(Math.max(high - low, Math.abs(high - prevClose), Math.abs(low - prevClose)));
  }
  const recent = trs.slice(-period);
  return recent.reduce((a, b) => a + b, 0) / recent.length;
}

async function calculateEntryLevel(symbol, direction, markPrice, symbolInfo, score = 0) {
  try {
    const klines = klineCache.getIfCached(symbol, '15m', 110);
    if (!klines || klines.length < 100) return null;
    const closes = klines.map((k) => k.close);
    const ema99 = computeEMA(closes, 99);
    const atr = computeATR(klines, 14);

    const strongThreshold = Number(process.env.AUTO_TRADE_STRONG_SCORE ?? 0.85);
    const isStrong = Math.abs(score) >= strongThreshold;

    let rawLimit;
    if (direction === 'short') {
      // Normal: 0.5×ATR bounce offset. Strong: 1×ATR — bigger bounce expected after sharp drop.
      const atrMult = isStrong ? 1.0 : 0.5;
      rawLimit = markPrice + atr * atrMult;
      rawLimit = Math.min(rawLimit, markPrice * (isStrong ? 1.02 : 1.01));
    } else {
      // Normal: EMA99 or max 2×ATR below. Strong: allow up to 3×ATR below for deeper dip entry.
      const atrFloor = isStrong ? 3.0 : 2.0;
      const floorPrice = markPrice - atr * atrFloor;
      rawLimit = Math.max(ema99, floorPrice);
      rawLimit = Math.min(rawLimit, markPrice * 0.9995);
    }

    const limitPrice = Number(priceFromTick(symbolInfo, rawLimit));
    console.log(`[AutoTrade] ${symbol} entry: ${direction}${isStrong ? ' [STRONG]' : ''} → LIMIT ${limitPrice} (EMA99=${ema99.toFixed(4)} ATR=${atr.toFixed(4)})`);
    return limitPrice;
  } catch (err) {
    console.warn(`[AutoTrade] ${symbol} calculateEntryLevel failed: ${err.message}`);
    return null;
  }
}

function getAutoTradeStatus() {
  return {
    enabled: runtimeSettings.autoTradeEnabled,
    blockedByExclusivePolicy: liveCardOnlyAutoBinanceEnabled(),
    autoBinancePolicy: AUTO_BINANCE_ENTRY_POLICY_VERSION,
    dryRun: runtimeSettings.dryRun,
    threshold: Number(process.env.AUTO_TRADE_THRESHOLD ?? 0.7),
    marginUsdt: Number(process.env.AUTO_TRADE_MARGIN_USDT ?? 2),
    leverage: Number(process.env.AUTO_TRADE_LEVERAGE ?? 10),
    notionalUsdt: Number(process.env.AUTO_TRADE_MARGIN_USDT ?? 2) * Number(process.env.AUTO_TRADE_LEVERAGE ?? 10),
    intervalMs: Number(process.env.AUTO_TRADE_INTERVAL_MS ?? 15000),
    cooldownMs: Number(process.env.AUTO_TRADE_COOLDOWN_MS ?? 900000),
    maxOrdersPerScan: Number(process.env.AUTO_TRADE_MAX_ORDERS_PER_SCAN ?? 1),
    startedAt: autoTradeState.startedAt,
    lastScanAt: autoTradeState.lastScanAt,
    lastOrders: autoTradeState.lastOrders,
    lastErrors: autoTradeState.lastErrors,
  };
}

function quantityFromNotional(symbolInfo, notionalUsdt, markPrice, skipMinCheck = false, {
  allowMinNotionalCeil = false,
} = {}) {
  const lotSize = symbolInfo.filters?.find((filter) => filter.filterType === 'LOT_SIZE');
  const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
  const minQty = Number(lotSize?.minQty ?? stepSize);
  const rawQuantity = notionalUsdt / markPrice;
  const minNotional = minQty * markPrice;

  if (!skipMinCheck && rawQuantity < minQty) {
    throw new Error(`Order size too small for ${symbolInfo.symbol}. Minimum is about ${minNotional.toFixed(2)} USDT.`);
  }

  let steppedQuantity = Math.floor(rawQuantity / stepSize) * stepSize;

  if (!skipMinCheck) {
    const notionalFilter = symbolInfo.filters?.find((f) => f.filterType === 'MIN_NOTIONAL');
    const minNotionalFilter = Number(notionalFilter?.notional ?? notionalFilter?.minNotional ?? 0);
    if (minNotionalFilter > 0 && steppedQuantity * markPrice < minNotionalFilter) {
      const adjustedQuantity = ceilQuantityAtMinimumNotional({
        steppedQuantity,
        stepSize,
        markPrice,
        requestedNotional: notionalUsdt,
        minimumNotional: minNotionalFilter,
        enabled: allowMinNotionalCeil,
      });
      if (adjustedQuantity == null) {
        throw new Error(`Order notional too small for ${symbolInfo.symbol}. Min ${minNotionalFilter} USDT required, got ${(steppedQuantity * markPrice).toFixed(2)} USDT.`);
      }
      steppedQuantity = adjustedQuantity;
    }
  }

  const precision = decimalsFromStep(stepSize);

  return steppedQuantity.toFixed(precision).replace(/\.?0+$/, '');
}

function priceFromTick(symbolInfo, price) {
  const priceFilter = symbolInfo.filters?.find((filter) => filter.filterType === 'PRICE_FILTER');
  const tickSize = Number(priceFilter?.tickSize ?? 0.00000001);
  const precision = decimalsFromStep(tickSize);

  return (Math.round(price / tickSize) * tickSize).toFixed(precision).replace(/\.?0+$/, '');
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

async function readJsonBody(request) {
  const chunks = [];

  for await (const chunk of request) {
    chunks.push(chunk);
  }

  const raw = Buffer.concat(chunks).toString('utf8');

  return raw ? JSON.parse(raw) : {};
}

async function batchedAllSettled(items, fn, batchSize = 5, delayMs = 300) {
  const results = [];
  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);
    results.push(...await Promise.allSettled(batch.map(fn)));
    if (i + batchSize < items.length) await new Promise((r) => setTimeout(r, delayMs));
  }
  return results;
}

function startLongShortRefresh() {
  const run = async () => {
    try {
      // Dùng getSharedSnapshot() thay vì gọi getTicker24hr() riêng (tránh tốn w=40)
      const snapshot = await getSharedSnapshot();
      const maxSymbols = Number(process.env.LONG_SHORT_REFRESH_MAX_SYMBOLS ?? 15);
      if (maxSymbols <= 0) return;
      const top = snapshot
        .sort((a, b) => b.quoteVolume - a.quoteVolume)
        .slice(0, maxSymbols)
        .map((t) => t.symbol);

      // Stagger calls: 5 per batch, 300ms between batches → ~2.4s total instead of burst
      const [globalResults, topResults] = await Promise.all([
        batchedAllSettled(top, (sym) => client.getGlobalLongShortRatio(sym, '15m', 1).then((rows) => ({ sym, row: rows[0] })), 1, 1200),
        batchedAllSettled(top, (sym) => client.getTopLongShortPositionRatio(sym, '15m', 1).then((rows) => ({ sym, row: rows[0] })), 1, 1200),
      ]);

      for (const r of globalResults) {
        if (r.status === 'fulfilled' && r.value.row) {
          longShortCache.set(r.value.sym, {
            longShortRatio: Number(r.value.row.longShortRatio),
            longAccount: Number(r.value.row.longAccount),
          });
        }
      }
      for (const r of topResults) {
        if (r.status === 'fulfilled' && r.value.row) {
          const d = r.value.row;
          topPositionCache.set(r.value.sym, {
            longShortRatio: Number(d.longShortRatio),
            longPosition: Number(d.longAccount),   // API field is named longAccount but represents position %
            shortPosition: Number(d.shortAccount),
          });
        }
      }
    } catch (err) {
      console.error('[LongShort] Refresh error:', err.message);
    }
  };
  setTimeout(run, 8000);
  setInterval(run, Number(process.env.LONG_SHORT_REFRESH_INTERVAL_MS ?? 15 * 60 * 1000));
}

async function getHedgeMode(token = null, credentialsOverride = null, requestOptions = {}) {
  const { apiKey, apiSecret } = credentialsOverride ?? getApiCredentials(token);
  if (hedgeModeCache.has(apiKey)) return hedgeModeCache.get(apiKey);
  try {
    const mode = await client.getPositionMode({ apiKey, apiSecret, ...requestOptions });
    hedgeModeCache.set(apiKey, mode);
    console.log(`[PositionMode] Account is in ${mode ? 'Hedge' : 'One-way'} mode.`);
    return mode;
  } catch {
    hedgeModeCache.set(apiKey, false);
    return false;
  }
}

function getApiCredentials(token = null) {
  // Token cụ thể → dùng session của token đó
  if (token) {
    const creds = sessionCredentials.get(token);
    const apiKey = creds?.apiKey || process.env.BINANCE_API_KEY;
    const apiSecret = creds?.apiSecret || process.env.BINANCE_API_SECRET;
    if (!apiKey || !apiSecret) throw new Error('Missing Binance API credentials. Enter API key on login or set BINANCE_API_KEY in .env.');
    return { apiKey, apiSecret };
  }
  // Background (token=null): luôn ưu tiên credential cố định trong .env.
  // Trang Orders có thể tự đăng nhập lại bằng credential cũ trong localStorage;
  // không để session UI đầu tiên ghi đè socket/auto-order/TP-SL background.
  if (process.env.BINANCE_API_KEY && process.env.BINANCE_API_SECRET) {
    return { apiKey: process.env.BINANCE_API_KEY, apiSecret: process.env.BINANCE_API_SECRET };
  }
  // Chỉ fallback session khi server thực sự không được cấu hình credential nền.
  if (sessionCredentials.size > 0) {
    const first = sessionCredentials.values().next().value;
    if (first?.apiKey && first?.apiSecret) return { apiKey: first.apiKey, apiSecret: first.apiSecret };
  }
  throw new Error('Chưa đăng nhập. Vào /orders và nhập API key để sử dụng.');
}

let _balanceCache = null;
let _balanceCacheAt = 0;
let _balanceInflight = null;
const BALANCE_TTL_MS = 60_000; // 1 phút — balance không cần real-time

async function getAccountBalance(token = null) {
  if (token) {
    const cached = ordersSessionSnapshots.get(token);
    if (cached && Date.now() - cached.verifiedAt < 15_000) {
      return cached.balance.filter((b) => Number(b.balance) > 0 || Number(b.crossUnPnl) !== 0);
    }
    const { apiKey, apiSecret } = getApiCredentials(token);
    const balance = await ordersAuthClient.getBalance({ apiKey, apiSecret });
    ordersSessionSnapshots.set(token, {
      verifiedAt: Date.now(),
      balance: Array.isArray(balance) ? balance : [],
      positions: cached?.positions ?? [],
    });
    return (Array.isArray(balance) ? balance : []).filter((b) => Number(b.balance) > 0 || Number(b.crossUnPnl) !== 0);
  }
  if (_balanceCache && Date.now() - _balanceCacheAt < BALANCE_TTL_MS) return _balanceCache;
  if (_balanceInflight) return _balanceInflight;
  if (shouldDeferAlgoRest()) return _balanceCache ?? [];
  const { apiKey, apiSecret } = getApiCredentials(token);
  _balanceInflight = client.getBalance({ apiKey, apiSecret })
    .then((rows) => {
      _balanceCache = rows.filter((b) => Number(b.balance) > 0 || Number(b.crossUnPnl) !== 0);
      _balanceCacheAt = Date.now();
      return _balanceCache;
    })
    .finally(() => { _balanceInflight = null; });
  return _balanceInflight;
}

let _dailyPnlCache = null;
let _dailyPnlCacheAt = 0;
let _dailyPnlInflight = null;
const DAILY_PNL_TTL_MS = 300_000; // 5 phút — income API weight=30, không cần real-time

async function getDailyPnl(token = null) {
  if (_dailyPnlCache && Date.now() - _dailyPnlCacheAt < DAILY_PNL_TTL_MS) return _dailyPnlCache;
  if (_dailyPnlInflight) return _dailyPnlInflight;
  if (shouldDeferAlgoRest()) return _dailyPnlCache ?? { realized: 0, commission: 0, funding: 0, net: 0, since: new Date().toISOString() };
  const { apiKey, apiSecret } = getApiCredentials(token);
  const startOfDay = new Date();
  startOfDay.setUTCHours(0, 0, 0, 0);
  _dailyPnlInflight = client.getIncome({ startTime: startOfDay.getTime(), limit: 1000, apiKey, apiSecret })
    .then((rows) => {
      let realized = 0; let commission = 0; let funding = 0;
      for (const r of rows) {
        const v = Number(r.income);
        if (r.incomeType === 'REALIZED_PNL') realized += v;
        else if (r.incomeType === 'COMMISSION') commission += v;
        else if (r.incomeType === 'FUNDING_FEE') funding += v;
      }
      _dailyPnlCache = { realized, commission, funding, net: realized + commission + funding, since: startOfDay.toISOString() };
      _dailyPnlCacheAt = Date.now();
      return _dailyPnlCache;
    })
    .finally(() => { _dailyPnlInflight = null; });
  return _dailyPnlInflight;
}

let _liveCardClosedPnlIncomeCache = null;
let _liveCardClosedPnlIncomeInflight = null;
const LIVE_CARD_CLOSED_PNL_INCOME_TTL_MS = 60_000;

async function fetchLiveCardIncomeRange({ startTime, endTime, apiKey, apiSecret, depth = 0 }) {
  const rows = await client.getIncome({ startTime, endTime, limit: 1000, apiKey, apiSecret });
  if (!Array.isArray(rows) || rows.length < 1000 || depth >= 8 || endTime - startTime <= 60_000) {
    return Array.isArray(rows) ? rows : [];
  }
  const midpoint = Math.floor((startTime + endTime) / 2);
  const [left, right] = await Promise.all([
    fetchLiveCardIncomeRange({ startTime, endTime: midpoint, apiKey, apiSecret, depth: depth + 1 }),
    fetchLiveCardIncomeRange({ startTime: midpoint + 1, endTime, apiKey, apiSecret, depth: depth + 1 }),
  ]);
  return [...left, ...right];
}

let liquidFlowV2BinanceStatsIncomeCache = null;
const LIQUID_FLOW_V2_BINANCE_STATS_CACHE_MS = 60_000;

async function getLiquidFlowV2BinanceStats({ token, fromDay = '', toDay = '', labelKey = '' } = {}) {
  const paperTrades = liquidFlowV2Paper.state.trades;
  const coinglassExecutionState = await coinGlassWebTop20.binanceExecutionState();
  const coinglassAudits = coinglassQualifiedBinanceAudits(coinglassExecutionState, {
    fromDay,
    toDay,
    labelKey,
  });
  const credentials = getApiCredentials(token);
  const orderWarnings = [];
  // The process-wide position monitor is fed by Binance user-data + mark-price
  // sockets. Prefer it here so a just-filled/just-closed position is visible to
  // the stats page immediately instead of waiting for the per-session REST TTL.
  const positionsPromise = getPositions().catch((error) => {
    console.warn(`[LiquidFlowV2BinanceStats] positions: ${error.message}`);
    return [];
  });
  const orderSnapshotsPromise = Promise.all(coinglassAudits.map((audit) => client.getOrder({
    symbol: audit.symbol,
    orderId: audit.orderId,
    ...credentials,
  }).catch((error) => {
    orderWarnings.push(`${audit.symbol}#${audit.orderId}: ${error.message}`);
    return null;
  })));
  const [positions, orderSnapshots] = await Promise.all([positionsPromise, orderSnapshotsPromise]);
  const coinglassTrades = coinglassQualifiedBinanceTrades({
    audits: coinglassAudits,
    orderSnapshots,
    positions,
    trackingPositions: slTracking.positions,
    defaultMarginUsdt: coinGlassWebTop20.config().binanceMarginUsdt,
    defaultLeverage: coinGlassWebTop20.config().binanceLeverage,
  });
  const trades = [...paperTrades, ...coinglassTrades];
  const selected = liquidFlowV2RealTrades(trades, { fromDay, toDay, labelKey });
  const executions = liquidFlowV2SyntheticExecutions(selected);
  const closed = executions.filter((row) => row.status === 'POSITION_CLOSED');
  let reconciliationWarning = orderWarnings.length
    ? `CoinGlass order verify: ${orderWarnings.slice(0, 5).join(' | ')}`
    : null;
  let incomeRowsPromise = Promise.resolve([]);
  if (closed.length) {
    const startTime = Math.min(...closed.map((row) => Date.parse(row.entryFilledAt))) - 60_000;
    const endTime = Math.min(Date.now(), Math.max(...closed.map((row) => Date.parse(row.positionClosedAt))) + 60_000);
    const cached = liquidFlowV2BinanceStatsIncomeCache;
    if (cached && Date.now() - cached.at < LIQUID_FLOW_V2_BINANCE_STATS_CACHE_MS
      && cached.startTime <= startTime && cached.endTime >= endTime) {
      incomeRowsPromise = Promise.resolve(cached.rows);
    } else {
      incomeRowsPromise = fetchLiveCardIncomeRange({ startTime, endTime, ...credentials })
        .then((rawRows) => {
          const rows = [...new Map((Array.isArray(rawRows) ? rawRows : []).map((row) => [[
            row?.tranId ?? '', row?.tradeId ?? '', row?.symbol ?? '', row?.incomeType ?? '', row?.time ?? '', row?.income ?? '',
          ].join(':'), row])).values()];
          liquidFlowV2BinanceStatsIncomeCache = { at: Date.now(), startTime, endTime, rows };
          return rows;
        })
        .catch((error) => {
          reconciliationWarning = [reconciliationWarning, String(error?.message ?? error).slice(0, 300)]
            .filter(Boolean).join(' | ');
          console.warn(`[LiquidFlowV2BinanceStats] income: ${reconciliationWarning}`);
          return cached?.rows ?? [];
        });
    }
  }
  const incomeRows = await incomeRowsPromise;
  const reconciled = reconcileLiveCardClosedPnl(executions, incomeRows);
  return {
    ...buildLiquidFlowV2BinanceStats({
      trades,
      reconciled,
      positions,
      fromDay,
      toDay,
      labelKey,
    }),
    reconciliationWarning,
  };
}

async function syncLiveCardClosedPnl(token, executions = []) {
  const pending = (Array.isArray(executions) ? executions : []).filter((row) => (
    row?.status === 'POSITION_CLOSED'
    && row?.closedPnlKnown !== true
    && Number.isFinite(Date.parse(row?.positionClosedAt ?? ''))
  ));
  if (!pending.length) return { attempted: false, reconciled: 0, incomeRows: 0, error: null };

  const startTime = Math.min(...pending.map((row) => {
    const parsed = Date.parse(row.entrySubmittedAt ?? row.attemptedAt ?? row.entryFilledAt ?? '');
    return Number.isFinite(parsed) ? parsed - 60_000 : Date.parse(row.positionClosedAt) - 24 * 60 * 60_000;
  }));
  const endTime = Math.min(Date.now(), Math.max(...pending.map((row) => Date.parse(row.positionClosedAt) + 60_000)));
  if (isBinanceRestCongested()) {
    return { attempted: false, reconciled: 0, incomeRows: 0, error: 'BINANCE_REST_GATE_CONGESTED' };
  }
  const cached = _liveCardClosedPnlIncomeCache;
  if (cached && Date.now() - cached.at < LIVE_CARD_CLOSED_PNL_INCOME_TTL_MS
    && cached.startTime <= startTime && cached.endTime >= endTime) {
    const updated = await liveCardBinanceLifecycle.reconcileClosedPnl(cached.rows);
    return { attempted: true, reconciled: updated.length, incomeRows: cached.rows.length, error: null, cached: true };
  }
  if (_liveCardClosedPnlIncomeInflight) return _liveCardClosedPnlIncomeInflight;

  _liveCardClosedPnlIncomeInflight = (async () => {
    try {
      const { apiKey, apiSecret } = getApiCredentials(token);
      const rawRows = await fetchLiveCardIncomeRange({ startTime, endTime, apiKey, apiSecret });
      const deduped = [...new Map(rawRows.map((row) => [[
        row?.tranId ?? '', row?.tradeId ?? '', row?.symbol ?? '', row?.incomeType ?? '', row?.time ?? '', row?.income ?? '',
      ].join(':'), row])).values()];
      _liveCardClosedPnlIncomeCache = { at: Date.now(), startTime, endTime, rows: deduped };
      const updated = await liveCardBinanceLifecycle.reconcileClosedPnl(deduped);
      return { attempted: true, reconciled: updated.length, incomeRows: deduped.length, error: null, cached: false };
    } catch (error) {
      return {
        attempted: true,
        reconciled: 0,
        incomeRows: 0,
        error: String(error?.message ?? error).slice(0, 500),
      };
    } finally {
      _liveCardClosedPnlIncomeInflight = null;
    }
  })();
  return _liveCardClosedPnlIncomeInflight;
}

async function getPositions(token = null) {
  if (token) {
    const cached = ordersSessionSnapshots.get(token);
    if (cached && Date.now() - cached.verifiedAt < 15_000) {
      return cached.positions
        .filter((position) => Number(position.positionAmt) !== 0)
        .map((position) => ({
          ...position,
          pnlSource: 'BINANCE_SESSION_REST',
          pnlStreamVersion: ORDERS_POSITION_PNL_STREAM_VERSION,
        }));
    }
    const { apiKey, apiSecret } = getApiCredentials(token);
    const positions = await ordersAuthClient.getPositions({ apiKey, apiSecret });
    ordersSessionSnapshots.set(token, {
      verifiedAt: Date.now(),
      balance: cached?.balance ?? [],
      positions: Array.isArray(positions) ? positions : [],
    });
    return (Array.isArray(positions) ? positions : [])
      .filter((position) => Number(position.positionAmt) !== 0)
      .map((position) => ({
        ...position,
        pnlSource: 'BINANCE_SESSION_REST',
        pnlStreamVersion: ORDERS_POSITION_PNL_STREAM_VERSION,
      }));
  }
  const socketStatus = posMonitor?.getStatus?.() ?? null;
  const socketRows = posMonitor?.getActivePositions?.() ?? null;
  const socketSnapshotReady = Array.isArray(socketRows)
    && Number.isFinite(Number(socketStatus?.lastRestSyncAt))
    && Date.now() - Number(socketStatus.lastRestSyncAt) < 90_000;
  if (socketSnapshotReady) {
    const restBySymbol = new Map(
      (_posStore.positions ?? []).map((position) => [position.symbol, position]),
    );
    return socketRows.map((position) => {
      const rest = restBySymbol.get(position.symbol) ?? {};
      const markPrice = Number(position.markPrice) > 0
        ? position.markPrice
        : rest.markPrice ?? 0;
      const unRealizedProfit = Number(position.markPrice) > 0
        ? position.unRealizedProfit
        : rest.unRealizedProfit ?? 0;
      return {
        ...rest,
        ...position,
        markPrice,
        unRealizedProfit,
        liquidationPrice: Number(position.liquidationPrice) > 0
          ? position.liquidationPrice
          : rest.liquidationPrice ?? 0,
        pnlSource: 'BINANCE_POSITION_MONITOR_SOCKET',
        pnlStreamVersion: ORDERS_POSITION_PNL_STREAM_VERSION,
      };
    });
  }
  const { positions } = await getSharedPositionData();
  return positions.map((position) => ({
    ...position,
    pnlSource: 'BINANCE_REST_FALLBACK',
    pnlStreamVersion: ORDERS_POSITION_PNL_STREAM_VERSION,
  }));
}

// ── Shared position data store ─────────────────────────────────────────────
// Gom positions + openOrders + algoOrders vào 1 cache TTL 30s.
// Tất cả scanners dùng chung — tối đa 1 REST burst per TTL window.
let _posStore = { positions: [], openOrders: [], algoOrders: [], fetchedAt: 0 };
let _posStoreInflight = null;
const POS_STORE_TTL_MS = 60_000; // 60s — positions/openOrders không cần <30s; giảm getOpenOrders(w=40) frequency

async function getSharedPositionData({ bypassAlgoRestDefer = false } = {}) {
  if (Date.now() - _posStore.fetchedAt < POS_STORE_TTL_MS) return _posStore;
  if (_posStoreInflight) return _posStoreInflight;
  if (!bypassAlgoRestDefer && shouldDeferAlgoRest()) return _posStore;
  let creds;
  try { creds = getApiCredentials(null); } catch { return _posStore; }
  const { apiKey, apiSecret } = creds;
  _posStoreInflight = (async () => {
    try {
      const [positions, openOrders, algoResult] = await Promise.all([
        client.getPositions({ apiKey, apiSecret }),
        client.getOpenOrders({ apiKey, apiSecret }),
        client.getOpenAlgoOrders({ apiKey, apiSecret }).catch(() => ({ orders: [] })),
      ]);
      const algoOrders = Array.isArray(algoResult?.orders) ? algoResult.orders
        : Array.isArray(algoResult) ? algoResult : [];
      _posStore = {
        positions: positions.filter((p) => Number(p.positionAmt) !== 0),
        openOrders: Array.isArray(openOrders) ? openOrders : [],
        algoOrders,
        fetchedAt: Date.now(),
      };
      _openOrdersCache = _posStore.openOrders;
      _openOrdersCacheAt = _posStore.fetchedAt;
    } catch (err) {
      if (!err.message?.includes('Missing Binance API')) console.error('[PosStore] fetch error:', err.message);
    }
    return _posStore;
  })();
  try { return await _posStoreInflight; } finally { _posStoreInflight = null; }
}

function invalidatePosStore() { _posStore = { ..._posStore, fetchedAt: 0 }; }

// ── Open orders cache — tránh gọi REST liên tục ───────────────────────────────
// Invalidate bằng invalidateOpenOrdersCache() sau mỗi lần đặt/hủy lệnh hoặc fill
let _openOrdersCache = null;      // cached array (all symbols, no-token)
let _openOrdersCacheAt = 0;
let _openOrdersInflight = null;
const OPEN_ORDERS_TTL = 30_000;   // 30s TTL fallback nếu không invalidate

function invalidateOpenOrdersCache() {
  _openOrdersCache = null;
  _openOrdersCacheAt = 0;
  invalidatePosStore();
}

async function getCachedOpenOrders(apiKey, apiSecret) {
  if (_openOrdersCache && Date.now() - _openOrdersCacheAt < OPEN_ORDERS_TTL) {
    return _openOrdersCache;
  }
  if (_openOrdersInflight) return _openOrdersInflight;
  _openOrdersInflight = client.getOpenOrders({ apiKey, apiSecret })
    .then((rows) => {
      _openOrdersCache = rows;
      _openOrdersCacheAt = Date.now();
      return _openOrdersCache;
    })
    .finally(() => { _openOrdersInflight = null; });
  return _openOrdersInflight;
}

async function getOpenOrders(symbol, token = null) {
  if (token) {
    const { apiKey, apiSecret } = getApiCredentials(token);
    const rows = await ordersAuthClient.getOpenOrders({ symbol, apiKey, apiSecret });
    return Array.isArray(rows) ? rows : [];
  }
  const { openOrders } = await getSharedPositionData();
  return symbol ? openOrders.filter((o) => o.symbol === symbol) : openOrders;
}

async function getOpenAlgoOrdersList(token = null) {
  if (token) {
    const { apiKey, apiSecret } = getApiCredentials(token);
    const result = await ordersAuthClient.getOpenAlgoOrders({ apiKey, apiSecret });
    const rows = Array.isArray(result?.orders) ? result.orders : Array.isArray(result) ? result : [];
    return [...new Map(rows.map((row) => [
      row.algoId ?? row.clientAlgoId ?? `${row.symbol}:${row.triggerPrice}:${row.side}`,
      row,
    ])).values()];
  }
  const { algoOrders } = await getSharedPositionData();
  const byId = new Map();
  for (const row of algoOrders) byId.set(row.algoId ?? row.clientAlgoId ?? `${row.symbol}:${row.triggerPrice}:${row.side}`, row);
  return [...byId.values()];
}

async function getRecentTrades(symbol, limit, token = null) {
  const { apiKey, apiSecret } = getApiCredentials(token);
  return client.getUserTrades({ symbol, limit, apiKey, apiSecret });
}

async function cancelOrder(payload, token = null) {
  const symbol = normalizeSymbol(payload.symbol ?? '');
  const orderId = Number(payload.orderId);
  if (!symbol || !orderId) throw new Error('symbol and orderId are required.');
  const { apiKey, apiSecret } = getApiCredentials(token);
  return client.cancelOrder({ symbol, orderId, apiKey, apiSecret });
}

async function cancelAllOrdersForSymbol(symbol, apiKey, apiSecret) {
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  let regularCount = 0;
  let algoCount = 0;

  try {
    await client.cancelAllOpenOrders({ symbol, apiKey, apiSecret, recvWindow });
    regularCount = 1; // API doesn't return count, just success
    console.log(`[CancelAll] ${symbol} regular orders cancelled`);
  } catch (err) {
    // -2011 = no open orders, not a real error
    if (!err.message?.includes('-2011')) {
      console.warn(`[CancelAll] ${symbol} regular: ${err.message}`);
    }
  }

  try {
    const algoResult = await client.getOpenAlgoOrders({ apiKey, apiSecret, recvWindow });
    const allAlgo = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
    // Filter client-side: only cancel orders belonging to this symbol
    const algoOrders = allAlgo.filter((o) => o.symbol === symbol);
    for (const o of algoOrders) {
      try {
        await client.cancelAlgoOrder({ algoId: o.algoId, apiKey, apiSecret, recvWindow });
        algoCount += 1;
      } catch (err) {
        console.warn(`[CancelAll] ${symbol} algoId=${o.algoId}: ${err.message}`);
      }
    }
    if (algoCount > 0) console.log(`[CancelAll] ${symbol} ${algoCount} algo order(s) cancelled`);
  } catch (err) {
    console.warn(`[CancelAll] ${symbol} algo fetch: ${err.message}`);
  }

  return { symbol, regularCount, algoCount };
}

function autoCancelEntryLimitOrdersEnabled() {
  return isAutoCancelEntryLimitEnabled(process.env.AUTO_CANCEL_ENTRY_LIMIT_ORDERS);
}

async function confirmBinancePositionClosed(symbol, apiKey, apiSecret, source = 'protectionCleanup:confirmClosed') {
  const positions = await client.getPositions({
    apiKey,
    apiSecret,
    priority: 0,
    dropOnCongestion: false,
    source,
  });
  const activePosition = activeBinancePositionForSymbol(positions, symbol);
  return { closed: activePosition == null, activePosition };
}

function restorePositionMonitorFromBinance(position) {
  if (!position || !posMonitor) return;
  posMonitor.trackPosition(position.symbol, {
    amt: Number(position.positionAmt),
    entry: Number(position.entryPrice),
    leverage: Number(position.leverage) || 1,
    isolatedMargin: Number(position.isolatedMargin),
    initialMargin: Number(position.positionInitialMargin ?? position.initialMargin),
    positionSide: position.positionSide ?? 'BOTH',
  });
}

async function handleConfirmedPositionClose(symbol) {
  const { apiKey, apiSecret } = getApiCredentials(null);
  await new Promise((resolve) => setTimeout(resolve, 750));
  const confirmation = await confirmBinancePositionClosed(
    symbol,
    apiKey,
    apiSecret,
    'positionSocketClose:confirmClosed',
  );
  if (!confirmation.closed) {
    restorePositionMonitorFromBinance(confirmation.activePosition);
    console.warn(
      `[ProtectionCleanup] ${symbol} stale/out-of-order close ignored; Binance position is active`
      + ` version=${BINANCE_POSITION_CLOSE_CONFIRM_VERSION}`,
    );
    return { symbol, skipped: 'POSITION_ACTIVE' };
  }

  console.log(
    `[PosMonitor] ${symbol} close confirmed by Binance Position Risk -> cleaning TP/SL, retaining LIMIT orders`
    + ` version=${BINANCE_POSITION_CLOSE_CONFIRM_VERSION}`,
  );
  broadcastOrdersPositionPnl('position-closed', {
    version: ORDERS_POSITION_PNL_STREAM_VERSION,
    symbol,
    eventAt: Date.now(),
  });
  signalProtectionPlans.delete(symbol);
  twelveHourTpMoved.delete(symbol);
  twelveHourTpLastRun.delete(symbol);
  twelveHourTpRunning.delete(symbol);
  positionFirstSeenAt.delete(symbol);
  resetBinanceProfitLockRuntime(symbol, 'POSITION_CLOSED');
  if (slTracking.positions?.[symbol]) {
    delete slTracking.positions[symbol];
    saveSlTracking();
  }
  await liveCardBinanceLifecycle.markPositionClosed(symbol).catch((error) => {
    console.warn(`[LiveCardLifecycle] mark closed ${symbol}:`, error.message);
  });
  broadcastOrdersPositionPnl('live-card-lifecycle', {
    version: ORDERS_POSITION_PNL_STREAM_VERSION,
    symbol,
    status: 'POSITION_CLOSED',
    eventAt: Date.now(),
  });
  const result = await cancelAutomaticProtectionOrdersForSymbol(
    symbol,
    apiKey,
    apiSecret,
    { confirmedClosed: true },
  );
  invalidateOpenOrdersCache();
  return result;
}

async function cancelAutomaticProtectionOrdersForSymbol(symbol, apiKey, apiSecret, { confirmedClosed = false } = {}) {
  if (!confirmedClosed) {
    const confirmation = await confirmBinancePositionClosed(symbol, apiKey, apiSecret);
    if (!confirmation.closed) {
      console.warn(
        `[ProtectionCleanup] ${symbol} cancel refused: Binance position is active`
        + ` version=${BINANCE_POSITION_CLOSE_CONFIRM_VERSION}`,
      );
      return { symbol, regularCount: 0, algoCount: 0, retainedLimits: 0, skipped: 'POSITION_ACTIVE' };
    }
  }
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  const regularOrders = await client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }).catch((error) => {
    console.warn(`[ProtectionCleanup] ${symbol} regular fetch: ${error.message}`);
    return [];
  });
  const protectionOrders = selectAutomaticProtectionCleanupOrders(regularOrders);
  let regularCount = 0;
  for (const order of protectionOrders) {
    if (order?.orderId == null) continue;
    await client.cancelOrder({ symbol, orderId: order.orderId, apiKey, apiSecret, recvWindow })
      .then(() => { regularCount += 1; })
      .catch((error) => console.warn(`[ProtectionCleanup] ${symbol} orderId=${order.orderId}: ${error.message}`));
  }

  const algoResult = await client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }).catch((error) => {
    console.warn(`[ProtectionCleanup] ${symbol} algo fetch: ${error.message}`);
    return { orders: [] };
  });
  const algoOrders = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
  let algoCount = 0;
  for (const order of algoOrders.filter((row) => row?.symbol === symbol)) {
    if (order?.algoId == null) continue;
    await client.cancelAlgoOrder({ algoId: order.algoId, apiKey, apiSecret, recvWindow })
      .then(() => { algoCount += 1; })
      .catch((error) => console.warn(`[ProtectionCleanup] ${symbol} algoId=${order.algoId}: ${error.message}`));
  }
  const retainedLimits = (Array.isArray(regularOrders) ? regularOrders : []).filter(isRegularLimitOrder).length;
  if (regularCount || algoCount || retainedLimits) {
    console.log(
      `[ProtectionCleanup] ${symbol} regular=${regularCount} algo=${algoCount} `
      + `LIMIT retained=${retainedLimits} version=${LIMIT_ORDER_RETENTION_VERSION}`,
    );
  }
  return { symbol, regularCount, algoCount, retainedLimits };
}

// ── BTC Trend Monitor — cancel contra-trend LIMIT orders on bias shift ──────────

let _prevBtcBias = { bear: 'neutral', bull: 'neutral' };
let _btcHealthMonitorRunning = false;

async function cancelContraTrendLimitOrders(direction, health, webhookUrl) {
  if (!autoCancelEntryLimitOrdersEnabled()) {
    console.log(`[BtcTrend] ${direction} LIMIT retained; automatic cancellation disabled (${LIMIT_ORDER_RETENTION_VERSION})`);
    return;
  }
  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const allOrders = await getCachedOpenOrders(apiKey, apiSecret);
    const isReduceOnly = (o) => o.reduceOnly === true || o.reduceOnly === 'true';
    const isLimit = (o) => ['LIMIT', 'LIMIT_MAKER'].includes(String(o.type ?? o.origType ?? '').toUpperCase());
    const side = direction === 'LONG' ? 'BUY' : 'SELL';
    const targets = allOrders.filter((o) => isLimit(o) && !isReduceOnly(o) && o.side === side);
    if (!targets.length) return;

    const cancelled = [];
    for (const o of targets) {
      try {
        await client.cancelOrder({ symbol: o.symbol, orderId: o.orderId, apiKey, apiSecret });
        cancelled.push(o.symbol);
        console.log(`[BtcTrend] 🗑 Cancelled ${o.symbol} ${direction} LIMIT #${o.orderId}`);
      } catch (e) {
        console.warn(`[BtcTrend] ⚠ Cancel ${o.symbol} #${o.orderId}: ${e.message}`);
      }
    }

    if (cancelled.length && webhookUrl) {
      const btcSide = direction === 'LONG' ? `bearish (${health.bearPoints}/8)` : `bullish (${health.bullPoints}/6)`;
      const msg = `🗑 **Contra-trend LIMIT xoá** | BTC ${btcSide}\n` +
        `Đã cancel **${cancelled.length}** lệnh ${direction} LIMIT: ${cancelled.join(', ')}\n` +
        `RSI 1h: ${health.rsi1h} · RSI 4h: ${health.rsi4h} · EMA20 1h: ${health.emaTrend1h} · 6h: ${health.pct6h != null ? (health.pct6h > 0 ? '+' : '') + health.pct6h + '%' : '–'}`;
      fetch(webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ content: msg }),
      }).catch(() => {});
    }
  } catch (e) {
    if (e.message?.includes('Missing Binance API')) return;
    console.error('[BtcTrend] cancel error:', e.message);
  }
}

async function runBtcHealthMonitor() {
  if (_btcHealthMonitorRunning) return;
  _btcHealthMonitorRunning = true;
  try {
    // Force refresh để luôn đọc data mới nhất
    btcHealthCache.expiresAt = 0;
    const health = await getBtcHealth();
    if (!health || health.error) return;

    const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
    const prevBear = _prevBtcBias.bear;
    const currBear = health.bias;
    const prevBull = _prevBtcBias.bull;
    const currBull = health.bullBias;

    // Chuyển sang xấu → cancel LONG LIMIT
    if (prevBear === 'neutral' && (currBear === 'caution' || currBear === 'bearish')) {
      console.log(`[BtcTrend] 🔴 Bear shift: ${prevBear} → ${currBear} — cancelling LONG LIMITs`);
      await cancelContraTrendLimitOrders('LONG', health, webhookUrl);
    }

    // Chuyển sang tốt → cancel SHORT LIMIT
    if (prevBull === 'neutral' && (currBull === 'caution' || currBull === 'bullish')) {
      console.log(`[BtcTrend] 🟢 Bull shift: ${prevBull} → ${currBull} — cancelling SHORT LIMITs`);
      await cancelContraTrendLimitOrders('SHORT', health, webhookUrl);
    }

    _prevBtcBias = { bear: currBear, bull: currBull };
  } catch (e) {
    if (e.message?.includes('Missing Binance API')) return;
    console.warn('[BtcTrend] monitor error:', e.message);
  } finally {
    _btcHealthMonitorRunning = false;
  }
}

const lastKnownPositions = new Map(); // symbol → { unRealizedProfit, positionAmt }

async function runStaleOrderCleaner() {
  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const { positions } = await getSharedPositionData();
    const activeMap = new Map(
      positions
        .map((p) => [p.symbol, { unRealizedProfit: Number(p.unRealizedProfit), positionAmt: Number(p.positionAmt) }]),
    );

    if (lastKnownPositions.size > 0) {
      for (const [sym, prev] of lastKnownPositions) {
        if (activeMap.has(sym)) continue;

        let closeConfirmation;
        try {
          closeConfirmation = await confirmBinancePositionClosed(
            sym,
            apiKey,
            apiSecret,
            'staleOrderCleaner:confirmClosed',
          );
        } catch (error) {
          console.warn(`[StaleOrders] ${sym} close confirmation failed; cleanup skipped: ${error.message}`);
          continue;
        }
        if (!closeConfirmation.closed) {
          const active = closeConfirmation.activePosition;
          activeMap.set(sym, {
            unRealizedProfit: Number(active.unRealizedProfit),
            positionAmt: Number(active.positionAmt),
          });
          restorePositionMonitorFromBinance(active);
          console.warn(
            `[StaleOrders] ${sym} transient snapshot omission ignored; Binance position is active`
            + ` version=${BINANCE_POSITION_CLOSE_CONFIRM_VERSION}`,
          );
          continue;
        }

        avgDownFired.delete(sym);
        tpMovedToEntry.delete(sym);
        twelveHourTpMoved.delete(sym);
        twelveHourTpLastRun.delete(sym);
        twelveHourTpRunning.delete(sym);
        tpConfirmedClear(sym);
        negTpLastRun.delete(sym);
        negativeSince.delete(sym);
        slTrailLockRoe.delete(sym);
        slTrailLastRun.delete(sym);
        positionFirstSeenAt.delete(sym);
        positionTimeoutFired.delete(sym);
        if (slTracking.positions[sym]) {
          delete slTracking.positions[sym];
          saveSlTracking();
        }
        console.log(`[StaleOrders] ${sym} closed → cleaning TP/SL, retaining LIMIT orders`);
        cancelAutomaticProtectionOrdersForSymbol(sym, apiKey, apiSecret, { confirmedClosed: true }).catch((err) =>
          console.warn(`[StaleOrders] protection cleanup ${sym}: ${err.message}`),
        );

        // Detect SL: fetch last few trades, if closing trade has negative realizedPnl → blacklist 2h
        try {
          const trades = await client.getUserTrades({ symbol: sym, limit: 5, apiKey, apiSecret });
          if (trades.length > 0) {
            const last = trades[trades.length - 1];
            const pnl = Number(last.realizedPnl);
            if (pnl < 0) {
              await addToDynamicBlacklist(sym, 2 * 60 * 60 * 1000, `SL hit pnl=${pnl.toFixed(4)}`);
            }
          }
        } catch (err) {
          console.warn(`[StaleOrders] ${sym} trade check: ${err.message}`);
        }
      }
    }

    lastKnownPositions.clear();
    for (const [sym, data] of activeMap) lastKnownPositions.set(sym, data);

    // Entry LIMIT auto-cancel is opt-in. Default keeps pending LIMIT orders until manual cancel/fill.
    const staleMs = Number(process.env.STALE_ORDER_TIMEOUT_MS ?? 30 * 60 * 1000);
    if (autoCancelEntryLimitOrdersEnabled() && staleMs > 0) {
      const allOrders = await client.getOpenOrders({ apiKey, apiSecret });
      const now = Date.now();
      const isReduceOnly = (o) => o.reduceOnly === true || o.reduceOnly === 'true';
      const isLimitType  = (o) => {
        const t = String(o.type ?? o.origType ?? '').toUpperCase();
        return t === 'LIMIT' || t === 'LIMIT_MAKER';
      };
      const stale = allOrders.filter(
        (o) => isLimitType(o) && !isReduceOnly(o) && (now - Number(o.time)) > staleMs,
      );
      for (const o of stale) {
        const ageMin = Math.round((now - Number(o.time)) / 60000);
        try {
          await client.cancelOrder({ symbol: o.symbol, orderId: o.orderId, apiKey, apiSecret });
          console.log(`[StaleOrders] Cancelled ${o.symbol} #${o.orderId} LIMIT ${o.side} — ${ageMin}min old`);
        } catch (err) {
          console.warn(`[StaleOrders] Cancel ${o.symbol} #${o.orderId}: ${err.message}`);
        }
      }
    }
  } catch (err) {
    if (err.message?.includes('Missing Binance API')) return;
    console.error('[StaleOrders] Scan error:', err.message);
  }
}

function getTargetLockRoe(roe) {
  // 10→1, 15→5, 20→10, 25→15, 30→20, ...
  if (roe >= 15) {
    const steps = Math.floor((roe - 15) / 5);
    return (15 + steps * 5) - 10;
  }
  if (roe >= 10) return 1;
  return null;
}

function getBinanceProfitLockTargetRoe(roe) {
  return resolveBinanceProfitLockRoe(roe, {
    triggerRoe: Number(process.env.BINANCE_PROFIT_LOCK_TRIGGER_ROE ?? 5),
    firstLockRoe: Number(process.env.BINANCE_PROFIT_LOCK_FIRST_LOCK_ROE ?? 1),
  });
}

function isLiquidFlowV2ManagedPosition(symbol, pos = {}) {
  const normalizedSymbol = normalizeSymbol(symbol);
  const tracking = slTracking.positions?.[normalizedSymbol] ?? slTracking.positions?.[symbol] ?? null;
  const plan = signalProtectionPlans.get(normalizedSymbol) ?? signalProtectionPlans.get(symbol) ?? null;
  if (isLiquidFlowV2ProfitLockSource(tracking?.signalSource, plan?.source)) return true;

  const side = Number(pos.amt ?? pos.positionAmt) >= 0 ? 'LONG' : 'SHORT';
  return matchesLiquidFlowV2ProfitLockTrade({
    symbol: normalizedSymbol,
    side,
    entryPrice: pos.entry ?? pos.entryPrice,
    openedAt: tracking?.openedAt,
    trades: liquidFlowV2Paper.state.trades,
  });
}

function isManualBinanceManagedPosition(symbol, pos = {}) {
  const normalizedSymbol = normalizeSymbol(symbol);
  const tracking = slTracking.positions?.[normalizedSymbol] ?? slTracking.positions?.[symbol] ?? null;
  const plan = signalProtectionPlans.get(normalizedSymbol) ?? signalProtectionPlans.get(symbol) ?? null;
  // The current in-memory plan is newer than persisted tracking from a prior
  // lifecycle on the same symbol, so it must win classification.
  if (String(plan?.source ?? '').trim()) {
    return isManualBinanceProfitLockSource(plan.source) && !plan?.lifecycleId;
  }
  if (String(tracking?.signalSource ?? '').trim()) {
    return isManualBinanceProfitLockSource(tracking.signalSource) && !tracking?.lifecycleId;
  }
  if (tracking?.lifecycleId || plan?.lifecycleId) return false;

  const side = Number(pos.amt ?? pos.positionAmt) >= 0 ? 'LONG' : 'SHORT';
  if (matchesManualLiquidFlowV2ProfitLockTrade({
    symbol: normalizedSymbol,
    side,
    entryPrice: pos.entry ?? pos.entryPrice,
    openedAt: tracking?.openedAt,
    trades: liquidFlowV2Paper.state.trades,
  })) return true;

  // Binance-app/manual fills have no bot source, plan or lifecycle.
  return true;
}

function isTakeProfitUserOrLiquidFlowV2ManagedPosition(symbol, pos = {}) {
  if (isLiquidFlowV2ManagedPosition(symbol, pos)) return true;
  const normalizedSymbol = normalizeSymbol(symbol);
  const tracking = slTracking.positions?.[normalizedSymbol] ?? slTracking.positions?.[symbol] ?? null;
  const plan = signalProtectionPlans.get(normalizedSymbol) ?? signalProtectionPlans.get(symbol) ?? null;
  return isUserOrLiquidFlowV2ManagedSource(tracking?.signalSource, plan?.source);
}

async function rememberBinanceProfitLock(symbol, stopLossPrice, lockRoe, lifecycleKey = null) {
  const tracking = slTracking.positions?.[symbol] ?? null;
  const lifecycleId = tracking?.lifecycleId ?? signalProtectionPlans.get(symbol)?.lifecycleId ?? null;
  if (tracking) {
    if (tracking.preserveSignalProtection === true) tracking.signalSl = Number(stopLossPrice);
    tracking.slPlaced = true;
    tracking.slPrice = Number(stopLossPrice);
    tracking.slPlacedAt = new Date().toISOString();
    tracking.profitLockVersion = BINANCE_PROFIT_LOCK_VERSION;
    tracking.profitLockLifecycleKey = lifecycleKey;
    tracking.profitLockArmedRoe = Number(lockRoe);
    tracking.profitLockArmedLifecycleKey = lifecycleKey;
    tracking.profitLockRoe = Number(lockRoe);
    tracking.profitLockStopLossPrice = Number(stopLossPrice);
    tracking.profitLockUpdatedAt = new Date().toISOString();
    saveSlTracking();
  }
  if (lifecycleId) {
    await liveCardBinanceLifecycle.upsert({
      lifecycleId,
      stopLossPrice: Number(stopLossPrice),
      profitLockVersion: BINANCE_PROFIT_LOCK_VERSION,
      profitLockRoe: Number(lockRoe),
      profitLockStopLossPrice: Number(stopLossPrice),
      profitLockLifecycleKey: lifecycleKey,
      profitLockArmedRoe: Number(lockRoe),
      profitLockArmedLifecycleKey: lifecycleKey,
      profitLockUpdatedAt: new Date().toISOString(),
    }, 'PROFIT_LOCK_SL_MOVED', {
      symbol,
      lockRoe: Number(lockRoe),
      stopLossPrice: Number(stopLossPrice),
    }).catch((error) => console.warn(`[ProfitLock] lifecycle ${symbol}:`, error.message));
    broadcastOrdersPositionPnl('live-card-lifecycle', {
      version: ORDERS_POSITION_PNL_STREAM_VERSION,
      lifecycleId,
      symbol,
      eventType: 'PROFIT_LOCK_SL_MOVED',
      eventAt: Date.now(),
    });
  }
}

function resetBinanceProfitLockRuntime(symbol, reason = 'UNKNOWN') {
  const normalizedSymbol = normalizeSymbol(symbol);
  const previousLock = slTrailLockRoe.get(normalizedSymbol);
  slTrailLockRoe.delete(normalizedSymbol);
  slTrailLastRun.delete(normalizedSymbol);
  const tracking = slTracking.positions?.[normalizedSymbol] ?? null;
  if (tracking) {
    delete tracking.profitLockArmedRoe;
    delete tracking.profitLockArmedAt;
    delete tracking.profitLockArmedLifecycleKey;
    delete tracking.profitLockArmedObservedRoe;
    delete tracking.profitLockArmedMarkPrice;
    delete tracking.profitLockLifecycleKey;
    delete tracking.profitLockRoe;
    delete tracking.profitLockStopLossPrice;
    delete tracking.profitLockUpdatedAt;
    saveSlTracking();
  }
  if (previousLock != null) {
    console.log(`[ProfitLock] reset ${normalizedSymbol} reason=${reason}`);
  }
}

function armBinanceProfitLock(symbol, targetLockRoe, lifecycleKey, roe, markPrice) {
  const tracking = slTracking.positions?.[symbol] ?? null;
  if (!tracking || !lifecycleKey) return;
  const persistedKey = String(tracking.profitLockArmedLifecycleKey ?? '');
  const persistedRoe = persistedKey === lifecycleKey
    ? Number(tracking.profitLockArmedRoe ?? -Infinity)
    : -Infinity;
  if (Number.isFinite(persistedRoe) && persistedRoe >= targetLockRoe) return;
  tracking.profitLockVersion = BINANCE_PROFIT_LOCK_VERSION;
  tracking.profitLockArmedRoe = Number(targetLockRoe);
  tracking.profitLockArmedAt = new Date().toISOString();
  tracking.profitLockArmedLifecycleKey = lifecycleKey;
  tracking.profitLockArmedObservedRoe = Number(roe);
  tracking.profitLockArmedMarkPrice = Number(markPrice) || null;
  saveSlTracking();
  console.log(`[ProfitLock] ARMED ${symbol} ROE=${Number(roe).toFixed(1)}% target=+${targetLockRoe}% lifecycle=${lifecycleKey}`);
}

const slTrailRunning = new Set();
const slGuardRunning = new Set();
const slTrailLockRoe = new Map(); // symbol → { lockRoe, lifecycleKey } (in-memory dedup)
const slTrailLastRun = new Map(); // symbol → timestamp of last API call
const SL_TRAIL_COOLDOWN_MS = 60_000; // tối thiểu 60s giữa 2 lần gọi API cho cùng symbol
const SL_TRAIL_IMMEDIATE_TRIGGER_RETRY_MS = 5_000;

async function closeBinancePositionAtBreachedProfitLock(symbol, context) {
  const { apiKey, apiSecret, symbolInfo, targetLockRoe, stopPrice, isLong } = context;
  const [positions, premiumIndex] = await Promise.all([
    client.getPositions({
      apiKey,
      apiSecret,
      priority: 0,
      dropOnCongestion: false,
      source: 'profitLock:immediateTriggerPosition',
    }),
    client.getPremiumIndex(symbol),
  ]);
  const current = (Array.isArray(positions) ? positions : []).find((row) => {
    if (normalizeSymbol(row?.symbol) !== symbol) return false;
    const amount = Number(row?.positionAmt ?? row?.amt);
    return isLong ? amount > 0 : amount < 0;
  });
  if (!current) return { closed: false, reason: 'POSITION_ALREADY_CLOSED' };

  const latestMark = Number(premiumIndex?.markPrice ?? current.markPrice);
  if (!isBinanceProfitLockTargetBreached({
    side: isLong ? 'LONG' : 'SHORT',
    markPrice: latestMark,
    stopPrice,
  })) {
    return { closed: false, reason: 'LATEST_MARK_NOT_BREACHED', latestMark };
  }

  const currentAmount = Number(current.positionAmt ?? current.amt);
  const lotSize = symbolInfo.filters?.find((filter) => filter.filterType === 'LOT_SIZE');
  const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
  const steppedQty = Math.floor(Math.abs(currentAmount) / stepSize) * stepSize;
  const quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');
  if (!(Number(quantity) > 0)) return { closed: false, reason: 'INVALID_QUANTITY', latestMark };

  const positionSide = String(current.positionSide ?? 'BOTH').toUpperCase();
  const closeIsLong = positionSide === 'LONG'
    ? true
    : positionSide === 'SHORT'
      ? false
      : currentAmount > 0;
  const closeParams = {
    symbol,
    side: closeIsLong ? 'SELL' : 'BUY',
    type: 'MARKET',
    quantity,
    recvWindow: Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000),
    newClientOrderId: `lp_plx_${Date.now()}`.slice(0, 36),
  };
  if (positionSide !== 'BOTH') closeParams.positionSide = positionSide;
  else closeParams.reduceOnly = 'true';

  const order = await client.placeFuturesOrder({ params: closeParams, apiKey, apiSecret });
  console.error(
    `[SlTrailEmergency] ✅ ${symbol} target +${targetLockRoe}% @ ${stopPrice} was crossed`
    + ` (latest mark ${latestMark}); reduce-only MARKET close orderId=${order?.orderId ?? '-'} version=${BINANCE_PROFIT_LOCK_VERSION}`,
  );
  return { closed: true, latestMark, orderId: order?.orderId ?? null };
}

async function handleSlTrailByProfit(symbol, pos, roe, markPrice = null) {
  if (process.env.AUTO_SL_ENABLED === 'false') return;
  const isManualPosition = isManualBinanceManagedPosition(symbol, pos);
  const isLiquidFlowV2Position = isLiquidFlowV2ManagedPosition(symbol, pos);
  if (slTrailRunning.has(symbol)) return;
  const lastRun = slTrailLastRun.get(symbol) ?? 0;
  if (Date.now() - lastRun < SL_TRAIL_COOLDOWN_MS) return;

  const usesRoe10Lock1 = isManualPosition || isLiquidFlowV2Position;
  const isOrdersExcluded = isCapTslSymbol(symbol);
  const observedTargetLockRoe = isOrdersExcluded
    ? resolveOrdersExcludedBinanceProfitLockRoe(roe)
    : usesRoe10Lock1
      ? resolveManualBinanceProfitLockRoe(roe)
      : getBinanceProfitLockTargetRoe(roe);
  const isLong = Number(pos.amt ?? pos.positionAmt) > 0;
  const entry = Number(pos.entry ?? pos.entryPrice);
  if (!isFinite(entry) || entry <= 0) return;
  const tracking = slTracking.positions?.[symbol] ?? null;
  const lifecycleKey = binanceProfitLockLifecycleKey({
    symbol,
    side: isLong ? 'LONG' : 'SHORT',
    entryPrice: entry,
    openedAt: tracking?.openedAt,
  });
  const persistedTargetLockRoe = String(tracking?.profitLockArmedLifecycleKey ?? '') === lifecycleKey
    ? Number(tracking?.profitLockArmedRoe)
    : NaN;
  const targetLockRoe = Number.isFinite(persistedTargetLockRoe)
    ? Math.max(observedTargetLockRoe ?? -Infinity, persistedTargetLockRoe)
    : observedTargetLockRoe;
  if (targetLockRoe === null || !Number.isFinite(targetLockRoe)) return;

  if (observedTargetLockRoe != null) {
    armBinanceProfitLock(symbol, observedTargetLockRoe, lifecycleKey, roe, markPrice);
  }
  const lockState = slTrailLockRoe.get(symbol);
  const currentLockRoe = lockState?.lifecycleKey === lifecycleKey
    ? Number(lockState.lockRoe)
    : -Infinity;
  if (lockState && lockState.lifecycleKey !== lifecycleKey) {
    slTrailLockRoe.delete(symbol);
    slTrailLastRun.delete(symbol);
    console.warn(`[ProfitLock] ${symbol} discarded stale in-memory lifecycle ${lockState.lifecycleKey ?? '-'}`);
  }
  if (targetLockRoe <= currentLockRoe) return;

  slTrailRunning.add(symbol);
  slTrailLastRun.set(symbol, Date.now());
  let emergencyContext = null;
  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

    const [algoResult, openOrdersResult, symbolList] = await Promise.all([
      client.getOpenAlgoOrders({
        symbol,
        apiKey,
        apiSecret,
        priority: 0,
        dropOnCongestion: false,
        source: 'profitLock:openAlgoOrders',
      }),
      client.getOpenOrders({
        symbol,
        apiKey,
        apiSecret,
        priority: 0,
        dropOnCongestion: false,
        source: 'profitLock:openOrders',
      }),
      getSymbols(),
    ]);
    const allAlgo = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
    const allOpen = Array.isArray(openOrdersResult) ? openOrdersResult : [];

    // Prefer explicit STOP type. Old algo JSON may only expose CONDITIONAL, where
    // the loss-side trigger remains the compatibility fallback.
    const algoSl = allAlgo.find((o) => {
      if (o.symbol !== symbol) return false;
      const side = String(o.side ?? '').toUpperCase();
      const closingSide = (isLong && side === 'SELL') || (!isLong && side === 'BUY');
      const orderType = String(o.orderType ?? o.origType ?? o.type ?? '').toUpperCase();
      const isStopType = orderType === 'STOP_MARKET' || orderType === 'STOP';
      const triggerP = Number(o.triggerPrice ?? o.stopPrice ?? 0);
      const isSLSide = triggerP > 0 && (isLong ? triggerP < entry : triggerP > entry);
      return closingSide && (isStopType || (orderType === 'CONDITIONAL' && isSLSide));
    });
    // Regular SL: STOP_MARKET or STOP type
    const regularSl = allOpen.find((o) => {
      if (o.symbol !== symbol) return false;
      const t = String(o.type ?? '').toUpperCase();
      return t === 'STOP_MARKET' || t === 'STOP';
    });
    const slOrder = algoSl || regularSl;

    const symbolInfo = symbolList.find((s) => s.symbol === symbol);
    if (!symbolInfo) return;

    const leverage = pos.leverage || 10;

    const rawSlPrice = binanceProfitLockStopPrice({
      side: isLong ? 'LONG' : 'SHORT',
      entryPrice: entry,
      leverage,
      lockRoe: targetLockRoe,
    });
    if (!isFinite(rawSlPrice) || rawSlPrice <= 0) return;
    const newSlPrice = priceFromTick(symbolInfo, rawSlPrice);
    if (!newSlPrice || newSlPrice === 'NaN' || Number(newSlPrice) <= 0) return;

    emergencyContext = {
      apiKey,
      apiSecret,
      symbolInfo,
      targetLockRoe,
      stopPrice: Number(newSlPrice),
      isLong,
    };

    const mark = Number(markPrice ?? 0);
    if (mark > 0 && isBinanceProfitLockTargetBreached({
      side: isLong ? 'LONG' : 'SHORT',
      markPrice: mark,
      stopPrice: Number(newSlPrice),
    })) {
      const recovery = await closeBinancePositionAtBreachedProfitLock(symbol, emergencyContext);
      if (recovery.closed) return;
      slTrailLastRun.set(symbol, Date.now() - SL_TRAIL_COOLDOWN_MS + SL_TRAIL_IMMEDIATE_TRIGGER_RETRY_MS);
      console.warn(
        `[SlTrail] ${symbol} target +${targetLockRoe}% already crossed; recovery=${recovery.reason}`
        + `${Number(recovery.latestMark) > 0 ? ` latestMark=${recovery.latestMark}` : ''}`,
      );
      return;
    }

    // Current SL already at or better than target → just record it
    if (slOrder) {
      const curSl = Number(slOrder.triggerPrice ?? slOrder.stopPrice ?? 0);
      if ((isLong && curSl >= newSlPrice) || (!isLong && curSl <= newSlPrice)) {
        slTrailLockRoe.set(symbol, { lockRoe: targetLockRoe, lifecycleKey });
        await rememberBinanceProfitLock(symbol, curSl, targetLockRoe, lifecycleKey);
        return;
      }
    }

    const positionSide = pos.positionSide ?? 'BOTH';
    const isHedge = positionSide !== 'BOTH';

    const slParams = buildClosePositionProtectionParams({
      symbol,
      closeSide: isLong ? 'SELL' : 'BUY',
      type: 'STOP_MARKET',
      triggerPrice: String(newSlPrice),
      positionSide: isHedge ? positionSide : 'BOTH',
      workingType: 'MARK_PRICE',
      recvWindow,
      clientAlgoId: `lp_slt_${Date.now()}`.slice(0, 36),
    });

    // Binance GTE_GTC closePosition rejects a second STOP in the same direction.
    // Cancel the exact old SL first, then place the tighter SL. If placement
    // fails, restore the old SL so the position is not left unprotected.
    const oldSlPrice = Number(slOrder?.triggerPrice ?? slOrder?.stopPrice ?? 0);
    const oldSlWorkingType = String(slOrder?.workingType ?? 'MARK_PRICE').toUpperCase();
    let oldSlCancelled = false;
    if (algoSl) {
      await client.cancelAlgoOrder({ algoId: algoSl.algoId, apiKey, apiSecret, recvWindow });
      oldSlCancelled = true;
    } else if (regularSl) {
      await client.cancelOrder({ symbol, orderId: regularSl.orderId, apiKey, apiSecret, recvWindow });
      oldSlCancelled = true;
    }

    try {
      await client.placeAlgoOrder({ params: slParams, apiKey, apiSecret });
    } catch (placementError) {
      let targetConfirmed = false;
      try {
        const verification = await client.getOpenAlgoOrders({
          symbol,
          apiKey,
          apiSecret,
          priority: 0,
          dropOnCongestion: false,
          source: 'profitLock:verifyReplacementAfterError',
        });
        const verificationOrders = Array.isArray(verification?.orders)
          ? verification.orders
          : Array.isArray(verification) ? verification : [];
        targetConfirmed = hasBinanceProfitLockStopAtTarget({
          orders: verificationOrders,
          symbol,
          closeSide: isLong ? 'SELL' : 'BUY',
          stopPrice: Number(newSlPrice),
        });
      } catch (verificationError) {
        console.warn(`[SlTrail] ${symbol} replacement verification failed: ${verificationError.message}`);
      }

      if (!targetConfirmed && oldSlCancelled && oldSlPrice > 0) {
        const restoreParams = buildClosePositionProtectionParams({
          symbol,
          closeSide: isLong ? 'SELL' : 'BUY',
          type: 'STOP_MARKET',
          triggerPrice: String(oldSlPrice),
          positionSide: isHedge ? positionSide : 'BOTH',
          workingType: oldSlWorkingType === 'CONTRACT_PRICE' ? 'CONTRACT_PRICE' : 'MARK_PRICE',
          recvWindow,
          clientAlgoId: `lp_slr_${Date.now()}`.slice(0, 36),
        });
        try {
          await client.placeAlgoOrder({ params: restoreParams, apiKey, apiSecret });
          console.warn(`[SlTrail] ${symbol} replacement failed; restored old SL @ ${oldSlPrice}`);
        } catch (restoreError) {
          console.error(`[SlTrailCritical] ${symbol} failed to restore old SL @ ${oldSlPrice}: ${restoreError.message}`);
        }
      }
      if (!targetConfirmed) throw placementError;
      console.warn(`[SlTrail] ${symbol} replacement response failed but target SL was confirmed on Binance`);
    }

    slTrailLockRoe.set(symbol, { lockRoe: targetLockRoe, lifecycleKey });
    await rememberBinanceProfitLock(symbol, newSlPrice, targetLockRoe, lifecycleKey);
    const profitLockPolicy = isOrdersExcluded
      ? 'ORDERS_EXCLUDE_ROE10_CAP_LOCK1'
      : isManualPosition
        ? 'MANUAL_ROE10_LOCK1'
        : isLiquidFlowV2Position
          ? 'LIQUID_V2_ROE10_LOCK1'
          : 'NON_V2';
    console.log(`[SlTrail] ✅ ${symbol} ROE=${roe.toFixed(1)}% → ${slOrder ? 'SL dời lên' : 'SL mới'} +${targetLockRoe}% ROE @ ${newSlPrice} policy=${profitLockPolicy} version=${BINANCE_PROFIT_LOCK_VERSION}`);
  } catch (err) {
    if (emergencyContext && isBinanceProfitLockImmediateTriggerError(err)) {
      try {
        const recovery = await closeBinancePositionAtBreachedProfitLock(symbol, emergencyContext);
        if (recovery.closed) return;
        slTrailLastRun.set(symbol, Date.now() - SL_TRAIL_COOLDOWN_MS + SL_TRAIL_IMMEDIATE_TRIGGER_RETRY_MS);
        console.warn(
          `[SlTrail] ${symbol} immediate-trigger recovery=${recovery.reason}`
          + `${Number(recovery.latestMark) > 0 ? ` latestMark=${recovery.latestMark}` : ''}; retry in ${SL_TRAIL_IMMEDIATE_TRIGGER_RETRY_MS / 1000}s`,
        );
      } catch (recoveryError) {
        console.error(`[SlTrailEmergency] ❌ ${symbol}:`, recoveryError.message);
      }
    }
    console.error(`[SlTrail] ❌ ${symbol}:`, err.message);
  } finally {
    slTrailRunning.delete(symbol);
  }
}

async function triggerSlGuardForSymbol(symbol) {
  if (slGuardRunning.has(symbol)) {
    console.log(`[SlGuard] ${symbol} skipped: protection check already running`);
    return;
  }
  slGuardRunning.add(symbol);
  console.log(`[SlGuard] triggerSlGuardForSymbol called: ${symbol}`);
  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const positions = await client.getPositions({ apiKey, apiSecret });
    const pos = positions.find((p) => p.symbol === symbol && Number(p.positionAmt) !== 0);
    if (!pos) { console.log(`[SlGuard] ${symbol} no active position found`); return; }
    const allOrders = await client.getOpenOrders({ apiKey, apiSecret });
    await handleMissingSl([pos], allOrders, apiKey, apiSecret);
  } catch (err) {
    if (err.message?.includes('Missing Binance API')) return;
    console.error(`[SlGuard] triggerSlGuard ${symbol}:`, err.message);
  } finally {
    slGuardRunning.delete(symbol);
  }
}

async function handleMissingSl(rawPositions, allOrders, apiKey, apiSecret) {
  if (process.env.AUTO_SL_ENABLED === 'false') return;
  const slRoe = Number(process.env.AUTO_SL_ROE ?? 25);
  if (slRoe <= 0) return;

  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

  let algoOrders = null;
  const getAlgoOrders = async () => {
    if (algoOrders !== null) return algoOrders;
    const result = await client.getOpenAlgoOrders({ apiKey, apiSecret });
    algoOrders = Array.isArray(result?.orders) ? result.orders : Array.isArray(result) ? result : [];
    return algoOrders;
  };

  const symbols = await getSymbols();

  for (const p of rawPositions) {
    const symbol = p.symbol;

    // Only process positions registered in sl-tracking.json (opened after json was created)
    const tracked = slTracking.positions[symbol];
    if (!tracked) continue;
    if (tracked.slPlaced) continue;

    const entry = Number(p.entryPrice);
    const amt = Number(p.positionAmt);
    const leverage = Number(p.leverage) || 10;
    if (!entry || !amt) continue;

    const isLong = amt > 0;
    const closeSide = isLong ? 'SELL' : 'BUY';
    const positionSide = p.positionSide ?? 'BOTH';

    // Keep any existing close-side SL. A later fresh check immediately before
    // placement closes the race between duplicated/partial fill callbacks.
    const algo = await getAlgoOrders();
    if (hasOpenProtectionOrder(allOrders, algo, {
      symbol,
      closeSide,
      positionSide,
      kind: 'SL',
    })) {
      slTracking.positions[symbol].slPlaced = true;
      saveSlTracking();
      continue;
    }

    const rawSlPrice = isLong
      ? entry * (1 - (slRoe / 100) / leverage)
      : entry * (1 + (slRoe / 100) / leverage);

    const symbolInfo = symbols.find((s) => s.symbol === symbol);
    if (!symbolInfo) continue;
    const slPrice = priceFromTick(symbolInfo, rawSlPrice);

    const isHedge = positionSide !== 'BOTH';

    const slParams = buildClosePositionProtectionParams({
      symbol,
      closeSide: isLong ? 'SELL' : 'BUY',
      type: 'STOP_MARKET',
      triggerPrice: String(slPrice),
      positionSide: isHedge ? positionSide : 'BOTH',
      workingType: 'MARK_PRICE',
      recvWindow,
      clientAlgoId: `lp_slg_${Date.now()}`.slice(0, 36),
    });

    try {
      const [freshRegular, freshAlgoResult] = await Promise.all([
        client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
        client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }),
      ]);
      const freshAlgo = Array.isArray(freshAlgoResult?.orders)
        ? freshAlgoResult.orders
        : Array.isArray(freshAlgoResult) ? freshAlgoResult : [];
      if (hasOpenProtectionOrder(freshRegular, freshAlgo, {
        symbol,
        closeSide,
        positionSide,
        kind: 'SL',
      })) {
        slTracking.positions[symbol].slPlaced = true;
        saveSlTracking();
        console.log(`[SlGuard] ${symbol} skipped: existing SL found on fresh check`);
        continue;
      }
      await client.placeAlgoOrder({ params: slParams, apiKey, apiSecret });
      slTracking.positions[symbol].slPlaced = true;
      slTracking.positions[symbol].slPrice = slPrice;
      slTracking.positions[symbol].slPlacedAt = new Date().toISOString();
      saveSlTracking();
      console.log(`[SlGuard] ✅ ${symbol} ${isLong ? 'LONG' : 'SHORT'} entry=${entry} lev=${leverage}x → SL @ ${slPrice} (-${slRoe}% ROE)`);
    } catch (err) {
      console.error(`[SlGuard] ❌ ${symbol}: ${err.message}`);
    }
  }
}

const liqAutoOrderFired = new Map(); // `${symbol}:${price}` → timestamp
const pendingLiqTp = new Map(); // symbol → { tpPrice, tpRoePct, direction, at }
const recentLiqAutoBlock = new Map(); // symbol -> { direction, bias, sweepProb, at }

function rememberLiqAutoBlock(payload) {
  if (!payload?.symbol) return;
  const sweepProb = Number(payload.sweepProb ?? 0);
  const minProb = Number(process.env.LIQ_AUTO_BLOCK_MIN_PROB ?? 80);
  if (sweepProb < minProb) return;
  recentLiqAutoBlock.set(String(payload.symbol).toUpperCase(), {
    direction: String(payload.direction ?? '').toLowerCase(),
    bias: Number(payload.bias ?? 0),
    sweepProb,
    at: Date.now(),
  });
}

function liqAutoBlockReason(symbol, side) {
  const rec = recentLiqAutoBlock.get(String(symbol ?? '').toUpperCase());
  if (!rec) return '';
  const ttlMs = Number(process.env.LIQ_AUTO_BLOCK_TTL_MS ?? 2 * 60 * 60 * 1000);
  if (Date.now() - rec.at > ttlMs) {
    recentLiqAutoBlock.delete(String(symbol ?? '').toUpperCase());
    return '';
  }
  const minProb = Number(process.env.LIQ_AUTO_BLOCK_MIN_PROB ?? 80);
  if (rec.sweepProb < minProb) return '';
  const orderSide = String(side ?? '').toUpperCase();
  const longBlocked = orderSide === 'LONG' || orderSide === 'BUY';
  const shortBlocked = orderSide === 'SHORT' || orderSide === 'SELL';
  if (longBlocked && (rec.direction === 'long' || rec.bias <= -Number(process.env.LIQ_AUTO_BLOCK_MIN_ABS_BIAS ?? 0.5))) {
    return `liq-scan bearish sweepProb=${rec.sweepProb}% bias=${Number(rec.bias).toFixed(3)}`;
  }
  if (shortBlocked && (rec.direction === 'short' || rec.bias >= Number(process.env.LIQ_AUTO_BLOCK_MIN_ABS_BIAS ?? 0.5))) {
    return `liq-scan bullish sweepProb=${rec.sweepProb}% bias=${Number(rec.bias).toFixed(3)}`;
  }
  return '';
}

function getLiqHighProbThreshold() {
  const thresholds = [];
  if (process.env.PAPER_LIQ_ENABLED !== 'false') thresholds.push(Number(process.env.PAPER_LIQ_MIN_PROB ?? 80));
  if (!liveCardOnlyAutoBinanceEnabled() && process.env.AUTO_LIQ_ORDER_ENABLED === 'true') {
    thresholds.push(Number(process.env.AUTO_LIQ_ORDER_MIN_PROB ?? 90));
  }
  return thresholds.length ? Math.min(...thresholds) : 80;
}

function getLiqHighProbHandler() {
  const paperEnabled = process.env.PAPER_LIQ_ENABLED !== 'false';
  const realEnabled = !liveCardOnlyAutoBinanceEnabled() && process.env.AUTO_LIQ_ORDER_ENABLED === 'true';
  if (!paperEnabled && !realEnabled) return null;

  return async (payload) => {
    rememberLiqAutoBlock(payload);

    if (paperEnabled) {
      await createLiqPaperTrade(payload).catch((err) => {
        console.error(`[PaperLiq] ❌ ${payload.symbol}:`, err.message);
      });
    }

    const autoMarketOnConfirmation = process.env.AUTO_LIQ_AUTO_MARKET_ON_CONFIRMATION === 'true';
    const realMinProb = Number(process.env.AUTO_LIQ_ORDER_MIN_PROB ?? 90);
    if (autoMarketOnConfirmation && realEnabled && payload.sweepProb >= realMinProb) {
      await handleLiqAutoOrder(payload);
    }
  };
}

const pumpAutoOrderFired = new Map(); // symbol → timestamp

// Signal flood guard — khi quá nhiều LONG bắn cùng lúc (dấu hiệu BTC spike)
const recentLongOrderTimes = [];          // rolling timestamps của LONG orders vừa đặt
let signalFloodBlockedUntil = 0;          // timestamp hết hạn block
const SIGNAL_FLOOD_WINDOW_MS = 5 * 60 * 1000;  // window 5 phút
const SIGNAL_FLOOD_THRESHOLD = 8;               // ≥ 8 lệnh/5 phút → flood
const SIGNAL_FLOOD_PAUSE_MS  = 30 * 60 * 1000; // dừng 30 phút sau khi detect

function isPumpShortEdgeAutoRecord(order) {
  const side = String(order?.side ?? order?.action ?? '').toUpperCase();
  const score = Number(order?.score);
  return (side === 'SELL' || side === 'SHORT') && score >= 40 && score <= 79;
}

function countPumpShortEdgeAutoExposure() {
  const ids = new Set();
  for (const order of [...pumpPendingOrders, ...pumpWatchingOrders]) {
    if (!isPumpShortEdgeAutoRecord(order)) continue;
    ids.add(order.orderId ?? `${order.symbol}:${order.side}:${order.placedAt ?? order.filledAt ?? ''}`);
  }
  return ids.size;
}

async function handlePumpAutoOrder(signal, openOrders = null) {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (!runtimeSettings.pumpAutoOrderEnabled) return;
  if (isVnBlockHour()) { console.log(`[PumpAuto] ⏰ Block 17-19h VN — ${signal.symbol}`); return; }
  const { symbol, action, score, marketOk, entry, sl, factors, type: signalType } = signal;
  if (String(signalType ?? '').startsWith('ma60_volume_cluster')) return;
  const liqBlock = liqAutoBlockReason(symbol, action);
  if (liqBlock) {
    console.log(`[PumpAuto] skip ${symbol} ${action} - ${liqBlock}`);
    return;
  }
  const onlyPumpShortEdge = process.env.PUMP_AUTO_ONLY_PUMP_SHORT_EDGE === 'true';
  const pumpAutoMinScore = Number(process.env.PUMP_AUTO_MIN_SCORE ?? 80);
  const pumpAutoMaxScore = Number(process.env.PUMP_AUTO_MAX_SCORE ?? 999);
  if (onlyPumpShortEdge && action !== 'SHORT') return;
  if (score < pumpAutoMinScore) return;
  if (score > pumpAutoMaxScore) return;
  if (!onlyPumpShortEdge && marketOk === false) return;
  if (!onlyPumpShortEdge && factors?.emaRibbon === 0) return; // EMA ribbon không bullish → không đặt lệnh
  // Chase guard — bỏ qua nếu giá đã chạy > 30% vào TP range
  const chasePct = factors?.chasePct ?? 0;
  if (chasePct > 0.30) {
    console.log(`[PumpAuto] ⏭ ${symbol} chase=${(chasePct * 100).toFixed(0)}% > 30% — skip`);
    return;
  }
  // Adjusted score guard (score đã trừ chase penalty từ detector)
  if (!onlyPumpShortEdge && score < 70) {
    console.log(`[PumpAuto] ⏭ ${symbol} adj.score=${score} < 70 — skip`);
    return;
  }
  if (!entry || !sl) return;

  // ── Danger zone — block TẤT CẢ auto order khi RSI cực đoan ──────────────────
  // RSI 1h < 20 hoặc RSI 4h < 25: oversold cực đoan → bounce bất ngờ, short nguy hiểm
  // RSI 1h > 80 hoặc RSI 4h > 75: overbought cực đoan → dump bất ngờ, long nguy hiểm
  {
    const health = btcHealthCache.data;
    const r1h = health?.rsi1h;
    const r4h = health?.rsi4h;
    const isDangerLow  = (r1h != null && r1h < 25) || (r4h != null && r4h < 32); // oversold — short đáy nguy hiểm
    const isDangerHigh = (r1h != null && r1h > 80) || (r4h != null && r4h > 72); // overbought — long đỉnh nguy hiểm
    if (isDangerLow || isDangerHigh) {
      const zone = isDangerLow ? `oversold cực đoan` : `overbought cực đoan`;
      console.log(`[PumpAuto] 🚫 ${symbol} block ALL — danger zone: ${zone} (RSI1h=${r1h} RSI4h=${r4h})`);
      const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (webhookUrl) {
        const dirEmoji = action === 'LONG' ? '🟢 LONG' : '🔴 SHORT';
        const msg = `🚫 **Pump Auto BLOCKED** | **${symbol}** ${dirEmoji}\n` +
          `Score: **${score}** | Entry: \`${entry}\`\n` +
          `BTC Danger Zone: **${zone}**\n` +
          `RSI 1h: **${r1h ?? '–'}** · RSI 4h: **${r4h ?? '–'}** · ${isDangerLow ? 'Bounce risk cao' : 'Dump risk cao'}`;
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: msg }),
        }).catch(() => {});
      }
      return;
    }
  }

  // EMA_PB vol filter: vol < 1.8x → skip (không đủ buying pressure để confirm pullback)
  if (signalType === 'ema_pullback' && action === 'LONG') {
    const volRatio = factors?.volRatio ?? 0;
    if (volRatio < 1.8) {
      console.log(`[PumpAuto] ⏭ ${symbol} skip EMA_PB — vol=${volRatio}x < 1.8x`);
      return;
    }
  }

  // Case 1: Signal Flood — ≥8 LONG đặt trong 5 phút → BTC spike pattern → dừng 30 phút
  if (action === 'LONG') {
    const now = Date.now();
    // Prune entries cũ ngoài window
    while (recentLongOrderTimes.length > 0 && recentLongOrderTimes[0] < now - SIGNAL_FLOOD_WINDOW_MS) {
      recentLongOrderTimes.shift();
    }
    if (now < signalFloodBlockedUntil) {
      const remainMin = Math.ceil((signalFloodBlockedUntil - now) / 60_000);
      console.log(`[PumpAuto] 🌊 ${symbol} block — signal flood pause (còn ${remainMin} phút)`);
      return;
    }
    if (recentLongOrderTimes.length >= SIGNAL_FLOOD_THRESHOLD) {
      signalFloodBlockedUntil = now + SIGNAL_FLOOD_PAUSE_MS;
      console.log(`[PumpAuto] 🌊 FLOOD DETECTED — ${recentLongOrderTimes.length} LONG/${SIGNAL_FLOOD_WINDOW_MS / 60_000} phút → dừng 30 phút`);
      const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (webhookUrl) {
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: `🌊 **Signal Flood DETECTED** — **${recentLongOrderTimes.length}** LONG trong 5 phút\nDừng tất cả LONG auto order **30 phút**. Nghi ngờ BTC spike candle.` }),
        }).catch(() => {});
      }
      return;
    }
  }

  // Case 2: BTC 1h candle đỏ > 0.5% → block EMA_PB LONG (đang trong correction phase)
  if (action === 'LONG' && signalType === 'ema_pullback') {
    const health = btcHealthCache.data;
    const c1h = health?.btcCandle1hPct ?? 0;
    if (c1h < -0.5) {
      console.log(`[PumpAuto] 📉 ${symbol} block EMA_PB LONG — BTC 1h candle ${c1h.toFixed(2)}% (correction phase)`);
      const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (webhookUrl) {
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: `📉 **Pump Auto BLOCKED** | **${symbol}** 🟢 LONG [EMA_PB]\nScore: **${score}** | Entry: \`${entry}\`\nBTC 1h candle: **${c1h.toFixed(2)}%** — correction phase, EMA_PB blocked.` }),
        }).catch(() => {});
      }
      return;
    }
  }

  // Block EMA_PB LONG sau BTC spike candle (vol > 2.5x avg + move > 1% trên 1h)
  // Lý do: sau spike BTC thường correction ngay → alt EMA_PB vào đúng lúc BTC kéo xuống
  if (action === 'LONG' && signalType === 'ema_pullback' && btcHealthCache.data?.btcSpikeAlert) {
    const health = btcHealthCache.data;
    console.log(`[PumpAuto] ⚡ ${symbol} block EMA_PB LONG — BTC spike candle detected (RSI1h=${health.rsi1h} pct6h=${health.pct6h}%)`);
    const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
    if (webhookUrl) {
      fetch(webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ content: `⚡ **Pump Auto BLOCKED** | **${symbol}** 🟢 LONG [EMA_PB]\nScore: **${score}** | Entry: \`${entry}\`\nBTC spike candle detected — correction risk cao. Block EMA_PB 2 nến.` }),
      }).catch(() => {});
    }
    return;
  }

  // Block khi BTC health = bearish hoặc caution (chỉ block LONG — SHORT vẫn cho qua)
  if (action === 'LONG' || action == null) {
    const health = btcHealthCache.data;
    if (health?.bias === 'bearish' || health?.bias === 'caution') {
      console.log(`[PumpAuto] ⛔ ${symbol} block — BTC bias=${health.bias} (RSI1h=${health.rsi1h} RSI4h=${health.rsi4h} EMA1h=${health.emaTrend1h})`);
      const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (webhookUrl) {
        const reasons = [
          health.fundingRate > 0.05 ? `Funding **${health.fundingRate}%** (cao)` : null,
          health.bearishDiv ? `RSI Div ⚠` : null,
          health.longPct > 62 ? `L/S **${health.longPct}%** long` : null,
          health.rsi4h > 70 ? `RSI 4h **${health.rsi4h}** (overbought)` : null,
          health.rsi4h != null && health.rsi4h < 35 ? `RSI 4h **${health.rsi4h}** (dump)` : null,
          health.rsi1h != null && health.rsi1h < 40 ? `RSI 1h **${health.rsi1h}** (bearish)` : null,
          health.emaTrend1h === 'below' ? `Price dưới EMA20 1h` : null,
          health.obvTrend === 'falling' ? `OBV 4h ↓` : null,
        ].filter(Boolean);
        const biasEmoji = health.bias === 'bearish' ? '⛔' : '⚡';
        const msg = `${biasEmoji} **Pump Auto BLOCKED** | **${symbol}** 🟢 LONG\n` +
          `Score: **${score}** | Entry: \`${entry}\`\n` +
          `BTC Health: **${health.bias}** (${health.bearPoints}/8)\n` +
          `Lý do: ${reasons.join(' · ') || 'tổng hợp nhiều yếu tố'}`;
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: msg }),
        }).catch(() => {});
      }
      return;
    }
  }

  // Block SHORT khi BTC đang bullish — đối xứng với block LONG khi bearish
  if (action === 'SHORT' && !onlyPumpShortEdge) {
    const health = btcHealthCache.data;
    if (health?.bullBias === 'bullish') { // caution = cảnh báo thôi, không hard-block SHORT
      console.log(`[PumpAuto] ⛔ ${symbol} block SHORT — BTC bullBias=${health.bullBias} (RSI1h=${health.rsi1h} EMA1h=${health.emaTrend1h} pct6h=${health.pct6h}%)`);
      const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (webhookUrl) {
        const reasons = [
          health.rsi1h != null && health.rsi1h > 60 ? `RSI 1h **${health.rsi1h}** (bullish)` : null,
          health.emaTrend1h === 'above' ? `Price trên EMA20 1h` : null,
          health.pct6h != null && health.pct6h > 1.5 ? `BTC +${health.pct6h}% trong 6h` : null,
          health.obvTrend === 'rising' ? `OBV 4h ↑` : null,
          health.rsi4h != null && health.rsi4h > 55 ? `RSI 4h **${health.rsi4h}** (bullish)` : null,
          health.longPct != null && health.longPct < 42 ? `L/S **${health.longPct}%** long (short squeeze risk)` : null,
        ].filter(Boolean);
        const biasEmoji = health.bullBias === 'bullish' ? '⛔' : '⚡';
        const msg = `${biasEmoji} **Pump Auto BLOCKED** | **${symbol}** 🔴 SHORT\n` +
          `Score: **${score}** | Entry: \`${entry}\`\n` +
          `BTC Bull Trend: **${health.bullBias}** (${health.bullPoints}/6)\n` +
          `Lý do: ${reasons.join(' · ') || 'BTC đang trong uptrend'}`;
        fetch(webhookUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: msg }),
        }).catch(() => {});
      }
      return;
    }
  }

  const last = pumpAutoOrderFired.get(symbol) ?? 0;
  if (Date.now() - last < 2 * 3600 * 1000) {
    console.log(`[PumpAuto] ⏭ ${symbol} skip — 2h dedup`);
    return;
  }

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const margin = Number(process.env.PUMP_AUTO_ORDER_MARGIN ?? 1);
    const defaultLeverage = Number(process.env.PUMP_AUTO_ORDER_LEVERAGE ?? 10);
    const leverage = calcAutoLeverage(signal.entry, signal.sl, defaultLeverage);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
    const maxLimitOrders = runtimeSettings.pumpMaxLimitOrders;

    if (!openOrders) openOrders = await client.getOpenOrders({ apiKey, apiSecret });
    const openLimitEntries = openOrders.filter((o) => o.type === 'LIMIT' && !o.reduceOnly);
    if (openLimitEntries.some((o) => o.symbol === symbol)) {
      console.log(`[PumpAuto] ⏭ ${symbol} skip — already has LIMIT order`);
      return;
    }
    if (openLimitEntries.length >= maxLimitOrders) {
      console.log(`[PumpAuto] ⚠ ${symbol} skip — max ${maxLimitOrders} limit orders reached`);
      return;
    }

    if (onlyPumpShortEdge) {
      const maxShortEdge = Number(process.env.PUMP_AUTO_SHORT_EDGE_MAX_POSITIONS ?? 10);
      const currentShortEdge = countPumpShortEdgeAutoExposure();
      if (maxShortEdge > 0 && currentShortEdge >= maxShortEdge) {
        console.log(`[PumpAuto] ⚠ ${symbol} skip — PUMP_SHORT EDGE max ${maxShortEdge} reached (current=${currentShortEdge})`);
        return;
      }
    }

    // Max positions check: positions đang mở + LIMIT pending không vượt ngưỡng
    const maxPositions = runtimeSettings.pumpMaxPositions;
    if (maxPositions > 0) {
      const positions = await client.getPositions({ apiKey, apiSecret });
      const openCount = positions.filter((p) => Number(p.positionAmt) !== 0).length;
      const pendingCount = openLimitEntries.length;
      if (openCount + pendingCount >= maxPositions) {
        console.log(`[PumpAuto] ⚠ ${symbol} skip — max positions ${maxPositions} reached (open=${openCount} pending=${pendingCount})`);
        return;
      }
    }

    const symbols = await getSymbols();
    const info = symbols.find((s) => s.symbol === symbol);
    const tickSize = Number(info?.filters?.find((f) => f.filterType === 'PRICE_FILTER')?.tickSize ?? 0);
    const stepSize = Number(info?.filters?.find((f) => f.filterType === 'LOT_SIZE')?.stepSize ?? 0);

    await client.setLeverage({ symbol, leverage, apiKey, apiSecret, recvWindow });

    const premiumIndex = await client.getPremiumIndex(symbol);
    const markPrice = Number(premiumIndex.markPrice);
    const minNotionalFilter = Number(info?.filters?.find((f) => f.filterType === 'MIN_NOTIONAL')?.notional ?? 0);
    const notional = Math.max(margin * leverage, minNotionalFilter > 0 ? minNotionalFilter : 0);
    const qtyRaw = notional / entry;
    const qty = stepSize > 0 ? Math.floor(qtyRaw / stepSize) * stepSize : qtyRaw;
    const qtyStr = stepSize > 0 ? qty.toFixed(Math.max(0, -Math.floor(Math.log10(stepSize)))) : qty.toFixed(6);
    const side = action === 'LONG' ? 'BUY' : 'SELL';
    const entryStr = tickSize > 0 ? entry.toFixed(Math.max(0, -Math.floor(Math.log10(tickSize)))) : entry.toFixed(8);

    const order = await client.placeFuturesOrder({
      params: { symbol, side, type: 'LIMIT', price: entryStr, quantity: qtyStr, timeInForce: 'GTC', recvWindow, newClientOrderId: `lp_auto_${Date.now()}`.slice(0, 36) },
      apiKey, apiSecret,
    });

    pumpAutoOrderFired.set(symbol, Date.now());
    if (side === 'BUY') recentLongOrderTimes.push(Date.now()); // track cho signal flood guard
    invalidateOpenOrdersCache();
    console.log(`[PumpAuto] ✅ ${symbol} ${side} LIMIT @${entryStr} qty=${qtyStr} margin=$${margin} score=${score}`);

    // Đặt SL ngay sau entry order — STOP_MARKET reduceOnly
    const slRoePct = Number(process.env.PUMP_AUTO_ORDER_SL_ROE ?? 30);
    const slPriceRaw = side === 'BUY'
      ? Number(entryStr) * (1 - slRoePct / 100 / leverage)
      : Number(entryStr) * (1 + slRoePct / 100 / leverage);
    let slPlaced = false;
    let slPriceStr = null;
    if (isFinite(slPriceRaw) && slPriceRaw > 0 && info) {
      slPriceStr = tickSize > 0
        ? slPriceRaw.toFixed(Math.max(0, -Math.floor(Math.log10(tickSize))))
        : slPriceRaw.toFixed(8);
      const slParams = {
        symbol,
        side: side === 'BUY' ? 'SELL' : 'BUY',
        type: 'STOP_MARKET',
        stopPrice: slPriceStr,
        quantity: qtyStr,
        workingType: 'MARK_PRICE',
        reduceOnly: 'true',
        recvWindow,
        newClientOrderId: `lp_psl_${order.orderId}`.slice(0, 36),
      };
      try {
        await client.placeFuturesOrder({ params: slParams, apiKey, apiSecret })
          .catch((e) => {
            if (e.message?.includes('not supported') || e.message?.includes('Algo Order')) {
              const algoParams = { ...slParams, algoType: 'CONDITIONAL', triggerPrice: slPriceStr };
              delete algoParams.stopPrice;
              return client.placeAlgoOrder({ params: algoParams, apiKey, apiSecret });
            }
            throw e;
          });
        slPlaced = true;
        console.log(`[PumpAuto] 🛡 ${symbol} SL @${slPriceStr} (${slRoePct}% ROE)`);
      } catch (e) {
        console.warn(`[PumpAuto] ⚠ SL failed ${symbol}:`, e.message);
      }
    }

    // Lưu tp từ signal để pollPumpOrders đặt TP_MARKET khi order filled
    const tpFromSignal = signal.tp ?? null;
    addPumpPendingOrder({ orderId: order.orderId, symbol, side, entry: Number(entryStr), qty: Number(qtyStr), margin, leverage, score, type: signal.type ?? null, slPlaced, slPrice: slPriceStr ? Number(slPriceStr) : null, tp: tpFromSignal, placedAt: Date.now() }).catch(() => {});

    const webhookUrl = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
    if (webhookUrl) {
      const slStatus = slPlaced ? `🛡 SL: \`${slPriceStr}\` (−${slRoePct}% ROE)` : `⚠ **SL không đặt được**`;
      const entryQuality = chasePct > 0.45 || score < 55
        ? '🚫 Đã trễ — chờ pullback'
        : chasePct > 0.30 || score < 70
          ? '⚠ Cân nhắc — chase cao'
          : '✅ Có thể vào';
      const chaseStr = chasePct > 0.01 ? ` · Chase ${(chasePct * 100).toFixed(0)}%TP` : '';
      const tpStr = tpFromSignal ? ` · TP: \`${tpFromSignal}\`` : '';
      const msg = `🎯 **Pump Auto LIMIT** | **${symbol}** ${action === 'LONG' ? '🟢 LONG' : '🔴 SHORT'}\n` +
        `Score: **${score}** | ${entryQuality}${chaseStr}\n` +
        `Entry: \`${entryStr}\`${tpStr} | ${slStatus}\n` +
        `Margin: $${margin} × ${leverage}x | RSI: ${factors?.rsi14val ?? '-'} | Vol: ${factors?.volRatio ?? '-'}×\n` +
        `Type: ${signal.type ?? '-'} | OrderId: ${order.orderId}`;
      fetch(webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ content: msg }),
      }).catch(() => {});
    }
  } catch (err) {
    console.error(`[PumpAuto] ❌ ${symbol} error:`, err.message);
  }
}

async function handleLiqAutoOrder({ symbol, markPrice, direction, sweepTargetPrice, sweepProb, confirmation = null }) {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  // Dedup theo symbol (không theo price) — tránh đặt nhiều lệnh khi price thay đổi nhẹ giữa các scan
  const last = liqAutoOrderFired.get(symbol) ?? 0;
  if (Date.now() - last < 2 * 3600 * 1000) {
    console.log(`[AutoLiq] ⏭ ${symbol} skip — 2h dedup (đã đặt lệnh trong 2h qua)`);
    return;
  }

  // Filter sweep distance quá nhỏ — signal gần target dễ bị SL ngay
  const minSweepDistPct = Number(process.env.LIQ_MIN_SWEEP_DIST_PCT ?? 2.0);
  if (minSweepDistPct > 0 && sweepTargetPrice > 0 && markPrice > 0) {
    const distPct = Math.abs((sweepTargetPrice - markPrice) / markPrice * 100);
    if (distPct < minSweepDistPct) {
      console.log(`[AutoLiq] ⏭ ${symbol} skip — sweepDist ${distPct.toFixed(2)}% < min ${minSweepDistPct}%`);
      return;
    }
  }

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const requireConfirmation = process.env.AUTO_LIQ_REQUIRE_REVERSAL_CONFIRMATION !== 'false';
    const allowProbe = process.env.AUTO_LIQ_PROBE_BEFORE_CONFIRMATION !== 'false';
    const isConfirmed = confirmation?.confirmed === true;
    if (requireConfirmation && !isConfirmed && !allowProbe) {
      console.log(`[AutoLiq] ⏳ ${symbol} skip — ${confirmation?.reason ?? 'waiting for reversal confirmation'}`);
      return;
    }

    const baseMargin = Number(process.env.AUTO_LIQ_ORDER_MARGIN ?? 5);
    const probeMargin = Number(process.env.AUTO_LIQ_PROBE_MARGIN ?? 1);
    const isProbe = requireConfirmation && !isConfirmed;
    const margin = isProbe ? probeMargin : baseMargin;
    const leverage = Number(process.env.AUTO_LIQ_ORDER_LEVERAGE ?? 10);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
    const maxLimitOrders = Number(process.env.AUTO_LIQ_MAX_LIMIT_ORDERS ?? 30);

    // Count existing open LIMIT entry orders (non-reduceOnly) and check per-symbol dedup
    const openOrders = await client.getOpenOrders({ apiKey, apiSecret });
    const openLimitEntries = openOrders.filter((o) => o.type === 'LIMIT' && !o.reduceOnly);
    const symbolAlreadyHasLimit = openLimitEntries.some((o) => o.symbol === symbol);
    if (symbolAlreadyHasLimit) {
      console.log(`[AutoLiq] ⏭ ${symbol} skip — đã có lệnh LIMIT đang chờ cho symbol này`);
      return;
    }
    const openLimitCount = openLimitEntries.length;
    if (openLimitCount >= maxLimitOrders) {
      console.log(`[AutoLiq] ⏭ ${symbol} skip — đã có ${openLimitCount} lệnh LIMIT chờ (max ${maxLimitOrders})`);
      const liqWh = process.env.LIQ_SCAN_WEBHOOK_URL || process.env.DISCORD_WEBHOOK_URL;
      if (liqWh) {
        fetch(liqWh, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ content: `⚠️ **[AutoLiq]** Bỏ qua **${symbol}** — đã có **${openLimitCount}** lệnh LIMIT đang chờ (max ${maxLimitOrders}). Huỷ bớt lệnh cũ để tiếp tục đặt.` }),
        }).catch(() => {});
      }
      return;
    }

    const [symbols] = await Promise.all([getSymbols()]);
    const symbolInfo = symbols.find((s) => s.symbol === symbol);
    if (!symbolInfo) { console.warn(`[AutoLiq] ${symbol} not in symbols`); return; }

    const confirmedOrderType = String(process.env.AUTO_LIQ_CONFIRMED_ORDER_TYPE ?? 'MARKET').toUpperCase();
    const useMarket = isConfirmed && confirmedOrderType === 'MARKET';
    const price = useMarket
      ? priceFromTick(symbolInfo, markPrice || sweepTargetPrice)
      : priceFromTick(symbolInfo, sweepTargetPrice);
    const notional = margin * leverage;
    const rawQty = notional / price;
    const lotSize = symbolInfo.filters?.find((f) => f.filterType === 'LOT_SIZE');
    const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
    const steppedQty = Math.floor(rawQty / stepSize) * stepSize;
    const quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');

    if (Number(quantity) <= 0) { console.warn(`[AutoLiq] ${symbol} qty=0, skip`); return; }

    await client.setLeverage({ symbol, leverage, apiKey, apiSecret }).catch(() => {});

    const isHedge = await getHedgeMode(null);
    const positionSide = isHedge ? (direction === 'short' ? 'SHORT' : 'LONG') : undefined;

    const side = direction === 'short' ? 'SELL' : 'BUY';
    const entryParams = {
      symbol,
      side,
      type: useMarket ? 'MARKET' : 'LIMIT',
      quantity,
      recvWindow,
      newClientOrderId: `${isProbe ? 'liq_probe' : useMarket ? 'liq_mkt' : 'liq_conf'}_${Date.now()}`.slice(0, 36),
    };
    if (!useMarket) {
      entryParams.price = String(price);
      entryParams.timeInForce = 'GTC';
    }
    if (isHedge) { entryParams.positionSide = positionSide; } else { entryParams.reduceOnly = 'false'; }
    await client.placeFuturesOrder({ params: entryParams, apiKey, apiSecret });

    // TP động theo sweepProb: 90%→30% ROE, 99%→50% ROE
    const tpRoePct = direction === 'short'
      ? 6
      : 30 + ((sweepProb - 90) / 9) * 20;
    const tpRoe = tpRoePct / 100;
    const rawTpPrice = direction === 'short'
      ? price * (1 - tpRoe / leverage)
      : price * (1 + tpRoe / leverage);
    const tpPrice = priceFromTick(symbolInfo, rawTpPrice);

    // Lưu pending TP — sẽ đặt sau khi position monitor xác nhận position đã mở
    // (không đặt ngay vì entry là LIMIT chưa fill, one-way mode reject reduceOnly trước khi có position)
    pendingLiqTp.set(symbol, { tpPrice, tpRoePct, direction, isHedge, positionSide, leverage, at: Date.now() });

    liqAutoOrderFired.set(symbol, Date.now());
    console.log(`[AutoLiq] ✅ ${isProbe ? '[PROBE]' : '[CONFIRMED]'} ${symbol} ${direction.toUpperCase()} ${entryParams.type}${useMarket ? '' : ` @${price}`} — pending TP @${tpPrice} (${tpRoePct.toFixed(1)}% ROE) margin=${margin} qty=${quantity} sweepProb=${sweepProb}%${confirmation?.reason ? ` reason=${confirmation.reason}` : ''}`);
  } catch (err) {
    console.error(`[AutoLiq] ❌ ${symbol}:`, err.message);
  }
}

const placingLiqTp = new Set();
async function placePendingLiqTp(symbol, pos) {
  const pending = pendingLiqTp.get(symbol);
  if (!pending) return;
  if (placingLiqTp.has(symbol)) return;
  // Bỏ qua nếu pending đã quá 2h (entry chưa fill sau 2h, bỏ)
  if (Date.now() - pending.at > 2 * 3600 * 1000) { pendingLiqTp.delete(symbol); return; }

  placingLiqTp.add(symbol);
  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

    // Kiểm tra đã có TP chưa (tránh đặt trùng)
    const algoResult = await client.getOpenAlgoOrders({ apiKey, apiSecret });
    const allAlgo = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
    const hasTp = allAlgo.some((o) => o.symbol === symbol &&
      String(o.type ?? '').toUpperCase() === 'TAKE_PROFIT_MARKET');
    if (hasTp) { pendingLiqTp.delete(symbol); return; }

    const symbolList = await getSymbols();
    const symbolInfo = symbolList.find((s) => s.symbol === symbol);
    if (!symbolInfo) return;

    const tpSide = pending.direction === 'short' ? 'BUY' : 'SELL';
    const positionSide = pos?.positionSide ?? pending.positionSide ?? 'BOTH';
    const isHedge = positionSide !== 'BOTH';
    const liqTakeProfit = resolveNonLiquidFlowV2TakeProfit({
      side: pending.direction,
      source: 'auto-liq',
      entryPrice: Number(pos?.entry ?? pos?.entryPrice),
      leverage: Number(pos?.leverage ?? pending.leverage) || 1,
      requestedTakeProfitPrice: pending.tpPrice,
    });
    const effectiveLiqTp = priceFromTick(symbolInfo, liqTakeProfit.takeProfitPrice);
    const tpParams = {
      algoType: 'CONDITIONAL',
      symbol,
      side: tpSide,
      type: 'TAKE_PROFIT_MARKET',
      triggerPrice: String(effectiveLiqTp),
      workingType: 'MARK_PRICE',
      closePosition: 'true',
      priceProtect: 'true',
      clientAlgoId: `liqtp_${symbol}_${Date.now()}`.slice(0, 36),
      recvWindow,
    };
    if (isHedge) tpParams.positionSide = positionSide;

    await client.placeAlgoOrder({ params: tpParams, apiKey, apiSecret });
    pendingLiqTp.delete(symbol);
    console.log(`[AutoLiq] ✅ TP placed ${symbol} @${effectiveLiqTp} (${liqTakeProfit.applied ? liqTakeProfit.roePct : pending.tpRoePct}% ROE)`);
  } catch (e) {
    console.warn(`[AutoLiq] TP place failed ${symbol}: ${e.message}`);
  } finally {
    placingLiqTp.delete(symbol);
  }
}

// ── L/S Ratio Reversal Scanner ──────────────────────────────────────────────

const lsRatioCache = {
  '5m':  { data: [], updatedAt: 0, scanning: false },
  '15m': { data: [], updatedAt: 0, scanning: false },
};

function detectLsReversal(data) {
  const values = data.map((d) => Number(d.longAccount));
  const n = values.length;
  if (n < 6) return null;

  // Exclude current bar when finding window extreme
  const prev = values.slice(0, -1);
  const windowMax = Math.max(...prev);
  const windowMin = Math.min(...prev);
  const windowRange = windowMax - windowMin;
  if (windowRange < 0.004) return null; // filter flat coins (<0.4pp variation)

  const current = values[n - 1];

  // Use last occurrence so we pick the most recent peak/bottom
  const maxIdx = prev.lastIndexOf(windowMax);
  const minIdx = prev.lastIndexOf(windowMin);
  const barsFromPeak   = (n - 2) - maxIdx;
  const barsFromBottom = (n - 2) - minIdx;

  // Peak reversal → SHORT signal
  if (barsFromPeak >= 2 && barsFromPeak <= 8) {
    const drop = windowMax - current;
    if (drop / windowRange >= 0.35 && drop >= 0.002) {
      const after = values.slice(maxIdx + 1);
      if (after[after.length - 1] < after[0]) { // net decline since peak
        return {
          direction: 'short',
          extreme: +(windowMax * 100).toFixed(1),
          current: +(current * 100).toFixed(1),
          barsAgo: barsFromPeak,
          strength: +(drop * 100).toFixed(2),
          range: +(windowRange * 100).toFixed(2),
          extremeTs: data[maxIdx].timestamp,
        };
      }
    }
  }

  // Bottom reversal → LONG signal
  if (barsFromBottom >= 2 && barsFromBottom <= 8) {
    const rise = current - windowMin;
    if (rise / windowRange >= 0.35 && rise >= 0.002) {
      const after = values.slice(minIdx + 1);
      if (after[after.length - 1] > after[0]) { // net rise since bottom
        return {
          direction: 'long',
          extreme: +(windowMin * 100).toFixed(1),
          current: +(current * 100).toFixed(1),
          barsAgo: barsFromBottom,
          strength: +(rise * 100).toFixed(2),
          range: +(windowRange * 100).toFixed(2),
          extremeTs: data[minIdx].timestamp,
        };
      }
    }
  }

  return null;
}

async function runLsRatioScan(period = '15m') {
  const cache = lsRatioCache[period];
  if (!cache || cache.scanning) return;
  cache.scanning = true;
  console.log(`[LSRatio] Starting scan period=${period}…`);
  try {
    const snapshot = await getMarketSnapshot();
    const coins = snapshot
      .filter((r) => r.quoteVolume >= 5_000_000)
      .sort((a, b) => b.quoteVolume - a.quoteVolume)
      .slice(0, 150);

    const results = [];
    for (const coin of coins) {
      try {
        const data = await client.getTopLongShortPositionRatio(coin.symbol, period, 20);
        if (!data || data.length < 4) continue;
        const signal = detectLsReversal(data);
        if (signal) results.push({ symbol: coin.symbol, volume: coin.quoteVolume, markPrice: coin.markPrice, ...signal });
      } catch { /* skip unsupported symbols */ }
      await new Promise((r) => setTimeout(r, 80));
    }

    results.sort((a, b) => b.strength - a.strength);
    cache.data = results;
    cache.updatedAt = Date.now();
    console.log(`[LSRatio] Scan done period=${period} — ${results.length} signals`);
  } finally {
    cache.scanning = false;
  }
}

// ── End L/S Ratio Scanner ────────────────────────────────────────────────────

const negativeSince = new Map(); // symbol → timestamp when position first went negative
// Position timeout — real Binance positions
const positionFirstSeenAt = new Map(); // symbol → timestamp (from onRoeUpdate first call or slTracking)
const positionTimeoutFired = new Set(); // symbol — prevent double-fire per position lifecycle

const tpMovedToEntry = new Map(); // symbol → entryPrice when TP was moved to entry

function negativeTpRoeThreshold() {
  return normalizeNegativeTpRoe(
    process.env.NEG_TP_ROE ?? BINANCE_NEGATIVE_TP_TO_ENTRY_DEFAULT_ROE,
  );
}

const twelveHourTpMoved = new Map(); // symbol -> entry price handled for the current lifecycle
const twelveHourTpLastRun = new Map();
const twelveHourTpRunning = new Set();
const TWELVE_HOUR_TP_COOLDOWN_MS = 60_000;

function isTruthyBinanceFlag(value) {
  return value === true || String(value ?? '').toLowerCase() === 'true';
}

function positionOrderMatchesSide(order, symbol, closeSide, positionSide) {
  if (String(order?.symbol ?? '').toUpperCase() !== symbol) return false;
  if (String(order?.side ?? '').toUpperCase() !== closeSide) return false;
  return String(order?.positionSide ?? 'BOTH').toUpperCase() === positionSide;
}

function regularTakeProfitCloseOrders(orders, { symbol, closeSide, positionSide }) {
  const hedgeMode = positionSide !== 'BOTH';
  return (Array.isArray(orders) ? orders : []).filter((order) => {
    if (!positionOrderMatchesSide(order, symbol, closeSide, positionSide)) return false;
    const type = String(order?.origType ?? order?.type ?? '').toUpperCase();
    if (type === 'TAKE_PROFIT' || type === 'TAKE_PROFIT_MARKET') return true;
    if (type !== 'LIMIT') return false;
    return hedgeMode || isTruthyBinanceFlag(order?.reduceOnly) || isTruthyBinanceFlag(order?.closePosition);
  });
}

function algoTakeProfitCloseOrders(orders, { symbol, closeSide, positionSide }) {
  return (Array.isArray(orders) ? orders : []).filter((order) => {
    if (!positionOrderMatchesSide(order, symbol, closeSide, positionSide)) return false;
    const type = String(order?.orderType ?? order?.type ?? '').toUpperCase();
    return type === 'TAKE_PROFIT' || type === 'TAKE_PROFIT_MARKET';
  });
}

function takeProfitOrderPrice(order) {
  return Number(order?.triggerPrice ?? order?.stopPrice ?? order?.price);
}

function takeProfitOrderQuantity(order) {
  return Number(order?.origQty ?? order?.quantity ?? order?.executedQty ?? 0);
}

function positionOpenedAtForTwelveHourTp(symbol) {
  const tracked = slTracking.positions?.[symbol] ?? null;
  return parseBinancePositionOpenedAt(tracked?.openedAt)
    ?? parseBinancePositionOpenedAt(positionFirstSeenAt.get(symbol));
}

function negativeEntryGuardHasPriority(symbol, pos, roe) {
  if (isCapTslSymbol(symbol)) return false;
  const entry = Number(pos?.entry ?? pos?.entryPrice);
  const movedEntry = Number(tpMovedToEntry.get(symbol));
  if (Number.isFinite(movedEntry) && Number.isFinite(entry) && entry > 0
    && Math.abs(movedEntry - entry) / entry < 0.005) return true;
  const negTpRoe = negativeTpRoeThreshold();
  const tpGuardRoe = Number(process.env.TP_ENTRY_GUARD_ROE ?? -50);
  if (shouldMoveSymbolNegativeTpToEntry(symbol, roe, negTpRoe) || Number(roe) <= tpGuardRoe) return true;
  return evaluateBinanceEightHourNegativeTakeProfit({
    enabled: process.env.BINANCE_NEGATIVE_TP_AFTER_8H_ENABLED !== 'false',
    openedAt: positionOpenedAtForTwelveHourTp(symbol),
    entryPrice: entry,
    positionAmount: Number(pos?.amt ?? pos?.positionAmt),
    currentRoe: roe,
    capTsl: false,
    maxAgeMs: Number(
      process.env.BINANCE_NEGATIVE_TP_AFTER_8H_MS ?? DEFAULT_BINANCE_NEGATIVE_TP_MAX_AGE_MS,
    ),
  }).eligible;
}

async function handleEightHourNegativeTakeProfit(symbol, pos, roe) {
  const entry = Number(pos?.entry ?? pos?.entryPrice);
  const amt = Number(pos?.amt ?? pos?.positionAmt);
  const decision = evaluateBinanceEightHourNegativeTakeProfit({
    enabled: process.env.BINANCE_NEGATIVE_TP_AFTER_8H_ENABLED !== 'false',
    openedAt: positionOpenedAtForTwelveHourTp(symbol),
    entryPrice: entry,
    positionAmount: amt,
    currentRoe: roe,
    capTsl: isCapTslSymbol(symbol),
    maxAgeMs: Number(
      process.env.BINANCE_NEGATIVE_TP_AFTER_8H_MS ?? DEFAULT_BINANCE_NEGATIVE_TP_MAX_AGE_MS,
    ),
  });
  if (!decision.eligible) return;
  await handleNegativeTimeoutTp(symbol, {
    ...pos,
    entry,
    amt,
  }, {
    triggerVersion: BINANCE_EIGHT_HOUR_NEGATIVE_TP_VERSION,
    triggerAgeMs: decision.ageMs,
    triggerRoe: decision.currentRoe,
  });
}

async function rememberTwelveHourTakeProfit(symbol, entry, targetPrice, targetRoePct, ageMs, action) {
  twelveHourTpMoved.set(symbol, entry);
  tpConfirmedClear(symbol);
  const tracking = slTracking.positions?.[symbol] ?? null;
  const lifecycleId = tracking?.lifecycleId ?? signalProtectionPlans.get(symbol)?.lifecycleId ?? null;
  const updatedAt = new Date().toISOString();
  if (tracking) {
    tracking.twelveHourTakeProfitVersion = BINANCE_TWELVE_HOUR_TAKE_PROFIT_VERSION;
    tracking.twelveHourTakeProfitPrice = Number(targetPrice);
    tracking.twelveHourTakeProfitRoe = Number(targetRoePct);
    tracking.twelveHourTakeProfitAgeMs = Number(ageMs);
    tracking.twelveHourTakeProfitAction = action;
    tracking.twelveHourTakeProfitUpdatedAt = updatedAt;
    await saveSlTracking();
  }
  if (lifecycleId) {
    await liveCardBinanceLifecycle.upsert({
      lifecycleId,
      twelveHourTakeProfitVersion: BINANCE_TWELVE_HOUR_TAKE_PROFIT_VERSION,
      twelveHourTakeProfitPrice: Number(targetPrice),
      twelveHourTakeProfitRoe: Number(targetRoePct),
      twelveHourTakeProfitAgeMs: Number(ageMs),
      twelveHourTakeProfitAction: action,
      twelveHourTakeProfitUpdatedAt: updatedAt,
    }, 'TWELVE_HOUR_TP_MOVED', {
      symbol,
      targetPrice: Number(targetPrice),
      targetRoePct: Number(targetRoePct),
      ageMs: Number(ageMs),
      action,
    }).catch((error) => console.warn(`[12hTP] lifecycle ${symbol}:`, error.message));
  }
}

async function handleTwelveHourTakeProfit(symbol, pos, markPrice, roe) {
  const enabled = process.env.BINANCE_TP_AFTER_12H_ENABLED !== 'false';
  const maxAgeMs = Number(process.env.BINANCE_TP_AFTER_12H_MS ?? DEFAULT_BINANCE_TP_MAX_AGE_MS);
  const targetRoePct = Number(process.env.BINANCE_TP_AFTER_12H_ROE ?? DEFAULT_BINANCE_TP_TARGET_ROE_PCT);
  const entry = Number(pos?.entry ?? pos?.entryPrice);
  const amt = Number(pos?.amt ?? pos?.positionAmt);
  const leverage = Number(pos?.leverage) || 1;
  const openedAt = positionOpenedAtForTwelveHourTp(symbol);
  const decision = evaluateBinanceTwelveHourTakeProfit({
    enabled,
    openedAt,
    entryPrice: entry,
    leverage,
    positionAmount: amt,
    maxAgeMs,
    targetRoePct,
  });
  if (!decision.eligible || negativeEntryGuardHasPriority(symbol, pos, roe)) return;

  const previousEntry = Number(twelveHourTpMoved.get(symbol));
  if (Number.isFinite(previousEntry) && entry > 0 && Math.abs(previousEntry - entry) / entry < 0.0001) return;
  if (twelveHourTpRunning.has(symbol)) return;
  const lastRun = twelveHourTpLastRun.get(symbol) ?? 0;
  if (Date.now() - lastRun < TWELVE_HOUR_TP_COOLDOWN_MS) return;
  twelveHourTpLastRun.set(symbol, Date.now());
  twelveHourTpRunning.add(symbol);

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
    const [openOrders, algoResult, symbols] = await Promise.all([
      client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
      client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }).catch(() => ({ orders: [] })),
      getSymbols(),
    ]);
    const symbolInfo = symbols.find((row) => row.symbol === symbol);
    if (!symbolInfo) throw new Error('symbol metadata not found');

    const tickSize = Number(symbolInfo.filters?.find((filter) => filter.filterType === 'PRICE_FILTER')?.tickSize ?? 0.00000001);
    const roundedTarget = roundBinanceTakeProfitTowardProfit({
      price: decision.targetPrice,
      tickSize,
      side: decision.side,
    });
    if (!roundedTarget) throw new Error('invalid +1% ROE target price');
    const targetPrice = priceFromTick(symbolInfo, roundedTarget);
    const targetNumeric = Number(targetPrice);
    const positionSide = String(pos?.positionSide ?? 'BOTH').toUpperCase();
    const orderMatch = { symbol, closeSide: decision.closeSide, positionSide };
    const algoRows = Array.isArray(algoResult?.orders)
      ? algoResult.orders
      : Array.isArray(algoResult) ? algoResult : [];
    const regularTp = regularTakeProfitCloseOrders(openOrders, orderMatch);
    const algoTp = algoTakeProfitCloseOrders(algoRows, orderMatch);

    const lotSize = symbolInfo.filters?.find((filter) => filter.filterType === 'LOT_SIZE');
    const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
    const steppedQty = Math.floor(Math.abs(amt) / stepSize) * stepSize;
    if (!Number.isFinite(steppedQty) || steppedQty <= 0) throw new Error('position quantity rounds to zero');
    const quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');
    const quantityNumeric = Number(quantity);
    const qtyCovers = (order) => {
      const orderQty = takeProfitOrderQuantity(order);
      return !Number.isFinite(orderQty) || orderQty <= 0 || orderQty >= quantityNumeric * 0.995;
    };
    const matchesTarget = (order) => isBinanceTwelveHourTpPriceMatch(
      takeProfitOrderPrice(order),
      targetNumeric,
      tickSize,
    ) && qtyCovers(order);
    if ([...regularTp, ...algoTp].some(matchesTarget)) {
      await rememberTwelveHourTakeProfit(
        symbol, entry, targetNumeric, decision.targetRoePct, decision.ageMs, 'EXISTING_TARGET',
      );
      console.log(`[12hTP] ${symbol} already has TP at ${targetPrice}; marked complete`);
      return;
    }

    for (const order of regularTp) {
      if (!order.orderId) continue;
      await client.cancelOrder({ symbol, orderId: order.orderId, apiKey, apiSecret, recvWindow });
      await new Promise((resolve) => setTimeout(resolve, 80));
    }
    for (const order of algoTp) {
      if (!order.algoId) continue;
      await client.cancelAlgoOrder({ algoId: order.algoId, apiKey, apiSecret, recvWindow });
      await new Promise((resolve) => setTimeout(resolve, 80));
    }
    if (regularTp.length || algoTp.length) invalidateOpenOrdersCache();

    // If the +1% target is already behind Mark, use a marketable reduce-only LIMIT.
    // It closes at the target or better without accepting an unbounded MARKET fill.
    const currentRoe = Number(roe);
    const closeNow = Number.isFinite(currentRoe) && currentRoe >= decision.targetRoePct;
    if (closeNow) {
      const params = {
        symbol,
        side: decision.closeSide,
        type: 'LIMIT',
        price: String(targetPrice),
        quantity,
        timeInForce: 'GTC',
        recvWindow,
        newClientOrderId: `tp12h_limit_${Date.now()}`.slice(0, 36),
      };
      if (positionSide !== 'BOTH') params.positionSide = positionSide;
      else params.reduceOnly = 'true';
      await client.placeFuturesOrder({ params, apiKey, apiSecret });
      await rememberTwelveHourTakeProfit(
        symbol, entry, targetNumeric, decision.targetRoePct, decision.ageMs, 'MARKETABLE_LIMIT_ABOVE_TARGET',
      );
      console.log(`[12hTP] ${symbol} age=${(decision.ageMs / 3_600_000).toFixed(1)}h ROE=${currentRoe.toFixed(2)}% -> marketable LIMIT ${targetPrice} (target +${decision.targetRoePct}% ROE)`);
      return;
    }

    const params = {
      algoType: 'CONDITIONAL',
      symbol,
      side: decision.closeSide,
      type: 'TAKE_PROFIT_MARKET',
      triggerPrice: String(targetPrice),
      quantity,
      workingType: 'MARK_PRICE',
      recvWindow,
      newClientOrderId: `tp12h_${Date.now()}`.slice(0, 36),
    };
    if (positionSide !== 'BOTH') params.positionSide = positionSide;
    else params.reduceOnly = 'true';
    await client.placeAlgoOrder({ params, apiKey, apiSecret });
    invalidateOpenOrdersCache();
    await rememberTwelveHourTakeProfit(
      symbol, entry, targetNumeric, decision.targetRoePct, decision.ageMs, 'TP_MOVED',
    );
    console.log(`[12hTP] ${symbol} ${decision.side} age=${(decision.ageMs / 3_600_000).toFixed(1)}h -> TP ${targetPrice} (+${decision.targetRoePct}% ROE at ${leverage}x); SL retained`);
  } catch (error) {
    console.error(`[12hTP] ${symbol}:`, error.message);
  } finally {
    twelveHourTpRunning.delete(symbol);
  }
}

async function handleTpEntryGuard(symbol, pos, markPrice, roe) {
  return handleNegativeTimeoutTp(symbol, pos);
}

// ── Real Binance Position Timeout ─────────────────────────────────────────────
// Đóng lệnh thật sau X giờ nếu ROE > minRoe% (đang lời nhẹ) và chưa đạt TP
async function handlePositionTimeout(symbol, pos, markPrice, roe) {
  if (!runtimeSettings.positionTimeoutEnabled) return;
  if (roe < 0) return;                                      // Tuyệt đối không cắt lệnh âm
  if (roe <= runtimeSettings.positionTimeoutMinRoe) return; // Chỉ cắt khi ROE > minRoe%
  if (positionTimeoutFired.has(symbol)) return;

  // Xác định openedAt: ưu tiên slTracking (chính xác từ fill), fallback positionFirstSeenAt
  const tracked = slTracking.positions[symbol];
  const openedAt = tracked?.openedAt ?? positionFirstSeenAt.get(symbol);
  if (!openedAt) return; // chưa biết thời gian mở

  const timeoutMs = runtimeSettings.positionTimeoutH * 3_600_000;
  const elapsed = Date.now() - openedAt;
  if (elapsed < timeoutMs) return; // chưa đủ thời gian

  positionTimeoutFired.add(symbol);

  let apiKey, apiSecret;
  try {
    ({ apiKey, apiSecret } = getApiCredentials(null));
  } catch {
    positionTimeoutFired.delete(symbol);
    return;
  }

  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  const amt = Number(pos.amt ?? pos.positionAmt ?? 0);
  if (amt === 0) { positionTimeoutFired.delete(symbol); return; }

  const isLong = amt > 0;
  const closeSide = isLong ? 'SELL' : 'BUY';
  const positionSide = pos.positionSide ?? 'BOTH';
  const isHedge = positionSide !== 'BOTH';

  // Tính quantity theo step size
  const symbols = await getSymbols().catch(() => []);
  const symbolInfo = symbols.find((s) => s.symbol === symbol);
  let quantity;
  if (symbolInfo) {
    const lotSize = symbolInfo.filters?.find((f) => f.filterType === 'LOT_SIZE');
    const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
    const steppedQty = Math.floor(Math.abs(amt) / stepSize) * stepSize;
    quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');
  } else {
    quantity = String(Math.abs(amt));
  }

  const orderParams = {
    symbol,
    side: closeSide,
    type: 'MARKET',
    quantity,
    recvWindow,
    newClientOrderId: `lp_ptout_${Date.now()}`.slice(0, 36),
  };
  if (isHedge) { orderParams.positionSide = positionSide; } else { orderParams.reduceOnly = 'true'; }

  const elapsedH = (elapsed / 3_600_000).toFixed(1);
  console.log(`[PosTimeout] ⏱ ${symbol} ${isLong ? 'LONG' : 'SHORT'} ROE=${roe.toFixed(2)}% elapsed=${elapsedH}h → market close`);

  try {
    const result = await client.placeFuturesOrder({ params: orderParams, apiKey, apiSecret });
    console.log(`[PosTimeout] ✅ ${symbol} market close OK orderId=${result?.orderId ?? '?'}`);
  } catch (err) {
    console.error(`[PosTimeout] ❌ ${symbol}: ${err.message}`);
    positionTimeoutFired.delete(symbol); // retry nếu lỗi
  }
}

function startNegTpScanner() {
  const intervalMs = Number(process.env.NEG_TP_SCAN_INTERVAL_MS ?? 30000);
  const negTpRoe = negativeTpRoeThreshold();
  const tpGuardRoe = Number(process.env.TP_ENTRY_GUARD_ROE ?? -50);
  const ageMs = Number(
    process.env.BINANCE_NEGATIVE_TP_AFTER_8H_MS ?? DEFAULT_BINANCE_NEGATIVE_TP_MAX_AGE_MS,
  );
  console.log(`[NegTp] Scanner started. deep=${BINANCE_NEGATIVE_TP_TO_ENTRY_VERSION} ROE threshold=${negTpRoe}% age=${BINANCE_EIGHT_HOUR_NEGATIVE_TP_VERSION} ${ageMs / 3_600_000}h interval=${intervalMs / 1000}s`);

  const run = async () => {
    try {
      const { positions: active } = await getSharedPositionData();
      if (!active.length) return;
      const activeSymbols = new Set(active.map((p) => p.symbol));
      for (const sym of negativeSince.keys()) {
        if (!activeSymbols.has(sym)) negativeSince.delete(sym);
      }
      for (const p of active) {
        const symbol = p.symbol;
        if (isCapTslSymbol(symbol)) {
          negativeSince.delete(symbol);
          continue;
        }
        const amt = Number(p.positionAmt);
        const entry = Number(p.entryPrice);
        const lev = Number(p.leverage) || 1;
        const mark = Number(p.markPrice);
        // unRealizedProfit = 0 khi chưa có WS tick → tính lại từ mark price
        const rawUpnl = Number(p.unRealizedProfit);
        const upnl = rawUpnl !== 0 ? rawUpnl : (mark > 0 ? (mark - entry) * amt : null);
        if (upnl === null) continue; // chưa có mark price, bỏ qua
        const isolated = Number(p.isolatedMargin);
        const initial = Number(p.initialMargin);
        const margin = isolated > 0 ? isolated : initial > 0 ? initial : Math.abs(amt) * entry / lev;
        if (margin <= 0) continue;
        const roe = (upnl / margin) * 100;
        const pos = { amt, entry, leverage: lev, positionSide: p.positionSide ?? 'BOTH' };
        if (shouldMoveSymbolNegativeTpToEntry(symbol, roe, negTpRoe) || roe <= tpGuardRoe) {
          handleNegativeTimeoutTp(symbol, pos).catch(() => {});
        }
        handleEightHourNegativeTakeProfit(symbol, pos, roe).catch(() => {});
        if (roe < 0) {
          if (!negativeSince.has(symbol)) negativeSince.set(symbol, Date.now());
        } else {
          negativeSince.delete(symbol);
          tpMovedToEntry.delete(symbol);
        }
      }
    } catch (err) {
      console.error('[NegTp] Scanner error:', err.message);
    }
  };

  setInterval(run, intervalMs);
  run();
}

// symbol|entry keys confirmed to have a TP — skip API check until position changes or fill
const tpConfirmedSet = new Set();
const tpProtectionRunning = new Set();
function tpConfirmedClear(symbol) {
  for (const k of tpConfirmedSet) { if (k.startsWith(`${symbol}|`)) tpConfirmedSet.delete(k); }
}

let startupTakeProfitRecoveryScheduled = false;
let startupTakeProfitRecoveryRunning = null;
let missedFillProtectionRecoveryScheduled = false;
let missedFillProtectionRecoveryRunning = null;

function startupRecoveryTimestamp(row = {}) {
  const raw = row.binanceEntryFilledAt ?? row.fillTime ?? row.filledAt ?? row.updatedAt ?? row.createdAt ?? 0;
  const numeric = Number(raw);
  if (Number.isFinite(numeric) && numeric > 0) return numeric;
  const parsed = Date.parse(String(raw ?? ''));
  return Number.isFinite(parsed) ? parsed : 0;
}

function latestMatchingStartupRow(rows, pos, { statuses = null, entryFields = [] } = {}) {
  const symbol = normalizeSymbol(pos?.symbol ?? '');
  const amount = Number(pos?.positionAmt ?? pos?.amt);
  const side = amount > 0 ? 'LONG' : 'SHORT';
  const entry = Number(pos?.entryPrice ?? pos?.entry);
  return (Array.isArray(rows) ? rows : [])
    .filter((row) => {
      if (normalizeSymbol(row?.symbol ?? '') !== symbol) return false;
      if (String(row?.side ?? '').toUpperCase() !== side) return false;
      if (statuses && !statuses.has(String(row?.status ?? '').toUpperCase())) return false;
      const rowEntry = entryFields.map((field) => Number(row?.[field])).find((value) => Number.isFinite(value) && value > 0);
      return !(entry > 0 && rowEntry > 0) || Math.abs(entry - rowEntry) / rowEntry <= 0.05;
    })
    .sort((a, b) => startupRecoveryTimestamp(b) - startupRecoveryTimestamp(a))[0] ?? null;
}

function liquidFlowV2StartupTakeProfit(pos) {
  const trade = latestMatchingStartupRow(liquidFlowV2Paper.state.trades, pos, {
    statuses: new Set(['OPEN', 'PENDING_ENTRY']),
    entryFields: ['binanceEntryPrice', 'entryPrice'],
  });
  if (!trade || String(trade.binanceEntryState ?? '').toUpperCase() !== 'FILLED') return null;
  const takeProfitPrice = Number(trade.binanceProtectionSignalTakeProfitPrice ?? trade.takeProfit);
  return Number.isFinite(takeProfitPrice) && takeProfitPrice > 0
    ? { trade, takeProfitPrice }
    : null;
}

async function placeStartupMissingTakeProfitOnly({
  pos,
  symbolInfo,
  target,
  apiKey,
  apiSecret,
  snapshotRegularOrders,
  snapshotAlgoOrders,
}) {
  const symbol = normalizeSymbol(pos?.symbol ?? '');
  if (!symbol || !symbolInfo || !target?.takeProfitPrice) return 'NO_TARGET';
  if (!startupPositionNeedsTakeProfit(pos, snapshotRegularOrders, snapshotAlgoOrders)) return 'EXISTING';

  const amount = Number(pos.positionAmt ?? pos.amt);
  const closeSide = amount > 0 ? 'SELL' : 'BUY';
  const positionSide = String(pos.positionSide ?? 'BOTH').toUpperCase();
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  const triggerPrice = priceFromTick(symbolInfo, Number(target.takeProfitPrice));
  if (!triggerPrice || triggerPrice === 'NaN' || Number(triggerPrice) <= 0) return 'INVALID_TARGET';

  // Fresh fail-closed read immediately before the write. Any existing regular
  // or algo TP is authoritative, regardless of its price or quantity.
  const [freshRegular, freshAlgoResult] = await Promise.all([
    client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
    client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }),
  ]);
  const freshAlgo = Array.isArray(freshAlgoResult?.orders)
    ? freshAlgoResult.orders
    : Array.isArray(freshAlgoResult) ? freshAlgoResult : [];
  if (!startupPositionNeedsTakeProfit(pos, freshRegular, freshAlgo)) return 'EXISTING';

  const params = buildStartupTakeProfitOrderParams({
    symbol,
    closeSide,
    positionSide,
    triggerPrice,
    workingType: String(target.workingType ?? 'MARK_PRICE').toUpperCase(),
    recvWindow,
  });

  const result = await client.placeAlgoOrder({ params, apiKey, apiSecret });
  tpConfirmedSet.add(`${symbol}|${Number(pos.entryPrice ?? pos.entry).toFixed(8)}`);
  invalidateOpenOrdersCache();
  console.log(
    `[TpOnlyGuard] placed ${symbol} ${amount > 0 ? 'LONG' : 'SHORT'} TP=${triggerPrice}`
    + ` source=${target.source ?? '-'} workingType=${params.workingType}`
    + ` algoId=${result?.algoId ?? '-'} version=${BINANCE_STARTUP_TP_ONLY_RECOVERY_VERSION}; SL untouched`,
  );
  return 'PLACED';
}

async function runStartupTakeProfitRecovery() {
  const { apiKey, apiSecret } = getApiCredentials(null);
  invalidatePosStore();
  const [{ positions, openOrders, algoOrders }, symbols, lifecycleStatus] = await Promise.all([
    getSharedPositionData({ bypassAlgoRestDefer: true }),
    getSymbols(),
    liveCardBinanceLifecycle.status().catch(() => ({ executions: [] })),
  ]);
  const active = Array.isArray(positions) ? positions : [];
  const lifecycleRows = Array.isArray(lifecycleStatus?.executions) ? lifecycleStatus.executions : [];
  const activeLifecycleStatuses = new Set([
    'ENTRY_PARTIALLY_FILLED', 'ENTRY_FILLED', 'PROTECTED', 'PROTECTION_FAILED', 'BOT_CLOSE_FAILED',
  ]);
  const summary = { active: active.length, existing: 0, placed: 0, noTarget: 0, failed: 0 };

  for (const pos of active) {
    const symbol = normalizeSymbol(pos.symbol);
    try {
      if (!startupPositionNeedsTakeProfit(pos, openOrders, algoOrders)) {
        summary.existing += 1;
        continue;
      }
      const tracking = slTracking.positions?.[symbol] ?? null;
      const plan = signalProtectionPlans.get(symbol) ?? null;
      const lifecycle = latestMatchingStartupRow(lifecycleRows, pos, {
        statuses: activeLifecycleStatuses,
        entryFields: ['fillPrice', 'entryPrice'],
      });
      const liquidFlowV2Match = liquidFlowV2StartupTakeProfit(pos);
      const trackedTakeProfitPrice = Number(
        tracking?.signalTp ?? plan?.tpPrice ?? lifecycle?.takeProfitPrice ?? lifecycle?.signalTakeProfitPrice,
      );
      const trackedSource = String(
        tracking?.signalSource ?? plan?.source ?? lifecycle?.sourceType ?? lifecycle?.signalSource ?? '',
      ).trim();
      const isLiquidFlowV2 = Boolean(liquidFlowV2Match) || isLiquidFlowV2ManagedPosition(symbol, pos);
      const isManual = !lifecycle && !isLiquidFlowV2 && isManualBinanceManagedPosition(symbol, pos);
      const pumpRecord = [...pumpPendingOrders, ...pumpWatchingOrders].find(
        (row) => row.symbol === symbol && Number(row.tp) > 0
          && Math.abs((Number(row.fillPrice ?? row.entry) - Number(pos.entryPrice)) / Number(pos.entryPrice)) < 0.01,
      );
      const target = resolveStartupTakeProfitTarget({
        side: Number(pos.positionAmt) > 0 ? 'LONG' : 'SHORT',
        entryPrice: Number(pos.entryPrice),
        leverage: Number(pos.leverage) || 1,
        trackedTakeProfitPrice,
        liquidFlowV2TakeProfitPrice: liquidFlowV2Match?.takeProfitPrice,
        pumpTakeProfitPrice: pumpRecord?.tp,
        isLiquidFlowV2,
        isManual,
        source: trackedSource || (pumpRecord ? 'pump-order' : null),
        defaultLongRoePct: Number(process.env.AUTO_TRADE_LONG_TP_ROE ?? 10),
        defaultShortRoePct: Number(process.env.AUTO_TRADE_SHORT_TP_ROE ?? 6),
      });
      if (!target) {
        summary.noTarget += 1;
        console.warn(`[TpOnlyGuard] ${symbol} missing TP but no causal target recovered; skipped; SL untouched`);
        continue;
      }
      target.workingType = String(
        tracking?.takeProfitWorkingType
        ?? plan?.takeProfitWorkingType
        ?? lifecycle?.takeProfitWorkingType
        ?? (isLiquidFlowV2 ? 'CONTRACT_PRICE' : 'MARK_PRICE'),
      ).toUpperCase();
      const result = await placeStartupMissingTakeProfitOnly({
        pos,
        symbolInfo: symbols.find((row) => row.symbol === symbol),
        target,
        apiKey,
        apiSecret,
        snapshotRegularOrders: openOrders,
        snapshotAlgoOrders: algoOrders,
      });
      if (result === 'PLACED') summary.placed += 1;
      else if (result === 'EXISTING') summary.existing += 1;
      else summary.noTarget += 1;
    } catch (error) {
      summary.failed += 1;
      console.warn(`[TpOnlyGuard] ${symbol} failed: ${error.message}; no orders cancelled; SL untouched`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  console.log(`[TpOnlyGuard] scan complete ${JSON.stringify(summary)} version=${BINANCE_STARTUP_TP_ONLY_RECOVERY_VERSION}; SL untouched`);
  return summary;
}

function runTakeProfitOnlyGuardOnce() {
  if (startupTakeProfitRecoveryRunning) return startupTakeProfitRecoveryRunning;
  startupTakeProfitRecoveryRunning = runStartupTakeProfitRecovery()
    .catch((error) => {
      console.warn(`[TpOnlyGuard] scan aborted: ${error.message}; SL untouched`);
      return null;
    })
    .finally(() => {
      startupTakeProfitRecoveryRunning = null;
    });
  return startupTakeProfitRecoveryRunning;
}

function startStartupTakeProfitRecovery() {
  if (startupTakeProfitRecoveryScheduled || process.env.BINANCE_STARTUP_TP_RECOVERY_ENABLED === 'false') return;
  startupTakeProfitRecoveryScheduled = true;
  const delayMs = Math.max(5_000, Number(process.env.BINANCE_STARTUP_TP_RECOVERY_DELAY_MS ?? 20_000));
  const intervalMs = Math.max(30_000, Number(process.env.BINANCE_TP_ONLY_GUARD_INTERVAL_MS ?? 60_000));
  console.log(
    `[TpOnlyGuard] scheduled after ${delayMs}ms, then every ${intervalMs}ms;`
    + ' only place a missing TP; never place/cancel/replace SL',
  );
  setTimeout(() => {
    runTakeProfitOnlyGuardOnce();
    setInterval(() => runTakeProfitOnlyGuardOnce(), intervalMs).unref?.();
  }, delayMs).unref?.();
}

function runMissedFillProtectionRecovery(reason = 'SCHEDULED') {
  if (missedFillProtectionRecoveryRunning) return missedFillProtectionRecoveryRunning;
  missedFillProtectionRecoveryRunning = (async () => {
    if (!posMonitor?.recoverMissedFullFills) throw new Error('position monitor not ready');
    const summary = await posMonitor.recoverMissedFullFills({
      since: Number(protectionFillWatermark.lastHandledFillAt) || 0,
      handledOrderIds: protectionFillWatermark.handledOrderIds,
      recoverySource: String(reason).startsWith('USER_DATA_RECONNECT:')
        ? 'MISSED_FILL_RECONNECT_RECOVERY'
        : 'MISSED_FILL_RECOVERY',
    });
    console.log(
      `[ProtectionRecovery] complete reason=${reason} ${JSON.stringify(summary)}`
      + ` watermark=${new Date(Number(protectionFillWatermark.lastHandledFillAt) || 0).toISOString()}`,
    );
    return summary;
  })().finally(() => {
    missedFillProtectionRecoveryRunning = null;
  });
  return missedFillProtectionRecoveryRunning;
}

function startMissedFillProtectionRecovery() {
  if (missedFillProtectionRecoveryScheduled || process.env.BINANCE_MISSED_FILL_RECOVERY_ENABLED === 'false') return;
  missedFillProtectionRecoveryScheduled = true;
  const delayMs = Math.max(5_000, Number(process.env.BINANCE_MISSED_FILL_RECOVERY_DELAY_MS ?? 12_000));
  console.log(
    `[ProtectionRecovery] scheduled once after ${delayMs}ms from durable full-fill watermark;`
    + ` no periodic missing-SL/TP scan; version=${POSITION_PROTECTION_TRIGGER_VERSION}`,
  );
  setTimeout(async () => {
    try {
      await runMissedFillProtectionRecovery('STARTUP_ONE_SHOT');
    } catch (error) {
      console.warn(`[ProtectionRecovery] one-shot failed: ${error.message}`);
    }
  }, delayMs).unref?.();
}

function startMissingTpScanner() {
  if (process.env.AUTO_TP_SCAN_ENABLED === 'false') return;
  const intervalMs = Math.max(Number(process.env.AUTO_TP_SCAN_INTERVAL_MS ?? 60_000), 30_000);
  console.log(`[AutoTP] Scanner started. interval=${intervalMs / 1000}s`);
  const run = () => runMissingTpScan().catch((err) => {
    if (err.message?.includes('Missing Binance API') || err.message?.includes('Chưa đăng nhập')) return;
    console.error('[AutoTP] Scan error:', err.message);
  });
  run();
  setInterval(run, intervalMs);
}

function startSlTrailSafetyScanner() {
  if (process.env.SL_TRAIL_SAFETY_SCAN_ENABLED === 'false') return;
  const intervalMs = Math.max(Number(process.env.SL_TRAIL_SAFETY_SCAN_INTERVAL_MS ?? 30_000), 10_000);
  console.log(`[SlTrailScan] Safety scanner started. interval=${intervalMs / 1000}s`);
  const run = () => runSlTrailSafetyScan().catch((err) => {
    if (err.message?.includes('Missing Binance API')) return;
    console.error('[SlTrailScan] Scan error:', err.message);
  });
  run();
  setTimeout(run, 10_000).unref?.();
  setInterval(run, intervalMs);
}

async function refreshTakeProfitForSymbol(symbol) {
  const { apiKey, apiSecret } = getApiCredentials(null);
  invalidateOpenOrdersCache();

  const { positions } = await getSharedPositionData();
  let pos = positions.find((p) => p.symbol === symbol);
  if (!pos && posMonitor?.getActivePositions) {
    pos = posMonitor.getActivePositions().find((p) => p.symbol === symbol);
  }
  if (!pos || Number(pos.positionAmt) === 0) {
    console.warn(`[AutoTP] ${symbol} fill refresh skipped: active position not found`);
    return;
  }

  const symbols = await getSymbols();
  await ensureTakeProfitForPosition(pos, symbols, apiKey, apiSecret, null, null, { force: true });
}

async function getPositionRoeForTpGuard(pos, { fetchMark = false } = {}) {
  const symbol = pos.symbol;
  const amt = Number(pos.positionAmt ?? pos.amt);
  const entry = Number(pos.entryPrice ?? pos.entry);
  const leverage = Number(pos.leverage) || 1;
  if (!symbol || !amt || !entry) return { ready: false, amt, entry, leverage };

  const isolatedMargin = Number(pos.isolatedMargin);
  const initialMargin = Number(pos.initialMargin);
  const margin = isolatedMargin > 0
    ? isolatedMargin
    : initialMargin > 0
      ? initialMargin
      : Math.abs(amt) * entry / leverage;
  if (margin <= 0) return { ready: false, amt, entry, leverage };

  let mark = Number(pos.markPrice);
  let rawUpnl = Number(pos.unRealizedProfit ?? pos.unrealizedProfit);
  const needsMark = fetchMark || !Number.isFinite(mark) || mark <= 0 || !Number.isFinite(rawUpnl) || rawUpnl === 0;
  if (needsMark) {
    const premium = await client.getPremiumIndex(symbol).catch(() => null);
    const fetchedMark = Number(premium?.markPrice);
    if (Number.isFinite(fetchedMark) && fetchedMark > 0) mark = fetchedMark;
  }

  const upnl = fetchMark && Number.isFinite(mark) && mark > 0
    ? (mark - entry) * amt
    : Number.isFinite(rawUpnl) && rawUpnl !== 0
      ? rawUpnl
      : Number.isFinite(mark) && mark > 0
        ? (mark - entry) * amt
        : NaN;
  if (!Number.isFinite(upnl)) return { ready: false, amt, entry, leverage, margin, mark };

  return {
    ready: true,
    amt,
    entry,
    leverage,
    margin,
    mark,
    upnl,
    roe: (upnl / margin) * 100,
  };
}

async function runSlTrailSafetyScan() {
  if (process.env.AUTO_SL_ENABLED === 'false') return;
  const { positions: active } = await getSharedPositionData({ bypassAlgoRestDefer: true });
  if (!active.length) return;

  for (const p of active) {
    const amt = Number(p.positionAmt);
    const entry = Number(p.entryPrice);
    const mark = Number(p.markPrice);
    const leverage = Number(p.leverage) || 1;
    if (!p.symbol || !amt || !entry) continue;

    const isolatedMargin = Number(p.isolatedMargin);
    const initialMargin = Number(p.positionInitialMargin ?? p.initialMargin);
    const margin = resolvePositionRoeMargin({
      positionInitialMargin: initialMargin,
      isolatedMargin,
      positionAmt: amt,
      entryPrice: entry,
      leverage,
    });
    if (margin <= 0) continue;

    const upnl = Number(p.unRealizedProfit ?? p.unrealizedProfit ?? 0);
    const roe = upnl
      ? (upnl / margin) * 100
      : mark > 0
        ? ((mark - entry) / entry) * leverage * (amt > 0 ? 1 : -1) * 100
        : 0;

    await handleSlTrailByProfit(p.symbol, {
      amt,
      entry,
      leverage,
      isolatedMargin,
      initialMargin,
      positionSide: p.positionSide ?? 'BOTH',
    }, roe, mark || null);
  }
}

async function runMissingTpScan() {
  const { apiKey, apiSecret } = getApiCredentials(null);
  const { positions: active, openOrders: sharedOpenOrders, algoOrders: sharedAlgoOrders } = await getSharedPositionData();
  if (!active.length) return;

  const symbols = await getSymbols();
  for (const pos of active) {
    await ensureTakeProfitForPosition(pos, symbols, apiKey, apiSecret, sharedOpenOrders, sharedAlgoOrders);
    await new Promise((r) => setTimeout(r, 80));
  }
}

async function ensureTakeProfitForPosition(pos, symbols, apiKey, apiSecret, sharedOpenOrders = null, sharedAlgoOrders = null, options = {}) {
  const symbol = pos?.symbol;
  if (!symbol || tpProtectionRunning.has(symbol)) {
    if (symbol) console.log(`[AutoTP] ${symbol} skipped: protection check already running`);
    return;
  }
  tpProtectionRunning.add(symbol);
  try {
    return await ensureTakeProfitForPositionUnlocked(
      pos, symbols, apiKey, apiSecret, sharedOpenOrders, sharedAlgoOrders, options,
    );
  } finally {
    tpProtectionRunning.delete(symbol);
  }
}

async function ensureTakeProfitForPositionUnlocked(pos, symbols, apiKey, apiSecret, sharedOpenOrders = null, sharedAlgoOrders = null, options = {}) {
  const symbol = pos.symbol;
  const amt = Number(pos.positionAmt);
  const entry = Number(pos.entryPrice);
  const leverage = Number(pos.leverage) || 1;
  if (!symbol || !amt || !entry) return;

  const tpKey = `${symbol}|${entry.toFixed(8)}`;
  const isLong = amt > 0;
  const closeSide = isLong ? 'SELL' : 'BUY';
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);
  const preserveSignalProtection = hasPreservedLiveCardSignalProtection(symbol);
  const expectedWorkingType = preserveSignalProtection ? 'CONTRACT_PRICE' : 'MARK_PRICE';
  const takeProfitUserOrV2Managed = isTakeProfitUserOrLiquidFlowV2ManagedPosition(symbol, pos);
  const roeInfo = await getPositionRoeForTpGuard(pos, { fetchMark: options.force });
  const negTpRoe = negativeTpRoeThreshold();
  const tpGuardRoe = Number(process.env.TP_ENTRY_GUARD_ROE ?? -50);
  if (roeInfo.ready && !isCapTslSymbol(symbol)
    && (shouldMoveSymbolNegativeTpToEntry(symbol, roeInfo.roe, negTpRoe) || roeInfo.roe <= tpGuardRoe)) {
    console.log(`[AutoTP] ${symbol} ROE=${roeInfo.roe.toFixed(2)}% <= guard (${Math.max(negTpRoe, tpGuardRoe)}%) -> move TP to entry`);
    await handleNegativeTimeoutTp(symbol, {
      amt,
      entry,
      leverage,
      positionSide: pos.positionSide ?? 'BOTH',
    });
    return;
  }
  if (options.force && !roeInfo.ready) {
    console.warn(`[AutoTP] ${symbol} skip normal TP: cannot compute fresh ROE after fill`);
    return;
  }
  // Skip API calls only after the negative guard had a chance to move TP to entry.
  if (!options.force && tpConfirmedSet.has(tpKey)) return;

  let openOrders, algoRows;
  if (sharedOpenOrders && sharedAlgoOrders) {
    openOrders = sharedOpenOrders.filter((o) => o.symbol === symbol);
    algoRows = sharedAlgoOrders.filter((o) => o.symbol === symbol);
  } else {
    const [openOrdersRes, algoResult] = await Promise.all([
      client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }).catch(() => []),
      client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }).catch(() => ({ orders: [] })),
    ]);
    openOrders = openOrdersRes;
    algoRows = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
  }

  const symbolInfo = symbols.find((s) => s.symbol === symbol);
  if (!symbolInfo) return;

  // Ưu tiên TP gốc của signal đã lưu khi socket fill.
  const trackedSignalTp = Number(slTracking.positions[symbol]?.signalTp ?? 0);
  const trackedSignalSl = Number(slTracking.positions[symbol]?.signalSl ?? 0);
  const pumpRecord = [...pumpPendingOrders, ...pumpWatchingOrders].find(
    (r) => r.symbol === symbol && r.tp && Math.abs((Number(r.fillPrice ?? r.entry) - entry) / entry) < 0.01,
  );
  const takeProfitSource = slTracking.positions[symbol]?.signalSource
    ?? (pumpRecord ? 'pump-order' : 'binance-position-fallback');
  let rawTpPrice;
  if (Number.isFinite(trackedSignalTp) && trackedSignalTp > 0) {
    rawTpPrice = trackedSignalTp;
    console.log(`[AutoTP] 📌 ${symbol} giữ signal TP=${rawTpPrice} source=${slTracking.positions[symbol]?.signalSource ?? '-'}`);
  } else if (preserveSignalProtection) {
    console.warn(`[AutoTP] ${symbol} giữ protection tín hiệu nhưng thiếu signalTp; không dùng TP ROE cố định`);
    return;
  } else if (pumpRecord?.tp) {
    rawTpPrice = Number(pumpRecord.tp);
    console.log(`[AutoTP] 📌 ${symbol} dùng signal TP=${rawTpPrice} thay vì ROE cố định`);
  } else if (takeProfitUserOrV2Managed) {
    console.log(`[AutoTP] ${symbol} user/Liquid Flow V2 managed: không tự dựng TP fallback`);
    return;
  } else {
    const defaultTp = Number(process.env.AUTO_TRADE_TP_ROE ?? 20);
    const fallbackTakeProfit = resolveNonLiquidFlowV2TakeProfit({
      side: isLong ? 'LONG' : 'SHORT',
      source: takeProfitSource,
      entryPrice: entry,
      leverage,
      requestedTakeProfitPrice: null,
    });
    const tpRoe = (fallbackTakeProfit.applied
      ? fallbackTakeProfit.roePct
      : isLong
        ? Number(process.env.AUTO_TRADE_LONG_TP_ROE ?? defaultTp)
        : Number(process.env.AUTO_TRADE_SHORT_TP_ROE ?? defaultTp)) / 100;
    if (!Number.isFinite(tpRoe) || tpRoe <= 0) return;
    rawTpPrice = isLong
      ? entry * (1 + tpRoe / leverage)
      : entry * (1 - tpRoe / leverage);
  }
  const fixedTakeProfit = resolveNonLiquidFlowV2TakeProfit({
    side: isLong ? 'LONG' : 'SHORT',
    source: takeProfitSource,
    entryPrice: entry,
    leverage,
    requestedTakeProfitPrice: rawTpPrice,
  });
  if (fixedTakeProfit.applied) rawTpPrice = fixedTakeProfit.takeProfitPrice;
  if (!isFinite(rawTpPrice) || rawTpPrice <= 0) return;
  const triggerPrice = priceFromTick(symbolInfo, rawTpPrice);
  if (!triggerPrice || triggerPrice === 'NaN' || Number(triggerPrice) <= 0) return;

  const lotSize = symbolInfo.filters?.find((f) => f.filterType === 'LOT_SIZE');
  const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
  const steppedQty = Math.floor(Math.abs(amt) / stepSize) * stepSize;
  const quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');
  if (Number(quantity) <= 0) return;

  const expectedPrice = Number(triggerPrice);
  const expectedQty = Number(quantity);
  const priceTol = Math.max(0.001, Number(process.env.AUTO_TP_REFRESH_PRICE_TOL_PCT ?? 0.15) / 100);
  const qtyTol = Math.max(0.000001, Number(process.env.AUTO_TP_REFRESH_QTY_TOL_PCT ?? 0.5) / 100);
  const isTpType = (t) => {
    const u = String(t ?? '').toUpperCase();
    return u === 'TAKE_PROFIT_MARKET' || u === 'TAKE_PROFIT';
  };
  const orderPrice = (o) => Number(o.triggerPrice ?? o.stopPrice ?? o.price);
  const orderQty = (o) => Number(o.origQty ?? o.quantity ?? o.executedQty ?? 0);
  const orderWorkingType = (o) => String(o.workingType ?? 'MARK_PRICE').toUpperCase();
  const priceMatches = (p) => Number.isFinite(p) && Math.abs(p - expectedPrice) / expectedPrice <= priceTol;
  const qtyCovers = (q) => !Number.isFinite(q) || q <= 0 || q >= expectedQty * (1 - qtyTol);
  const workingTypeMatches = (o) => orderWorkingType(o) === expectedWorkingType;

  const existingAlgoTp = algoRows.find((o) =>
    o.symbol === symbol &&
    String(o.side ?? '').toUpperCase() === closeSide &&
    isTpType(o.orderType ?? o.type) &&
    priceMatches(orderPrice(o)) &&
    qtyCovers(orderQty(o)) &&
    workingTypeMatches(o),
  );
  const existingRegularTp = openOrders.find((o) =>
    o.symbol === symbol &&
    o.side === closeSide &&
    isTpType(o.origType ?? o.type) &&
    priceMatches(orderPrice(o)) &&
    qtyCovers(orderQty(o)) &&
    workingTypeMatches(o),
  );
  if (existingAlgoTp || existingRegularTp) {
    tpConfirmedSet.add(tpKey);
    return;
  }

  // Idempotent protection policy: an existing close-side TP is authoritative.
  // Do not cancel/replace it merely because a concurrent callback computed a
  // different target or quantity.
  if (hasOpenProtectionOrder(openOrders, algoRows, {
    symbol,
    closeSide,
    positionSide: pos.positionSide ?? 'BOTH',
    kind: 'TP',
  })) {
    tpConfirmedSet.add(tpKey);
    console.log(`[AutoTP] ${symbol} skipped: existing TP retained`);
    return;
  }

  const staleRegularTp = openOrders.filter((o) =>
    o.symbol === symbol &&
    o.side === closeSide &&
    isTpType(o.origType ?? o.type) &&
    (!priceMatches(orderPrice(o)) || !qtyCovers(orderQty(o)) || !workingTypeMatches(o)),
  );
  const staleAlgoTp = algoRows.filter((o) =>
    o.symbol === symbol &&
    String(o.side ?? '').toUpperCase() === closeSide &&
    isTpType(o.orderType ?? o.type) &&
    (!priceMatches(orderPrice(o)) || !qtyCovers(orderQty(o)) || !workingTypeMatches(o)),
  );
  for (const o of staleRegularTp) {
    if (!o.orderId) continue;
    await client.cancelOrder({ symbol, orderId: o.orderId, apiKey, apiSecret, recvWindow }).catch((e) =>
      console.warn(`[AutoTP] ${symbol} cancel stale TP order ${o.orderId}: ${e.message}`),
    );
    await new Promise((r) => setTimeout(r, 80));
  }
  for (const o of staleAlgoTp) {
    if (!o.algoId) continue;
    await client.cancelAlgoOrder({ algoId: o.algoId, apiKey, apiSecret, recvWindow }).catch((e) =>
      console.warn(`[AutoTP] ${symbol} cancel stale TP algo ${o.algoId}: ${e.message}`),
    );
    await new Promise((r) => setTimeout(r, 80));
  }
  if (staleRegularTp.length || staleAlgoTp.length) {
    invalidateOpenOrdersCache();
    console.log(`[AutoTP] ${symbol} stale TP refresh: regular=${staleRegularTp.length}, algo=${staleAlgoTp.length}, newQty=${quantity}, newTP=${triggerPrice}`);
  }

  const positionSide = pos.positionSide ?? 'BOTH';
  const isHedge = positionSide !== 'BOTH';
  const tpParams = {
    algoType: 'CONDITIONAL',
    symbol,
    side: closeSide,
    type: 'TAKE_PROFIT_MARKET',
    triggerPrice: String(triggerPrice),
    quantity,
    workingType: expectedWorkingType,
    recvWindow,
    newClientOrderId: `tp_scan_${Date.now()}`.slice(0, 36),
  };
  if (isHedge) tpParams.positionSide = positionSide;
  else tpParams.reduceOnly = 'true';

  try {
    const [freshRegular, freshAlgoResult] = await Promise.all([
      client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
      client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }),
    ]);
    const freshAlgo = Array.isArray(freshAlgoResult?.orders)
      ? freshAlgoResult.orders
      : Array.isArray(freshAlgoResult) ? freshAlgoResult : [];
    if (hasOpenProtectionOrder(freshRegular, freshAlgo, {
      symbol,
      closeSide,
      positionSide,
      kind: 'TP',
    })) {
      tpConfirmedSet.add(tpKey);
      console.log(`[AutoTP] ${symbol} skipped: existing TP found on fresh check`);
      return;
    }
    const result = await client.placeAlgoOrder({ params: tpParams, apiKey, apiSecret });
    tpConfirmedSet.add(tpKey);
    console.log(`[AutoTP] ✅ ${symbol} ${isLong ? 'LONG' : 'SHORT'} entry=${entry} lev=${leverage}x → TP @ ${triggerPrice} qty=${quantity} workingType=${expectedWorkingType} algoId=${result.algoId}`);
  } catch (err) {
    const isMaxStop = err.message?.toLowerCase().includes('max stop') || err.message?.toLowerCase().includes('too many stop');
    if (!isMaxStop) { console.error(`[AutoTP] ❌ ${symbol}:`, err.message); return; }

    // Xóa hết lệnh stop cũ cho symbol này rồi đặt lại TP + SL
    console.warn(`[AutoTP] ⚠ ${symbol} max stop orders — xóa hết và đặt lại...`);
    await clearSymbolOrders(symbol, apiKey, apiSecret, recvWindow);

    // Retry TP
    try {
      tpParams.newClientOrderId = `tp_retry_${Date.now()}`.slice(0, 36);
      const result = await client.placeAlgoOrder({ params: tpParams, apiKey, apiSecret });
      tpConfirmedSet.add(tpKey);
      console.log(`[AutoTP] ✅ ${symbol} (retry) → TP @ ${triggerPrice} algoId=${result.algoId}`);
    } catch (retryErr) {
      console.error(`[AutoTP] ❌ ${symbol} retry TP:`, retryErr.message);
      return;
    }

    // Đặt lại SL
    const slRoeEnv = isLong ? process.env.AUTO_TRADE_LONG_SL_ROE : process.env.AUTO_TRADE_SHORT_SL_ROE;
    const slRoePct = slRoeEnv ? Math.abs(Number(slRoeEnv)) : Number(process.env.AUTO_SL_ROE ?? 25);
    const rawSl = preserveSignalProtection && Number.isFinite(trackedSignalSl) && trackedSignalSl > 0
      ? trackedSignalSl
      : slRoePct > 0
        ? (isLong
          ? entry * (1 - slRoePct / 100 / leverage)
          : entry * (1 + slRoePct / 100 / leverage))
        : null;
    if (rawSl && Number.isFinite(rawSl) && rawSl > 0) {
      const slPrice = priceFromTick(symbolInfo, rawSl);
      if (slPrice && Number(slPrice) > 0) {
        const slParams = {
          symbol, side: closeSide,
          type: 'STOP_MARKET', stopPrice: String(slPrice), quantity,
          workingType: 'MARK_PRICE', reduceOnly: 'true', recvWindow,
          newClientOrderId: `sl_retry_${Date.now()}`.slice(0, 36),
        };
        if (isHedge) { delete slParams.reduceOnly; slParams.positionSide = positionSide; }
        try {
          await client.placeFuturesOrder({ params: slParams, apiKey, apiSecret })
            .catch((e) => {
              if (e.message?.includes('not supported') || e.message?.includes('Algo Order')) {
                const ap = { ...slParams, algoType: 'CONDITIONAL', triggerPrice: String(slPrice) };
                delete ap.stopPrice;
                return client.placeAlgoOrder({ params: ap, apiKey, apiSecret });
              }
              throw e;
            });
          console.log(`[AutoTP] 🛡 ${symbol} SL @${slPrice} (${preserveSignalProtection ? 'signal' : `${slRoePct}% ROE`})`);
        } catch (slErr) {
          console.warn(`[AutoTP] ⚠ ${symbol} SL retry failed:`, slErr.message);
        }
      }
    }
  }
}

// Xóa toàn bộ open orders (regular + algo) cho một symbol
async function clearSymbolOrders(symbol, apiKey, apiSecret, recvWindow = 5000) {
  // Chỉ cancel reduce-only orders (SL/TP), không cancel LIMIT entry
  try {
    const openOrders = await client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }).catch(() => []);
    const stopTypes = new Set(['STOP_MARKET', 'TAKE_PROFIT_MARKET', 'STOP', 'TAKE_PROFIT']);
    const toCancel = openOrders.filter((o) =>
      o.reduceOnly || stopTypes.has(String(o.origType ?? o.type ?? '').toUpperCase()),
    );
    for (const o of toCancel) {
      await client.cancelOrder({ symbol, orderId: o.orderId, apiKey, apiSecret, recvWindow }).catch(() => {});
      await new Promise((r) => setTimeout(r, 100));
    }
    if (toCancel.length) console.log(`[AutoTP] 🗑 ${symbol} đã hủy ${toCancel.length} reduce-only order(s)`);
  } catch (e) {
    console.warn(`[AutoTP] clearSymbolOrders ${symbol}:`, e.message);
  }
  // Algo orders đều là TP/SL — cancel hết
  try {
    const algoResult = await client.getOpenAlgoOrders({ symbol, apiKey, apiSecret, recvWindow }).catch(() => ({ orders: [] }));
    const algoRows = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
    for (const o of algoRows) {
      if (!o.algoId) continue;
      await client.cancelAlgoOrder({ algoId: o.algoId, apiKey, apiSecret, recvWindow }).catch(() => {});
      await new Promise((r) => setTimeout(r, 100));
    }
    if (algoRows.length) console.log(`[AutoTP] 🗑 ${symbol} đã hủy ${algoRows.length} algo order(s)`);
  } catch (e) {
    console.warn(`[AutoTP] clearAlgoOrders ${symbol}:`, e.message);
  }
  invalidateOpenOrdersCache();
}

async function handleNegativeTimeoutTp(symbol, pos, {
  triggerVersion = BINANCE_NEGATIVE_TP_TO_ENTRY_VERSION,
  triggerAgeMs = null,
  triggerRoe = null,
} = {}) {
  // Orders "Cap TSL" is an explicit opt-out from every negative TP-to-entry
  // path (socket, REST scanner, deep guard and eight-hour age fallback).
  if (isCapTslSymbol(symbol)) {
    negativeSince.delete(symbol);
    return;
  }
  const entry = pos.entry;
  // Dedup: already set TP to entry for this position
  const prevEntry = tpMovedToEntry.get(symbol);
  if (prevEntry !== undefined && Math.abs(prevEntry - entry) / entry < 0.005) return;

  // Cooldown: don't spam API if check was recent
  const lastRun = negTpLastRun.get(symbol) ?? 0;
  if (Date.now() - lastRun < NEG_TP_COOLDOWN_MS) return;
  negTpLastRun.set(symbol, Date.now());

  console.log(`[NegTp] ${symbol} checking — entry=${entry} amt=${pos.amt} trigger=${triggerVersion}`);

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

    const [openOrders, algoResult, symbols] = await Promise.all([
      client.getOpenOrders({ symbol, apiKey, apiSecret, recvWindow }),
      client.getOpenAlgoOrders({ symbol, apiKey, apiSecret }).catch(() => ({ orders: [] })),
      getSymbols(),
    ]);

    const symbolInfo = symbols.find((s) => s.symbol === symbol);
    if (!symbolInfo) { console.warn(`[NegTp] ${symbol} not found in symbols`); return; }

    const isLong = pos.amt > 0;
    if (!isFinite(entry) || entry <= 0) { console.warn(`[NegTp] ${symbol} invalid entry ${entry}`); return; }
    const newTpPrice = priceFromTick(symbolInfo, entry);
    if (!newTpPrice || newTpPrice === 'NaN' || Number(newTpPrice) <= 0) { console.warn(`[NegTp] ${symbol} priceFromTick returned invalid: ${newTpPrice}`); return; }

    const entryTol = 0.005;
    const isNearEntry = (price) => {
      const p = Number(price);
      return Number.isFinite(p) && Math.abs(p - Number(newTpPrice)) / Number(newTpPrice) <= entryTol;
    };

    // Check if a close order already exists near entry. A normal TP far above/below
    // entry is not enough here because this guard intentionally moves TP to breakeven.
    const allOpen = Array.isArray(openOrders) ? openOrders : [];
    const existingClose = allOpen.find((o) => {
      const t = String(o.origType ?? o.type ?? '').toUpperCase();
      const sideOk = isLong ? o.side === 'SELL' : o.side === 'BUY';
      if (!sideOk) return false;
      if (t === 'TAKE_PROFIT_MARKET' || t === 'TAKE_PROFIT') {
        return isNearEntry(o.stopPrice ?? o.triggerPrice);
      }
      if (t === 'LIMIT') {
        return isNearEntry(o.price);
      }
      return false;
    });
    if (existingClose) {
      tpMovedToEntry.set(symbol, entry);
      console.log(`[NegTp] ${symbol} đã có lệnh close ở entry, skip`);
      return;
    }

    // Check algo orders
    const allAlgo = Array.isArray(algoResult?.orders) ? algoResult.orders : Array.isArray(algoResult) ? algoResult : [];
    const existingAlgo = allAlgo.find((o) => {
      if (o.symbol !== symbol) return false;
      const t = String(o.orderType ?? o.type ?? '').toUpperCase();
      if (t !== 'TAKE_PROFIT_MARKET' && t !== 'TAKE_PROFIT') return false;
      return isNearEntry(o.triggerPrice ?? o.stopPrice);
    });
    if (existingAlgo) {
      tpMovedToEntry.set(symbol, entry);
      console.log(`[NegTp] ${symbol} already has algo close near entry, skip`);
      return;
    }

    const closeSide = isLong ? 'SELL' : 'BUY';
    const staleTpOpen = allOpen.filter((o) => {
      const t = String(o.origType ?? o.type ?? '').toUpperCase();
      if (o.side !== closeSide) return false;
      if (t !== 'LIMIT' && t !== 'TAKE_PROFIT' && t !== 'TAKE_PROFIT_MARKET') return false;
      const p = t === 'LIMIT' ? o.price : (o.stopPrice ?? o.triggerPrice);
      return !isNearEntry(p);
    });
    for (const o of staleTpOpen) {
      if (!o.orderId) continue;
      await client.cancelOrder({ symbol, orderId: o.orderId, apiKey, apiSecret, recvWindow }).catch((e) =>
        console.warn(`[NegTp] ${symbol} cancel stale TP order ${o.orderId}: ${e.message}`),
      );
      await new Promise((r) => setTimeout(r, 80));
    }

    const staleTpAlgo = allAlgo.filter((o) => {
      if (o.symbol !== symbol) return false;
      const t = String(o.orderType ?? o.type ?? '').toUpperCase();
      if (t !== 'TAKE_PROFIT' && t !== 'TAKE_PROFIT_MARKET') return false;
      if (String(o.side ?? '').toUpperCase() !== closeSide) return false;
      return !isNearEntry(o.triggerPrice ?? o.stopPrice);
    });
    for (const o of staleTpAlgo) {
      if (!o.algoId) continue;
      await client.cancelAlgoOrder({ algoId: o.algoId, apiKey, apiSecret, recvWindow }).catch((e) =>
        console.warn(`[NegTp] ${symbol} cancel stale TP algo ${o.algoId}: ${e.message}`),
      );
      await new Promise((r) => setTimeout(r, 80));
    }
    if (staleTpOpen.length || staleTpAlgo.length) {
      invalidateOpenOrdersCache();
      console.log(`[NegTp] ${symbol} canceled stale TP(s): regular=${staleTpOpen.length}, algo=${staleTpAlgo.length}`);
    }

    const lotSize = symbolInfo.filters?.find((f) => f.filterType === 'LOT_SIZE');
    const stepSize = Number(lotSize?.stepSize ?? 10 ** -Number(symbolInfo.quantityPrecision ?? 3));
    const steppedQty = Math.floor(Math.abs(pos.amt) / stepSize) * stepSize;
    if (steppedQty <= 0) { console.warn(`[NegTp] ${symbol} qty rounds to 0, skip`); return; }
    const quantity = steppedQty.toFixed(decimalsFromStep(stepSize)).replace(/\.?0+$/, '');

    const positionSide = pos.positionSide ?? 'BOTH';
    const isHedge = positionSide !== 'BOTH';

    // LIMIT order at entry — works on all symbols without algo permission
    const tpParams = {
      symbol,
      side: isLong ? 'SELL' : 'BUY',
      type: 'LIMIT',
      price: String(newTpPrice),
      quantity,
      timeInForce: 'GTC',
      recvWindow,
    };
    if (isHedge) { tpParams.positionSide = positionSide; } else { tpParams.reduceOnly = 'true'; }

    await client.placeFuturesOrder({ params: tpParams, apiKey, apiSecret });
    tpMovedToEntry.set(symbol, entry);

    const durationMs = triggerAgeMs != null && Number.isFinite(Number(triggerAgeMs))
      ? Number(triggerAgeMs)
      : Date.now() - (negativeSince.get(symbol) ?? Date.now());
    const hours = (durationMs / 3_600_000).toFixed(1);
    const roeText = triggerRoe != null && Number.isFinite(Number(triggerRoe))
      ? ` ROE=${Number(triggerRoe).toFixed(2)}%`
      : '';
    console.log(`[NegTp] ✅ ${symbol}${roeText} age=${hours}h → LIMIT close đặt tại entry ${newTpPrice} (${triggerVersion})`);
  } catch (err) {
    console.error(`[NegTp] ❌ ${symbol}:`, err.message);
  }
}

const negTpLastRun = new Map(); // symbol → timestamp of last API call
const NEG_TP_COOLDOWN_MS = 120_000; // 2 min minimum between API calls per symbol

const avgDownFired = new Map(); // symbol → entryPrice when avg-down was placed

async function handleAvgDown(symbol, pos, roe) {
  if (liveCardOnlyAutoBinanceEnabled()) return;
  if (process.env.AVG_DOWN_ENABLED !== 'true') return;

  const entry = pos.entry;
  // Dedup: already placed for this entry (within 0.5% = same position, not re-opened)
  const prevEntry = avgDownFired.get(symbol);
  if (prevEntry !== undefined && Math.abs(prevEntry - entry) / entry < 0.005) return;

  try {
    const { apiKey, apiSecret } = getApiCredentials(null);
    const marginUsdt = Number(process.env.AVG_DOWN_MARGIN_USDT ?? 2);
    const leverage = pos.leverage || Number(process.env.AUTO_TRADE_LEVERAGE ?? 10);
    const notionalUsdt = marginUsdt * leverage;
    const side = pos.amt > 0 ? 'BUY' : 'SELL';

    avgDownFired.set(symbol, entry); // mark before placing to prevent re-entry on concurrent ticks

    if (runtimeSettings.dryRun) {
      console.log(`[AvgDown] [DRY] ${symbol} ROE=${roe.toFixed(1)}% → would avg-down $${marginUsdt} ${side}`);
      return;
    }

    await placeOrder({ symbol, side, notionalUsdt, leverage, dryRun: false, source: 'avg-down' });
    console.log(`[AvgDown] ✅ ${symbol} ROE=${roe.toFixed(1)}% → avg-down $${marginUsdt} ${side}`);
  } catch (err) {
    const msg = err.message ?? '';
    // Non-retriable: margin insufficient or notional too small → keep fired so we don't spam
    if (msg.includes('Margin is insufficient') || msg.includes('notional')) {
      console.warn(`[AvgDown] ⚠ ${symbol}: ${msg} — skip retry`);
    } else {
      avgDownFired.delete(symbol); // allow retry on transient failures
      console.error(`[AvgDown] ❌ ${symbol}:`, msg);
    }
  }
}

async function closePosition(payload, token = null) {
  const symbol = normalizeSymbol(payload.symbol ?? '');
  const positionAmt = Number(payload.positionAmt);
  if (!symbol || !positionAmt) throw new Error('symbol and positionAmt are required.');
  const side = positionAmt > 0 ? 'SELL' : 'BUY';
  const quantity = Math.abs(positionAmt);
  const { apiKey, apiSecret } = getApiCredentials(token);
  const recvWindow = Number(process.env.BINANCE_DEFAULT_RECV_WINDOW ?? 5000);

  const [symbols, premiumIndex] = await Promise.all([
    getSymbols(),
    client.getPremiumIndex(symbol),
  ]);
  const symbolInfo = symbols.find((s) => s.symbol === symbol);
  if (!symbolInfo) throw new Error(`Symbol ${symbol} not found.`);

  const markPrice = Number(premiumIndex.markPrice);
  const steppedQty = quantityFromNotional(symbolInfo, quantity * markPrice, markPrice);

  const isHedge = await getHedgeMode(token);
  const closeParams = {
    symbol,
    side,
    type: 'MARKET',
    quantity: steppedQty,
    recvWindow,
    newClientOrderId: `lp_close_${Date.now()}`,
  };
  if (isHedge) {
    closeParams.positionSide = positionAmt > 0 ? 'LONG' : 'SHORT';
  } else {
    closeParams.reduceOnly = 'true';
  }

  const result = await client.placeFuturesOrder({ params: closeParams, apiKey, apiSecret });
  // Cleanup is owned by the confirmed position-close path. Do not race the
  // reduce-only MARKET acknowledgement against Binance Position Risk.
  return result;
}

async function sendStatic(pathname, response) {
  const staticPath = pathname === '/'
    ? '/index.html'
    : pathname === '/signals'
      ? '/signals.html'
      : pathname === '/pump'
        ? '/pump.html'
        : pathname === '/cap'
          ? '/cap.html'
        : pathname === '/killshort'
          ? '/killshort.html'
        : pathname === '/spike-reversal'
          ? '/spike-reversal.html'
        : pathname === '/post-pump-kill-short'
          ? '/post-pump-kill-short.html'
        : pathname === '/dump-ignition'
          ? '/dump-ignition.html'
        : pathname === '/etf-proxy'
          ? '/etf-proxy.html'
        : pathname === '/market-news'
          ? '/market-news.html'
        : pathname === '/coin-flow'
          ? '/coin-flow.html'
        : pathname === '/token-unlocks'
          ? '/token-unlocks.html'
        : pathname === '/pump-ignition'
          ? '/pump-ignition.html'
        : pathname === '/ema-squeeze'
          ? '/ema-squeeze.html'
        : pathname === '/recommended-signals'
          ? '/recommended-signals.html'
        : pathname === '/intraday-combos'
          ? '/intraday-combos.html'
        : pathname === '/decision-paper'
          ? '/decision-paper.html'
        : pathname === '/br-like-limit'
          ? '/br-like-limit.html'
        : pathname === '/ema99-kill-reclaim'
          ? '/ema99-kill-reclaim.html'
        : pathname === '/shakeout-reclaim'
          ? '/shakeout-reclaim.html'
        : pathname === '/top-reversal'
          ? '/top-reversal.html'
        : pathname === '/edge-short'
          ? '/edge-short.html'
        : pathname === '/orders'
          ? '/orders.html'
          : pathname === '/highvol'
            ? '/highvol.html'
            : pathname === '/lsratio'
              ? '/lsratio.html'
              : pathname === '/paper'
                ? '/paper.html'
                : pathname === '/liquid-scan'
                  ? '/liquid-scan.html'
                : pathname === '/liquid-flow-v2'
                  ? '/liquid-flow-v2.html'
                : pathname === '/liquid-flow-v2-binance-stats'
                  ? '/liquid-flow-v2-binance-stats.html'
                : pathname === '/coinglass-web-top20'
                  ? '/coinglass-web-top20.html'
              : pathname;
  const safePath = normalize(staticPath).replace(/^(\.\.[/\\])+/, '');
  const filePath = join(publicDir, safePath);

  if (!filePath.startsWith(publicDir)) {
    await sendJson(response, { error: 'Not found' }, 404);
    return;
  }

  try {
    const fileStat = await stat(filePath);

    if (!fileStat.isFile()) {
      await sendJson(response, { error: 'Not found' }, 404);
      return;
    }

    response.writeHead(200, {
      'content-type': contentTypeFor(filePath),
      'cache-control': 'no-store',
    });

    if (extname(filePath) === '.html') {
      let html = await readFile(filePath, 'utf8');
      const paperCandlePages = new Set([
        '/pump.html', '/post-pump-kill-short.html', '/cap.html', '/edge-short.html',
        '/liquid-scan.html', '/dump-ignition.html', '/ema-squeeze.html', '/spike-reversal.html',
        '/decision-paper.html', '/shakeout-reclaim.html', '/top-reversal.html', '/pump-ignition.html',
        '/br-like-limit.html', '/paper.html', '/recommended-signals.html',
      ]);
      if (paperCandlePages.has(staticPath) && !html.includes('/paper-candle-columns.js')) {
        html = html.includes('</head>')
          ? html.replace('</head>', '  <script src="/paper-candle-columns.js?v=20260722-ema-candle-sort-filter2"></script>\n</head>')
          : html;
      }
      if (paperPageLearningEnabled && paperCandlePages.has(staticPath) && !html.includes('/paper-learning-columns.js')) {
        html = html.includes('</head>')
          ? html.replace('</head>', '  <script src="/paper-learning-columns.js"></script>\n</head>')
          : html;
      }
      const hasDedicatedLoader = staticPath === '/recommended-signals.html';
      if (!hasDedicatedLoader && !html.includes('/global-loading.js')) {
        const loaderScript = '<script src="/global-loading.js"></script>';
        html = html.includes('</head>')
          ? html.replace('</head>', `  ${loaderScript}\n</head>`)
          : html.replace('</body>', `  ${loaderScript}\n</body>`);
      }
      response.end(html);
      return;
    }

    createReadStream(filePath).pipe(response);
  } catch {
    await sendJson(response, { error: 'Not found' }, 404);
  }
}

async function sendJson(response, payload, status = 200) {
  response.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
  });
  response.end(JSON.stringify(payload));
}

function contentTypeFor(filePath) {
  const types = {
    '.html': 'text/html; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.js': 'application/javascript; charset=utf-8',
    '.png': 'image/png',
  };

  return types[extname(filePath)] ?? 'application/octet-stream';
}
